  const topbarHeight = topbar && getComputedStyle(topbar).display !== 'none' ? topbar.getBoundingClientRect().height : 0;
  document.documentElement.style.setProperty('--runtime-topbar-height', `${Math.ceil(topbarHeight)}px`);
