// The available Sanrin creature is delivered inside the /api/field payload
// (currentField.state.creature_encounter.creature_summary). The summary is added
// by the field route alone; /api/state (currentRuntimeState) returns the raw
// persisted encounter without it, so the candidate must read the enriched field
// payload — reading currentRuntimeState here would always miss the summary and the
// creature would never appear. display_name / kind_label come from the authored
// profile via the backend; the client never invents them.
function availableCreatureEncounterSummary() {
  const encounter = currentField?.state?.creature_encounter;
  if (!encounter || encounter.status !== 'available') return null;
  const summary = encounter.creature_summary;
  if (!summary?.creature_id || !summary.visual_set_id) return null;
  return { ...summary, location_id: encounter.location_id };
}

function creatureCandidateFromSummary(summary) {
  const visualSetId = summary.visual_set_id;
  const faceUrl = String(summary.face_url ?? '').trim();
  const standeeUrl = String(summary.standee_url ?? '').trim();
  if (!faceUrl) throw new Error(`missing creature summary face_url: ${summary.creature_id ?? '(unknown creature)'}`);
  if (!standeeUrl) throw new Error(`missing creature summary standee_url: ${summary.creature_id ?? '(unknown creature)'}`);
  const parameterAttitudeType = String(summary.parameter_attitude_type ?? '').trim();
  if (!parameterAttitudeType) throw new Error(`missing creature summary parameter_attitude_type: ${summary.creature_id ?? '(unknown creature)'}`);
  if (!summary.parameters || typeof summary.parameters !== 'object') throw new Error(`missing creature summary parameters: ${summary.creature_id ?? '(unknown creature)'}`);
  return {
    character_id: summary.creature_id,
    display_name: summary.display_name,
    kind: summary.kind,
    kind_label: summary.kind_label,
    parameter_attitude_type: parameterAttitudeType,
    parameters: summary.parameters,
    visual_set_id: visualSetId,
    face_url: faceUrl,
    selection_icon_url: faceUrl,
    standee_url: standeeUrl,
    is_creature: true
  };
}

function registerCreatureCandidate(summary) {
  if (!summary?.creature_id || !summary.visual_set_id) return null;
  const candidate = creatureCandidateFromSummary(summary);
  creatureCandidatesById[candidate.character_id] = candidate;
  return candidate;
}

function creatureActorById(characterId) {
  if (creatureCandidatesById[characterId]) return creatureCandidatesById[characterId];
  const summary = availableCreatureEncounterSummary();
  if (summary && summary.creature_id === characterId) return registerCreatureCandidate(summary);
  return null;
}

// True only when the id resolves to a known creature actor (registered candidate or the
// live available encounter). Used to tell a creature actor apart from an unknown academy
// id: the academy roster never contains creatures, so this is the one positive signal that
// an out-of-roster active actor is a creature rather than a stale/unknown academy id.
function isCreatureActorId(characterId) {
  return Boolean(characterId) && Boolean(creatureActorById(characterId));
}

function sanrinCreatureCandidatesFor(locationId) {
  const summary = availableCreatureEncounterSummary();
  if (!summary || summary.location_id !== locationId) return [];
  const candidate = registerCreatureCandidate(summary);
  return candidate ? [candidate] : [];
}

// Loads the full creature roster from the backend (`/api/creatures`) and registers
// each as a conversation actor candidate. Backend-driven: display fields come from the
// validated creature summary, and a malformed entry fails fast in
// creatureCandidateFromSummary (no client-side default values).
async function refreshAllCreatures() {
  // Fail closed: clear the cached roster before the load so a failed or malformed
  // /api/creatures response leaves no stale creatures behind for the field box to show.
  allCreatureCandidates = [];
  const result = await getJson('/api/creatures');
  if (!Array.isArray(result.creatures)) throw new Error('GET /api/creatures did not return a creatures array');
  allCreatureCandidates = result.creatures.map((summary) => {
    const candidate = registerCreatureCandidate(summary);
    if (!candidate) throw new Error(`invalid creature summary from /api/creatures: ${summary?.creature_id ?? '(unknown)'}`);
    return candidate;
  });
}

// The routing hub display stage: a meta location, not a field location. Mirrors the backend routing
// scene fields (app/src/routingMetaContext.mjs ROUTING_HUB_LOCATION_NAME / ROUTING_HUB_VISIBLE_SITUATION).
// It has no background art, so its stage card renders with a blank background instead of the previous
// field location (e.g. the greenhouse) that the player stood on before entering the hub.
const ROUTING_HUB_STAGE = Object.freeze({
  id: 'routing-hub',
  display_name: 'ルーティングハブ',
  visible_situation: '新しい一週間の始まりを告げ、プレイヤーと次の行き先を話して決める場所。',
  background_url: ''
});

// True while a routing hub conversation is the active conversation. Requires a concrete conversation
// id string — an undefined/empty id is NOT an active hub, so a turn body never sends `id: undefined`
// (which JSON serialization would silently drop back to the fragile implicit-continuation path).
function isRoutingHubActive() {
  return typeof routingHubConversationId === 'string' && routingHubConversationId !== '';
}

// True while an errand client conversation is the active conversation. Requires a concrete conversation
// id string (same discipline as the hub id) so a turn body never sends `id: undefined`. The backend
// routes an active-errand turn by this id, so it is what keeps the errand turn from fail-fasting.
function isActiveErrandConversation() {
  return typeof activeErrandConversationId === 'string' && activeErrandConversationId !== '';
}

// True while a study circle host conversation is the active conversation. Requires a concrete conversation
// id string (same discipline as the hub / errand id) so a turn body never sends `id: undefined`. The backend
// routes an active study circle turn by this id, so it is what keeps the study circle turn from fail-fasting.
function isActiveStudyCircleConversation() {
  return typeof activeStudyCircleConversationId === 'string' && activeStudyCircleConversationId !== '';
}

// True while the academy-loading interstitial is the active screen. Used by the routing hub turn's failure
// defense line: a decided turn whose 見送り読みポーズ raised the drain loading screen must not strand the player
// there if the dispatch then fails.
function isAcademyLoadingScreenActive() {
  return screens['academy-loading'].classList.contains('active');
}

// True while the routing hub screen is the active screen. Used by the routing hub turn's completion
// focus contract: after controls have been re-enabled, focus is restored to `#routing-hub-input` only
// when the hub conversation is still active AND the routing hub screen remains active. Terminal transitions
// (dispatch, graduation selection, auto-end, settings redirect) leave the hub screen, so the contract is a
// no-op there and does not steal focus from the destination screen (mirrors the lounge's explicit
// runLoungePlayerTurn seam).
function isRoutingHubScreenActive() {
  return screens['routing-hub'].classList.contains('active');
}

// Restore keyboard focus to `#routing-hub-input` when a non-terminal routing hub turn has finished and
// the player is expected to type the next utterance. Gated on 3 conditions (all required, no silent
// fallback): the routing hub screen is active, the routing hub conversation is still active, and the
// input element is present and not disabled. Any terminal transition leaves the hub screen or clears
// the hub conversation id, so this call is a no-op there — mirrors the lounge's runLoungePlayerTurn
// re-enable→focus pattern.
function focusRoutingHubInputIfContinuing() {
  if (!isRoutingHubScreenActive()) return;
  if (!isRoutingHubActive()) return;
  const input = document.querySelector('#routing-hub-input');
  if (!input || input.disabled) return;
  input.focus();
}

// A conversation is the routing hub iff it carries the backend routing_hub marker AND the routing
// persona actor id — the exact identifier the backend uses (task contract). The display name is
// per-variant (never a fixed name), so it is not part of the identity. Anything else is not a routing
// hub, so this never mistakes a normal conversation for one.
function isRoutingHubConversation(conversation) {
  return Boolean(conversation?.routing_hub)
    && conversation.character_id === ROUTING_PERSONA_CHARACTER_ID;
}

// Adopt a routing hub conversation as the active one: pin the routing persona actor and remember the
// conversation id for deterministic turn continuation. Fail-fast if the response is not a routing hub
// conversation, rather than silently entering a broken hub.
function enterRoutingHubConversation(conversation) {
  if (!isRoutingHubConversation(conversation)) {
    throw new Error('routing hub start did not return a routing hub conversation (routing_hub + ルミ actor required)');
  }
  const conversationId = conversation.id;
  // A concrete conversation id is required for deterministic turn continuation; a missing/empty id must
  // fail fast rather than degrade to sending `id: undefined` (which serialization drops, falling back to
  // the fragile implicit-continuation path the task forbids).
  if (typeof conversationId !== 'string' || conversationId === '') {
    throw new Error(`routing hub conversation is missing a conversation id: ${JSON.stringify(conversationId)}`);
  }
  routingHubConversationId = conversationId;
  activeCharacterId = conversation.character_id;
}

// Leave the routing hub: clear the routing conversation id so subsequent normal interactions / loop
// turns are not treated as routing (no stale id, actor, or hub stage).
function clearRoutingHubConversation() {
  routingHubConversationId = null;
  markTerraceGraduation(false);
}

// The terrace carries data-graduation through the graduation-guide week (from the hub start that opens it) and while
// the 案内人's graduation conversation goes on on it, so the night-journey layer (metaJourney.js) does not take its
// 今日はここまで for leaving for the gate.
function markTerraceGraduation(on) {
  screens['routing-hub'].toggleAttribute('data-graduation', on);
}

// A routing turn confirmed an academy person as the graduation partner (routing phase 2 begins off the terrace): the
// backend attached routing_graduation_guide_selection naming someone other than the 案内人. Gated on routing mode so a
// loop turn never matches. The turn handler that consumes it has already navigated to the character's graduation event
// on the daytime screen, so the caller must not auto-end / refresh the closed hub (same discipline as
// isRoutingTurnDispatch). Choosing the 案内人 herself is not a hand-off: the conversation goes on on the terrace.
function isRoutingGraduationHandOff(result) {
  const selection = result?.routing_graduation_guide_selection;
  return currentPlayMode === 'routing' && Boolean(selection) && selection.character_id !== ROUTING_PERSONA_CHARACTER_ID;
}

// The active conversation is a graduation conversation (routing phase 2: an academy person's event on the daytime
// screen, or the 案内人's on the terrace) when the runtime pending-interaction context points at the graduation ending
// event flag. In routing mode this is the one conversation that must end through the shared graduation title route
// (graduation-ending-complete → title), not the routing hub drain-on-exit.
function isRoutingGraduationEndingConversation() {
  return currentRuntimeState?.pending_interaction_context?.event_flag_id === 'event.graduation_ending.ready';
}

// True during the routing graduation-guide week: the runtime state carries the routing_graduation_guide state
// object (C-08 game-systems 正本). The hub end's wrap_up opt-in is gated on the NEGATION of this — the backend
// 409s an explicit wrap_up while the guide is active (the guide week has no graduation-avoidance exit), so only
// a wrap_up-absent hub end reaches the guide continuation contract (finalization_status:'idle' + graduation_guide,
// stay on the hub). The judgment source is the runtime state read directly, with NO ?? currentRuntimeState
// default: this is only reached from the hub end, where a live hub always carries runtime state, so a missing
// runtime state is a contract violation — fail fast rather than silently deciding "not a guide" and sending the
// 409-bound wrap_up.
function isRoutingGraduationGuideActive() {
  if (!currentRuntimeState || typeof currentRuntimeState !== 'object') {
    throw new Error('cannot determine routing graduation guide state: runtime state is missing');
  }
  const guide = currentRuntimeState.routing_graduation_guide;
  return Boolean(guide) && typeof guide === 'object';
}

// Register the routing persona visual summary from a backend routing response. The summary must carry
// the routing actor id, a non-empty per-variant display name (the speaker name), and the full variant
// visual (visual set, face, standee, selection icon); a summary that is missing any of these is a real
// data-integrity error (fail-fast) — never silently blank or borrow another character.
function registerRoutingPersonaVisual(summary) {
  if (!summary
    || summary.character_id !== ROUTING_PERSONA_CHARACTER_ID
    || typeof summary.display_name !== 'string'
    || summary.display_name === '') {
    throw new Error(`routing persona visual summary must carry the routing actor id and a display name: ${JSON.stringify(summary)}`);
  }
  if (!summary.visual_set_id || !summary.face_url || !summary.selection_icon_url || !summary.standee_url) {
    throw new Error(`routing persona visual summary is missing visual fields: ${JSON.stringify(summary)}`);
  }
  routingPersonaVisual = summary;
}

// The routing persona actor reuses the load-bearing `lina` slot but is a
// non-selectable actor with its own variant visual set (routing_lumi_<variant>). Its display object is the registered
// visual summary, so the speaker face / standee / icon render the persona's real art — never the roster head
// (セラ / character_001). A missing registration is a real error (fail-fast), not a blank fallback.
function routingPersonaActor() {
  if (!routingPersonaVisual) {
    throw new Error('routing persona visual summary is not registered; cannot render the routing hub actor');
  }
  return routingPersonaVisual;
}

// True when the active actor is the preserved routing persona (the `lina` slot) inside a live hub.
function activeActorIsRoutingPersona() {
  return isRoutingHubActive() && activeCharacterId === ROUTING_PERSONA_CHARACTER_ID;
}

// Resolve the routing persona visual actor for a character id, but only while it is the active routing
// hub actor, or while the hub without a conversation (routingHubStartFailure) shows the last hub conversation's
// lines, which that persona spoke. This is routing-scoped: an ordinary リナ・クラウゼ conversation on the same `lina`
// slot must NOT inherit the routing persona variant visual, so it resolves only on the hub.
function routingActorById(characterId) {
  if (characterId !== ROUTING_PERSONA_CHARACTER_ID) return null;
  if (!activeActorIsRoutingPersona() && !routingHubStartFailure) return null;
  return routingPersonaActor();
}

// True while the player is inside a ホムンクルス conversation on the daytime screen.
function isActiveAtelierConversation() {
  return typeof activeAtelierConversationId === 'string' && activeAtelierConversationId !== '';
}

// Register the homunculus non-selectable actor visual from the atelier conversation-start response. The summary
// must carry the homunculus id, a non-empty display name, and its visual (visual set + face); a missing field is a
// real data-integrity error (fail-fast) — never silently blank or borrow a roster head. Stored as an actor display
// object (character_id keyed) so the daytime speaker face / name resolve the homunculus' own art.
function registerAtelierActorVisual(summary) {
  if (!summary
    || typeof summary.homunculus_id !== 'string' || summary.homunculus_id === ''
    || typeof summary.display_name !== 'string' || summary.display_name === ''
    || typeof summary.visual_set_id !== 'string' || summary.visual_set_id === ''
    || typeof summary.face_url !== 'string' || summary.face_url === '') {
    throw new Error(`atelier actor visual summary is missing required fields: ${JSON.stringify(summary)}`);
  }
  activeAtelierActor = {
    character_id: summary.homunculus_id,
    display_name: summary.display_name,
    visual_set_id: summary.visual_set_id,
    face_url: summary.face_url
  };
}

// Resolve the homunculus visual actor for a character id, but only while its atelier conversation is active
// (scoped like routingActorById): the homunculus is a per-slot surface actor absent from the selectable roster, so
// a later conversation on a different actor must never inherit a stale homunculus visual.
function atelierActorById(characterId) {
  if (!isActiveAtelierConversation() || !activeAtelierActor) return null;
  if (activeAtelierActor.character_id !== characterId) return null;
  return activeAtelierActor;
}

// True when `characterId` is a live non-selectable active actor that the academy-roster fallback must
// preserve: the routing persona (the `lina` slot) inside a live hub, a confirmed creature actor, or the
// homunculus of a live 錬成室 conversation. These actors are intentionally absent from the selectable
// academy roster, so refreshCharacters()' roster-head fallback (character_001 / セラ) must never hijack
// one of them. This is the single place the roster-preservation decision lives: a new non-selectable
// active-actor kind is added HERE only, so the roster fallback can never again drift out of sync with one
// actor kind (the bug that reset an in-progress homunculus conversation to セラ).
function isNonSelectableActiveActorId(characterId) {
  if (isRoutingHubActive() && characterId === ROUTING_PERSONA_CHARACTER_ID) return true;
  if (isCreatureActorId(characterId)) return true;
  if (atelierActorById(characterId)) return true;
  return false;
}

function activeCharacter() {
  if (activeActorIsRoutingPersona()) return routingPersonaActor();
  const atelierActor = atelierActorById(activeCharacterId);
  if (atelierActor) return atelierActor;
  return selectableCharacters.find((character) => character.character_id === activeCharacterId)
    ?? creatureActorById(activeCharacterId)
    ?? selectableCharacters[0]
    ?? { character_id: activeCharacterId, display_name: '選択中のキャラ' };
}

function characterAuthoringMessage() {
  return characterAuthoringCapability?.message ?? 'デスクトップ版ではキャラクター説明の編集は無効です。ブラウザ実行で編集してください。';
}

function characterAuthoringEnabled() {
  return characterAuthoringCapability?.enabled !== false;
}

// routingArrival marks the render a routing hub dispatch lands on ({ destinationLabel } from the dispatch, null
// otherwise): a failed arrival fetch there has nothing to go on with, so it returns to the hub
// (returnToRoutingHubAfterArrivalFailure) with the failure notice naming the destination instead of staying on the
// screen's status line.
function showScreen(name, { rerollAcademyMap = false, skipDungeonRefresh = false, routingArrival = null } = {}) {
  // Entry fail-fast: the 28 `screens` keys are the closed set of screen ids. An unknown id would silently blank
  // every screen (and desync BGM), so it throws here. A known screen with no BGM track is a different, valid case
  // (silence) handled by syncBgmForUiState.
  if (!Object.hasOwn(screens, name)) throw new Error(`showScreen: unknown screen id ${name}`);
  // Continuous-loader line preservation: when the loading interstitial is ALREADY the active screen and showScreen
  // is called again for it (a back-to-back loader handoff — e.g. achievement drain → hub return, drain → generic
  // destination), the constellation must keep the segments it has already traced rather than restart from zero.
  // Capture the prior active state BEFORE the class toggle below so a true entry (non-loader → loader) is
  // distinguished from an in-place copy/phase update on a loader that is already up.
  const loaderAlreadyActive = document.body.classList.contains('academy-loading-screen-active');
  document.body.classList.toggle('title-screen-active', name === 'title');
  document.body.classList.toggle('slot-load-screen-active', name === 'slot-load');
  document.body.classList.toggle('settings-screen-active', name === 'settings');
  document.body.classList.toggle('academy-loading-screen-active', name === 'academy-loading');
  updateViewportMetrics();
  if (name === 'academy-map' && conversationFinalizationInFlight) {
    showProcessingToast();
    return;
  }
  if (name !== 'academy-loading') academyLoadingStarfield.stop();
  if (name !== 'academy-loading') academyLoadingConstellation.stop();
  if (name !== 'academy-loading') passageEnds();
  if (name !== 'training') resetTrainingResultDisplay();
  if (name === 'academy-map') {
    ensureAcademyMapCharacterAssignments({ force: rerollAcademyMap });
    // 昼版マップ: 開くたびにドロワーを閉じ（召喚-only: 開いたドロワーを持ち越さない）、週グリフを更新し、
    // 「昼へ明ける」着地を重ねる。placement / 遷移機構は変えていない。
    closeAcademyMapInfo();
    closeAcademyMapCompanionPopup();
    renderAcademyMapWeek();
    playAcademyMapDayArrival();
  }
  for (const tab of tabs) tab.classList.toggle('active', tab.dataset.screen === name);
  for (const [screenName, element] of Object.entries(screens)) element.classList.toggle('active', screenName === name);
  // True entry only: a non-loader → loader transition starts (resets to zero) the starfield + constellation. A
  // loader → loader re-show (loaderAlreadyActive) leaves both running so the traced segments are preserved across
  // the continuous handoff; only the loading copy/phase is updated in that case.
  // The conversation passage (会話へ移るあいだ) shows neither the night art nor the constellation, so it never starts them.
  if (name === 'academy-loading' && !loaderAlreadyActive && !passageShowing()) academyLoadingStarfield.start();
  if (name === 'academy-loading' && !loaderAlreadyActive && !passageShowing()) academyLoadingConstellation.start();
  if (name === 'academy-conversation-session') renderAcademyConversationSessionScreen();
  if (name === 'academy-room') renderAcademyRoomScreen();
  if (name === 'routing-hub') routingHubStage.renderScreen();
  hubTerrace.screenShown(name, currentRuntimeState);
  placeVeilScreenShown(name);
  syncWaitSigil();
  if (name !== 'routing-hub') {
    routingHubStage.stopAmbient();
    routingHubStage.closeInfo();
    // The 星の揺り籠 overlay is a hub-only side-road; leaving the hub closes it so it never persists across screens.
    closeRoutingHubStarCradle();
  }
  if (name === 'conversation-day') conversationDayStage.renderScreen();
  if (name !== 'conversation-day') {
    conversationDayStage.stopAmbient();
    conversationDayStage.closeInfo();
  }
  // 札の部屋（依頼の札・研究会の札）に着いた: 待ちの層の下で今週の札を要求し、揃ったら札の部屋が現れる（enterRoomCards）。
  const roomCardsRoom = roomCardsRoomOfScreen(name);
  if (roomCardsRoom) {
    roomCardsVisitArrivals.set(roomCardsRoom.kind, routingArrival);
    enterRoomCards(roomCardsRoom).catch(reportError);
  }
  // The alchemy arrival screen has no operable pre-entry state either: showing it fetches the full 56-recipe
  // book and renders the selectable rows. A failed fetch / malformed payload throws (no silent empty rows): on the
  // hub dispatch's arrival it returns to the hub, otherwise it surfaces on the arrival status line. Unlike the errand /
  // study-circle arrivals the alchemy lab is a stay-and-craft screen, so this same refresh runs after each craft
  // (the 分類 filter is reset only on a fresh arrival, preserved across the in-visit re-fetches).
  if (name === 'academy-alchemy') refreshAlchemyScreen({ resetFilter: true }).catch(routingArrival ? (error) => returnToRoutingHubAfterArrivalFailure(error, routingArrival) : reportAlchemyScreenError);
  // The workshop arrival screen has no operable pre-entry state either: showing it fetches this week's full
  // recipe board and renders the selectable cards. A failed fetch / malformed payload throws (no silent empty
  // cards): on the hub dispatch's arrival it returns to the hub, otherwise it surfaces on the arrival status line.
  // Unlike the other arrivals the workshop is a stay-and-craft screen, so this same refresh runs after each craft (the
  // 種別 filter is reset only on a fresh arrival, preserved across the in-visit re-fetches).
  if (name === 'academy-workshop') refreshWorkshopScreen({ resetFilter: true }).catch(routingArrival ? (error) => returnToRoutingHubAfterArrivalFailure(error, routingArrival) : reportWorkshopScreenError);
  // The library arrival screen has no operable pre-entry state either: showing it rebuilds the scene from its
  // first state (the lamps and dust of the arrival, an empty shelf, a blank 請求票) and fetches the arrival
  // envelope (server-authoritative exit; a failed one on the hub dispatch's arrival returns to the hub). Reading is
  // search-driven from there. Leaving the screen stops the scene's running flows and dust, so nothing resolved
  // afterwards draws onto a later visit.
  if (name === 'academy-library') {
    libraryArrivalFromRouting = routingArrival;
    libraryScreen.enter().catch(reportError);
  }
  if (name !== 'academy-library') libraryScreen.suspend();
  // The 奏楽堂 (concert hall) arrival is a stay screen (like the workshop / library): showing it fetches
  // GET /api/concert-hall (week header, server-authoritative exit, the 楽師's lines, the 収蔵 shelf — no LM) and
  // lands the 棚面 (a failed fetch on the hub dispatch's arrival returns to the hub). Any performance still sounding is stopped on every screen change away from it: the concert
  // hall is a silent BGM screen and its player is the only voice there, so nothing may keep playing under
  // another screen's music.
  if (name === 'academy-concert-hall') refreshConcertHallScreen().catch(routingArrival ? (error) => returnToRoutingHubAfterArrivalFailure(error, routingArrival) : (error) => reportConcertHallScreenError(error, retryConcertHallArrival));
  if (name !== 'academy-concert-hall') concertHallPlayer.stop();
  // The 錬成室 arrival is a stay screen (like the workshop / library): showing it fetches GET /api/atelier and
  // renders the 3 slots / 銘棚 / cost / conversation-spent state from the response. A failed fetch (locked gate /
  // non-routing / malformed) throws (no silent empty slots): on the hub dispatch's arrival it returns to the hub,
  // otherwise it surfaces on the arrival status line. This same refresh runs after synthesis / farewell / a conversation
  // return, so the slots and 銘棚 reflect the latest surface.
  if (name === 'academy-atelier') {
    refreshAtelierScreen().catch(routingArrival ? (error) => returnToRoutingHubAfterArrivalFailure(error, routingArrival) : reportAtelierScreenError);
  }
  // The arena screen has no operable pre-entry state either: showing it fetches GET /api/arena/state and
  // renders the participate-form selection (no tournament yet) or the bracket (with the player's live match
  // attached when one is in progress — reload resume). A failed fetch / malformed payload throws (no silent empty
  // cards): on the hub dispatch's arrival it returns to the hub, otherwise it surfaces on the selection status line.
  if (name === 'academy-arena') refreshArenaScreen().catch(routingArrival ? (error) => returnToRoutingHubAfterArrivalFailure(error, routingArrival) : reportArenaScreenError);
  if (name === 'academy-auction') enterOrResumeAuctionScreen({ routingArrival }).catch(reportAuctionScreenError);
  // The 談話室 (lounge) is a routing-only content destination reached through the hub dispatch (lounge →
  // academy-lounge). Like the auction it drives itself from the frontend across a dedicated per-utterance HTTP
  // surface; showing it enters a fresh weekly group talk under an entry loading cover that releases on the first
  // NPC utterance stream (M-2026-07-06-001). The loungeFlowInFlight guard makes the trailing re-entrant
  // showScreen('academy-lounge') from the loading interstitial a no-op (the reset runs once per genuine entry).
  if (name === 'academy-lounge') enterLoungeScreen({ routingArrival }).catch(reportLoungeScreenError);
  // The 星見の窓 (overlook) is a routing-only content destination reached through the hub dispatch (overlook →
  // academy-overlook). Showing it enters under a loading cover (or, on the trailing re-show after a cover of its
  // own, resumes the entry that is already live); leaving it stops the frame loop and the talk ambient. The field
  // poll follows the entry's state, not the screen, so a focus wait under the loading cover keeps reading it.
  if (name === 'academy-overlook') enterOrResumeOverlookScreen().catch(reportOverlookScreenError);
  if (name !== 'academy-overlook') suspendOverlookScreen();
  if (name === 'gathering') refreshGathering().catch(reportError);
  // Normally opening the dungeon screen re-fetches its state to render the entry/active view. The
  // enter flow already holds the fresh board from the enter stream, so it activates the screen with
  // skipDungeonRefresh and renders that buffered board itself — a re-fetch here would redundantly
  // re-render over the still-streaming opening. A failed state fetch on the hub dispatch's arrival returns to the hub.
  if (name === 'academy-dungeon' && !skipDungeonRefresh) refreshDungeonScreen().catch(routingArrival ? (error) => returnToRoutingHubAfterArrivalFailure(error, routingArrival) : reportError);
  // The debug field screen's creature box lists the full roster. Load it only when that
  // screen is opened, so production surfaces (academy map / companion / etc.) never depend
  // on /api/creatures and a catalog failure cannot widen their contract. Rerender in both
  // outcomes so a failed load shows the cleared (empty) roster rather than stale creatures.
  if (name === 'field') refreshAllCreatures().catch(reportError).finally(() => renderFieldCreatureSelector());
  // BGM state sync, once, after the active-class update and past the transition-reject guard (the academy-map
  // finalization guard returns before here) and after the hub-exit cradle close above — so the desired track is
  // computed from the fully-settled screen + overlay state.
  syncBgmForUiState();
}

// Dev-only entry to the daytime conversation screen (the same ?initialScreen= convention as the other dev entries). It gives
// the new screen a verification entry before B2 wires the academy-map landing; the production landing switch
// is NOT added here. Reaching the screen requires runtime state (week/moon) — no save fails fast, mirroring
// the ?calibrate= requirement.
function requestedInitialConversationDay() {
  return new URLSearchParams(window.location.search).get('initialScreen') === 'conversation-day';
}

// Dev-only entry to the errand arrival screen (the same ?initialScreen= convention as title / conversation-day).
// It gives the new arrival screen a手触り verification entry before/besides the routing dispatch landing. Reaching
// it needs an active routing slot (GET /api/errand is routing-only and reads elapsed_weeks) — with no save the
// offer fetch fails fast and surfaces on the arrival status line, mirroring the routing hub's save requirement.
function requestedInitialAcademyErrand() {
  return new URLSearchParams(window.location.search).get('initialScreen') === 'academy-errand';
}

// Dev-only entry to the alchemy arrival screen (the same ?initialScreen= convention as the errand arrival).
// It needs an active routing slot (GET /api/alchemy is routing-only and reads elapsed_weeks) — with no save the
// offer fetch fails fast (409) and surfaces on the arrival status line, the same runtime-state requirement.
function requestedInitialAcademyAlchemy() {
  return new URLSearchParams(window.location.search).get('initialScreen') === 'academy-alchemy';
}

// Dev-only entry to the study circle arrival screen (the same ?initialScreen= convention as the errand / alchemy
// arrivals). It needs an active routing slot (GET /api/study-circle is routing-only and reads elapsed_weeks) — with
// no save the offer fetch fails fast (409) and surfaces on the arrival status line, the same runtime-state requirement.
function requestedInitialAcademyStudyCircle() {
  return new URLSearchParams(window.location.search).get('initialScreen') === 'academy-study-circle';
}

// Dev-only entry to the workshop arrival screen (the same ?initialScreen= convention as the errand / alchemy
// arrivals). It needs an active routing slot (GET /api/workshop is routing-only and reads elapsed_weeks / the
// inventory) — with no save the fetch fails fast (409) and surfaces on the arrival status line, the same
// runtime-state requirement.
function requestedInitialAcademyWorkshop() {
  return new URLSearchParams(window.location.search).get('initialScreen') === 'academy-workshop';
}

// Dev-only entry to the library arrival screen (the same ?initialScreen= convention as the errand / alchemy /
// workshop arrivals). It needs an active routing slot (GET /api/library is routing-only and reads elapsed_weeks) —
// with no save the fetch fails fast (409) and surfaces on the arrival status line, the same runtime-state requirement.
function requestedInitialAcademyLibrary() {
  return new URLSearchParams(window.location.search).get('initialScreen') === 'academy-library';
}

// Dev-only entry to the 錬成室 arrival screen (the same ?initialScreen= convention as the other arrivals).
// showScreen('academy-atelier') fetches GET /api/atelier, which is routing-only and re-checks the unlock gate —
// with no save / a non-routing mode / a locked atelier the fetch fail-fasts and surfaces on the arrival status
// line. The production handle is the routing homunculus dispatch, which lands the same screen.
function requestedInitialAcademyAtelier() {
  return new URLSearchParams(window.location.search).get('initialScreen') === 'academy-atelier';
}

// Dev-only entry to the 闘技会 screen (the same ?initialScreen= convention as the other arrivals).
// showScreen('academy-arena') fetches GET /api/arena/state, which is routing-only and reads the weekly slot —
// with no save / no built tournament the selection view renders (or the fetch fail-fasts on a malformed slot).
// The production handle is the routing arena dispatch, which lands the same screen; this entry is what the
// board-scale render harness uses to reach the bracket / match surface against real layout.
function requestedInitialAcademyArena() {
  return new URLSearchParams(window.location.search).get('initialScreen') === 'academy-arena';
}

// Dev-only entry to the 競売場 screen (same ?initialScreen= convention). showScreen('academy-auction') runs
// enterOrResumeAuctionScreen, which fetches GET /api/auction/state and enters / resumes the weekly slot. With no
// save / a non-routing mode / an unconfigured LM the enter fail-fasts and surfaces on the auction status line.
// The production handle is the routing auction dispatch, which lands the same screen.
function requestedInitialAcademyAuction() {
  return new URLSearchParams(window.location.search).get('initialScreen') === 'academy-auction';
}

// Dev-only entry to the 談話室 screen (same ?initialScreen= convention). showScreen('academy-lounge') runs
// enterLoungeScreen, which posts /api/lounge/enter and streams the opening utterance under the loading cover. With
// no save / a non-routing mode / an unconfigured LM the enter fail-fasts and surfaces on the lounge status line.
// The production handle is the routing lounge dispatch, which lands the same screen.
function requestedInitialAcademyLounge() {
  return new URLSearchParams(window.location.search).get('initialScreen') === 'academy-lounge';
}

// Startup screen contract. An absent initialScreen query is the default startup: the title screen. The server
// already served title-active HTML (flash-free); showScreen('title') runs the title side effects (starfield) and
// keeps the body/tab state in sync. ?initialScreen=debug is the debug tab-bar startup — the static index.html and
// the server's debug response already ship the academy-map-active layout with the topbar, so no screen switch is
// needed. The remaining values are the dev-only screen entries. An unknown non-null value is a hard error, not a
// silent fall-through to a default; it mirrors the server's 400 for the same value (the front-end guard is the
// second layer — the server rejects the request before app.js runs).
function applyInitialScreenOverride() {
  const initialScreen = new URLSearchParams(window.location.search).get('initialScreen');
  if (initialScreen === null) { showScreen('title'); return; }
  if (initialScreen === 'debug') return;
  if (requestedInitialConversationDay()) { showConversationDayDevScreen(); return; }
  if (requestedInitialAcademyErrand()) { showScreen('academy-errand'); return; }
  if (requestedInitialAcademyAlchemy()) { showScreen('academy-alchemy'); return; }
  if (requestedInitialAcademyStudyCircle()) { showScreen('academy-study-circle'); return; }
  if (requestedInitialAcademyWorkshop()) { showScreen('academy-workshop'); return; }
  if (requestedInitialAcademyLibrary()) { showScreen('academy-library'); return; }
  if (requestedInitialAcademyAtelier()) { showScreen('academy-atelier'); return; }
  if (requestedInitialAcademyArena()) { showScreen('academy-arena'); return; }
  if (requestedInitialAcademyAuction()) { showScreen('academy-auction'); return; }
  if (requestedInitialAcademyLounge()) { showScreen('academy-lounge'); return; }
  throw new Error(`unknown initialScreen override: ${initialScreen}`);
}

function clearVisibleConversation() {
  messageHistory = [];
  // Leaving/clearing the visible conversation drops the active errand / study circle conversation id + scene so
  // a stale content-conversation state can never leak into a later normal turn / stage frame. Every conversation
  // entry that clears the surface (the hub, the legacy session, the errand / study circle end/exit) runs through
  // here, so the content state is scoped to its own session; startErrandConversation / startStudyCircleConversation re-set both after this
  // clear. (The routing hub id has its own explicit clear points.)
  activeErrandConversationId = null;
  activeErrandScene = null;
  activeStudyCircleConversationId = null;
  activeStudyCircleScene = null;
  activeAtelierConversationId = null;
  activeAtelierScene = null;
  activeAtelierActor = null;
  setConversationStatus('');
  renderMessageStream([]);
}

function waitForConversationFinalization() {
  return activeConversationFinalizationPromise ?? Promise.resolve();
}

function waitForAcademyMapReadiness() {
  return waitForConversationFinalization();
}

function isEnteringGraduationEndingWeek() {
  return (currentRuntimeState?.elapsed_weeks ?? 0) + 1 >= GRADUATION_ENDING_WEEK
    && currentRuntimeState?.ending_completed !== true;
}

function setAcademyLoadingDestinationCopy(nextScreen, { copyKey = null, loadingCopy = null } = {}) {
  const copyByScreen = {
    'academy-conversation-session': {
      title: '会話セッションへ移動中',
      status: '会話の準備を待っています。'
    },
    'academy-training': {
      title: '次の一週間が始まります',
      status: '会話を終えて、次の一週間の鍛錬予定を整えています。'
    },
    'academy-room': {
      title: '自室へ移動中',
      status: '会話セッションの整理を続けながら自室を開いています。'
    },
    'academy-map': {
      title: '学院マップへ移動中',
      status: '会話セッションの整理と学院マップの準備を待っています。'
    }
  };
  const copyByKey = {
    // 卒業の入りと終わりの箱は題の一行だけ。
    'graduation-ending-start': {
      title: '卒業のときを迎えました',
      status: null
    },
    'graduation-ending-complete': {
      title: '卒業しました。',
      status: null
    }
  };
  const copy = loadingCopy ?? (copyKey ? copyByKey[copyKey] : null) ?? copyByScreen[nextScreen] ?? copyByScreen['academy-map'];
  const title = document.querySelector('#academy-loading-title');
  const status = document.querySelector('#academy-loading-status');
  if (title) title.textContent = copy.title;
  if (status) {
    status.textContent = copy.status ?? '';
    status.hidden = copy.status === null;
  }
  // ハブへ入る字の印。夜の道行きの層（metaJourney.js）はこの字を星の道に写さない。
  screens['academy-loading'].toggleAttribute('data-hub-entry', copy === ROUTING_HUB_ENTRY_LOADING_COPY);
  // 星見の窓へ入る道の印。この道の箱だけは待ちの紋を出さず、星座を描く（style.css）。
  screens['academy-loading'].toggleAttribute('data-overlook-entry', copy === OVERLOOK_ENTRY_LOADING_COPY);
  syncWaitSigil();
}

// Progress notification for the loading constellation. Flows call this at the observed event points the loading
// screen covers (SSE deltas/completes/drains/results, dungeon_enter, the POST / refresh boundaries of the multi-
// await starts). It is meaningful only while the loading interstitial is actually up: a call made when the loader
// is not showing is an intentional no-op (the notification is defined only for the active loader), NOT a silent
// fallback — flows fire it at their event points regardless of whether the loader currently covers them, and the
// non-showing case simply has nothing to advance.
function notifyAcademyLoadingProgress() {
  if (!document.body.classList.contains('academy-loading-screen-active')) return;
  academyLoadingConstellation.notifyProgress();
}

// ── 場所の絵の上の待ち（#place-veil）: 読み込みの箱の代わりに、場所の絵を画面いっぱいに残して待つ ─────────────────────────────
// 画面は切り替えず、いまの画面の上に全画面の層を置く。地は呼び出し側が渡す場所の絵（art）か、null ならいまの画面そのまま。dim で
// 読み込みの夜の絵と同じ暗がりを薄く掛け、星々を瞬かせる。待つあいだは右下で待ちの紋が回る（syncWaitSigil）。待ちの終わりは
// showScreen が決める: 行き先の画面（until）が出たら、ending が 'fade' なら暗がりを解きながら PLACE_VEIL_LEAVE_MS で薄れて行き先が
// 現れ、'cut' ならその場で消える。行き先でない画面が出た
// とき（設定の画面への誘い）もその場で消える。heldForArrival の待ちは、行き先の画面が出ても残り、着いた画面が自分の入りの要求を
// 待ちきったところ（placeVeilArrived）で同じように終わる（談話室・競売場）。失敗で終える待ちは、戻し先を出す前に stopPlaceVeil で夜へ沈める。
// 層は送り出しの幕（#terrace-opened）より上にあり、入り道の待ちは幕の絵を地にする。
// 画面を切り替えないので、待つあいだの曲は読み込みの画面の曲にする（syncBgmForUiState）。
// 待つあいだは下の画面たち（main.layout）を inert にし、見えない言葉の欄へ focus も字も入らないようにする。待ちが終わる（薄れ始める）か
// 層が下りたところで解く。
const placeVeil = document.querySelector('#place-veil');
const placeVeilScreens = document.querySelector('main.layout');
const placeVeilStarfield = createStarfieldAmbient({ canvasSelector: '#place-veil-starfield', starColorRgb: '207, 218, 255', starCount: 64 });
const PLACE_VEIL_ENDINGS = new Set(['fade', 'cut']);
const PLACE_VEIL_LEAVE_MS = 1200;
const PLACE_VEIL_STOP_MS = 1200;
// 待っているあいだだけ { until, ending, heldForArrival }、ほかは null。
let placeVeilWait = null;
let placeVeilLeaveTimer = null;

function placeVeilWaiting() {
  return placeVeilWait !== null;
}

function takeDownPlaceVeil() {
  clearTimeout(placeVeilLeaveTimer);
  placeVeilLeaveTimer = null;
  placeVeilStarfield.stop();
  placeVeil.hidden = true;
  delete placeVeil.dataset.veil;
  placeVeilScreens.inert = false;
  syncWaitSigil();
}

// 層の地の絵の置き方は、相手の画面が宣言したもの（--place-art-size・--place-art-position。窓の座標で書かれ、画面は自分の地の絵も
// この二つで敷く）をそのまま読む。縁をぼかす画面は縁の扱い（--place-art-mask・--place-art-mask-composite。絵の大きさに対する
// mask）も宣言して自分の絵もこれでぼかし、層も同じ縁を絵に掛ける。縁の宣言の無い画面の層はぼかさない。相手の画面は、入る道なら
// 行き先（until）、露台へ戻る道なら層を上げる前に出ていた画面。置き方の宣言の無い画面へ絵つきの層は上げず、縁の宣言が片方だけの
// 画面も throw。
function placeArtPlacement(screenName) {
  if (!Object.hasOwn(screens, screenName)) throw new Error(`place veil: no screen ${JSON.stringify(screenName)} to read the art placement from`);
  const style = getComputedStyle(screens[screenName]);
  const size = style.getPropertyValue('--place-art-size').trim();
  const position = style.getPropertyValue('--place-art-position').trim();
  if (size === '' || position === '') throw new Error(`place veil: the screen ${screenName} declares no art placement (--place-art-size ${JSON.stringify(size)}, --place-art-position ${JSON.stringify(position)})`);
  const mask = style.getPropertyValue('--place-art-mask').trim();
  const maskComposite = style.getPropertyValue('--place-art-mask-composite').trim();
  if ((mask === '') !== (maskComposite === '')) throw new Error(`place veil: the screen ${screenName} declares half an art edge (--place-art-mask ${JSON.stringify(mask)}, --place-art-mask-composite ${JSON.stringify(maskComposite)})`);
  return { size, position, edge: mask === '' ? null : { mask, maskComposite } };
}

function raisePlaceVeil({ art, dim, until, ending, heldForArrival = false }) {
  if (placeVeilWait !== null) throw new Error('place veil: a wait is already under way');
  if (art !== null && (typeof art !== 'string' || art === '')) throw new Error(`place veil: art must be an image url or null (the screen as it is), got ${JSON.stringify(art)}`);
  if (typeof dim !== 'boolean') throw new Error(`place veil: dim must be a boolean, got ${JSON.stringify(dim)}`);
  if (!Object.hasOwn(screens, until)) throw new Error(`place veil: unknown screen ${JSON.stringify(until)} to wait for`);
  if (!PLACE_VEIL_ENDINGS.has(ending)) throw new Error(`place veil: ending must be one of ${[...PLACE_VEIL_ENDINGS].join(', ')}, got ${JSON.stringify(ending)}`);
  if (typeof heldForArrival !== 'boolean') throw new Error(`place veil: heldForArrival must be a boolean, got ${JSON.stringify(heldForArrival)}`);
  const placement = art === null ? null : placeArtPlacement(until === 'routing-hub' ? currentActiveScreenName() : until);
  takeDownPlaceVeil();
  placeVeilWait = { until, ending, heldForArrival };
  placeVeilScreens.inert = true;
  placeVeil.dataset.veilGround = art === null ? 'screen' : 'art';
  // 層を上げたときに出ていた画面（地が画面そのままのとき、待ちの紋の置き場が読む。style.css）。
  placeVeil.dataset.veilOver = currentActiveScreenName();
  placeVeil.dataset.veilDim = dim ? 'night' : 'none';
  placeVeil.style.setProperty('--place-veil-art', art === null ? 'none' : `url('${art}')`);
  if (placement === null) {
    placeVeil.style.removeProperty('--place-veil-art-size');
    placeVeil.style.removeProperty('--place-veil-art-position');
  } else {
    placeVeil.style.setProperty('--place-veil-art-size', placement.size);
    placeVeil.style.setProperty('--place-veil-art-position', placement.position);
  }
  if (placement === null || placement.edge === null) {
    placeVeil.style.removeProperty('--place-veil-art-mask');
    placeVeil.style.removeProperty('--place-veil-art-mask-composite');
  } else {
    placeVeil.style.setProperty('--place-veil-art-mask', placement.edge.mask);
    placeVeil.style.setProperty('--place-veil-art-mask-composite', placement.edge.maskComposite);
  }
  placeVeil.dataset.veil = 'waiting';
  placeVeil.hidden = false;
  if (dim) placeVeilStarfield.start();
  syncWaitSigil();
  syncBgmForUiState();
}

// 失敗で終える: 明るみが消え、場所が夜へ沈む（動きを減らす設定では待たない）。沈みきったら層を下ろす。
async function stopPlaceVeil() {
  if (placeVeilWait === null) throw new Error('place veil: no wait to stop');
  placeVeilWait = null;
  placeVeil.dataset.veil = 'stopped';
  syncWaitSigil();
  if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) await sleep(PLACE_VEIL_STOP_MS);
  takeDownPlaceVeil();
  syncBgmForUiState();
}

// showScreen のたびに呼ぶ（画面が切り替わった後）。heldForArrival の待ちは、行き先の画面が出ただけでは終わらない。
function placeVeilScreenShown(name) {
  if (placeVeilWait === null) return;
  if (placeVeilWait.heldForArrival && name === placeVeilWait.until) return;
  endPlaceVeilWait(name);
}

// heldForArrival の待ちを、着いた画面が入りの要求を待ちきったところで終える。
function placeVeilArrived() {
  if (placeVeilWait === null || !placeVeilWait.heldForArrival) throw new Error('place veil: no wait held for an arrival');
  const name = currentActiveScreenName();
  if (name !== placeVeilWait.until) throw new Error(`place veil: the wait is held for ${placeVeilWait.until}, but ${JSON.stringify(name)} is showing`);
  endPlaceVeilWait(name);
  syncBgmForUiState();
}

// 着いた画面が自分の入りを待つ（談話室・競売場）: 送り出しから続く待ち（行き先の画面が出ても残る層）にそのまま乗る。送り出しを経ない
// 入り（開発用の入口・競売の再開）は、その画面を地にして待ちを上げる。
function placeVeilForArrival(screen) {
  if (placeVeilWait === null) {
    raisePlaceVeil({ art: null, dim: true, until: screen, ending: 'fade', heldForArrival: true });
    return;
  }
  if (placeVeilWait.until !== screen || !placeVeilWait.heldForArrival) {
    throw new Error(`place veil: the arrival at ${screen} found a wait for ${placeVeilWait.until} (heldForArrival ${placeVeilWait.heldForArrival})`);
  }
}

function endPlaceVeilWait(name) {
  const { until, ending } = placeVeilWait;
  placeVeilWait = null;
  placeVeilScreens.inert = false;
  placeVeilStarfield.stop();
  if (name !== until || ending === 'cut' || window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    takeDownPlaceVeil();
    return;
  }
  placeVeil.dataset.veil = 'leaving';
  syncWaitSigil();
  placeVeilLeaveTimer = setTimeout(takeDownPlaceVeil, PLACE_VEIL_LEAVE_MS);
}

// 待ちの紋（#wait-sigil）: 場所の絵の上の待ちのあいだと、読み込みの箱が出ているあいだ（会話へ移るあいだと星見の窓へ入る道の箱を除く）と、
// 画面の中の待ちの印（screenWaitMark）が見えているあいだ、右下で回り続ける。層が晴れる・夜へ沈む（leaving・stopped）あいだは層と
// 一緒に薄れ、層が下りたところで消える。ほかの終わりはその場で消える。待ちの層・読み込みの箱・会話へ移るあいだの出入りのたびに呼び、
// 画面の中の印の出入り（置き換え・札や画面の開け閉め）は下の見張りが呼ぶ。紋の属性は変わるときだけ書く（見張りが自分の書き込みで
// 回り続けないように）。
const waitSigil = document.querySelector('#wait-sigil');

function syncWaitSigil() {
  const boxWaiting = document.body.classList.contains('academy-loading-screen-active')
    && !passageShowing()
    && !screens['academy-loading'].hasAttribute('data-overlook-entry');
  const screenWaiting = [...document.querySelectorAll('.screen-wait-mark')].some((mark) => mark.checkVisibility());
  if (placeVeilWait !== null || boxWaiting || screenWaiting) {
    setWaitSigilState('turning');
    return;
  }
  if (!placeVeil.hidden && (placeVeil.dataset.veil === 'leaving' || placeVeil.dataset.veil === 'stopped')) {
    setWaitSigilState('leaving');
    return;
  }
  setWaitSigilState('hidden');
}

function setWaitSigilState(state) {
  const current = waitSigil.hasAttribute('hidden') ? 'hidden' : waitSigil.dataset.waitSigil === 'leaving' ? 'leaving' : 'turning';
  if (state === current) return;
  if (state === 'hidden') {
    delete waitSigil.dataset.waitSigil;
    waitSigil.setAttribute('hidden', '');
  } else if (state === 'leaving') {
    waitSigil.dataset.waitSigil = 'leaving';
  } else {
    delete waitSigil.dataset.waitSigil;
    waitSigil.removeAttribute('hidden');
  }
}

// 画面の中の待ちの印: 字で待ちを示していた所に、字の代わりに置く見えない印。印が見えているあいだ（印のある画面・札・欄が出ている
// あいだ）右下で待ちの紋が回り、届いたものが印を置き換えるか、印を抱えた札や画面が閉じると紋は消える。name は読み上げの名で、
// 名を持たない印は読み上げない。
function screenWaitMark(name = null) {
  const mark = document.createElement('span');
  mark.className = 'screen-wait-mark';
  if (name === null) {
    mark.setAttribute('aria-hidden', 'true');
  } else {
    mark.setAttribute('role', 'status');
    mark.setAttribute('aria-label', name);
  }
  return mark;
}

new MutationObserver(syncWaitSigil).observe(document.body, { subtree: true, childList: true, attributes: true, attributeFilter: ['hidden', 'class'] });

// 場所の絵の上で要求を待つ。読み込みの箱と同じく最短 ACADEMY_LOADING_MINIMUM_MS は待ち、失敗は reportLoadingError に通す（設定の
// 画面への誘いはそこで層ごと去る）。ほかの失敗は夜へ沈めてから投げ直し、呼び出し側の戻し先へ渡す。
async function awaitUnderPlaceVeil(readiness) {
  try {
    await Promise.all([sleep(ACADEMY_LOADING_MINIMUM_MS), readiness]);
  } catch (error) {
    reportLoadingError(error);
    if (placeVeilWaiting()) await stopPlaceVeil();
    throw error;
  }
}

// A streamed opening/turn emits many assistant_delta events; advancing the constellation on every delta would use
// the whole figure up in a second. This throttle notifies on the FIRST delta (the meaningful "text is now
// arriving" boundary) and then only every LOADING_PROGRESS_DELTA_STRIDE-th delta, so a long streamed wait paces
// the figure instead of exhausting it. Each SSE reader owns one instance (per-stream delta accounting).
const LOADING_PROGRESS_DELTA_STRIDE = 8;
function createLoadingProgressDeltaThrottle() {
  let count = 0;
  return () => {
    count += 1;
    if (count === 1 || count % LOADING_PROGRESS_DELTA_STRIDE === 0) notifyAcademyLoadingProgress();
  };
}

// ── 会話へ移るあいだ（conversationLayer.js の passage*）: 学院の会話・出来事・ホムンクルスへ移る読み込みは、箱・字・夜の絵・星座の
// 代わりに、行き先の場所が夜から満ち、応答が始まると相手の顔が現れる移り変わりになる（依頼・研究会は札の部屋のまま会話になる）。
// ほかの行き先の読み込みは箱のまま。
// The passage replaces the copy box on a loader that is already up (the event start under an arrival loader) as well as
// on one it raises itself, so it stops the starfield / constellation that a box loader may have started.
function beginConversationPassage(stage) {
  academyLoadingStarfield.stop();
  academyLoadingConstellation.stop();
  // The passage holds the stage name where the conversation screen puts it — right after the week — so the week label
  // it lays out (invisibly) must be the one the conversation screen will show.
  conversationDayStage.renderWeekAndMoon();
  passageBegins();
  syncWaitSigil();
  if (stage) passagePlaces(stage);
}

// The destination a conversation passage fills in, known before the conversation is set up. It is the same stage the
// conversation layer reads from academyFieldReading.conversationStage() on landing (the layer throws on a mismatch):
// the atelier has a fixed stage, and the academy-map conversation's stage is the one the player has just moved to. The
// event's stage is only known once /api/event-flags/start has run, so the event start places it from its readiness.
// The errand and the study circle have no passage: their conversation opens in the card room it was chosen in.
function conversationPassageStage(kind) {
  if (kind === 'atelier') return { id: 'atelier', displayName: ATELIER_SCENE_LOCATION_NAME, backgroundUrl: ATELIER_SCENE_STAGE_IMAGE_URL };
  if (kind === 'field') {
    const locationId = academyFieldReading.currentLocationId();
    if (locationId == null) throw new Error('conversation passage: the academy-map conversation has no current stage');
    return academyFieldReading.location(locationId);
  }
  throw new Error(`conversation passage: no stage before the start for conversation kind ${JSON.stringify(kind)}`);
}

// The partner whose face appears once the response has started: the conversation's actor (set by readiness), with the
// neutral face the conversation screen's rows resolve through sourceSheetImageUrl and the name they print.
function conversationPassagePartner() {
  const characterId = activeCharacterId;
  const actor = atelierActorById(characterId)
    ?? selectableCharacters.find((item) => item.character_id === characterId)
    ?? creatureActorById(characterId);
  if (!actor) throw new Error(`conversation passage: the partner ${JSON.stringify(characterId)} is not a known actor`);
  if (typeof actor.display_name !== 'string' || actor.display_name === '') throw new Error(`conversation passage: the partner ${characterId} has no display_name`);
  return { characterId, name: actor.display_name, faceSrc: sourceSheetImageUrl({ expression: 'neutral', view: 'face', characterId }) };
}

// Wait for a conversation's readiness. When it fails under a conversation passage, the passage first shows that it has
// stopped (its light goes out and the place sinks into the night — about 1.2s, none with reduced motion) and the
// failure then takes its usual way back. A settings-redirect failure goes to the settings screen without the pause.
async function awaitConversationReadiness(readiness, { passage }) {
  try {
    await readiness;
  } catch (error) {
    if (passage && settingsRedirectErrorMessage(error) == null) await passageStops();
    throw error;
  }
}

// passage: the conversation passage for the five conversation kinds ({ stage } — the destination stage, or null when it
// is only known once readiness has set the conversation up, in which case readiness places it). The loader then shows
// the destination filling in from the night instead of the copy box, the partner's face appears once readiness
// resolves, and the switch to nextScreen waits until the face has fully appeared.
async function showAcademyLoadingScreenUntilReady({ readiness, nextScreen = null, refreshBeforeNextScreen = true, rerollAcademyMap = false, strictFieldRefresh = false, routingArrival = null, copyKey = null, loadingCopy = null, passage = null }) {
  if (passage) beginConversationPassage(passage.stage);
  else setAcademyLoadingDestinationCopy(nextScreen, { copyKey, loadingCopy });
  showScreen('academy-loading');
  const minimumDisplay = new Promise((resolve) => setTimeout(resolve, ACADEMY_LOADING_MINIMUM_MS));
  try {
    await awaitConversationReadiness(Promise.all([minimumDisplay, readiness]), { passage: passage != null });
    if (passage) await passageArrives(conversationPassagePartner());
    // The pre-arrival refresh runs INSIDE the try: on a strict routing arrival a failed /api/field refresh
    // throws here, is reported through reportLoadingError, and rethrows — so the code never reaches the
    // showScreen(nextScreen) below with a stale currentField. A resilient (non-strict) refresh never throws,
    // so this is a no-op change for loop and every other caller.
    if (nextScreen != null && refreshBeforeNextScreen) {
      await refresh({ strictField: strictFieldRefresh });
      // The pre-arrival field refresh is a real observed boundary for the callers that opt into it (the generic
      // in-turn routing destination and the routing post-content arrival: performRoutingTurnDispatch /
      // navigateToPostContentScreen with refreshBeforeNextScreen). Advance the constellation here so those flows
      // are no longer 0-edge. Callers that pass refreshBeforeNextScreen:false (fixed-minimum / single-JSON flows)
      // never reach this and so are never given fabricated progress.
      notifyAcademyLoadingProgress();
    }
  } catch (error) {
    reportLoadingError(error);
    throw error;
  }
  if (nextScreen == null) return;
  showScreen(nextScreen, { rerollAcademyMap, routingArrival });
}

// The loop graduation ending event conversation (week 50 direct) lands on the daytime screen: routing is the official
// mode, so a newly entered graduation conversation always lands there. The graduation interaction is already set up
// server-side (startNextAcademyWeek called startEventFlagInteraction with the resolved landing screen, so
// started.state carries the truthful current_screen); this only chooses which surface renders it and
// never re-runs the event setup. The legacy session surface (routeGraduationEndingSessionLegacy) survives only
// for the load/resume re-entry of a save whose current_screen was persisted as legacy (reenterGraduationPhase2).
async function routeGraduationEndingSession(started, { loadingAlreadyVisible = false } = {}) {
  await routeGraduationEndingSessionDay(started, { loadingAlreadyVisible });
}

// Legacy (academy-conversation-session) landing for the graduation ending event conversation. It survives only
// for the load/resume phase-2 re-entry of a save whose current_screen was persisted as legacy: reenterGraduationPhase2
// picks this by the SAVED current_screen. A newly entered graduation conversation always lands on the daytime
// screen (routeGraduationEndingSession → routeGraduationEndingSessionDay). Like the daytime landing, the graduation
// interaction is already set up server-side, so this adopts the started state and runs the opening WITHOUT
// re-calling /api/event-flags/start.
async function routeGraduationEndingSessionLegacy(started, { loadingAlreadyVisible = false } = {}) {
  let openingStreamStartedResolve = null;
  let openingStreamStartedResolved = false;
  let openingPromise = Promise.resolve();
  const openingStreamStarted = new Promise((resolve) => {
    openingStreamStartedResolve = resolve;
  });
  const markOpeningStreamStarted = () => {
    if (openingStreamStartedResolved) return;
    openingStreamStartedResolved = true;
    openingStreamStartedResolve?.();
  };
  activeCharacterId = started.character_id ?? activeCharacterId;
  currentRuntimeState = started.state ?? currentRuntimeState;
  clearVisibleConversation();
  writeDebugLog({
    started_event_interaction: started.flag_id,
    character_id: started.character_id,
    location_id: started.location_id,
    state: started.state,
    screen: 'academy-conversation-session',
    route: 'graduation-ending'
  });
  const readiness = (async () => {
    await refresh();
    openingPromise = ensureOpeningUtterance({ onAssistantStreamStart: markOpeningStreamStarted });
    await Promise.race([openingStreamStarted, openingPromise]);
  })();
  try {
    conversationRequestInFlight = true;
    setConversationControlsDisabled(true);
    if (loadingAlreadyVisible) {
      try {
        await readiness;
      } catch (error) {
        reportLoadingError(error);
        throw error;
      }
      showScreen('academy-conversation-session');
    } else {
      await showAcademyLoadingScreenUntilReady({
        readiness,
        nextScreen: 'academy-conversation-session',
        refreshBeforeNextScreen: false,
        copyKey: 'graduation-ending-start'
      });
    }
    await openingPromise;
  } catch (error) {
    // Loading-residual defense (same discipline as runRoutingHubConversation): a failed graduation entry must not
    // leave the player on the academy-loading screen. A settings-redirect error already left it (reportLoadingError
    // → settings); for any other failure still on the loader, un-strand to the legacy graduation surface with the
    // cause on its status line, then re-raise so the caller's own reporter logs it once.
    if (isAcademyLoadingScreenActive() && settingsRedirectErrorMessage(error) == null) {
      showScreen('academy-conversation-session');
      setConversationStatus(errorDisplayMessage(error), { tone: 'error' });
    }
    throw error;
  } finally {
    conversationRequestInFlight = false;
    setConversationControlsDisabled(false);
  }
}

// Daytime landing for the graduation ending event conversation of the loop graduation (in routing, an academy person
// opens through openEventConversationDay and the 案内人's graduation goes on on the terrace). Unlike startConversationDayFromPendingEvent, the graduation interaction is ALREADY set up server-side, so this
// adopts the started state and opens the daytime surface WITHOUT re-calling /api/event-flags/start (a second
// start on an already-started graduation flag would be wrong). The stage frame shows the event location's field
// stage (renderConversationDayStage → the refreshed field). Loading stays covered by the shared
// graduation-ending-start copy (M-2026-07-06-001), reusing the caller's already-visible loading when present.
async function routeGraduationEndingSessionDay(started, { loadingAlreadyVisible = false } = {}) {
  markConversationDayKind(null);
  let openingStreamStartedResolve = null;
  let openingStreamStartedResolved = false;
  let openingPromise = Promise.resolve();
  const openingStreamStarted = new Promise((resolve) => {
    openingStreamStartedResolve = resolve;
  });
  const markOpeningStreamStarted = () => {
    if (openingStreamStartedResolved) return;
    openingStreamStartedResolved = true;
    openingStreamStartedResolve?.();
  };
  activeCharacterId = started.character_id ?? activeCharacterId;
  currentRuntimeState = started.state ?? currentRuntimeState;
  clearVisibleConversation();
  conversationDayStage.surface.setHistory([]);
  writeDebugLog({
    started_event_interaction: started.flag_id,
    character_id: started.character_id,
    location_id: started.location_id,
    state: started.state,
    screen: 'conversation-day',
    route: 'graduation-ending'
  });
  const readiness = (async () => {
    await refresh();
    openingPromise = ensureConversationDayOpening({ onAssistantStreamStart: markOpeningStreamStarted });
    await Promise.race([openingStreamStarted, openingPromise]);
  })();
  try {
    conversationRequestInFlight = true;
    conversationDayStage.setControlsDisabled(true);
    if (loadingAlreadyVisible) {
      try {
        await readiness;
      } catch (error) {
        reportLoadingError(error);
        throw error;
      }
      showScreen('conversation-day');
    } else {
      await showAcademyLoadingScreenUntilReady({
        readiness,
        nextScreen: 'conversation-day',
        refreshBeforeNextScreen: false,
        copyKey: 'graduation-ending-start'
      });
    }
    renderConversationDayStage();
    await openingPromise;
  } catch (error) {
    // Loading-residual defense: same as the legacy landing, but the daytime graduation surface. A non-settings
    // failure still on the loader un-strands to conversation-day with the cause on its status line, then re-raises.
    if (isAcademyLoadingScreenActive() && settingsRedirectErrorMessage(error) == null) {
      showScreen('conversation-day');
      conversationDayStage.setStatus(errorDisplayMessage(error), { tone: 'error' });
    }
    throw error;
  } finally {
    conversationRequestInFlight = false;
    conversationDayStage.setControlsDisabled(false);
    focusConversationDayInputIfContinuing();
  }
}

// Re-enter an in-flight graduation phase-2 conversation from a load / resume play entry (contract:
// graduationPhase2ReentryClient.parseGraduationPhase2Reentry). This bypasses the routing hub start / academy-room
// landing entirely: the saved conversation entry state (actor, pending graduation event context, active
// conversation) is preserved by the backend load, so the phase-2 conversation resumes in place instead of the
// graduation flow restarting after the next action.
//
// The 案内人 re-enters on the terrace (reenterGuideGraduationOnTerrace). An academy person's routing graduation
// re-enters like any event conversation (openEventConversationDay: the passage onto the daytime screen marked event),
// whichever screen the slot was saved under. The loop graduation picks its surface by the SAVED screen ('interaction' →
// daytime, 'academy-conversation-session' → legacy). The opening runs with no explicit conversation id: the backend
// re-uses the active conversation (messages present → the existing conversation is returned and its full history is
// restored to the stream; absent → a fresh opening is generated). /api/event-flags/start is never re-issued (same
// discipline as routeGraduationEndingSessionDay).
// The preserved state of an in-flight phase 2 must still carry the graduation ending event context. Read it strictly
// (fail-fast) rather than substituting a default: a missing/mismatched context is a real backend-contract violation
// for a slot the entry contract already declared mid-phase-2, not something to paper over with a hardcoded flag id.
async function readPreservedGraduationPhase2(reentry) {
  const state = await getJson('/api/state');
  const pending = state?.pending_interaction_context;
  if (pending?.event_flag_id !== 'event.graduation_ending.ready') {
    throw new Error(`graduation phase-2 re-entry expected the preserved graduation ending event context on /api/state, got: ${JSON.stringify(pending)}`);
  }
  return {
    character_id: reentry.character_id,
    state,
    flag_id: pending.event_flag_id,
    location_id: pending.location_id
  };
}

// The 案内人's graduation re-entry: the terrace as it always looks, with the graduation conversation going on in its
// stream. The terrace opens without a hub start (the backend 409s a hub start mid-phase-2), so the contract carries what
// a hub start would have answered for it — the persona visual and the destination names. The loading screen is the
// hub-entry one every routing load shows (never the graduation-ending-start box). The conversation is the active one
// the backend restores with its full history (the opening with no id); it must be the contract's conversation.
async function reenterGuideGraduationOnTerrace(reentry) {
  setAcademyLoadingDestinationCopy(null, { loadingCopy: ROUTING_HUB_ENTRY_LOADING_COPY });
  showScreen('academy-loading');
  conversationRequestInFlight = true;
  setConversationControlsDisabled(true);
  try {
    hubTerrace.setDestinations(reentry.routing_destinations);
    registerRoutingPersonaVisual(reentry.routing_persona_visual);
    const started = await readPreservedGraduationPhase2(reentry);
    currentRuntimeState = started.state;
    notifyAcademyLoadingProgress();
    const result = await postJson('/api/conversation/opening', { character_id: ROUTING_PERSONA_CHARACTER_ID, provider: conversationProvider() });
    const conversation = result.conversation;
    if (conversation?.id !== reentry.last_conversation_id || conversation.character_id !== ROUTING_PERSONA_CHARACTER_ID) {
      throw new Error(`guide graduation re-entry expected the active conversation ${JSON.stringify(reentry.last_conversation_id)} of the 案内人, got ${JSON.stringify({ id: conversation?.id, character_id: conversation?.character_id })}`);
    }
    routingHubConversationId = conversation.id;
    activeCharacterId = ROUTING_PERSONA_CHARACTER_ID;
    markTerraceGraduation(true);
    clearRoutingHubStartFailure();
    clearVisibleConversation();
    routingHubStage.surface.commitState(result);
    await refresh();
    notifyAcademyLoadingProgress();
    showScreen('routing-hub');
    routingHubStage.renderStream(routingHubStage.surface.getHistory());
    await Promise.all([refreshPrompt(), refreshRecordStatus()]);
  } catch (error) {
    // Loading-residual defense: a failed re-entry never strands the player on the loader. A settings-redirect error
    // already left it for the settings screen; any other failure returns to the slot list it was entered from.
    if (isAcademyLoadingScreenActive() && settingsRedirectErrorMessage(error) == null) showScreen('slot-load');
    throw error;
  } finally {
    conversationRequestInFlight = false;
    setConversationControlsDisabled(false);
  }
}

async function reenterGraduationPhase2(reentry, { mode }) {
  if (mode !== 'loop' && mode !== 'routing') throw new Error(`graduation phase-2 re-entry: unexpected play mode ${JSON.stringify(mode)}`);
  if (mode === 'routing' && reentry.is_guide_persona) {
    await reenterGuideGraduationOnTerrace(reentry);
    return;
  }
  if (mode === 'routing') {
    // Adopt the preserved state before the passage begins, so the week it lays out is the conversation's week.
    const started = await readPreservedGraduationPhase2(reentry);
    activeCharacterId = started.character_id;
    currentRuntimeState = started.state;
    await openEventConversationDay(async () => started, { loader: 'own' });
    return;
  }
  markConversationDayKind(null);
  const readiness = (async () => {
    // Adopt the preserved runtime state (graduation ending event context intact) up front, before the route
    // function's own refresh.
    const started = await readPreservedGraduationPhase2(reentry);
    activeCharacterId = started.character_id;
    currentRuntimeState = started.state;
    if (reentry.screen === 'academy-conversation-session') {
      await routeGraduationEndingSessionLegacy(started, { loadingAlreadyVisible: true });
    } else {
      await routeGraduationEndingSessionDay(started, { loadingAlreadyVisible: true });
    }
  })();
  try {
    await showAcademyLoadingScreenUntilReady({
      readiness,
      refreshBeforeNextScreen: false,
      copyKey: 'graduation-ending-start'
    });
  } catch (error) {
    // Loading-residual defense for the re-entry's OWN pre-route failures (the /api/state read + preserved-context
    // validation that run before the route function is called): those never reach the route function's un-strand,
    // so a non-settings failure would otherwise strand the loader. Un-strand to the surface the saved screen would
    // have re-entered (legacy → conversation session, else daytime) with the cause on its status line. A failure
    // inside the route function has already un-stranded itself (loader inactive), so the guard skips it here.
    if (isAcademyLoadingScreenActive() && settingsRedirectErrorMessage(error) == null) {
      if (reentry.screen === 'academy-conversation-session') {
        showScreen('academy-conversation-session');
        setConversationStatus(errorDisplayMessage(error), { tone: 'error' });
      } else {
        showScreen('conversation-day');
        conversationDayStage.setStatus(errorDisplayMessage(error), { tone: 'error' });
      }
    }
    throw error;
  }
}

async function openAcademyRoomTraining() {
  if (academyRoomActionInFlight) {
    showProcessingToast();
    return;
  }
  academyRoomActionInFlight = true;
  setAcademyRoomActionButtonsDisabled(true);
  try {
    if (isEnteringGraduationEndingWeek()) {
      const readiness = (async () => {
        await waitForConversationFinalization();
        const started = await postJson('/api/academy/week/start', {});
        writeDebugLog(started);
        currentRuntimeState = started.state ?? currentRuntimeState;
        if (started.route === 'graduation-ending') {
          await routeGraduationEndingSession(started, { loadingAlreadyVisible: true });
          return;
        }
        showScreen('academy-training');
      })();
      await showAcademyLoadingScreenUntilReady({
        readiness,
        refreshBeforeNextScreen: false,
        copyKey: 'graduation-ending-start'
      });
      return;
    }
    const started = await postJson('/api/academy/week/start', {});
    writeDebugLog(started);
    currentRuntimeState = started.state ?? currentRuntimeState;
    if (started.route === 'graduation-ending') {
      await routeGraduationEndingSession(started);
      return;
    }
    await showAcademyLoadingScreenUntilReady({
      readiness: Promise.resolve(),
      nextScreen: 'academy-training',
      refreshBeforeNextScreen: false
    });
  } catch (error) {
    // Loading-residual defense: the graduation-week branch runs the week start behind the loading screen, so a
    // non-settings failure there would strand the loader. Un-strand to the 自室 (academy-room) — the operable origin
    // these buttons live on, reachable via the top bar — then re-raise so the click handler's reporter logs it. A
    // graduation-route failure has already un-stranded to its conversation surface (loader inactive), so the guard
    // skips it. The non-graduation week start runs BEFORE any loader, so its failure never reaches the loader.
    if (isAcademyLoadingScreenActive() && settingsRedirectErrorMessage(error) == null) showScreen('academy-room');
    throw error;
  } finally {
    academyRoomActionInFlight = false;
    setAcademyRoomActionButtonsDisabled(false);
  }
}

async function openAcademyRoomSkipTraining() {
  if (academyRoomActionInFlight) {
    showProcessingToast();
    return;
  }
  academyRoomActionInFlight = true;
  setAcademyRoomActionButtonsDisabled(true);
  try {
    if (isEnteringGraduationEndingWeek()) {
      const readiness = (async () => {
        await waitForConversationFinalization();
        const started = await postJson('/api/academy/week/start', {});
        writeDebugLog(started);
        currentRuntimeState = started.state ?? currentRuntimeState;
        if (started.route === 'graduation-ending') {
          await routeGraduationEndingSession(started, { loadingAlreadyVisible: true });
          return;
        }
        const skipped = await postJson('/api/training/skip', {});
        currentWorld = skipped.world;
        currentRuntimeState = skipped.state ?? currentRuntimeState;
        renderPlayerParametersEditor(currentWorld.player_parameters ?? {});
        renderTrainingPlayerParameters(currentWorld.player_parameters ?? {});
        renderTrainingProgress(skipped.training_progress);
        await refreshPrompt();
        await routeAfterCompletedAcademyTraining(skipped.post_content_screen);
      })();
      await showAcademyLoadingScreenUntilReady({
        readiness,
        refreshBeforeNextScreen: false,
        copyKey: 'graduation-ending-start'
      });
      return;
    }
    const started = await postJson('/api/academy/week/start', {});
    writeDebugLog(started);
    currentRuntimeState = started.state ?? currentRuntimeState;
    if (started.route === 'graduation-ending') {
      await routeGraduationEndingSession(started);
      return;
    }
    const skipped = await postJson('/api/training/skip', {});
    currentWorld = skipped.world;
    currentRuntimeState = skipped.state ?? currentRuntimeState;
    renderPlayerParametersEditor(currentWorld.player_parameters ?? {});
    renderTrainingPlayerParameters(currentWorld.player_parameters ?? {});
    renderTrainingProgress(skipped.training_progress);
    await refreshPrompt();
    await routeAfterCompletedAcademyTraining(skipped.post_content_screen);
  } catch (error) {
    // Loading-residual defense (mirror of openAcademyRoomTraining): the graduation-week branch runs the week start
    // behind the loading screen, so a non-settings failure there un-strands to the 自室 (academy-room). A graduation
    // route / training-completion failure has already un-stranded itself (loader inactive), so the guard skips it.
    if (isAcademyLoadingScreenActive() && settingsRedirectErrorMessage(error) == null) showScreen('academy-room');
    throw error;
  } finally {
    academyRoomActionInFlight = false;
    setAcademyRoomActionButtonsDisabled(false);
  }
}

async function routePendingEventFromAcademyMap() {
  const status = await refreshEventFlagStatus();
  const autoStartFlag = (status.pending_events ?? []).find((flag) => flag.interaction?.location_id && flag.character_id);
  if (!autoStartFlag) return false;
  await startAcademyConversationSessionFromPendingEvent(autoStartFlag.id);
  return true;
}

async function routeNewGameIntroFromTitle() {
  const status = await refreshEventFlagStatus();
  const introFlag = (status.pending_events ?? []).find((flag) => flag.id === 'event.opening_mentor_intro.ready' && flag.interaction?.location_id && flag.character_id);
  if (!introFlag) return false;
  // The new-game mentor intro is an event conversation too: it lands on the daytime screen through the conversation
  // passage. Routing is the official mode, so there is no legacy landing here.
  await startConversationDayFromPendingEvent(introFlag.id);
  return true;
}

async function routeAfterCompletedAcademyTraining(postContentScreen) {
  // routing dispatched the player here; completed training returns to the hub over the training ground's art
  // (returnToRoutingHubFromPlace).
  if (postContentScreen === 'interaction') {
    await returnToRoutingHubFromPlace();
    return;
  }
  // loop returns to the academy map (the event-aware loading route). An unexpected screen is a
  // fail-fast, not a silent default.
  if (postContentScreen !== 'academy-map') {
    throw new Error(`training completion: unexpected post_content_screen ${JSON.stringify(postContentScreen)}`);
  }
  setAcademyLoadingDestinationCopy('academy-map');
  showScreen('academy-loading');
  try {
    const minimumDisplay = new Promise((resolve) => setTimeout(resolve, ACADEMY_LOADING_MINIMUM_MS));
    await Promise.all([minimumDisplay, waitForAcademyMapReadiness()]);
    // The readiness wait and the pending-event scan are the observed boundaries this loop completion holds under
    // the loading screen. Advance the constellation at each so the no-event map landing is no longer 0-edge; the
    // pending-event branch continues into the event start's own wiring.
    notifyAcademyLoadingProgress();
    const status = await refreshEventFlagStatus();
    notifyAcademyLoadingProgress();
    const autoStartFlag = (status.pending_events ?? []).find((flag) => flag.interaction?.location_id && flag.character_id);
    if (autoStartFlag) {
      await startAcademyConversationSessionFromPendingEvent(autoStartFlag.id, { loadingAlreadyVisible: true });
      return;
    }
    await refresh();
    notifyAcademyLoadingProgress();
    showScreen('academy-map');
  } catch (error) {
    // Loading-residual defense: this loop branch raises the loading screen directly, so a non-settings failure in the
    // readiness / event scan / refresh would strand it. Un-strand to the academy map — the loop destination this
    // completion reaches, operable and top-bar reachable — then re-raise so the caller's reporter logs it. An event
    // auto-start failure has already un-stranded to its own conversation surface (loader inactive), so the guard skips.
    if (isAcademyLoadingScreenActive() && settingsRedirectErrorMessage(error) == null) showScreen('academy-map');
    throw error;
  }
}

// The settings screen is a master-detail category nav: a category list plus only the selected
// category's panel. These are the categories, in nav order; the first is the default shown on open.
const SETTINGS_CATEGORIES = ['lmstudio', 'conversation-popup', 'audio'];
const DEFAULT_SETTINGS_CATEGORY = 'lmstudio';

// Show exactly the chosen category's panel and mark its nav tab active. Unknown categories fail-fast
// (no silent fallback to a default panel). Panels toggle via the `hidden` attribute, which the
// #settings-screen [hidden] id-scoped guard forces to display:none even though .settings-card is a
// display:grid element.
function selectSettingsCategory(category) {
  if (!SETTINGS_CATEGORIES.includes(category)) {
    throw new Error(`unknown settings category: ${category}`);
  }
  for (const panel of document.querySelectorAll('.settings-category-panel')) {
    panel.hidden = panel.dataset.settingsCategory !== category;
  }
  for (const tab of document.querySelectorAll('.settings-category-tab')) {
    const active = tab.dataset.settingsCategory === category;
    tab.classList.toggle('is-active', active);
    tab.setAttribute('aria-pressed', active ? 'true' : 'false');
  }
}

// Open the settings screen and reflect every persisted settings section from disk. Every settings
// entry point (the top-bar 設定 tab and the title/academy-map 設定 button) routes through here so
// the displayed state — LM Studio connection, conversation popup and audio — is identical regardless of entry.
// The default category is selected on every open so no empty panel is ever shown.
function openSettingsScreen() {
  showScreen('settings');
  refreshSettingsScreen();
}

// Reflect the persisted settings into the settings screen without switching screens. openSettingsScreen runs it
// after showing the screen; the night journey runs it alone when the settings room is lit over the screen in play.
function refreshSettingsScreen() {
  selectSettingsCategory(DEFAULT_SETTINGS_CATEGORY);
  loadLmStudioSettings().catch(reportError);
  loadConversationPopupSettings().catch(reportError);
  loadAudioSettings().catch(reportError);
}

for (const tab of tabs) {
  tab.addEventListener('click', () => {
    if (tab.dataset.screen === 'event') {
      openEventTab().catch(reportError);
      return;
    }
    if (tab.dataset.screen === 'slot-load') {
      openLoadScreen({ canResumePlay: document.body.classList.contains('play-mode') }).catch(reportError);
      return;
    }
    if (tab.dataset.screen === 'settings') {
      openSettingsScreen();
      return;
    }
    showScreen(tab.dataset.screen);
  });
}

async function getJson(url) {
  const response = await fetch(url);
  return readJsonResponse(response, url);
}

async function patchJson(url, body) {
  const response = await fetch(url, {
    method: 'PATCH',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(body)
  });
  return readJsonResponse(response, url);
}

async function postJson(url, body) {
  const response = await fetch(url, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(body)
  });
  return readJsonResponse(response, url);
}

function createApiError({ url, status, payload, fallbackText = '' }) {
  const message = payload?.error ?? `${url}: ${status} ${fallbackText}`.trim();
  const error = new Error(message);
  error.statusCode = status;
  error.errorCode = payload?.error_code ?? null;
  error.payload = payload ?? null;
  return error;
}

function parseJsonText(text) {
  if (!text) return null;
  try {
    return JSON.parse(text);
  } catch {
    return null;
  }
}

async function readJsonResponse(response, url) {
  const text = await response.text();
  const payload = parseJsonText(text);
  if (!response.ok) throw createApiError({ url, status: response.status, payload, fallbackText: text });
  return payload;
}

function defaultLmStudioSettings() {
  return {
    host: '127.0.0.1',
    port: 1234,
    base_url: 'http://127.0.0.1:1234/v1',
    model: '',
    chat_model: '',
    reflection_model: '',
    timeout_ms: null,
    stream: false,
    thinking_effort: null,
    provider: 'lmstudio',
    mock_provider_enabled: false
  };
}

function lmStudioSettingsElements() {
  return {
    status: document.querySelector('#lmstudio-settings-status'),
    host: document.querySelector('#lmstudio-host'),
    port: document.querySelector('#lmstudio-port'),
    model: document.querySelector('#lmstudio-model'),
    thinkingEffort: document.querySelector('#lmstudio-thinking-effort'),
    modelStatus: document.querySelector('#lmstudio-model-status'),
    fetchModelsButton: document.querySelector('#fetch-lmstudio-models')
  };
}

function normalizeLmStudioHost(value) {
  return String(value ?? '').trim();
}

function normalizeLmStudioModelValue(value) {
  return String(value ?? '').trim();
}

function normalizeLmStudioThinkingEffortSelectValue(value) {
  return value === 'low' || value === 'medium' || value === 'high' ? value : 'none';
}

function lmStudioThinkingEffortFromSelectValue(value) {
  if (value === 'none') return null;
  return value === 'low' || value === 'medium' || value === 'high' ? value : null;
}

function effectiveLmStudioModel(settings = currentLmStudioSettings) {
  return normalizeLmStudioModelValue(settings?.model ?? settings?.chat_model ?? settings?.reflection_model ?? '');
}

function normalizeLmStudioModelOptions(models = []) {
  return models
    .map((entry) => {
      const id = normalizeLmStudioModelValue(entry?.id);
      if (!id) return null;
      return {
        id,
        label: normalizeLmStudioModelValue(entry?.label) || id
      };
    })
    .filter(Boolean);
}

function setLmStudioSettingsStatus(message) {
  const { status } = lmStudioSettingsElements();
  if (status) status.textContent = message;
}

// 設定の欄の待ち: 状態の行の字の代わりに画面の中の待ちの印を置く（右下で待ちの紋が回る）。
function showSettingsStatusWait(status) {
  if (status) status.replaceChildren(screenWaitMark());
}

function setLmStudioModelStatus(message) {
  const { modelStatus } = lmStudioSettingsElements();
  if (modelStatus) modelStatus.textContent = message;
}

function renderLmStudioModelOptions(settings = currentLmStudioSettings) {
  const { model } = lmStudioSettingsElements();
  if (!model) return;
  const selectedModel = effectiveLmStudioModel(settings);
  const fetchedOptions = normalizeLmStudioModelOptions(lmStudioFetchedModelOptions);
  const hasCurrentValue = fetchedOptions.some((option) => option.id === selectedModel);
  const options = fetchedOptions.slice();
  if (selectedModel && !hasCurrentValue) {
    options.unshift({ id: selectedModel, label: `${selectedModel}（現在の保存値・一覧外）` });
  }

  model.innerHTML = '';
  model.append(new Option('未選択', ''));
  for (const option of options) {
    model.append(new Option(option.label, option.id));
  }
  model.value = selectedModel || '';

  if (selectedModel && !hasCurrentValue && fetchedOptions.length > 0) {
    setLmStudioModelStatus(`現在モデル: ${selectedModel}（取得した一覧には見つかりませんでした）`);
  } else if (selectedModel) {
    setLmStudioModelStatus(`現在モデル: ${selectedModel}`);
  } else {
    setLmStudioModelStatus('未選択');
  }
}

function renderLmStudioSettings(settings = currentLmStudioSettings ?? defaultLmStudioSettings()) {
  if (!settings) return;
  const { host, port, thinkingEffort } = lmStudioSettingsElements();
  if (host) host.value = settings.host ?? '127.0.0.1';
  if (port) port.value = String(settings.port ?? 1234);
  if (thinkingEffort) thinkingEffort.value = normalizeLmStudioThinkingEffortSelectValue(settings.thinking_effort);
  renderLmStudioModelOptions(settings);
  setLmStudioSettingsStatus(`現在: ${settings.base_url}`);
}

async function loadLmStudioSettings() {
  showSettingsStatusWait(lmStudioSettingsElements().status);
  try {
    currentLmStudioSettings = await getJson('/api/settings/lmstudio');
  } catch (error) {
    if (error?.errorCode !== 'LMSTUDIO_CONFIG_REQUIRED') throw error;
    currentLmStudioSettings = defaultLmStudioSettings();
    lmStudioFetchedModelOptions = [];
    renderLmStudioSettings(currentLmStudioSettings);
    setLmStudioSettingsStatus('LM Studioの設定が必要です。設定画面で接続先とモデルを保存してください。');
    return currentLmStudioSettings;
  }
  lmStudioFetchedModelOptions = [];
  renderLmStudioSettings(currentLmStudioSettings);
  return currentLmStudioSettings;
}

// Terminal text for a failed モデル一覧を取得. The server names a transport failure as 502
// `{ error_code: 'LMSTUDIO_MODEL_LIST_UNAVAILABLE', target, cause_code | cause_message }`; this maps
// that onto a closed table keyed by cause_code and always names the target. A code outside the table
// is shown verbatim in the generic row (never rounded to an unnamed error), and a payload that claims
// the diagnostics code without the fields the contract promises throws instead of guessing. Every other
// rejection (validation 400, non-transport 502, a network reject reaching our own server) terminates
// the status with its concrete reason.
const LM_STUDIO_MODEL_LIST_UNAVAILABLE_CODE = 'LMSTUDIO_MODEL_LIST_UNAVAILABLE';
const LM_STUDIO_UNREACHABLE_CAUSE_CODES = new Set(['EHOSTUNREACH', 'ETIMEDOUT', 'UND_ERR_CONNECT_TIMEOUT']);

// The transport-failure table itself, shared by every LM transport diagnostics payload (`target` plus one of
// `cause_code` / `cause_message`): the model list (LMSTUDIO_MODEL_LIST_UNAVAILABLE) and the conversation
// post-processing retry (LMSTUDIO_CONNECTION_UNAVAILABLE).
function lmStudioTransportFailureMessage(payload) {
  const errorCode = payload?.error_code;
  const target = typeof payload?.target === 'string' ? payload.target.trim() : '';
  if (!target) throw new Error(`${errorCode} response carries no target`);
  const causeCode = typeof payload.cause_code === 'string' ? payload.cause_code.trim() : '';
  const causeMessage = typeof payload.cause_message === 'string' ? payload.cause_message.trim() : '';
  if (causeCode) {
    if (LM_STUDIO_UNREACHABLE_CAUSE_CODES.has(causeCode)) {
      return `${target} に届きません。IP・LM Studio 側の起動・macOS の「ローカルネットワーク」権限（STARFALL MAGIC ACADEMY）を確認してください。`;
    }
    if (causeCode === 'ECONNREFUSED') {
      return `${target} は在りますが、この port で LM Studio が待ち受けていません。`;
    }
    return `${target} への接続に失敗しました（${causeCode}）。`;
  }
  if (causeMessage) return `${target} への接続に失敗しました（${causeMessage}）。`;
  throw new Error(`${errorCode} response carries neither cause_code nor cause_message`);
}

function lmStudioModelListFailureMessage(error) {
  const payload = error?.payload;
  if (payload?.error_code === LM_STUDIO_MODEL_LIST_UNAVAILABLE_CODE) return lmStudioTransportFailureMessage(payload);
  const reason = String(payload?.error ?? error?.message ?? '').trim();
  if (!reason) throw new Error('model list request failed without a reason');
  return `モデル一覧の取得に失敗しました: ${reason}`;
}

async function fetchLmStudioModels() {
  const { host, port, fetchModelsButton, modelStatus } = lmStudioSettingsElements();
  showSettingsStatusWait(modelStatus);
  if (fetchModelsButton) fetchModelsButton.disabled = true;
  // Success and failure both drive the model status to a terminal state: a failure paints the
  // cause-naming line (lmStudioModelListFailureMessage) so the wait mark never survives the request, then the
  // original error is rethrown to reportError so console/global reporting is unchanged.
  try {
    const response = await fetch('/api/settings/lmstudio/models', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({
        host: host?.value,
        port: Number(port?.value || 1234)
      })
    });
    const payload = (await readJsonResponse(response, '/api/settings/lmstudio/models')) ?? { models: [] };
    lmStudioFetchedModelOptions = normalizeLmStudioModelOptions(payload.models);
    renderLmStudioModelOptions(currentLmStudioSettings);
    setLmStudioSettingsStatus(`現在: ${payload.base_url}`);
    if ((lmStudioFetchedModelOptions ?? []).length === 0) {
      setLmStudioModelStatus('利用可能なモデルは返ってきませんでした。');
    }
    return payload;
  } catch (error) {
    let message;
    try {
      message = lmStudioModelListFailureMessage(error);
    } catch (contractError) {
      setLmStudioModelStatus(contractError.message);
      throw contractError;
    }
    setLmStudioModelStatus(message);
    throw error;
  } finally {
    if (fetchModelsButton) fetchModelsButton.disabled = false;
  }
}

// LM Studio settings apply on change — no save button. A committed host/port edit (blur/Enter) or a
// model / thinking-effort selection each calls this, symmetric with the play-mode radios. The destination
// is the host + port fields alone (the server builds base_url from them). The backend requires a model;
// while none is chosen the model status names it 未選択 and no PATCH leaves the client (not a silent
// skip or a defaulted model). An empty host is the server's to reject (400 host is required), and that
// reason lands on the status line like any other failed save.
async function saveLmStudioSettings() {
  const { host, port, model, thinkingEffort } = lmStudioSettingsElements();
  const selectedModel = normalizeLmStudioModelValue(model?.value);
  if (!selectedModel) {
    setLmStudioModelStatus('未選択');
    return null;
  }
  showSettingsStatusWait(lmStudioSettingsElements().status);
  // Both success and failure drive the category status to a terminal state: on failure the category panel
  // shows the concrete reason (server error body / network reject / malformed response) instead of staying
  // stuck on the wait mark, then the original error is rethrown to reportError so console/global reporting is
  // unchanged. No silent retry or fallback.
  try {
    const saved = await patchJson('/api/settings/lmstudio', {
      host: host?.value,
      port: Number(port?.value || 1234),
      model: selectedModel,
      thinking_effort: lmStudioThinkingEffortFromSelectValue(thinkingEffort?.value ?? 'none')
    });
    if (!saved) throw new Error('LM Studio settings save returned no body');
    currentLmStudioSettings = saved;
    renderLmStudioSettings(currentLmStudioSettings);
    setLmStudioSettingsStatus(`反映しました: ${currentLmStudioSettings?.base_url ?? ''}`);
    return currentLmStudioSettings;
  } catch (error) {
    setLmStudioSettingsStatus(settingsSaveErrorMessage(error, 'LM Studio'));
    throw error;
  }
}

function conversationPopupSettingsElements() {
  return {
    cooldown: document.querySelector('#conv-popup-cooldown-preset'),
    status: document.querySelector('#conv-popup-settings-status')
  };
}

function setConversationPopupSettingsStatus(text) {
  const { status } = conversationPopupSettingsElements();
  if (status) status.textContent = text;
}

function renderConversationPopupSettings() {
  const { cooldown } = conversationPopupSettingsElements();
  if (cooldown) cooldown.value = String(conversationPopupCooldownMs());
}

async function loadConversationPopupSettings() {
  const settings = await getJson('/api/settings/conversation-popup');
  applyConversationPopupSettings(settings);
  renderConversationPopupSettings();
  setConversationPopupSettingsStatus(`現在: クールタイム ${conversationPopupCooldownMs()}ms`);
  return settings;
}

async function saveConversationPopupSettings() {
  const { cooldown, status } = conversationPopupSettingsElements();
  showSettingsStatusWait(status);
  // Both success and failure drive the category status to a terminal state: on failure the category panel
  // shows the concrete reason (server error body / network reject / malformed response) instead of staying
  // stuck on the wait mark, then the original error is rethrown to reportError so console/global reporting is
  // unchanged. No silent retry or fallback.
  try {
    const saved = await patchJson('/api/settings/conversation-popup', {
      cooldown_ms: Number(cooldown?.value)
    });
    if (!saved) throw new Error('conversation popup settings save returned no body');
    applyConversationPopupSettings(saved);
    renderConversationPopupSettings();
    setConversationPopupSettingsStatus(`保存しました: クールタイム ${conversationPopupCooldownMs()}ms`);
    return saved;
  } catch (error) {
    setConversationPopupSettingsStatus(settingsSaveErrorMessage(error, '会話ポップアップ'));
    throw error;
  }
}

function audioSettingsElements() {
  return {
    enabled: document.querySelector('#audio-bgm-enabled'),
    volume: document.querySelector('#audio-bgm-volume'),
    status: document.querySelector('#audio-settings-status')
  };
}

function setAudioSettingsStatus(text) {
  const { status } = audioSettingsElements();
  if (status) status.textContent = text;
}

function describeAudioSettings(settings) {
  const percent = Math.round(settings.bgm_volume * 100);
  return settings.bgm_enabled ? `BGM: オン（音量 ${percent}%）` : 'BGM: オフ';
}

// Reflect the disk values into the controls + apply them to the controller. The controller applyAudioSettings is
// strict, so a malformed GET response fails fast rather than rendering a fabricated state.
function renderAudioSettings(settings) {
  const { enabled, volume } = audioSettingsElements();
  if (enabled) enabled.checked = settings.bgm_enabled;
  if (volume) volume.value = String(settings.bgm_volume);
}

async function loadAudioSettings() {
  const settings = await getJson('/api/settings/audio');
  bgmController.applyAudioSettings(settings);
  renderAudioSettings(settings);
  setAudioSettingsStatus(`現在: ${describeAudioSettings(settings)}`);
  return settings;
}

// On-change PATCH of a single field (the changed control), symmetric with the other categories' no-save-button
// apply. A non-OK response throws to reportError — no silent fallback. The persisted response is applied to the
// controller so the change takes effect on the playing BGM without restarting the source.
async function saveAudioSettings(update) {
  showSettingsStatusWait(audioSettingsElements().status);
  // Both success and failure drive the category status to a terminal state: on failure the category panel
  // shows the concrete reason (server error body / network reject / malformed response — applyAudioSettings
  // is strict and throws on a malformed shape) instead of staying stuck on the wait mark, then the original
  // error is rethrown to reportError so console/global reporting is unchanged. No silent retry or fallback.
  try {
    const saved = await patchJson('/api/settings/audio', update);
    bgmController.applyAudioSettings(saved);
    renderAudioSettings(saved);
    setAudioSettingsStatus(`保存しました: ${describeAudioSettings(saved)}`);
    return saved;
  } catch (error) {
    setAudioSettingsStatus(settingsSaveErrorMessage(error, '音声'));
    throw error;
  }
}

function normalizeSlotNoteValue(value) {
  return String(value ?? '')
    .replace(/\r\n/g, '\n')
    .trim()
    .slice(0, SLOT_LOAD_NOTE_MAX_LENGTH);
}

function describeSlotNoteStatus(note) {
  const length = String(note ?? '').length;
  return length ? `${length}/${SLOT_LOAD_NOTE_MAX_LENGTH}文字` : '空欄のままでも保存できます。';
}

async function saveSlotNote(slotId, playerNote) {
  const response = await fetch(`/api/slots/${encodeURIComponent(slotId)}/note`, {
    method: 'PATCH',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ player_note: playerNote })
  });
  const text = await response.text();
  if (!response.ok) throw new Error(`/api/slots/${encodeURIComponent(slotId)}/note: ${response.status} ${text}`);
  return text ? JSON.parse(text) : null;
}

function renderSlotNoteEditor(slot) {
  const editor = document.createElement('div');
  editor.className = 'slot-load-note-editor';

  const label = document.createElement('label');
  label.className = 'slot-load-note-label';

  const heading = document.createElement('span');
  heading.textContent = 'メモ';

  const textarea = document.createElement('textarea');
  textarea.name = `player_note_${slot.slot_id}`;
  textarea.placeholder = 'このスロットの進行メモ';
  textarea.maxLength = SLOT_LOAD_NOTE_MAX_LENGTH;
  textarea.value = slot.player_note ?? '';
  textarea.dataset.lastSaved = normalizeSlotNoteValue(slot.player_note ?? '');

  const status = document.createElement('small');
  status.className = 'slot-load-note-status';
  status.textContent = describeSlotNoteStatus(textarea.dataset.lastSaved);

  textarea.addEventListener('input', () => {
    const normalized = normalizeSlotNoteValue(textarea.value);
    status.textContent = normalized === (textarea.dataset.lastSaved ?? '')
      ? describeSlotNoteStatus(normalized)
      : '編集中…';
  });

  textarea.addEventListener('blur', () => {
    const run = async () => {
      const normalized = normalizeSlotNoteValue(textarea.value);
      if (normalized === (textarea.dataset.lastSaved ?? '')) {
        textarea.value = normalized;
        status.textContent = describeSlotNoteStatus(normalized);
        return;
      }
      textarea.disabled = true;
      status.replaceChildren(screenWaitMark());
      const result = await saveSlotNote(slot.slot_id, textarea.value);
      const savedNote = result?.slot?.player_note ?? normalized;
      textarea.value = savedNote;
      textarea.dataset.lastSaved = savedNote;
      status.textContent = describeSlotNoteStatus(savedNote);
      await refreshSaveSlots();
    };
    run().catch(reportError).finally(() => {
      textarea.disabled = false;
    });
  });

  label.append(heading, textarea);
  editor.append(label, status);
  return editor;
}

function characterSceneStandeeUrl(character = activeCharacter()) {
  return character?.standee_url ?? '';
}

// Creature visual sets may not be generated yet during the trial; hide a broken
// image instead of breaking the layout (the surrounding frame keeps its size).
function hideImageOnError(image) {
  image.onerror = () => {
    image.style.visibility = 'hidden';
  };
}

// Point an actor image at a source, or hide it when there is no source. A visual-less actor (the
// routing persona until its dedicated art lands) yields an empty url, so the element is hidden instead
// of requesting a bogus path or showing another character's image. A real-but-broken source still
// falls back to hideImageOnError. For a non-empty source this is byte-identical to the previous
// `hideImageOnError(img); img.style.visibility = ''; img.src = url` sequence.
function setActorImageSource(image, url) {
  hideImageOnError(image);
  if (!url) {
    image.removeAttribute('src');
    image.style.visibility = 'hidden';
    return;
  }
  image.style.visibility = '';
  image.src = url;
}

function sourceSheetImageUrl({ expression = 'neutral', view = 'standee', characterId = activeCharacterId } = {}) {
  // Resolve the non-selectable actor registries (routing persona `lina` / routing_lumi_<variant> on the routing hub,
  // then the active ホムンクルス) before the selectable roster so each renders its own visual instead of
  // borrowing the roster head.
  const character = routingActorById(characterId)
    ?? atelierActorById(characterId)
    ?? selectableCharacters.find((item) => item.character_id === characterId)
    ?? creatureActorById(characterId)
    ?? activeCharacter();
  const visualSetId = character.visual_set_id;
  if (view === 'standee') return characterSceneStandeeUrl(character);
  if (expression === 'neutral' && character.face_url) return character.face_url;
  // Every actor (roster / creature / routing persona) must carry a visual_set_id; a missing one is a
  // data-integrity break, so fail fast rather than silently blanking or requesting a `/undefined/` face.
  if (!visualSetId) throw new Error(`missing visual_set_id for character face: ${character.character_id}`);
  return `/canonical/character_visual_sets/${visualSetId}/face_emotions/${expression}.jpg`;
}

function renderCharacterDetailStandees(character = activeCharacter()) {
  for (const selector of ['#field-character-detail-standee', '#academy-conversation-session-character-detail-standee']) {
    const image = document.querySelector(selector);
    if (!image) continue;
    setActorImageSource(image, characterSceneStandeeUrl(character));
    image.alt = `${character.display_name ?? character.character_id}の一枚絵`;
  }
}

function splitMessageContent(message, makeNarrationPart) {
  const content = message.content ?? '';
  const parts = [];
  let index = 0;
  const matcher = /（([^（）]+)）|\(([^()]+)\)/g;
  for (const match of content.matchAll(matcher)) {
    const before = content.slice(index, match.index).trim();
    if (before) parts.push({ ...message, content: before });
    const narration = (match[1] ?? match[2] ?? '').trim();
    if (narration) parts.push(makeNarrationPart(narration));
    index = match.index + match[0].length;
  }
  const after = content.slice(index).trim();
  if (after) parts.push({ ...message, content: after });
  return parts.length ? parts : [message];
}

function splitAssistantContent(message) {
  return splitMessageContent(message, (narration) => ({
    role: 'narration',
    content: narration,
    face_emotion_variant_id: 'narration_face',
    expression: 'narration'
  }));
}

function splitPlayerContent(message) {
  return splitMessageContent(message, (narration) => ({
    role: 'player-narration',
    content: narration
  }));
}

function displayMessages(messages) {
  return messages.flatMap((message, messageIndex) => {
    // Preserve an index that already rode in on a split segment so re-feeding a
    // display list (sequential reveal, edit rewind) stays idempotent and each
    // player utterance keeps a single edit button pinned to its original turn.
    const withIndex = (entry) => ({ ...entry, __message_index: entry.__message_index ?? messageIndex });
    if (message.role === 'assistant') return splitAssistantContent(message).map(withIndex);
    if (message.role === 'user') return splitPlayerContent(message).map(withIndex);
    return [withIndex(message)];
  });
}

function completedAssistantPrefix(content) {
  let completedEnd = 0;
  let index = 0;
  const matcher = /（([^（）]+)）|\(([^()]+)\)/g;
  for (const match of content.matchAll(matcher)) {
    if (match.index > index) completedEnd = match.index;
    index = match.index + match[0].length;
    completedEnd = index;
  }
  const nextParen = content.slice(index).search(/[（(]/);
  if (nextParen >= 0) completedEnd = index + nextParen;
  return content.slice(0, completedEnd).trim();
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

// Conversation popup display preferences. The standard cooldown is 500ms and is
// enforced between every popup; presets (chosen in the settings screen) can make
// it shorter. Values are persisted server-side (/api/settings/conversation-popup).
// The chat-bubble pop-in duration is a fixed 220ms, declared once in CSS
// (--bubble-pop-in-duration); it is no longer a preference, so nothing overrides it here.
const CONVERSATION_POPUP_COOLDOWN_DEFAULT_MS = 500;
const conversationPopupSettings = {
  cooldown_ms: CONVERSATION_POPUP_COOLDOWN_DEFAULT_MS
};

function conversationPopupCooldownMs() {
  return conversationPopupSettings.cooldown_ms;
}

function applyConversationPopupSettings(settings) {
  const cooldownMs = Number(settings?.cooldown_ms);
  if (!Number.isFinite(cooldownMs)) {
    throw new Error('conversation popup settings must include numeric cooldown_ms');
  }
  conversationPopupSettings.cooldown_ms = cooldownMs;
}
function hasConversationEditItem(inventory = currentInventory) {
  return (inventory?.items ?? []).some((item) => item.item_id === CONVERSATION_EDIT_ITEM_ID && Number(item.quantity ?? 0) > 0);
}


function createMessageRows(displayList, popFromDisplayIndex, allowEdit) {
  return displayList.map((message, index) => {
    const row = document.createElement('article');
    row.className = `chat-message ${message.role === 'user' ? 'player-message' : message.role === 'player-narration' ? 'player-narration-message' : message.role === 'narration' ? 'narration-message' : 'character-message'}`;
    if (popFromDisplayIndex >= 0 && index >= popFromDisplayIndex && message.role !== 'user' && message.role !== 'player-narration') row.classList.add('pop-in');
    if (message.role !== 'user' && message.role !== 'narration' && message.role !== 'player-narration') {
      // Carry the speaker identity on the row so a multi-speaker consumer (the 談話室 group stage) can resolve
      // WHICH participant a clicked bubble belongs to. Single-speaker consumers read the same id they render the
      // face/name from, so this is inert for them (byte-equivalent behaviour; only a data-* attribute is added).
      row.dataset.characterId = message.character_id ?? activeCharacterId;
      // The row also carries the expression its face shows, so a consumer (the conversation layer) reads the
      // expression from the row's value rather than from the face's accessible name.
      const expression = message.expression ?? 'neutral';
      row.dataset.expression = expression;
      const faceFrame = document.createElement('div');
      faceFrame.className = 'message-face';
      const face = document.createElement('img');
      face.alt = `${message.character_name ?? activeCharacter().display_name} ${message.face_emotion_variant_id ?? 'face_neutral'}`;
      setActorImageSource(face, sourceSheetImageUrl({ expression, view: 'face', characterId: message.character_id ?? activeCharacterId }));
      faceFrame.append(face);
      row.append(faceFrame);
    }
    const bubble = document.createElement('div');
    bubble.className = 'message-bubble';
    if (message.role !== 'user' && message.role !== 'narration' && message.role !== 'player-narration') {
      const name = document.createElement('strong');
      name.className = 'message-speaker';
      name.textContent = message.character_name ?? activeCharacter().display_name;
      bubble.append(name);
    }
    const text = document.createElement('p');
    text.textContent = message.content ?? '';
    bubble.append(text);
    // A split player utterance (speech + ground text) becomes several rows that
    // share one __message_index; the edit affordance belongs once, on the tail
    // row, so a narration-only turn still keeps its button.
    const isPlayerUtteranceTail = (message.role === 'user' || message.role === 'player-narration')
      && (index === displayList.length - 1 || displayList[index + 1].__message_index !== message.__message_index);
    if (allowEdit && isPlayerUtteranceTail && hasConversationEditItem()) {
      const editButton = document.createElement('button');
      editButton.type = 'button';
      editButton.className = 'message-edit-button';
      editButton.textContent = '編集';
      editButton.addEventListener('click', () => editUserMessageAtIndex(message.__message_index).catch(reportError));
      bubble.append(editButton);
    }
    row.append(bubble);
    return row;
  });
}

function renderMessageStream(messages = messageHistory, { popFromDisplayIndex = -1 } = {}) {
  messageHistory = messages;
  const displayList = displayMessages(messages);
  for (const selector of ['#academy-conversation-session-message-stream']) {
    const stream = document.querySelector(selector);
    if (!stream) continue;
    stream.replaceChildren(...createMessageRows(displayList, popFromDisplayIndex, true));
    stream.scrollTop = stream.scrollHeight;
  }
}

function messagesFromConversation(conversation) {
  // System messages (e.g. stage-move narration / guidance) are LLM context and
  // are persisted in the conversation, but they are not chat bubbles, so they are
  // dropped from the displayed stream.
  return (conversation?.messages ?? []).filter((message) => message.role === 'user' || message.role === 'assistant').map((message) => {
    if (message.role === 'assistant') {
      return {
        role: 'assistant',
        character_id: activeCharacterId,
        character_name: activeCharacter().display_name,
        content: message.content ?? '',
        face_emotion_variant_id: message.face_emotion_variant_id ?? 'face_neutral',
        expression: message.expression ?? 'neutral'
      };
    }
    return { role: 'user', content: message.content ?? '' };
  });
}

function writeDebugLog(_value) {
  // Debug result panel was removed from the screen.
}

function showProcessingToast() {
  const toast = document.querySelector('#conversation-processing-toast');
  if (!toast) return;
  toast.classList.add('visible');
  if (processingToastTimer) clearTimeout(processingToastTimer);
  processingToastTimer = setTimeout(() => {
    toast.classList.remove('visible');
    processingToastTimer = null;
  }, 1000);
}

function showEconomyMessage(message) {
  const box = document.querySelector('#economy-message-box');
  if (!box) return;
  box.textContent = message;
  box.classList.add('visible');
  if (economyMessageTimer) clearTimeout(economyMessageTimer);
  economyMessageTimer = setTimeout(() => {
    box.classList.remove('visible');
    economyMessageTimer = null;
  }, 1800);
}

function setAcademyMapNavigationDisabled(disabled) {
  const tab = document.querySelector('[data-screen="academy-map"]');
  if (!tab) return;
  tab.disabled = disabled;
  tab.setAttribute('aria-disabled', disabled ? 'true' : 'false');
}

function setConversationControlsDisabled(disabled) {
  for (const selector of ['#academy-conversation-session-run-conversation', '#academy-conversation-session-end-conversation', '#academy-conversation-session-player-input']) {
    const control = document.querySelector(selector);
    if (control) control.disabled = disabled;
  }
}

function conversationProvider() {
  return 'lmstudio';
}

function conversationShouldAutoEnd(result) {
  return result?.conversation?.conversation_continuation?.continue_conversation === false;
}

async function autoEndConversationAfterFinalReply(result) {
  if (!conversationShouldAutoEnd(result)) return false;
  setStreamStatus('reflection: auto-ending after final reply');
  await sleep(FINAL_REPLY_AUTO_END_DELAY_MS);
  await endConversation({ allowDuringInFlight: true });
  return true;
}

function renderConversationResult(result, { revealAssistant = false } = {}) {
  const previousDisplayCount = displayMessages(messageHistory).length;
  renderMessageStream(messagesFromConversation(result.conversation), {
    popFromDisplayIndex: revealAssistant ? previousDisplayCount : -1
  });
  writeDebugLog({
    conversation_id: result.conversation.id,
    validator: result.validator,
    state: result.state
  });
}

function commitConversationResultState(result) {
  messageHistory = messagesFromConversation(result.conversation);
}

async function renderConversationResultSequentially(result) {
  const previousDisplay = displayMessages(messageHistory);
  const fullMessages = messagesFromConversation(result.conversation);
  const fullDisplay = displayMessages(fullMessages);
  const newSegments = fullDisplay.slice(previousDisplay.length);

  writeDebugLog({
    conversation_id: result.conversation.id,
    validator: result.validator,
    state: result.state
  });

  for (let index = 0; index < newSegments.length; index += 1) {
    renderMessageStream([
      ...previousDisplay,
      ...newSegments.slice(0, index + 1)
    ], { popFromDisplayIndex: previousDisplay.length + index });
    await sleep(conversationPopupCooldownMs());
  }

  // Keep the revealed DOM in place after the last segment. Replacing it with
  // freshly split rows here subtly shifts character and narration bubbles at
  // the moment the reply finishes; only the canonical state needs to switch
  // back from display segments to raw conversation messages.
  commitConversationResultState(result);
}

async function ensureOpeningUtterance({ characterId = activeCharacterId, onAssistantStreamStart = null } = {}) {
  if (messageHistory.length > 0) return;
  const provider = conversationProvider();
  setStreamStatus(provider === 'lmstudio' ? 'opening: generating with LM Studio' : 'opening: generating');
  if (provider === 'lmstudio') {
    await runOpeningConversationStream({ characterId, provider, onAssistantStreamStart });
  } else {
    onAssistantStreamStart?.();
    const result = await postJson('/api/conversation/opening', { character_id: characterId, provider });
    await renderConversationResultSequentially(result);
  }
  setStreamStatus('opening: completed');
  await Promise.all([refreshPrompt(), refreshRecordStatus()]);
}

let lastStreamStatusAt = 0;
let pendingStreamStatus = null;
let streamStatusFrame = null;

function setConversationStatus(message, { tone = '' } = {}) {
  const status = document.querySelector('#academy-conversation-session-status');
  if (!status) return;
  const text = String(message ?? '').trim();
  if (!text) {
    status.hidden = true;
    status.textContent = '';
    delete status.dataset.tone;
    return;
  }
  status.hidden = false;
  status.textContent = text;
  if (tone) status.dataset.tone = tone;
  else delete status.dataset.tone;
}

function setStreamStatus(text, { immediate = false, tone = '' } = {}) {
  const normalized = String(text ?? '').trim();
  pendingStreamStatus = normalized;
  if (immediate) {
    lastStreamStatusAt = Date.now();
    if (normalized) setConversationStatus(normalized, { tone });
    return;
  }
  if (streamStatusFrame) cancelAnimationFrame(streamStatusFrame);
  streamStatusFrame = requestAnimationFrame(() => {
    streamStatusFrame = null;
    lastStreamStatusAt = Date.now();
  });
}


function playerParameterInput({ group, key, label, value }) {
  const wrapper = document.createElement('label');
  wrapper.className = 'parameter-input';
  wrapper.textContent = label;
  const input = document.createElement('input');
  input.type = 'number';
  input.min = '0';
  input.max = '100';
  input.step = '1';
  input.value = String(value?.value ?? value ?? 0);
  input.dataset.parameterGroup = group;
  input.dataset.parameterKey = key;
  wrapper.append(input);
  return wrapper;
}

function renderPlayerParametersEditor(parameters = {}) {
  const container = document.querySelector('#player-parameters-editor');
  const magic = document.createElement('fieldset');
  const magicLegend = document.createElement('legend');
  magicLegend.textContent = 'プレイヤーの魔法習熟度（0〜100）';
  magic.append(magicLegend, ...magicParameterDefinitions.map(([key, label]) => playerParameterInput({ group: 'magic', key, label, value: parameters.magic?.[key] })));
  const abilities = document.createElement('fieldset');
  const abilitiesLegend = document.createElement('legend');
  abilitiesLegend.textContent = 'プレイヤーの基礎パラメーター（0〜100）';
  abilities.append(abilitiesLegend, ...abilityParameterDefinitions.map(([key, label]) => playerParameterInput({ group: 'abilities', key, label, value: parameters.abilities?.[key] })));
  container.replaceChildren(magic, abilities);
}

function setPlayerParameterGroupToValue(group, value) {
  const normalized = Math.max(0, Math.min(100, Number(value)));
  document.querySelectorAll(`#player-parameters-editor input[data-parameter-group="${group}"]`).forEach((input) => {
    input.value = String(normalized);
  });
}

function wirePlayerParameterPresets() {
  document.querySelectorAll('[data-parameter-preset-group][data-parameter-preset-value]').forEach((button) => {
    button.addEventListener('click', () => {
      const presetValue = Number(button.dataset.parameterPresetValue);
      if (!PLAYER_PARAMETER_PRESET_VALUES.includes(presetValue)) return;
      setPlayerParameterGroupToValue(button.dataset.parameterPresetGroup, presetValue);
    });
  });
}

function collectPlayerParameters() {
  const parameters = { magic: {}, abilities: {} };
  document.querySelectorAll('#player-parameters-editor input[data-parameter-group]').forEach((input) => {
    parameters[input.dataset.parameterGroup][input.dataset.parameterKey] = Number(input.value || 0);
  });
  return parameters;
}

function renderParameterGroup(title, definitions, values, createLabel) {
  const section = document.createElement('section');
  section.className = 'character-parameter-section';
  const grid = document.createElement('div');
  grid.className = 'character-parameter-group';
  const items = definitions.map(([key, shortLabel]) => {
    const stat = values?.[key];
    const value = Math.max(0, Math.min(100, Number(stat?.value ?? stat ?? 0)));
    const item = document.createElement('div');
    item.className = 'character-parameter-item';
    const label = createLabel(key, shortLabel);
    const meter = document.createElement('meter');
    meter.min = 0;
    meter.max = 100;
    meter.value = value;
    // Low/high/optimum split the bar into weak/mid/strong tiers so the fill
    // color reflects the value level (see the meter pseudo-element styles).
    meter.low = 33;
    meter.high = 66;
    meter.optimum = 100;
    const number = document.createElement('strong');
    number.textContent = String(value);
    item.append(label, meter, number);
    return item;
  });
  grid.replaceChildren(...items);
  const heading = document.createElement('h4');
  heading.textContent = title;
  section.append(heading, grid);
  return section;
}

// The two parameter groups (魔法習熟度 / 基礎能力) as detached sections, shared by the player / character parameter
// renderers below and by the routing hub self / buddy drawers (which append them into a titled sub-section instead
// of replacing a whole container). The player world state and a character profile carry the same {magic, abilities}
// shape, so one builder serves both. Each group is its word heading over its rows. createLabel(key, shortLabel) draws
// each parameter's name: words (parameterTextLabel) everywhere but the night bands (.night-band — the hub drawers, the
// hero's band on the daytime conversation and the academy map, and the 相手 window), which show the sigil alone
// (abilitySigilLabel).
function buildParameterGroups(parameters = {}, createLabel) {
  return [
    renderParameterGroup('魔法習熟度', magicParameterDefinitions, parameters.magic, createLabel),
    renderParameterGroup('基礎能力', abilityParameterDefinitions, parameters.abilities, createLabel)
  ];
}

// A parameter's name as words (the academy / training / dungeon meters).
function parameterTextLabel(_key, shortLabel) {
  const label = document.createElement('span');
  label.textContent = shortLabel;
  return label;
}

function renderCharacterParametersInto(character, containerSelector) {
  const container = document.querySelector(containerSelector);
  if (!container) return;
  // Sanrin creatures carry the same magic/ability stats as academy students and
  // render identical meters; their parameters arrive on the backend creature
  // summary, so missing values fail fast upstream rather than being zero-filled here.
  container.replaceChildren(...buildParameterGroups(character.parameters, parameterTextLabel));
}

function renderInteractionCharacterParameters(character) {
  renderCharacterParametersInto(character, '#academy-conversation-session-character-parameters');
}

function renderTrainingPlayerParameters(parameters = {}) {
  renderPlayerParametersInto(parameters, '#training-player-parameters');
  renderAcademyTrainingParameters(parameters);
  renderPlayerParametersInto(parameters, '#academy-room-player-parameters');
}

// 鍛錬の上の一列: 主人公の十一の値を、露台の能力の紋と値で並べる（魔法習熟度の六つ、基礎能力の五つの順）。値の無い能力が来るまでは
// 何も置かない（起動の前の空の値）。
function renderAcademyTrainingParameters(parameters) {
  const strip = document.querySelector('#academy-training-player-parameters');
  if (!parameters.magic || !parameters.abilities) {
    strip.replaceChildren();
    return;
  }
  const cells = [
    ...magicParameterDefinitions.map(([key, label]) => [key, label, parameters.magic[key]]),
    ...abilityParameterDefinitions.map(([key, label]) => [key, label, parameters.abilities[key]])
  ].map(([key, label, stat]) => {
    if (!Number.isFinite(stat?.value)) throw new Error(`training: the player parameter ${key} has no value, got ${JSON.stringify(stat)}`);
    const cell = document.createElement('span');
    cell.className = 'academy-training-param';
    cell.setAttribute('role', 'img');
    cell.setAttribute('aria-label', `${label} ${stat.value}`);
    const value = document.createElement('span');
    value.textContent = String(stat.value);
    cell.append(shelfSigil(key), value);
    return cell;
  });
  strip.replaceChildren(...cells);
}

function renderPlayerParametersInto(parameters = {}, containerSelector) {
  const container = document.querySelector(containerSelector);
  if (!container) return;
  container.replaceChildren(...buildParameterGroups(parameters, parameterTextLabel));
}

// Build the 素材メタ badges (属性ラベル + T<tier>) for a dungeon-material inventory item, or null for a
// non-material item. decorateInventory exposes element (a 6-attr key) and tier (1..4) on dungeon materials
// ONLY, always as a pair derived from the same catalog id; every other item exposes NEITHER. Presence of the
// pair is the material discriminant — its absence is a legitimate "not a material", not a fallback, so a
// non-material item renders unchanged. A half-present pair or an out-of-range tier is a broken enrich contract
// and surfaces (fail-fast, no silent skip). The badge container class is surface-scoped so each ledger tones
// the badges in its own token layer; workshopElementLabel is the shared 6-element vocabulary (fail-fast on an
// unknown element key).
function buildInventoryMaterialMeta(item, className) {
  const hasElement = item.element !== undefined;
  const hasTier = item.tier !== undefined;
  if (!hasElement && !hasTier) return null;
  if (hasElement !== hasTier) {
    throw new Error(`inventory material meta requires both element and tier or neither, got ${JSON.stringify(item)}`);
  }
  if (!Number.isInteger(item.tier) || item.tier < 1 || item.tier > 4) {
    throw new Error(`inventory material tier must be an integer in 1..4, got ${JSON.stringify(item)}`);
  }
  const meta = document.createElement('div');
  meta.className = className;
  const element = document.createElement('span');
  element.className = `${className}-element`;
  element.textContent = `属性${workshopElementLabel(item.element)}`;
  const tier = document.createElement('span');
  tier.className = `${className}-tier`;
  tier.textContent = `T${item.tier}`;
  meta.append(element, tier);
  return meta;
}

function renderAcademyRoomInventoryItems(inventory = currentInventory) {
  const list = document.querySelector('#academy-room-inventory-items');
  const count = document.querySelector('#academy-room-item-count');
  if (!list || !count) return;
  const items = inventory.items ?? [];
  count.textContent = `${items.length}種類`;
  if (!items.length) {
    const empty = document.createElement('p');
    empty.className = 'economy-empty';
    empty.textContent = '所持品はありません。';
    list.replaceChildren(empty);
    return;
  }
  list.replaceChildren(...items.map((item) => {
    const row = document.createElement('article');
    row.className = 'academy-room-item-row';
    const title = document.createElement('strong');
    title.textContent = item.name ?? item.item_id;
    const quantity = document.createElement('span');
    quantity.className = 'academy-room-item-quantity';
    quantity.textContent = `×${Number(item.quantity ?? 0).toLocaleString('ja-JP')}`;
    const description = document.createElement('p');
    description.textContent = item.description ?? '';
    row.append(title, quantity);
    const materialMeta = buildInventoryMaterialMeta(item, 'academy-room-item-materia');
    if (materialMeta) row.append(materialMeta);
    row.append(description);
    if (item.stat_effect) {
      const use = document.createElement('button');
      use.type = 'button';
      use.className = 'academy-room-item-use-button';
      use.textContent = '1個使う';
      use.addEventListener('click', () => useInventoryItem(item.item_id, 1).catch(reportError));
      const useAll = document.createElement('button');
      useAll.type = 'button';
      useAll.className = 'academy-room-item-use-button';
      useAll.textContent = '全部使う';
      useAll.addEventListener('click', () => useInventoryItem(item.item_id, item.quantity).catch(reportError));
      row.append(use, useAll);
    }
    return row;
  }));
}

function renderAcademyRoomBuddy() {
  const card = document.querySelector('#academy-room-buddy-card');
  const emptyContainer = document.querySelector('#academy-room-buddy-empty');
  if (!card || !emptyContainer) return;
  const buddyId = selectedAcademyBuddyCharacterId();
  const buddy = selectableCharacters.find((character) => character.character_id === buddyId);
  if (!buddy) {
    const empty = document.createElement('p');
    empty.className = 'panel-help';
    empty.textContent = '現在のバディーはいません。';
    card.classList.add('is-empty');
    emptyContainer.replaceChildren();
    card.replaceChildren(empty);
    return;
  }
  card.classList.remove('is-empty');
  emptyContainer.replaceChildren();
  const image = document.createElement('img');
  image.src = buddy.selection_icon_url ?? buddy.face_url ?? sourceSheetImageUrl({ characterId: buddy.character_id, view: 'face' });
  image.alt = `${buddy.display_name ?? buddy.character_id}の顔`;
  const body = document.createElement('div');
  const name = document.createElement('strong');
  name.textContent = buddy.display_name ?? buddy.character_id;
  const meta = document.createElement('small');
  meta.textContent = [buddy.school_year, buddy.club].filter(Boolean).join(' / ') || buddy.character_id;
  body.append(name, meta);
  card.replaceChildren(image, body);
}

function renderAcademyRoomEnemies() {
  const enemyIds = selectedAcademyEnemyCharacterIds();
  const count = document.querySelector('#academy-room-enemy-count');
  const list = document.querySelector('#academy-room-enemy-list');
  if (!list || !count) return;
  const enemies = selectableCharacters.filter((character) => enemyIds.has(character.character_id));
  count.textContent = `${enemies.length}人`;
  if (!enemies.length) {
    const empty = document.createElement('p');
    empty.className = 'panel-help';
    empty.textContent = '現在のエネミーはいません。';
    list.replaceChildren(empty);
    return;
  }
  list.replaceChildren(...enemies.map((enemy) => {
    const row = document.createElement('div');
    row.className = 'academy-room-enemy-row';
    const image = document.createElement('img');
    image.src = enemy.selection_icon_url ?? enemy.face_url ?? sourceSheetImageUrl({ characterId: enemy.character_id, view: 'face' });
    image.alt = `${enemy.display_name ?? enemy.character_id}の顔`;
    const body = document.createElement('div');
    const name = document.createElement('strong');
    name.textContent = enemy.display_name ?? enemy.character_id;
    const meta = document.createElement('small');
    meta.textContent = [enemy.school_year, enemy.club].filter(Boolean).join(' / ') || enemy.character_id;
    body.append(name, meta);
    row.append(image, body);
    return row;
  }));
}

function academyRoomDisplayedWeekNumber(state = currentRuntimeState) {
  return Math.max(1, Number(state?.elapsed_weeks ?? 0) + 1);
}

function academyRoomDisplayedWeekLabel(state = currentRuntimeState) {
  return `第${academyRoomDisplayedWeekNumber(state)}週`;
}

function renderAcademyRoomScreen() {
  const weekElement = document.querySelector('#academy-room-week');
  if (weekElement) weekElement.textContent = academyRoomDisplayedWeekLabel(currentRuntimeState);
  document.querySelector('#academy-room-money').textContent = moneyText(currentInventory.money);
  renderTrainingPlayerParameters(currentWorld?.player_parameters ?? {});
  renderAcademyRoomBuddy();
  renderAcademyRoomEnemies();
  renderAcademyRoomInventoryItems(currentInventory);
  setAcademyRoomActionButtonsDisabled(academyRoomActionInFlight);
}

function trainingDayForProgress(progress = currentTrainingProgress) {
  if (progress?.next_day && Number(progress.actions_used ?? 0) > 0 && progress.completed !== true) return progress.next_day;
  const used = Number(progress?.actions_used ?? 0);
  const index = progress?.completed === true ? TRAINING_ACTION_LIMIT - 1 : Math.max(0, Math.min(TRAINING_ACTION_LIMIT - 1, used));
  return trainingWeekdays[index] ?? trainingWeekdays[0];
}

function renderTrainingWeekday(day = currentTrainingDay) {
  currentTrainingDay = day ?? trainingWeekdays[0];
  for (const selector of ['#training-weekday', '#academy-training-weekday']) {
    const element = document.querySelector(selector);
    if (!element) continue;
    element.textContent = `${currentTrainingDay.name}（${currentTrainingDay.element_label}）`;
    element.dataset.element = currentTrainingDay.element;
  }
  renderAcademyTrainingDay(currentTrainingDay);
}

// 鍛錬の右上の曜日: 曜日の属性の紋と曜日の名。曜日と同じ属性の鍛錬の板が灯る（曜日の重なりで効き目が倍になる決まりを灯りで示す）。
function renderAcademyTrainingDay(day) {
  const dayMark = document.querySelector('#academy-training-day');
  dayMark.setAttribute('aria-label', `${day.name}（${day.element_label}）`);
  const name = document.createElement('span');
  name.textContent = day.name;
  dayMark.replaceChildren(shelfSigil(day.element), name);
  for (const drill of document.querySelectorAll('#academy-training-options .academy-training-drill')) {
    drill.dataset.today = String(drill.dataset.trainingElement === day.element);
  }
}

// 鍛錬の右上の残りの回数: 回数の上限だけ菱形を並べ、残っている分を灯す。
function renderAcademyTrainingRemaining(progress = currentTrainingProgress) {
  const remaining = Math.max(0, Math.min(progress.actions_limit, progress.remaining_actions));
  fillShelfDiamonds(document.querySelector('#academy-training-remaining'), remaining, progress.actions_limit, '残り');
}

function renderTrainingProgress(progress = currentTrainingProgress) {
  currentTrainingProgress = {
    actions_used: Number(progress?.actions_used ?? 0),
    actions_limit: Number(progress?.actions_limit ?? TRAINING_ACTION_LIMIT),
    remaining_actions: Number(progress?.remaining_actions ?? TRAINING_ACTION_LIMIT),
    completed: progress?.completed === true,
    next_day: progress?.next_day ?? null
  };
  document.querySelectorAll('#training-progress, #academy-training-progress').forEach((element) => {
    element.textContent = `行動 ${currentTrainingProgress.actions_used} / ${currentTrainingProgress.actions_limit}`;
    element.classList.toggle('completed', currentTrainingProgress.completed);
  });
  renderTrainingWeekday(trainingDayForProgress(currentTrainingProgress));
  renderAcademyTrainingRemaining(currentTrainingProgress);
}

function triggerTrainingEffect(result) {
  const overlays = document.querySelectorAll('#training-effect-overlay, #academy-training-effect-overlay');
  if (!overlays.length) return Promise.resolve();
  const changedLabels = (result.effects ?? [])
    .filter((effect) => effect.amount !== 0)
    .map((effect) => `${effect.label}${effect.amount > 0 ? '+' : ''}${effect.amount}${effect.weekday_bonus ? '（曜日ボーナス）' : ''}`);
  const message = changedLabels.length ? changedLabels.join(' / ') : '集中したけれど、今回は変化なし';
  overlays.forEach((overlay) => {
    overlay.textContent = message;
    overlay.classList.remove('visible');
    void overlay.offsetWidth;
    overlay.classList.add('visible');
  });
  trainingEffectInFlight = true;
  setTrainingButtonsDisabled(true);
  if (trainingEffectTimer) clearTimeout(trainingEffectTimer);
  return new Promise((resolve) => {
    trainingEffectTimer = setTimeout(() => {
      overlays.forEach((overlay) => overlay.classList.remove('visible'));
      trainingEffectInFlight = false;
      setTrainingButtonsDisabled(false);
      trainingEffectTimer = null;
      resolve();
    }, 1000);
  });
}

// The 終了演出 (day-transition overlay) text. A mid-week action advances to the next weekday and shows the
// per-day line. The week's final action has no next day (training backend: next_day is null exactly when
// completed), so its copy follows the same canonical mode signal routeAfterCompletedAcademyTraining routes on
// (post_content_screen): 'interaction' (routing) has no overlay at all (null) — the return path rises over the
// training ground's art at once — and 'academy-map' (loop) passes without words. A missing/unknown signal fail-fasts.
function trainingDayTransitionMessage(result) {
  const day = result.training_day;
  const nextDay = result.training_progress?.next_day;
  if (nextDay) {
    return `${day?.name ?? '今日'}の訓練が終わり、夜が明けて${nextDay.name}へ。`;
  }
  const postContentScreen = result.post_content_screen;
  if (postContentScreen === 'interaction') {
    return null;
  }
  if (postContentScreen === 'academy-map') {
    return '';
  }
  throw new Error(`training day transition: unexpected post_content_screen ${JSON.stringify(postContentScreen)}`);
}

function triggerTrainingDayTransition(result) {
  const overlays = document.querySelectorAll('#training-day-transition, #academy-training-day-transition');
  if (!overlays.length) return Promise.resolve();
  const message = trainingDayTransitionMessage(result);
  if (message === null) return Promise.resolve();
  overlays.forEach((overlay) => {
    overlay.textContent = message;
    overlay.classList.remove('visible');
    void overlay.offsetWidth;
    overlay.classList.add('visible');
  });
  trainingDayTransitionInFlight = true;
  setTrainingButtonsDisabled(true);
  return new Promise((resolve) => {
    setTimeout(() => {
      overlays.forEach((overlay) => overlay.classList.remove('visible'));
      trainingDayTransitionInFlight = false;
      setTrainingButtonsDisabled(false);
      resolve();
    }, 2000);
  });
}

function resetTrainingResultDisplay() {
  const fallbackTextBySelector = {
    '#training-result': 'まだトレーニングしていません。'
  };
  Object.entries(fallbackTextBySelector).forEach(([selector, text]) => {
    const container = document.querySelector(selector);
    if (container) container.textContent = text;
  });
  renderAcademyTrainingRemaining(currentTrainingProgress);
  document.querySelectorAll('#training-effect-overlay, #academy-training-effect-overlay, #training-day-transition, #academy-training-day-transition')
    .forEach((overlay) => overlay.classList.remove('visible'));
}

function setTrainingButtonsDisabled(disabled) {
  document.querySelectorAll('.training-option-card, .academy-training-drill').forEach((button) => {
    button.disabled = disabled || trainingActionInFlight || trainingEffectInFlight || trainingDayTransitionInFlight;
  });
}

function setAcademyRoomActionButtonsDisabled(disabled) {
  document.querySelectorAll('#academy-room-start-training, #academy-room-skip-training, #academy-room-open-load').forEach((button) => {
    button.disabled = disabled || academyRoomActionInFlight;
  });
}

function renderTrainingResult(result) {
  const containers = document.querySelectorAll('#training-result');
  if (!containers.length) return;
  if (!result) {
    containers.forEach((container) => {
      container.textContent = 'まだトレーニングしていません。';
    });
    return;
  }
  const buildResultFragment = () => {
    const fragment = document.createDocumentFragment();
    const title = document.createElement('h4');
    title.textContent = `${result.training.name} の結果`;
    const list = document.createElement('div');
    list.className = 'training-effect-list';
    const rows = result.effects.map((effect) => {
      const row = document.createElement('p');
      row.className = `training-effect ${effect.direction === 'decrease' ? 'decrease' : effect.amount > 0 ? 'increase' : 'no-change'}`;
      const chance = Math.round(Number(effect.chance ?? 0) * 100);
      if (effect.direction === 'decrease') {
        row.textContent = `${effect.label}: ${effect.before} → ${effect.after} (${chance}%で-1 / ${effect.amount < 0 ? '-1' : '変化なし'})`;
      } else {
        const bonus = effect.weekday_bonus ? ` / ${effect.bonus_multiplier}倍曜日ボーナス` : '';
        row.textContent = `${effect.label}: ${effect.before} → ${effect.after} (${chance}%で+1${bonus} / ${effect.amount > 0 ? `+${effect.amount}` : '変化なし'})`;
      }
      return row;
    });
    list.replaceChildren(...rows);
    fragment.append(title, list);
    return fragment;
  };
  containers.forEach((container) => container.replaceChildren(buildResultFragment()));
}

function createTrainingOptionCard(training) {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'training-option-card';
  button.dataset.trainingElement = training.element;
  const cardImage = document.createElement('img');
  cardImage.className = 'training-card-image';
  cardImage.src = training.cardImageUrl;
  cardImage.alt = `${training.name}のイメージ`;
  cardImage.loading = 'lazy';
  const body = document.createElement('span');
  body.className = 'training-card-body';
  const name = document.createElement('strong');
  name.textContent = training.name;
  const preview = document.createElement('span');
  preview.className = 'training-effect-preview';
  preview.textContent = training.effectPreview;
  const weekdayBonus = document.createElement('span');
  weekdayBonus.className = 'training-weekday-bonus';
  weekdayBonus.textContent = training.weekdayBonusLabel;
  const description = document.createElement('small');
  description.textContent = training.description;
  body.append(name, preview, weekdayBonus, description);
  button.append(cardImage, body);
  button.disabled = trainingActionInFlight || trainingEffectInFlight || trainingDayTransitionInFlight;
  button.addEventListener('click', () => runTraining(training.id).catch(reportError));
  return button;
}

// 鍛錬場の床の板: 鍛錬の絵と右下の属性の紋、その下の名。板そのものが鍛錬を始める釦。
function createAcademyTrainingDrill(training) {
  const drill = document.createElement('button');
  drill.type = 'button';
  drill.className = 'academy-training-drill';
  drill.dataset.trainingElement = training.element;
  drill.dataset.today = String(training.element === currentTrainingDay.element);
  drill.setAttribute('aria-label', training.name);
  const plate = document.createElement('span');
  plate.className = 'academy-training-plate';
  plate.append(shelfImage('academy-training-plate-image', training.cardImageUrl), shelfSigil(training.element));
  const name = document.createElement('span');
  name.className = 'shelf-label-name shelf-ellipse';
  name.textContent = training.name;
  drill.append(plate, name);
  drill.disabled = trainingActionInFlight || trainingEffectInFlight || trainingDayTransitionInFlight;
  drill.addEventListener('click', () => runTraining(training.id).catch(reportError));
  return drill;
}

function renderTrainingScreen() {
  const trainingList = document.querySelector('#training-options');
  if (trainingList) trainingList.replaceChildren(...trainingOptions.map((training) => createTrainingOptionCard(training)));
  document.querySelector('#academy-training-options').replaceChildren(...trainingOptions.map((training) => createAcademyTrainingDrill(training)));
  renderTrainingProgress(currentTrainingProgress);
  renderTrainingPlayerParameters(currentWorld?.player_parameters ?? {});
}

async function runTraining(trainingId) {
  if (trainingActionInFlight || trainingEffectInFlight || trainingDayTransitionInFlight) {
    showProcessingToast();
    return;
  }
  trainingActionInFlight = true;
  setTrainingButtonsDisabled(true);
  try {
    const result = await postJson('/api/training/run', { training_id: trainingId });
    currentWorld = result.world;
    currentRuntimeState = result.state ?? currentRuntimeState;
    renderPlayerParametersEditor(currentWorld.player_parameters ?? {});
    renderTrainingPlayerParameters(currentWorld.player_parameters ?? {});
    renderTrainingProgress(result.training_progress);
    renderTrainingResult(result);
    await triggerTrainingEffect(result);
    await refreshPrompt();
    await triggerTrainingDayTransition(result);
    if (result.training_progress?.completed) {
      await routeAfterCompletedAcademyTraining(result.post_content_screen);
    }
  } finally {
    trainingActionInFlight = false;
    setTrainingButtonsDisabled(false);
  }
}

// ── 棚の画面（購買・採取・鍛錬）が分け合う部品 ─────────────────────────────────────────────────────────────────
// 三つの画面は一つの層の組み方を分け合う: 地は入るときの待ちと同じ絵を画面いっぱいに敷き（setUpShelfScreens）、左上に場所の名、
// 右上に値と戻る紋。選ぶものは「円か板＋その下の名と値」の一つの部品で、部品そのものか、その右下の紋が行いの釦になる。数は菱形の
// 印、効く能力・属性・主人公の値は露台の紋で表す。字はすべて夜の楕円（.shelf-ellipse）の上に置き、使い方を説明する字は置かない。
const SHELF_SVG_NAMESPACE = 'http://www.w3.org/2000/svg';
const SHOP_SATCHEL_ICON_URL = '/canonical/academy_map/icons/inventory.png';

// 露台の紋（hubTerraceSigils.svg の symbol・起動時に #terrace-sigil-symbols へ写したもの）を中身ごと写した inline の SVG。<use> では
// 購買の銀の灯りへの塗り替えが中まで届かないので写す。読み上げの名は押す部品の側に持たせる。
function shelfSigil(name) {
  const symbol = document.getElementById(`sigil-${name}`);
  if (!(symbol instanceof SVGSymbolElement)) throw new Error(`shelf screens: no sigil symbol ${JSON.stringify(name)}`);
  const svg = document.createElementNS(SHELF_SVG_NAMESPACE, 'svg');
  svg.setAttribute('viewBox', symbol.getAttribute('viewBox'));
  svg.setAttribute('class', `shelf-sigil-mark shelf-sigil-${name}`);
  svg.setAttribute('aria-hidden', 'true');
  svg.setAttribute('focusable', 'false');
  for (const child of symbol.childNodes) svg.append(child.cloneNode(true));
  return svg;
}

function shelfImage(className, src) {
  const image = document.createElement('img');
  image.className = className;
  image.src = src;
  image.alt = '';
  image.setAttribute('aria-hidden', 'true');
  image.draggable = false;
  return image;
}

// 数の印: 上限の数だけ菱形を並べ、残りの分を灯す（鍛錬の残りの回数・採取の在庫）。読み上げの名は「<名> 残り / 上限」。
function fillShelfDiamonds(row, left, max, name) {
  if (!Number.isInteger(left) || !Number.isInteger(max) || left < 0 || left > max) {
    throw new Error(`shelf screens: ${name} ${JSON.stringify({ left, max })} is not a count within its limit`);
  }
  row.setAttribute('aria-label', `${name} ${left} / ${max}`);
  row.replaceChildren(...Array.from({ length: max }, (_, index) => {
    const diamond = document.createElement('span');
    diamond.className = 'shelf-diamond';
    diamond.dataset.state = index < left ? 'left' : 'spent';
    return diamond;
  }));
  return row;
}

// 品の印: 揺り籠の品は揺り籠の印（品の絵はまだ配られていない）、能力に効く品はその能力の紋、絵を持つ品はその絵。どれでもない品は
// 印を持たず、円が空のまま出る。
function shelfItemMarks(item) {
  if (STAR_CRADLE_SEED_ITEM_PATTERN.test(item.item_id)) return [shelfImage('shelf-item-image', STAR_CRADLE_ICON_URL)];
  if (item.stat_effect) return [shelfSigil(item.stat_effect.key)];
  if (item.icon) return [shelfImage('shelf-item-image', item.icon)];
  return [];
}

// 選ぶものの下の名と値（夜の楕円の上）。
function shelfLabel(name, value) {
  const label = document.createElement('span');
  label.className = 'shelf-label shelf-ellipse';
  const nameText = document.createElement('span');
  nameText.className = 'shelf-label-name';
  nameText.textContent = name;
  const valueText = document.createElement('span');
  valueText.className = 'shelf-label-value';
  valueText.textContent = value;
  label.append(nameText, valueText);
  return label;
}

function moneyText(value) {
  return `${Number(value ?? 0).toLocaleString('ja-JP')} G`;
}

function renderInventory(inventory = currentInventory) {
  const hadConversationEditItem = hasConversationEditItem(currentInventory);
  currentInventory = inventory;
  const hasCurrentConversationEditItem = hasConversationEditItem(currentInventory);
  if (hadConversationEditItem !== hasCurrentConversationEditItem && messageHistory.length > 0) renderMessageStream(messageHistory);
  document.querySelector('#inventory-money').textContent = `所持金: ${moneyText(inventory.money)}`;
  if (screens['academy-room']?.classList.contains('active')) renderAcademyRoomScreen();
  const list = document.querySelector('#inventory-items');
  const items = inventory.items ?? [];
  if (!items.length) {
    const empty = document.createElement('p');
    empty.className = 'economy-empty';
    empty.textContent = '所持品はありません。';
    list.replaceChildren(empty);
    return;
  }
  list.replaceChildren(...items.map((item) => {
    const card = document.createElement('article');
    card.className = 'economy-item-card';
    const title = document.createElement('strong');
    title.textContent = `${item.name ?? item.item_id} ×${item.quantity}`;
    const description = document.createElement('p');
    description.textContent = item.description ?? '';
    const use = document.createElement('button');
    use.type = 'button';
    use.textContent = item.stat_effect ? '1個使う' : '使えません';
    use.disabled = !item.stat_effect;
    use.addEventListener('click', () => useInventoryItem(item.item_id, 1).catch(reportError));
    const sell = document.createElement('button');
    sell.type = 'button';
    sell.textContent = `1個売る（${moneyText(item.sell_price)}）`;
    sell.addEventListener('click', () => sellInventoryItem(item.item_id).catch(reportError));
    // 使用可能なアイテムだけ「全部使う」を出す（所持数を quantity として渡す）。
    if (item.stat_effect) {
      const useAll = document.createElement('button');
      useAll.type = 'button';
      useAll.textContent = '全部使う';
      useAll.addEventListener('click', () => useInventoryItem(item.item_id, item.quantity).catch(reportError));
      card.append(title, description, use, useAll, sell);
    } else {
      card.append(title, description, use, sell);
    }
    return card;
  }));
}

// ── 購買 ──────────────────────────────────────────────────────────────────────────────────────────────────
// 品は二段の棚に並び、品そのものが買う釦（持ち金で届かない品は沈んで押せない）。手もとには持っている品が袋の印から右へ並び、押すと
// その品の使う（能力に効く品だけ）・売るの紋が開く（開くのは一つだけ・もう一度押すと閉じる）。持ち物が無いときは袋の印だけが薄く残る。
let shopOpenOwnedItemId = null;

function renderShopSatchel(inventory = currentInventory) {
  currentInventory = inventory;
  const money = moneyText(inventory.money);
  document.querySelector('#shop-wallet').setAttribute('aria-label', `所持金 ${money}`);
  document.querySelector('#shop-inventory-money').textContent = money;
  const items = inventory.items;
  if (!items.some((item) => item.item_id === shopOpenOwnedItemId)) shopOpenOwnedItemId = null;
  document.querySelector('#shop-satchel').dataset.empty = String(items.length === 0);
  document.querySelector('#shop-inventory-items').replaceChildren(...items.map((item) => buildShopOwned(item)));
}

function buildShopOwned(item) {
  const open = item.item_id === shopOpenOwnedItemId;
  const owned = document.createElement('div');
  owned.className = 'shop-owned';
  owned.dataset.open = String(open);
  const token = document.createElement('button');
  token.type = 'button';
  token.className = 'shop-owned-token';
  token.setAttribute('aria-label', item.name);
  token.setAttribute('aria-expanded', String(open));
  const count = document.createElement('span');
  count.className = 'shop-count';
  count.textContent = `×${item.quantity.toLocaleString('ja-JP')}`;
  token.append(...shelfItemMarks(item), count);
  token.addEventListener('click', () => {
    shopOpenOwnedItemId = open ? null : item.item_id;
    renderShopSatchel(currentInventory);
  });
  owned.append(token, shelfLabel(item.name, moneyText(item.sell_price)));
  if (open) {
    const ways = document.createElement('span');
    ways.className = 'shop-ways';
    if (item.stat_effect) ways.append(shopWay('use', `${item.name}を使う`, () => useInventoryItem(item.item_id, 1)));
    ways.append(shopWay('sell', `${item.name}を売る`, () => sellInventoryItem(item.item_id)));
    owned.append(ways);
  }
  return owned;
}

function shopWay(sigil, name, act) {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'shelf-sigil shop-way';
  button.setAttribute('aria-label', name);
  button.append(shelfSigil(sigil));
  button.addEventListener('click', () => act().catch(reportError));
  return button;
}

function renderShop(shop = currentShop) {
  currentShop = shop;
  const half = Math.ceil(shop.items.length / 2);
  document.querySelector('#shop-items').replaceChildren(...[shop.items.slice(0, half), shop.items.slice(half)].map((row) => {
    const shelf = document.createElement('div');
    shelf.className = 'shop-shelf';
    shelf.append(...row.map((item) => buildShopWare(item)));
    return shelf;
  }));
}

// 棚の品: 品の印の円（能力に効く品は右肩に効き目の値）と、その下の名と買値。
function buildShopWare(item) {
  const ware = document.createElement('button');
  ware.type = 'button';
  ware.className = 'shop-ware';
  ware.setAttribute('aria-label', `${item.name}を買う`);
  ware.disabled = Number(currentInventory.money) < item.buy_price;
  const vessel = document.createElement('span');
  vessel.className = 'shop-vessel';
  vessel.append(...shelfItemMarks(item));
  if (item.stat_effect) {
    const effect = document.createElement('span');
    effect.className = 'shop-effect';
    effect.textContent = `+${item.stat_effect.amount}`;
    vessel.append(effect);
  }
  ware.append(vessel, shelfLabel(item.name, moneyText(item.buy_price)));
  ware.addEventListener('click', () => buyShopItem(item.item_id).catch(reportError));
  return ware;
}

async function refreshEconomy() {
  const [inventory, shop] = await Promise.all([
    getJson('/api/inventory'),
    getJson('/api/shop')
  ]);
  currentInventory = inventory;
  currentShop = shop;
  renderInventory(inventory);
  renderShopSatchel(inventory);
  renderShop(shop);
}

async function buyShopItem(itemId) {
  const result = await postJson('/api/shop/buy', { item_id: itemId, quantity: 1 });
  renderInventory(result.inventory);
  renderShopSatchel(result.inventory);
  renderShop(currentShop);
  showEconomyMessage(`${result.item.name ?? result.item.item_id}を${moneyText(result.item.buy_price)}で購入しました。`);
}

// The feedback balloon reports the server-authoritative used count and parameter move (never a client recompute):
// how many were consumed and how the stat shifted, so 全部使う and 1個使う both read what actually happened.
function economyUseMessage(result) {
  const { item, effect } = result;
  const name = item.name ?? item.item_id;
  return `${name}を${effect.used_quantity}個使用しました（${effect.label} ${effect.before} → ${effect.after}）`;
}

async function useInventoryItem(itemId, quantity) {
  const result = await postJson('/api/inventory/use', { item_id: itemId, quantity });
  currentWorld = result.world;
  renderPlayerParametersEditor(currentWorld.player_parameters ?? {});
  renderTrainingScreen();
  renderInventory(result.inventory);
  renderShopSatchel(result.inventory);
  renderShop(currentShop);
  showEconomyMessage(economyUseMessage(result));
  await refreshPrompt();
}

async function sellInventoryItem(itemId) {
  const result = await postJson('/api/shop/sell', { item_id: itemId, quantity: 1 });
  renderInventory(result.inventory);
  renderShopSatchel(result.inventory);
  renderShop(currentShop);
  showEconomyMessage(`${result.item.name ?? result.item.item_id}を${moneyText(result.item.sell_price)}で売却しました。`);
}

// ── 採取 ──────────────────────────────────────────────────────────────────────────────────────────────────
// 採れる所は、所の絵を山林の絵の中の円にして小径に沿って置く。円の右下の籠の紋が採る釦で、在庫の尽きた所は紋が消えて円が灰に沈む。
// 円の下に所の名、採れる素材の印と数と売値、在庫の菱形。揺り籠の品の所は所の絵がまだ配られていないので、揺り籠の印を置く。
// 置き場は所ごとの円の中心（画面の幅と高さに対する割合）で、山林の所ごとに寄せて左から右へ並ぶ。
const GATHERING_SPOT_POSITIONS = Object.freeze({
  sanrin_trailhead_silverleaf_patch: { x: 15.63, y: 40.89 },
  sanrin_conifer_forest_resin_cluster: { x: 31.18, y: 59.78 },
  sanrin_conifer_forest_yuragi_bulb: { x: 46.32, y: 40.89 },
  sanrin_stream_bank_mica_pebbles: { x: 60.9, y: 59.78 },
  sanrin_stream_bank_warm_egg: { x: 75.83, y: 40.89 },
  sanrin_mossy_shrine_blue_moss: { x: 90.49, y: 59.78 },
  sanrin_mossy_shrine_madara_egg: { x: 90.49, y: 26.22 }
});

function renderGathering(gathering = currentGathering) {
  currentGathering = gathering;
  document.querySelector('#gathering-points').replaceChildren(...gathering.points.map((point) => buildGatheringSpot(point)));
}

function buildGatheringSpot(point) {
  const position = GATHERING_SPOT_POSITIONS[point.point_id];
  if (!position) throw new Error(`gathering: no spot on the 山林 picture for the point ${JSON.stringify(point.point_id)}`);
  const { remaining, max } = point.stock;
  const cradle = STAR_CRADLE_SEED_ITEM_PATTERN.test(point.material.item_id);
  const spot = document.createElement('div');
  spot.className = 'gathering-spot';
  spot.style.left = `${position.x}%`;
  spot.style.top = `${position.y}%`;
  spot.dataset.stock = remaining > 0 ? 'some' : 'none';
  const vignette = document.createElement('span');
  vignette.className = 'gathering-vignette';
  if (cradle) vignette.dataset.stand = 'cradle';
  vignette.append(shelfImage('gathering-vignette-image', cradle ? STAR_CRADLE_ICON_URL : point.image));
  if (remaining > 0) {
    const harvest = document.createElement('button');
    harvest.type = 'button';
    harvest.className = 'shelf-sigil gathering-harvest';
    dressSigilButton(harvest, 'harvest', `${point.display_name}を採取する`);
    harvest.addEventListener('click', () => collectGatheringPoint(point.point_id).catch(reportError));
    vignette.append(harvest);
  }
  const label = document.createElement('span');
  label.className = 'shelf-label gathering-label shelf-ellipse';
  const name = document.createElement('span');
  name.className = 'shelf-label-name';
  name.textContent = point.display_name;
  const yieldRow = document.createElement('span');
  yieldRow.className = 'gathering-yield';
  const quantity = document.createElement('span');
  quantity.textContent = `×${point.material.quantity}`;
  const price = document.createElement('span');
  price.className = 'shelf-label-value';
  price.textContent = moneyText(point.material.sell_price);
  yieldRow.append(...shelfItemMarks(point.material), quantity, price);
  const stock = document.createElement('span');
  stock.className = 'shelf-diamonds gathering-stock';
  stock.setAttribute('role', 'img');
  fillShelfDiamonds(stock, remaining, max, '在庫');
  label.append(name, yieldRow, stock);
  spot.append(vignette, label);
  return spot;
}

async function refreshGathering() {
  const gathering = await getJson('/api/gathering');
  currentGathering = gathering;
  renderGathering(gathering);
}

async function collectGatheringPoint(pointId) {
  let result;
  try {
    result = await postJson('/api/gathering/collect', { point_id: pointId });
  } catch (error) {
    if (error?.payload?.error === 'gathering_stock_empty') {
      await refreshGathering();
      showEconomyMessage('この採取ポイントの在庫はもうありません。');
      return;
    }
    throw error;
  }
  currentGathering = result.gathering;
  renderGathering(result.gathering);
  renderInventory(result.inventory);
  renderShopSatchel(result.inventory);
  const material = result.point.material;
  const quantity = result.gathered_item.quantity;
  showEconomyMessage(`${material.name ?? material.item_id}を${quantity}個採取しました。`);
}

function renderCharacterSelector() {
  const list = document.querySelector('#character-selection-list');
  const description = document.querySelector('#character-prompt-description');
  const speakingBasis = document.querySelector('#character-speaking-basis');
  const saveButton = document.querySelector('#save-character-description');
  const selectedCharacterSource = document.querySelector('#selected-character-source');
  const selected = activeCharacter();
  const authoringEnabled = characterAuthoringEnabled();
  document.querySelector('#selected-character-name-button').textContent = selected.display_name ?? selected.character_id;
  const fieldCharacterDetailTitle = document.querySelector('#field-character-detail-title');
  fieldCharacterDetailTitle.textContent = selected.display_name ?? selected.character_id;
  document.querySelector('#academy-conversation-session-character-name-button').textContent = selected.display_name ?? selected.character_id;
  document.querySelector('#academy-conversation-session-character-detail-title').textContent = selected.display_name ?? selected.character_id;
  renderInteractionCharacterParameters(selected);
  renderCharacterDetailStandees(selected);
  selectedCharacterSource.textContent = authoringEnabled ? '' : characterAuthoringMessage();
  description.value = selected.prompt_description ?? '';
  speakingBasis.value = selected.speaking_basis ?? '';
  description.readOnly = !authoringEnabled;
  speakingBasis.readOnly = !authoringEnabled;
  saveButton.disabled = !authoringEnabled;
  saveButton.title = authoringEnabled ? '' : characterAuthoringMessage();
  list.replaceChildren(...selectableCharacters.map((character) => {
    const flagged = characterDeleteFlaggedIds.has(character.character_id);
    const cell = document.createElement('div');
    cell.className = 'character-option-cell';
    cell.classList.toggle('is-delete-flagged', flagged);
    cell.dataset.characterId = character.character_id;

    const button = document.createElement('button');
    button.type = 'button';
    button.className = character.character_id === activeCharacterId ? 'selected character-option' : 'character-option';
    button.dataset.characterId = character.character_id;
    const thumb = document.createElement('img');
    thumb.src = character.selection_icon_url ?? character.face_url;
    thumb.alt = `${character.display_name} neutral face`;
    const label = document.createElement('span');
    label.innerHTML = `<strong>${character.display_name}</strong>`;
    button.append(thumb, label);
    button.addEventListener('click', () => {
      activeCharacterId = character.character_id;
      clearVisibleConversation();
      renderCharacterSelector();
      renderRelationshipDebugControls();
      refreshPrompt().catch(reportError);
      refreshRecordStatus().catch(reportError);
      openFieldCharacterDetail();
    });

    const badge = document.createElement('span');
    badge.className = 'delete-flag-badge';
    badge.textContent = '削除候補';
    badge.hidden = !flagged;

    const flagToggle = document.createElement('button');
    flagToggle.type = 'button';
    flagToggle.className = 'delete-flag-toggle';
    flagToggle.dataset.characterId = character.character_id;
    flagToggle.setAttribute('aria-pressed', flagged ? 'true' : 'false');
    flagToggle.textContent = flagged ? '削除フラグを外す' : '削除フラグを付ける';
    flagToggle.title = '削除候補のマーキングです（実際の削除は行いません）。';
    flagToggle.addEventListener('click', (event) => {
      event.stopPropagation();
      toggleCharacterDeleteFlag(character.character_id).catch(reportError);
    });

    cell.append(button, badge, flagToggle);
    return cell;
  }));
}

function characterDeleteFlaggedSetFrom(result) {
  if (!result || !Array.isArray(result.flagged)) {
    throw new Error('character delete flags response is missing a "flagged" array');
  }
  return new Set(result.flagged);
}

async function refreshCharacterDeleteFlags() {
  const result = await getJson('/api/character-delete-flags');
  characterDeleteFlaggedIds = characterDeleteFlaggedSetFrom(result);
}

async function toggleCharacterDeleteFlag(characterId) {
  const result = await postJson('/api/character-delete-flags/toggle', { character_id: characterId });
  characterDeleteFlaggedIds = characterDeleteFlaggedSetFrom(result);
  renderCharacterSelector();
}

async function refreshCharacters() {
  const [result] = await Promise.all([getJson('/api/characters'), refreshCharacterDeleteFlags()]);
  selectableCharacters = result.characters ?? [];
  characterAuthoringCapability = result.capabilities?.character_authoring ?? { enabled: true, reason: null, message: null };
  if (!selectableCharacters.some((character) => character.character_id === activeCharacterId)) {
    // Creatures, the routing persona, and a 錬成室 homunculus are intentionally absent from the academy
    // roster, so the academy-roster fallback must never hijack an in-progress non-selectable conversation
    // (a creature encounter, a live routing hub, or an active homunculus 錬成室 conversation) by resetting
    // the actor to the roster head (character_001 / セラ). A single predicate decides preservation for
    // every non-selectable active-actor kind; fall back only for an unknown academy id — never silently
    // keep an unidentified id (fail-fast).
    if (!isNonSelectableActiveActorId(activeCharacterId)) {
      activeCharacterId = selectableCharacters[0]?.character_id ?? activeCharacterId;
    }
  }
  renderCharacterSelector();
  renderRelationshipDebugControls();
}

async function saveSelectedCharacterDescription() {
  if (!characterAuthoringEnabled()) return;
  const promptDescription = document.querySelector('#character-prompt-description').value;
  const speakingBasis = document.querySelector('#character-speaking-basis').value;
  const result = await postJson('/api/characters/profile', { character_id: activeCharacterId, prompt_description: promptDescription, speaking_basis: speakingBasis });
  selectableCharacters = selectableCharacters.map((character) => character.character_id === activeCharacterId
    ? { ...character, prompt_description: result.profile.prompt_description, speaking_basis: result.profile.speaking_basis }
    : character);
  renderCharacterSelector();
  await refreshPrompt();
}

