async function startAcademyConversationSessionFromCompanion(characterId) {
  if (conversationRequestInFlight) {
    showProcessingToast();
    return;
  }
  conversationRequestInFlight = true;
  setConversationControlsDisabled(true);
  let openingStreamStartedResolve = null;
  let openingStreamStartedResolved = false;
  const openingStreamStarted = new Promise((resolve) => {
    openingStreamStartedResolve = resolve;
  });
  const markOpeningStreamStarted = () => {
    if (openingStreamStartedResolved) return;
    openingStreamStartedResolved = true;
    openingStreamStartedResolve?.();
  };
  let openingPromise = Promise.resolve();
  const readiness = (async () => {
    // A field / academy-map companion conversation is a normal conversation, never the routing hub; drop any
    // routing hub state so the chosen actor is not preserved as the routing persona and the stage is not the hub.
    // (Migrated from the removed field-interaction start; a no-op when no hub conversation is active.)
    clearRoutingHubConversation();
    activeCharacterId = characterId;
    // Drain-on-exit owns post-processing: the previous conversation's exit fully drained the queue
    // before it transitioned here, so the session starts immediately with no entry pre-drain wait.
    const result = await postJson('/api/interaction/start', { character_id: characterId, source_type: 'field' });
    notifyAcademyLoadingProgress();
    clearVisibleConversation();
    writeDebugLog({
      started_interaction: characterId,
      source_type: 'field',
      state: result.state,
      screen: 'academy-conversation-session'
    });
    await refresh();
    notifyAcademyLoadingProgress();
    // Send the actor the player actually chose. refresh() runs refreshCharacters(), and for a
    // creature this id is outside the academy roster; passing it explicitly keeps the opening on
    // the creature even though the global actor is only ever reset for unknown academy ids.
    openingPromise = ensureOpeningUtterance({ characterId, onAssistantStreamStart: markOpeningStreamStarted });
    await Promise.race([openingStreamStarted, openingPromise]);
  })();
  try {
    await showAcademyLoadingScreenUntilReady({
      readiness,
      nextScreen: 'academy-conversation-session',
      refreshBeforeNextScreen: false
    });
    await openingPromise;
  } catch (error) {
    // Loading-residual defense: a failed companion conversation start must not strand the player on the
    // academy-loading screen. A settings-redirect error already left it (reportLoadingError → settings); for any
    // other failure still on the loader, un-strand to the conversation session (its status line carries the cause,
    // the top bar carries the recovery path), then re-raise so the click handler's .catch(reportError) logs it once.
    if (isAcademyLoadingScreenActive() && settingsRedirectErrorMessage(error) == null) {
      showScreen('academy-conversation-session');
      setConversationStatus(errorDisplayMessage(error), { tone: 'error' });
    }
    throw error;
  } finally {
    conversationRequestInFlight = false;
    setConversationControlsDisabled(false);
  }
}

async function moveToLocation(locationId, { showDetail = false, nextScreen = 'field', selectedVisibleSituation = null } = {}) {
  const result = await postJson('/api/field/move', {
    location_id: locationId,
    selected_visible_situation: selectedVisibleSituation ?? selectedAcademyStageSituation(locationId) ?? undefined
  });
  currentField = null;
  writeDebugLog({
    moved_to: result.location.id,
    state: result.state
  });
  clearVisibleConversation();
  await refresh();
  showScreen(nextScreen);
  if (showDetail) openFieldLocationDetail();
}

// The conversation-session stage card renderer. The old physical interaction screen's stage/detail
// surfaces were removed, so this now targets only the session stage image, name, and detail popup.
function renderInteractionLocation(location) {
  const sessionImage = document.querySelector('#academy-conversation-session-location-image');
  const sessionDetailImage = document.querySelector('#academy-conversation-session-location-detail-image');
  const sessionName = document.querySelector('#academy-conversation-session-location-name-button');
  const sessionDetail = document.querySelector('#academy-conversation-session-location-detail-text');
  const sessionLocationDetailTitle = document.querySelector('#academy-conversation-session-location-detail-title');
  // The conversation-session screen belongs to the routing hub while one is active, so its stage card
  // shows the routing hub stage regardless of the field location the caller passed (refresh() ->
  // renderField feeds the field location here after every turn). Outside a routing hub sessionLocation
  // === location, so loop / normal conversation-session stage rendering is byte-equivalent.
  const sessionLocation = isRoutingHubActive() ? ROUTING_HUB_STAGE : location;
  const sessionLocationName = sessionLocation?.display_name ?? currentRuntimeState?.current_location_id ?? '現在地';
  if (sessionName) sessionName.textContent = sessionLocationName;
  if (sessionLocationDetailTitle) sessionLocationDetailTitle.textContent = sessionLocationName;
  if (sessionDetail) sessionDetail.textContent = sessionLocation?.visible_situation ?? '舞台の説明文はまだありません。';
  if (sessionImage) sessionImage.setAttribute('aria-label', `${sessionLocationName}の画像`);
  if (sessionDetailImage) sessionDetailImage.setAttribute('aria-label', `${sessionLocationName}の画像`);
  // The session stage background follows sessionLocation: the field/companion background in loop /
  // normal conversations (byte-equivalent), and the routing hub's blank background (no art yet) while
  // the hub is active, so the greenhouse (or any prior field stage) never bleeds into the hub card.
  if (sessionLocation?.background_url) {
    const sessionBackgroundImage = `linear-gradient(180deg, rgba(21,26,38,0.04), rgba(21,26,38,0.52)), url('${sessionLocation.background_url}')`;
    for (const target of [sessionImage, sessionDetailImage]) {
      if (!target) continue;
      target.style.backgroundImage = sessionBackgroundImage;
      target.dataset.backgroundSourceImageUrl = sessionLocation.background_source_image_url ?? sessionLocation.background_url ?? '';
    }
  } else {
    for (const target of [sessionImage, sessionDetailImage]) {
      if (!target) continue;
      target.style.backgroundImage = '';
      delete target.dataset.backgroundSourceImageUrl;
    }
  }
}

function openInteractionDetailDialog(selector) {
  const dialog = document.querySelector(selector);
  if (!dialog) return;
  if (typeof dialog.showModal === 'function') {
    dialog.showModal();
    return;
  }
  dialog.setAttribute('open', '');
  dialog.classList.add('fallback-open');
  document.body.classList.add('interaction-detail-backdrop');
}

