async function startAcademyConversationSessionFromPendingEvent(flagId, { loadingAlreadyVisible = false, allowDuringInFlight = false } = {}) {
  // Event-flag conversations land on the daytime conversation screen. Routing is the official mode, so there is
  // no legacy session landing; startConversationDayFromPendingEvent owns the in-flight guard, the /api/event-flags
  // /start setup, and the opening flow. allowDuringInFlight is the explicit opt-in for the one caller that starts
  // this event session from inside a still-in-flight originating turn (the routing in-turn academy-map dispatch,
  // arriveAtRoutingAcademyMap); every other caller leaves it false and keeps the single-flight guard.
  await startConversationDayFromPendingEvent(flagId, { loadingAlreadyVisible, allowDuringInFlight });
}

async function startEventFlagInteractionFromScreen(flagId) {
  // The manual event-tab start lands on the daytime conversation screen (loading-interstitial opening). Routing
  // is the official mode, so there is no legacy immediate session start; startConversationDayFromPendingEvent
  // owns the in-flight guard and the opening flow.
  await startConversationDayFromPendingEvent(flagId);
}

async function openEventTab() {
  if (conversationRequestInFlight) {
    showProcessingToast();
    return;
  }
  const status = await refreshEventFlagStatus();
  const autoStartFlag = (status.pending_events ?? []).find((flag) => flag.interaction?.location_id && flag.character_id);
  if (autoStartFlag) {
    await startEventFlagInteractionFromScreen(autoStartFlag.id);
    return;
  }
  showScreen('event');
}

