async function refreshLlmRequestLog() {
  const status = await getJson('/api/debug/llm-requests');
  recentLlmRequests = status.requests ?? [];
  const list = document.querySelector('#llm-request-list');
  list.innerHTML = '';
  if (recentLlmRequests.length === 0) {
    list.textContent = 'LLMリクエストはまだありません。';
    return;
  }
  for (const request of recentLlmRequests) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'llm-request-title-button';
    button.textContent = `${request.title} (${request.kind})`;
    button.addEventListener('click', () => openLlmRequestDetail(request.id));
    list.append(button);
  }
}

async function resetContinuityRecords(target) {
  const result = await postJson('/api/records/reset', { character_id: activeCharacterId, target });
  writeDebugLog({
    reset_continuity_records: target,
    removed: result.removed
  });
  renderContinuityRecords(result.status);
}

async function deleteCharacterRecords(target) {
  await resetContinuityRecords(target);
}

// acceptedErrorCodes names the API error codes that are a known state for this task, not a failure: the task then
// yields fallbackValue without reporting. Every other error is reported as before.
async function runRefreshTask(label, taskFactory, { timeoutMs = REFRESH_TASK_TIMEOUT_MS, fallbackValue = null, acceptedErrorCodes = [] } = {}) {
  let timedOut = false;
  const taskPromise = Promise.resolve()
    .then(taskFactory)
    .then((value) => ({ status: 'fulfilled', value }))
    .catch((error) => {
      if (acceptedErrorCodes.includes(error?.errorCode)) return { status: 'accepted', value: fallbackValue };
      if (!timedOut) reportError(error);
      return { status: 'rejected', value: fallbackValue };
    });
  const result = await Promise.race([
    taskPromise,
    new Promise((resolve) => setTimeout(() => {
      timedOut = true;
      resolve({ status: 'timeout', value: fallbackValue });
    }, timeoutMs))
  ]);
  if (result.status === 'timeout') reportError(new Error(`refresh timeout: ${label}`));
  return result.value;
}

// noSaveYet is the boot read on a machine that may hold no save at all: /api/state and /api/field answer
// NO_ACTIVE_SLOT there, which is the "no save yet" state (the title offers only 最初から始める), not an error to
// write on the title. Any other failure of the boot read is reported as usual.
async function refresh({ strictField = false, noSaveYet = false } = {}) {
  const playStateAccepted = noSaveYet ? ['NO_ACTIVE_SLOT'] : [];
  await Promise.all([
    runRefreshTask('characters', () => refreshCharacters()),
    runRefreshTask('world settings', () => refreshWorldSettings()),
    runRefreshTask('economy', () => refreshEconomy())
  ]);
  // strictField is the routing content-arrival contract: the map reads its stage descriptions live from
  // currentField, so a failed /api/field must fail-fast (throw) instead of falling back to the stale
  // cached field and rendering a frozen map. The default resilient path (loop and every other caller)
  // keeps the last-known field on a stalled fetch, so those transitions stay byte-equivalent.
  const [state, field] = await Promise.all([
    runRefreshTask('state', () => getJson('/api/state'), { fallbackValue: currentRuntimeState, acceptedErrorCodes: playStateAccepted }),
    strictField
      ? getJson('/api/field')
      : runRefreshTask('field', () => getJson('/api/field'), { fallbackValue: currentField, acceptedErrorCodes: playStateAccepted })
  ]);
  currentRuntimeState = state ?? currentRuntimeState;
  renderRelationshipDebugControls();
  const trainingState = currentRuntimeState ?? {};
  currentTrainingProgress = {
    actions_used: Number(trainingState.training_actions_used ?? 0),
    actions_limit: Number(trainingState.training_actions_limit ?? TRAINING_ACTION_LIMIT),
    remaining_actions: Math.max(0, Number(trainingState.training_actions_limit ?? TRAINING_ACTION_LIMIT) - Number(trainingState.training_actions_used ?? 0)),
    completed: Number(trainingState.training_actions_used ?? 0) >= Number(trainingState.training_actions_limit ?? TRAINING_ACTION_LIMIT)
  };
  renderTrainingProgress(currentTrainingProgress);
  if (screens['academy-room']?.classList.contains('active')) renderAcademyRoomScreen();
  if (field) renderField(field);
  await Promise.all([
    runRefreshTask('record status', () => refreshRecordStatus()),
    runRefreshTask('flag status', () => refreshFlagStatus()),
    runRefreshTask('event flag status', () => refreshEventFlagStatus()),
    runRefreshTask('llm request log', () => refreshLlmRequestLog()),
    runRefreshTask('save slots', () => refreshSaveSlots())
  ]);
}

async function refreshPrompt() {
}

// The chat send/receive/sequential-reveal/expression logic below is surface-neutral:
// it is driven entirely through a `surface` so the academy conversation session and
// the dungeon companion sidebar can mount the same controller. A surface supplies the
// per-screen seams — its message history store, assistant identity, render target,
// conversation→display mapping, canonical-state commit, and post-stream refresh — while
// the reveal pacing, expression handling, and SSE parsing stay shared.
const academyChatSurface = {
  getHistory: () => messageHistory,
  setHistory: (messages) => { messageHistory = messages; },
  render: (messages, options) => renderMessageStream(messages, options),
  mapMessages: (conversation) => messagesFromConversation(conversation),
  assistantIdentity: () => ({ character_id: activeCharacterId, character_name: activeCharacter().display_name }),
  commitState: (result) => commitConversationResultState(result),
  refresh: () => refresh()
};

// Sequential (cooldown-paced) reveal of an already-complete result for any surface.
// Used for non-streamed openings — the academy keeps its own renderConversationResultSequentially
// so its frozen contract is untouched; the dungeon companion opening reuses this generic form.
async function revealResultSequentially(surface, result) {
  const previousDisplay = displayMessages(surface.getHistory());
  const fullMessages = surface.mapMessages(result.conversation);
  const fullDisplay = displayMessages(fullMessages);
  const newSegments = fullDisplay.slice(previousDisplay.length);
  for (let index = 0; index < newSegments.length; index += 1) {
    surface.render([
      ...previousDisplay,
      ...newSegments.slice(0, index + 1)
    ], { popFromDisplayIndex: previousDisplay.length + index });
    await sleep(conversationPopupCooldownMs());
  }
  surface.commitState(result);
}

// The turn's prompt prewarm failed after the turn was written (SSE error PROMPT_PREWARM_FAILED). The error carries
// the written turn as turn_result; the stream adopts it in place of the result and attaches the failure as
// prompt_prewarm_error, which the screen shows on its error banner while keeping the turn and reopening input.
const PROMPT_PREWARM_FAILED_ERROR_CODE = 'PROMPT_PREWARM_FAILED';

function promptPrewarmFailedTurnResult({ url, data }) {
  if (!data.turn_result || typeof data.turn_result !== 'object') {
    throw new Error(`${url}: PROMPT_PREWARM_FAILED stream error is missing turn_result`);
  }
  return {
    ...data.turn_result,
    prompt_prewarm_error: createApiError({ url, status: 503, payload: data, fallbackText: data.error ?? '' })
  };
}

async function runAssistantSseStream({ surface, endpoint, body, statusPrefix = 'stream', finalAssistantMode = 'last', refreshAfter = true, onAssistantStreamStart = null, onStageMove = null, onRoutingDispatch = null, onRoutingDraining = null, onEvent = null, revealAfter = null }) {
  const response = await fetch(endpoint, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(body)
  });
  if (!response.ok) {
    const text = await response.text();
    throw createApiError({ url: endpoint, status: response.status, payload: parseJsonText(text), fallbackText: text });
  }
  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = '';
  let assistantText = '';
  let assistantExpression = 'neutral';
  let finalResult = null;
  const baseMessages = [...surface.getHistory()];
  const visibleAssistantSegments = [];
  const pendingAssistantSegments = [];
  let assistantRevealPromise = Promise.resolve();
  let assistantRevealRunning = false;
  let assistantRevealFrame = null;
  // revealAfter holds the first popup until the caller's signal (the conversation screen it renders into is shown);
  // the segments keep queueing meanwhile and then reveal one per cooldown from that signal.
  let assistantRevealCooldownGate = revealAfter ?? Promise.resolve();
  let currentAssistantQueuedSegmentCount = 0;
  let assistantCompleteCount = 0;
  let assistantStreamStarted = false;
  // 舞台移動: the stage_move event arrives between the cutoff (the last line at the old stage) and the new-stage
  // opening. stageMoveAtSegment is the count of segments queued by then (the cutoff's included); the reveal runs the
  // move choreography (onStageMove) once before revealing the segment at that index, so the stage moves after the
  // cutoff and before the opening line.
  // A turn that fails after the stage_move event never starts the move afterwards (streamFailed), and the session
  // stage is put where the player is (returnStageToCurrentLocation).
  let stageMoveEvent = null;
  let stageMoveAtSegment = null;
  let stageMoveShown = null;
  let streamFailed = false;
  const noteLoadingDelta = createLoadingProgressDeltaThrottle();

  function showStageMove() {
    stageMoveShown ??= onStageMove({ stageMove: stageMoveEvent });
    return stageMoveShown;
  }

  // The turn failed after announcing the move: the move may have painted the destination while the player is still at
  // the old stage (the server writes the move at the end of the turn), or the turn was written while the move never
  // showed (the stream was cut before the opening). Where the player is comes from the server, never from the screen:
  // let a move in progress finish, then adopt the server's field (strict — a failed /api/field throws instead of
  // keeping the stale field), which repaints the session stage.
  async function returnStageToCurrentLocation() {
    if (stageMoveShown) await Promise.allSettled([stageMoveShown]);
    renderField(await getJson('/api/field'));
  }

  function notifyAssistantStreamStarted() {
    if (assistantStreamStarted) return;
    assistantStreamStarted = true;
    onAssistantStreamStart?.();
  }

  const assistantMessage = (content) => ({
    role: 'assistant',
    ...surface.assistantIdentity(),
    content,
    face_emotion_variant_id: `face_${assistantExpression}`,
    expression: assistantExpression
  });

  function queueAssistantSegments(content) {
    if (!content.trim()) return;
    const completedSegments = displayMessages([assistantMessage(content)])
      .filter((segment) => (segment.content ?? '').trim());
    const newSegments = completedSegments.slice(currentAssistantQueuedSegmentCount);
    pendingAssistantSegments.push(...newSegments);
    currentAssistantQueuedSegmentCount += newSegments.length;
  }

  function beginNextAssistantMessage() {
    assistantText = '';
    currentAssistantQueuedSegmentCount = 0;
  }

  function queueCompletedAssistantSegments() {
    const completed = completedAssistantPrefix(assistantText);
    if (!completed.trim()) return;
    queueAssistantSegments(completed);
  }

  async function revealNextAssistantSegment() {
    if (assistantRevealRunning) return assistantRevealPromise;
    assistantRevealRunning = true;
    try {
      while (pendingAssistantSegments.length > 0) {
        // Enforce the cooldown between every popup, including segments queued by
        // assistant_complete. The gate carries the remaining cooldown across loop
        // restarts so no popup ever appears sooner than the cooldown after the prior one.
        await assistantRevealCooldownGate;
        if (visibleAssistantSegments.length === stageMoveAtSegment) {
          if (streamFailed) break;
          await showStageMove();
        }
        const previousDisplayCount = displayMessages(surface.getHistory()).length;
        visibleAssistantSegments.push(pendingAssistantSegments.shift());
        surface.render([
          ...baseMessages,
          ...visibleAssistantSegments
        ], { popFromDisplayIndex: previousDisplayCount });
        assistantRevealCooldownGate = sleep(conversationPopupCooldownMs());
      }
    } finally {
      assistantRevealRunning = false;
    }
  }

  function revealCompletedAssistantText() {
    queueCompletedAssistantSegments();
    assistantRevealPromise = revealNextAssistantSegment();
  }

  function scheduleAssistantSegmentReveal() {
    if (assistantRevealFrame) return;
    assistantRevealFrame = requestAnimationFrame(() => {
      assistantRevealFrame = null;
      revealCompletedAssistantText();
    });
  }

  async function finishAssistantSegmentReveal() {
    const assistantMessages = surface.mapMessages(finalResult.conversation).filter((message) => message.role === 'assistant');
    const finalAssistant = finalAssistantMode === 'first' ? assistantMessages[0] : assistantMessages.at(-1);
    if (finalAssistant) assistantText = finalAssistant.content ?? assistantText;
    if (assistantRevealFrame) {
      cancelAnimationFrame(assistantRevealFrame);
      assistantRevealFrame = null;
    }
    queueAssistantSegments(assistantText);
    await assistantRevealPromise;
    await revealNextAssistantSegment();
  }

  function handleBlock(block) {
    const event = block.split('\n').find((line) => line.startsWith('event: '))?.slice(7);
    const dataText = block.split('\n').find((line) => line.startsWith('data: '))?.slice(6);
    const data = dataText ? JSON.parse(dataText) : null;
    // Side-channel events the shared controller does not interpret (e.g. the dungeon enter
    // board) are handed to the caller; the academy passes no handler and is unaffected.
    if (onEvent) onEvent(event, data);
    if (event === 'status') setStreamStatus(`${statusPrefix}: ${data.phase}`);
    if (event === 'assistant_emotion') {
      assistantExpression = data.expression ?? 'neutral';
      setStreamStatus(`${statusPrefix}: emotion ${assistantExpression}`);
    }
    if (event === 'assistant_delta') {
      notifyAssistantStreamStarted();
      noteLoadingDelta();
      if (assistantCompleteCount > 0) {
        beginNextAssistantMessage();
        assistantCompleteCount = 0;
      }
      assistantText += data.delta;
      scheduleAssistantSegmentReveal();
      setStreamStatus(`${statusPrefix}: receiving assistant text (${assistantText.length} chars)`);
    }
    if (event === 'assistant_complete') {
      notifyAssistantStreamStarted();
      notifyAcademyLoadingProgress();
      if (assistantCompleteCount > 0) beginNextAssistantMessage();
      assistantText = data.content ?? assistantText;
      assistantExpression = data.expression ?? assistantExpression;
      if (assistantRevealFrame) {
        cancelAnimationFrame(assistantRevealFrame);
        assistantRevealFrame = null;
      }
      queueAssistantSegments(assistantText);
      assistantCompleteCount += 1;
      assistantRevealPromise = revealNextAssistantSegment();
      setStreamStatus(`${statusPrefix}: assistant text completed`);
    }
    // Drain-on-exit: the decided routing turn's send-off has streamed in and the backend is now running
    // the pending-finalization drain before the result. Show the loading screen so the post-processing
    // runs under it (the send-off was shown while streaming; it is not hidden — the loading screen only
    // takes over for the drain, then the result event navigates to the destination).
    if (event === 'routing_draining') {
      onRoutingDraining?.(data);
      notifyAcademyLoadingProgress();
    }
    // finalization_progress: a block boundary of the post-turn drain (memory / skill / work_record /
    // state_effects / commit). While the drain runs under the loading screen, each boundary advances the
    // constellation one edge (no-op when the loader is not shown — same guard as every other notify).
    if (event === 'finalization_progress') notifyAcademyLoadingProgress();
    if (event === 'stage_move') {
      if (!onStageMove) throw new Error(`${endpoint}: stage_move streamed to a surface without a stage move handler`);
      if (stageMoveEvent) throw new Error(`${endpoint}: a second stage_move in one turn`);
      stageMoveEvent = data;
      stageMoveAtSegment = visibleAssistantSegments.length + pendingAssistantSegments.length;
    }
    if (event === 'result') {
      finalResult = data;
      notifyAcademyLoadingProgress();
    }
    // PROMPT_PREWARM_FAILED arrives after the turn was written: adopt the written turn like a result (the failure
    // rides on it for the screen's banner). Every other error fails the turn.
    if (event === 'error') {
      if (data?.error_code !== PROMPT_PREWARM_FAILED_ERROR_CODE) throw createApiError({ url: endpoint, status: 503, payload: data, fallbackText: data?.error ?? '' });
      finalResult = promptPrewarmFailedTurnResult({ url: endpoint, data });
    }
  }

  try {
    while (true) {
      const { value, done } = await reader.read();
      buffer += decoder.decode(value ?? new Uint8Array(), { stream: !done });
      const blocks = buffer.split('\n\n');
      buffer = blocks.pop() ?? '';
      for (const block of blocks) {
        if (block.trim()) handleBlock(block);
      }
      if (done) break;
    }
    if (buffer.trim()) handleBlock(buffer);
    if (!finalResult) throw new Error('stream ended without final result');
    // The streamed move and the written move are one move: a result carrying a stage_move the stream never announced
    // (or announcing another destination) is a broken backend contract.
    if ((finalResult.stage_move?.to_location_id ?? null) !== (stageMoveEvent?.to_location_id ?? null)) {
      throw new Error(`${endpoint}: stage_move event / result mismatch (event=${stageMoveEvent?.to_location_id ?? null}, result=${finalResult.stage_move?.to_location_id ?? null})`);
    }
  } catch (error) {
    streamFailed = true;
    if (stageMoveEvent) {
      await returnStageToCurrentLocation().catch((failure) => {
        reportConversationError(error);
        throw failure;
      });
    }
    throw error;
  }
  const stageMove = finalResult.stage_move ?? null;
  const routingDispatch = onRoutingDispatch ? (finalResult.routing_dispatch ?? null) : null;
  // A field stage move and a routing dispatch are mutually exclusive: a routing hub turn bypasses the
  // field stage-move judgment to make its destination decision. A result carrying both is a backend
  // contract violation; fail fast rather than silently preferring one branch.
  if (stageMove && routingDispatch) {
    throw new Error('conversation turn result carries both stage_move and routing_dispatch (mutually exclusive)');
  }
  if (stageMove) {
    // The reply and the movement cutoff revealed at the old stage, the move choreography ran (or runs now, if the
    // opening brought no segment of its own), and the new-stage opening line reveals after it.
    await finishAssistantSegmentReveal();
    await showStageMove();
    surface.commitState(finalResult);
  } else if (routingDispatch) {
    // A decided routing hub turn carries the send-off utterance plus the dispatch payload, exactly
    // where a field turn carries a stage move. Unlike a stage move there is no opening line to hold
    // back: reveal the whole send-off, adopt the post-dispatch state, then hand the dispatch to the
    // in-turn handler so it moves on to the destination content screen.
    await finishAssistantSegmentReveal();
    surface.commitState(finalResult);
    await onRoutingDispatch({ result: finalResult, dispatch: routingDispatch });
  } else {
    await finishAssistantSegmentReveal();
    surface.commitState(finalResult);
  }
  setStreamStatus(`${statusPrefix}: completed`);
  if (refreshAfter) await surface.refresh();
  return finalResult;
}

async function runOpeningConversationStream({ characterId = activeCharacterId, provider, onAssistantStreamStart = null }) {
  return runAssistantSseStream({
    surface: academyChatSurface,
    endpoint: '/api/conversation/opening/stream',
    body: { character_id: characterId, provider: provider },
    statusPrefix: 'opening',
    finalAssistantMode: 'first',
    refreshAfter: false,
    onAssistantStreamStart
  });
}

async function performStageMoveTransition({ stageMove }) {
  // Reached mid-turn when the stream announces an in-session stage move (the stage_move event). The reply
  // and the movement cutoff are already on screen and the new-stage opening line is held back; slip into
  // the loading screen to absorb the jump and paint the destination stage (image / name / visible_situation)
  // on the session, then return to it for the opening. Same session, same history — only the stage changes.
  // The turn's own refresh adopts the written stage afterwards.
  const destination = stageMoveDestination(stageMove);
  const destinationName = destination.display_name;
  try {
    await showAcademyLoadingScreenUntilReady({
      // Painting the destination stage is the observed boundary; advance the constellation when it completes so
      // the in-session move is no longer 0-edge.
      readiness: (async () => { renderInteractionLocation(destination); notifyAcademyLoadingProgress(); })(),
      nextScreen: 'academy-conversation-session',
      refreshBeforeNextScreen: false,
      loadingCopy: {
        title: `${destinationName}へ移動中`,
        status: '会話を続けたまま、次の舞台へ移っています。'
      }
    });
  } catch (error) {
    // Loading-residual defense: a failed stage-move paint must not strand the player on the loading screen. The
    // move is same-session (the conversation is still live), so un-strand back to the conversation session with the
    // cause on its status line, then re-raise so the turn handler's reportConversationError logs it once.
    if (isAcademyLoadingScreenActive() && settingsRedirectErrorMessage(error) == null) {
      showScreen('academy-conversation-session');
      setConversationStatus(errorDisplayMessage(error), { tone: 'error' });
    }
    throw error;
  }
}

// The per-turn conversation request body. A routing hub turn additionally carries the routing hub
// conversation id so the backend continues the hub deterministically instead of relying on the fragile
// last_conversation_id inference; the actor stays the preserved routing persona (activeCharacterId ===
// lina), so the explicit id and character_id agree and never trip ROUTING_TURN_CONTEXT_MISMATCH (409).
// An active errand turn carries the errand conversation id instead (the errand client is an ordinary
// roster actor, so no actor pinning): the backend routes an active-errand turn through
// matchingActiveErrandForConversation, which fail-fasts unless the turn carries the errand conversation
// id. An active study circle turn carries the study circle conversation id the same way (the host is an
// ordinary roster actor; the backend routes an active study circle turn by the request conversation id +
// host actor). An active 錬成室 (homunculus) turn carries the atelier conversation id the same way (the ホムンクルス is a
// per-slot non-roster actor; the backend routes it by the request conversation id + homunculus actor via
// matchingActiveAtelierConversation). Hub, errand, study circle, and atelier are mutually exclusive (entering one
// clears the others), so at most one id is set. A turn that is none of them omits id, so loop / normal interaction
// request bodies stay byte-equivalent.
function routingTurnRequestBody(extra) {
  const body = { character_id: activeCharacterId, ...extra };
  if (isRoutingHubActive()) body.id = routingHubConversationId;
  else if (isActiveErrandConversation()) body.id = activeErrandConversationId;
  else if (isActiveStudyCircleConversation()) body.id = activeStudyCircleConversationId;
  else if (isActiveAtelierConversation()) body.id = activeAtelierConversationId;
  return body;
}

async function runConversationStream({ playerInput, provider, refreshAfter = true }) {
  return runAssistantSseStream({
    surface: academyChatSurface,
    endpoint: '/api/conversation/stream',
    body: routingTurnRequestBody({ player_input: playerInput, provider: provider }),
    statusPrefix: 'stream',
    finalAssistantMode: 'last',
    refreshAfter,
    onStageMove: performStageMoveTransition,
    onRoutingDispatch: ({ result, dispatch }) => performRoutingTurnDispatch({ result, dispatch, overSendoff: false }),
    onRoutingDraining: showRoutingDrainLoadingScreen
  });
}

// Drain-on-exit loading screen for the in-turn wrap-up dispatch (区切りをつける → title): shown when the 見送り読みポーズ
// outlasts the backend drain, so the rest of the drain runs under the loading screen (beneath the send-off curtain)
// and performRoutingTurnDispatch (on the result event) leaves it for the title. A dispatch to a destination waits over
// its curtain instead (raiseSendoffPlaceVeil).
function showRoutingDrainLoadingScreen() {
  setAcademyLoadingDestinationCopy(null, { loadingCopy: ROUTING_EXIT_DRAIN_LOADING_COPY });
  showScreen('academy-loading');
}

// 送り出しの幕の絵の置き方: 幕も待ちの層と同じ規則で、行き先の画面（区切りをつけるならタイトルの画面）が宣言した置き方で絵を敷く
// ので、幕に満ちた絵がそのまま待ちの絵・着いた画面の絵になる。絵の無い行き先は null。宣言の無い行き先は placeArtPlacement が throw。
function sendoffCurtainPlacement(destinationId) {
  if (!Object.hasOwn(ROUTING_DISPATCH_SCREENS, destinationId)) {
    throw new Error(`routing send-off curtain: no destination screen to read the art placement from (destination_id ${JSON.stringify(destinationId)})`);
  }
  return destinationArt(destinationId) === null ? null : placeArtPlacement(ROUTING_DISPATCH_SCREENS[destinationId]);
}

// 札の画面・実践・談話室・競売場へ入る待ち: 送り出しの幕で満ちた行き先の絵をそのまま地にして（幕と同じ絵を層の地に置く）、薄い
// 暗がりを置き、右下で待ちの紋を回す。読み込みの箱は出さない。行き先の画面が出たら、絵が薄れて
// 行き先の画面が現れる。談話室・競売場・札の部屋（依頼・研究会）は着いた画面が自分の入りの要求を待つので、層は行き先の画面が出ても
// 残り、入りが整ったところで終わる（placeVeilArrived）。
const SCREENS_ENTERED_UNDER_THEIR_OWN_WAIT = new Set(['academy-lounge', 'academy-auction', 'academy-errand', 'academy-study-circle']);
function raiseSendoffPlaceVeil(destinationId) {
  if (destinationId === 'title' || !Object.hasOwn(ROUTING_DISPATCH_SCREENS, destinationId)) {
    throw new Error(`routing send-off wait: no destination screen to wait for (destination_id ${JSON.stringify(destinationId)})`);
  }
  const until = ROUTING_DISPATCH_SCREENS[destinationId];
  const art = hubTerrace.holdCurtainForWait();
  raisePlaceVeil({ art, dim: true, until, ending: 'fade', heldForArrival: SCREENS_ENTERED_UNDER_THEIR_OWN_WAIT.has(until) });
}

// Loading screen for the graduation guide selection turn when the partner is an academy person (routing phase 2
// hand-off): shown on the graduation_guide_draining SSE signal when the backend drain outlasts the 見送り読みポーズ. Their
// graduation opens like any event conversation, so the loading screen comes up as the conversation passage in the night
// (the front gate is placed once the event is set up). Choosing the 案内人 herself has no hand-off: the conversation goes
// on on the terrace.
function showGraduationEventPassageLoadingScreen() {
  beginConversationPassage(null);
  showScreen('academy-loading');
}

// Start (and display) the selected academy person's graduation event conversation from a routing graduation guide
// selection result (routing phase 2). The backend already finalized the hub (guide) conversation and started the
// character's graduation event server-side (pending_interaction_context = event.graduation_ending.ready,
// current_interaction_character_id = the chosen character), so this only adopts the selected character +
// post-selection state and opens the graduation conversation like any event conversation (openEventConversationDay: the
// passage onto the daytime screen marked event) — it never re-runs the event setup. loadingAlreadyVisible is true when
// the caller already began the passage (the reading pause outlasted the drain); false when the caller is still on the
// hub and the entry raises it. Fail-fast on a missing selected character id or post-selection state (no silent fallback
// to stale state).
async function startRoutingGraduationEndingFromSelection({ result, loadingAlreadyVisible }) {
  const characterId = result?.graduation_ending?.character_id;
  if (typeof characterId !== 'string' || characterId === '' || characterId === ROUTING_PERSONA_CHARACTER_ID) {
    throw new Error(`routing graduation guide selection must name an academy person in graduation_ending.character_id (got ${JSON.stringify(result?.graduation_ending)})`);
  }
  if (!result.state || typeof result.state !== 'object') {
    throw new Error(`routing graduation guide selection is missing post-selection state (got ${JSON.stringify(result.state)})`);
  }
  const started = {
    character_id: characterId,
    state: result.state,
    flag_id: 'event.graduation_ending.ready',
    location_id: result.state?.pending_interaction_context?.location_id ?? null
  };
  await openEventConversationDay(async () => started, { loader: loadingAlreadyVisible ? 'passage' : 'own' });
}

// ─────────────────────────────────────────────────────────────────────────────
// Routing hub — the first consumer of the shared conversation stage (conversationStage.js).
//
// The routing hub is its own screen (#routing-hub-screen) with its own chat DOM, history, streaming,
// status, ambient, and info drawer — deliberately NOT the shared academy conversation session chat.
// Rather than reimplement that machinery inline, it instantiates a conversation stage bound to the
// routing theme/scope (axis 1: #routing-hub-* selectors, /canonical/routing assets, a deep-night
// starfield ambient) and the routing conversation type (axis 2: ルミ persona visual + actor identity, the
// five info categories + renderers, the routing runtime week). The invariant mechanics — the 完成吹き出し
// 単位・等間隔・pop-in reveal queue, the at-bottom gate (+ face-load / status-toggle re-pin), the
// no-in-progress-status live region (error banner only), the info drawer open/switch/close + fixed-set
// fail-fast, the week/moon fail-fast, and prefers-reduced-motion support — all come from the stage, so
// loop / academy conversations stay byte-equivalent (the shared runConversation / runAssistantSseStream /
// renderMessageStream / messageHistory are untouched) and the daytime 会話専用画面 can reuse the same
// stage. The routing turn execution + in-turn dispatch / drain-on-exit seams stay in the consumer
// functions below, driving the backend contract exactly (same /api/conversation stream / end endpoints,
// routing turn body with the hub conversation id, the routing_draining signal, and the shared
// performRoutingTurnDispatch / endRoutingConversation navigation).
// ─────────────────────────────────────────────────────────────────────────────

const ROUTING_HUB_TOTAL_WEEKS = 50;

// 読みポーズ: 最終発言 (行き先確定ターンのルミの見送り / 達成自動終了ターンの切上げ発言 / 競売3ロット目決着の最終
// 発話) が出揃ってから、それを読むための間をこの長さだけ取り、その後に画面遷移 (ロード画面 / 閉場ビュー) へ進む。
// backend の後処理 drain はこのポーズ中に裏で進んでいてよい (frontend は遷移タイミングを遅らせるだけで、backend
// 契約・SSE イベント順序は不変)。定数はここ1箇所だけに定義し、hub 見送り (beginSendoffReadingPause)・昼会話の達成
// 自動終了 (beginAchievementReadingPause)・競売の閉場 (resolveAuctionCurrentLot) が単一ソースで共有する — 5000
// リテラルの二重宣言は作らない。
const DRAIN_READING_PAUSE_MS = 5000;

// The routing hub info drawer's fixed category set (自分/バディ/エネミー/持ち物/お金) + their titles. The
// stage validates a category against this set (fail-fast on anything else) before rendering it.
const ROUTING_HUB_CATEGORY_TITLES = Object.freeze({
  self: '自分',
  buddy: 'バディー',
  enemy: 'エネミー',
  inventory: '持ち物',
  money: 'お金',
  diary: '日記',
  library: '収蔵庫'
});

// The terrace: the hub's place-name glow and peek, the send-off curtain, the returned week's fading place, and the left
// rail's switching while a rail screen is open (hubTerrace.js).
const hubTerrace = createHubTerrace();

// The routing hub conversation stage. Axis 1 (scope/theme): the #routing-hub-* selectors, the
// /canonical/routing category icons, and a deep-night starfield ambient. Axis 2 (conversation type): the
// ルミ persona visual (standee/speaker), the routing actor identity, the routing runtime week, and the
// five info categories + their renderers. Injected deps are the shared app helpers so the module stays
// decoupled from app.js. The routing-specific turn execution / dispatch stays in the consumer below.
const routingHubStage = createConversationStage({
  screenSelector: '#routing-hub-screen',
  streamSelector: '#routing-hub-message-stream',
  statusSelector: '#routing-hub-status',
  controlSelectors: ['#routing-hub-send', '#routing-hub-end', '#routing-hub-input'],
  standeeSelector: '#routing-hub-standee',
  weekSelector: '#routing-hub-week',
  weekTotal: ROUTING_HUB_TOTAL_WEEKS,
  weekLabel: (week, total) => `第${week}週 / ${total}`,
  // The routing runtime week source (fail-fast on missing/invalid elapsed_weeks lives in the stage's
  // conversationStageWeek — week 1 fabrication / silent clamp is not introduced). The graduation guide week
  // reads 第50週 / 50 through this same derivation with no special-casing: the guide holds elapsed_weeks at 49,
  // so elapsed_weeks+1 is already 第50週.
  currentWeek: () => conversationStageWeek(currentRuntimeState?.elapsed_weeks),
  personaVisual: () => routingPersonaVisual,
  standeeAlt: (persona) => `${persona.display_name ?? 'ルーティング案内役'}の立ち絵`,
  assistantIdentity: () => ({ character_id: activeCharacterId, character_name: activeCharacter().display_name }),
  refresh: () => refresh(),
  ambient: createStarfieldAmbient({ canvasSelector: '#routing-hub-starfield', starColorRgb: '207, 218, 255', starCount: 90 }),
  infoPopupSelector: '#routing-hub-info-popup',
  infoTitleSelector: '#routing-hub-info-popup-title',
  infoBodySelector: '#routing-hub-info-popup-body',
  infoIconSelector: '#routing-hub-info-popup-icon',
  categoryButtonSelector: '.routing-hub-category-button',
  categoryDataKey: 'routingCategory',
  categoryTitles: ROUTING_HUB_CATEGORY_TITLES,
  categoryIconUrl: (category) => `/canonical/routing/icons/${category}.png`,
  categoryRenderers: {
    // self is a person panel: the shared parameter groups (the academy room / training mechanism) over a validated
    // parameter source, then the hero's 装備欄 (target 'player') below. The routing silver/starlight skin comes from
    // the drawer-scoped CSS. A missing player_parameters is broken routing-home state — fail fast (no ?? {}).
    self: (bodyEl) => renderRoutingHubSelfInto(bodyEl),
    buddy: (bodyEl) => renderRoutingHubBuddyInto(bodyEl),
    enemy: (bodyEl) => renderRoutingHubEnemiesInto(bodyEl),
    inventory: (bodyEl) => renderRoutingHubInventoryInto(bodyEl),
    // money's only data source is currentInventory.money (validated by the caller — no default-value
    // fallback); moneyText is the shared G formatter, applied by renderRoutingHubMoneyInto.
    money: (bodyEl) => {
      if (!currentInventory || typeof currentInventory.money === 'undefined') {
        throw new Error(`routing hub money info requires currentInventory.money, got ${JSON.stringify(currentInventory?.money)}`);
      }
      renderRoutingHubMoneyInto(bodyEl, currentInventory.money);
    },
    // diary opens on the roster picker (select a character → their journal); a fetch failure is routed to
    // reportError by the async loader (the sync renderer body only lays out the picker).
    diary: (bodyEl) => renderRoutingHubDiaryInto(bodyEl),
    // 収蔵庫 (hub-only) opens straight into an async load of the saved-fragment shelf (the diary async-category
    // grammar: a loading card shows synchronously, the async loader fills the shelf, a fetch failure → reportError).
    library: (bodyEl) => renderRoutingHubLibraryCollectionInto(bodyEl)
  }
}, {
  displayMessages,
  // The terrace marks the destination names in the guide's words as the rows are drawn (and watches for the send-off's
  // last piece to be lit).
  createMessageRows: (displayList, popFromDisplayIndex, allowEdit) => hubTerrace.markRows(createMessageRows(displayList, popFromDisplayIndex, allowEdit)),
  messagesFromConversation,
  conversationPopupCooldownMs,
  sleep,
  setActorImageSource
});

// The routing hub speaker name (ルミ, relayed through the chat bubbles) opens a routing-styled character popup:
// the routing persona standee (一枚絵) + name, no ability section (the routing persona is a non-selectable actor
// with no parameters). The routing_persona_visual summary is the only profile-like frontend data, and its sole
// such field is the display name (no title / intro is sent to the frontend), so — per the task's
// "データが無い項目は出さない" — only the name is shown, never a fabricated field. Uses the shared
// characterSceneStandeeUrl helper and the same [hidden]-toggle modal流儀 / node guards as the info drawer; a
// missing routing persona registration (routingPersonaActor throws) or popup markup is broken state (fail-fast).
function openRoutingHubCharacterPopup() {
  const persona = routingPersonaActor();
  const popup = document.querySelector('#routing-hub-character-popup');
  const title = document.querySelector('#routing-hub-character-popup-title');
  const standee = document.querySelector('#routing-hub-character-popup-standee');
  if (!popup || !title || !standee) {
    throw new Error('routing hub character popup nodes are missing (broken markup wiring)');
  }
  title.textContent = persona.display_name;
  standee.alt = `${persona.display_name}の一枚絵`;
  setActorImageSource(standee, characterSceneStandeeUrl(persona));
  popup.hidden = false;
}

// Close the routing hub character popup. Fail-fast on missing popup markup (broken wiring), mirroring the
// stage / info popup close contracts rather than silently succeeding.
function closeRoutingHubCharacterPopup() {
  const popup = document.querySelector('#routing-hub-character-popup');
  if (!popup) {
    throw new Error('routing hub character popup node #routing-hub-character-popup is missing (broken markup wiring)');
  }
  popup.hidden = true;
}

// Clean routing hub turn stream. Mirrors the backend SSE contract but drives one 統一出現規律: every
// 吹き出し種別 (主人公の発話/地の文・ルミの発話/地の文・見送り発話) is revealed through a single
// cooldown-paced queue as 完成した吹き出し単位 — never partial characters — so nothing streams in char by
// char and multiple 吹き出しが一度に届いても等間隔で順に出る。A routing hub turn never carries a field stage
// move, so there is no stage-move branch. 見送り読みポーズ (行き先確定ターン): the ~5s reading pause starts the
// moment routing_draining reveals the dispatch mid-stream and runs CONCURRENTLY with the backend drain — if it
// elapses before the drain delivers the result it hands off to the drain loading screen and waits for the
// result under it, otherwise the hub stays visible for the whole pause; either way the drained result then
// hands off to performRoutingTurnDispatch. A non-dispatch turn just commits the authoritative conversation and
// settles the hub.
async function runRoutingHubTurnStream({ playerInput, provider }) {
  const endpoint = '/api/conversation/stream';
  const body = routingTurnRequestBody({ player_input: playerInput, provider });
  const baseMessages = [...routingHubStage.surface.getHistory()];
  const reveal = routingHubStage.createTurnReveal(baseMessages);
  // 主人公の発話・地の文 も同じ規律に乗せる: enqueue the player's own utterance as the first 吹き出し単位 so a
  // split 発話+地の文 pops in ポンポンと順に (not both at once), matching ルミの応答 cadence.
  reveal.enqueue(displayMessages([{ role: 'user', content: playerInput }]));
  let expression = 'neutral';
  let assistantText = '';
  let assistantSegmentCount = 0;
  // The last complete assistant message: on a dispatch turn, the send-off words the terrace waits to see lit.
  let lastAssistantContent = '';
  let finalResult = null;
  // 見送り読みポーズ (行き先確定ターン) の並行制御。sendoffReadingPause は routing_draining で1回だけ起動する
  // 読みポーズの promise、drainLoadingShown はそのポーズが drain ロード画面を先に出したか (result より先にポーズが
  // 満了したか) の記録、streamFailed は error 後にそのロード画面表示を抑止するためのフラグ。
  let sendoffReadingPause = null;
  // 見送り読みポーズ (卒業ガイドで学院の人を締めくくり相手に確定したターン, routing phase 2 hand-off) の並行制御。
  // graduation_guide_draining で1回だけ起動する読みポーズの promise。dispatch の sendoffReadingPause と同じ規律だが、遷移先が
  // (行き先ではなく) 選択キャラの卒業 event 会話で、pause 満了先着のロード画面が会話へ移るあいだの夜になる点だけ異なる。1ターン
  // につき dispatch と selection のどちらか一方だけが起動する (両方の draining が同時に来ることはない)。案内人自身を選んだ
  // ターンは draining を伴わない (会話が露台でそのまま続く)。
  let graduationSelectionPause = null;
  let drainLoadingShown = false;
  let streamFailed = false;
  // The decided destination (routing_draining's destination_id): the 見送り読みポーズ raises its wait.
  let sendoffDestinationId = null;
  const noteLoadingDelta = createLoadingProgressDeltaThrottle();

  const assistantMessage = (content) => ({
    role: 'assistant',
    ...routingHubStage.surface.assistantIdentity(),
    content,
    face_emotion_variant_id: `face_${expression}`,
    expression
  });

  // Fold the accumulating assistant text into 完成した吹き出し単位 and enqueue only the newly-completed ones.
  // completedAssistantPrefix holds an open 地の文 / trailing plain text back until it is closed / the message
  // completes, so a segment is only ever queued once its boundary is fixed.
  function enqueueAssistantSegments(source) {
    if (!source.trim()) return;
    const segments = displayMessages([assistantMessage(source)]).filter((segment) => (segment.content ?? '').trim());
    const fresh = segments.slice(assistantSegmentCount);
    assistantSegmentCount += fresh.length;
    reveal.enqueue(fresh);
  }

  // 見送り読みポーズ pipeline. routing_draining が「このターンは行き先確定で、送り出しの吹き出しは全て enqueue 済み、
  // これから backend の後処理 drain が走る」ことを告げた瞬間に起動する: 送り出しの吹き出しが全て出揃ったら (reveal.drain)
  // ~5秒の読みポーズを取るが、それを backend drain と並行して走らせる (drain の後に直列で走らせない)。ポーズが drain 完了
  // (result 到着) より先に満了したら、drain ロード画面へ自分で hand off し、まだ開いている stream が result を
  // その下で受け取る。result が先に着けばハブ表示のまま満了を待ち、下の dispatch 分岐が hand off する。ターンにつき1回だけ。
  function beginSendoffReadingPause() {
    if (sendoffReadingPause) return;
    sendoffReadingPause = (async () => {
      await reveal.drain();
      await sleep(DRAIN_READING_PAUSE_MS);
      // 5秒経過。drain がまだ result を返していなければ、ここで待ちに入り、その下で result を待ち続ける（行き先へは
      // 送り出しの幕の上の待ち、区切りは drain ロード画面）。result が既に着いていればハブ表示のまま (dispatch 分岐が遷移する)。
      // error で終わった stream は自分でハブを復元するので、その後に待ちを出さない。
      if (!finalResult && !streamFailed) {
        if (sendoffDestinationId === 'title') showRoutingDrainLoadingScreen();
        else raiseSendoffPlaceVeil(sendoffDestinationId);
        drainLoadingShown = true;
      }
    })();
  }

  // 見送り読みポーズ pipeline for the graduation guide selection of an academy person (routing phase 2).
  // graduation_guide_draining は「このターンは締めくくり相手 (学院の人) が確定し、ルミの見送りの吹き出しは全て enqueue 済み、
  // これから backend が hub 会話を finalize して選択キャラの卒業 event を起こす」ことを告げる (routing_draining と同層)。
  // beginSendoffReadingPause と同一の並行規律で、見送りが出揃ったら (reveal.drain) ~5秒読みポーズを backend drain と並行に
  // 取り、pause が先着したら会話へ移るあいだの夜へ hand off して result をその下で待つ。ターンにつき1回だけ。
  function beginGraduationSelectionPause(characterId) {
    if (graduationSelectionPause) return;
    if (typeof characterId !== 'string' || characterId === '' || characterId === ROUTING_PERSONA_CHARACTER_ID) {
      throw new Error(`routing hub stream: graduation_guide_draining must name an academy person (got ${JSON.stringify(characterId)})`);
    }
    graduationSelectionPause = (async () => {
      await reveal.drain();
      await sleep(DRAIN_READING_PAUSE_MS);
      if (!finalResult && !streamFailed) {
        showGraduationEventPassageLoadingScreen();
        drainLoadingShown = true;
      }
    })();
  }

  function handleBlock(block) {
    const event = block.split('\n').find((line) => line.startsWith('event: '))?.slice(7);
    const dataText = block.split('\n').find((line) => line.startsWith('data: '))?.slice(6);
    const data = dataText ? JSON.parse(dataText) : null;
    if (event === 'assistant_emotion') expression = data.expression ?? 'neutral';
    if (event === 'assistant_delta') {
      noteLoadingDelta();
      assistantText += data.delta;
      enqueueAssistantSegments(completedAssistantPrefix(assistantText));
    }
    if (event === 'assistant_complete') {
      notifyAcademyLoadingProgress();
      expression = data.expression ?? expression;
      assistantText = data.content ?? assistantText;
      lastAssistantContent = assistantText;
      enqueueAssistantSegments(assistantText);
      // Reset per-assistant-message accounting so a second assistant_complete (e.g. a follow-up 吹き出し)
      // queues its own segments from scratch.
      assistantText = '';
      assistantSegmentCount = 0;
    }
    // routing_draining marks mid-stream that this is a 行き先確定 (dispatch) turn: the send-off 吹き出し are all
    // enqueued and the backend now runs its pending-finalization drain before the result. Start the 見送り読み
    // ポーズ NOW so the ~5s read runs concurrently with that drain instead of serially after it; the pause raises
    // the drain loading screen itself only if the drain outlasts it (backend 契約・SSE イベント順序は不変).
    if (event === 'routing_draining') {
      // The terrace opens the decided destination (the drain signal's destination_id, not a name the words mentioned).
      hubTerrace.beginSendoff(data.destination_id, lastAssistantContent, sendoffCurtainPlacement(data.destination_id));
      sendoffDestinationId = data.destination_id;
      beginSendoffReadingPause();
      notifyAcademyLoadingProgress();
    }
    // graduation_guide_draining marks mid-stream that this turn confirmed an academy person as the graduation partner:
    // ルミの見送りの吹き出し are all enqueued and the backend now finalizes the hub conversation + starts the character's
    // graduation event before the result. Start the graduation 見送り読みポーズ NOW so the ~5s read overlaps that
    // drain (same concurrency as routing_draining), raising the conversation passage only if the drain outlasts the
    // read.
    if (event === 'graduation_guide_draining') {
      beginGraduationSelectionPause(data.character_id);
      notifyAcademyLoadingProgress();
    }
    // finalization_progress: a block boundary of the post-turn drain running concurrently with the 見送り読み
    // ポーズ. Once the drain outlasts the pause and the loading screen is raised, each boundary advances the
    // constellation one edge (no-op while the loader is not yet shown — same guard as every other notify).
    if (event === 'finalization_progress') notifyAcademyLoadingProgress();
    if (event === 'result') {
      finalResult = data;
      notifyAcademyLoadingProgress();
    }
    // PROMPT_PREWARM_FAILED arrives after the turn was written: adopt the written turn like a result (the failure
    // rides on it for the screen's banner). Every other error fails the turn.
    if (event === 'error') {
      if (data?.error_code !== PROMPT_PREWARM_FAILED_ERROR_CODE) throw createApiError({ url: endpoint, status: 503, payload: data, fallbackText: data?.error ?? '' });
      finalResult = promptPrewarmFailedTurnResult({ url: endpoint, data });
    }
  }

  try {
    const response = await fetch(endpoint, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(body)
    });
    if (!response.ok) {
      const text = await response.text();
      throw createApiError({ url: endpoint, status: response.status, payload: parseJsonText(text), fallbackText: text });
    }
    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffer = '';
    while (true) {
      const { value, done } = await reader.read();
      buffer += decoder.decode(value ?? new Uint8Array(), { stream: !done });
      const blocks = buffer.split('\n\n');
      buffer = blocks.pop() ?? '';
      for (const block of blocks) {
        if (block.trim()) handleBlock(block);
      }
      if (done) break;
    }
    if (buffer.trim()) handleBlock(buffer);
  } catch (error) {
    // Stop the reveal queue so a failed send's restore (runRoutingHubConversation) is not overwritten by a
    // late paced render, and mark the stream failed so a concurrent 見送り読みポーズ (started if routing_draining
    // had already fired) does not raise the drain loading screen after the hub has been restored.
    streamFailed = true;
    reveal.cancel();
    // A wait already standing over the send-off curtain sinks into the night before the curtain lifts (a settings-redirect
    // failure leaves for the settings screen, which takes the wait down).
    if (placeVeilWaiting() && settingsRedirectErrorMessage(error) == null) await stopPlaceVeil();
    hubTerrace.abortSendoff(currentRuntimeState);
    throw error;
  }
  if (!finalResult) throw new Error('routing hub stream ended without a final result');

  const routingDispatch = finalResult.routing_dispatch ?? null;
  const guideSelection = finalResult.routing_graduation_guide_selection ?? null;

  // Backend contract pairing: routing_draining (which starts the 見送り読みポーズ) is emitted iff this turn
  // dispatches, i.e. iff the result carries routing_dispatch. Enforce the pairing rather than silently
  // tolerating a half-signalled stream (a dispatch result with no preceding drain signal, or a drain signal
  // with no dispatch).
  if (Boolean(routingDispatch) !== Boolean(sendoffReadingPause)) {
    throw new Error(`routing hub stream: routing_draining / routing_dispatch mismatch (draining=${Boolean(sendoffReadingPause)}, dispatch=${Boolean(routingDispatch)})`);
  }
  // The mirror pairing for the graduation guide selection: graduation_guide_draining (which starts the
  // graduation 見送り読みポーズ) is emitted iff this turn confirmed an academy person as the partner, i.e. iff the result
  // carries routing_graduation_guide_selection naming someone other than the 案内人. A half-signalled selection stream
  // fails fast the same way.
  const academyPersonSelection = Boolean(guideSelection) && guideSelection.character_id !== ROUTING_PERSONA_CHARACTER_ID;
  if (academyPersonSelection !== Boolean(graduationSelectionPause)) {
    throw new Error(`routing hub stream: graduation_guide_draining / routing_graduation_guide_selection mismatch (draining=${Boolean(graduationSelectionPause)}, selection=${JSON.stringify(guideSelection?.character_id ?? null)})`);
  }

  if (academyPersonSelection) {
    // 学院の人を締めくくり相手に確定したターン (routing phase 2). The graduation 見送り読みポーズ has been running concurrently
    // with the backend drain (hub finalize + graduation event start) since graduation_guide_draining. Await it: either
    // the result arrived within the ~5s pause (hub stayed visible) or the pause elapsed first and already began the
    // conversation passage (drainLoadingShown). Drop the hub actor/id, then open the selected character's event.
    await graduationSelectionPause;
    clearRoutingHubConversation();
    await startRoutingGraduationEndingFromSelection({ result: finalResult, loadingAlreadyVisible: drainLoadingShown });
    routingHubStage.setStatus('');
    return finalResult;
  }

  if (routingDispatch) {
    // 行き先確定ターン。見送り読みポーズ has been running concurrently with the backend drain since routing_draining.
    // Wait for it to finish: either the result arrived first and the hub stayed visible for the whole ~5s (hand
    // off now), or the pause elapsed first and already handed off to the drain loading screen (drainLoadingShown)
    // and we are here now that the drain delivered the result.
    await sendoffReadingPause;
    routingHubStage.surface.commitState(finalResult);
    routingHubStage.renderStream(routingHubStage.surface.getHistory());
    // Clear the hub status BEFORE dispatching: a failed arrival returns to the hub inside the dispatch and writes its
    // failure notice there, which a clear after the dispatch would wipe.
    routingHubStage.setStatus('');
    await performRoutingTurnDispatch({ result: finalResult, dispatch: routingDispatch, overSendoff: true });
    return finalResult;
  }

  // Non-dispatch turn (byte-equivalent to the pre-concurrency path): let every queued 吹き出し (player utterance
  // + ルミの応答) finish revealing on the shared cadence, adopt the authoritative state, and settle the hub. The turn
  // that chooses the 案内人 herself is one of these: the conversation goes on on the terrace as the graduation
  // conversation, and the result's state (the graduation started, the week held) is adopted here.
  await reveal.drain();
  if (guideSelection) {
    if (!finalResult.state || typeof finalResult.state !== 'object') {
      throw new Error(`routing hub stream: the 案内人 selection is missing the graduation state (got ${JSON.stringify(finalResult.state)})`);
    }
    currentRuntimeState = finalResult.state;
    markTerraceGraduation(true);
  }
  routingHubStage.surface.commitState(finalResult);
  routingHubStage.renderStream(routingHubStage.surface.getHistory());
  routingHubStage.setStatus('');
  return finalResult;
}

// Send a routing hub turn. Snapshots the committed history + input before the turn so a transport / API /
// stream failure restores both instead of leaving an unsent utterance stranded on screen with a cleared
// input. The player's utterance is not rendered optimistically here — the turn's shared reveal queue reveals
// it as the first 吹き出し単位 on the same 統一出現規律 as ルミの応答.
async function runRoutingHubConversation() {
  // The hub-start failure landing has no conversation to send into: the send stays closed there.
  if (routingFinalizeBlockedExit || routingHubStartFailure) return;
  if (conversationRequestInFlight) {
    showProcessingToast();
    return;
  }
  const input = document.querySelector('#routing-hub-input');
  const playerInput = (input?.value ?? '').trim();
  if (!playerInput) return;
  const historySnapshot = [...routingHubStage.surface.getHistory()];
  const inputSnapshot = input ? input.value : '';
  conversationRequestInFlight = true;
  setRoutingHubControlsDisabled(true);
  const provider = conversationProvider();
  try {
    if (input) input.value = '';
    const result = await runRoutingHubTurnStream({ playerInput, provider });
    // A decided turn dispatched in-turn (performRoutingTurnDispatch already navigated to the
    // destination after the queue drained); do not refresh the closed hub.
    if (isRoutingTurnDispatch(result)) return;
    // A confirmed academy person (routing phase 2): runRoutingHubTurnStream already navigated to the character's
    // graduation event on the daytime screen after the queue drained; do not auto-end or refresh the closed hub (same
    // discipline as the dispatch return above). Choosing the 案内人 keeps the terrace and goes on below.
    if (isRoutingGraduationHandOff(result)) return;
    if (await autoEndConversationAfterFinalReply(result)) return;
    await refresh();
    if (result.prompt_prewarm_error) routingHubStage.setStatus(errorDisplayMessage(result.prompt_prewarm_error), { tone: 'error' });
  } catch (error) {
    // A send-off that fails after its curtain began lifts the curtain before the hub is restored; a wait standing over
    // the curtain first sinks into the night.
    if (placeVeilWaiting() && settingsRedirectErrorMessage(error) == null) await stopPlaceVeil();
    hubTerrace.abortSendoff(currentRuntimeState);
    routingHubStage.surface.setHistory(historySnapshot);
    routingHubStage.renderStream(historySnapshot);
    // A turn refused by the blocked post-processing queue is already saved, so its text does not go back into
    // the input; every other failure restores it.
    if (input && !isPendingFinalizationsBlockedError(error)) input.value = inputSnapshot;
    routingHubStage.setStatus('');
    // Invalid LLM output (and LM Studio config/connection failures) route the player to the LM settings
    // with the cause message, the same as the hub-entry path; any other failure shows the hub error banner.
    if (handleRuntimeApiError(error, { allowSettingsRedirect: true })) return;
    // Loading-residual defense line (general, NOT destination-limited): a decided turn whose 見送り読みポーズ
    // outlasted the backend drain has already handed off to the academy-loading screen
    // (showRoutingDrainLoadingScreen). If the dispatch then fails — an unknown destination, a screen/transition
    // mismatch, or any other post-loading throw — restoring the hub display above does NOT switch the active
    // screen, so the player would be stranded on the loading screen. Un-strand back to the hub, then show the
    // cause on the hub error banner — the same surface and discipline as endRoutingConversation's failed-end
    // defense, so a decision-turn failure is visible on the hub the player is returned to (the hub carries no
    // in-progress status text; the error banner is its only status line). General — gated only on the loading
    // screen being active, not on any destination id.
    if (isAcademyLoadingScreenActive()) showScreen('routing-hub');
    // An exit turn (a decided send-off, or a graduation-guide partner) whose drain the blocked post-processing
    // queue refused shows the emergency exit instead of the cause. The turn itself is already saved: after the
    // retry a send-off resumes its dispatch; a guide turn has no server route to rebuild the selection, so it
    // stays on the hub.
    if (isPendingFinalizationsBlockedError(error)) {
      showRoutingFinalizeBlockedNotice(isRoutingGraduationGuideActive()
        ? async () => focusRoutingHubInputIfContinuing()
        : resumeRoutingHubSendoffDispatch);
      return;
    }
    routingHubStage.setStatus(errorDisplayMessage(error), { tone: 'error' });
  } finally {
    conversationRequestInFlight = false;
    setRoutingHubControlsDisabled(false);
    // Non-terminal turn refocus: after re-enabling controls, restore keyboard focus to `#routing-hub-input`
    // so the next utterance can be typed without a mouse click (mirrors the lounge's runLoungePlayerTurn
    // re-enable→focus seam). The helper's 3-condition gate (hub screen active + hub conversation active +
    // input present + not disabled) makes this a no-op for every terminal exit (dispatch, graduation
    // selection, auto-end, settings redirect), so it never steals focus from the destination screen.
    focusRoutingHubInputIfContinuing();
  }
}

// ── Routing hub info drawer content builders ─────────────────────────────────
// The category renderers wired into routingHubStage.categoryRenderers (axis 2 data). The drawer
// open/switch/close, rail-select, header icon, and fixed-set fail-fast are owned by the shared stage;
// these builders paint the routing-specific category bodies with the routing-hub-info-* classes.
// Empty-state card (buddy 不在 / enemy 0件 / 持ち物なし …): the dotted picture of what is missing, set where the rows
// would begin; the title and note are its read-out name.
function routingHubInfoEmptyCard(title, note, art) {
  const card = document.createElement('div');
  card.className = 'routing-hub-info-empty-card';
  return fillWithEmptyArt(card, art, `${title}。${note}`);
}

// Count summary band atop the enemy / inventory lists.
function routingHubInfoSummary(countText, labelText) {
  const summary = document.createElement('div');
  summary.className = 'routing-hub-info-summary';
  const count = document.createElement('strong');
  count.className = 'routing-hub-info-summary-count';
  count.textContent = countText;
  const label = document.createElement('span');
  label.className = 'routing-hub-info-summary-label';
  label.textContent = labelText;
  summary.append(count, label);
  return summary;
}

function routingHubRosterFaceUrl(character) {
  return character.selection_icon_url ?? character.face_url ?? sourceSheetImageUrl({ characterId: character.character_id, view: 'face' });
}

// Meta chips (学年 / クラブ). A field with no value is omitted rather than shown as an empty chip.
function routingHubInfoMetaChips(character) {
  const row = document.createElement('div');
  row.className = 'routing-hub-info-chip-row';
  for (const value of [character.school_year, character.club]) {
    if (!value) continue;
    const chip = document.createElement('span');
    chip.className = 'routing-hub-info-chip';
    chip.textContent = value;
    row.append(chip);
  }
  return row;
}

// The routing hub self panel (自分 category): the shared parameter groups under a パラメーター heading, then the hero's
// 装備欄 (equip / unequip, target 'player') in a 装備 section named for reading only, its slot marks needing no word
// heading. Both person panels (self / buddy) share the async
// 装備欄 loader + slot 導線 (loadRoutingHubPersonEquipInto); opening either category bumps the person-equip token so
// a category switch abandons an in-flight equipment fetch / re-render. A missing player_parameters is broken
// routing-home state — fail fast (no ?? {}).
function renderRoutingHubSelfInto(bodyEl) {
  routingHubPersonEquipToken += 1; // re-opening a person category abandons any in-flight person 装備 fetch / re-render
  const parameters = currentWorld?.player_parameters;
  if (!parameters || typeof parameters !== 'object') {
    throw new Error(`routing hub self info requires currentWorld.player_parameters, got ${JSON.stringify(parameters)}`);
  }
  // ui-prose-exception: 1791169304820-a8a0bc52
  const params = routingHubInfoSection('パラメーター');
  // ui-prose-exception: 1791169304820-a8a0bc52
  params.body.append(...buildParameterGroups(parameters, abilitySigilLabel));
  const equipment = routingHubInfoReadOnlySection('装備');
  equipment.body.append(routingHubEquipmentLoadingCard());
  bodyEl.append(params.section, equipment.section);
  loadRoutingHubPersonEquipInto('self', 'player', equipment.body).catch(reportError);
}

// The routing hub buddy panel (バディー category) delegates to the async endpoint loader below.
function renderRoutingHubBuddyInto(bodyEl) {
  loadRoutingHubBuddyInto(bodyEl).catch(reportError);
}

// The routing hub buddy panel is async against the GET /api/relationships/buddy truth source (loading card
// immediately → fetch → stale-token + still-on-buddy guard), so a homunculus buddy renders instead of throwing as a
// dangling roster id. A selectable buddy keeps 現行同等 content (hero card + shared parameter groups + 装備欄); a
// homunculus buddy shows the hero card (endpoint face / name / 好感度) + 装備欄 only — its parameters live in the
// 錬成室 / ホムンクルスポップアップ, so no fabricated parameter section here. The parameter section is headed and the 装備
// section named for reading only, as on the self panel. No buddy is a titled empty-state card.
async function loadRoutingHubBuddyInto(bodyEl) {
  const token = (buddyViewFetchToken += 1);
  bodyEl.replaceChildren(routingHubInfoLoadingCard());
  const view = await fetchBuddyView();
  if (token !== buddyViewFetchToken) return;
  const popup = document.querySelector('#routing-hub-info-popup');
  if (!popup || popup.dataset.category !== 'buddy') return;
  const subject = resolveBuddyPanelSubject(view);
  // ui-prose-exception: 1790825320180-97982fce
  const buddySection = routingHubInfoSection('バディー');
  if (!subject) {
    buddySection.body.append(routingHubInfoEmptyCard('バディー記録なし', 'バディーはいません。', 'person'));
    bodyEl.replaceChildren(buddySection.section);
    return;
  }
  buddySection.body.append(routingHubBuddyHeroCard(subject));
  const nodes = [buddySection.section];
  // The parameter section is roster-derived (同 design as self); a homunculus carries no roster parameters in the
  // endpoint, so it shows no parameter section rather than fabricating one.
  if (subject.kind === 'character') {
    // ui-prose-exception: 1791169304820-a8a0bc52
    const params = routingHubInfoSection('パラメーター');
    // ui-prose-exception: 1791169304820-a8a0bc52
    params.body.append(...buildParameterGroups(subject.roster.parameters, abilitySigilLabel));
    nodes.push(params.section);
  }
  const equipment = routingHubInfoReadOnlySection('装備');
  equipment.body.append(routingHubEquipmentLoadingCard());
  nodes.push(equipment.section);
  bodyEl.replaceChildren(...nodes);
  // The person 装備欄 targets the buddy id (the backend equip target accepts a homunculus id). Bumping the
  // person-equip token here means a category switch after this point abandons the equip fetch / re-render.
  routingHubPersonEquipToken += 1;
  loadRoutingHubPersonEquipInto('buddy', subject.characterId, equipment.body).catch(reportError);
}

// The routing hub buddy hero card: a homunculus shows its endpoint face_url / display_name + a 好感度 affinity chip,
// a selectable character shows its roster face / name + 学年・クラブ meta chips (現行同等).
function routingHubBuddyHeroCard(subject) {
  const card = document.createElement('div');
  card.className = 'routing-hub-info-buddy-card';
  const portrait = document.createElement('img');
  portrait.className = 'routing-hub-info-portrait';
  const body = document.createElement('div');
  body.className = 'routing-hub-info-buddy-body';
  const name = document.createElement('strong');
  name.className = 'routing-hub-info-buddy-name';
  if (subject.kind === 'homunculus') {
    const buddy = subject.homunculus;
    portrait.src = buddy.face_url;
    portrait.alt = `${buddy.display_name}の顔`;
    name.textContent = buddy.display_name;
    const chips = document.createElement('div');
    chips.className = 'routing-hub-info-chip-row';
    chips.append(buddyAffinityChip(buddy.affinity, 'routing-hub-info-chip'));
    body.append(name, chips);
  } else {
    const buddy = subject.roster;
    portrait.src = routingHubRosterFaceUrl(buddy);
    portrait.alt = `${buddy.display_name ?? buddy.character_id}の顔`;
    name.textContent = buddy.display_name ?? buddy.character_id;
    body.append(name);
    const chips = routingHubInfoMetaChips(buddy);
    if (chips.childElementCount > 0) body.append(chips);
  }
  card.append(portrait, body);
  return card;
}

function routingHubInfoLoadingCard() {
  const card = document.createElement('div');
  card.className = 'routing-hub-info-loading';
  card.append(screenWaitMark());
  return card;
}

// Compact enemy card (face + name + meta) used in the enemy list.
function routingHubInfoRosterCard(character) {
  const card = document.createElement('div');
  card.className = 'routing-hub-info-roster-card';
  const image = document.createElement('img');
  image.className = 'routing-hub-info-roster-face';
  image.src = routingHubRosterFaceUrl(character);
  image.alt = `${character.display_name ?? character.character_id}の顔`;
  const body = document.createElement('div');
  body.className = 'routing-hub-info-roster-body';
  const name = document.createElement('strong');
  name.className = 'routing-hub-info-roster-name';
  name.textContent = character.display_name ?? character.character_id;
  const meta = document.createElement('small');
  meta.className = 'routing-hub-info-roster-meta';
  meta.textContent = [character.school_year, character.club].filter(Boolean).join(' / ') || character.character_id;
  body.append(name, meta);
  card.append(image, body);
  return card;
}

function renderRoutingHubEnemiesInto(bodyEl) {
  const enemies = resolveInfoDrawerEnemies();
  // ui-prose-exception: 1790825320180-97982fce
  const enemySection = routingHubInfoSection('エネミー');
  bodyEl.append(enemySection.section);
  if (!enemies.length) {
    enemySection.body.append(routingHubInfoEmptyCard('エネミー記録なし', '対立関係のキャラクターはいません。', 'person'));
    return;
  }
  enemySection.body.append(routingHubInfoSummary(`${enemies.length}件`, 'エネミー'));
  const list = document.createElement('div');
  list.className = 'routing-hub-info-roster-list';
  list.append(...enemies.map((enemy) => routingHubInfoRosterCard(enemy)));
  enemySection.body.append(list);
}

// Monotonic guard for the whole inventory drawer generation: each (re-)render of the inventory category bumps this
// token. An async result — a resolved GET /api/equipment OR a resolved POST /api/inventory/use re-render — commits
// only when its captured token is still current and the drawer is still on the inventory category. Switching
// category / re-opening therefore abandons an in-flight fetch / re-render rather than flashing a stale surface in
// (the same discipline as diaryFetchToken).
let routingHubInventoryToken = 0;
// Single-flight guard for the 使う 導線: a use POST is in flight for at most one item at a time (rapid double-clicks
// and cross-row clicks are dropped, preventing a duplicate POST).
let routingHubInventoryUseInFlight = false;

// The routing hub inventory category is a two-section drawer: a 装備 section (a display-only list of the owned
// equipment that is NOT currently equipped by anyone) above the 所持品欄 (the item ledger). Equipping lives on the
// person panels (自分 / バディー), so the inventory drawer only browses the un-equipped gear — the equipped pieces
// show on their owner's panel (the role division). The 装備 section shows a loading card immediately and starts the
// async loader; the 所持品欄 is built synchronously so its inventory fail-fast surfaces BEFORE any DOM mutation or
// fetch (a broken items surface throws before either section is appended). The two sections are appended in order,
// then the equipment loader runs, routing a fetch failure to reportError (and painting an in-section error card).
function renderRoutingHubInventoryInto(bodyEl) {
  routingHubInventoryToken += 1; // re-opening the inventory category abandons any in-flight equipment fetch / use re-render
  const equipment = routingHubInfoSection('装備');
  equipment.body.append(routingHubEquipmentLoadingCard());
  const items = routingHubInfoSection('持ち物');
  renderRoutingHubInventoryLedgerInto(items.body);
  bodyEl.append(equipment.section, items.section);
  loadRoutingHubInventoryEquipmentInto(equipment.body).catch(reportError);
}

// A titled drawer section ({ section, body }): the two-section inventory drawer stacks the 装備 section over the
// 持ち物 section, each a heading over the body its content renders into.
function routingHubInfoSection(titleText) {
  const section = document.createElement('section');
  section.className = 'routing-hub-info-section';
  const title = document.createElement('h4');
  title.className = 'routing-hub-info-section-title';
  title.textContent = titleText;
  const body = document.createElement('div');
  body.className = 'routing-hub-info-section-body';
  section.append(title, body);
  return { section, body };
}

// A drawer section whose name is read out only (aria-label, no heading), for content its marks already name.
function routingHubInfoReadOnlySection(name) {
  const section = document.createElement('section');
  section.className = 'routing-hub-info-section';
  section.setAttribute('aria-label', name);
  const body = document.createElement('div');
  body.className = 'routing-hub-info-section-body';
  section.append(body);
  return { section, body };
}

// 所持品欄: a 種類 count summary + a name/quantity/description ledger with optional dungeon-material meta badges,
// or a titled 持ち物なし empty-state card. A row whose enriched item carries the server-authoritative stat_effect
// meta (the same field decorateInventory attaches for a stat 霊薬; its absence is the honest "not a usable item",
// exactly like material element/tier) also carries a 使う 導線. Broken enriched item data surfaces (fail-fast)
// rather than being masked with item_id / 0 / an empty slot. `feedback` ({ message, tone }) is the transient result
// of the previous 使う (success / error) painted above the list on a re-render; absent on first open.
function renderRoutingHubInventoryLedgerInto(bodyEl, feedback = null) {
  // A valid inventory has an items array; an empty array is legitimate "no items", but a missing/invalid
  // inventory state is broken and must surface rather than read as empty.
  const items = currentInventory?.items;
  if (!Array.isArray(items)) {
    throw new Error(`routing hub inventory requires currentInventory.items array, got ${JSON.stringify(items)}`);
  }
  // The 使う result stays visible above the ledger while the list below re-renders to the new quantities.
  if (feedback) bodyEl.append(routingHubInventoryFeedbackCard(feedback));
  if (items.length === 0) {
    bodyEl.append(routingHubInfoEmptyCard('持ち物なし', '所持しているアイテムはありません。', 'pouch'));
    return;
  }
  bodyEl.append(routingHubInfoSummary(`${items.length}種類`, '持ち物'));
  const list = document.createElement('ul');
  list.className = 'routing-hub-info-ledger';
  for (const item of items) {
    // Enriched inventory items (decorateInventory) carry a non-empty name, a numeric quantity, and a
    // description string. A violation is broken state — surface it, never mask it with item_id / 0 / an
    // empty slot (no silent or default-value fallback).
    if (typeof item.name !== 'string' || item.name === '') {
      throw new Error(`routing hub inventory item requires a non-empty name, got ${JSON.stringify(item)}`);
    }
    if (typeof item.quantity !== 'number' || !Number.isFinite(item.quantity)) {
      throw new Error(`routing hub inventory item requires a numeric quantity, got ${JSON.stringify(item)}`);
    }
    if (typeof item.description !== 'string') {
      throw new Error(`routing hub inventory item requires a description string, got ${JSON.stringify(item)}`);
    }
    // usable is the server-authoritative use gate (GET /api/inventory / POST /api/inventory/use decorate it).
    // A missing flag is broken wiring, not "not usable" — surface it rather than silently hiding the 使う 導線.
    if (typeof item.usable !== 'boolean') {
      throw new Error(`routing hub inventory item requires a boolean usable flag, got ${JSON.stringify(item)}`);
    }
    // gift_category is the server-authoritative 渡す gate ('gift' | 'ally_boost' | null). A missing field is broken
    // wiring, not "not giftable" — surface it rather than silently hiding the 渡す 導線.
    if (item.gift_category !== null && item.gift_category !== 'gift' && item.gift_category !== 'ally_boost') {
      throw new Error(`routing hub inventory item requires a gift_category of gift|ally_boost|null, got ${JSON.stringify(item)}`);
    }
    const row = document.createElement('li');
    row.className = 'routing-hub-info-ledger-row';
    const head = document.createElement('div');
    head.className = 'routing-hub-info-ledger-head';
    const name = document.createElement('strong');
    name.textContent = item.name;
    const quantity = document.createElement('span');
    quantity.className = 'routing-hub-info-ledger-quantity';
    quantity.textContent = `×${item.quantity.toLocaleString('ja-JP')}`;
    head.append(name, quantity);
    row.append(head);
    const materialMeta = buildInventoryMaterialMeta(item, 'routing-hub-info-ledger-materia');
    if (materialMeta) row.append(materialMeta);
    // A description is always a string; an empty one legitimately means "no description" — omit the line
    // rather than rendering an empty slot.
    if (item.description.trim() !== '') {
      const desc = document.createElement('p');
      desc.className = 'routing-hub-info-ledger-desc';
      desc.textContent = item.description;
      row.append(desc);
    }
    // Usable items (server-authoritative `usable` flag — no item id / name hardcoding, no frontend category
    // guess) carry a 使う 導線; gift / ally_boost / dungeon_consumable / material / non-usable rows carry none.
    if (item.usable) row.append(routingHubInventoryUseAction(item, bodyEl));
    // 渡す (会話中の贈与 to the routing hub guide 案内人): shown only in a hub conversation on a gift-category item
    // (the guide holds no parameter surface, so ally_boost is excluded — the backend 400s it). The category is the
    // server-authoritative `gift_category` annotation on the item. Disabled once a gift has been delivered this hub
    // conversation (the 1会話1回 gate; the server is the final defense). The 案内人's graduation conversation on the
    // terrace is no longer a hub conversation and takes no gift (as her graduation never did), so it shows none.
    if (isRoutingHubActive() && !isRoutingGraduationEndingConversation() && item.gift_category === 'gift') {
      row.append(routingHubGiftAction(item));
    }
    list.append(row);
  }
  bodyEl.append(list);
}

// The 使う action row: 1個使う uses one unit and 全部使う uses the owned quantity, both through POST
// /api/inventory/use. bodyEl is the ledger section body the success / error re-render targets.
function routingHubInventoryUseAction(item, bodyEl) {
  const actions = document.createElement('div');
  actions.className = 'routing-hub-info-ledger-actions';
  const use = document.createElement('button');
  use.type = 'button';
  use.className = 'routing-hub-info-ledger-use';
  use.textContent = '1個使う';
  use.addEventListener('click', () => useRoutingHubInventoryItem(item.item_id, 1, use, bodyEl).catch(reportError));
  const useAll = document.createElement('button');
  useAll.type = 'button';
  useAll.className = 'routing-hub-info-ledger-use';
  useAll.textContent = '全部使う';
  useAll.addEventListener('click', () => useRoutingHubInventoryItem(item.item_id, item.quantity, useAll, bodyEl).catch(reportError));
  actions.append(use, useAll);
  return actions;
}

// The transient 使う feedback line (role=status): success reports what was used and the parameter it moved
// (server-authoritative result.effect — the front never recomputes the value); error surfaces the fail-fast API
// message (item_is_not_usable / insufficient / transport) instead of a silent failure. Toned by data-tone.
function routingHubInventoryFeedbackCard({ message, tone }) {
  const card = document.createElement('p');
  card.className = 'routing-hub-info-ledger-feedback';
  card.dataset.tone = tone;
  card.setAttribute('role', 'status');
  card.setAttribute('aria-live', 'polite');
  card.textContent = message;
  return card;
}

// Success message reads the server-authoritative POST result — what was used and how the parameter(s) moved. The
// client never recomputes a value. Two server shapes: a 購買 stat 霊薬 returns a single `effect` (with its own
// used_quantity); an alchemy self_boost returns an `effects` array (one entry per raised parameter) plus a
// top-level used_quantity. A result carrying neither is broken and fails fast (no silent fallback).
function routingHubInventoryUseMessage(result) {
  const { item } = result;
  if (result.effect) {
    const { effect } = result;
    return `${item.name}を${effect.used_quantity}個使いました（${effect.label} ${effect.before} → ${effect.after}）`;
  }
  if (!Array.isArray(result.effects)) {
    throw new Error(`inventory use result requires an effect or effects, got ${JSON.stringify(result)}`);
  }
  const moves = result.effects.map((effect) => `${effect.label} ${effect.before} → ${effect.after}`).join(' / ');
  return `${item.name}を${result.used_quantity}個使いました（${moves}）`;
}

// Use `quantity` units of an item from the ledger (1 for 1個使う, the owned count for 全部使う). Single-flight
// (drops overlapping clicks across both buttons) and disables the pressed button immediately (no duplicate POST).
// On success the global inventory/world are refreshed from the authoritative POST
// result, then — only while the drawer is still this inventory generation (token + still on inventory) — the ledger
// re-renders to the new quantities with a success line; a used-up item's row disappears. On error the ledger
// re-renders carrying the fail-fast API message (never a silent failure). A result that lands after a category
// switch / re-open still updates global state, and an error there re-throws to reportError.
async function useRoutingHubInventoryItem(itemId, quantity, button, bodyEl) {
  if (routingHubInventoryUseInFlight) return;
  routingHubInventoryUseInFlight = true;
  button.disabled = true;
  const token = routingHubInventoryToken;
  try {
    const result = await postJson('/api/inventory/use', { item_id: itemId, quantity });
    currentInventory = result.inventory;
    currentWorld = result.world;
    if (routingHubInventoryIsCurrent(token)) {
      bodyEl.replaceChildren();
      renderRoutingHubInventoryLedgerInto(bodyEl, { message: routingHubInventoryUseMessage(result), tone: 'success' });
    }
  } catch (error) {
    if (!routingHubInventoryIsCurrent(token)) throw error;
    bodyEl.replaceChildren();
    renderRoutingHubInventoryLedgerInto(bodyEl, { message: errorDisplayMessage(error), tone: 'error' });
  } finally {
    routingHubInventoryUseInFlight = false;
  }
}

// ── 会話中の贈与（渡す・ハブの案内人）───────────────────────────────────────────
// The routing hub inventory drawer's 渡す affordance hands a gift to the current hub conversation partner (the
// routing persona 案内人 `lina`) over POST /api/conversation/gift. It is shown only when a gift is possible: an
// active hub conversation (isRoutingHubActive — the backend accepts the guide via its routing_hub snapshot, and
// 409s ROUTING_MODE_REQUIRED off routing) on a gift-category item. Unlike the daytime drawer (a selectable roster
// partner accepts both gift + ally_boost), the guide holds no parameter surface, so only the affinity `gift`
// category is deliverable here (an ally_boost 400s GIFT_ITEM_NOT_ELIGIBLE) and no 渡す button is shown off it.
// The 1会話1回 gate is keyed on the hub conversation id, so it resets by itself when the next hub conversation
// starts. The gift response effect / reaction record shape is byte-identical to the daytime (roster) gift, so the
// shared conversationGiftHandoverNarrationText / conversationGiftEffectMessage / conversationGiftErrorMessage
// helpers are reused; only the reveal targets the hub stage (clean-chat: the shared academy chat is never touched).

// True once a gift has been delivered in the current hub conversation (client mirror of the backend
// GIFT_ALREADY_GIVEN gate). Keyed on the hub conversation id, so it resets by itself when the next hub
// conversation starts. isRoutingHubActive already requires a concrete hub conversation id, so a false gate on no
// hub conversation is impossible (giftGivenConversationId is compared to the live hub id only when hub-active).
function routingHubGiftAlreadyGiven() {
  return isRoutingHubActive() && giftGivenConversationId === routingHubConversationId;
}

// The 渡す 導線 on a gift-category ledger row: hands the owned gift to the hub guide. Disabled by the 1会話1回 gate
// once a gift has been delivered this hub conversation (the server is the final defense).
function routingHubGiftAction(item) {
  const give = document.createElement('button');
  give.type = 'button';
  give.className = 'routing-hub-info-ledger-give';
  give.textContent = '渡す';
  const alreadyGiven = routingHubGiftAlreadyGiven();
  give.disabled = alreadyGiven;
  if (alreadyGiven) give.title = 'この会話ではもう渡しています';
  give.addEventListener('click', () => handleRoutingHubGift(item).catch(reportError));
  return give;
}

// Reveal the hand-over 地の文 + the guide's reaction on the hub stream through the shared cooldown-paced reveal
// queue (one 吹き出し単位 at a time, the same cadence a normal hub turn uses). The two appended messages match the
// record shape messagesFromConversation produces (a user narration + an assistant reaction with no emotion), so
// the next turn's authoritative commitState rebuild is seamless. Reveals through the routing hub stage's own
// surface only — the shared academy chat (messageHistory / academyChatSurface) is never touched (clean-chat).
async function revealRoutingHubGift(result) {
  const reactionText = String(result?.reaction_text ?? '').trim();
  if (!reactionText) throw new Error(`routing hub gift reveal requires reaction_text, got ${JSON.stringify(result?.reaction_text)}`);
  const baseMessages = [...routingHubStage.surface.getHistory()];
  const handover = { role: 'user', content: conversationGiftHandoverNarrationText(result.item.name) };
  // The reaction carries no emotion (the backend appends the record message without one, and the reveal must not
  // force a neutral icon literal — createMessageRows / messagesFromConversation default a missing emotion to the
  // neutral face), so it renders identically to the record the next commitState rebuild adopts.
  const reaction = {
    role: 'assistant',
    ...routingHubStage.surface.assistantIdentity(),
    content: reactionText
  };
  const reveal = routingHubStage.createTurnReveal(baseMessages);
  reveal.enqueue(displayMessages([handover]));
  reveal.enqueue(displayMessages([reaction]));
  await reveal.drain();
  routingHubStage.surface.setHistory([...baseMessages, handover, reaction]);
  routingHubStage.renderStream(routingHubStage.surface.getHistory());
}

// Hand the item over to the hub guide: confirm → close the drawer so the reaction is visible on the stream →
// POST /api/conversation/gift → reveal the reaction + toast the effect → refresh. The shared
// conversationRequestInFlight + the dedicated conversationGiftInFlight single-flight guard keep a gift from
// overlapping a turn or firing twice. A 503 leaves the item unconsumed and retryable (the explicit 未消費 line).
async function handleRoutingHubGift(item) {
  if (conversationRequestInFlight || conversationGiftInFlight) {
    showProcessingToast();
    return;
  }
  // Defense: the render gate already hides the button off these, but re-check before the network call so a stale
  // click (e.g. the drawer left open across a conversation change) never fires an out-of-context gift.
  if (!isRoutingHubActive() || routingHubGiftAlreadyGiven()) return;
  const partnerName = activeCharacter().display_name;
  if (!window.confirm(`「${item.name}」を${partnerName}に渡しますか？`)) return;
  conversationGiftInFlight = true;
  conversationRequestInFlight = true;
  setRoutingHubControlsDisabled(true);
  routingHubStage.setStatus('');
  routingHubStage.closeInfo();
  try {
    const { result, state } = await postJson('/api/conversation/gift', { item_id: item.item_id });
    currentRuntimeState = state ?? currentRuntimeState;
    currentInventory = result.inventory;
    giftGivenConversationId = routingHubConversationId;
    await revealRoutingHubGift(result);
    showEconomyMessage(conversationGiftEffectMessage(result));
    await refresh().catch(reportError);
  } catch (error) {
    if (handleRuntimeApiError(error, { allowSettingsRedirect: true })) return;
    routingHubStage.setStatus(conversationGiftErrorMessage(error), { tone: 'error' });
  } finally {
    conversationGiftInFlight = false;
    conversationRequestInFlight = false;
    setRoutingHubControlsDisabled(false);
  }
}

// ── 装備欄 (routing hub) ──────────────────────────────────────────────────────
// GET /api/equipment is the single source of truth — the SAME authoritative snapshot the practical-dungeon entry
// equips through (validated fail-fast by the shared validateDungeonEquipmentSnapshot). Two surfaces consume it:
//   • the person panels (自分 / バディー): the owner's two slots (weapon / amulet) with the equip / unequip 導線
//     (target 'player' or the buddy character_id), the SAME button grammar as the dungeon entry #dungeon-equipment —
//     an empty slot offers the owned instances of its kind as 装備 candidate buttons (a click POSTs
//     /api/equipment/equip); an occupied slot carries a 解除 button (POST /api/equipment/unequip). A successful
//     action re-fetches GET /api/equipment and re-renders the section; a single-flight guard blocks a double POST;
//     the stale guard abandons a result that lands after a category switch / re-open.
//   • the inventory drawer 装備 section: a display-only list of the owned equipment NOT equipped by any owner
//     (filtered by the authoritative sales[].equipped flag) — no slots, no equip 導線 (equipping is the person
//     panels' job). The equipped pieces show on their owner's panel (the role division).
// Every label reads the shared workshopArrivalClient closed-set vocabulary through dungeonEquipmentInstanceMetaText
// (no private translation), and every equipped/owned card opens the shared 装備 detail popup.

function routingHubEquipmentLoadingCard() {
  const card = document.createElement('div');
  card.className = 'routing-hub-info-equip-loading';
  card.append(screenWaitMark());
  return card;
}

// A GET failure / a malformed snapshot paints this explicit in-section error (never a silent empty / placeholder
// degrade); the loader ALSO re-throws so the failure surfaces through reportError.
function routingHubEquipmentErrorCard() {
  const card = document.createElement('div');
  card.className = 'routing-hub-info-equip-error';
  const title = document.createElement('strong');
  title.className = 'routing-hub-info-equip-error-title';
  title.textContent = '装備を読み込めませんでした';
  const note = document.createElement('p');
  note.className = 'routing-hub-info-equip-error-note';
  note.textContent = '装備情報の取得に失敗しました。時間をおいて開き直してください。';
  card.append(title, note);
  return card;
}

// The stale-race guard shared by the whole inventory drawer generation: a resolved async result (equipment fetch OR
// use re-render) commits only when its captured token is still the live one AND the drawer is still on the inventory
// category (a category switch / re-open abandons the in-flight fetch / re-render).
function routingHubInventoryIsCurrent(token) {
  if (token !== routingHubInventoryToken) return false;
  const popup = document.querySelector('#routing-hub-info-popup');
  return Boolean(popup) && popup.dataset.category === 'inventory';
}

function validateEquipmentSales(rawSales, instances) {
  if (!Array.isArray(rawSales)) {
    throw new Error(`equipment snapshot: sales must be an array (got ${JSON.stringify(rawSales)})`);
  }
  if (rawSales.length !== instances.length) {
    throw new Error(`equipment snapshot: sales length ${rawSales.length} must match instances length ${instances.length}`);
  }
  return instances.map((view, index) => {
    const sale = rawSales[index];
    if (!sale || typeof sale !== 'object' || Array.isArray(sale)) {
      throw new Error(`equipment snapshot: sales[${index}] must be an object (got ${JSON.stringify(sale)})`);
    }
    if (sale.instance_id !== view.instance.instance_id) {
      throw new Error(`equipment snapshot: sales[${index}].instance_id ${JSON.stringify(sale.instance_id)} must match instances[${index}] ${JSON.stringify(view.instance.instance_id)}`);
    }
    if (!Number.isInteger(sale.sell_price) || sale.sell_price <= 0) {
      throw new Error(`equipment snapshot: sales[${index}].sell_price must be a positive integer (got ${JSON.stringify(sale.sell_price)})`);
    }
    if (typeof sale.equipped !== 'boolean') {
      throw new Error(`equipment snapshot: sales[${index}].equipped must be a boolean (got ${JSON.stringify(sale.equipped)})`);
    }
    return { view: view, sellPrice: sale.sell_price, equipped: sale.equipped };
  });
}

// Inventory drawer 装備 section: fetch GET /api/equipment and render the display-only list of the owned equipment
// NOT equipped by any owner. The authoritative sales[].equipped flag decides — an instance on the player OR the buddy
// is excluded here and shows on that owner's panel instead. The loading card (shown by the sync renderer) is replaced
// only if still current. The snapshot is validated fail-fast through the shared validators; a GET failure or a
// malformed snapshot paints the in-section error card (when current) and re-throws so reportError also surfaces it —
// no silent empty / placeholder fallback. An empty un-equipped pool is a legitimate empty state, kept distinct from
// an error.
async function loadRoutingHubInventoryEquipmentInto(sectionBody) {
  const token = routingHubInventoryToken;
  try {
    const snapshot = await getJson('/api/equipment');
    if (!routingHubInventoryIsCurrent(token)) return;
    const view = validateDungeonEquipmentSnapshot(snapshot);
    const sales = validateEquipmentSales(snapshot.sales, view.instances);
    const unequipped = sales.filter((entry) => !entry.equipped).map((entry) => entry.view);
    sectionBody.replaceChildren(...routingHubInventoryEquipmentList(unequipped));
  } catch (error) {
    if (routingHubInventoryIsCurrent(token)) sectionBody.replaceChildren(routingHubEquipmentErrorCard());
    throw error;
  }
}

// The inventory 装備 section content: a 件数 summary + a compact list of the un-equipped instances (each row opens the
// shared 装備 detail popup), or a quiet titled empty state (an empty pool is not an error).
function routingHubInventoryEquipmentList(unequipped) {
  if (unequipped.length === 0) {
    return [routingHubInfoEmptyCard('未装備の装備品なし', '装備していない武器・護符はありません。', 'gear')];
  }
  const nodes = [routingHubInfoSummary(`${unequipped.length}件`, '未装備の装備品')];
  const list = document.createElement('div');
  list.className = 'routing-hub-info-equip-owned';
  list.append(...unequipped.map((entry) => routingHubEquipmentOwnedRow(entry)));
  nodes.push(list);
  return nodes;
}

// ── Person 装備欄 (self / buddy panels) ─────────────────────────────────────────
// Monotonic guard for the whole self / buddy 装備欄 generation: opening either person category bumps this token
// (renderRoutingHubSelfInto / renderRoutingHubBuddyInto). A resolved GET /api/equipment OR an equip/unequip re-render
// commits only when its captured token is still current AND the drawer is still on that same person category.
// Switching category / re-opening therefore abandons an in-flight fetch / re-render rather than flashing a stale
// surface in.
let routingHubPersonEquipToken = 0;
// Single-flight guard for the person 装備欄 equip/unequip 導線: at most one equip/unequip POST is in flight at a time
// (a second click while one is pending is dropped, preventing a duplicate POST that would rewrite the slot).
let routingHubPersonEquipInFlight = false;

// The stale-race guard for a person 装備欄: the resolved async result commits only when its captured token is still
// the live one AND the drawer is still on the SAME person category it was opened from (self / buddy).
function routingHubPersonEquipIsCurrent(token, category) {
  if (token !== routingHubPersonEquipToken) return false;
  const popup = document.querySelector('#routing-hub-info-popup');
  return Boolean(popup) && popup.dataset.category === category;
}

// Resolve the owner's slots from the validated snapshot for a given equip target. 'player' → the hero slots; a buddy
// id → the snapshot buddy's slots, fail-fast if the snapshot buddy is absent or a different id (the roster buddy and
// the backend equipment buddy disagreeing is broken state, never silently coerced to empty / the other owner).
function routingHubPersonEquipSlots(view, target) {
  if (target === 'player') return view.slots;
  if (!view.buddy || view.buddy.characterId !== target) {
    throw new Error(`routing hub buddy equipment target ${JSON.stringify(target)} does not match the snapshot buddy ${JSON.stringify(view.buddy?.characterId ?? null)}`);
  }
  return view.buddy.slots;
}

// Fetch + render the person's 装備欄 into the section body (this is ALSO the re-render an equip / unequip runs on
// success, and — carrying a `feedback` line — on a failed action). Commits only if still current. The snapshot is
// validated fail-fast through the shared validator; a GET failure / malformed snapshot paints the in-section error
// card (when current) and re-throws so reportError also surfaces it — no silent empty / placeholder fallback.
async function loadRoutingHubPersonEquipInto(category, target, sectionBody, feedback = null) {
  const token = routingHubPersonEquipToken;
  try {
    const snapshot = await getJson('/api/equipment');
    if (!routingHubPersonEquipIsCurrent(token, category)) return;
    const view = validateDungeonEquipmentSnapshot(snapshot);
    const slots = routingHubPersonEquipSlots(view, target);
    sectionBody.replaceChildren(...routingHubPersonEquipCards(category, target, slots, view.instances, sectionBody, feedback));
  } catch (error) {
    if (routingHubPersonEquipIsCurrent(token, category)) sectionBody.replaceChildren(routingHubEquipmentErrorCard());
    throw error;
  }
}

// The person 装備欄 content: an optional transient feedback line (a failed equip / unequip message), then the two slot
// cards (weapon / amulet, each carrying its equip / unequip 導線 for this owner). sectionBody is the section body an
// equip / unequip re-render targets (threaded into the slot 導線).
function routingHubPersonEquipCards(category, target, slots, instances, sectionBody, feedback = null) {
  const nodes = [];
  if (feedback) nodes.push(routingHubEquipmentFeedbackCard(feedback));
  const slotsWrap = document.createElement('div');
  slotsWrap.className = 'routing-hub-info-equip-slots';
  for (const slot of WORKSHOP_EQUIPMENT_KINDS) {
    slotsWrap.append(routingHubPersonEquipSlotCard(category, target, slot, slots[slot], instances, sectionBody));
  }
  nodes.push(slotsWrap);
  return nodes;
}

// One slot card (same grammar as the dungeon entry): the slot's mark, then — for an occupied slot — the equipped
// instance detail + a 解除 (unequip) button, or — for an empty slot — the 装備 candidate buttons from the owned instances
// of this kind (a click equips it into this owner's slot; none of the kind → the mark alone).
function routingHubPersonEquipSlotCard(category, target, slot, equippedView, instances, sectionBody) {
  const card = document.createElement('div');
  card.className = 'routing-hub-info-equip-slot';
  card.dataset.slot = slot;
  card.append(routingHubPersonEquipSlotMark(slot, equippedView?.instance ?? null));
  if (equippedView) {
    card.append(routingHubPersonEquipEquipped(category, target, slot, equippedView, sectionBody));
  } else {
    const candidates = instances.filter((view) => view.instance.kind === slot);
    if (candidates.length > 0) card.append(routingHubPersonEquipCandidates(category, target, slot, candidates, sectionBody));
  }
  return card;
}

// The slot's mark: the dungeon entry kit's picture of the kind (the equipped weapon's own type, a wand for an empty
// weapon slot, the charm), lit when occupied and its shadow when empty. The slot name (and 未装備 for an empty slot)
// is read out only (role=img, aria-label).
function routingHubPersonEquipSlotMark(slot, instance) {
  const slotName = `${workshopKindLabel(slot)}スロット`;
  const mark = document.createElement('span');
  mark.className = `routing-hub-info-equip-slot-mark${instance ? '' : ' is-empty'}`;
  mark.setAttribute('role', 'img');
  mark.setAttribute('aria-label', instance ? slotName : `${slotName}・未装備`);
  mark.innerHTML = equipmentSlotMarkSvg(slot, instance);
  return mark;
}

function equipmentSlotMarkSvg(slot, instance) {
  if (slot === 'amulet') return charmSvg();
  if (slot !== 'weapon') throw new Error(`equipment slot mark: unknown slot ${JSON.stringify(slot)}`);
  if (!instance) return wandSvg();
  if (!(instance.weapon_type in DUNGEON_WEAPON_MARKS)) throw new Error(`equipment slot mark: unknown weapon_type ${JSON.stringify(instance.weapon_type)}`);
  return DUNGEON_WEAPON_MARKS[instance.weapon_type]();
}

// An occupied slot: the equipped instance detail + a 解除 button that clears this owner's slot (POST
// /api/equipment/unequip { target }). Clicking the card body opens the instance detail popup (装備中); the 解除
// button stops propagation so it stays unequip-only (a 解除 click never opens the detail). The 解除 rejects to
// reportError (a failure ALSO paints the in-section error line).
function routingHubPersonEquipEquipped(category, target, slot, view, sectionBody) {
  const wrap = document.createElement('div');
  wrap.className = 'routing-hub-info-equip-equipped';
  wrap.addEventListener('click', () => {
    try { openRoutingHubEquipmentPopup(view, { equipped: true }); } catch (error) { reportError(error); }
  });
  wrap.append(routingHubEquipmentEquippedDetail(view));
  const unequip = document.createElement('button');
  unequip.type = 'button';
  unequip.className = 'routing-hub-info-equip-action';
  unequip.dataset.action = 'unequip';
  unequip.dataset.slot = slot;
  // 解除 puts the piece back among the belongings: the terrace's back sigil (the same as 棚に戻る).
  dressSigilButton(unequip, 'back', '解除');
  unequip.addEventListener('click', (event) => {
    event.stopPropagation();
    unequipRoutingHubPersonSlot(category, target, slot, sectionBody).catch(reportError);
  });
  wrap.append(unequip);
  return wrap;
}

// An empty slot's 装備 candidate buttons from the owned instances of this kind (a click equips it into this owner's
// slot). An instance already equipped by the OTHER owner still lists here — the backend 一点物排他 error surfaces on
// click (the existing contract), never a silent hide.
function routingHubPersonEquipCandidates(category, target, slot, candidates, sectionBody) {
  const list = document.createElement('div');
  list.className = 'routing-hub-info-equip-candidates';
  list.append(...candidates.map((view) => routingHubPersonEquipCandidate(category, target, slot, view.instance, sectionBody)));
  return list;
}

// One 装備 candidate button: the instance name + the shared identity line (種別・属性・階級T・出来栄え via
// dungeonEquipmentInstanceMetaText). A click equips this owned instance into this owner's slot; it rejects to
// reportError (a failure — e.g. the 一点物排他 EQUIPMENT_INSTANCE_ALREADY_EQUIPPED — ALSO paints the in-section line).
function routingHubPersonEquipCandidate(category, target, slot, instance, sectionBody) {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'routing-hub-info-equip-candidate';
  button.dataset.instanceId = instance.instance_id;
  button.dataset.element = instance.element;
  const name = document.createElement('span');
  name.className = 'routing-hub-info-equip-candidate-name';
  name.textContent = instance.name;
  const meta = document.createElement('span');
  meta.className = 'routing-hub-info-equip-candidate-meta';
  meta.textContent = dungeonEquipmentInstanceMetaText(instance);
  button.append(name, meta);
  button.addEventListener('click', () => equipRoutingHubPersonSlot(category, target, slot, instance.instance_id, sectionBody).catch(reportError));
  return button;
}

// The equipped instance detail: its name, the shared identity line (種別・属性・階級T・出来栄え via
// dungeonEquipmentInstanceMetaText), and the base / bonus effect rows — each row its chips alone, named for reading
// only; an empty set shows no row.
function routingHubEquipmentEquippedDetail(view) {
  const { instance, baseEffects, bonusEffects } = view;
  const detail = document.createElement('div');
  detail.className = 'routing-hub-info-equip-instance';
  detail.dataset.element = instance.element;
  const name = document.createElement('p');
  name.className = 'routing-hub-info-equip-instance-name';
  name.textContent = instance.name;
  const meta = document.createElement('p');
  meta.className = 'routing-hub-info-equip-instance-meta';
  meta.textContent = dungeonEquipmentInstanceMetaText(instance);
  const effects = document.createElement('div');
  effects.className = 'routing-hub-info-equip-effects';
  if (baseEffects.length > 0) effects.append(routingHubEquipmentEffectChipsRow('基礎性能', baseEffects));
  if (bonusEffects.length > 0) effects.append(routingHubEquipmentEffectChipsRow('付加性能', bonusEffects));
  detail.append(name, meta, effects);
  return detail;
}

// One effect row of the 装備欄 (基礎性能 / 付加性能): its effect chips, the row's name read out only (aria-label).
function routingHubEquipmentEffectChipsRow(name, entries) {
  const row = document.createElement('div');
  row.className = 'routing-hub-info-equip-effect-row';
  row.setAttribute('aria-label', name);
  row.append(routingHubEquipmentEffectChips(entries));
  return row;
}

// The chips of a non-empty effect set (each shared effect entry carries its closed-set label + value).
function routingHubEquipmentEffectChips(entries) {
  const chips = document.createElement('span');
  chips.className = 'routing-hub-info-equip-effect-chips';
  for (const entry of entries) {
    const chip = document.createElement('span');
    chip.className = 'routing-hub-info-equip-effect';
    chip.textContent = `${entry.label}+${entry.value}`;
    chips.append(chip);
  }
  return chips;
}

// One effect row of the 装備 detail popup (基礎性能 / 付加性能): the row label + its effect chips, or a single 「なし」
// for an empty set.
function routingHubEquipmentEffectRow(label, entries) {
  const row = document.createElement('div');
  row.className = 'routing-hub-info-equip-effect-row';
  const rowLabel = document.createElement('span');
  rowLabel.className = 'routing-hub-info-equip-effect-label';
  rowLabel.textContent = label;
  if (entries.length === 0) {
    const chips = document.createElement('span');
    chips.className = 'routing-hub-info-equip-effect-chips';
    const none = document.createElement('span');
    none.className = 'routing-hub-info-equip-effect-none';
    none.textContent = 'なし';
    chips.append(none);
    row.append(rowLabel, chips);
  } else {
    row.append(rowLabel, routingHubEquipmentEffectChips(entries));
  }
  return row;
}

// A compact owned-but-unequipped row: the instance name + the shared identity line (種別・属性・階級T・出来栄え).
// Clicking the row opens the instance detail popup (未装備) — the flavor / full performance live there, not inline.
function routingHubEquipmentOwnedRow(view) {
  const { instance } = view;
  const row = document.createElement('div');
  row.className = 'routing-hub-info-equip-owned-row';
  row.dataset.element = instance.element;
  row.addEventListener('click', () => {
    try { openRoutingHubEquipmentPopup(view, { equipped: false }); } catch (error) { reportError(error); }
  });
  const name = document.createElement('strong');
  name.className = 'routing-hub-info-equip-owned-name';
  name.textContent = instance.name;
  const meta = document.createElement('span');
  meta.className = 'routing-hub-info-equip-owned-meta';
  meta.textContent = dungeonEquipmentInstanceMetaText(instance);
  row.append(name, meta);
  return row;
}

// ── 装備 detail popup ─────────────────────────────────────────────────────────
// Clicking an equipped card body or an owned (未装備) row opens this popup with the full instance detail: the name
// (title), the 装備中 / 未装備 state, the shared identity line, the flavor 全文, and the base / 付加 effect rows (an
// empty set reads an honest 「なし」). NO additional fetch — the instance view comes from the already-rendered,
// shared-validated GET /api/equipment snapshot, so every field is fail-fast-guaranteed (name / flavor non-empty,
// effects shape valid). It follows the routing hub popup grammar ([hidden] toggle, data-routing-popup-close,
// role=dialog); closing leaves the 装備欄 untouched (no re-fetch). Broken popup markup is fail-fast.
function openRoutingHubEquipmentPopup(view, { equipped }) {
  const { instance } = view;
  const popup = document.querySelector('#routing-hub-equipment-popup');
  const title = document.querySelector('#routing-hub-equipment-popup-title');
  const body = document.querySelector('#routing-hub-equipment-popup-body');
  if (!popup || !title || !body) {
    throw new Error('routing hub equipment popup nodes are missing (broken markup wiring)');
  }
  title.textContent = instance.name;
  body.replaceChildren(...routingHubEquipmentPopupSections(view, equipped));
  popup.hidden = false;
}

// The popup body: the 装備中 / 未装備 status, the shared identity line, the flavor 全文, and the 基礎 / 付加 effect
// rows (routingHubEquipmentEffectRow — the chips are the 装備欄's own). instance.flavor is validator-guaranteed non-empty (assertWorkshopString), so it always renders.
function routingHubEquipmentPopupSections(view, equipped) {
  const { instance, baseEffects, bonusEffects } = view;
  const status = document.createElement('p');
  status.className = 'routing-hub-equipment-popup-status';
  status.dataset.state = equipped ? 'equipped' : 'unequipped';
  status.textContent = equipped ? '装備中' : '未装備';
  const meta = document.createElement('p');
  meta.className = 'routing-hub-equipment-popup-meta';
  meta.textContent = dungeonEquipmentInstanceMetaText(instance);
  const flavor = document.createElement('p');
  flavor.className = 'routing-hub-equipment-popup-flavor';
  flavor.textContent = instance.flavor;
  const effects = document.createElement('div');
  effects.className = 'routing-hub-equipment-popup-effects';
  effects.append(
    routingHubEquipmentEffectRow('基礎性能', baseEffects),
    routingHubEquipmentEffectRow('付加性能', bonusEffects)
  );
  return [status, meta, flavor, effects];
}

// Close the 装備 detail popup. Fail-fast on missing markup (broken wiring), mirroring the character / info popup
// close contracts rather than silently succeeding. The 装備欄 state is untouched (no re-fetch).
function closeRoutingHubEquipmentPopup() {
  const popup = document.querySelector('#routing-hub-equipment-popup');
  if (!popup) {
    throw new Error('routing hub equipment popup node #routing-hub-equipment-popup is missing (broken markup wiring)');
  }
  popup.hidden = true;
}

// The transient equip / unequip result line (role=status): a failed action's fail-fast API message painted above
// the slots on the re-render (never a silent no-op). Toned by data-tone; a success re-render carries no feedback.
function routingHubEquipmentFeedbackCard({ message, tone }) {
  const card = document.createElement('p');
  card.className = 'routing-hub-info-equip-feedback';
  card.dataset.tone = tone;
  card.setAttribute('role', 'status');
  card.setAttribute('aria-live', 'polite');
  card.textContent = message;
  return card;
}

// Equip an owned instance into this owner's slot (candidate click).
function equipRoutingHubPersonSlot(category, target, slot, instanceId, sectionBody) {
  return runRoutingHubPersonEquipAction(category, target, sectionBody, () =>
    postJson('/api/equipment/equip', { target, slot, instance_id: instanceId }));
}

// Clear this owner's slot (解除 click).
function unequipRoutingHubPersonSlot(category, target, slot, sectionBody) {
  return runRoutingHubPersonEquipAction(category, target, sectionBody, () =>
    postJson('/api/equipment/unequip', { target, slot }));
}

// Run one equip / unequip against a person's slots (target 'player' or the buddy character_id). Single-flight (a
// second click while one is pending is dropped — no duplicate POST). The action's authoritative snapshot is never
// adopted optimistically: on success the section re-fetches GET /api/equipment and re-renders; on failure (transport
// / 400 一点物排他 etc.) it re-renders from that authoritative snapshot with an in-section error line AND re-throws to
// reportError (no silent no-op / placeholder degrade). The person-equip token abandons a result that lands after a
// category switch / re-open. Only the single-flight reset runs in finally.
async function runRoutingHubPersonEquipAction(category, target, sectionBody, action) {
  if (routingHubPersonEquipInFlight) return;
  routingHubPersonEquipInFlight = true;
  const token = routingHubPersonEquipToken;
  try {
    await action();
    if (routingHubPersonEquipIsCurrent(token, category)) await loadRoutingHubPersonEquipInto(category, target, sectionBody);
  } catch (error) {
    if (!routingHubPersonEquipIsCurrent(token, category)) throw error;
    await loadRoutingHubPersonEquipInto(category, target, sectionBody, { message: errorDisplayMessage(error), tone: 'error' });
    throw error;
  } finally {
    routingHubPersonEquipInFlight = false;
  }
}

// ───────────────────────────────────────────────────────────────────────────────────────────────────
// 星の揺り籠 (star cradle): the routing hub sandbox overlay. A named / clickable 浮遊装飾の一角 opens a modal
// garden overlay — the 箱庭の絵 filling the window, the terrace hidden beneath it, closed by its close sigil
// ([hidden] toggle + data-routing-popup-close like the other routing hub popups) — that drives the 8 GET/plant/feed/harvest/byproduct/name/cage/release routes. It is a hub side-road,
// not a week destination — open / close it any time without consuming a week or touching the hub chat state.
// Every displayed value is view-derived (the frontend never re-computes a growth formula); a 400/409 surfaces
// on the overlay status line, and contract-known-impossible actions are disabled with a reason rather than
// firing a doomed request. It is LM-independent, so it stays out of the loading-screen discipline entirely.
const STAR_CRADLE_REQUEST_PATH = '/api/star-cradle';
const STAR_CRADLE_ASSET_ROOT = '/canonical/star_cradle';
const STAR_CRADLE_ICON_URL = `${STAR_CRADLE_ASSET_ROOT}/cradle_icon.png`;
// Plantable seed/egg items are identified from inventory by the authored star cradle item_id contract
// (the backend catalog's SEED_ITEM_ID_PATTERN `^star_cradle_<name>$`) — there is no catalog / candidate
// route to enumerate them, and hardcoding the four ids would duplicate authored data. The backend plant
// route stays the authoritative gate (a non-seed 400s STAR_CRADLE_NOT_A_SEED, surfaced near the action);
// caged creatures live on their own surface (`sc_creature_*`), never in this inventory pool.
const STAR_CRADLE_SEED_ITEM_PATTERN = /^star_cradle_[a-z_]+$/;
// Feed candidates are attribute materials (`material_<element>_t<tier>`); the backend feed route validates
// the concrete element (a non-material 400s STAR_CRADLE_NOT_A_MATERIAL, surfaced near the action).
const STAR_CRADLE_MATERIAL_ITEM_PATTERN = /^material_[a-z]+_t[1-4]$/;
// Pre-reveal plant stage → generic stage sprite (the view's stage string is the single source; an unknown
// stage is broken state and throws rather than falling back to a placeholder). Bloomed plants use variety art.
const STAR_CRADLE_PLANT_STAGE_SPRITE = Object.freeze({ '芽': 'plant_sprout', '若葉': 'plant_leaf', '蕾': 'plant_bud' });
// A held egg (vs a seed or bulb) shows the egg art in the 植える場 (the authored `star_cradle_<name>_egg` ids).
const STAR_CRADLE_EGG_ITEM_PATTERN = /^star_cradle_[a-z_]+_egg$/;
// The fed mark of an element: the element's first-tier material icon.
const STAR_CRADLE_FED_ICON_ROOT = '/canonical/dungeon/material-icons';
// The seats' feet on the ground picture (percent of the 1600x900 箱庭の絵): pots on the upper lawn, creatures on the
// lower lawn. A view with more slots than seats is broken state and throws.
const STAR_CRADLE_POT_SPOTS = Object.freeze([{ x: 25.625, y: 44.444 }, { x: 40.625, y: 41.333 }, { x: 55.625, y: 44.444 }]);
const STAR_CRADLE_CREATURE_SPOTS = Object.freeze([{ x: 27.5, y: 75.111 }, { x: 43.75, y: 78.222 }, { x: 59.375, y: 75.111 }]);
// The gold star mark (金色変異 / 変貌): the same four-point star the sigils carry.
const STAR_CRADLE_GOLD_STAR = '<svg viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M8 1 L9.7 6.3 L15 8 L9.7 9.7 L8 15 L6.3 9.7 L1 8 L6.3 6.3 Z" fill="#e8c877" /></svg>';

function starCradleAssetUrl(relativePath) {
  return `${STAR_CRADLE_ASSET_ROOT}/${relativePath}`;
}

// The pot sprite for a plant view: its variety art once bloomed, else the generic stage sprite. No existence
// check / fallback path — a missing file surfaces as an image load failure (the fixed-asset-path 規約).
function starCradlePlantSpriteUrl(view) {
  if (view.revealed) return starCradleAssetUrl(`varieties/${view.variety.id}.png`);
  const sprite = STAR_CRADLE_PLANT_STAGE_SPRITE[view.stage];
  if (!sprite) throw new Error(`star cradle pot has an unknown pre-bloom stage: ${JSON.stringify(view.stage)}`);
  return starCradleAssetUrl(`stages/${sprite}.png`);
}

// The creature sprite: 卵 before hatch, the variety juvenile after hatch, and — as an adult — the mutation
// art if it took its second form else the variety adult art.
function starCradleCreatureSpriteUrl(view) {
  if (!view.revealed) return starCradleAssetUrl('stages/egg.png');
  if (!view.adult) return starCradleAssetUrl(`creatures/${view.variety.id}_juvenile.png`);
  if (view.mutation) return starCradleAssetUrl(`creatures/${view.variety.id}_${view.mutation.id}.png`);
  return starCradleAssetUrl(`creatures/${view.variety.id}_adult.png`);
}

// A star cradle op's 400/404/409 is a caller-facing outcome (bad request / empty slot / gate conflict) shown
// near the action; anything else is a genuine failure that re-throws to reportError.
function isStarCradleClientError(error) {
  return error?.statusCode === 400 || error?.statusCode === 404 || error?.statusCode === 409;
}

// The overlay status line doubles as the busy indicator and the error surface (no silent no-op). An empty
// message hides it.
function setStarCradleStatus(message, { tone = 'info' } = {}) {
  const status = document.querySelector('#routing-hub-star-cradle-status');
  if (!status) throw new Error('routing hub star cradle status node #routing-hub-star-cradle-status is missing (broken markup wiring)');
  if (!message) {
    status.textContent = '';
    status.hidden = true;
    return;
  }
  status.textContent = message;
  status.dataset.tone = tone;
  status.hidden = false;
}

// 揺り籠を読み込むあいだ: 状態の行に字の代わりに画面の中の待ちの印を置く（右下で待ちの紋が回る）。
function showStarCradleStatusWait() {
  const status = document.querySelector('#routing-hub-star-cradle-status');
  if (!status) throw new Error('routing hub star cradle status node #routing-hub-star-cradle-status is missing (broken markup wiring)');
  status.replaceChildren(screenWaitMark());
  status.dataset.tone = 'info';
  status.hidden = false;
}

// Monotonic token: a resolved GET /api/star-cradle commits only when its captured token is still current and
// the overlay is still open. Every op bumps the token before re-rendering so a late initial fetch never
// clobbers a post-action view (the same discipline as the info-drawer fetch tokens).
let starCradleViewToken = 0;
// Single-flight guard: one plant/feed/harvest/byproduct/name/cage/release POST at a time (rapid / cross-row
// clicks are dropped, preventing a duplicate POST).
let starCradleActionInFlight = false;
// The last rendered view (re-rendered in place when a seat is selected or the name input opens / closes), the selected
// feedable individual ({ kind, slotIndex } — its materials show under it), and the adult whose name input is open.
let starCradleView = null;
let starCradleSelected = null;
let starCradleNamingSlot = null;

function isRoutingHubStarCradleOpen() {
  const overlay = document.querySelector('#routing-hub-star-cradle');
  return Boolean(overlay) && !overlay.hidden;
}

// Open the garden overlay ([hidden] toggle) and fetch the current view. A missing overlay node is broken
// markup (fail-fast). Opening / closing is unconditional and week-free; it never touches the hub chat state.
function openRoutingHubStarCradle() {
  const overlay = document.querySelector('#routing-hub-star-cradle');
  if (!overlay) throw new Error('routing hub star cradle overlay #routing-hub-star-cradle is missing (broken markup wiring)');
  overlay.hidden = false;
  starCradleSelected = null;
  starCradleNamingSlot = null;
  syncBgmForUiState(); // overlay override: v6-cradle takes over while the garden is open
  loadRoutingHubStarCradleView().catch(reportError);
}

// Close the garden overlay. Fail-fast on missing markup (mirrors the other routing hub popup close contracts).
function closeRoutingHubStarCradle() {
  const overlay = document.querySelector('#routing-hub-star-cradle');
  if (!overlay) throw new Error('routing hub star cradle overlay #routing-hub-star-cradle is missing (broken markup wiring)');
  overlay.hidden = true;
  syncBgmForUiState(); // overlay closed: fall back to the current screen's track
}

// Fetch the whole garden view and render it. Token + still-open guard discards a fetch that resolves after a
// close / re-open. A fetch failure surfaces on the status line AND re-throws to reportError (two surfaces, no
// silent empty garden).
async function loadRoutingHubStarCradleView() {
  const token = (starCradleViewToken += 1);
  showStarCradleStatusWait();
  let view;
  try {
    view = await getJson(STAR_CRADLE_REQUEST_PATH);
  } catch (error) {
    if (token === starCradleViewToken && isRoutingHubStarCradleOpen()) {
      setStarCradleStatus(errorDisplayMessage(error), { tone: 'error' });
    }
    throw error;
  }
  if (token !== starCradleViewToken || !isRoutingHubStarCradleOpen()) return;
  setStarCradleStatus('', {});
  renderRoutingHubStarCradleView(view);
}

// The garden: the 箱庭の絵 ground (CSS) with the pots on the upper lawn, the creatures on the lower lawn, the 植える場
// at the far empty pots, and the 籠 on the round stone stand. State reads as pictures, marks and counts (stage art,
// growth pips, fed material marks, sigil counts); the words of each value stay on the reading names. Every value
// shown comes from the view.
function renderRoutingHubStarCradleView(view) {
  const garden = document.querySelector('#routing-hub-star-cradle-garden');
  if (!garden) throw new Error('routing hub star cradle garden #routing-hub-star-cradle-garden is missing (broken markup wiring)');
  starCradleView = view;
  if (starCradleSelected !== null && !starCradleRecordAt(view, starCradleSelected)?.feedable) starCradleSelected = null;
  if (starCradleNamingSlot !== null && !starCradleRecordAt(view, { kind: 'creature', slotIndex: starCradleNamingSlot })?.adult) starCradleNamingSlot = null;
  garden.replaceChildren(
    ...starCradleSpots(view.pot_slots, view.pots, STAR_CRADLE_POT_SPOTS, 'pot', starCradlePlantSpot),
    ...starCradleSpots(view.creature_slots, view.creatures, STAR_CRADLE_CREATURE_SPOTS, 'nest', starCradleCreatureSpot),
    starCradleStation(view),
    starCradleCagedStand(view)
  );
}

function starCradleRecordAt(view, { kind, slotIndex }) {
  const records = kind === 'plant' ? view.pots : view.creatures;
  return records.find((record) => record.slot_index === slotIndex) ?? null;
}

function starCradleIsSelected(kind, view) {
  return starCradleSelected !== null && starCradleSelected.kind === kind && starCradleSelected.slotIndex === view.slot_index;
}

// One lawn's seats: `total` spots, each filled by its slot_index record or shown as the lawn's dotted empty picture.
function starCradleSpots(total, records, spots, emptyArt, spotFor) {
  if (total > spots.length) throw new Error(`star cradle view has ${total} ${emptyArt} slots but the garden lays out ${spots.length}`);
  const byIndex = new Map(records.map((record) => [record.slot_index, record]));
  return spots.slice(0, total).map((at, index) => {
    const record = byIndex.get(index);
    if (record) return spotFor(record, at);
    const figure = document.createElement('div');
    figure.className = 'routing-hub-star-cradle-figure';
    figure.append(fillWithEmptyArt(document.createElement('span'), emptyArt, '空き'));
    return starCradleSpot(at, figure, [], false);
  });
}

// A seat on the lawn: the foot (--x, --y on the ground picture) with the figure above it and the tag (name, growth,
// actions) below it. The selected seat's foot glows gold.
function starCradleSpot(at, figure, tagChildren, selected) {
  const node = document.createElement('div');
  node.className = 'routing-hub-star-cradle-spot';
  if (selected) node.classList.add('is-selected');
  node.style.setProperty('--x', `${at.x}%`);
  node.style.setProperty('--y', `${at.y}%`);
  const tag = document.createElement('div');
  tag.className = 'routing-hub-star-cradle-tag';
  tag.append(...tagChildren);
  node.append(figure, tag);
  return node;
}

// The figure of an individual. A feedable one is a button: pressing it selects it (its foot glows gold and the owned
// materials appear under it); pressing the selected one again lets go.
function starCradleFigure(sprite, kind, view, name) {
  if (!view.feedable) {
    const figure = document.createElement('div');
    figure.className = 'routing-hub-star-cradle-figure';
    figure.append(sprite);
    return figure;
  }
  const selected = starCradleIsSelected(kind, view);
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'routing-hub-star-cradle-figure';
  button.setAttribute('aria-label', `${name}に餌を与える`);
  button.setAttribute('aria-pressed', String(selected));
  button.append(sprite);
  button.addEventListener('click', () => {
    starCradleSelected = selected ? null : { kind, slotIndex: view.slot_index };
    renderRoutingHubStarCradleView(starCradleView);
  });
  return button;
}

// A sprite figure: the swaying plant / wandering creature art. The per-kind class drives the CSS animation;
// a golden plant adds .is-golden (a CSS glow, no separate art). The slot index staggers the wander phase.
function starCradleSpriteFigure(url, altText, { kind, size, golden = false, slotIndex = 0 }) {
  const figure = document.createElement('div');
  figure.className = `routing-hub-star-cradle-sprite routing-hub-star-cradle-sprite-${kind}`;
  if (golden) figure.classList.add('is-golden');
  figure.style.setProperty('--sc-sprite-index', String(slotIndex));
  figure.style.setProperty('--size', `${size}px`);
  const img = document.createElement('img');
  img.className = 'routing-hub-star-cradle-sprite-img';
  img.src = url;
  img.alt = altText;
  figure.append(img);
  return figure;
}

function starCradleNameRow(text, marks = []) {
  const row = document.createElement('span');
  row.className = 'routing-hub-star-cradle-name';
  const name = document.createElement('span');
  name.textContent = text;
  row.append(name, ...marks);
  return row;
}

// The gold star beside a name (金色変異 / 変貌); its words are the reading name.
function starCradleGoldMark(name) {
  const mark = document.createElement('span');
  mark.className = 'routing-hub-star-cradle-mark';
  mark.setAttribute('role', 'img');
  mark.setAttribute('aria-label', name);
  mark.innerHTML = STAR_CRADLE_GOLD_STAR;
  return mark;
}

// The growth pips: one per week up to bloom (or adulthood), the elapsed weeks lit, a small gap after the hatch week.
// The stage and week words are the reading name. Behind the pips, the fed material marks.
function starCradleGrowthRow(view, total, gapAfter, name) {
  const row = document.createElement('span');
  row.className = 'routing-hub-star-cradle-name';
  const meter = document.createElement('span');
  meter.className = 'routing-hub-star-cradle-meter';
  meter.setAttribute('role', 'img');
  meter.setAttribute('aria-label', name);
  const lit = Math.min(view.weeks_elapsed, total);
  for (let week = 1; week <= total; week += 1) {
    const pip = document.createElement('span');
    pip.className = 'routing-hub-star-cradle-pip';
    if (week <= lit) pip.classList.add('is-lit');
    if (gapAfter !== null && week === gapAfter + 1) pip.classList.add('is-gap');
    meter.append(pip);
  }
  row.append(meter);
  for (const [element, count] of Object.entries(view.feed)) {
    if (count <= 0) continue;
    const mark = document.createElement('span');
    mark.className = 'routing-hub-star-cradle-fed';
    mark.setAttribute('role', 'img');
    mark.setAttribute('aria-label', `餌やり済み: ${element}×${count}`);
    const icon = document.createElement('img');
    icon.src = `${STAR_CRADLE_FED_ICON_ROOT}/material_${element}_t1.png`;
    icon.alt = '';
    const number = document.createElement('span');
    number.textContent = String(count);
    mark.append(icon, number);
    row.append(mark);
  }
  return row;
}

function starCradleActionsRow(children) {
  const row = document.createElement('div');
  row.className = 'routing-hub-star-cradle-actions';
  row.append(...children);
  return row;
}

// One pot: the plant art (variety once bloomed, else the stage art), the name (variety once bloomed, else the seed),
// the gold star of a golden plant, the growth pips, the 収穫 sigil once bloomed, and the materials while selected.
function starCradlePlantSpot(view, at) {
  const name = view.revealed ? view.variety.name : view.seed_item.name;
  const alt = view.revealed ? view.variety.name : `${view.seed_item.name}（${view.stage}）`;
  const sprite = starCradleSpriteFigure(starCradlePlantSpriteUrl(view), alt, { kind: 'plant', size: view.revealed ? 176 : 140, golden: Boolean(view.golden), slotIndex: view.slot_index });
  const selected = starCradleIsSelected('plant', view);
  const marks = view.golden ? [starCradleGoldMark('金色変異')] : [];
  const growth = starCradleGrowthRow(view, view.mature_weeks, null, `${view.stage}・${view.weeks_elapsed}週目 / 開花${view.mature_weeks}週`);
  let actions = [];
  if (view.revealed) actions = [starCradleActionButton('harvest', '収穫する', () => starCradleHarvest(view.slot_index))];
  else if (selected) actions = starCradleFeedPicker('plant', view);
  return starCradleSpot(at, starCradleFigure(sprite, 'plant', view, name), [starCradleNameRow(name, marks), growth, starCradleActionsRow(actions)], selected);
}

// One creature: the art (egg / juvenile / adult / mutation), its name (given name, else the mutation, variety or egg),
// the gold star of a mutation, the growth pips, and — as an adult — the 副産物 / 名付け / 籠 sigils.
function starCradleCreatureSpot(view, at) {
  const name = view.name ?? (view.adult && view.mutation ? view.mutation.name : view.revealed ? view.variety.name : view.seed_item.name);
  const alt = view.revealed ? view.variety.name : `${view.seed_item.name}（${view.stage}）`;
  const size = view.revealed ? (view.adult ? 170 : 128) : 92;
  const sprite = starCradleSpriteFigure(starCradleCreatureSpriteUrl(view), alt, { kind: 'creature', size, slotIndex: view.slot_index });
  const selected = starCradleIsSelected('creature', view);
  const marks = view.adult && view.mutation ? [starCradleGoldMark(`変貌: ${view.mutation.name}`)] : [];
  const growth = starCradleGrowthRow(view, view.adult_weeks, view.hatch_weeks, `${view.stage}・${view.weeks_elapsed}週目 / 孵化${view.hatch_weeks}週・成体${view.adult_weeks}週`);
  let actions = [];
  if (view.adult && starCradleNamingSlot === view.slot_index) actions = starCradleNameInput(view);
  else if (view.adult) {
    actions = [
      starCradleByproductAction(view),
      starCradleActionButton('name', '名付ける', () => {
        starCradleNamingSlot = view.slot_index;
        renderRoutingHubStarCradleView(starCradleView);
        document.querySelector('#routing-hub-star-cradle .routing-hub-star-cradle-name-input').focus();
      }),
      // cageable is the contract flag for 籠に入れる; a full caged surface never blocks caging (it always adds).
      starCradleActionButton('cage', '籠に入れる', () => starCradleCage(view.slot_index), { disabled: !view.cageable })
    ];
  } else if (selected) actions = starCradleFeedPicker('creature', view);
  return starCradleSpot(at, starCradleFigure(sprite, 'creature', view, name), [starCradleNameRow(name, marks), growth, starCradleActionsRow(actions)], selected);
}

// The 副産物 (weekly byproduct) claim: the sigil with the claimable week count while byproduct_pending_weeks > 0,
// else the quiet disabled sigil (contract-known-impossible → disabled, not a doomed 409; the reason is its reading name).
function starCradleByproductAction(view) {
  const pending = view.byproduct_pending_weeks;
  if (pending > 0) {
    return starCradleActionButton('byproduct', `副産物を受け取る（${pending}週分）`, () => starCradleByproduct(view.slot_index), { count: pending });
  }
  return starCradleActionButton('byproduct', '副産物を受け取る（今週分は受け取り済み）', () => starCradleByproduct(view.slot_index), { disabled: true });
}

// The name input opened in place by the 名付け sigil: Enter or the sigil names the creature, Escape closes it. The backend
// name validation error (空 / 24字超 / 記号) surfaces on the overlay status line.
function starCradleNameInput(view) {
  const input = document.createElement('input');
  input.type = 'text';
  input.className = 'routing-hub-star-cradle-name-input';
  input.maxLength = 48;
  if (view.name) input.value = view.name;
  input.setAttribute('aria-label', 'この子の名前');
  input.addEventListener('keydown', (event) => {
    if (event.isComposing) return;
    if (event.key === 'Enter') starCradleName(view.slot_index, input.value);
    if (event.key === 'Escape') {
      event.stopPropagation();
      starCradleNamingSlot = null;
      renderRoutingHubStarCradleView(starCradleView);
    }
  });
  return [input, starCradleActionButton('name', '名付ける', () => starCradleName(view.slot_index, input.value))];
}

// The owned attribute materials under the selected individual: each its icon and owned count (pressing one feeds a
// unit, biasing the outcome). None owned is the dotted empty pouch (never a silent empty). Feed is contract-blocked
// after reveal — the picker only renders while feedable.
function starCradleFeedPicker(kind, view) {
  const materials = starCradleMaterialCandidates();
  if (materials.length === 0) return [fillWithEmptyArt(document.createElement('span'), 'pouch', '餌にできる属性素材を持っていません。')];
  return materials.map((item) => {
    if (typeof item.icon !== 'string' || item.icon === '') throw new Error(`star cradle feed material ${item.item_id} has no icon`);
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'routing-hub-star-cradle-material';
    button.setAttribute('aria-label', `${item.name}を与える（×${item.quantity.toLocaleString('ja-JP')}）`);
    const icon = document.createElement('img');
    icon.src = item.icon;
    icon.alt = '';
    const count = document.createElement('span');
    count.textContent = item.quantity.toLocaleString('ja-JP');
    button.append(icon, count);
    button.addEventListener('click', () => { starCradleFeed(kind, view.slot_index, item.item_id); });
    return button;
  });
}

// The 植える場 at the far empty pots: the free pot / nest counts as the dotted pot and nest with a number, then the
// held seeds and eggs (stage art, name, count, 植える sigil); none held is the dotted empty pouch.
function starCradleStation(view) {
  const station = document.createElement('div');
  station.className = 'routing-hub-star-cradle-station';
  const free = document.createElement('div');
  free.className = 'routing-hub-star-cradle-free';
  free.append(starCradleFreeItem('pot', '鉢', view.free_pot_slots), starCradleFreeItem('nest', '生き物', view.free_creature_slots));
  station.append(free);
  const candidates = starCradleSeedCandidates();
  if (candidates.length === 0) {
    station.append(fillWithEmptyArt(document.createElement('span'), 'pouch', '植えられる種や卵を持っていません。'));
    return station;
  }
  for (const item of candidates) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'routing-hub-star-cradle-seed';
    button.setAttribute('aria-label', `${item.name}を植える（×${item.quantity.toLocaleString('ja-JP')}）`);
    const thumb = document.createElement('img');
    thumb.src = starCradleAssetUrl(STAR_CRADLE_EGG_ITEM_PATTERN.test(item.item_id) ? 'stages/egg.png' : 'stages/plant_sprout.png');
    thumb.alt = '';
    const name = document.createElement('span');
    name.textContent = item.name;
    const count = document.createElement('span');
    count.className = 'routing-hub-star-cradle-count';
    count.textContent = `×${item.quantity.toLocaleString('ja-JP')}`;
    const sigil = dressSigilButton(document.createElement('span'), 'plant', '植える');
    button.append(thumb, name, count, ...sigil.childNodes);
    button.addEventListener('click', () => { starCradlePlant(item.item_id); });
    station.append(button);
  }
  return station;
}

function starCradleFreeItem(art, label, count) {
  const item = fillWithEmptyArt(document.createElement('span'), art, `${label}の空き ${count}`);
  item.className = 'routing-hub-star-cradle-free-item';
  const number = document.createElement('span');
  number.textContent = String(count);
  item.append(number);
  return item;
}

// The 籠 on the round stone stand: each one-off caged creature as its adult art, name and 放す sigil (backend 409s a
// full garden near the action). An empty cage is the dotted empty cage, read out as its note.
function starCradleCagedStand(view) {
  const cage = document.createElement('div');
  cage.className = 'routing-hub-star-cradle-cage';
  if (view.caged.length === 0) {
    cage.append(fillWithEmptyArt(document.createElement('span'), 'cage', '籠に入れた子はいません。'));
    return cage;
  }
  for (const instance of view.caged) {
    const row = document.createElement('div');
    row.className = 'routing-hub-star-cradle-caged';
    const img = document.createElement('img');
    img.src = starCradleAssetUrl(`creatures/${instance.variety.id}_${instance.mutation ? instance.mutation.id : 'adult'}.png`);
    img.alt = instance.mutation ? `${instance.variety.name}・${instance.mutation.name}` : instance.variety.name;
    const name = instance.name ?? (instance.mutation ? instance.mutation.name : instance.variety.name);
    row.append(img, starCradleNameRow(name), starCradleActionButton('release', '放す', () => starCradleRelease(instance.instance_id)));
    cage.append(row);
  }
  return cage;
}

// A star cradle action button: the action's sigil, its words on aria-label; the claimable week count of the byproduct
// stays a number beside the sigil. A disabled button (contract-known-impossible action) fires nothing; an enabled one
// runs its op through the single-flight runner.
function starCradleActionButton(sigil, name, onClick, { disabled = false, count = null } = {}) {
  const button = document.createElement('button');
  button.type = 'button';
  dressSigilButton(button, sigil, name);
  if (count !== null) {
    const countText = document.createElement('span');
    countText.className = 'terrace-sigil-count';
    countText.textContent = String(count);
    button.append(countText);
  }
  if (disabled) {
    button.disabled = true;
    return button;
  }
  button.addEventListener('click', () => { onClick(); });
  return button;
}

// Inventory items that are plantable star cradle seeds/eggs (by the authored item_id pattern).
function starCradleSeedCandidates() {
  const items = currentInventory?.items;
  if (!Array.isArray(items)) {
    throw new Error(`star cradle plant candidates require currentInventory.items array, got ${JSON.stringify(items)}`);
  }
  return items.filter((item) => STAR_CRADLE_SEED_ITEM_PATTERN.test(item.item_id));
}

// Inventory items that are attribute materials (feed candidates).
function starCradleMaterialCandidates() {
  const items = currentInventory?.items;
  if (!Array.isArray(items)) {
    throw new Error(`star cradle feed candidates require currentInventory.items array, got ${JSON.stringify(items)}`);
  }
  return items.filter((item) => STAR_CRADLE_MATERIAL_ITEM_PATTERN.test(item.item_id));
}

// The shared op runner: single-flight POST → adopt the authoritative inventory (when the op returns one) →
// re-render from the response view (bumping the view token so a late initial fetch can't clobber it). A
// 400/404/409 surfaces on the overlay status line near the action; anything else re-throws to reportError.
async function runStarCradleAction(request) {
  if (starCradleActionInFlight) return;
  starCradleActionInFlight = true;
  setStarCradleStatus('', {});
  try {
    const result = await request();
    if (result.inventory) currentInventory = result.inventory;
    starCradleViewToken += 1;
    renderRoutingHubStarCradleView(result.view);
  } catch (error) {
    if (!isStarCradleClientError(error)) { reportError(error); return; }
    setStarCradleStatus(errorDisplayMessage(error), { tone: 'error' });
  } finally {
    starCradleActionInFlight = false;
  }
}

function starCradlePlant(itemId) {
  return runStarCradleAction(() => postJson(`${STAR_CRADLE_REQUEST_PATH}/plant`, { item_id: itemId }));
}

function starCradleFeed(kind, slotIndex, materialItemId) {
  return runStarCradleAction(() => postJson(`${STAR_CRADLE_REQUEST_PATH}/feed`, { kind, slot_index: slotIndex, material_item_id: materialItemId }));
}

function starCradleHarvest(slotIndex) {
  return runStarCradleAction(() => postJson(`${STAR_CRADLE_REQUEST_PATH}/harvest`, { slot_index: slotIndex }));
}

function starCradleByproduct(slotIndex) {
  return runStarCradleAction(() => postJson(`${STAR_CRADLE_REQUEST_PATH}/byproduct`, { slot_index: slotIndex }));
}

// A named creature closes its name input; a rejected name keeps it open with the reason on the status line.
function starCradleName(slotIndex, name) {
  return runStarCradleAction(async () => {
    const result = await postJson(`${STAR_CRADLE_REQUEST_PATH}/name`, { slot_index: slotIndex, name });
    starCradleNamingSlot = null;
    return result;
  });
}

function starCradleCage(slotIndex) {
  return runStarCradleAction(() => postJson(`${STAR_CRADLE_REQUEST_PATH}/cage`, { slot_index: slotIndex }));
}

function starCradleRelease(instanceId) {
  return runStarCradleAction(() => postJson(`${STAR_CRADLE_REQUEST_PATH}/release`, { instance_id: instanceId }));
}

// Money: a large numeric tile + a short label. Source is currentInventory.money only (validated by the
// caller); moneyText is the shared G formatter.
function renderRoutingHubMoneyInto(bodyEl, money) {
  const card = document.createElement('div');
  card.className = 'routing-hub-info-money-card';
  const value = document.createElement('strong');
  value.className = 'routing-hub-info-money-value';
  value.textContent = moneyText(money);
  const label = document.createElement('span');
  label.className = 'routing-hub-info-money-label';
  label.textContent = '購買で使える資金';
  card.append(value, label);
  bodyEl.append(card);
}

// ── Diary (6th category) ─────────────────────────────────────────────────────
// The routing hub diary opens on a roster picker (all selectable characters); selecting one swaps the body to
// that character's journal, with a back affordance to the picker. The picker cells are buttons (they navigate),
// unlike the enemy list's static roster cards, but reuse the same shared roster face helper. entry.text is
// rendered as-is (no re-processing); the raw type / tags metadata is never surfaced.
// The routing hub diary picker lists ルミ (the routing persona on the `lina` slot) ALONGSIDE the selectable
// roster: the exam / midterm records are written to her diary (GET /api/diary accepts 'lina'), so she must be
// pickable here to read them. She is NOT a selectable roster character, so her picker entry is built from the
// registered routing persona visual (its display_name / face) with a fixed role subtitle, prepended before the
// roster. This is hub-only — the daytime (partner-only) diary is a separate renderer and stays unchanged. A
// missing persona registration is broken hub state → fail fast (routingPersonaActor), never a silent drop.
function routingHubDiaryPickerEntries() {
  return [{ ...routingPersonaActor(), diary_meta: '週の行事の記録' }, ...selectableCharacters];
}

function renderRoutingHubDiaryInto(bodyEl) {
  diaryFetchToken += 1; // re-opening the category abandons any in-flight character fetch
  const list = document.createElement('div');
  list.className = 'routing-hub-info-roster-list';
  // ルミ is always prepended, so the picker is never empty (the empty-roster case is unreachable now).
  for (const character of routingHubDiaryPickerEntries()) {
    list.append(routingHubDiaryRosterButton(bodyEl, character));
  }
  bodyEl.append(list);
}

function routingHubDiaryRosterButton(bodyEl, character) {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'routing-hub-info-diary-roster-button';
  const image = document.createElement('img');
  image.className = 'routing-hub-info-roster-face';
  image.src = routingHubRosterFaceUrl(character);
  image.alt = `${character.display_name ?? character.character_id}の顔`;
  const body = document.createElement('div');
  body.className = 'routing-hub-info-roster-body';
  const name = document.createElement('strong');
  name.className = 'routing-hub-info-roster-name';
  name.textContent = character.display_name ?? character.character_id;
  const meta = document.createElement('small');
  meta.className = 'routing-hub-info-roster-meta';
  // ルミ carries an explicit role subtitle (she has no 学年/クラブ); the roster cells keep the 学年/クラブ line.
  meta.textContent = character.diary_meta ?? ([character.school_year, character.club].filter(Boolean).join(' / ') || character.character_id);
  body.append(name, meta);
  button.append(image, body);
  button.addEventListener('click', () => loadRoutingHubDiaryForCharacter(bodyEl, character).catch(reportError));
  return button;
}

// Fetch + render the selected character's journal. A loading card shows immediately; the resolved fetch renders
// only if it is still current (token) and the drawer is still on diary. Zero memories is a legitimate empty
// state (not an error); a fetch failure surfaces through the caller's reportError.
async function loadRoutingHubDiaryForCharacter(bodyEl, character) {
  const token = (diaryFetchToken += 1);
  bodyEl.replaceChildren(routingHubDiaryLoadingCard());
  const entries = await fetchCharacterDiary(character.character_id);
  if (token !== diaryFetchToken) return;
  const popup = document.querySelector('#routing-hub-info-popup');
  if (!popup || popup.dataset.category !== 'diary') return;
  bodyEl.replaceChildren(routingHubDiaryBackButton(bodyEl), routingHubDiaryHeader(character, entries.length));
  if (entries.length === 0) {
    bodyEl.append(routingHubInfoEmptyCard('まだ日記がありません', `${character.display_name ?? character.character_id}との思い出は、まだ日記に綴られていません。`, 'diary'));
    return;
  }
  const journal = document.createElement('div');
  journal.className = 'routing-hub-info-diary-entries';
  for (const entry of entries) {
    journal.append(routingHubDiaryEntry(entry));
  }
  bodyEl.append(journal);
}

function routingHubDiaryLoadingCard() {
  const card = document.createElement('div');
  card.className = 'routing-hub-info-diary-loading';
  card.append(screenWaitMark());
  return card;
}

function routingHubDiaryBackButton(bodyEl) {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'routing-hub-info-diary-back';
  dressSigilButton(button, 'back', 'ほかのキャラを選ぶ');
  button.addEventListener('click', () => {
    bodyEl.replaceChildren();
    renderRoutingHubDiaryInto(bodyEl);
  });
  return button;
}

function routingHubDiaryHeader(character, count) {
  const header = document.createElement('div');
  header.className = 'routing-hub-info-diary-header';
  const face = document.createElement('img');
  face.className = 'routing-hub-info-diary-face';
  face.src = routingHubRosterFaceUrl(character);
  face.alt = `${character.display_name ?? character.character_id}の顔`;
  const body = document.createElement('div');
  body.className = 'routing-hub-info-diary-head-body';
  const title = document.createElement('strong');
  title.className = 'routing-hub-info-diary-title';
  title.textContent = `${character.display_name ?? character.character_id}の日記`;
  body.append(title);
  // A journal with no entries says so with the empty picture below the header, so the header carries no count then.
  if (count > 0) {
    const note = document.createElement('span');
    note.className = 'routing-hub-info-diary-count';
    note.textContent = `${count}件の記録`;
    body.append(note);
  }
  header.append(face, body);
  return header;
}

// One journal entry = the memory text as-is, in a left-ruled 手記風 block. Chronological order is preserved by
// the caller iterating entries as received (parseDiaryEntries never re-sorts).
function routingHubDiaryEntry(entry) {
  const block = document.createElement('article');
  block.className = 'routing-hub-info-diary-entry';
  const text = document.createElement('p');
  text.className = 'routing-hub-info-diary-entry-text';
  text.textContent = entry.text;
  block.append(text);
  return block;
}

// ── 関連する本 (library footnotes) — the footnote strip of the ハブ収蔵庫 re-read ─────────────────────────────
// 本文 and its 脚注 are two SEPARATE requests: POST /api/library/read banks the fragment into the 収蔵庫 and
// returns collection_entry_id, then POST /api/library/footnotes { entry_id } answers { entry_id, references }.
// The body is already banked when the footnote call starts, so a slow or failed footnote never costs the reading:
// it is a LOCAL state at the end of the body with an explicit 再試行 (no auto retry, and an HTTP error / malformed
// payload is never read as an empty list — parseLibraryFootnotes refuses it, so 0件 and 失敗 stay distinguishable).
// An LM-config failure here is handled as this local failure too — routing to the settings screen would throw away
// the body the player already has.
//
// The three states (pending / ready / failed) are drawn by renderLibraryFootnotesInto into the ハブ収蔵庫 drawer (the
// 大書庫 見開き draws the same states as ink footnotes under the end of the body — libraryScreen.js — with the same wording). The ink and
// rules come from the host's own token layer through CSS scope (#routing-hub-info-popup-body), so this renderer pins
// no color.
//
// Staleness: every opened book takes the next generation token. A resolved / failed call commits only while its
// captured token is still current, its host is still in the document, AND its host view is still on screen —
// closing the book, going back to the shelf, picking another book, closing the drawer or switching category all
// abandon it, so an old answer (or an old failure) can never land on a newly opened book.
let libraryFootnoteGeneration = 0;

function nextLibraryFootnoteGeneration() {
  libraryFootnoteGeneration += 1;
  return libraryFootnoteGeneration;
}

// The strip lives at the very end of the body it belongs to (inside the 大書庫 page's own scroller / right after
// the saved 収蔵 body), never as a separately stacked card.
function buildLibraryFootnotesHost() {
  const host = document.createElement('section');
  host.className = 'library-footnotes';
  return host;
}

// The 関連する本 heading. It titles the strip in EVERY state it draws — the resolved list and the failure alike —
// so a reader who has the strip open never has to guess what the line under the rule is about.
function libraryFootnotesHeading() {
  const heading = document.createElement('p');
  heading.className = 'library-footnotes-heading';
  heading.textContent = '関連する本';
  return heading;
}

function libraryFootnotesStatusLine(text) {
  const line = document.createElement('p');
  line.className = 'library-footnotes-status';
  line.setAttribute('role', 'status');
  line.setAttribute('aria-live', 'polite');
  const label = document.createElement('span');
  label.className = 'library-footnotes-status-label';
  label.textContent = text;
  line.append(label);
  return line;
}

// One 関連する本 row. A readable reference is an underlined title that reads it; an unreadable (禁書) one is the
// title plus 今は開けない — NOT a link, and carrying nothing else the backend refused to send (no gate value, no
// 骨子, no 分類).
function libraryFootnoteItem(reference, onOpen) {
  const item = document.createElement('li');
  item.className = 'library-footnotes-item';
  item.dataset.readable = String(reference.readable);
  if (!reference.readable) {
    const unreadable = document.createElement('span');
    unreadable.className = 'library-footnotes-unreadable';
    const title = document.createElement('span');
    title.className = 'library-footnotes-unreadable-title';
    title.textContent = reference.title;
    const note = document.createElement('span');
    note.className = 'library-footnotes-unreadable-note';
    note.textContent = '今は開けない';
    unreadable.append(title, note);
    item.append(unreadable);
    return item;
  }
  const link = document.createElement('button');
  link.type = 'button';
  link.className = 'library-footnotes-link';
  link.textContent = reference.title;
  link.addEventListener('click', () => onOpen(reference));
  item.append(link);
  return item;
}

// Draw one footnote state into a host. Both drawn states open with the same 関連する本 heading under the rule:
// ready is 見出し → 題の行, failed is 見出し → 読み込めませんでした + 再試行. 'ready' with zero references removes
// the host entirely — a 中核 book whose 関連宣言 is empty gets NO 関連する本 box, not an empty one (and a pending
// wait is the screen wait mark alone). An unknown state is a wiring bug → throw.
function renderLibraryFootnotesInto(host, state) {
  if (!host) throw new Error('library footnotes host is missing (broken wiring)');
  const status = state?.status;
  if (status === 'pending') {
    host.dataset.state = 'pending';
    host.replaceChildren(screenWaitMark());
    return;
  }
  if (status === 'failed') {
    host.dataset.state = 'failed';
    const line = libraryFootnotesStatusLine('関連する本を読み込めませんでした。');
    const retry = document.createElement('button');
    retry.type = 'button';
    retry.className = 'library-footnotes-retry';
    retry.textContent = '再試行';
    retry.addEventListener('click', state.onRetry);
    line.append(retry);
    host.replaceChildren(libraryFootnotesHeading(), line);
    return;
  }
  if (status !== 'ready') {
    throw new Error(`library footnotes state must be pending / ready / failed, got ${JSON.stringify(status)}`);
  }
  if (state.references.length === 0) {
    host.remove();
    return;
  }
  host.dataset.state = 'ready';
  const list = document.createElement('ul');
  list.className = 'library-footnotes-list';
  for (const reference of state.references) list.append(libraryFootnoteItem(reference, state.onOpen));
  host.replaceChildren(libraryFootnotesHeading(), list);
}

// The stale guard every async footnote commit passes: same generation, host still in the document, and the host
// view still on screen (context.isCurrent).
function libraryFootnoteContextIsCurrent(host, context) {
  return context.generation === libraryFootnoteGeneration && host.isConnected && context.isCurrent();
}

function failLibraryFootnotes(host, context, error) {
  // The reason is recorded (never a silent catch) and the failure stays local: body, 本を閉じる / ← 棚に戻る and
  // the rest of the view are untouched, and 再試行 re-sends the SAME entry_id once.
  console.error(error);
  if (!libraryFootnoteContextIsCurrent(host, context)) return;
  renderLibraryFootnotesInto(host, {
    status: 'failed',
    onRetry: () => { loadLibraryFootnotesInto(host, context).catch(reportError); }
  });
}

async function loadLibraryFootnotesInto(host, context) {
  renderLibraryFootnotesInto(host, { status: 'pending' });
  let payload;
  try {
    payload = await postJson(LIBRARY_FOOTNOTES_REQUEST_PATH, { entry_id: context.entryId });
  } catch (error) {
    failLibraryFootnotes(host, context, error);
    return;
  }
  if (!libraryFootnoteContextIsCurrent(host, context)) return;
  let references;
  try {
    references = parseLibraryFootnotes(payload, { entryId: context.entryId, layer: context.layer });
  } catch (error) {
    failLibraryFootnotes(host, context, error);
    return;
  }
  renderLibraryFootnotesInto(host, { status: 'ready', references, onOpen: context.onOpen });
}

// ── 収蔵庫 (library collection) — the routing hub's 7th info-drawer category, hub-only ─────────────────────────
// The 大書庫 (library) destination commits every read fragment to the per-slot 収蔵庫 server-side; this drawer is
// the ONLY place it is surfaced (うゆりすさん確定: hub-only — no 書庫画面-internal view, no other-screen 導線). It
// follows the diary async-category grammar: the sync renderer shows a loading card and kicks off the async loader
// (GET /api/library/collection, LM-free), which fills the 自分の書斎棚 with small spines — ordered by the chosen
// 並び替え軸, a display-only choice that writes nothing to storage. Picking a spine re-reads the SAVED text as-is
// (no read call, no re-generation — the entry carries its own point-in-time fragment) and fetches only its 脚注;
// ← 棚に戻る re-renders the shelf from the last server answer. お気に入り and 処分 are explicit mutations whose
// RESPONSE entries are the authority (never a locally guessed toggle), and 処分 goes through an in-drawer
// confirmation. A 関連する本 move reads inside the drawer: the hub screen never changes and the drawer stays open.
// An absent / empty collection is a legitimate initial state → a quiet empty card, not an error; a fetch failure /
// malformed response surfaces through reportError (no silent swallow). The read/parse/sort contract lives in the
// headless-tested libraryCollectionViewClient.js.
const LIBRARY_COLLECTION_SORT_LABELS = Object.freeze({
  read_week: '読んだ週',
  title: '題',
  category: '分類',
  favorite: 'お気に入り'
});

// 並び替え is display state for the page session: the chosen 軸 survives ← 棚に戻る and re-opening the drawer, and
// is never persisted. Its initial value is the closed set's first key (読んだ週, newest first).
let libraryCollectionSortKey = LIBRARY_COLLECTION_SORT_KEYS[0];

// The drawer's live view: the entries the server last returned, the entry currently open (null on the shelf), and
// the body node they are drawn into. Every mutation answer replaces the entries, so 棚 and 開いている本 always show
// what the server last said.
let routingHubLibraryView = null;

// Single-flight guard shared by every 収蔵庫 action that talks to the server (お気に入り / 処分 / 関連本への移動),
// so a double press — or two different actions raced together — never issues a second POST.
let libraryCollectionActionInFlight = false;

async function fetchLibraryCollection() {
  const response = await fetch(LIBRARY_COLLECTION_REQUEST_PATH);
  if (!response.ok) {
    throw new Error(`library collection fetch failed: HTTP ${response.status}`);
  }
  return parseLibraryCollectionEntries(await response.json());
}

// Sync renderer: 収蔵庫 opens straight into a load (no picker — unlike diary). A loading card shows immediately,
// then the async loader fills the shelf. Bumping the token abandons any in-flight fetch on re-open (diary文法).
function renderRoutingHubLibraryCollectionInto(bodyEl) {
  const token = (libraryCollectionFetchToken += 1);
  nextLibraryFootnoteGeneration();
  closeRoutingHubLibraryDisposeConfirm();
  routingHubLibraryView = null;
  bodyEl.replaceChildren(routingHubLibraryLoadingCard());
  loadRoutingHubLibraryCollection(bodyEl, token).catch(reportError);
}

async function loadRoutingHubLibraryCollection(bodyEl, token) {
  const entries = await fetchLibraryCollection();
  if (token !== libraryCollectionFetchToken) return;
  if (!routingHubLibraryDrawerIsOpen()) return;
  renderRoutingHubLibraryShelf(bodyEl, entries);
}

// The drawer is still the live 収蔵庫 view: open, on the library category, and its body still in the document.
function routingHubLibraryDrawerIsOpen() {
  const popup = document.querySelector('#routing-hub-info-popup');
  return Boolean(popup) && !popup.hidden && popup.dataset.category === 'library';
}

function routingHubLibraryViewIsLive() {
  return routingHubLibraryDrawerIsOpen() && Boolean(routingHubLibraryView) && routingHubLibraryView.bodyEl.isConnected;
}

// The 自分の書斎棚: entries as small spines on a shelf, in the chosen 並び替え order. Empty is a legitimate initial
// state — and carries no 並び替え row, since there is nothing to order.
function renderRoutingHubLibraryShelf(bodyEl, entries) {
  nextLibraryFootnoteGeneration();
  routingHubLibraryView = { bodyEl, entries, entry: null };
  bodyEl.replaceChildren();
  if (entries.length === 0) {
    bodyEl.append(routingHubInfoEmptyCard('まだ何も収蔵されていません', '大書庫で本を読むと、その写しがここへ並びます。', 'shelf'));
    return;
  }
  bodyEl.append(routingHubLibrarySortRow());
  const shelf = document.createElement('div');
  shelf.className = 'routing-hub-info-library-shelf';
  for (const entry of sortLibraryCollectionEntries(entries, libraryCollectionSortKey)) {
    shelf.append(routingHubLibrarySpineButton(entry));
  }
  bodyEl.append(shelf);
}

// 並び替え: the closed 4軸 select above the shelf. Choosing an 軸 only re-draws the shelf — the
// received entries are untouched and nothing is written to storage. A value outside the closed set is a wiring
// bug → throw before anything is re-rendered.
function routingHubLibrarySortRow() {
  const row = document.createElement('div');
  row.className = 'routing-hub-info-library-sort';
  const label = document.createElement('label');
  label.className = 'routing-hub-info-library-sort-label';
  label.setAttribute('for', 'routing-hub-info-library-sort-select');
  label.textContent = '並び替え';
  const select = document.createElement('select');
  select.className = 'routing-hub-info-library-sort-select';
  select.id = 'routing-hub-info-library-sort-select';
  for (const key of LIBRARY_COLLECTION_SORT_KEYS) {
    const option = document.createElement('option');
    option.value = key;
    option.textContent = LIBRARY_COLLECTION_SORT_LABELS[key];
    select.append(option);
  }
  select.value = libraryCollectionSortKey;
  select.addEventListener('change', () => {
    const sortKey = select.value;
    if (!LIBRARY_COLLECTION_SORT_KEYS.includes(sortKey)) {
      throw new Error(`library collection sort select produced an unknown key ${JSON.stringify(sortKey)}`);
    }
    libraryCollectionSortKey = sortKey;
    renderRoutingHubLibraryShelf(routingHubLibraryView.bodyEl, routingHubLibraryView.entries);
  });
  row.append(label, select);
  return row;
}

// One 背表紙 (book spine): the layer picks its 装丁 tone (data-layer — core=革装金箔系 / periphery=布装彩色系 /
// generated=無銘写本系, all routing-token accents) and the top carries the お気に入り ★ — a non-favorite spine keeps
// the same line, unmarked, so the shelf stays even. Clicking re-reads the saved fragment.
function routingHubLibrarySpineButton(entry) {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'routing-hub-info-library-spine';
  button.dataset.layer = entry.layer;
  const favorite = document.createElement('span');
  favorite.className = 'routing-hub-info-library-spine-favorite';
  favorite.dataset.on = String(entry.favorite);
  favorite.textContent = '★';
  const title = document.createElement('span');
  title.className = 'routing-hub-info-library-spine-title';
  title.textContent = entry.title;
  button.append(favorite, title);
  button.addEventListener('click', () => showRoutingHubLibraryEntry(entry));
  return button;
}

// Re-reading a collected book shows the SAVED text as-is — no read call, no re-generation (the entry carries its
// own point-in-time fragment); only its 脚注 are fetched. ← 棚に戻る re-renders the shelf from the entries the
// server last returned, keeping the chosen 並び替え.
function showRoutingHubLibraryEntry(entry) {
  const bodyEl = routingHubLibraryView.bodyEl;
  nextLibraryFootnoteGeneration();
  routingHubLibraryView = { bodyEl, entries: routingHubLibraryView.entries, entry };
  bodyEl.replaceChildren(
    routingHubLibraryBackButton(),
    routingHubLibraryEntryHeader(entry),
    routingHubLibraryEntryActions(entry),
    routingHubLibraryErrorLine()
  );
  const text = document.createElement('p');
  text.className = 'routing-hub-info-library-entry-text';
  text.textContent = entry.text;
  bodyEl.append(text);
  const host = buildLibraryFootnotesHost();
  bodyEl.append(host);
  loadLibraryFootnotesInto(host, {
    generation: libraryFootnoteGeneration,
    entryId: entry.entry_id,
    layer: entry.layer,
    isCurrent: routingHubLibraryDrawerIsOpen,
    onOpen: (reference) => followRoutingHubLibraryFootnote(reference).catch(reportError)
  }).catch(reportError);
}

function routingHubLibraryBackButton() {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'routing-hub-info-library-back';
  dressSigilButton(button, 'back', '棚に戻る');
  button.addEventListener('click', () => renderRoutingHubLibraryShelf(routingHubLibraryView.bodyEl, routingHubLibraryView.entries));
  return button;
}

function routingHubLibraryEntryHeader(entry) {
  const header = document.createElement('div');
  header.className = 'routing-hub-info-library-entry-header';
  const title = document.createElement('strong');
  title.className = 'routing-hub-info-library-entry-title';
  title.textContent = entry.title;
  const meta = document.createElement('span');
  meta.className = 'routing-hub-info-library-entry-meta';
  // read_week is the raw elapsed_weeks at read time; conversationStageWeek renders the 1-based display week.
  meta.textContent = `${entry.category}・第${conversationStageWeek(entry.read_week)}週に読んだ`;
  header.append(title, meta);
  return header;
}

// お気に入り・処分 の1行: between the 題/分類/週 header and the saved body.
function routingHubLibraryEntryActions(entry) {
  const row = document.createElement('div');
  row.className = 'routing-hub-info-library-actions';
  const favorite = document.createElement('button');
  favorite.type = 'button';
  favorite.className = 'routing-hub-info-library-favorite';
  favorite.dataset.on = String(entry.favorite);
  favorite.textContent = `${entry.favorite ? '★' : '☆'} お気に入り`;
  favorite.addEventListener('click', () => toggleRoutingHubLibraryFavorite(entry).catch(reportError));
  const dispose = document.createElement('button');
  dispose.type = 'button';
  dispose.className = 'routing-hub-info-library-dispose';
  dispose.textContent = '処分';
  dispose.addEventListener('click', () => openRoutingHubLibraryDisposeConfirm(entry));
  row.append(favorite, dispose);
  return row;
}

// The drawer's own error line: a failed お気に入り / 処分 / 関連本への移動 says so HERE, leaving the saved body and
// the shelf exactly as they were (hidden — and so absent from layout — until something fails).
function routingHubLibraryErrorLine() {
  const line = document.createElement('p');
  line.className = 'routing-hub-info-library-error';
  line.setAttribute('role', 'status');
  line.setAttribute('aria-live', 'polite');
  line.hidden = true;
  return line;
}

function setRoutingHubLibraryError(message) {
  const line = routingHubLibraryView?.bodyEl.querySelector('.routing-hub-info-library-error');
  if (!line) return;
  const text = String(message ?? '').trim();
  line.hidden = text === '';
  line.textContent = text;
}

// お気に入り: POST the INVERTED value and adopt the returned entries as the authority — the button's own mark is
// never flipped before the server answers, and a failure changes nothing but the error line.
async function toggleRoutingHubLibraryFavorite(entry) {
  if (libraryCollectionActionInFlight) {
    showProcessingToast();
    return;
  }
  libraryCollectionActionInFlight = true;
  try {
    setRoutingHubLibraryError('');
    const payload = await postJson(LIBRARY_COLLECTION_FAVORITE_PATH, { entry_id: entry.entry_id, favorite: !entry.favorite });
    const entries = parseLibraryCollectionEntries(payload);
    if (!routingHubLibraryViewIsLive()) return;
    const next = requireLibraryCollectionEntry(entries, entry.entry_id);
    routingHubLibraryView = { bodyEl: routingHubLibraryView.bodyEl, entries, entry: next };
    // Only the actions row is redrawn: the saved body and its already-fetched 脚注 stay as they are (a shelf mark
    // is not a re-reading, so it must not cost another footnote generation).
    const actions = routingHubLibraryView.bodyEl.querySelector('.routing-hub-info-library-actions');
    if (actions) actions.replaceWith(routingHubLibraryEntryActions(next));
  } catch (error) {
    console.error(error);
    if (!routingHubLibraryViewIsLive()) return;
    setRoutingHubLibraryError(`お気に入りを変更できませんでした。${errorDisplayMessage(error)}`);
  } finally {
    libraryCollectionActionInFlight = false;
  }
}

// The 処分 confirmation: an overlay INSIDE the drawer card (the hub screen never changes). It names the book, asks
// once, and offers やめる / 処分する in that order. The initial selection is やめる and is shown through :focus —
// not :focus-visible — so it is visible whether the confirmation was opened by mouse or by keyboard. Tab /
// Shift+Tab move the selection between the two buttons and nothing else, so focus stays inside the confirmation.
function openRoutingHubLibraryDisposeConfirm(entry) {
  const card = document.querySelector('.routing-hub-info-popup-card');
  if (!card) throw new Error('routing hub info drawer card (.routing-hub-info-popup-card) is missing (broken markup wiring)');
  if (card.querySelector('.routing-hub-info-library-confirm')) return;
  const overlay = document.createElement('div');
  overlay.className = 'routing-hub-info-library-confirm';
  overlay.setAttribute('role', 'dialog');
  overlay.setAttribute('aria-modal', 'true');
  const confirmCard = document.createElement('div');
  confirmCard.className = 'routing-hub-info-library-confirm-card';
  const title = document.createElement('p');
  title.className = 'routing-hub-info-library-confirm-title';
  title.textContent = entry.title;
  const question = document.createElement('p');
  question.className = 'routing-hub-info-library-confirm-question';
  question.textContent = 'この本を棚から処分しますか？';
  const row = document.createElement('div');
  row.className = 'routing-hub-info-library-confirm-row';
  const cancel = document.createElement('button');
  cancel.type = 'button';
  cancel.className = 'routing-hub-info-library-confirm-cancel';
  dressSigilButton(cancel, 'keep', 'やめる');
  cancel.addEventListener('click', () => closeRoutingHubLibraryDisposeConfirm());
  const accept = document.createElement('button');
  accept.type = 'button';
  accept.className = 'routing-hub-info-library-confirm-accept';
  dressSigilButton(accept, 'dispose', '処分する');
  accept.addEventListener('click', () => disposeRoutingHubLibraryEntry(entry).catch(reportError));
  overlay.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') {
      event.preventDefault();
      event.stopPropagation();
      closeRoutingHubLibraryDisposeConfirm();
      return;
    }
    if (event.key !== 'Tab') return;
    event.preventDefault();
    (document.activeElement === cancel ? accept : cancel).focus();
  });
  row.append(cancel, accept);
  confirmCard.append(title, question, row);
  overlay.append(confirmCard);
  card.append(overlay);
  cancel.focus();
}

// やめる / Escape: the confirmation closes and NOTHING was sent — the book is still on the shelf and still open.
function closeRoutingHubLibraryDisposeConfirm() {
  const overlay = document.querySelector('.routing-hub-info-library-confirm');
  if (overlay) overlay.remove();
}

// 処分する: the only path that sends POST /api/library/collection/dispose, once. The returned entries are the
// authority for the shelf that comes back (an お気に入り book disposes through this same confirmation); a failure
// keeps the saved view and says so.
async function disposeRoutingHubLibraryEntry(entry) {
  if (libraryCollectionActionInFlight) {
    showProcessingToast();
    return;
  }
  libraryCollectionActionInFlight = true;
  try {
    const payload = await postJson(LIBRARY_COLLECTION_DISPOSE_PATH, { entry_id: entry.entry_id });
    const entries = parseLibraryCollectionEntries(payload);
    if (!routingHubLibraryViewIsLive()) return;
    closeRoutingHubLibraryDisposeConfirm();
    renderRoutingHubLibraryShelf(routingHubLibraryView.bodyEl, entries);
  } catch (error) {
    console.error(error);
    if (!routingHubLibraryViewIsLive()) return;
    closeRoutingHubLibraryDisposeConfirm();
    setRoutingHubLibraryError(`本を処分できませんでした。${errorDisplayMessage(error)}`);
  } finally {
    libraryCollectionActionInFlight = false;
  }
}

// A 関連する本 move from the 収蔵 re-read: the real read API runs, but the wait is covered INSIDE the drawer card
// and the hub screen never changes. On success the saved copy is the authority — the shelf is re-fetched and the
// entry the read just banked is looked up by its collection_entry_id (an id the refreshed shelf does not carry is
// broken state → throw; read_week / favorite are never guessed). A failed read leaves the open book untouched; a
// failed refresh says the reading WAS banked but the shelf could not be updated, and never re-reads the book.
async function followRoutingHubLibraryFootnote(reference) {
  if (libraryCollectionActionInFlight) {
    showProcessingToast();
    return;
  }
  const target = libraryFootnoteReadTarget(reference);
  libraryCollectionActionInFlight = true;
  setRoutingHubLibraryError('');
  setRoutingHubLibraryBusy(true);
  try {
    let reading;
    try {
      reading = validateLibraryReadResult(await postJson('/api/library/read', target));
    } catch (error) {
      console.error(error);
      if (routingHubLibraryViewIsLive()) setRoutingHubLibraryError(`関連する本を開けませんでした。${errorDisplayMessage(error)}`);
      return;
    }
    try {
      const entries = await fetchLibraryCollection();
      if (!routingHubLibraryViewIsLive()) return;
      routingHubLibraryView = { bodyEl: routingHubLibraryView.bodyEl, entries, entry: null };
      showRoutingHubLibraryEntry(requireLibraryCollectionEntry(entries, reading.collectionEntryId));
    } catch (error) {
      console.error(error);
      if (routingHubLibraryViewIsLive()) setRoutingHubLibraryError(`本は読み終えて収蔵しましたが、書斎棚を読み直せませんでした。${errorDisplayMessage(error)}`);
    }
  } finally {
    libraryCollectionActionInFlight = false;
    setRoutingHubLibraryBusy(false);
  }
}

// The entry a mutation / refresh answer must contain. A missing id is broken state — never a fabricated entry.
function requireLibraryCollectionEntry(entries, entryId) {
  const entry = entries.find((candidate) => candidate.entry_id === entryId);
  if (!entry) throw new Error(`library collection has no entry ${JSON.stringify(entryId)} (broken 収蔵 state)`);
  return entry;
}

// The in-drawer wait cover for a 関連する本 move: a veil holding the screen wait mark (the wait sigil turns in the
// bottom-right corner), in the routing token layer, sized to the drawer card so the hub behind it stays visible and
// unchanged.
function setRoutingHubLibraryBusy(active) {
  const card = document.querySelector('.routing-hub-info-popup-card');
  if (!card) throw new Error('routing hub info drawer card (.routing-hub-info-popup-card) is missing (broken markup wiring)');
  const existing = card.querySelector('.routing-hub-info-library-busy');
  if (existing) existing.remove();
  if (!active) return;
  const overlay = document.createElement('div');
  overlay.className = 'routing-hub-info-library-busy';
  overlay.append(screenWaitMark());
  card.append(overlay);
}

function routingHubLibraryLoadingCard() {
  const card = document.createElement('div');
  card.className = 'routing-hub-info-library-loading';
  card.append(screenWaitMark());
  return card;
}

// ─────────────────────────────────────────────────────────────────────────────
// Daytime conversation screen — the SECOND consumer of the shared conversation stage
// (conversationStage.js). It is its own screen (#conversation-day-screen) with its own chat DOM, history,
// streaming, status, ambient, and info drawer — the same composition as the routing hub, but it talks to a
// SELECTABLE ROSTER academy character (not the routing persona ルミ) over the ordinary character
// conversation API (opening / turn / stream). It carries NONE of the hub-specific mechanics (destination
// judgment, in-turn dispatch, drain-on-exit, week progression): a daytime turn just reveals the reply and
// commits state. The invariant chat mechanics (reveal queue, at-bottom gate, info drawer, week/moon, status,
// screen-class flashes) all come from the stage, so nothing is reimplemented and loop / academy / routing
// stay byte-equivalent. Axis 1 (scope/theme) = the #conversation-day-* selectors + /canonical/conversation_day
// assets + a daytime light-motes ambient; axis 2 (conversation type) = the active roster character's persona
// visual + identity, the five info categories + daytime renderers, and the runtime week.
// ─────────────────────────────────────────────────────────────────────────────

const CONVERSATION_DAY_TOTAL_WEEKS = 50;

// The daytime info drawer's fixed category set (自分/バディ/エネミー/持ち物/お金) + their titles. The stage
// validates a category against this set (fail-fast on anything else) before rendering it.
const CONVERSATION_DAY_CATEGORY_TITLES = Object.freeze({
  self: '自分',
  buddy: 'バディー',
  enemy: 'エネミー',
  inventory: '持ち物',
  money: 'お金',
  diary: '日記'
});

// Daytime ambient strategy ({ start(), stop() }) injected into the stage — the daytime counterpart of the
// routing starfield, NOT a reused starfield. Soft warm light motes drift up and sway behind the stage; the
// deterministic lattice reuses the stage module's shared buildConversationStageStars (pure logic reuse, not a
// forked implementation). moteCount is required and validated (no default-value fallback). prefers-reduced-
// motion draws a single static field and runs no rAF loop; the mode is surfaced on the canvas dataset so it
// is observable (canvas.dataset.ambient = 'static' | 'animated').
function createConversationDayAmbient({ canvasSelector, moteColorRgb, moteCount }) {
  if (!Number.isInteger(moteCount) || moteCount <= 0) {
    throw new Error(`conversation day ambient requires a positive integer moteCount, got ${JSON.stringify(moteCount)}`);
  }
  // Reduced-motion is read from the live matchMedia result (no fabricated reduced-motion default): a missing
  // matchMedia is a broken browser environment for a client-only component — fail fast rather than silently
  // continuing as if reduced motion were off.
  if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') {
    throw new Error('conversation day ambient requires window.matchMedia (prefers-reduced-motion) — unavailable in this environment');
  }
  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
  let frame = null;
  let motes = null;

  function draw(ctx, width, height, t) {
    ctx.clearRect(0, 0, width, height);
    const span = height + 40;
    for (const mote of motes) {
      const sway = reducedMotion.matches ? 0 : Math.sin(t * 0.0004 * mote.speed + mote.phase) * 12;
      const rise = reducedMotion.matches ? 0 : (t * 0.012 * mote.speed) % span;
      const x = mote.x + sway;
      const y = ((mote.y - rise) % span + span) % span;
      const alpha = reducedMotion.matches ? 0.5 : 0.35 + 0.4 * (0.5 + 0.5 * Math.sin(t * 0.001 * mote.speed + mote.phase));
      ctx.beginPath();
      ctx.arc(x, y, mote.radius * 1.6, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(${moteColorRgb}, ${alpha.toFixed(3)})`;
      ctx.fill();
    }
  }

  return {
    start() {
      // Fail-fast (no silent no-op / default-value fallback): the motes canvas ships in the daytime markup and
      // the screen is active + laid out before renderScreen starts the ambient, so a missing canvas node, an
      // unusable 2D context, or a zero-size canvas is broken state — surface it rather than fabricating a
      // canvas size or quietly skipping the ambient.
      const canvas = document.querySelector(canvasSelector);
      if (!canvas || typeof canvas.getContext !== 'function') {
        throw new Error(`conversation day ambient canvas ${JSON.stringify(canvasSelector)} is missing or not a canvas (broken markup wiring)`);
      }
      const width = canvas.clientWidth;
      const height = canvas.clientHeight;
      if (!Number.isFinite(width) || width <= 0 || !Number.isFinite(height) || height <= 0) {
        throw new Error(`conversation day ambient canvas has no laid-out size (${width}x${height}); the daytime screen must be active and laid out before the ambient starts`);
      }
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');
      if (!ctx) {
        throw new Error('conversation day ambient could not acquire a 2D canvas context');
      }
      motes = buildConversationStageStars(width, height, moteCount);
      if (frame) cancelAnimationFrame(frame);
      if (reducedMotion.matches) {
        canvas.dataset.ambient = 'static';
        draw(ctx, width, height, 0);
        return;
      }
      canvas.dataset.ambient = 'animated';
      let startTime = null;
      const loop = (time) => {
        if (startTime === null) startTime = time;
        draw(ctx, width, height, time - startTime);
        frame = requestAnimationFrame(loop);
      };
      frame = requestAnimationFrame(loop);
    },
    stop() {
      if (frame) {
        cancelAnimationFrame(frame);
        frame = null;
      }
    }
  };
}

// ── Daytime info drawer content builders ─────────────────────────────────────
// The daytime category renderers wired into conversationDayStage.categoryRenderers. They surface the SAME
// data the routing hub renderers do (the same academy relationship / inventory / money selectors — pure data
// logic reused), but paint the bodies with daytime-scoped conversation-day-info-* classes so they are not
// bound to the --routing-* token layer (presentation is daytime-scoped; only the data selection is shared).
// The per-category fail-fast (self / money / inventory item validation) is kept identical to the routing hub.
function conversationDayInfoEmptyCard(title, note) {
  const card = document.createElement('div');
  card.className = 'conversation-day-info-empty-card';
  const heading = document.createElement('strong');
  heading.className = 'conversation-day-info-empty-title';
  heading.textContent = title;
  const body = document.createElement('p');
  body.className = 'conversation-day-info-empty-note';
  body.textContent = note;
  card.append(heading, body);
  return card;
}

function conversationDayInfoSummary(countText, labelText) {
  const summary = document.createElement('div');
  summary.className = 'conversation-day-info-summary';
  const count = document.createElement('strong');
  count.className = 'conversation-day-info-summary-count';
  count.textContent = countText;
  const label = document.createElement('span');
  label.className = 'conversation-day-info-summary-label';
  label.textContent = labelText;
  summary.append(count, label);
  return summary;
}

function conversationDayRosterFaceUrl(character) {
  return character.selection_icon_url ?? character.face_url ?? sourceSheetImageUrl({ characterId: character.character_id, view: 'face' });
}

function conversationDayInfoMetaChips(character) {
  const row = document.createElement('div');
  row.className = 'conversation-day-info-chip-row';
  for (const value of [character.school_year, character.club]) {
    if (!value) continue;
    const chip = document.createElement('span');
    chip.className = 'conversation-day-info-chip';
    chip.textContent = value;
    row.append(chip);
  }
  return row;
}

// The buddy category is async against the GET /api/relationships/buddy truth source (loading card immediately →
// fetch → stale-token + still-on-buddy guard), so a homunculus buddy renders instead of throwing as a dangling
// roster id. routing hub / academy-map (loadRoutingHubBuddyInto / loadAcademyMapBuddyInfo) は同型。
function renderConversationDayBuddyInto(bodyEl) {
  loadConversationDayBuddyInto(bodyEl).catch(reportError);
}

async function loadConversationDayBuddyInto(bodyEl) {
  const token = (buddyViewFetchToken += 1);
  bodyEl.replaceChildren(conversationDayInfoLoadingCard());
  const view = await fetchBuddyView();
  if (token !== buddyViewFetchToken) return;
  const popup = document.querySelector('#conversation-day-info-popup');
  if (!popup || popup.dataset.category !== 'buddy') return;
  const subject = resolveBuddyPanelSubject(view);
  if (!subject) {
    bodyEl.replaceChildren(conversationDayInfoEmptyCard('バディー記録なし', 'バディーはいません。'));
    return;
  }
  bodyEl.replaceChildren(conversationDayBuddyHeroCard(subject));
}

// The buddy hero card: a homunculus shows its endpoint face_url / display_name + a 好感度 affinity chip (no roster
// meta), a selectable character shows its roster face / name + 学年・クラブ chips (現行同等). Day-scoped classes only.
function conversationDayBuddyHeroCard(subject) {
  const card = document.createElement('div');
  card.className = 'conversation-day-info-buddy-card';
  const portrait = document.createElement('img');
  portrait.className = 'conversation-day-info-portrait';
  const body = document.createElement('div');
  body.className = 'conversation-day-info-buddy-body';
  const name = document.createElement('strong');
  name.className = 'conversation-day-info-buddy-name';
  if (subject.kind === 'homunculus') {
    const buddy = subject.homunculus;
    portrait.src = buddy.face_url;
    portrait.alt = `${buddy.display_name}の顔`;
    name.textContent = buddy.display_name;
    const chips = document.createElement('div');
    chips.className = 'conversation-day-info-chip-row';
    chips.append(buddyAffinityChip(buddy.affinity, 'conversation-day-info-chip'));
    body.append(name, chips);
  } else {
    const buddy = subject.roster;
    portrait.src = conversationDayRosterFaceUrl(buddy);
    portrait.alt = `${buddy.display_name ?? buddy.character_id}の顔`;
    name.textContent = buddy.display_name ?? buddy.character_id;
    body.append(name);
    const chips = conversationDayInfoMetaChips(buddy);
    if (chips.childElementCount > 0) body.append(chips);
  }
  card.append(portrait, body);
  return card;
}

function conversationDayInfoLoadingCard() {
  const card = document.createElement('div');
  card.className = 'conversation-day-info-loading';
  card.append(screenWaitMark());
  return card;
}

function conversationDayInfoRosterCard(character) {
  const card = document.createElement('div');
  card.className = 'conversation-day-info-roster-card';
  const image = document.createElement('img');
  image.className = 'conversation-day-info-roster-face';
  image.src = conversationDayRosterFaceUrl(character);
  image.alt = `${character.display_name ?? character.character_id}の顔`;
  const body = document.createElement('div');
  body.className = 'conversation-day-info-roster-body';
  const name = document.createElement('strong');
  name.className = 'conversation-day-info-roster-name';
  name.textContent = character.display_name ?? character.character_id;
  const meta = document.createElement('small');
  meta.className = 'conversation-day-info-roster-meta';
  meta.textContent = [character.school_year, character.club].filter(Boolean).join(' / ') || character.character_id;
  body.append(name, meta);
  card.append(image, body);
  return card;
}

function renderConversationDayEnemiesInto(bodyEl) {
  const enemies = resolveInfoDrawerEnemies();
  if (!enemies.length) {
    bodyEl.append(conversationDayInfoEmptyCard('エネミー記録なし', '対立関係のキャラクターはいません。'));
    return;
  }
  bodyEl.append(conversationDayInfoSummary(`${enemies.length}件`, 'エネミー'));
  const list = document.createElement('div');
  list.className = 'conversation-day-info-roster-list';
  list.append(...enemies.map((enemy) => conversationDayInfoRosterCard(enemy)));
  bodyEl.append(list);
}

// ── 会話中の贈与（渡す）───────────────────────────────────────────────────────
// The daytime inventory drawer's 渡す affordance hands a gift / 仲間強化薬 to the current conversation partner
// over POST /api/conversation/gift. It is shown only when a gift is actually possible: a routing daytime
// conversation (currentPlayMode 'routing' — the backend 409s ROUTING_MODE_REQUIRED otherwise) whose partner is a
// selectable roster character (lina / creature / homunculus are absent from the roster, so this excludes them
// exactly as the backend's GIFT_ACTOR_NOT_SELECTABLE does), for a deliverable item, and only until one gift has
// been delivered this conversation (the 1会話1回 gate; the server is the final defense).

// The active daytime conversation id (the backend resolves the gift target from runtime_state.last_conversation_id).
function currentDaytimeConversationId() {
  return String(currentRuntimeState?.last_conversation_id ?? '').trim();
}

// True while the current daytime conversation partner can receive a gift: routing mode + a selectable roster
// partner. This is the single actor gate; it excludes the routing persona (lina), creatures, and homunculi
// because none of them are in the selectable roster.
function conversationGiftEligibleActor() {
  return currentPlayMode === 'routing'
    && selectableCharacters.some((character) => character.character_id === activeCharacterId);
}

// True once a gift has been delivered in the current conversation (client mirror of the backend GIFT_ALREADY_GIVEN
// gate). Keyed on the conversation id, so it resets by itself when the next conversation starts.
function conversationGiftAlreadyGiven() {
  const conversationId = currentDaytimeConversationId();
  return conversationId !== '' && giftGivenConversationId === conversationId;
}

// The fixed 地の文 the backend appends to the record when a gift is handed over (mirrors
// conversationGiftHandoverNarration in app/src/llm/conversationPipeline.mjs). The gift response returns only
// reaction_text (no handover text) and there is no conversation re-fetch endpoint, so reproducing this fixed line
// lets the optimistic reveal stay byte-identical to the record the next turn's commitState adopts — no reorder /
// duplication when the authoritative history is next rebuilt.
function conversationGiftHandoverNarrationText(itemName) {
  const name = String(itemName ?? '').trim();
  if (!name) throw new Error('conversation gift handover narration requires an item name');
  return `主人公が「${name}」を差し出した。`;
}

// Reveal the hand-over 地の文 + the partner's reaction on the daytime stream through the shared cooldown-paced
// reveal queue (one 吹き出し単位 at a time, the same cadence a normal turn uses). The two appended messages match
// the record shape messagesFromConversation produces (a user narration + an assistant reaction with no emotion),
// so the next turn's authoritative commitState rebuild is seamless.
async function revealConversationDayGift(result) {
  const reactionText = String(result?.reaction_text ?? '').trim();
  if (!reactionText) throw new Error(`conversation gift reveal requires reaction_text, got ${JSON.stringify(result?.reaction_text)}`);
  const baseMessages = [...conversationDayStage.surface.getHistory()];
  const handover = { role: 'user', content: conversationGiftHandoverNarrationText(result.item.name) };
  // The reaction carries no emotion (the backend appends the record message without one, and the reveal must not
  // force a neutral icon literal — createMessageRows / messagesFromConversation default a missing emotion to the
  // neutral face), so it renders identically to the record the next commitState rebuild adopts.
  const reaction = {
    role: 'assistant',
    ...conversationDayStage.surface.assistantIdentity(),
    content: reactionText
  };
  const reveal = conversationDayStage.createTurnReveal(baseMessages);
  reveal.enqueue(displayMessages([handover]));
  reveal.enqueue(displayMessages([reaction]));
  await reveal.drain();
  conversationDayStage.surface.setHistory([...baseMessages, handover, reaction]);
  conversationDayStage.renderStream(conversationDayStage.surface.getHistory());
}

// A short, human line for the gift's mechanical effect, shown as a transient toast after the reaction reveals.
// gift → 好感度 before→after (+bonus); ally_boost → each parameter's label before→after (+amount). The effect
// shape is validated against the item category (fail-fast on a mismatch — no silent skip).
function conversationGiftEffectMessage(result) {
  const { item, effect } = result;
  if (item.category === 'gift') {
    if (!effect || typeof effect.affinity_after !== 'number' || typeof effect.affinity_before !== 'number' || typeof effect.bonus !== 'number') {
      throw new Error(`gift effect requires numeric affinity fields, got ${JSON.stringify(effect)}`);
    }
    return `${item.name}を渡した — 好感度 ${effect.affinity_before} → ${effect.affinity_after}（+${effect.bonus}）`;
  }
  if (item.category === 'ally_boost') {
    if (!effect || !Array.isArray(effect.parameter_effects) || effect.parameter_effects.length === 0) {
      throw new Error(`ally_boost effect requires a non-empty parameter_effects array, got ${JSON.stringify(effect)}`);
    }
    const parts = effect.parameter_effects.map((entry) => `${entry.label} ${entry.before} → ${entry.after}（+${entry.amount}）`);
    return `${item.name}を渡した — ${parts.join(' / ')}`;
  }
  throw new Error(`unexpected gift item category: ${JSON.stringify(item.category)}`);
}

// The gift error surfaced on the daytime status line. The 503 generation failure is the one the player retries
// (nothing consumed), so it gets an explicit 未消費・再試行可 line; every other code keeps the existing conversation
// error grammar (the backend message via errorDisplayMessage).
function conversationGiftErrorMessage(error) {
  if (error?.errorCode === 'GIFT_REACTION_GENERATION_FAILED') {
    return '反応の生成に失敗しました。アイテムは消費していません。少し待ってからもう一度お試しください。';
  }
  return errorDisplayMessage(error);
}

// Hand the item over to the current partner: confirm → close the drawer so the reaction is visible on the stream
// → POST /api/conversation/gift → reveal the reaction + toast the effect → sync the roster (ally_boost updates a
// runtime profile, reflected on reload). The shared conversationRequestInFlight + a dedicated single-flight guard
// keep a gift from overlapping a turn or firing twice. A 503 leaves the item unconsumed and retryable.
async function handleConversationDayGift(item) {
  if (conversationRequestInFlight || conversationGiftInFlight) {
    showProcessingToast();
    return;
  }
  // Defense: the render gate already hides the button off these, but re-check before the network call so a stale
  // click (e.g. the drawer left open across a conversation change) never fires an out-of-context gift.
  if (!conversationGiftEligibleActor() || conversationGiftAlreadyGiven()) return;
  const partnerName = activeCharacter().display_name;
  if (!window.confirm(`「${item.name}」を${partnerName}に渡しますか？`)) return;
  conversationGiftInFlight = true;
  conversationRequestInFlight = true;
  conversationDayStage.setControlsDisabled(true);
  conversationDayStage.setResponding(true);
  conversationDayStage.setStatus('');
  conversationDayStage.closeInfo();
  let reactionRevealed = false;
  try {
    const { result, state } = await postJson('/api/conversation/gift', { item_id: item.item_id });
    currentRuntimeState = state ?? currentRuntimeState;
    currentInventory = result.inventory;
    giftGivenConversationId = currentDaytimeConversationId();
    await revealConversationDayGift(result);
    reactionRevealed = true;
    showEconomyMessage(conversationGiftEffectMessage(result));
    await refresh().catch(reportError);
  } catch (error) {
    if (handleRuntimeApiError(error, { allowSettingsRedirect: true })) return;
    conversationDayStage.setStatus(conversationGiftErrorMessage(error), { tone: 'error' });
  } finally {
    conversationGiftInFlight = false;
    conversationRequestInFlight = false;
    conversationDayStage.setControlsDisabled(false);
    conversationDayStage.setResponding(false);
    if (reactionRevealed) focusConversationDayInputIfContinuing();
  }
}

function renderConversationDayInventoryInto(bodyEl) {
  const items = currentInventory?.items;
  if (!Array.isArray(items)) {
    throw new Error(`conversation day inventory requires currentInventory.items array, got ${JSON.stringify(items)}`);
  }
  if (items.length === 0) {
    bodyEl.append(conversationDayInfoEmptyCard('持ち物なし', '所持しているアイテムはありません。'));
    return;
  }
  bodyEl.append(conversationDayInfoSummary(`${items.length}種類`, '持ち物'));
  const list = document.createElement('ul');
  list.className = 'conversation-day-info-ledger';
  for (const item of items) {
    if (typeof item.name !== 'string' || item.name === '') {
      throw new Error(`conversation day inventory item requires a non-empty name, got ${JSON.stringify(item)}`);
    }
    if (typeof item.quantity !== 'number' || !Number.isFinite(item.quantity)) {
      throw new Error(`conversation day inventory item requires a numeric quantity, got ${JSON.stringify(item)}`);
    }
    if (typeof item.description !== 'string') {
      throw new Error(`conversation day inventory item requires a description string, got ${JSON.stringify(item)}`);
    }
    // gift_category is the server-authoritative 渡す gate ('gift' | 'ally_boost' | null). A missing field is broken
    // wiring, not "not giftable" — surface it rather than silently hiding the 渡す 導線.
    if (item.gift_category !== null && item.gift_category !== 'gift' && item.gift_category !== 'ally_boost') {
      throw new Error(`conversation day inventory item requires a gift_category of gift|ally_boost|null, got ${JSON.stringify(item)}`);
    }
    const row = document.createElement('li');
    row.className = 'conversation-day-info-ledger-row';
    const head = document.createElement('div');
    head.className = 'conversation-day-info-ledger-head';
    const name = document.createElement('strong');
    name.textContent = item.name;
    const quantity = document.createElement('span');
    quantity.className = 'conversation-day-info-ledger-quantity';
    quantity.textContent = `×${item.quantity.toLocaleString('ja-JP')}`;
    head.append(name, quantity);
    row.append(head);
    const materialMeta = buildInventoryMaterialMeta(item, 'conversation-day-info-ledger-materia');
    if (materialMeta) row.append(materialMeta);
    if (item.description.trim() !== '') {
      const desc = document.createElement('p');
      desc.className = 'conversation-day-info-ledger-desc';
      desc.textContent = item.description;
      row.append(desc);
    }
    // 渡す (会話中の贈与): shown only when a gift is possible (routing daytime conversation + selectable partner)
    // and this owned item is a deliverable category (gift / ally_boost) per the server-authoritative `gift_category`
    // annotation. Disabled once a gift has been delivered this conversation (the 1会話1回 gate; server is final).
    if (conversationGiftEligibleActor() && item.gift_category !== null) {
      const give = document.createElement('button');
      give.type = 'button';
      give.className = 'conversation-day-info-ledger-give';
      give.textContent = '渡す';
      const alreadyGiven = conversationGiftAlreadyGiven();
      give.disabled = alreadyGiven;
      if (alreadyGiven) give.title = 'この会話ではもう渡しています';
      give.addEventListener('click', () => handleConversationDayGift(item).catch(reportError));
      row.append(give);
    }
    list.append(row);
  }
  bodyEl.append(list);
}

function renderConversationDayMoneyInto(bodyEl, money) {
  const card = document.createElement('div');
  card.className = 'conversation-day-info-money-card';
  const value = document.createElement('strong');
  value.className = 'conversation-day-info-money-value';
  value.textContent = moneyText(money);
  const label = document.createElement('span');
  label.className = 'conversation-day-info-money-label';
  label.textContent = '購買で使える資金';
  card.append(value, label);
  bodyEl.append(card);
}

// ── Diary (6th category) ─────────────────────────────────────────────────────
// The daytime diary shows ONLY the current conversation partner's journal (no roster picker): the partner is the
// active roster character. It is resolved fail-fast from the selectable roster (never the silent activeCharacter()
// fallback object), then fetched + rendered. A loading card shows immediately; the resolved fetch renders only if
// it is still current (token) and the drawer is still on diary. entry.text is rendered as-is; type / tags are
// never surfaced. A fetch failure surfaces via reportError.
function conversationDayDiaryPartner() {
  const partner = selectableCharacters.find((character) => character.character_id === activeCharacterId);
  if (!partner) {
    throw new Error(`conversation day diary requires the active partner ${JSON.stringify(activeCharacterId)} in the selectable roster`);
  }
  return partner;
}

function renderConversationDayDiaryInto(bodyEl) {
  const partner = conversationDayDiaryPartner();
  loadConversationDayDiaryEntries(bodyEl, partner).catch(reportError);
}

async function loadConversationDayDiaryEntries(bodyEl, partner) {
  const token = (diaryFetchToken += 1);
  bodyEl.replaceChildren(conversationDayDiaryLoadingCard());
  const entries = await fetchCharacterDiary(partner.character_id);
  if (token !== diaryFetchToken) return;
  const popup = document.querySelector('#conversation-day-info-popup');
  if (!popup || popup.dataset.category !== 'diary') return;
  bodyEl.replaceChildren(conversationDayDiaryHeader(partner, entries.length));
  if (entries.length === 0) {
    bodyEl.append(conversationDayInfoEmptyCard('まだ日記がありません', `${partner.display_name ?? partner.character_id}との思い出は、まだ日記に綴られていません。`));
    return;
  }
  const journal = document.createElement('div');
  journal.className = 'conversation-day-info-diary-entries';
  for (const entry of entries) {
    journal.append(conversationDayDiaryEntry(entry));
  }
  bodyEl.append(journal);
}

function conversationDayDiaryLoadingCard() {
  const card = document.createElement('div');
  card.className = 'conversation-day-info-diary-loading';
  card.append(screenWaitMark());
  return card;
}

function conversationDayDiaryHeader(partner, count) {
  const header = document.createElement('div');
  header.className = 'conversation-day-info-diary-header';
  const face = document.createElement('img');
  face.className = 'conversation-day-info-diary-face';
  face.src = conversationDayRosterFaceUrl(partner);
  face.alt = `${partner.display_name ?? partner.character_id}の顔`;
  const body = document.createElement('div');
  body.className = 'conversation-day-info-diary-head-body';
  const title = document.createElement('strong');
  title.className = 'conversation-day-info-diary-title';
  title.textContent = `${partner.display_name ?? partner.character_id}の日記`;
  const note = document.createElement('span');
  note.className = 'conversation-day-info-diary-count';
  note.textContent = count === 0 ? 'まだ記録がありません' : `${count}件の記録`;
  body.append(title, note);
  header.append(face, body);
  return header;
}

// One journal entry = the memory text as-is, in a left-ruled 手記風 block. Chronological order is preserved by
// the caller iterating entries as received (parseDiaryEntries never re-sorts).
function conversationDayDiaryEntry(entry) {
  const block = document.createElement('article');
  block.className = 'conversation-day-info-diary-entry';
  const text = document.createElement('p');
  text.className = 'conversation-day-info-diary-entry-text';
  text.textContent = entry.text;
  block.append(text);
  return block;
}

// The daytime conversation stage. Axis 1 (scope/theme): the #conversation-day-* selectors, the
// /canonical/conversation_day category icons, and the daytime light-motes ambient. Axis 2 (conversation
// type): the active roster character's persona visual (standee / speaker / face), the runtime week, and the
// five info categories + their daytime renderers. Injected deps are the shared app helpers so the module
// stays decoupled from app.js. The daytime turn execution stays in the consumer functions below — a plain
// character conversation with NO destination / dispatch / drain / week-progression seams.
const conversationDayStage = createConversationStage({
  screenSelector: '#conversation-day-screen',
  streamSelector: '#conversation-day-message-stream',
  statusSelector: '#conversation-day-status',
  controlSelectors: ['#conversation-day-send', '#conversation-day-end', '#conversation-day-input'],
  weekSelector: '#conversation-day-week',
  moonSelector: '#conversation-day-moon-phase',
  respondingClass: 'is-day-responding',
  playerSpokeClass: 'is-day-player-spoke',
  dispatchClimaxClass: 'is-day-dispatch-climax',
  playerSpokeMs: 600,
  dispatchClimaxMs: 900,
  weekTotal: CONVERSATION_DAY_TOTAL_WEEKS,
  moonPhaseCount: 8,
  weekLabel: (week, total) => `第${week}週 / ${total}`,
  moonAriaLabel: (phase, count) => `月相 ${phase + 1} / ${count}`,
  // The runtime week source (fail-fast on missing/invalid elapsed_weeks lives in the stage's
  // conversationStageWeek — week 1 fabrication / silent clamp is not introduced).
  currentWeek: () => conversationStageWeek(currentRuntimeState?.elapsed_weeks),
  // The standee frame no longer shows a persona standee: its content is the current conversation's STAGE image
  // (driven by renderConversationDayStage over currentField, click → the daytime stage-detail popup), and there
  // is no speaker caption. So the stage carries no persona visual — renderScreen's standee/speaker blocks are
  // guarded no-ops (no standeeSelector / speakerSelector). The partner's face + name still come from
  // assistantIdentity below (the chat bubbles), unchanged.
  personaVisual: () => null,
  assistantIdentity: () => ({ character_id: activeCharacterId, character_name: activeCharacter().display_name }),
  refresh: () => refresh(),
  ambient: createConversationDayAmbient({ canvasSelector: '#conversation-day-motes', moteColorRgb: '255, 236, 179', moteCount: 70 }),
  infoPopupSelector: '#conversation-day-info-popup',
  infoTitleSelector: '#conversation-day-info-popup-title',
  infoBodySelector: '#conversation-day-info-popup-body',
  infoIconSelector: '#conversation-day-info-popup-icon',
  categoryButtonSelector: '.conversation-day-category-button',
  categoryDataKey: 'dayCategory',
  categoryTitles: CONVERSATION_DAY_CATEGORY_TITLES,
  categoryIconUrl: (category) => `/canonical/conversation_day/icons/${category}.png`,
  categoryRenderers: {
    // self reuses the hub's shared parameter groups (buildParameterGroups) over a validated parameter source, with
    // the hub's ability sigils as names (the name stays in aria-label); the night-band look comes from the shared
    // .night-band CSS. A missing player_parameters is broken state — fail fast (no ?? {}).
    self: (bodyEl) => {
      const parameters = currentWorld?.player_parameters;
      if (!parameters || typeof parameters !== 'object') {
        throw new Error(`conversation day self info requires currentWorld.player_parameters, got ${JSON.stringify(parameters)}`);
      }
      // ui-prose-exception: 1791169304820-a8a0bc52
      bodyEl.append(...buildParameterGroups(parameters, abilitySigilLabel));
    },
    buddy: (bodyEl) => renderConversationDayBuddyInto(bodyEl),
    enemy: (bodyEl) => renderConversationDayEnemiesInto(bodyEl),
    inventory: (bodyEl) => renderConversationDayInventoryInto(bodyEl),
    // money's only data source is currentInventory.money (validated by the caller — no default-value
    // fallback); moneyText is the shared G formatter, applied by renderConversationDayMoneyInto.
    money: (bodyEl) => {
      if (!currentInventory || typeof currentInventory.money === 'undefined') {
        throw new Error(`conversation day money info requires currentInventory.money, got ${JSON.stringify(currentInventory?.money)}`);
      }
      renderConversationDayMoneyInto(bodyEl, currentInventory.money);
    },
    // diary shows only the current conversation partner's journal (no roster picker); a fetch failure is routed
    // to reportError by the async loader (the sync renderer only resolves the partner + kicks off the load).
    diary: (bodyEl) => renderConversationDayDiaryInto(bodyEl)
  }
}, {
  displayMessages,
  createMessageRows,
  messagesFromConversation,
  conversationPopupCooldownMs,
  sleep,
  setActorImageSource
});

// The current conversation's stage/location for the daytime screen. The stage image (the standee frame's sole
// content) and the stage-detail popup both read this live from the server-evaluated field — the single source
// of truth — with no client-side stage store: the field's current_location, else the location whose id matches
// the field's current_location_id. A missing stage is broken state surfaced by the callers' fail-fast.
function conversationDayStageLocation() {
  return currentField?.current_location
    ?? currentField?.locations?.find((item) => item.id === currentField?.state?.current_location_id)
    ?? null;
}

// Resolve AND validate the current conversation's stage for the daytime screen. Fail-fast, no placeholder:
// a missing stage, a missing 舞台名 (display_name), or missing background art is broken state, surfaced as an
// explicit error — never substituted with a generic label / id / blank (no default-value fallback). Shared by
// the frame stage image and the stage-detail popup so both surface the same broken state identically.
function conversationDayResolvedStage() {
  const location = conversationDayStageLocation();
  if (!location) {
    throw new Error('conversation day stage requires the current conversation stage/location (none resolved from currentField)');
  }
  if (typeof location.display_name !== 'string' || location.display_name.trim() === '') {
    throw new Error(`conversation day stage ${JSON.stringify(location.id ?? null)} has no display_name (stage name missing — no placeholder fallback)`);
  }
  if (!location.background_url) {
    throw new Error(`conversation day stage ${JSON.stringify(location.id ?? null)} has no background_url (stage art missing — no placeholder fallback)`);
  }
  return location;
}

// The fixed errand scene location label — mirrors the backend's server-built errand scene location_name
// (依頼の現場), which is independent of the field's current stage.
const ERRAND_SCENE_LOCATION_NAME = '依頼の現場';
// The 依頼の現場 舞台画像: the new 1:1 content stage art shown in the errand detail popup (a fixed scene image,
// independent of the field's current stage). The stage frame keeps the 依頼主 standee as the clickable face; the
// detail popup it opens shows THIS 1:1 stage image instead of the standee. It is the errand destination's art (the
// send-off curtain, the wait over it and the card room's ground: one image from hubTerrace.js).
const ERRAND_SCENE_STAGE_IMAGE_URL = destinationArt('errand');
// The 研究会 会場 舞台画像: the 1:1 content stage art shown in the study circle detail popup (the errand mirror — a
// fixed scene image, independent of the field's current stage). The stage frame keeps the 主催 standee as the
// clickable face; the detail popup it opens shows THIS 1:1 stage image instead of the standee. It is the study circle
// destination's art (the send-off curtain, the wait over it and the card room's ground: one image from hubTerrace.js).
const STUDY_CIRCLE_SCENE_STAGE_IMAGE_URL = destinationArt('study_circle');
// The 錬成室 舞台名 — mirrors the backend's injected atelier scene location_name (homunculusScene.ATELIER_LOCATION_NAME),
// the title shown in the atelier stage-detail popup.
const ATELIER_SCENE_LOCATION_NAME = '錬成室';
// The 錬成室 舞台画像: the fixed 1:1 stage art for a ホムンクルス conversation. Unlike errand / study — whose
// stage frame shows the 依頼主 / 主催 standee and whose popup shows the fixed 1:1 image — the homunculus has NO standee
// (the pool is face-sheet only), so the stage FRAME itself shows this 1:1 錬成室 image, and the detail popup shows the
// same image (the errand fixed-1:1 mechanism applied to the frame). The scene text is the server-authoritative
// injected scene (held on activeAtelierScene), never a frontend copy.
const ATELIER_SCENE_STAGE_IMAGE_URL = '/canonical/atelier/stage.jpg';

// Resolve AND validate the active errand's daytime scene (the stage frame + detail popup). The errand scene
// is independent of the field's current stage (依頼の現場 fixed): the frame shows the 依頼主 standee and the
// detail popup shows 依頼の現場 + the errand's title / situation, held from the start response's `errand` as the
// single source. Fail-fast, no placeholder / other-stage substitution: a missing held scene, a missing/empty
// title / situation / client_character_id, an unresolvable client roster character, or an unresolvable 依頼主
// standee is broken state, surfaced explicitly (no default-value fallback).
function conversationDayErrandResolvedScene() {
  if (!activeErrandScene || typeof activeErrandScene !== 'object') {
    throw new Error('conversation day errand scene is not held (no active errand scene resolved from the errand start)');
  }
  const { title, situation, client_character_id: clientId } = activeErrandScene;
  if (typeof title !== 'string' || title.trim() === '') {
    throw new Error(`conversation day errand scene has no title (errand display field missing — no placeholder fallback)`);
  }
  if (typeof situation !== 'string' || situation.trim() === '') {
    throw new Error(`conversation day errand scene has no situation (errand display field missing — no placeholder fallback)`);
  }
  if (typeof clientId !== 'string' || clientId.trim() === '') {
    throw new Error(`conversation day errand scene has no client_character_id (errand display field missing — no placeholder fallback)`);
  }
  const client = selectableCharacters.find((item) => item.character_id === clientId);
  if (!client) {
    throw new Error(`conversation day errand 依頼主 not found in character roster: ${clientId}`);
  }
  const standeeUrl = characterSceneStandeeUrl(client);
  if (!standeeUrl) {
    throw new Error(`conversation day errand 依頼主 ${clientId} has no standee (依頼主 standee unresolvable — no placeholder fallback)`);
  }
  return { title, situation, standeeUrl };
}

// Resolve AND validate the active study circle's daytime scene (the stage frame + detail popup). Like the errand
// scene it is independent of the field's current stage: the frame shows the 主催 (host) standee and the detail
// popup shows the study circle 会場 (venue) + theme name / situation, held from the start response's study_circle
// (the decorated offer) as the single source. Fail-fast, no placeholder / other-stage substitution: a missing held
// scene, a missing/empty theme name / venue / situation / host_character_id, an unresolvable host roster character,
// or an unresolvable 主催 standee is broken state, surfaced explicitly (no default-value fallback).
function conversationDayStudyCircleResolvedScene() {
  if (!activeStudyCircleScene || typeof activeStudyCircleScene !== 'object') {
    throw new Error('conversation day study circle scene is not held (no active study circle scene resolved from the study circle start)');
  }
  const { theme_name: themeName, venue, situation, host_character_id: hostId } = activeStudyCircleScene;
  if (typeof themeName !== 'string' || themeName.trim() === '') {
    throw new Error(`conversation day study circle scene has no theme_name (study circle display field missing — no placeholder fallback)`);
  }
  if (typeof venue !== 'string' || venue.trim() === '') {
    throw new Error(`conversation day study circle scene has no venue (study circle display field missing — no placeholder fallback)`);
  }
  if (typeof situation !== 'string' || situation.trim() === '') {
    throw new Error(`conversation day study circle scene has no situation (study circle display field missing — no placeholder fallback)`);
  }
  if (typeof hostId !== 'string' || hostId.trim() === '') {
    throw new Error(`conversation day study circle scene has no host_character_id (study circle display field missing — no placeholder fallback)`);
  }
  const host = selectableCharacters.find((item) => item.character_id === hostId);
  if (!host) {
    throw new Error(`conversation day study circle 主催 not found in character roster: ${hostId}`);
  }
  const standeeUrl = characterSceneStandeeUrl(host);
  if (!standeeUrl) {
    throw new Error(`conversation day study circle 主催 ${hostId} has no standee (主催 standee unresolvable — no placeholder fallback)`);
  }
  return { themeName, venue, situation, standeeUrl };
}

// Resolve AND validate the active 錬成室 (homunculus) conversation's daytime scene. Unlike errand / study there is
// NO standee (the pool is face-sheet only): the stage frame and the detail popup both show the fixed 錬成室 1:1
// stage image, and the popup title / situation are the server-authoritative injected scene (location_name /
// visible_situation) held from the conversation-start response — never a frontend-authored copy. Fail-fast: a
// missing held scene or a missing/empty location name / situation is broken state (no placeholder substitution).
function conversationDayAtelierResolvedScene() {
  if (!activeAtelierScene || typeof activeAtelierScene !== 'object') {
    throw new Error('conversation day atelier scene is not held (no active atelier scene resolved from the atelier conversation start)');
  }
  const { locationName, visibleSituation } = activeAtelierScene;
  if (typeof locationName !== 'string' || locationName.trim() === '') {
    throw new Error('conversation day atelier scene has no location_name (injected scene field missing — no placeholder fallback)');
  }
  if (typeof visibleSituation !== 'string' || visibleSituation.trim() === '') {
    throw new Error('conversation day atelier scene has no visible_situation (injected scene field missing — no placeholder fallback)');
  }
  return { locationName, visibleSituation };
}

// The daytime stage frame is a near-square standee frame, so it shows the SQUARE crop of the current stage
// background (1254×1254 art under /canonical/backgrounds/square/) instead of the wide 16:9 source that every other
// background consumer (the stage-detail popup, the academy-map dialog, ...) keeps. The square URL is derived
// mechanically from the wide background_url: keep the exact basename, swap only the directory to the square subdir.
// No per-location special map, no existence check, no wide fallback — a missing square crop surfaces as a normal
// image-load failure (the locations.json ↔ square-asset existence is pinned by conversationDaySquareStage.test.mjs).
function conversationDaySquareStageUrl(backgroundUrl) {
  return `/canonical/backgrounds/square/${backgroundUrl.slice(backgroundUrl.lastIndexOf('/') + 1)}`;
}

// Paint the standee frame with the current conversation's stage image (no text label). Called on daytime
// landing and after every turn, reading the freshly-refreshed currentField (a 舞台移動 is already painted mid-turn,
// before the new-stage opening line, by runConversationDayTurnStream). During an errand the frame instead shows
// the 依頼主 standee (the errand scene is independent of the field's current stage — 依頼の現場 fixed), never a
// field stage image. The stage / 舞台名 / background art
// fail-fast lives in conversationDayResolvedStage; the errand scene / standee fail-fast in
// conversationDayErrandResolvedScene.
function renderConversationDayStage() {
  const image = document.querySelector('#conversation-day-stage-image');
  if (!image) {
    throw new Error('conversation day stage image node #conversation-day-stage-image is missing (broken markup wiring)');
  }
  if (isActiveErrandConversation()) {
    const scene = conversationDayErrandResolvedScene();
    image.style.backgroundImage = `url('${scene.standeeUrl}')`;
    image.setAttribute('aria-label', `${ERRAND_SCENE_LOCATION_NAME}の詳細を見る`);
    return;
  }
  // During a study circle the frame instead shows the 主催 standee (the study circle scene is independent of the
  // field's current stage — the venue is fixed), never a field stage image.
  if (isActiveStudyCircleConversation()) {
    const scene = conversationDayStudyCircleResolvedScene();
    image.style.backgroundImage = `url('${scene.standeeUrl}')`;
    image.setAttribute('aria-label', `${scene.venue}の詳細を見る`);
    return;
  }
  // During a ホムンクルス conversation the frame shows the fixed 錬成室 1:1 stage image itself (the pool is
  // face-sheet only — there is NO standee to show), never a field stage image.
  if (isActiveAtelierConversation()) {
    const scene = conversationDayAtelierResolvedScene();
    image.style.backgroundImage = `url('${ATELIER_SCENE_STAGE_IMAGE_URL}')`;
    image.setAttribute('aria-label', `${scene.locationName}の詳細を見る`);
    return;
  }
  paintConversationDayStageFrame(conversationDayResolvedStage());
}

// Paint the standee frame with a field stage (the current one, or an in-turn stage move's destination).
function paintConversationDayStageFrame(location) {
  const image = document.querySelector('#conversation-day-stage-image');
  if (!image) {
    throw new Error('conversation day stage image node #conversation-day-stage-image is missing (broken markup wiring)');
  }
  image.style.backgroundImage = `url('${conversationDaySquareStageUrl(location.background_url)}')`;
  image.setAttribute('aria-label', `${location.display_name}の詳細を見る`);
}

// A field stage by id, from the field's locations — every screen:'field' stage, the same set the backend picks an
// in-turn stage move's destination from (academy-map pins, the Sanrin stages, the snowy inner garden alike).
function fieldStageLocation(id) {
  const location = currentField?.locations?.find((entry) => entry.id === id);
  if (!location) throw new Error(`field stage ${JSON.stringify(id)} is not among the field locations`);
  return location;
}

// The destination of an in-turn stage move (the stage_move SSE event, streamed before the new-stage opening line),
// with the situation the backend drew for it. The server writes the move only at the end of the turn, so the screens
// paint the destination from this before their refresh adopts it. Fail-fast, no placeholder: a destination with no
// 舞台名 or no art is broken state.
function stageMoveDestination(stageMove) {
  const location = fieldStageLocation(stageMove.to_location_id);
  if (typeof location.display_name !== 'string' || location.display_name.trim() === '') {
    throw new Error(`stage move destination ${JSON.stringify(location.id)} has no display_name`);
  }
  if (!location.background_url) throw new Error(`stage move destination ${JSON.stringify(location.id)} has no background_url`);
  return { ...location, visible_situation: stageMove.to_visible_situation };
}

// Open the daytime stage-detail popup (same information items as the legacy screen's stage detail — 舞台名 +
// 舞台画像 + visible_situation — in the daytime style). Toggled via the hidden attribute under the id-scoped
// [hidden] guard, closed by its close button + backdrop, exactly like the info drawer. Fail-fast, no
// placeholder: a missing stage / 舞台名 / background art (conversationDayResolvedStage) or a missing stage
// description (visible_situation) is broken state, surfaced explicitly.
function openConversationDayStagePopup() {
  const popup = document.querySelector('#conversation-day-stage-popup');
  const title = document.querySelector('#conversation-day-stage-popup-title');
  const image = document.querySelector('#conversation-day-stage-popup-image');
  const text = document.querySelector('#conversation-day-stage-popup-text');
  if (!popup || !title || !image || !text) {
    throw new Error('conversation day stage popup nodes are missing (broken markup wiring)');
  }
  // The scene marker scopes the errand 1:1 stage-image sizing (data-scene="errand"). Reset it on every open so a
  // prior errand popup never leaks its square sizing onto a later normal / study circle popup (the errand branch
  // re-sets it below; the other branches stay on the 16:9 base image, byte-equal).
  delete popup.dataset.scene;
  // Errand conversation: the detail popup shows 依頼の現場 (the fixed errand location, mirroring the backend
  // scene location_name) + the errand's title / situation over the 依頼の現場 1:1 stage image (errand/stage.jpg),
  // held from the errand scene as the single source. The stage frame keeps the 依頼主 standee (the clickable
  // face); this popup shows the stage image instead. Fail-fast lives in conversationDayErrandResolvedScene
  // (missing scene / display fields / standee — no placeholder).
  if (isActiveErrandConversation()) {
    const scene = conversationDayErrandResolvedScene();
    title.textContent = ERRAND_SCENE_LOCATION_NAME;
    image.style.backgroundImage = `url('${ERRAND_SCENE_STAGE_IMAGE_URL}')`;
    image.setAttribute('aria-label', `${ERRAND_SCENE_LOCATION_NAME}の画像`);
    popup.dataset.scene = 'errand';
    text.textContent = `${scene.title}\n\n${scene.situation}`;
    popup.hidden = false;
    return;
  }
  // Study circle conversation: the detail popup shows the study circle 会場 (venue, as the title) + the theme name /
  // situation over the new 1:1 study circle stage image (study_circle/stage.jpg, marked data-scene="study-circle" for
  // the square sizing — the errand branch's mirror), held from the study circle scene as the single source. The stage
  // frame keeps the 主催 standee (the clickable face); this popup shows the stage image instead. Fail-fast lives in
  // conversationDayStudyCircleResolvedScene (missing scene / display fields / standee).
  if (isActiveStudyCircleConversation()) {
    const scene = conversationDayStudyCircleResolvedScene();
    title.textContent = scene.venue;
    image.style.backgroundImage = `url('${STUDY_CIRCLE_SCENE_STAGE_IMAGE_URL}')`;
    image.setAttribute('aria-label', `${scene.venue}の画像`);
    popup.dataset.scene = 'study-circle';
    text.textContent = `${scene.themeName}\n\n${scene.situation}`;
    popup.hidden = false;
    return;
  }
  // ホムンクルス conversation: the detail popup shows 錬成室 (the injected scene location_name, matching the
  // backend scene) + the injected 情景 over the 錬成室 1:1 stage image (atelier/stage.jpg, data-scene="atelier" for the
  // square sizing — the errand branch's mirror), held from the server-authoritative injected scene as the single
  // source. Fail-fast lives in conversationDayAtelierResolvedScene (missing scene / fields — no placeholder).
  if (isActiveAtelierConversation()) {
    const scene = conversationDayAtelierResolvedScene();
    title.textContent = scene.locationName;
    image.style.backgroundImage = `url('${ATELIER_SCENE_STAGE_IMAGE_URL}')`;
    image.setAttribute('aria-label', `${scene.locationName}の画像`);
    popup.dataset.scene = 'atelier';
    text.textContent = scene.visibleSituation;
    popup.hidden = false;
    return;
  }
  const location = conversationDayResolvedStage();
  if (typeof location.visible_situation !== 'string' || location.visible_situation.trim() === '') {
    throw new Error(`conversation day stage ${JSON.stringify(location.id ?? null)} has no visible_situation (stage detail missing — no placeholder fallback)`);
  }
  title.textContent = location.display_name;
  image.style.backgroundImage = `url('${location.background_url}')`;
  image.setAttribute('aria-label', `${location.display_name}の画像`);
  text.textContent = location.visible_situation;
  popup.hidden = false;
}

// Close the stage-detail popup. Fail-fast on missing popup markup (broken wiring) rather than silently
// succeeding — the close contract is explicit, mirroring openConversationDayStagePopup's node guard.
function closeConversationDayStagePopup() {
  const popup = document.querySelector('#conversation-day-stage-popup');
  if (!popup) {
    throw new Error('conversation day stage popup node #conversation-day-stage-popup is missing (broken markup wiring)');
  }
  popup.hidden = true;
}

// The daytime speaker name (the roster conversation partner) opens a daytime-styled character popup: the
// partner's 能力値 (magic/ability meters, via the shared renderCharacterParametersInto) + 一枚絵 (standee, via the
// shared characterSceneStandeeUrl). The partner is drawn from the selectable roster by the active character id —
// the daytime screen is a single-partner conversation, so every 相手 bubble is that character, exactly the id the
// bubble face/name already render. A miss is a real roster desync — fail fast, matching openDungeonCompanionDetail
// (not a silent no-op). Every selectable character carries parameters (the catalog fails fast at load otherwise),
// so the ability section is always populated. Same [hidden]-toggle modal流儀 / node guards as the stage popup.
function openConversationDayCharacterPopup() {
  const character = selectableCharacters.find((item) => item.character_id === activeCharacterId);
  if (!character) {
    throw new Error(`conversation day partner not found in character roster: ${activeCharacterId}`);
  }
  // display_name is authoritative roster data (the catalog requires a non-empty display_name for every
  // selectable character); a missing one is broken data — fail fast before showing the popup rather than
  // silently substituting the internal character_id (no ad-hoc default fallback). Validate before mutating the
  // DOM so a throw never leaves a half-rendered popup.
  if (typeof character.display_name !== 'string' || character.display_name.trim() === '') {
    throw new Error(`conversation day partner ${character.character_id} has no display_name (broken roster data — no id fallback)`);
  }
  const popup = document.querySelector('#conversation-day-character-popup');
  const title = document.querySelector('#conversation-day-character-popup-title');
  const standee = document.querySelector('#conversation-day-character-popup-standee');
  const parameters = document.querySelector('#conversation-day-character-popup-parameters');
  if (!popup || !title || !standee || !parameters) {
    throw new Error('conversation day character popup nodes are missing (broken markup wiring)');
  }
  title.textContent = character.display_name;
  standee.alt = `${character.display_name}の一枚絵`;
  setActorImageSource(standee, characterSceneStandeeUrl(character));
  // The ability names are the hub's sigils (the name stays in aria-label), the same headed groups as the hero's band.
  // ui-prose-exception: 1791197094306-76b91e84
  parameters.replaceChildren(...buildParameterGroups(character.parameters, abilitySigilLabel));
  popup.hidden = false;
}

// Close the daytime character popup. Fail-fast on missing popup markup (broken wiring), mirroring the stage
// popup close contract rather than silently succeeding.
function closeConversationDayCharacterPopup() {
  const popup = document.querySelector('#conversation-day-character-popup');
  if (!popup) {
    throw new Error('conversation day character popup node #conversation-day-character-popup is missing (broken markup wiring)');
  }
  popup.hidden = true;
}

// The daytime ホムンクルス popup: opened from the 相手 speaker name while a 錬成室 conversation is active.
// The homunculus is a per-slot non-selectable actor absent from the roster, so its parameters come from the 錬成室
// arrival active entry (atelierArrivalView, held from GET /api/atelier) matched by the live homunculus id, and its
// face from the registered atelier actor visual (activeAtelierActor.face_url), drawn with its ground taken out (the
// conversation layer's mattedFace) so the face stands on the band's night instead of a disc of its pale ground; the
// band opens at once and the face fills in when the matte is ready. Its 11 parameters (魔法6＋基礎能力5)
// reuse the atelier rows in the 相手 window's two headed groups (renderAtelierParameterGroups) with the same ability
// sigils as the 相手 window (the name stays in aria-label), laid out on the shared night band (.night-band) like the
// hero's meters. READ-ONLY: it only reads held view state and toggles the popup's hidden attr —
// it never touches the conversation turn/end/record state. Fail-fast on a missing actor / arrival view / entry
// (broken 錬成室 state) before mutating the DOM, so a broken response never opens a blank popup.
async function openConversationDayHomunculusPopup() {
  if (!activeAtelierActor) {
    throw new Error('conversation day homunculus popup opened with no active atelier actor (broken 錬成室 conversation state)');
  }
  const homunculusId = activeAtelierActor.character_id;
  const entry = atelierArrivalView?.active?.find((item) => item.homunculus_id === homunculusId);
  if (!entry) {
    throw new Error(`conversation day homunculus not found in atelier arrival view: ${homunculusId} (broken 錬成室 arrival state — no blank popup)`);
  }
  const popup = document.querySelector('#conversation-day-homunculus-popup');
  const title = document.querySelector('#conversation-day-homunculus-popup-title');
  const face = document.querySelector('#conversation-day-homunculus-popup-face');
  const parameters = document.querySelector('#conversation-day-homunculus-popup-parameters');
  if (!popup || !title || !face || !parameters) {
    throw new Error('conversation day homunculus popup nodes are missing (broken markup wiring)');
  }
  title.textContent = entry.display_name;
  face.alt = `${entry.display_name}の顔`;
  setActorImageSource(face, '');
  // ui-prose-exception: 1791197094306-76b91e84
  parameters.replaceChildren(...renderAtelierParameterGroups(entry.parameters, abilitySigilLabel));
  popup.hidden = false;
  setActorImageSource(face, await mattedFace(activeAtelierActor.face_url));
}

// Close the daytime homunculus popup. Fail-fast on missing popup markup (broken wiring), mirroring the character /
// stage popup close contract rather than silently succeeding.
function closeConversationDayHomunculusPopup() {
  const popup = document.querySelector('#conversation-day-homunculus-popup');
  if (!popup) {
    throw new Error('conversation day homunculus popup node #conversation-day-homunculus-popup is missing (broken markup wiring)');
  }
  popup.hidden = true;
}

// The drain-on-exit wait of an achievement auto-end: raised by the achievement_draining reading pause (after the
// wrap-up streamed, before the completion result arrives) ONLY if the backend completion drain outlasts the ~5s read —
// so the post-processing drain runs over the errand / study circle stage's art (the conversation's own ground) and the
// hub return (completeErrand/StudyCircleFromTurnResult → returnToRoutingHubFromPlace) continues under it with no break.
function raiseAchievementDrainPlaceVeil() {
  raisePlaceVeil({ art: academyFieldReading.conversationStage().backgroundUrl, dim: true, until: 'routing-hub', ending: 'fade' });
}

// Clean daytime turn stream. Mirrors the routing hub's 統一出現規律 — every 吹き出し種別 (主人公の発話/地の文・
// 相手の発話/地の文) is revealed through the stage's single cooldown-paced queue as 完成した吹き出し単位, never
// partial characters — and, like the hub send-off, an ACHIEVEMENT auto-end (errand / study_circle) starts a
// reading pause the moment achievement_draining reveals the wrap-up mid-stream, running it CONCURRENTLY with the
// backend completion drain (it raises the drain loading screen itself only if the drain outlasts the pause). A
// daytime turn still carries no routing destination / in-turn dispatch / week progression — the ③ climax and the
// destination dispatch of the hub are absent by design.
async function runConversationDayTurnStream({ playerInput, provider, onStageMove }) {
  const endpoint = '/api/conversation/stream';
  // The daytime turn body, built through routingTurnRequestBody so its hub/errand mutual-exclusion contract
  // reaches the daytime turn: an ACTIVE ERRAND carries the errand conversation id in body.id (the backend
  // routes an active-errand turn by it — a missing id 409s ROUTING_ERRAND_CONTEXT_MISMATCH). The daytime screen
  // never runs a routing hub, so the hub id is never set here; a non-errand daytime turn stays the ordinary
  // { character_id, player_input, provider } body byte-for-byte, so loop / normal daytime conversations are
  // unchanged. NO destination / dispatch / drain / week-progression seams (a daytime turn never dispatches).
  const body = routingTurnRequestBody({ player_input: playerInput, provider });
  const baseMessages = [...conversationDayStage.surface.getHistory()];
  const reveal = conversationDayStage.createTurnReveal(baseMessages);
  // 主人公の発話・地の文 も同じ規律に乗せる: enqueue the player's utterance as the first 吹き出し単位.
  reveal.enqueue(displayMessages([{ role: 'user', content: playerInput }]));
  let expression = 'neutral';
  let assistantText = '';
  let assistantSegmentCount = 0;
  let finalResult = null;
  // 達成読みポーズ (達成自動終了ターン) の並行制御。hub の 見送り読みポーズ と同型: achievementReadingPause は
  // achievement_draining で1回だけ起動する読みポーズの promise、achievementLoadingShown はそのポーズが drain の待ち
  // (場所の絵の上) を先に出したか (result より先にポーズが満了したか) の記録、streamFailed は error 後にその表示を抑止するフラグ。
  let achievementReadingPause = null;
  let achievementLoadingShown = false;
  let streamFailed = false;
  // 舞台移動: the stage_move event arrives between the cutoff (the last line at the old stage) and the new-stage
  // opening. From then on every 吹き出し waits behind the move — the cutoff finishes revealing, the frame and the
  // conversation layer move to the destination (the layer: the person dissolves, the ground and the 舞台名 move, the
  // person emerges again), and only then does the opening reveal. afterStageMove chains those enqueues in order.
  // onStageMove receives the move's own promise, so a failed turn can wait for the move and put the stage back where
  // the player is (runConversationDayConversation).
  let stageMoveId = null;
  let afterStageMove = null;
  const noteLoadingDelta = createLoadingProgressDeltaThrottle();

  function enqueueReveal(segments) {
    if (afterStageMove) afterStageMove = afterStageMove.then(() => reveal.enqueue(segments));
    else reveal.enqueue(segments);
  }

  function beginStageMove(stageMove) {
    if (afterStageMove) throw new Error('conversation day stream: a second stage_move in one turn');
    const destination = stageMoveDestination(stageMove);
    stageMoveId = destination.id;
    afterStageMove = (async () => {
      await reveal.drain();
      // A turn that failed before the move began showing never shows it.
      if (streamFailed) return;
      paintConversationDayStageFrame(destination);
      await stageMoves(destination.id);
    })();
    onStageMove(afterStageMove);
  }

  const assistantMessage = (content) => ({
    role: 'assistant',
    ...conversationDayStage.surface.assistantIdentity(),
    content,
    face_emotion_variant_id: `face_${expression}`,
    expression
  });

  function enqueueAssistantSegments(source) {
    if (!source.trim()) return;
    const segments = displayMessages([assistantMessage(source)]).filter((segment) => (segment.content ?? '').trim());
    const fresh = segments.slice(assistantSegmentCount);
    assistantSegmentCount += fresh.length;
    enqueueReveal(fresh);
  }

  // 達成読みポーズ pipeline. achievement_draining が「達成自動終了ターンで、切上げ発言の吹き出しは全て enqueue 済み、
  // これから backend の completion drain が走る」ことを告げた瞬間に起動する: 切上げ発言が出揃ったら (reveal.drain)
  // ~5秒の読みポーズを取るが、それを backend drain と並行して走らせる (drain の後に直列で走らせない)。ポーズが drain
  // 完了 (result 到着) より先に満了したら drain の待ち (場所の絵の上) をここで出し、まだ開いている stream が result
  // をその下で受け取る。result が先に着けば会話画面表示のまま満了を待ち、呼び出し側の完了ヘルパーがハブ帰還の待ちへ
  // 進む。error で終わった stream は自分で会話画面を復元するので、その後に待ちを出さない。ターンにつき1回だけ。
  function beginAchievementReadingPause() {
    if (achievementReadingPause) return;
    achievementReadingPause = (async () => {
      await reveal.drain();
      conversationDayStage.setResponding(false);
      await sleep(DRAIN_READING_PAUSE_MS);
      if (!finalResult && !streamFailed) {
        raiseAchievementDrainPlaceVeil();
        achievementLoadingShown = true;
      }
    })();
  }

  function handleBlock(block) {
    const event = block.split('\n').find((line) => line.startsWith('event: '))?.slice(7);
    const dataText = block.split('\n').find((line) => line.startsWith('data: '))?.slice(6);
    const data = dataText ? JSON.parse(dataText) : null;
    if (event === 'assistant_emotion') expression = data.expression ?? 'neutral';
    if (event === 'assistant_delta') {
      conversationDayStage.setResponding(true);
      noteLoadingDelta();
      assistantText += data.delta;
      enqueueAssistantSegments(completedAssistantPrefix(assistantText));
    }
    if (event === 'assistant_complete') {
      notifyAcademyLoadingProgress();
      expression = data.expression ?? expression;
      assistantText = data.content ?? assistantText;
      enqueueAssistantSegments(assistantText);
      assistantText = '';
      assistantSegmentCount = 0;
    }
    // achievement_draining marks mid-stream that this is a 達成自動終了 (errand / study_circle) turn: the wrap-up
    // 吹き出し are all enqueued and the backend now runs its completion drain before the result. Start the 達成読み
    // ポーズ NOW so the ~5s read runs concurrently with that drain instead of serially after the result; the pause
    // raises the drain loading screen itself only if the drain outlasts it (backend 契約・SSE イベント順序は不変).
    if (event === 'achievement_draining') {
      beginAchievementReadingPause();
      notifyAcademyLoadingProgress();
    }
    // finalization_progress: a block boundary of the post-turn completion drain running concurrently with the
    // 達成読みポーズ. Once the drain outlasts the pause and the loading screen is raised, each boundary advances
    // the constellation one edge (no-op while the loader is not yet shown — same guard as every other notify).
    if (event === 'finalization_progress') notifyAcademyLoadingProgress();
    if (event === 'stage_move') beginStageMove(data);
    if (event === 'result') {
      finalResult = data;
      notifyAcademyLoadingProgress();
    }
    // PROMPT_PREWARM_FAILED arrives after the turn was written: adopt the written turn like a result (the failure
    // rides on it for the screen's banner). Every other error fails the turn.
    if (event === 'error') {
      if (data?.error_code !== PROMPT_PREWARM_FAILED_ERROR_CODE) throw createApiError({ url: endpoint, status: 503, payload: data, fallbackText: data?.error ?? '' });
      finalResult = promptPrewarmFailedTurnResult({ url: endpoint, data });
    }
  }

  try {
    const response = await fetch(endpoint, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(body)
    });
    if (!response.ok) {
      const text = await response.text();
      throw createApiError({ url: endpoint, status: response.status, payload: parseJsonText(text), fallbackText: text });
    }
    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffer = '';
    while (true) {
      const { value, done } = await reader.read();
      buffer += decoder.decode(value ?? new Uint8Array(), { stream: !done });
      const blocks = buffer.split('\n\n');
      buffer = blocks.pop() ?? '';
      for (const block of blocks) {
        if (block.trim()) handleBlock(block);
      }
      if (done) break;
    }
    if (buffer.trim()) handleBlock(buffer);
    if (!finalResult) throw new Error('conversation day stream ended without a final result');
    // The streamed move and the written move are one move: a result carrying a stage_move the stream never announced
    // (or announcing another destination) is a broken backend contract.
    if ((finalResult.stage_move?.to_location_id ?? null) !== stageMoveId) {
      throw new Error(`conversation day stream: stage_move event / result mismatch (event=${stageMoveId}, result=${finalResult.stage_move?.to_location_id ?? null})`);
    }
    await afterStageMove;
  } catch (error) {
    // Stop the reveal queue so a failed send's restore is not overwritten by a late paced render, and mark the
    // stream failed so a concurrent 達成読みポーズ (started if achievement_draining had already fired) does not raise
    // the drain loading screen after the daytime screen has been restored, and a stage move that has not begun
    // showing does not show.
    streamFailed = true;
    reveal.cancel();
    throw error;
  }

  // Backend contract pairing: achievement_draining (which starts the 達成読みポーズ) is emitted iff this turn achieved,
  // i.e. iff the result carries a completion (errand_result / study_circle_result). Enforce the pairing in BOTH
  // directions rather than tolerating a half-signalled stream (a completion with no preceding drain signal, or a
  // drain signal with no completion). The per-kind achievement/completion pairing is re-checked in the completion
  // helpers; this guards the signal itself.
  const achieved = Boolean(finalResult.errand_result || finalResult.study_circle_result);
  if (achieved !== Boolean(achievementReadingPause)) {
    throw new Error(`conversation day stream: achievement_draining / achievement completion mismatch (draining=${Boolean(achievementReadingPause)}, achieved=${achieved})`);
  }

  if (achievementReadingPause) {
    // 達成自動終了ターン。達成読みポーズ has run concurrently with the backend completion drain since achievement_draining.
    // Await it: either the result arrived first and the daytime screen stayed visible for the whole ~5s read (the
    // completion helper then goes straight to the hub-return wait — 会話画面へ戻る瞬間なし), or the pause elapsed
    // first and already raised the drain wait over the stage's art (achievementLoadingShown) and we are here now that the
    // drain delivered the result (the hub-return wait continues under it — 待ちが連続). Adopt the authoritative
    // conversation, then let the caller's completion helper take the hub-return transition.
    await achievementReadingPause;
    conversationDayStage.surface.commitState(finalResult);
    conversationDayStage.renderStream(conversationDayStage.surface.getHistory());
    return finalResult;
  }
  // Let every queued 吹き出し finish revealing on the shared cadence before adopting the authoritative state.
  await reveal.drain();
  conversationDayStage.surface.commitState(finalResult);
  conversationDayStage.renderStream(conversationDayStage.surface.getHistory());
  conversationDayStage.setResponding(false);
  conversationDayStage.setStatus('');
  return finalResult;
}

// The daytime end path, shared by the end button and the character-decided cutoff auto-end so both take the
// identical branch (the branch lives here once, not duplicated in the click handler). An ACTIVE ERRAND ends
// through the routing drain-on-exit (endRoutingConversation → /api/conversation/end drain →
// navigateToPostContentScreen('interaction') = hub return); a non-errand daytime conversation (a loop-mode
// academy-map character conversation) ends through endConversation (loop finalization + 復帰先: 自室, or the
// graduation title route). options flow to endConversation so the auto-end can end during its own still-in-flight
// turn (allowDuringInFlight); the errand drain path has no in-flight guard, matching the button's existing errand
// end.
function endConversationDay(options = {}) {
  if (isActiveErrandConversation()) {
    return endRoutingConversation();
  }
  return endConversation(options);
}

// Consume a character-decided cutoff (conversation_continuation.continue_conversation === false) with the same
// contract as the shared conversation screen's autoEndConversationAfterFinalReply: detect the false continuation,
// hold FINAL_REPLY_AUTO_END_DELAY_MS so the final reply stays readable, then end. It differs only by routing the
// end through the SHARED daytime end path (endConversationDay) so the end button and the auto-end behave
// identically. The end runs inside its own still-in-flight turn, so it opts into allowDuringInFlight exactly as
// the shared screen's helper does.
async function autoEndConversationDayAfterFinalReply(result) {
  if (!conversationShouldAutoEnd(result)) return false;
  setStreamStatus('reflection: auto-ending after final reply');
  await sleep(FINAL_REPLY_AUTO_END_DELAY_MS);
  // 学院マップから入った会話では、会話の層の人が光へ溶けて消えてから終える（終えるの釦と同じ動き。それ以外の会話ではすぐ返る）。
  await partnerLeaves();
  await endConversationDay({ allowDuringInFlight: true });
  return true;
}

// The in-turn errand auto-end: an errand turn that met its achievement condition finalized server-side
// within the turn (drain-on-exit), so its response already carries the completion (errand_result — reward
// paid, active errand cleared, post_content_screen resolved). The wrap-up 発話 has already revealed on the
// shared cadence AND been held readable by the turn's 達成読みポーズ (runConversationDayTurnStream, started on
// achievement_draining and run concurrently with the backend drain — it also raised the drain loading screen
// if the completion drain outlasted the read), so this helper adds NO second serial wait: it takes the SAME
// content-return transition the content exits take (returnToRoutingHubFromPlace), minus the
// /api/conversation/end round-trip the server already ran. Returns true when it consumed an errand completion
// so the caller skips the normal refresh/repaint of a conversation that is closing. The achievement signal and
// the completion result are paired: a turn that carries one but not the other is a broken backend contract and
// fails fast rather than transitioning on a half-signalled response. A non-errand turn, or an errand turn that
// did not achieve, carries neither and returns false, keeping the daytime turn byte-equivalent.
async function completeErrandFromTurnResult(result) {
  const hasAchievement = Boolean(result?.errand_achievement);
  const hasCompletion = Boolean(result?.errand_result);
  if (hasAchievement !== hasCompletion) {
    throw new Error(`errand turn: achievement / completion mismatch (achievement=${hasAchievement}, completion=${hasCompletion})`);
  }
  if (!hasCompletion) return false;
  assertDrainedRoutingFinalization(result.finalization_status);
  // The drained completion is authoritative: it finalized the errand server-side, so its post-finalization
  // state must be present. Fail fast rather than falling back to the pre-turn state, which would silently
  // adopt stale runtime state on a finalized-but-stateless response (same discipline as the dispatch path).
  if (!result.state || typeof result.state !== 'object') {
    throw new Error(`errand completion is missing post-finalization state (got ${JSON.stringify(result.state)})`);
  }
  currentRuntimeState = result.state;
  clearVisibleConversation();
  // An errand is routing-only, so its completion always returns to the hub ('interaction'); fail fast on any
  // other post_content_screen rather than mis-routing (same contract as returnToRoutingHubFromContent).
  if (result.post_content_screen !== 'interaction') {
    throw new Error(`errand completion: unexpected post_content_screen ${JSON.stringify(result.post_content_screen)}`);
  }
  // Cover the non-streaming hub-start wait with the errand stage's art (the same returnToRoutingHubFromPlace 流儀 as
  // the content exits; it continues the drain wait when the reading pause already raised it) instead of a bare
  // enterRoutingHub under the still-visible daytime screen, which reads as a freeze. This consumption runs inside the daytime turn's still-in-flight window
  // (runConversationDayConversation set conversationRequestInFlight and its finally has not cleared it yet), so the
  // hub re-open opts in explicitly — the same allowDuringInFlight 流儀 as the cutoff auto-end's endConversationDay —
  // threaded through to enterRoutingHub's re-entry gate. The shared helper keeps the wait from ever being terminal
  // (a failed hub start lands on the hub without a conversation).
  await returnToRoutingHubFromPlace({ allowDuringInFlight: true });
  return true;
}

// The in-turn study circle auto-end: the exact mirror of completeErrandFromTurnResult. A study circle turn
// that met its achievement condition finalized server-side within the turn (drain-on-exit), so its response
// already carries the completion (study_circle_result — parameter deltas applied, active study circle cleared,
// post_content_screen resolved). The host's wrap-up 発話 has already revealed on the shared cadence AND been held
// readable by the turn's 達成読みポーズ (started on achievement_draining kind 'study_circle', run concurrently with
// the backend drain), so this helper adds NO second serial wait: it takes the SAME content-return transition the
// content exits take (returnToRoutingHubFromPlace), minus the /api/conversation/end round-trip the
// server already ran. Returns true when it consumed a study circle completion so the caller skips the normal
// refresh/repaint. The achievement signal and the completion result are paired: a turn that carries one but not
// the other is a broken backend contract and fails fast. A non-study-circle turn, or a study circle turn that
// did not achieve, carries neither and returns false, keeping the daytime turn byte-equivalent.
async function completeStudyCircleFromTurnResult(result) {
  const hasAchievement = Boolean(result?.study_circle_achievement);
  const hasCompletion = Boolean(result?.study_circle_result);
  if (hasAchievement !== hasCompletion) {
    throw new Error(`study circle turn: achievement / completion mismatch (achievement=${hasAchievement}, completion=${hasCompletion})`);
  }
  if (!hasCompletion) return false;
  assertDrainedRoutingFinalization(result.finalization_status);
  // The drained completion is authoritative: it finalized the study circle server-side, so its
  // post-finalization state must be present. Fail fast rather than falling back to the pre-turn state.
  if (!result.state || typeof result.state !== 'object') {
    throw new Error(`study circle completion is missing post-finalization state (got ${JSON.stringify(result.state)})`);
  }
  currentRuntimeState = result.state;
  clearVisibleConversation();
  // A study circle is routing-only, so its completion always returns to the hub ('interaction'); fail fast on
  // any other post_content_screen rather than mis-routing (same contract as the errand completion).
  if (result.post_content_screen !== 'interaction') {
    throw new Error(`study circle completion: unexpected post_content_screen ${JSON.stringify(result.post_content_screen)}`);
  }
  await returnToRoutingHubFromPlace({ allowDuringInFlight: true });
  return true;
}

// The daytime screen's modal overlays: the info drawer, the stage-detail popup, and the two partner popups
// (roster character / ホムンクルス). While any is open the player is reading it, so the turn-completion refocus
// must not pull focus behind it. (The gift confirmation is a blocking window.confirm, so it can never be open
// while the refocus runs.)
const CONVERSATION_DAY_OVERLAY_SELECTORS = Object.freeze([
  '#conversation-day-info-popup',
  '#conversation-day-stage-popup',
  '#conversation-day-character-popup',
  '#conversation-day-homunculus-popup'
]);

function isConversationDayOverlayOpen() {
  return CONVERSATION_DAY_OVERLAY_SELECTORS.some((selector) => {
    const overlay = document.querySelector(selector);
    if (!overlay) throw new Error(`conversation day overlay ${selector} is missing (broken markup wiring)`);
    return !overlay.hidden;
  });
}

// Restore keyboard focus to `#conversation-day-input` whenever the partner has finished speaking and the player is
// expected to type the next utterance: after a daytime turn (the reply has revealed to its last 吹き出し), after the
// opening (each daytime start's finally, once the first reply has revealed), and after a gift's reaction has
// revealed (handleConversationDayGift, success only). The same gate as the routing hub's
// focusRoutingHubInputIfContinuing, all required, no silent fallback: the daytime screen is active, a conversation
// is live (the runtime state carries the interaction partner), the input is present and not disabled — plus no
// daytime overlay is open. Every terminal exit (auto-end, errand / study circle completion,
// settings redirect) leaves the daytime screen, so this is a no-op there and never steals focus from the
// destination screen. preventScroll keeps a scrolled-up read position in place.
function focusConversationDayInputIfContinuing() {
  if (!screens['conversation-day'].classList.contains('active')) return;
  const partnerId = currentRuntimeState?.current_interaction_character_id;
  if (typeof partnerId !== 'string' || partnerId === '') return;
  if (isConversationDayOverlayOpen()) return;
  const input = document.querySelector('#conversation-day-input');
  if (!input || input.disabled) return;
  input.focus({ preventScroll: true });
}

// A daytime turn that announced a stage move (the stage_move event) and then failed can leave the frame and the
// conversation layer at the destination while the player is still at the old stage (the server writes the move at
// the end of the turn), or at the old stage while the turn was written (the stream was cut before the move showed).
// Where the player is comes from the server, never from the screen: adopt the server's field (strict — a failed
// /api/field throws instead of keeping the stale field), repaint the frame from it, and move the layer there (the
// same choreography as an in-turn move; nothing moves if the layer already shows that stage).
async function returnConversationDayStageToCurrentLocation() {
  renderField(await getJson('/api/field'));
  renderConversationDayStage();
  await stageReturns(conversationDayResolvedStage().id);
}

// Send a daytime turn. Snapshots history + input before the turn so a transport / API / stream failure
// restores both instead of stranding an unsent utterance with a cleared input. A failed turn that announced a stage
// move also puts the stage back where the player is (returnConversationDayStageToCurrentLocation). The player's
// utterance is not rendered optimistically — the reveal queue reveals it as the first 吹き出し単位, the same 統一出現規律
// as the partner's reply.
async function runConversationDayConversation() {
  if (conversationRequestInFlight) {
    showProcessingToast();
    return;
  }
  const input = document.querySelector('#conversation-day-input');
  const playerInput = (input?.value ?? '').trim();
  if (!playerInput) return;
  const historySnapshot = [...conversationDayStage.surface.getHistory()];
  const inputSnapshot = input ? input.value : '';
  conversationRequestInFlight = true;
  conversationDayStage.setControlsDisabled(true);
  const provider = conversationProvider();
  let stageMoveShown = null;
  try {
    if (input) input.value = '';
    // ② the player spoke — flare the composer. ① the partner is now responding (glow from turn start, the
    // only in-progress cue; the daytime chat shows no in-progress status text, error banner only).
    conversationDayStage.flashPlayerSpoke();
    conversationDayStage.setResponding(true);
    const result = await runConversationDayTurnStream({ playerInput, provider, onStageMove: (shown) => { stageMoveShown = shown; } });
    // An achieved errand / study circle turn auto-ended server-side within the turn: consume the completion
    // contract and take the post-content transition before any refresh/repaint touches the closing stage.
    // Errand and study circle are mutually exclusive, so at most one consumes the turn.
    if (await completeErrandFromTurnResult(result)) return;
    if (await completeStudyCircleFromTurnResult(result)) return;
    // A character-decided cutoff (continue_conversation === false) auto-ends after the final reply has revealed,
    // through the SAME shared daytime end path as the end button (errand → drain-on-exit, loop → finalization);
    // return before the normal refresh/repaint that would otherwise touch the stage this turn is closing.
    if (await autoEndConversationDayAfterFinalReply(result)) return;
    await refresh();
    // Reflect a 舞台移動 (or any stage change) that this turn produced: re-paint the stage image from the
    // freshly-refreshed field so the shown stage always matches the current conversation stage.
    renderConversationDayStage();
    if (result.prompt_prewarm_error) conversationDayStage.setStatus(errorDisplayMessage(result.prompt_prewarm_error), { tone: 'error' });
  } catch (error) {
    // The achievement auto-end's wait over the stage's art was already up: it sinks into the night before the daytime
    // screen comes back under it (a settings redirect takes it down on the way to the settings screen instead).
    if (placeVeilWaiting() && settingsRedirectErrorMessage(error) == null) await stopPlaceVeil();
    // A turn that announced a stage move: let the move finish showing before the history comes back, so a person
    // still dissolving does not race the restored stream (the move's own failure surfaces on its own path).
    if (stageMoveShown) await Promise.allSettled([stageMoveShown]);
    conversationDayStage.surface.setHistory(historySnapshot);
    conversationDayStage.renderStream(historySnapshot);
    if (input) input.value = inputSnapshot;
    conversationDayStage.setStatus('');
    let stageReturnFailure = null;
    if (stageMoveShown) await returnConversationDayStageToCurrentLocation().catch((failure) => { stageReturnFailure = failure; });
    if (!handleRuntimeApiError(error, { allowSettingsRedirect: true })) reportConversationError(error);
    if (stageReturnFailure) throw stageReturnFailure;
  } finally {
    conversationRequestInFlight = false;
    conversationDayStage.setControlsDisabled(false);
    conversationDayStage.setResponding(false);
    focusConversationDayInputIfContinuing();
  }
}

// The daytime opening streams through the shared SSE reveal helper bound to the stage's own surface — the same
// path the academy-map session opening uses (runOpeningConversationStream) — so the loading screen can hold
// until the opening's first assistant event and release into the daytime screen at stream start.
async function runConversationDayOpeningStream({ characterId = activeCharacterId, provider, onAssistantStreamStart = null, revealAfter = null }) {
  return runAssistantSseStream({
    surface: conversationDayStage.surface,
    endpoint: '/api/conversation/opening/stream',
    body: { character_id: characterId, provider },
    statusPrefix: 'opening',
    finalAssistantMode: 'first',
    refreshAfter: false,
    onAssistantStreamStart,
    revealAfter
  });
}

// The daytime opening for the current partner. onAssistantStreamStart fires on the first streamed token so the
// loading screen releases at stream start; a non-streaming provider has no first token, so it signals stream
// start immediately and falls back to the ordinary (/api/conversation/opening) cooldown-paced reveal on the
// stage surface (byte-equivalent to the prior non-streamed opening for that provider).
// revealAfter (the passage entries' landing — startConversationDay / openEventConversationDay settle it right after the
// switch to the daytime screen) holds the first popup of either branch
// until the daytime screen is shown, so the opening reveals one per cooldown on the visible screen instead of being
// spent on the hidden screen while the passage arrives. Reception, readiness and the passage are not held.
async function ensureConversationDayOpening({ onAssistantStreamStart = null, revealAfter = null } = {}) {
  if (conversationDayStage.surface.getHistory().length > 0) return;
  const provider = conversationProvider();
  if (provider === 'lmstudio') {
    await runConversationDayOpeningStream({ provider, onAssistantStreamStart, revealAfter });
  } else {
    onAssistantStreamStart?.();
    const result = await postJson('/api/conversation/opening', { character_id: activeCharacterId, provider });
    await revealAfter;
    await revealResultSequentially(conversationDayStage.surface, result);
  }
}

// 昼の会話の種別の印。#conversation-day-screen の data-conversation-kind に、入口ごとの種類を立てる: 学院マップから相手を選んで
// 入る会話（学院の人・山林の生き物＝startConversationDay）は field、依頼は errand、研究会は study-circle、ホムンクルスは atelier、
// 出来事は event（学院の人との routing の卒業も出来事として event）。loop の卒業の会話では下ろす。会話の見せ方の層（conversationLayer.*）は印の立った会話の見せ方を一つの形で受け持ち、
// 種類ごとに違うのは地にする場所の絵と場所の名だけ（academyFieldReading.conversationStage）。印の無い会話は製品の見た目と振る舞いのまま。
const CONVERSATION_DAY_KINDS = new Set(['field', 'errand', 'study-circle', 'atelier', 'event']);

function markConversationDayKind(kind) {
  if (kind === null) {
    delete screens['conversation-day'].dataset.conversationKind;
    return;
  }
  if (!CONVERSATION_DAY_KINDS.has(kind)) throw new Error(`conversation day kind ${JSON.stringify(kind)} is not one of ${[...CONVERSATION_DAY_KINDS].join(', ')}`);
  screens['conversation-day'].dataset.conversationKind = kind;
}

// Start a daytime conversation with a selectable roster character over the ordinary character conversation API
// (POST /api/interaction/start → opening). Like the academy-map session start, it never flips straight to the
// conversation screen: it holds the academy-loading interstitial while the interaction starts and the opening
// begins, then releases into the daytime screen at the opening's first stream event (racing the full opening so
// an opening failure surfaces through the loading error path instead of hanging the loading screen — no infinite
// load). A start that fails on the loader returns to the hub like a failed event start under the academy-map arrival
// (the failure notice names the academy map; the cause stays on the console). This is the daytime landing for an academy-map character/creature conversation when the persisted
// preference is 'day' (the default), and is also the dev entry's start (?initialScreen=conversation-day).
async function startConversationDay(characterId) {
  if (conversationRequestInFlight) {
    showProcessingToast();
    return;
  }
  conversationRequestInFlight = true;
  conversationDayStage.setControlsDisabled(true);
  markConversationDayKind('field');
  let openingStreamStartedResolve = null;
  let openingStreamStartedResolved = false;
  const openingStreamStarted = new Promise((resolve) => {
    openingStreamStartedResolve = resolve;
  });
  const markOpeningStreamStarted = () => {
    if (openingStreamStartedResolved) return;
    openingStreamStartedResolved = true;
    openingStreamStartedResolve?.();
  };
  // The opening reveals from the landing on the daytime screen, not from the stream start the passage still arrives
  // over. A start that fails releases it in finally, so a pending opening is never left waiting.
  let landedOnConversationDay = null;
  const conversationDayLanded = new Promise((resolve) => {
    landedOnConversationDay = resolve;
  });
  let openingPromise = Promise.resolve();
  const readiness = (async () => {
    activeCharacterId = characterId;
    await postJson('/api/interaction/start', { character_id: characterId, source_type: 'field' });
    notifyAcademyLoadingProgress();
    conversationDayStage.surface.setHistory([]);
    await refresh();
    notifyAcademyLoadingProgress();
    // Progress the opening behind the loading screen and release the screen at stream start (or on an opening
    // failure), not after the full first reply.
    openingPromise = ensureConversationDayOpening({ onAssistantStreamStart: markOpeningStreamStarted, revealAfter: conversationDayLanded });
    await Promise.race([openingStreamStarted, openingPromise]);
  })();
  try {
    await showAcademyLoadingScreenUntilReady({
      readiness,
      nextScreen: 'conversation-day',
      refreshBeforeNextScreen: false,
      passage: { stage: conversationPassageStage('field') }
    });
    // The stage frame shows the current conversation's stage image (renderScreen no longer sets a persona
    // standee): paint it from the freshly-refreshed field on landing, before the opening reveal continues.
    renderConversationDayStage();
    landedOnConversationDay();
    await openingPromise;
  } catch (error) {
    // Loading-residual defense: a failed daytime conversation start must not strand the player on the loading
    // screen, nor land on a conversation screen with no partner. A non-settings failure still on the loader returns
    // to the hub — opened anew under the stopped passage, because the academy-map visit already ended the hub
    // conversation — then re-raises so the caller's .catch(reportError) logs it once.
    if (isAcademyLoadingScreenActive() && settingsRedirectErrorMessage(error) == null) {
      await returnToRoutingHubThroughLoadingScreen({ allowDuringInFlight: true, failedArrival: { screen: 'academy-map' } });
    }
    throw error;
  } finally {
    landedOnConversationDay();
    conversationRequestInFlight = false;
    conversationDayStage.setControlsDisabled(false);
    focusConversationDayInputIfContinuing();
  }
}

// Daytime landing for an event-flag conversation. Routing is the official mode, so every newly entered event
// conversation lands here. Mirrors startConversationDay's loading-interstitial opening flow, but sets the
// interaction up through /api/event-flags/start — so the event's source_type:'event', event context, and event
// location are preserved (only the presentation screen differs — the event semantics are driven by the backend
// state + finalization, not by which screen is shown). The stage frame shows the event location's field stage
// (renderConversationDayStage → the refreshed field), with no event-specific map / placeholder. This is the sole
// event-conversation landing that the auto-start callers (post-training loop, routing map arrival, new-game intro,
// manual event-tab start) reach, directly or through startAcademyConversationSessionFromPendingEvent /
// startEventFlagInteractionFromScreen.
async function startConversationDayFromPendingEvent(flagId, { loadingAlreadyVisible = false, allowDuringInFlight = false } = {}) {
  if (conversationRequestInFlight && !allowDuringInFlight) {
    showProcessingToast();
    return;
  }
  await openEventConversationDay(async () => {
    const result = await postJson('/api/event-flags/start', { flag_id: flagId, screen: 'conversation-day' });
    return { ...result, flag_id: flagId };
  }, { loader: loadingAlreadyVisible ? 'box' : 'own' });
}

// Open the daytime conversation marked event through the conversation passage. setUp runs first inside readiness and
// returns the set-up interaction ({ character_id, state, flag_id, location_id }); the event's stage is only known once
// it has run, so the passage begins in the night and readiness places the event location after the refresh.
// loader names the loading screen the passage runs on: 'own' raises it here, 'box' takes over a box loader that is
// already up, 'passage' continues a passage the caller has already begun in the night.
async function openEventConversationDay(setUp, { loader }) {
  if (!['own', 'box', 'passage'].includes(loader)) throw new Error(`event conversation: unknown loader ${JSON.stringify(loader)}`);
  conversationRequestInFlight = true;
  conversationDayStage.setControlsDisabled(true);
  markConversationDayKind('event');
  let openingStreamStartedResolve = null;
  let openingStreamStartedResolved = false;
  const openingStreamStarted = new Promise((resolve) => {
    openingStreamStartedResolve = resolve;
  });
  const markOpeningStreamStarted = () => {
    if (openingStreamStartedResolved) return;
    openingStreamStartedResolved = true;
    openingStreamStartedResolve?.();
  };
  // The opening reveals from the landing on the daytime screen, not from the stream start the passage still arrives
  // over. A start that fails releases it in finally, so a pending opening is never left waiting.
  let landedOnConversationDay = null;
  const conversationDayLanded = new Promise((resolve) => {
    landedOnConversationDay = resolve;
  });
  let openingPromise = Promise.resolve();
  if (loader === 'box') beginConversationPassage(null);
  const readiness = (async () => {
    const started = await setUp();
    notifyAcademyLoadingProgress();
    activeCharacterId = started.character_id;
    currentRuntimeState = started.state ?? currentRuntimeState;
    clearVisibleConversation();
    conversationDayStage.surface.setHistory([]);
    writeDebugLog({
      started_event_interaction: started.flag_id,
      character_id: started.character_id,
      location_id: started.location_id,
      state: started.state,
      screen: 'conversation-day'
    });
    await refresh();
    notifyAcademyLoadingProgress();
    passagePlaces(academyFieldReading.conversationStage());
    openingPromise = ensureConversationDayOpening({ onAssistantStreamStart: markOpeningStreamStarted, revealAfter: conversationDayLanded });
    await Promise.race([openingStreamStarted, openingPromise]);
  })();
  try {
    if (loader === 'own') {
      await showAcademyLoadingScreenUntilReady({
        readiness,
        nextScreen: 'conversation-day',
        refreshBeforeNextScreen: false,
        passage: { stage: null }
      });
    } else {
      try {
        await awaitConversationReadiness(readiness, { passage: true });
        await passageArrives(conversationPassagePartner());
      } catch (error) {
        reportLoadingError(error);
        throw error;
      }
      showScreen('conversation-day');
    }
    renderConversationDayStage();
    landedOnConversationDay();
    await openingPromise;
  } catch (error) {
    // Loading-residual defense: a failed event conversation start (every loader) must not strand the player on the
    // loading screen. A non-settings failure still on the loader un-strands to conversation-day with the cause on its
    // status line, then re-raises so the caller's reporter logs.
    if (isAcademyLoadingScreenActive() && settingsRedirectErrorMessage(error) == null) {
      showScreen('conversation-day');
      conversationDayStage.setStatus(errorDisplayMessage(error), { tone: 'error' });
    }
    throw error;
  } finally {
    landedOnConversationDay();
    conversationRequestInFlight = false;
    conversationDayStage.setControlsDisabled(false);
    focusConversationDayInputIfContinuing();
  }
}

// Dev entry (?initialScreen=conversation-day): open the daytime screen. With a selectable roster present it
// starts a real conversation with the first roster character (opening / turn / stream over the existing API);
// with an empty roster it just displays the composed screen (renderScreen). No production landing is added.
function showConversationDayDevScreen() {
  const character = selectableCharacters[0];
  if (character) {
    startConversationDay(character.character_id).catch(reportError);
    return;
  }
  showScreen('conversation-day');
}

// ── 表の部屋（調合・工房・錬成室）で分け合う作り ──────────────────────────────────────────────────────────
// 三画面は同じ作りの上に、表の中身の並べ方だけを変えて置く: 地は場所の絵を画面いっぱいに敷き（送り出しの幕・場所の絵の上の待ちと
// 同じ destinationArt の一枚を cover・center で — 待つあいだの絵がそのまま画面の地になる）、表の下だけを暗がりで沈め（style.css の
// .table-room-table::before が表の矩形から広げて置く）、左上に場所の名、右上に出る紋を置く。調合の分類と錬成室の釦の紋は
// tableRoomSigils.svg の symbol で、起動時に #table-room-sigil-symbols へ写して <use> で引く（露台の能力の紋と同じ作法）。
const TABLE_ROOM_DESTINATIONS = Object.freeze({ 'academy-alchemy': 'alchemy', 'academy-workshop': 'workshop', 'academy-atelier': 'homunculus' });
for (const [screen, destination] of Object.entries(TABLE_ROOM_DESTINATIONS)) {
  const art = destinationArt(destination);
  if (art === null) throw new Error(`table room ${screen}: the destination ${destination} has no place art to stand on`);
  screens[screen].style.setProperty('--table-room-art', `url('${art}')`);
}

const TABLE_ROOM_SIGILS_URL = '/tableRoomSigils.svg';
const TABLE_ROOM_SVG_NS = 'http://www.w3.org/2000/svg';

async function loadTableRoomSigils() {
  const response = await fetch(TABLE_ROOM_SIGILS_URL);
  if (!response.ok) throw new Error(`table room: ${TABLE_ROOM_SIGILS_URL} answered ${response.status}`);
  const sheet = new DOMParser().parseFromString(await response.text(), 'image/svg+xml');
  if (sheet.querySelector('parsererror')) throw new Error(`table room: ${TABLE_ROOM_SIGILS_URL} is not an SVG`);
  const symbols = sheet.documentElement.querySelectorAll(':scope > symbol[id^="table-sigil-"]');
  if (symbols.length === 0) throw new Error(`table room: ${TABLE_ROOM_SIGILS_URL} has no sigil symbols`);
  document.querySelector('#table-room-sigil-symbols').replaceChildren(...Array.from(symbols, (symbol) => document.importNode(symbol, true)));
}

// 紋の svg（置き場の symbol を <use> で引く・名前を持たない）。名前は呼び出し側が釦の aria-label か role=img の印で付ける。
function tableRoomSigilSvg(key) {
  const id = `table-sigil-${key}`;
  const symbol = document.getElementById(id);
  if (!(symbol instanceof SVGSymbolElement)) throw new Error(`table room: no sigil symbol ${id}`);
  const svg = document.createElementNS(TABLE_ROOM_SVG_NS, 'svg');
  svg.setAttribute('class', 'table-room-sigil');
  svg.setAttribute('viewBox', symbol.getAttribute('viewBox'));
  svg.setAttribute('aria-hidden', 'true');
  svg.setAttribute('focusable', 'false');
  const use = document.createElementNS(TABLE_ROOM_SVG_NS, 'use');
  use.setAttribute('href', `#${id}`);
  svg.append(use);
  return svg;
}

// 名前を読み上げにだけ持つ印（role=img）。中身は渡された svg（紋・ダンジョンの持ち物の印）。
function tableRoomMark(svg, name, className) {
  const mark = document.createElement('span');
  mark.className = className;
  mark.setAttribute('role', 'img');
  mark.setAttribute('aria-label', name);
  mark.append(svg);
  return mark;
}

// 所持金（札の段の右に一つだけ）。行ごとに所持を繰り返さない。
function setTableRoomPurse(selector, money) {
  const purse = document.querySelector(selector);
  if (!purse) throw new Error(`table room purse (${selector}) is missing (broken markup wiring)`);
  purse.textContent = moneyText(money);
}

// 絞り込みの釦（押すと絞り、もう一度押すと解ける）。中身は紋の印か字（ティア）。
function tableRoomFilterButton(content, onPress) {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = typeof content === 'string' ? 'table-room-chip' : 'table-room-mark-button';
  button.append(content);
  button.addEventListener('click', onPress);
  return button;
}

// 品の行の値の一行（名と値・足りない値は data-short で薔薇色）。名の無い一行は金額。
function tableRoomCostLine(name, amount, short) {
  const line = document.createElement('span');
  line.className = 'table-room-cost';
  if (short) line.dataset.short = 'true';
  const label = document.createElement('span');
  label.className = 'table-room-cost-name';
  label.textContent = name;
  const value = document.createElement('span');
  value.className = 'table-room-cost-amount';
  value.textContent = amount;
  line.append(label, value);
  return line;
}

function tableRoomCell(className) {
  const cell = document.createElement('span');
  cell.className = `table-room-cell ${className}`;
  return cell;
}

// ── Alchemy lab screen (academy-alchemy): the routing "alchemy" (調合) destination lands here ─────────────
// A routing dispatch to the alchemy destination navigates to #academy-alchemy-screen through the existing
// loading interstitial (performRoutingTurnDispatch / navigateToPostContentScreen consume the dispatch, the mirror
// ROUTING_DISPATCH_SCREENS maps alchemy → academy-alchemy). showScreen fetches the full 56-recipe standing book
// here. Like the workshop it is a STAY-and-craft screen: selecting an affordable recipe crafts it in one call
// (POST /api/alchemy/craft — a choice-cost recipe is crafted from the element sigil the player presses in its row),
// floats a result popup with the crafted item as its 主役, and on 受け取る the player STAYS in the lab with the board
// re-fetched (held / affordable change as materials are consumed). There is no affordability guarantee (every recipe
// may be unaffordable), so leaving is an explicit 出る sigil that navigates to the server-authoritative
// post_content_screen from GET /api/alchemy — never a frontend-hardcoded default. The payload / craft contract
// validators live in the headless-testable module alchemyArrivalClient.js (imported above), so the fail-fast
// paths are unit-tested without a browser.

// Single-flight guard so a double click never fires two POST /api/alchemy/craft (each would consume materials).
let alchemyCraftInFlight = false;
// The server-authoritative exit screen from the latest GET /api/alchemy, held so the 出る sigil can navigate
// onward. Never a fabricated default — set only from a validated arrival payload, kept across in-visit re-fetches.
let alchemyExitScreen = null;
// The active 分類 (category) board filter ('all' — no chip pressed — or one of ALCHEMY_CATEGORY_ORDER). Reset on a
// fresh arrival, preserved across the post-craft re-fetches so a craft does not undo the player's narrowing.
let alchemyCategoryFilter = 'all';

// The arrival status line is the error banner: a failed board fetch / craft surfaces here instead of leaving
// empty or placeholder rows (no silent fallback). The status line ships in the arrival markup, so a missing node
// is broken wiring — throw rather than silently suppressing the error surface craft failures must appear on.
function setAlchemyScreenStatus(message, { tone = null } = {}) {
  const status = document.querySelector('#academy-alchemy-status');
  if (!status) {
    throw new Error('alchemy arrival status line (#academy-alchemy-status) is missing (broken markup wiring)');
  }
  const text = String(message ?? '').trim();
  if (!text) {
    status.hidden = true;
    status.textContent = '';
    delete status.dataset.tone;
    return;
  }
  status.hidden = false;
  status.textContent = text;
  if (tone) status.dataset.tone = tone;
  else delete status.dataset.tone;
}

function reportAlchemyScreenError(error) {
  if (handleRuntimeApiError(error, { allowSettingsRedirect: true })) return;
  setAlchemyScreenStatus(errorDisplayMessage(error), { tone: 'error' });
  console.error(error);
}

// Fetch the standing recipe book and render the selectable rows. GET /api/alchemy is routing-only and reads
// runtime state (elapsed_weeks) + the inventory, so a non-routing / save-less reach fail-fasts here (409); a
// malformed response — not exactly 56 recipes, a recipe missing a required field, or a missing server exit —
// throws (validateAlchemyBookPayload), so the board never shows empty or placeholder rows. Every throw surfaces
// on the arrival status line. Fail closed: the prior board is cleared BEFORE the fetch so a failed / malformed
// re-fetch leaves NO stale, still-clickable rows (an already-priced recipe must never remain presentable against
// last visit's inventory).
async function refreshAlchemyScreen({ resetFilter = false } = {}) {
  setAlchemyScreenStatus('');
  hideAlchemyResultPopup();
  if (resetFilter) alchemyCategoryFilter = 'all';
  document.querySelector('#academy-alchemy-recipes').replaceChildren();
  const payload = await getJson('/api/alchemy');
  renderAlchemyBoard(payload);
}

// The whole payload is validated fail-fast by the shared headless-testable validator BEFORE any DOM mutation
// (bad shape / wrong count / a malformed recipe / a missing exit all throw here), so the board is never
// half-rendered on a broken response; only after it validates are the sorted rows mounted. The server exit is
// held for the 出る sigil; the purse is the held money every recipe's money cost carries (one value, shown once).
function renderAlchemyBoard(payload) {
  const { recipes, postContentScreen } = validateAlchemyBookPayload(payload);
  alchemyExitScreen = postContentScreen;
  setTableRoomPurse('#academy-alchemy-purse', recipes[0].costs.money.held);
  const sorted = sortAlchemyRecipes(recipes);
  document.querySelector('#academy-alchemy-recipes').replaceChildren(...sorted.map((recipe) => buildAlchemyRow(recipe)));
  renderAlchemyFilter();
  applyAlchemyFilter(alchemyCategoryFilter);
}

// The 分類 filter: one sigil button per category (贈り物 / 仲間強化 / 自分用強化 / ダンジョン消耗品 / 換金品 — the name is
// read out only). No chip pressed is すべて; pressing a chip narrows the board in place (no re-fetch), pressing the
// pressed chip again releases it.
function renderAlchemyFilter() {
  const filter = document.querySelector('#academy-alchemy-filter');
  filter.replaceChildren(...ALCHEMY_CATEGORY_ORDER.map((category) => {
    const button = tableRoomFilterButton(alchemyCategoryMark(category), () => applyAlchemyFilter(alchemyCategoryFilter === category ? 'all' : category));
    button.classList.add('academy-alchemy-filter-chip');
    button.dataset.category = category;
    return button;
  }));
}

function alchemyCategoryMark(category) {
  const mark = tableRoomMark(tableRoomSigilSvg(category), alchemyCategoryLabel(category), 'academy-alchemy-category-mark');
  mark.dataset.category = category;
  return mark;
}

// Filter the board to one 分類 (or すべて) by toggling each row's hidden attribute — no re-fetch / re-render, so
// the confirmed board stays intact. The pressed chip is marked so the current selection reads.
function applyAlchemyFilter(category) {
  alchemyCategoryFilter = category;
  for (const row of document.querySelectorAll('#academy-alchemy-recipes .academy-alchemy-row')) {
    row.hidden = category !== 'all' && row.dataset.category !== category;
  }
  for (const chip of document.querySelectorAll('#academy-alchemy-filter .academy-alchemy-filter-chip')) {
    chip.setAttribute('aria-pressed', String(chip.dataset.category === category));
  }
}

// Build one recipe ROW from an ALREADY-VALIDATED normalized recipe (validateAlchemyRecipe output: costs carry
// their short / enough flags, category is derived). Pure DOM assembly — the field validation lives in the shared
// validator so it is headless-testable. The row's cells, left to right: the 分類 sigil, the 品名 (name + description
// sub-line), the 効果 summary, the materials (each 「名 必要数（所持 n）」, the short value in rose — or, for a
// choice-cost recipe, 「T{tier} ×{quantity}」 over the six element sigils with their held counts), and the money
// cost (only when the recipe has one). An affordable row carries the gold line on its left edge; an unaffordable one
// is sunk (data-lack) and not pressable. A fixed-cost row is one button that crafts; a choice-cost row crafts from the
// element sigil pressed in it (an element short of the quantity is not pressable).
function buildAlchemyRow(recipe) {
  const item = document.createElement('li');
  item.className = 'table-room-row academy-alchemy-row';
  item.dataset.recipeId = recipe.recipe_id;
  item.dataset.category = recipe.category;
  if (!recipe.affordable) item.dataset.lack = 'true';
  const fixed = recipe.costs.mode !== 'choice';
  const body = document.createElement(fixed ? 'button' : 'div');
  body.className = 'table-room-row-body academy-alchemy-row-body';
  if (fixed) {
    body.type = 'button';
    body.disabled = !recipe.affordable;
  }

  const categoryCell = tableRoomCell('academy-alchemy-cell-category');
  categoryCell.append(alchemyCategoryMark(recipe.category));

  const nameCell = tableRoomCell('academy-alchemy-cell-name');
  const nameEl = document.createElement('span');
  nameEl.className = 'table-room-name';
  nameEl.textContent = recipe.result.name;
  const descEl = document.createElement('span');
  descEl.className = 'table-room-desc';
  descEl.textContent = recipe.result.description;
  nameCell.append(nameEl, descEl);

  const effectCell = tableRoomCell('academy-alchemy-cell-effect');
  const effectChip = document.createElement('span');
  effectChip.className = 'table-room-effect';
  effectChip.textContent = recipe.result.effect_summary;
  // The effect pill is held to one line (nowrap + ellipsis); title keeps the full summary reachable when it is
  // truncated (a long multi-parameter self_boost effect exceeds the 効果 column width).
  effectChip.title = recipe.result.effect_summary;
  effectCell.append(effectChip);

  const itemsCell = tableRoomCell('academy-alchemy-cell-items');
  if (fixed) {
    for (const cost of recipe.costs.items) itemsCell.append(tableRoomCostLine(cost.display_name, `${cost.required}（所持 ${cost.held}）`, cost.short));
  } else {
    itemsCell.append(buildAlchemyChoice(recipe));
  }

  const moneyCell = tableRoomCell('academy-alchemy-cell-money');
  if (recipe.costs.money.required > 0) moneyCell.append(tableRoomCostLine('', moneyText(recipe.costs.money.required), recipe.costs.money.short));

  body.append(categoryCell, nameCell, effectCell, itemsCell, moneyCell);
  // A failed / malformed craft rejects (craftAlchemyRecipe does not swallow it); surface it through the alchemy
  // error reporter (LM-config errors are routed to settings by handleRuntimeApiError) and the player STAYS —
  // nothing was consumed, so the same board is still valid for a retry. No silent retry / auto fallback.
  if (fixed && recipe.affordable) body.addEventListener('click', () => craftAlchemyRecipe(recipe, null).catch(reportAlchemyScreenError));
  item.append(body);
  return item;
}

// A choice-cost recipe's materials cell: the requirement 「T{tier} ×{quantity}」 over the six element options, each its
// element sigil (from the terrace ability sigils) and held count. An option holding enough of an affordable recipe
// is a gold-ringed button that crafts with that element's material; an option short of the quantity is sunk and its
// held count is rose.
function buildAlchemyChoice(recipe) {
  const { choice } = recipe.costs;
  const wrap = document.createElement('span');
  wrap.className = 'academy-alchemy-choice';
  const need = document.createElement('span');
  need.className = 'academy-alchemy-choice-need';
  need.textContent = `T${choice.tier} ×${choice.quantity}`;
  const options = document.createElement('span');
  options.className = 'academy-alchemy-choice-options';
  for (const option of choice.options) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'academy-alchemy-choice-option';
    button.dataset.itemId = option.item_id;
    button.disabled = !recipe.affordable || !option.enough;
    if (!option.enough) button.dataset.short = 'true';
    button.setAttribute('aria-label', `${option.display_name}で仕上げる`);
    const sigil = abilitySigilLabel(option.element, workshopElementLabel(option.element));
    sigil.classList.add('academy-alchemy-choice-sigil');
    const held = document.createElement('span');
    held.className = 'academy-alchemy-choice-held';
    held.textContent = String(option.held);
    button.append(sigil, held);
    if (!button.disabled) {
      button.addEventListener('click', () => craftAlchemyRecipe(recipe, buildAlchemyChoiceMaterials(option.item_id, choice.quantity)).catch(reportAlchemyScreenError));
    }
    options.append(button);
  }
  wrap.append(need, options);
  return wrap;
}

// The in-flight craft indicator: POST /api/alchemy/craft consumes materials + grants the item, so the craft can
// take a visible beat. The alchemy lab is a stay-and-craft screen (no transition to the loading screen), so the
// wait is covered IN SCREEN: the board goes busy (dimmed + non-interactive) under an overlay holding the screen wait
// mark, so the wait sigil turns in the bottom-right corner, in the alchemy token layer. Built/removed in lockstep with the craft (setAlchemyCrafting(false) in the caller's
// finally), so it never lingers past a resolution.
function buildAlchemyCraftingIndicator() {
  const overlay = document.createElement('div');
  overlay.className = 'academy-alchemy-crafting';
  overlay.id = 'academy-alchemy-crafting';
  overlay.append(screenWaitMark());
  return overlay;
}

// Toggle the board's in-flight craft busy state: mark the board (data-crafting) so the CSS dims + blocks the
// recipe grid, and float / remove the crafting overlay. A missing board node is broken markup — fail fast.
function setAlchemyCrafting(active) {
  const board = document.querySelector('.academy-alchemy-board');
  if (!board) {
    throw new Error('alchemy board (.academy-alchemy-board) is missing (broken markup wiring)');
  }
  const existing = board.querySelector('#academy-alchemy-crafting');
  if (active) {
    board.dataset.crafting = 'true';
    if (!existing) board.append(buildAlchemyCraftingIndicator());
  } else {
    delete board.dataset.crafting;
    if (existing) existing.remove();
  }
}

// Craft the selected recipe: POST /api/alchemy/craft { recipe_id, materials? } (a single call; the backend
// resolves the cost, atomically consumes materials + money, grants the item, and records the content result — no
// conversation). `materials` is the single-element choice payload for a choice recipe, null for a fixed recipe.
// The response is resolved AGAINST the selected recipe (the crafted recipe id + item identity must match — the
// popup reflects what the server actually crafted, not a blindly-trusted stale row; a divergence fail-fasts), the
// authoritative state is adopted, and the result popup floats. A failed craft REJECTS (fail-fast): the throw is
// not swallowed — it propagates to the caller's `.catch(reportAlchemyScreenError)` (materials stay unconsumed, so
// the board is still valid). The in-screen crafting busy state covers the wait and is cleared in finally
// regardless of outcome, so the crafting overlay never lingers past a resolution. alchemyCraftInFlight is the
// single-flight guard: a second press hits showProcessingToast so no second craft POST is issued.
async function craftAlchemyRecipe(recipe, materials) {
  if (alchemyCraftInFlight) {
    showProcessingToast();
    return;
  }
  alchemyCraftInFlight = true;
  try {
    setAlchemyScreenStatus('');
    setAlchemyCrafting(true);
    const response = await postJson('/api/alchemy/craft', { recipe_id: recipe.recipe_id, ...(materials ? { materials } : {}) });
    const { state, display } = resolveAlchemyCraft(response, recipe);
    // Adopt the authoritative post-craft state (the materials were consumed / the item added server-side).
    currentRuntimeState = state;
    writeDebugLog({ crafted_alchemy: recipe.recipe_id, state });
    openAlchemyResultPopup(display);
  } finally {
    alchemyCraftInFlight = false;
    setAlchemyCrafting(false);
  }
}

// The result popup floats over the board (the workshop / dungeon result-popup idiom: an on-screen modal, not a
// screen change) with the crafted item's name as the 主役, then the description, the 分類 badge + 効果 summary, and
// the crafted quantity. The display is the resolveAlchemyCraft output — cross-checked against the selection — so
// nothing is re-derived or blindly reused.
function openAlchemyResultPopup(display) {
  const popup = document.querySelector('#academy-alchemy-result-popup');
  const body = document.querySelector('#academy-alchemy-result-body');
  if (!popup || !body) {
    throw new Error('alchemy result popup markup is missing (broken wiring)');
  }
  const name = document.createElement('h3');
  name.id = 'academy-alchemy-result-title';
  name.className = 'academy-alchemy-result-name';
  name.textContent = display.name;
  const done = document.createElement('p');
  done.className = 'academy-alchemy-result-done';
  done.textContent = display.quantity > 1 ? `調合が仕上がりました。（×${display.quantity}）` : '調合が仕上がりました。';
  const description = document.createElement('p');
  description.className = 'academy-alchemy-result-description';
  description.textContent = display.description;

  const summary = document.createElement('p');
  summary.className = 'academy-alchemy-result-summary';
  const category = document.createElement('span');
  category.className = 'academy-alchemy-result-category';
  category.dataset.category = display.category;
  category.textContent = alchemyCategoryLabel(display.category);
  const effect = document.createElement('span');
  effect.className = 'academy-alchemy-result-effect';
  effect.textContent = display.effect_summary;
  summary.append(category, effect);

  body.replaceChildren(name, done, description, summary);
  popup.hidden = false;
}

function hideAlchemyResultPopup() {
  const popup = document.querySelector('#academy-alchemy-result-popup');
  if (popup) popup.hidden = true;
}

// 受け取る: close the result and STAY in the alchemy lab, re-fetching the board (held / affordable changed as the
// materials were consumed). This is NOT a navigation — the alchemy lab is a stay-and-craft screen; leaving is the
// separate 「調合室を出る」. The re-fetch preserves the active 分類 filter.
function acknowledgeAlchemyResult() {
  hideAlchemyResultPopup();
  return refreshAlchemyScreen();
}

// 調合室を出る: leave the stay-and-craft screen through the server-authoritative post_content_screen held from the
// latest GET /api/alchemy (routing-only → the routing hub) via the shared return over the place's art
// (returnToRoutingHubFromPlace — never a bare enterRoutingHub under the still-visible alchemy screen, which reads as a
// freeze). A double press is guarded by the shared routingContentReturnInFlight flag so it never
// starts two hub returns. A missing held screen is broken state — fail fast (never a fabricated default); the
// alchemy lab is reachable with zero crafts, so this is the always-available exit even when every recipe is
// unaffordable.
async function exitAlchemy() {
  if (routingContentReturnInFlight) {
    showProcessingToast();
    return;
  }
  const nextScreen = alchemyExitScreen;
  if (typeof nextScreen !== 'string' || nextScreen === '') {
    throw new Error('alchemy exit: no post_content_screen held (調合室の退出先が未取得 — broken arrival flow)');
  }
  routingContentReturnInFlight = true;
  try {
    await returnToRoutingHubFromContent(nextScreen);
  } finally {
    routingContentReturnInFlight = false;
  }
}

document.querySelector('#academy-alchemy-result-close').addEventListener('click', () => acknowledgeAlchemyResult().catch(reportAlchemyScreenError));
document.querySelector('#academy-alchemy-exit').addEventListener('click', () => exitAlchemy().catch(reportAlchemyScreenError));

// ── Workshop arrival screen (academy-workshop): the routing "workshop" (工房) destination lands here ─────────
// A routing dispatch to the workshop destination navigates to #academy-workshop-screen through the existing
// loading interstitial (performRoutingTurnDispatch / navigateToPostContentScreen consume the dispatch, the mirror
// ROUTING_DISPATCH_SCREENS maps workshop → academy-workshop). showScreen fetches the full 96-recipe board here.
// Unlike the alchemy arrival (a single completion that returns to the hub), the workshop is a STAY-and-craft
// screen: selecting an affordable recipe crafts it in one call (POST /api/workshop/craft — the LLM names the
// item), floats a result popup with the name/flavor as its 主役, and on 受け取る the player STAYS in the workshop
// with the board re-fetched (held / affordable change as materials are consumed). There is no affordability
// guarantee (every recipe may be unaffordable), so leaving is an explicit 出る sigil (工房を出る) that navigates to the
// server-authoritative post_content_screen from GET /api/workshop — never a frontend-hardcoded default. The
// payload / craft contract validators live in the headless-testable module workshopArrivalClient.js (imported
// above), so the fail-fast paths are unit-tested without a browser.
// Single-flight guard so a double click never fires two POST /api/workshop/craft (each would consume materials).
let workshopCraftInFlight = false;
// The server-authoritative exit screen from the latest GET /api/workshop, held so 「工房を出る」 can navigate
// onward. Never a fabricated default — set only from a validated arrival payload, kept across in-visit re-fetches.
let workshopExitScreen = null;
// The active board filter — a 3-axis AND composition (種別 × ティア × 属性), each axis WORKSHOP_FILTER_ALL or an
// exact value. Reset on a fresh arrival, preserved across the post-craft re-fetches so a craft does not throw the
// player back to すべて on any axis. The normalized board recipes are held alongside so the in-place filter matches
// on the validated recipe objects (the same workshopVisibleRecipes predicate the headless tests pin) rather than
// re-deriving the match from DOM datasets.
const workshopFilter = { category: WORKSHOP_FILTER_ALL, tier: WORKSHOP_FILTER_ALL, element: WORKSHOP_FILTER_ALL };
let workshopBoardRecipes = [];

// The arrival status line is the error banner: a failed board fetch / craft surfaces here instead of leaving
// empty or placeholder rows (no silent fallback). The status line ships in the arrival markup, so a missing
// node is broken wiring — throw rather than silently suppressing the error surface craft failures must appear on.
function setWorkshopScreenStatus(message, { tone = null } = {}) {
  const status = document.querySelector('#academy-workshop-status');
  if (!status) {
    throw new Error('workshop arrival status line (#academy-workshop-status) is missing (broken markup wiring)');
  }
  const text = String(message ?? '').trim();
  if (!text) {
    status.hidden = true;
    status.textContent = '';
    delete status.dataset.tone;
    return;
  }
  status.hidden = false;
  status.textContent = text;
  if (tone) status.dataset.tone = tone;
  else delete status.dataset.tone;
}

function reportWorkshopScreenError(error) {
  if (handleRuntimeApiError(error, { allowSettingsRedirect: true })) return;
  setWorkshopScreenStatus(errorDisplayMessage(error), { tone: 'error' });
  console.error(error);
}

// Fetch the weekly workshop board and render the selectable rows. GET /api/workshop is routing-only and reads
// runtime state (elapsed_weeks) + the inventory, so a non-routing / save-less reach fail-fasts here (409); a
// malformed response — not exactly 96 recipes, a recipe missing a required field / leaking a withheld roll
// output, or a missing server exit — throws (validateWorkshopArrivalPayload), so the board never shows empty,
// placeholder, or quality-leaking rows. Every throw surfaces on the arrival status line. Fail closed: the prior
// board is cleared BEFORE the fetch so a failed / malformed re-fetch leaves NO stale, still-clickable rows
// (an already-priced recipe must never remain presentable against last visit's inventory).
async function refreshWorkshopScreen({ resetFilter = false } = {}) {
  setWorkshopScreenStatus('');
  hideWorkshopResultPopup();
  if (resetFilter) resetWorkshopFilter();
  document.querySelector('#academy-workshop-recipes').replaceChildren();
  const payload = await getJson('/api/workshop');
  renderWorkshopBoard(payload);
}

// The whole payload is validated fail-fast by the shared headless-testable validator BEFORE any DOM mutation
// (bad shape / wrong count / a malformed or quality-leaking recipe / a missing exit all throw here), so the board
// is never half-rendered on a broken response; only after it validates are the sorted rows mounted. The server
// exit is held for the 出る sigil; the purse is the held money every recipe's money cost carries (one value, shown once).
function renderWorkshopBoard(payload) {
  const { recipes, postContentScreen } = validateWorkshopArrivalPayload(payload);
  workshopExitScreen = postContentScreen;
  setTableRoomPurse('#academy-workshop-purse', recipes[0].money.held);
  const sorted = sortWorkshopRecipes(recipes);
  workshopBoardRecipes = sorted;
  document.querySelector('#academy-workshop-recipes').replaceChildren(...sorted.map((recipe) => buildWorkshopRow(recipe)));
  renderWorkshopFilters(sorted);
  applyWorkshopFilter();
}

// Reset all three filter axes to すべて (the fresh-arrival state). One place so refreshWorkshopScreen's resetFilter
// resets EVERY axis, never just 種別.
function resetWorkshopFilter() {
  workshopFilter.category = WORKSHOP_FILTER_ALL;
  workshopFilter.tier = WORKSHOP_FILTER_ALL;
  workshopFilter.element = WORKSHOP_FILTER_ALL;
}

// The 種別 mark (剣・杖・短杖・護符 — the dungeon's own item marks) and the 属性 sigil (the terrace ability sigils), each
// naming itself only to the reader. Shared by the filter buttons and the rows.
const WORKSHOP_KIND_MARKS = Object.freeze({ sword: swordSvg, staff: staffSvg, short_rod: wandSvg, amulet: charmSvg });

function workshopKindMark(category) {
  const template = document.createElement('template');
  template.innerHTML = WORKSHOP_KIND_MARKS[category]();
  return tableRoomMark(template.content.firstElementChild, workshopCategoryLabel(category), 'academy-workshop-kind-mark');
}

function workshopElementMark(element) {
  const mark = abilitySigilLabel(element, workshopElementLabel(element));
  mark.classList.add('academy-workshop-element-mark');
  return mark;
}

// Build the three filter groups (種別 × ティア × 属性). 種別 and 属性 come from the frozen closed sets
// (WORKSHOP_CATEGORY_ORDER / WORKSHOP_ELEMENTS) as mark buttons; the ティア chips (values, so words) are the tiers
// actually present in this week's board (workshopTierValues), so no empty tier is offered. No button pressed on an
// axis is すべて; pressing narrows in place (no re-fetch), pressing the pressed button again releases that axis.
function renderWorkshopFilters(recipes) {
  renderWorkshopFilterGroup('#academy-workshop-filter', 'category',
    WORKSHOP_CATEGORY_ORDER.map((category) => ({ value: category, content: workshopKindMark(category) })));
  renderWorkshopFilterGroup('#academy-workshop-tier-filter', 'tier',
    workshopTierValues(recipes).map((tier) => ({ value: tier, content: `T${tier}` })));
  renderWorkshopFilterGroup('#academy-workshop-element-filter', 'element',
    WORKSHOP_ELEMENTS.map((element) => ({ value: element, content: workshopElementMark(element) })));
}

// Render one filter group (one button per closed-set / data-derived option). A missing group container is broken
// markup → throw (never silently drop an axis).
function renderWorkshopFilterGroup(selector, axis, options) {
  const group = document.querySelector(selector);
  if (!group) throw new Error(`workshop arrival filter group (${selector}) is missing (broken markup wiring)`);
  group.replaceChildren(...options.map(({ value, content }) => {
    const button = tableRoomFilterButton(content, () => selectWorkshopFilter(axis, workshopFilter[axis] === value ? WORKSHOP_FILTER_ALL : value));
    button.classList.add('academy-workshop-filter-chip');
    button.dataset.axis = axis;
    button.dataset.value = String(value);
    return button;
  }));
}

// Set one filter axis and re-apply. The value is the frozen axis value (a category / element string, a tier number,
// or WORKSHOP_FILTER_ALL) — kept as-is so the tier axis stays numeric for the workshopVisibleRecipes predicate.
function selectWorkshopFilter(axis, value) {
  workshopFilter[axis] = value;
  applyWorkshopFilter();
}

// Apply the current 3-axis filter to the board IN PLACE (no re-fetch / re-render): toggle each row's hidden by
// whether its recipe is in the visible set (workshopVisibleRecipes — the same AND predicate the headless tests
// pin), mark the pressed button per axis (aria-pressed), and reveal the explicit 「該当するレシピがありません」 empty
// message when the combination matches no recipe (never a silently blank table).
function applyWorkshopFilter() {
  const visibleIds = new Set(workshopVisibleRecipes(workshopBoardRecipes, workshopFilter).map((recipe) => recipe.recipe_id));
  for (const row of document.querySelectorAll('#academy-workshop-recipes .academy-workshop-row')) {
    row.hidden = !visibleIds.has(row.dataset.recipeId);
  }
  for (const chip of document.querySelectorAll('#academy-workshop-screen .academy-workshop-filter-chip')) {
    chip.setAttribute('aria-pressed', String(chip.dataset.value === String(workshopFilter[chip.dataset.axis])));
  }
  setWorkshopBoardEmpty(visibleIds.size === 0);
}

// Toggle the explicit empty-state message (a filter combination matched no recipe). The node ships in the arrival
// markup, so a missing node is broken wiring → throw rather than silently showing a blank table.
function setWorkshopBoardEmpty(empty) {
  const node = document.querySelector('#academy-workshop-empty');
  if (!node) throw new Error('workshop arrival empty-state (#academy-workshop-empty) is missing (broken markup wiring)');
  node.hidden = !empty;
}

// Build one recipe ROW from an ALREADY-VALIDATED normalized recipe (validateWorkshopRecipe output: cost rows carry
// their `short` flag, base_effects is an ordered {label,value} list, category is derived). This is pure DOM
// assembly — the field validation lives in the shared validator so it is headless-testable. The row's cells, left
// to right: the 種別 mark, the 属性 sigil, the tier, the recipe-fixed base performance, each material
// 「名 必要数（所持 n）」 (the short value in rose), the money, and the qualitative 出来栄え見込み (the S-derived outlook —
// never a confirmed quality, which the arrival withholds). An affordable row carries the gold line on its left edge
// and crafts on press; an unaffordable one is sunk (data-lack) and not pressable.
function buildWorkshopRow(recipe) {
  const item = document.createElement('li');
  item.className = 'table-room-row academy-workshop-row';
  item.dataset.recipeId = recipe.recipe_id;
  if (!recipe.affordable) item.dataset.lack = 'true';
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'table-room-row-body academy-workshop-row-body';
  button.disabled = !recipe.affordable;

  const kindCell = tableRoomCell('academy-workshop-cell-mark');
  kindCell.append(workshopKindMark(recipe.category));
  const elementCell = tableRoomCell('academy-workshop-cell-mark');
  elementCell.append(workshopElementMark(recipe.element));
  const tierCell = tableRoomCell('academy-workshop-cell-tier');
  tierCell.textContent = `T${recipe.tier}`;

  const effectsCell = tableRoomCell('academy-workshop-cell-effects');
  for (const effect of recipe.base_effects) effectsCell.append(workshopEffectChip(effect));

  const itemsCell = tableRoomCell('academy-workshop-cell-items');
  for (const cost of recipe.items) itemsCell.append(tableRoomCostLine(cost.display_name, `${cost.required}（所持 ${cost.held}）`, cost.short));

  const moneyCell = tableRoomCell('academy-workshop-cell-money');
  moneyCell.append(tableRoomCostLine('', moneyText(recipe.money.required), recipe.money.short));

  const outlookCell = tableRoomCell('academy-workshop-cell-outlook');
  outlookCell.dataset.band = String(recipe.outlook.band);
  outlookCell.textContent = recipe.outlook.label;

  button.append(kindCell, elementCell, tierCell, effectsCell, itemsCell, moneyCell, outlookCell);
  // A failed / malformed craft rejects (craftWorkshopRecipe does not swallow it); surface it through the workshop
  // error reporter (LM-config errors are routed to settings by handleRuntimeApiError) and the player STAYS —
  // nothing was consumed, so the same board is still valid for a retry. No silent retry / auto-naming fallback.
  if (recipe.affordable) {
    button.addEventListener('click', () => craftWorkshopRecipe(recipe).catch(reportWorkshopScreenError));
  }
  item.append(button);
  return item;
}

function workshopEffectChip(effect) {
  const chip = document.createElement('span');
  chip.className = 'academy-workshop-effect';
  chip.textContent = `${effect.label}+${effect.value}`;
  return chip;
}

// The in-flight craft indicator: POST /api/workshop/craft rolls the deterministic quality AND has the LLM name the
// item, so the craft can take a visible beat. The workshop is a stay-and-craft screen (no transition to the loading
// screen), so the wait is covered IN SCREEN: the board goes busy (dimmed + non-interactive) under an overlay holding
// the screen wait mark — the wait sigil turns in the bottom-right corner — so the wait reads as intentional crafting,
// not a frozen board. It is built/removed in lockstep with the
// craft (setWorkshopCrafting(false) in the caller's finally), so it never lingers past a resolution.
function buildWorkshopCraftingIndicator() {
  const overlay = document.createElement('div');
  overlay.className = 'academy-workshop-crafting';
  overlay.id = 'academy-workshop-crafting';
  overlay.append(screenWaitMark());
  return overlay;
}

// Toggle the board's in-flight craft busy state: mark the board (data-crafting) so the CSS dims + blocks the recipe
// grid, and float / remove the crafting overlay. A missing board node is broken markup — fail fast.
function setWorkshopCrafting(active) {
  const board = document.querySelector('.academy-workshop-board');
  if (!board) {
    throw new Error('workshop board (.academy-workshop-board) is missing (broken markup wiring)');
  }
  const existing = board.querySelector('#academy-workshop-crafting');
  if (active) {
    board.dataset.crafting = 'true';
    if (!existing) board.append(buildWorkshopCraftingIndicator());
  } else {
    delete board.dataset.crafting;
    if (existing) existing.remove();
  }
}

// Craft the selected recipe: POST /api/workshop/craft { recipe_id } (a single call; the backend rolls the
// deterministic quality, has the LLM name the item, gates it, and atomically commits — no conversation). The
// response is resolved AGAINST the selected recipe (the crafted recipe id + item identity must match — the popup
// reflects what the server actually crafted, not a blindly-trusted stale row; a divergence fail-fasts), the
// authoritative state is adopted, and the result popup floats. A failed craft REJECTS (fail-fast): the throw is
// not swallowed — it propagates to the row click handler's `.catch(reportWorkshopScreenError)` (materials stay
// unconsumed, so the board is still valid). The in-screen crafting busy state covers the wait and is cleared in
// finally regardless of outcome (success → the result popup floats over the board; failure → the error banner shows
// on the status line), so the crafting overlay never lingers past a resolution. workshopCraftInFlight is the
// single-flight guard: a second press hits showProcessingToast so no second craft POST is issued.
async function craftWorkshopRecipe(recipe) {
  if (workshopCraftInFlight) {
    showProcessingToast();
    return;
  }
  workshopCraftInFlight = true;
  try {
    setWorkshopScreenStatus('');
    setWorkshopCrafting(true);
    const response = await postJson('/api/workshop/craft', { recipe_id: recipe.recipe_id });
    const { state, display } = resolveWorkshopCraft(response, recipe);
    // Adopt the authoritative post-craft state (the materials were consumed / the item added server-side).
    currentRuntimeState = state;
    writeDebugLog({ crafted_workshop: recipe.recipe_id, state });
    openWorkshopResultPopup(display);
  } finally {
    workshopCraftInFlight = false;
    setWorkshopCrafting(false);
  }
}

// The result popup floats over the board (the alchemy / dungeon result-popup idiom: an on-screen modal, not a
// screen change) with the crafted item's LLM-authored name + flavor as the 主役, then the confirmed identity
// (種別・属性・tier・出来栄え) and the performance (base + roll-derived bonus effects). The display is the
// resolveWorkshopCraft output — cross-checked against the selection — so nothing is re-derived or blindly reused.
function openWorkshopResultPopup(display) {
  const popup = document.querySelector('#academy-workshop-result-popup');
  const body = document.querySelector('#academy-workshop-result-body');
  if (!popup || !body) {
    throw new Error('workshop result popup markup is missing (broken wiring)');
  }
  const name = document.createElement('h3');
  name.id = 'academy-workshop-result-title';
  name.className = 'academy-workshop-result-name';
  name.textContent = display.name;
  const flavor = document.createElement('p');
  flavor.className = 'academy-workshop-result-flavor';
  flavor.textContent = display.flavor;

  const identity = document.createElement('p');
  identity.className = 'academy-workshop-result-identity';
  const kind = document.createElement('span');
  kind.className = 'academy-workshop-result-kind';
  kind.textContent = workshopKindLabelFull(display);
  const meta = document.createElement('span');
  meta.className = 'academy-workshop-result-meta';
  meta.textContent = `属性${workshopElementLabel(display.element)}・階級T${display.tier}・出来栄え${workshopQualityLabel(display.quality)}`;
  identity.append(kind, meta);

  const effects = document.createElement('div');
  effects.className = 'academy-workshop-result-effects';
  effects.append(workshopResultEffectRow('基礎性能', display.base_effects), workshopResultEffectRow('付加性能', display.bonus_effects));

  body.replaceChildren(name, flavor, identity, effects);
  popup.hidden = false;
}

function workshopResultEffectRow(label, effectList) {
  const row = document.createElement('div');
  row.className = 'academy-workshop-result-effect-row';
  const rowLabel = document.createElement('span');
  rowLabel.className = 'academy-workshop-result-effect-label';
  rowLabel.textContent = label;
  const chips = document.createElement('span');
  chips.className = 'academy-workshop-result-effect-chips';
  // A roll-derived bonus set can be empty (a structurally valid instance); render an honest 「なし」 rather than
  // an empty span, so the 付加性能 row still reads. base_effects is always present, so it never hits this branch.
  if (effectList.length === 0) {
    const none = document.createElement('span');
    none.className = 'academy-workshop-result-effect-none';
    none.textContent = 'なし';
    chips.append(none);
  } else {
    for (const effect of effectList) chips.append(workshopEffectChip(effect));
  }
  row.append(rowLabel, chips);
  return row;
}

function hideWorkshopResultPopup() {
  const popup = document.querySelector('#academy-workshop-result-popup');
  if (popup) popup.hidden = true;
}

// 受け取る: close the result and STAY in the workshop, re-fetching the board (held / affordable changed as the
// materials were consumed). This is NOT a navigation — the workshop is a stay-and-craft screen; leaving is the
// separate 「工房を出る」. The re-fetch preserves the active 種別 filter.
function acknowledgeWorkshopResult() {
  hideWorkshopResultPopup();
  return refreshWorkshopScreen();
}

// 工房を出る: leave the stay-and-craft screen through the server-authoritative post_content_screen held from the
// latest GET /api/workshop (routing-only → the routing hub) via the shared return over the place's art
// (returnToRoutingHubFromPlace — never a bare enterRoutingHub under the still-visible workshop screen, which reads as
// a freeze). A double press is guarded by the shared routingContentReturnInFlight flag so
// it never starts two hub returns. A missing held screen is broken state — fail fast (never a fabricated
// default); the workshop is reachable with zero crafts, so this is the always-available exit even when every
// recipe is unaffordable.
async function exitWorkshop() {
  if (routingContentReturnInFlight) {
    showProcessingToast();
    return;
  }
  const nextScreen = workshopExitScreen;
  if (typeof nextScreen !== 'string' || nextScreen === '') {
    throw new Error('workshop exit: no post_content_screen held (工房の退出先が未取得 — broken arrival flow)');
  }
  routingContentReturnInFlight = true;
  try {
    await returnToRoutingHubFromContent(nextScreen);
  } finally {
    routingContentReturnInFlight = false;
  }
}

document.querySelector('#academy-workshop-result-close').addEventListener('click', () => acknowledgeWorkshopResult().catch(reportWorkshopScreenError));
document.querySelector('#academy-workshop-exit').addEventListener('click', () => exitWorkshop().catch(reportWorkshopScreenError));

// ── 会場（闘技会・競売場・奏楽堂）で分け合う作り ─────────────────────────────────────────────────────────────────────────
// 三つの会場は、催しが段を踏んで進む。画面は会場の絵いっぱいの一枚（地）に固定し、段ごとの面だけがその上で入れ替わる:
// - 地: 会場の絵（hubTerrace.js の destinationArt = 露台の送り出しの幕・入るときの待ちと同じ一枚）を画面いっぱいに敷く。
// - 左上の場所の名・上の中ほどの段の道（催しの段を星で結んだ道）・右上の出る紋（その段で出られるときだけ）。
// - 段の道: 済んだ段の星は塗られ、いまの段の星は大きく灯り、先の段の星は輪郭だけ。失敗したときは、いまの段の星の先で道が途切れ、
//   製品の失敗の紋（ROUTING_FAILURE_GLYPH_SVG の途切れた星の道）と同じ形になり、その右に言い直しの紋が立つ。原因は console にだけ残す。
// - 字の釦はすべて紋（venueSigils.svg の symbol・露台の戻る紋）にし、名は読み上げの名（aria-label）にだけ持つ。
const VENUE_SIGILS_URL = '/venueSigils.svg';
const VENUE_SVG_NS = 'http://www.w3.org/2000/svg';
// 段の道の星（失敗の紋の星の形）と、星どうしの間（viewBox の単位）。
const VENUE_PATH_STAR = 'M5 4.5 6.1 8.9 10.5 10 6.1 11.1 5 15.5 3.9 11.1-.5 10 3.9 8.9z';
const VENUE_PATH_STEP = 46;
const VENUE_PATH_SCALE = 1.6;
// 言い直しの紋の読み上げの名。
const VENUE_RETRY_LABEL = 'もう一度';

// venueSigils.svg の symbol を文書の置き場へ写す（露台の能力の紋と同じ理由: 静的配信の .svg は外から <use> で引けない）。
async function loadVenueSigils() {
  const response = await fetch(VENUE_SIGILS_URL);
  if (!response.ok) throw new Error(`venue sigils: ${VENUE_SIGILS_URL} answered ${response.status}`);
  const sheet = new DOMParser().parseFromString(await response.text(), 'image/svg+xml');
  if (sheet.querySelector('parsererror')) throw new Error(`venue sigils: ${VENUE_SIGILS_URL} is not an SVG`);
  const symbols = sheet.documentElement.querySelectorAll(':scope > symbol[id^="venue-"]');
  if (symbols.length === 0) throw new Error(`venue sigils: ${VENUE_SIGILS_URL} has no venue symbols`);
  const holder = document.querySelector('#venue-sigil-symbols');
  if (!holder) throw new Error('venue sigils: the symbol holder #venue-sigil-symbols is missing');
  holder.replaceChildren(...Array.from(symbols, (symbol) => document.importNode(symbol, true)));
}

// 紋を引く <svg>（<use href="#venue-<名>">）。sigil は symbol の id から venue- を外した名。
function venueSigil(sigil, className = 'venue-sigil-mark') {
  const svg = document.createElementNS(VENUE_SVG_NS, 'svg');
  svg.setAttribute('class', className);
  svg.setAttribute('aria-hidden', 'true');
  svg.setAttribute('focusable', 'false');
  const use = document.createElementNS(VENUE_SVG_NS, 'use');
  use.setAttribute('href', `#venue-${sigil}`);
  svg.append(use);
  return svg;
}

// 釦を会場の紋の釦にする（中身は紋だけ・名は aria-label）。
function dressVenueSigilButton(button, sigil, label) {
  if (typeof label !== 'string' || label.trim() === '') throw new Error(`venue sigil button ${sigil} has no name to read out`);
  button.classList.add('venue-sigil-button');
  button.setAttribute('aria-label', label);
  button.replaceChildren(venueSigil(sigil));
  return button;
}

function venueSigilButton(sigil, label, onClick, className = '') {
  const button = document.createElement('button');
  button.type = 'button';
  if (className) button.className = className;
  dressVenueSigilButton(button, sigil, label);
  button.addEventListener('click', onClick);
  return button;
}

// 会場の地: 行き先の絵を画面の --venue-art に置く（一か所 = destinationArt）。絵を持たない行き先は会場にならない。
function dressVenueGround(screen, destinationId) {
  const art = destinationArt(destinationId);
  if (art === null) throw new Error(`venue ground: the destination ${destinationId} has no art to stand on`);
  screen.style.setProperty('--venue-art', `url('${art}')`);
}

// 段の道を描く。names は段の名（読み上げの名にだけ使う）、current はいまの段の番号（names.length は全部済んだ）、failed は
// いまの段で失敗したか。失敗の道は、いまの段の星から次の星へ向かう道が途切れた形（失敗の紋）で終わり、その先の星は描かない。
function renderVenuePath(node, { names, current, failed = false }) {
  if (!Array.isArray(names) || names.length < 2) throw new Error('venue path: needs at least two stage names');
  if (!Number.isInteger(current) || current < 0 || current > names.length) throw new Error(`venue path: current ${current} is out of the ${names.length} stages`);
  if (failed && current >= names.length) throw new Error('venue path: a finished way cannot fail');
  const x = (index) => 11 + VENUE_PATH_STEP * index;
  // 失敗の道は、途切れた道の向こうに次の星を一つだけ置く（最後の段の失敗なら、道の外に輪郭の星を一つ）。
  const lastStar = failed ? current + 1 : names.length - 1;
  const width = x(lastStar) + 11;
  const parts = [];
  for (let i = 0; i < lastStar; i += 1) {
    const x0 = x(i) + 8;
    const x1 = x(i + 1) - 8;
    if (failed && i === current) {
      const mid = (x0 + x1) / 2;
      parts.push(`<path class="venue-path-road" data-state="broken" d="M${x0} 11H${mid - 3.4}M${mid + 3.4} 11H${x1}" />`);
      parts.push(`<path class="venue-path-break" d="M${mid - 1.6} 8.2 ${mid - 0.6} 10M${mid + 1.6} 12 ${mid + 0.6} 13.8" />`);
    } else {
      parts.push(`<path class="venue-path-road" data-state="${i < current ? 'done' : 'ahead'}" d="M${x0} 11H${x1}" />`);
    }
  }
  for (let i = 0; i <= lastStar; i += 1) {
    const state = failed
      ? (i < current ? 'done' : i === current ? 'failed' : 'ahead')
      : (i < current ? 'done' : i === current ? 'current' : 'ahead');
    const scale = state === 'current' ? 1.5 : 1;
    parts.push(`<path class="venue-path-star" data-state="${state}" transform="translate(${x(i)} 11) scale(${scale}) translate(-5 -10)" d="${VENUE_PATH_STAR}" />`);
  }
  node.innerHTML = `<svg class="venue-path-art" viewBox="0 0 ${width} 22" width="${width * VENUE_PATH_SCALE}" height="${22 * VENUE_PATH_SCALE}" aria-hidden="true" focusable="false">${parts.join('')}</svg>`;
  node.dataset.failed = failed ? 'true' : 'false';
  const where = current >= names.length ? 'すべて済んだ' : failed ? `${names[current]}で途切れた` : `いま ${names[current]}`;
  node.setAttribute('aria-label', `${names.join('・')}（${where}）`);
}

// 言い直しの紋: 失敗した道の右に立つ（retry が null なら下ろす）。押すと一度だけ retry を呼ぶ。
function setVenueRetry(button, retry) {
  button.onclick = null;
  button.hidden = retry === null;
  if (retry === null) return;
  button.onclick = () => {
    button.onclick = null;
    button.hidden = true;
    retry();
  };
}

// 待つあいだの印（工房の orbit dots と同じ三つの点）。名は読み上げの名だけ。
function venueBusyMark(label) {
  const busy = document.createElement('span');
  busy.className = 'venue-busy';
  busy.setAttribute('role', 'status');
  busy.setAttribute('aria-label', label);
  for (let i = 0; i < 3; i += 1) {
    const dot = document.createElement('span');
    dot.className = 'venue-busy-dot';
    busy.append(dot);
  }
  return busy;
}

// 失敗の紋（失敗の紋の SVG そのもの）を、字を持たない印として置く（生成の失敗を受けたその場所）。
function venueFailureMark(label) {
  const mark = document.createElement('span');
  mark.className = 'routing-failure-mark venue-failure-mark';
  mark.setAttribute('role', 'img');
  mark.setAttribute('aria-label', label);
  mark.innerHTML = ROUTING_FAILURE_GLYPH_SVG;
  return mark;
}

// ── Concert hall arrival screen (academy-concert-hall): the routing "奏楽堂" (concert_hall) destination lands here ──
// A routing dispatch to the concert_hall destination navigates to #academy-concert-hall-screen through the existing
// loading interstitial (the mirror ROUTING_DISPATCH_SCREENS maps concert_hall → academy-concert-hall). Like the
// workshop / library it is a STAY screen: the player writes a free-text wish, the 楽師 composes it through the
// staged LM pipeline (S1 材料 → S2 方向 → S3 指南 → S4 骨子 → S5 節ごとの音符) whose stage outputs are read out on the
// 語り面 as the PRE-PERFORMANCE narration while they arrive (in-screen busy, M-2026-07-06-001 stay-screen form),
// the piece is performed by the screen's own Web Audio player (concertHallPlayer.js — its own AudioContext; the
// screen-music controller and the BGM settings are never touched, the screen is a silent BGM screen), and it is
// already in the 収蔵 shelf when the performance ends (the backend commits on S5 success — no 「収蔵する」 button).
// Any shelf row replays its saved score with its saved narration (no LM). Leaving is the explicit 「奏楽堂を出る」
// to the server-authoritative post_content_screen (a performance still sounding is stopped first).
//
// The board is driven by the closed 9-state machine of concertHallClient.js (到着 / 入力中 / 作曲中 / 演奏前の語り /
// 演奏中 / 演奏後 / 棚 / 再演 / LM エラー); every DOM change below is a function of that state, and every payload,
// stream event and piece is validated by the same module BEFORE any DOM mutation (no inline re-implementation).
//
// It stands on the venue (会場で分け合う作り): the hall's art by day fills the screen, the way of its stages (願い・語り・
// 演奏・棚) runs across the top, and the faces change over it — the shelf with the 楽師's greeting, the narration coming
// down line by line in front of the curtain between the piano and the harp (each stage's name is its sigil), the
// performance with the piece's head and the lit section. The wish stays in the writing line at the bottom.
const CONCERT_HALL_SAMPLE_BASE_URL = '/canonical/concert_hall/';
const CONCERT_HALL_BUSY_LABEL = '楽師が譜を書いている';
const CONCERT_HALL_WRITTEN_LABEL = '譜が書けた';
// 段の道（願い・語り・演奏・棚）と、状態ごとのいまの段。
const CONCERT_HALL_WAY = ['願い', '語り', '演奏', '棚'];
const CONCERT_HALL_WAY_STAGE = Object.freeze({ arrived: 0, typing: 0, composing: 1, narrated: 1, error: 1, playing: 2, replaying: 2, played: 3, shelf: 3 });
// 語りの段の名の紋（venueSigils.svg）。段の名は紋の読み上げの名だけ。
const CONCERT_HALL_STAGE_SIGILS = Object.freeze({ materials: 'materials', direction: 'direction', guidance: 'guidance', skeleton: 'skeleton' });

// The ONE player of the screen. Its AudioContext is created lazily inside the first 「演奏を始める」 click (autoplay
// policy satisfied by this player alone); an environment without Web Audio fails fast there, never silently.
const concertHallPlayer = createConcertHallPlayer({
  fetchImpl: (url) => fetch(url),
  audioContextFactory: () => {
    const AudioContextCtor = window.AudioContext;
    if (!AudioContextCtor) throw new Error('concert hall player: this runtime has no Web Audio (AudioContext)');
    return new AudioContextCtor();
  },
  sampleBaseUrl: CONCERT_HALL_SAMPLE_BASE_URL
});

// The screen's state: the machine, the validated arrival (performer lines + shelf), the server-authoritative exit,
// the in-progress compose draft (its text, the narration filled so far, the failed stage) and the piece on stage.
let concertHallMachine = createConcertHallStateMachine();
let concertHallArrival = null;
let concertHallExitScreen = null;
let concertHallDraft = null;
let concertHallStagePiece = null;
// The entry highlighted on the 棚面 after a performance (演奏後: the piece just composed, on top).
let concertHallHighlightEntryId = null;
// Single-flight guards: one compose stream, one perform / replay start at a time.
let concertHallComposeInFlight = false;
let concertHallStartInFlight = false;
// 段の道が途切れているか（失敗の紋と言い直しの紋が立っている間）。
let concertHallWayFailed = false;
// 指南を開いているか（題の三語を押すと全文が開く。新しい語りでは畳んだ姿から始まる）。
let concertHallGuidanceOpen = false;

function concertHallNode(selector) {
  const node = document.querySelector(selector);
  if (!node) throw new Error(`concert hall screen node (${selector}) is missing (broken markup wiring)`);
  return node;
}

const concertHallScreen = concertHallNode('#academy-concert-hall-screen');
dressVenueGround(concertHallScreen, 'concert_hall');
dressSigilButton(concertHallNode('#academy-concert-hall-exit'), 'back', '奏楽堂を出る');
dressVenueSigilButton(concertHallNode('#academy-concert-hall-retry'), 'retry', VENUE_RETRY_LABEL);
dressVenueSigilButton(concertHallNode('#academy-concert-hall-compose'), 'compose', '奏でてもらう');
dressVenueSigilButton(concertHallNode('#academy-concert-hall-perform'), 'play', '演奏を始める');
dressVenueSigilButton(concertHallNode('#academy-concert-hall-stop'), 'stop', '止める');

function renderConcertHallWay() {
  renderVenuePath(concertHallNode('#academy-concert-hall-path'), {
    names: CONCERT_HALL_WAY,
    current: CONCERT_HALL_WAY_STAGE[concertHallMachine.state],
    failed: concertHallWayFailed
  });
}

// 奏楽堂の失敗: いまの段の星の先で道が途切れ、言い直しの紋が立つ。retry は失敗した手をもう一度行う（無ければ紋は立たない）。
// 原因は console にだけ残す。
function reportConcertHallScreenError(error, retry = null) {
  console.error(error);
  concertHallWayFailed = true;
  renderConcertHallWay();
  setVenueRetry(concertHallNode('#academy-concert-hall-retry'), retry === null ? null : () => {
    clearConcertHallWayFailure();
    retry();
  });
}

// 到着の読み込みの言い直し（開発用の入口・読み直しで着いたとき。行き先から着いた失敗は露台へ戻る）。
function retryConcertHallArrival() {
  refreshConcertHallScreen().catch((error) => reportConcertHallScreenError(error, retryConcertHallArrival));
}

function clearConcertHallWayFailure() {
  concertHallWayFailed = false;
  setVenueRetry(concertHallNode('#academy-concert-hall-retry'), null);
  renderConcertHallWay();
}

// Fetch the arrival envelope and land the 棚面 in the 到着 state. The machine is rebuilt (a fresh visit starts at
// 到着), any performance is stopped, and the whole payload is validated before any DOM mutation.
async function refreshConcertHallScreen() {
  concertHallPlayer.stop();
  concertHallMachine = createConcertHallStateMachine();
  concertHallDraft = null;
  concertHallStagePiece = null;
  concertHallHighlightEntryId = null;
  clearConcertHallWayFailure();
  concertHallNode('#academy-concert-hall-input').value = '';
  concertHallNode('#academy-concert-hall-shelf').replaceChildren();
  const payload = await getJson('/api/concert-hall');
  renderConcertHallArrival(payload);
}

function renderConcertHallArrival(payload) {
  const arrival = validateConcertHallArrivalPayload(payload);
  concertHallArrival = arrival;
  concertHallExitScreen = arrival.postContentScreen;
  concertHallNode('#academy-concert-hall-greeting').textContent = arrival.performer.greeting;
  renderConcertHallShelf();
  setConcertHallFace('shelf');
  syncConcertHallControls();
}

// The shelf: newest first, one row button per piece with its 題 and 方向; the 演奏後 highlight marks the piece just
// composed. Zero pieces shows the 楽師's empty-shelf line instead of an empty list.
function renderConcertHallShelf() {
  const list = concertHallNode('#academy-concert-hall-shelf');
  const empty = concertHallNode('#academy-concert-hall-shelf-empty');
  const pieces = concertHallShelfOrder(concertHallArrival.pieces);
  list.replaceChildren(...pieces.map((piece) => buildConcertHallShelfRow(piece)));
  list.hidden = pieces.length === 0;
  empty.hidden = pieces.length > 0;
  empty.textContent = pieces.length === 0 ? concertHallArrival.performer.empty_shelf : '';
}

function buildConcertHallShelfRow(piece) {
  const item = document.createElement('li');
  item.className = 'academy-concert-hall-shelf-row';
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'academy-concert-hall-shelf-button';
  button.dataset.entryId = piece.entry_id;
  if (piece.entry_id === concertHallHighlightEntryId) button.dataset.highlight = 'true';
  const mark = venueSigil('written', 'academy-concert-hall-shelf-mark');
  const title = document.createElement('span');
  title.className = 'academy-concert-hall-shelf-title';
  title.textContent = piece.title;
  const direction = document.createElement('span');
  direction.className = 'academy-concert-hall-shelf-direction';
  direction.textContent = piece.direction_label;
  button.append(mark, title, direction);
  const replay = () => replayConcertHallPiece(piece.entry_id, button).catch((error) => reportConcertHallScreenError(error, replay));
  button.addEventListener('click', replay);
  item.append(button);
  return item;
}

// The three faces of the board: exactly one is visible; the board's data-face mirrors it for the CSS / harness.
function setConcertHallFace(face) {
  const faces = { shelf: '#academy-concert-hall-shelf-face', narration: '#academy-concert-hall-narrative-face', performance: '#academy-concert-hall-performance-face' };
  if (!Object.hasOwn(faces, face)) throw new Error(`concert hall face is not one of shelf / narration / performance: ${face}`);
  for (const [name, selector] of Object.entries(faces)) concertHallNode(selector).hidden = name !== face;
  concertHallNode('.academy-concert-hall-board').dataset.face = face;
}

// The writing line follows the state: the input is dead while composing / performing, 「奏でてもらう」 needs text and a
// state that accepts a new wish, the exit is always live. The way of the stages follows the state too.
function syncConcertHallControls() {
  const state = concertHallMachine.state;
  const input = concertHallNode('#academy-concert-hall-input');
  const compose = concertHallNode('#academy-concert-hall-compose');
  input.disabled = state === 'composing' || state === 'playing' || state === 'replaying';
  compose.disabled = input.disabled || state === 'arrived' || input.value.trim() === '';
  concertHallScreen.dataset.state = state;
  renderConcertHallWay();
}

// Typing moves 到着 ⇄ 入力中 (and drops the 演奏後 / 棚 face back to 入力中); in 演奏前 / エラー the text simply
// arms 「奏でてもらう」 for another piece (the 語り面 stays).
function onConcertHallInput() {
  const text = concertHallNode('#academy-concert-hall-input').value.trim();
  const state = concertHallMachine.state;
  if (text !== '' && (state === 'arrived' || state === 'played' || state === 'shelf')) {
    concertHallMachine.transition('typing');
    if (state !== 'arrived') {
      concertHallHighlightEntryId = null;
      renderConcertHallShelf();
    }
  } else if (text === '' && state === 'typing') {
    concertHallMachine.transition('arrived');
  }
  syncConcertHallControls();
}

// ── compose (POST /api/concert-hall/compose as SSE) ──

// 「奏でてもらう」: 入力中 / 演奏前 / エラー → 作曲中 with a fresh draft for the typed wish; the retry sigil re-runs the
// failed draft's text. The narration fills as the events arrive; `done` lands 演奏前 with the play sigil, `error` lands
// LM エラー with the way broken at 語り.
async function composeConcertHallPiece({ retry = false } = {}) {
  if (concertHallComposeInFlight) {
    showProcessingToast();
    return;
  }
  const text = retry ? concertHallDraft.text : concertHallNode('#academy-concert-hall-input').value.trim();
  if (text === '') throw new Error('concert hall compose: the wish text is empty');
  // A wish typed before a replay is still in the input on the 棚面 (演奏後 / 棚): it is 入力中 by the board's
  // definition, so the machine passes through it on the way to 作曲中.
  if (concertHallMachine.state === 'played' || concertHallMachine.state === 'shelf') concertHallMachine.transition('typing');
  concertHallMachine.transition('composing', { stage: 'materials' });
  concertHallDraft = { text, narration: {}, sections: [], written: new Set(), error: null };
  concertHallStagePiece = null;
  concertHallHighlightEntryId = null;
  concertHallGuidanceOpen = false;
  clearConcertHallWayFailure();
  concertHallNode('#academy-concert-hall-perform').hidden = true;
  setConcertHallFace('narration');
  renderConcertHallNarrationCards();
  syncConcertHallControls();
  concertHallComposeInFlight = true;
  try {
    await readConcertHallComposeStream(text);
  } catch (error) {
    // A stream that could not be opened (LM unconfigured → 503 before the stream, transport) or a malformed event:
    // the same LM エラー face, the way broken at 語り.
    landConcertHallError({ stage: concertHallMachine.stage });
    console.error(error);
  } finally {
    concertHallComposeInFlight = false;
  }
}

async function readConcertHallComposeStream(text) {
  const endpoint = '/api/concert-hall/compose';
  const response = await fetch(endpoint, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ free_text: text })
  });
  if (!response.ok) {
    const bodyText = await response.text();
    throw createApiError({ url: endpoint, status: response.status, payload: parseJsonText(bodyText), fallbackText: bodyText });
  }
  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = '';
  let closed = false;
  const handleBlock = async (block) => {
    const { event, data } = parseConcertHallSseBlock(block);
    if (event === 'stage') {
      applyConcertHallStageEvent(validateConcertHallStageEvent(data));
    } else if (event === 'done') {
      closed = true;
      await landConcertHallDone(validateConcertHallDoneEvent(data));
    } else {
      closed = true;
      const failure = validateConcertHallErrorEvent(data);
      console.error(`concert hall compose failed at ${failure.stage}: ${failure.message}`);
      landConcertHallError(failure);
    }
  };
  while (true) {
    const { value, done } = await reader.read();
    buffer += decoder.decode(value ?? new Uint8Array(), { stream: !done });
    const blocks = buffer.split('\n\n');
    buffer = blocks.pop() ?? '';
    for (const block of blocks) if (block.trim()) await handleBlock(block);
    if (done) break;
  }
  if (buffer.trim()) await handleBlock(buffer);
  if (!closed) throw new Error('concert hall compose stream ended without done / error');
}

// A validated stage event: the finished stage's narration goes on its line, the next stage becomes the busy one
// (S3 guidance is machine-resolved and arrives with S2, S4 brings the section rows, each S5 marks its section).
function applyConcertHallStageEvent({ stage, index, payload, narration }) {
  if (stage === 'section') {
    concertHallDraft.written.add(index);
    concertHallMachine.setStage('section');
  } else {
    concertHallDraft.narration[stage] = narration;
    if (stage === 'skeleton') {
      concertHallDraft.sections = payload.sections.map((section) => ({ name: section.name, character: section.character }));
    }
    const next = { materials: 'direction', direction: 'guidance', guidance: 'skeleton', skeleton: 'section' }[stage];
    concertHallMachine.setStage(next);
  }
  renderConcertHallNarrationCards();
}

// `done`: the piece is committed server-side; the shelf is refreshed from the arrival GET (LM-free) so 演奏後 can
// show it on top, and the 語り面 lands 演奏前 with the play sigil lit on the stage floor.
async function landConcertHallDone({ piece }) {
  concertHallStagePiece = piece;
  concertHallMachine.transition('narrated');
  const arrival = validateConcertHallArrivalPayload(await getJson('/api/concert-hall'));
  concertHallArrival = arrival;
  concertHallExitScreen = arrival.postContentScreen;
  renderConcertHallNarrationCards();
  concertHallNode('#academy-concert-hall-perform').hidden = false;
  syncConcertHallControls();
}

// `error` (or a stream that failed to open): LM エラー — the finished narration stays, the way breaks at 語り and the
// retry sigil re-runs the same wish.
function landConcertHallError({ stage }) {
  const failedStage = stage ?? concertHallMachine.stage ?? 'materials';
  concertHallMachine.transition('error');
  concertHallDraft.error = { stage: failedStage };
  renderConcertHallNarrationCards();
  syncConcertHallControls();
  reportConcertHallScreenError(new Error(`concert hall compose failed at ${failedStage}`), () => {
    composeConcertHallPiece({ retry: true }).catch((error) => reportConcertHallScreenError(error));
  });
}

// ── the 語り (narration) lines ──

// Builds the narration from a view: { narration: {materials, direction, guidance, skeleton}, sections: [{name,
// character}], written: Set<index>, busyStage, error: {stage} | null, currentSection }. The stages come down one line
// each in CONCERT_HALL_STAGE_CARDS order, only once they have arrived (the running one shows the busy mark); the
// stage's name is its sigil. The guidance folds to its titles (pressing them opens the full lines); the skeleton is
// the row of sections (name · character · the 譜が書けた paper once its notes are written).
function buildConcertHallCards(view) {
  const lines = document.createElement('ol');
  lines.className = 'academy-concert-hall-stage-cards';
  for (const { stage, title } of CONCERT_HALL_STAGE_CARDS) {
    const arrived = view.narration[stage] ?? null;
    const busy = view.busyStage === stage || (stage === 'skeleton' && view.busyStage === 'section' && view.sections.length === 0);
    const failed = view.error?.stage === stage;
    if (arrived === null && !busy && !failed) continue;
    const card = document.createElement('li');
    card.className = 'academy-concert-hall-card';
    card.dataset.stage = stage;
    if (busy) card.dataset.busy = 'true';
    if (failed) card.dataset.error = 'true';
    const mark = document.createElement('span');
    mark.className = 'academy-concert-hall-card-title';
    mark.setAttribute('role', 'img');
    mark.setAttribute('aria-label', title);
    mark.append(venueSigil(CONCERT_HALL_STAGE_SIGILS[stage], 'academy-concert-hall-card-mark'));
    card.append(mark);
    const body = document.createElement('div');
    body.className = 'academy-concert-hall-card-body';
    if (arrived !== null) {
      if (stage === 'guidance') body.append(...buildConcertHallGuidance(arrived));
      else if (stage === 'skeleton') body.append(...buildConcertHallSections(view));
      else for (const line of arrived) body.append(concertHallLine(line));
    }
    if (busy) body.append(venueBusyMark(CONCERT_HALL_BUSY_LABEL));
    card.append(body);
    lines.append(card);
  }
  return [lines];
}

function concertHallLine(text) {
  const line = document.createElement('p');
  line.className = 'academy-concert-hall-card-text';
  line.textContent = text;
  return line;
}

// 指南: 題の三語だけを見せて畳む（押すと全文が開き、もう一度押すと畳む）。
function buildConcertHallGuidance(guidanceLines) {
  const titles = guidanceLines.map((line) => concertHallGuidanceTitle(line));
  const fold = document.createElement('button');
  fold.type = 'button';
  fold.className = 'academy-concert-hall-guidance';
  fold.setAttribute('aria-expanded', concertHallGuidanceOpen ? 'true' : 'false');
  for (const title of titles) {
    const tag = document.createElement('span');
    tag.className = 'academy-concert-hall-guidance-tag';
    tag.textContent = title;
    fold.append(tag);
  }
  fold.addEventListener('click', () => {
    concertHallGuidanceOpen = !concertHallGuidanceOpen;
    if (concertHallMachine.state === 'playing' || concertHallMachine.state === 'replaying') renderConcertHallPerformanceCards(concertHallStagePiece, concertHallPerformanceSection);
    else renderConcertHallNarrationCards();
  });
  const nodes = [fold];
  if (concertHallGuidanceOpen) for (const line of guidanceLines) nodes.push(concertHallLine(line));
  return nodes;
}

// 骨子 = 節の並び: 節の名・一行・譜が書けた印（譜の紙）。書いている節には待ちの印、演奏中はいまの節が灯る。
function buildConcertHallSections(view) {
  return view.sections.map((section, index) => {
    const row = document.createElement('div');
    row.className = 'academy-concert-hall-section';
    row.dataset.sectionIndex = String(index);
    if (view.currentSection === index) row.dataset.current = 'true';
    const name = document.createElement('span');
    name.className = 'academy-concert-hall-section-title';
    name.textContent = section.name;
    const line = document.createElement('span');
    line.className = 'academy-concert-hall-section-line';
    line.textContent = section.character;
    row.append(name, line);
    if (view.written.has(index)) {
      const written = document.createElement('span');
      written.className = 'academy-concert-hall-written';
      written.setAttribute('role', 'img');
      written.setAttribute('aria-label', CONCERT_HALL_WRITTEN_LABEL);
      written.append(venueSigil('written', 'academy-concert-hall-written-mark'));
      row.append(written);
    } else if (view.busyStage === 'section' && index === view.written.size) {
      row.append(venueBusyMark(CONCERT_HALL_BUSY_LABEL));
    }
    return row;
  });
}

function concertHallDraftView() {
  const composing = concertHallMachine.state === 'composing';
  return {
    narration: concertHallDraft.narration,
    sections: concertHallDraft.sections,
    written: concertHallDraft.written,
    busyStage: composing ? concertHallMachine.stage : null,
    error: concertHallDraft.error,
    currentSection: null
  };
}

function renderConcertHallNarrationCards() {
  concertHallNode('#academy-concert-hall-narration-cards').replaceChildren(...buildConcertHallCards(concertHallDraftView()));
}

// The 演奏面's narration from a piece's SAVED narration (the same lines; the current section is lit).
function concertHallPieceView(piece, currentSection) {
  return {
    narration: {
      materials: [piece.narration.materials],
      direction: [piece.narration.direction],
      guidance: piece.narration.guidance,
      skeleton: piece.narration.skeleton
    },
    sections: piece.score.sections.map((section) => ({ name: section.name, character: section.character })),
    written: new Set(piece.score.sections.map((_section, index) => index)),
    busyStage: null,
    error: null,
    currentSection
  };
}

// The section the performance is in (for re-rendering the 演奏面 when the guidance is opened / folded).
let concertHallPerformanceSection = null;

function renderConcertHallPerformanceCards(piece, currentSection) {
  concertHallPerformanceSection = currentSection;
  concertHallNode('#academy-concert-hall-performance-cards').replaceChildren(...buildConcertHallCards(concertHallPieceView(piece, currentSection)));
}

// ── performance (the screen's own player) ──

function renderConcertHallHead(piece, progress) {
  concertHallNode('#academy-concert-hall-head-title').textContent = piece.title;
  concertHallNode('#academy-concert-hall-head-meta').textContent = concertHallScoreHeadline(piece.score);
  const percent = Math.max(0, Math.min(100, Math.round(progress * 100)));
  concertHallNode('#academy-concert-hall-progress-bar').style.width = `${percent}%`;
  concertHallNode('.academy-concert-hall-progress').setAttribute('aria-valuenow', String(percent));
}

// Load the piece's samples (all awaited — a missing sample throws before anything sounds) and start the player;
// the 演奏面 head follows the progress clock and the lit section follows the score. `onEnded` lands the after-state
// given by the caller.
async function startConcertHallPerformance(piece, { onEnded }) {
  await concertHallPlayer.load(piece.score);
  renderConcertHallPerformanceCards(piece, null);
  await concertHallPlayer.play({
    onSection: ({ index }) => {
      renderConcertHallPerformanceCards(piece, index);
    },
    onProgress: ({ beat, totalBeats }) => {
      const percent = Math.max(0, Math.min(100, Math.round(beat / totalBeats * 100)));
      concertHallNode('#academy-concert-hall-progress-bar').style.width = `${percent}%`;
      concertHallNode('.academy-concert-hall-progress').setAttribute('aria-valuenow', String(percent));
    },
    onEnded: () => {
      try {
        onEnded();
      } catch (error) {
        reportConcertHallScreenError(error);
      }
    }
  });
}

// 「演奏を始める」: 演奏前 → 演奏中 (the samples load under the play sigil first, so a load failure stays on the 語り面 with
// the sigil live). The performance's end (or 「止める」) lands 演奏後: the 棚面 with the new piece on top, highlighted.
async function performConcertHallPiece() {
  if (concertHallStartInFlight) {
    showProcessingToast();
    return;
  }
  const piece = concertHallStagePiece;
  if (!piece) throw new Error('concert hall perform: no composed piece on stage');
  const cta = concertHallNode('#academy-concert-hall-perform');
  concertHallStartInFlight = true;
  cta.disabled = true;
  try {
    renderConcertHallHead(piece, 0);
    await startConcertHallPerformance(piece, { onEnded: () => landConcertHallPlayed() });
    concertHallMachine.transition('playing');
    cta.hidden = true;
    setConcertHallFace('performance');
    syncConcertHallControls();
  } finally {
    cta.disabled = false;
    concertHallStartInFlight = false;
  }
}

function landConcertHallPlayed() {
  concertHallMachine.transition('played');
  concertHallHighlightEntryId = concertHallStagePiece.entry_id;
  concertHallNode('#academy-concert-hall-input').value = '';
  renderConcertHallShelf();
  setConcertHallFace('shelf');
  syncConcertHallControls();
}

// A shelf row: 到着 / 入力中 / 演奏後 / 棚 → 再演 with the saved narration and score (GET /api/concert-hall/pieces/<id>,
// no LM). The row is marked loading while the piece and its samples arrive; a failure leaves the state where it
// was and breaks the way (the retry sigil plays the row again). The replay's end (or 「止める」) lands 棚.
async function replayConcertHallPiece(entryId, row) {
  if (concertHallStartInFlight) {
    showProcessingToast();
    return;
  }
  const state = concertHallMachine.state;
  if (!['arrived', 'typing', 'played', 'shelf'].includes(state)) throw new Error(`concert hall replay is not available while ${state}`);
  concertHallStartInFlight = true;
  row.dataset.loading = 'true';
  try {
    const piece = validateConcertHallPiece(await getJson(`/api/concert-hall/pieces/${encodeURIComponent(entryId)}`));
    concertHallStagePiece = piece;
    concertHallGuidanceOpen = false;
    renderConcertHallHead(piece, 0);
    await startConcertHallPerformance(piece, { onEnded: () => landConcertHallShelf() });
    concertHallMachine.transition('replaying');
    concertHallHighlightEntryId = null;
    setConcertHallFace('performance');
    syncConcertHallControls();
  } finally {
    delete row.dataset.loading;
    concertHallStartInFlight = false;
  }
}

function landConcertHallShelf() {
  concertHallMachine.transition('shelf');
  renderConcertHallShelf();
  setConcertHallFace('shelf');
  syncConcertHallControls();
}

// 「止める」: the sound stops now and the after-state is the same as a natural end (演奏後 / 棚).
function stopConcertHallPerformance() {
  const state = concertHallMachine.state;
  if (state !== 'playing' && state !== 'replaying') return;
  concertHallPlayer.stop();
  if (state === 'playing') landConcertHallPlayed();
  else landConcertHallShelf();
}

// 「奏楽堂を出る」: stop any performance first, then the shared routing content return to the held
// server-authoritative post_content_screen (never a frontend default).
async function exitConcertHall() {
  if (routingContentReturnInFlight) {
    showProcessingToast();
    return;
  }
  const nextScreen = concertHallExitScreen;
  if (typeof nextScreen !== 'string' || nextScreen === '') {
    throw new Error('concert hall exit: no post_content_screen held (奏楽堂の退出先が未取得 — broken arrival flow)');
  }
  concertHallPlayer.stop();
  routingContentReturnInFlight = true;
  try {
    await returnToRoutingHubFromContent(nextScreen);
  } finally {
    routingContentReturnInFlight = false;
  }
}

concertHallNode('#academy-concert-hall-input').addEventListener('input', () => {
  try {
    onConcertHallInput();
  } catch (error) {
    reportConcertHallScreenError(error);
  }
});
concertHallNode('#academy-concert-hall-compose').addEventListener('click', () => composeConcertHallPiece().catch((error) => reportConcertHallScreenError(error)));
const performConcertHallFromSigil = () => performConcertHallPiece().catch((error) => reportConcertHallScreenError(error, performConcertHallFromSigil));
concertHallNode('#academy-concert-hall-perform').addEventListener('click', performConcertHallFromSigil);
concertHallNode('#academy-concert-hall-stop').addEventListener('click', () => {
  try {
    stopConcertHallPerformance();
  } catch (error) {
    reportConcertHallScreenError(error);
  }
});
const exitConcertHallFromSigil = () => exitConcertHall().catch((error) => reportConcertHallScreenError(error, exitConcertHallFromSigil));
concertHallNode('#academy-concert-hall-exit').addEventListener('click', exitConcertHallFromSigil);

// ── Great Library arrival screen (academy-library): the routing "大書庫" (library) destination lands here ────────
// A routing dispatch to the library destination navigates to #academy-library-screen through the existing loading
// interstitial (performRoutingTurnDispatch / navigateToPostContentScreen consume the dispatch, the mirror
// ROUTING_DISPATCH_SCREENS maps library → academy-library). The scene itself — the 請求票 on the desk, the lamp that
// searches the aisle, the books standing in the painted bays, the 見開き with page turns and footnotes, the 蔵書票, the lamps
// going out — is owned by libraryScreen.js. This file keeps only the destination wiring around it: the arrival GET
// (and the server-authoritative exit it carries), the exit to the hub over the place's art, the LM-config / connection
// redirect to the settings screen, and the single-flight guard on the body read. Reading commits the fragment to the
// 収蔵庫 server-side (no parameter/affinity effect), so any number of books can be read in one visit.

// The server-authoritative exit screen from the latest GET /api/library, held so 「書庫を出る」 can navigate onward.
// Never a fabricated default — set only from a validated arrival payload.
let libraryExitScreen = null;
// The routing arrival of the library entry in progress ({ destinationLabel } when a routing hub dispatch landed on it,
// null otherwise; set by showScreen): a failed arrival fetch then returns to the hub rather than leaving the scene
// stopped on its 請求票 line.
let libraryArrivalFromRouting = null;
// Single-flight guard on POST /api/library/read: the scene never asks for two bodies at once, so a second read while
// one is in flight is broken wiring (fail fast rather than racing two 収蔵 commits).
let libraryReadInFlight = false;

function validateLibraryArrivalPayload(payload) {
  if (!payload || typeof payload !== 'object') throw new Error('library arrival: malformed payload');
  const week = payload.week;
  if (!Number.isInteger(week) || week < 0) throw new Error(`library arrival: invalid week ${JSON.stringify(week)}`);
  const postContentScreen = payload.post_content_screen;
  if (typeof postContentScreen !== 'string' || postContentScreen === '') {
    throw new Error('library arrival: missing post_content_screen (server-authoritative exit)');
  }
  return { week, postContentScreen };
}

function libraryString(value, label) {
  if (typeof value !== 'string' || value.trim() === '') throw new Error(`library: missing ${label}`);
  return value;
}

// The read-result validator the ハブ収蔵庫's 関連する本 move uses (the 大書庫 scene validates its own reads).
function validateLibraryReadResult(response) {
  if (!response || typeof response !== 'object') throw new Error('library read: malformed response');
  return {
    title: libraryString(response.title, 'read title'),
    category: libraryString(response.category, 'read category'),
    layer: libraryString(response.layer, 'read layer'),
    text: libraryString(response.text, 'read text'),
    collectionEntryId: libraryString(response.collection_entry_id, 'read collection_entry_id')
  };
}

async function loadLibraryArrival() {
  libraryExitScreen = null;
  try {
    const { postContentScreen } = validateLibraryArrivalPayload(await getJson('/api/library'));
    libraryExitScreen = postContentScreen;
  } catch (error) {
    // The scene redirects an LM config/connection failure itself (redirectRuntimeError); any other failure on the hub
    // dispatch's arrival returns to the hub.
    if (libraryArrivalFromRouting && settingsRedirectErrorMessage(error) == null) returnToRoutingHubAfterArrivalFailure(error, libraryArrivalFromRouting);
    throw error;
  }
}

async function readLibraryBook(target) {
  if (libraryReadInFlight) throw new Error('library read: a body read is already in flight (the scene must not ask twice)');
  libraryReadInFlight = true;
  try {
    return await postJson('/api/library/read', target);
  } finally {
    libraryReadInFlight = false;
  }
}

// 書庫を出る: leave the stay screen through the server-authoritative post_content_screen held from the latest GET
// /api/library (routing-only → the routing hub) via the shared return over the place's art
// (returnToRoutingHubFromPlace). A double press is guarded by the shared routingContentReturnInFlight flag. A missing
// held screen is broken state — fail fast (never a fabricated default).
async function exitLibrary() {
  if (routingContentReturnInFlight) {
    showProcessingToast();
    return;
  }
  const nextScreen = libraryExitScreen;
  if (typeof nextScreen !== 'string' || nextScreen === '') {
    throw new Error('library exit: no post_content_screen held (書庫の退出先が未取得 — broken arrival flow)');
  }
  routingContentReturnInFlight = true;
  try {
    await returnToRoutingHubFromContent(nextScreen);
  } finally {
    routingContentReturnInFlight = false;
  }
}

const libraryScreen = createLibraryScreen({
  loadArrival: loadLibraryArrival,
  search: (theme) => postJson('/api/library/search', { theme }),
  read: readLibraryBook,
  footnotes: (entryId) => postJson(LIBRARY_FOOTNOTES_REQUEST_PATH, { entry_id: entryId }),
  redirectRuntimeError: (error) => handleRuntimeApiError(error, { allowSettingsRedirect: true }),
  leave: exitLibrary,
  waitMark: () => screenWaitMark()
});

// ── 錬成室 arrival screen (academy-atelier): the routing "homunculus" (錬成室) destination lands here ──
// A routing dispatch to the homunculus destination navigates to #academy-atelier-screen through the existing
// loading interstitial (the mirror ROUTING_DISPATCH_SCREENS maps homunculus → academy-atelier). Like the workshop /
// library it is a STAY screen: showScreen fetches GET /api/atelier and renders the 3 slots (ホムンクルス) / 銘棚 / cost /
// conversation-spent state, and the player stays here across synthesis / farewell / a first conversation, leaving
// only through the server-authoritative post_content_screen (錬成室を出る). Synthesis and farewell are both LLM-backed:
// synthesis waits on the room itself (the forge fills the vessel with light until the response — startAtelierForge),
// farewell is covered by the shared academy loading screen (M-2026-07-06-001); the first conversation enters the
// daytime screen as a pre-started atelier conversation (POST /api/atelier/conversation/start, NOT
// /api/interaction/start). The response-shape validators live in the headless-testable atelierArrivalClient.js.

// Single-flight guard for the two LLM-backed atelier actions (synthesize / farewell). A second press before the
// flag clears hits showProcessingToast.
let atelierActionInFlight = false;
// The latest validated arrival view (slots / 銘棚 / material picker / max_active / conversation_spent), read by the
// synthesis form and the slot conversation buttons so the frontend never re-derives max_active or the material total.
let atelierArrivalView = null;
// The synthesis params pending the blind-confirm dialog's 確定 (mode + name + skeleton + materials), and the
// homunculus id pending the one-way farewell-confirm dialog's お別れ. Held between the dialog open and its accept button.
let atelierPendingSynthesis = null;
let atelierPendingFarewellId = null;
// The synthesis material picker's current selection ({ item_id: quantity }). Reset when the form opens; mutated by the
// per-material steppers. atelierSelectionTotal / isAtelierSelectionComplete (atelierArrivalClient.js) read it.
let atelierMaterialSelection = {};

function atelierNode(id) {
  const node = document.querySelector(id);
  if (!node) throw new Error(`atelier screen node ${id} is missing (broken markup wiring)`);
  return node;
}

function setAtelierScreenStatus(message, { tone = null } = {}) {
  const status = atelierNode('#academy-atelier-status');
  const text = String(message ?? '').trim();
  if (!text) {
    status.hidden = true;
    status.textContent = '';
    delete status.dataset.tone;
    return;
  }
  status.hidden = false;
  status.textContent = text;
  if (tone) status.dataset.tone = tone;
  else delete status.dataset.tone;
}

// A failed atelier request shows the failure glyph beside the place name (the status line sits there); the place
// name already names the destination, so the notice does not repeat it. The English cause stays on the console.
function showAtelierFailureNotice() {
  writeRoutingFailureNotice(atelierNode('#academy-atelier-status'), {});
}

function reportAtelierScreenError(error) {
  if (handleRuntimeApiError(error, { allowSettingsRedirect: true })) return;
  showAtelierFailureNotice();
  console.error(error);
}

// Enter the room afresh: any standing forge and any dialog are cleared first so a re-entry never re-opens a stale form,
// then the arrival is fetched and rendered. A failed fetch throws (surfaces on the status line).
async function refreshAtelierScreen() {
  dismissAtelierForge();
  setAtelierScreenStatus('');
  closeAtelierSynthesisForm();
  closeAtelierSynthesisConfirm();
  closeAtelierSynthesisResult();
  closeAtelierFarewellConfirm();
  await loadAtelierArrival();
}

// Fetch the arrival envelope and render the slots / 銘棚 / cost / synthesize availability.
async function loadAtelierArrival() {
  const payload = await getJson('/api/atelier');
  const view = validateAtelierArrivalPayload(payload);
  atelierArrivalView = view;
  atelierExitScreen = view.postContentScreen;
  renderAtelierSlots(view);
  renderAtelierNameplates(view.nameplates);
  updateAtelierSynthesizeOpen(view);
}

// Render the fixed max_active slot row: each active child's face / name / 在り週 / 好感度, its 11 parameters (the
// terrace ability sigils over a thin meter and the value) and the 会いに行く / お別れ sigil buttons, and the empty-person
// picture (read out 「空き」) for each free slot. The 会いに行く action is disabled when this visit's one conversation is
// spent (its title says so, never silently hidden).
function renderAtelierSlots(view) {
  const list = atelierNode('#academy-atelier-slots');
  list.replaceChildren();
  for (let index = 0; index < view.maxActive; index += 1) {
    const entry = view.active[index];
    const item = document.createElement('li');
    if (!entry) {
      item.className = 'academy-atelier-slot academy-atelier-slot--empty';
      const art = document.createElement('div');
      art.className = 'academy-atelier-slot-empty-art';
      fillWithEmptyArt(art, 'person', '空き');
      item.append(art);
      list.append(item);
      continue;
    }
    item.className = 'academy-atelier-slot academy-atelier-slot--active';
    item.dataset.homunculusId = entry.homunculus_id;

    const faceFrame = document.createElement('div');
    faceFrame.className = 'academy-atelier-slot-face';
    const face = document.createElement('img');
    hideImageOnError(face);
    face.src = entry.face_url;
    face.alt = `${entry.display_name}の顔`;
    faceFrame.append(face);

    // Head: the face beside the child's identity (name + 在り週 / 好感度). The 11-parameter grid spans the full slot
    // width BELOW the head.
    const identity = document.createElement('div');
    identity.className = 'academy-atelier-slot-identity';
    const nameRow = document.createElement('div');
    nameRow.className = 'academy-atelier-slot-name-row';
    const name = document.createElement('p');
    name.className = 'academy-atelier-slot-name';
    name.textContent = entry.display_name;
    nameRow.append(name);
    // The current buddy (is_buddy:true) shows a バディー chip beside the name; a non-buddy slot is unchanged.
    if (entry.is_buddy) {
      const buddyChip = document.createElement('span');
      buddyChip.className = 'academy-atelier-slot-buddy-chip';
      buddyChip.textContent = 'バディー';
      nameRow.append(buddyChip);
    }
    const meta = document.createElement('p');
    meta.className = 'academy-atelier-slot-meta';
    meta.textContent = `第${conversationStageWeek(entry.created_week)}週生まれ・好感度 ${entry.affinity}`;
    identity.append(nameRow, meta);
    const head = document.createElement('div');
    head.className = 'academy-atelier-slot-head';
    head.append(faceFrame, identity);

    // The child's 11 parameters (magic 6 + abilities 5): the terrace ability sigil (the name read out only), a meter
    // and the value, from the server-normalized shape.
    const parameters = renderAtelierParameterList(entry.parameters, abilitySigilLabel);

    const actions = document.createElement('div');
    actions.className = 'academy-atelier-slot-actions';
    const talk = atelierSigilButton('academy-atelier-slot-talk', 'visit', '会いに行く');
    if (view.conversationSpent) {
      talk.disabled = true;
      talk.title = 'この訪問の会話は使い切りました。次に訪れたときに会えます。';
    }
    talk.addEventListener('click', () => startAtelierConversation(entry.homunculus_id).catch(reportAtelierScreenError));
    const farewell = atelierSigilButton('academy-atelier-slot-farewell', 'farewell', 'お別れ');
    farewell.addEventListener('click', () => openAtelierFarewellConfirm(entry.homunculus_id, entry.display_name));
    actions.append(talk, farewell);
    item.append(head, parameters, actions);
    list.append(item);
  }
}

// A 錬成室 sigil button (the table-room sigil; the name read out only).
function atelierSigilButton(className, sigil, name) {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = `academy-atelier-mark-button ${className}`;
  button.setAttribute('aria-label', name);
  button.append(tableRoomSigilSvg(sigil));
  return button;
}

// Build a child's 11 parameter rows (magic 6 + abilities 5): each row is the server label + a 0–100 meter + the value.
// The label is the server-authoritative 日本語 name (atelierParameterRows) — never a frontend label map. Shared by the
// active slot, the synthesis result view and the ホムンクルス window (all render into .academy-atelier-parameters lists).
// createLabel(key, name) draws the name: the sigil alone (abilitySigilLabel) on the atelier slots and the night band,
// words (parameterTextLabel) in the synthesis result view.
function atelierParameterListItems(parameters, createLabel) {
  return atelierParameterRows(parameters).map((row) => atelierParameterItem(row.key, row, createLabel));
}

// One parameter row: the stat's server label drawn by createLabel, its 0–100 meter and its value.
function atelierParameterItem(key, stat, createLabel) {
  const item = document.createElement('li');
  item.className = 'academy-atelier-parameter';
  const label = createLabel(key, stat.label);
  label.classList.add('academy-atelier-parameter-label');
  const meter = document.createElement('meter');
  meter.className = 'academy-atelier-parameter-meter';
  meter.min = 0;
  meter.max = 100;
  meter.value = stat.value;
  meter.low = 33;
  meter.high = 66;
  meter.optimum = 100;
  const value = document.createElement('strong');
  value.className = 'academy-atelier-parameter-value';
  value.textContent = String(stat.value);
  item.append(label, meter, value);
  return item;
}

// A child's parameters as the two groups of the 相手 window (.character-parameter-section): 魔法習熟度 over the magic
// rows, then 基礎能力 over the ability rows, each group its word heading over its own .academy-atelier-parameters list.
function renderAtelierParameterGroups(parameters, createLabel) {
  const { magic, abilities } = validateAtelierParameters(parameters);
  return [['魔法習熟度', magic], ['基礎能力', abilities]].map(([title, group]) => {
    const section = document.createElement('section');
    section.className = 'character-parameter-section';
    const heading = document.createElement('h4');
    heading.textContent = title;
    const list = document.createElement('ul');
    list.className = 'academy-atelier-parameters';
    list.append(...Object.entries(group).map(([key, stat]) => atelierParameterItem(key, stat, createLabel)));
    section.append(heading, list);
    return section;
  });
}

// A standalone parameter list (its own .academy-atelier-parameters <ul>) for the active slot body.
function renderAtelierParameterList(parameters, createLabel) {
  const list = document.createElement('ul');
  list.className = 'academy-atelier-parameters';
  list.append(...atelierParameterListItems(parameters, createLabel));
  return list;
}

// Render the persistent 銘棚 (nameplates of departed children). The empty shelf picture (the terrace's empty-shelf art)
// toggles with the list so it shows only when no child has been seen off yet.
function renderAtelierNameplates(nameplates) {
  const list = atelierNode('#academy-atelier-nameplates');
  const empty = atelierNode('#academy-atelier-nameplates-empty');
  list.replaceChildren();
  fillWithEmptyArt(empty, 'shelf', '銘棚は空');
  empty.hidden = nameplates.length > 0;
  for (const entry of nameplates) {
    const item = document.createElement('li');
    item.className = 'academy-atelier-nameplate';
    const name = document.createElement('p');
    name.className = 'academy-atelier-nameplate-name';
    name.textContent = entry.display_name;
    const epitaph = document.createElement('p');
    epitaph.className = 'academy-atelier-nameplate-epitaph';
    epitaph.textContent = entry.epitaph;
    const week = document.createElement('p');
    week.className = 'academy-atelier-nameplate-week';
    week.textContent = `第${conversationStageWeek(entry.farewell_week)}週に見送った`;
    item.append(name, epitaph, week);
    list.append(item);
  }
}

// The 新たに錬成する entry is disabled when a new synthesis is impossible (満枠 / face pool 枯渇 / 所持素材 < 10). The
// held material total against the required total stands beside the entry as a value (marked short below the
// requirement); the title names the other two reasons so the disabled state never reads as silently doing nothing.
function updateAtelierSynthesizeOpen(view) {
  const open = atelierNode('#academy-atelier-synthesize-open');
  open.disabled = !view.canSynthesize;
  const reason = view.canSynthesize ? null : atelierSynthesizeBlockReason(view);
  if (reason) open.title = reason;
  else open.removeAttribute('title');
  const heldTotal = atelierHeldMaterialTotal(view);
  const count = atelierNode('#academy-atelier-material-count');
  count.textContent = `素材 ${heldTotal} / ${view.requiredMaterialTotal}`;
  count.dataset.short = heldTotal < view.requiredMaterialTotal ? 'true' : 'false';
}

function atelierHeldMaterialTotal(view) {
  return view.materials.reduce((sum, material) => sum + material.held, 0);
}

// The reason a new synthesis is blocked that the screen does not already show, derived from the arrival view
// (can_synthesize is the AND of all three server conditions; the view carries enough to name which one bites). A
// material shortfall has no line: the 素材 value beside the entry shows it. Money is never a reason (no money cost).
function atelierSynthesizeBlockReason(view) {
  if (view.active.length >= view.maxActive) return '錬成室の枠が満杯です。';
  if (atelierHeldMaterialTotal(view) < view.requiredMaterialTotal) return null;
  return '灯せる面がもう残っていません。';
}

// Render the material grid inside the synthesis box: rows are the six elements (their terrace ability sigils), columns
// the tiers present among the dungeon materials, and each cell one material — its name, held count and a −/＋ stepper
// with the chosen quantity. The player picks any mix totaling EXACTLY required_material_total (the 選択 n / total value
// beside the 錬成する sigil carries that number); duplicates of one material are allowed up to its held count.
// Selection state lives in atelierMaterialSelection. A missing element × tier material is a broken payload — throw.
function renderAtelierMaterialPicker(view) {
  const grid = atelierNode('#academy-atelier-materials');
  const tiers = [...new Set(view.materials.map((material) => material.tier))].sort((a, b) => a - b);
  grid.style.setProperty('--atelier-tier-count', String(tiers.length));
  const cells = [document.createElement('span')];
  for (const tier of tiers) {
    const head = document.createElement('span');
    head.className = 'academy-atelier-grid-tier';
    head.textContent = `T${tier}`;
    cells.push(head);
  }
  for (const element of WORKSHOP_ELEMENTS) {
    const sigil = abilitySigilLabel(element, workshopElementLabel(element));
    sigil.classList.add('academy-atelier-grid-element');
    cells.push(sigil);
    for (const tier of tiers) {
      const material = view.materials.find((entry) => entry.element === element && entry.tier === tier);
      if (!material) throw new Error(`atelier synthesis: no ${element} T${tier} material in the arrival materials`);
      cells.push(buildAtelierMaterialCell(material, view));
    }
  }
  grid.replaceChildren(...cells);
  updateAtelierMaterialPicker(view);
}

function buildAtelierMaterialCell(material, view) {
  const item = document.createElement('div');
  item.className = 'academy-atelier-material';
  item.dataset.itemId = material.item_id;
  if (material.held === 0) item.classList.add('academy-atelier-material--none');
  const name = document.createElement('span');
  name.className = 'academy-atelier-material-name';
  name.textContent = material.name;
  const held = document.createElement('span');
  held.className = 'academy-atelier-material-held';
  held.textContent = `所持 ${material.held}`;

  const stepper = document.createElement('div');
  stepper.className = 'academy-atelier-material-stepper';
  const minus = document.createElement('button');
  minus.type = 'button';
  minus.className = 'academy-atelier-material-step academy-atelier-material-step--minus';
  minus.textContent = '−';
  minus.setAttribute('aria-label', `${material.name}を減らす`);
  minus.addEventListener('click', () => adjustAtelierMaterial(material.item_id, -1, view));
  const qty = document.createElement('span');
  qty.className = 'academy-atelier-material-qty';
  const plus = document.createElement('button');
  plus.type = 'button';
  plus.className = 'academy-atelier-material-step academy-atelier-material-step--plus';
  plus.textContent = '＋';
  plus.setAttribute('aria-label', `${material.name}を増やす`);
  plus.addEventListener('click', () => adjustAtelierMaterial(material.item_id, 1, view));
  stepper.append(minus, qty, plus);

  item.append(name, held, stepper);
  return item;
}

// Apply a stepper press: clamp the new quantity to [0, held] and to the remaining room under required_material_total
// (so the running total can never exceed the target and a single material can never exceed its held count).
function adjustAtelierMaterial(itemId, delta, view) {
  const material = view.materials.find((entry) => entry.item_id === itemId);
  if (!material) return;
  const current = atelierMaterialSelection[itemId] ?? 0;
  const others = atelierSelectionTotal(atelierMaterialSelection) - current;
  const max = Math.max(0, Math.min(material.held, view.requiredMaterialTotal - others));
  const next = Math.max(0, Math.min(max, current + delta));
  if (next === 0) delete atelierMaterialSelection[itemId];
  else atelierMaterialSelection[itemId] = next;
  updateAtelierMaterialPicker(view);
}

// Reflect the current selection onto the rendered picker: each row's quantity + stepper disabled state, the running
// 選択 n / total line, and the synthesize submit (enabled only for a complete selection — total hit + within held).
function updateAtelierMaterialPicker(view) {
  const grid = atelierNode('#academy-atelier-materials');
  const total = atelierSelectionTotal(atelierMaterialSelection);
  for (const item of grid.querySelectorAll('.academy-atelier-material')) {
    const material = view.materials.find((entry) => entry.item_id === item.dataset.itemId);
    if (!material) continue;
    const qty = atelierMaterialSelection[material.item_id] ?? 0;
    item.querySelector('.academy-atelier-material-qty').textContent = String(qty);
    item.classList.toggle('academy-atelier-material--selected', qty > 0);
    item.querySelector('.academy-atelier-material-step--minus').disabled = qty <= 0;
    item.querySelector('.academy-atelier-material-step--plus').disabled = qty >= material.held || total >= view.requiredMaterialTotal;
  }
  const totalLine = atelierNode('#academy-atelier-materials-total');
  totalLine.textContent = `選択 ${total} / ${view.requiredMaterialTotal}`;
  totalLine.dataset.short = total < view.requiredMaterialTotal ? 'true' : 'false';
  atelierNode('#academy-atelier-synthesis-submit').disabled = !isAtelierSelectionComplete({
    selection: atelierMaterialSelection,
    materials: view.materials,
    requiredTotal: view.requiredMaterialTotal
  });
}

function setAtelierSynthesisStatus(message, { tone = null } = {}) {
  const status = atelierNode('#academy-atelier-synthesis-status');
  const text = String(message ?? '').trim();
  if (!text) {
    status.hidden = true;
    status.textContent = '';
    delete status.dataset.tone;
    return;
  }
  status.hidden = false;
  status.textContent = text;
  if (tone) status.dataset.tone = tone;
  else delete status.dataset.tone;
}

// The skeleton (骨子) field is manual-only; おまかせ generates the 骨子 from the name, so its field is hidden.
// The mode form guarantees exactly one radio of the closed set is checked (manual default + open re-checks manual);
// an out-of-set / missing checked value is broken markup wiring, so fail fast rather than coercing to a default mode.
function currentAtelierSynthesisMode() {
  const checked = document.querySelector('#academy-atelier-synthesis-form input[name="atelier-mode"]:checked');
  const mode = checked?.value;
  if (!ATELIER_SYNTHESIS_MODES.includes(mode)) {
    throw new Error(`atelier synthesis mode is not one of ${ATELIER_SYNTHESIS_MODES.join('/')} (got ${JSON.stringify(mode)} — broken mode markup wiring)`);
  }
  return mode;
}

function updateAtelierSkeletonFieldVisibility() {
  const field = atelierNode('#academy-atelier-skeleton-field');
  field.hidden = currentAtelierSynthesisMode() !== 'manual';
}

// Open the synthesis box (manual default, cleared name / skeleton, the material grid rendered from the held view). A full
// roster surfaces the reason on the arrival status line instead of opening (mirrors the disabled entry).
function openAtelierSynthesisForm() {
  if (!atelierArrivalView) return;
  if (!atelierArrivalView.canSynthesize) {
    const reason = atelierSynthesizeBlockReason(atelierArrivalView);
    if (reason) setAtelierScreenStatus(reason, { tone: 'error' });
    return;
  }
  const manual = document.querySelector('#academy-atelier-synthesis-form input[name="atelier-mode"][value="manual"]');
  if (manual) manual.checked = true;
  atelierNode('#academy-atelier-name-input').value = '';
  atelierNode('#academy-atelier-skeleton-input').value = '';
  setAtelierSynthesisStatus('');
  updateAtelierSkeletonFieldVisibility();
  atelierMaterialSelection = {};
  renderAtelierMaterialPicker(atelierArrivalView);
  atelierNode('#academy-atelier-room').hidden = true;
  atelierNode('#academy-atelier-lede').hidden = true;
  atelierNode('#academy-atelier-synthesis-form').hidden = false;
}

// The synthesis box stands in the room's place under the same pool (the slots, 銘棚 and the lede under the table step
// aside while it is open); closing it brings them back.
function closeAtelierSynthesisForm() {
  atelierNode('#academy-atelier-synthesis-form').hidden = true;
  atelierNode('#academy-atelier-room').hidden = false;
  atelierNode('#academy-atelier-lede').hidden = false;
}

// Validate the form fields client-side (the backend re-validates), then open the blind-confirm dialog. A blank name
// (or a blank 骨子 in manual mode) surfaces on the form status line without opening the confirm.
function submitAtelierSynthesisForm() {
  if (!atelierArrivalView) return;
  const mode = currentAtelierSynthesisMode();
  const name = atelierNode('#academy-atelier-name-input').value.trim();
  const skeleton = atelierNode('#academy-atelier-skeleton-input').value.trim();
  if (name === '') {
    setAtelierSynthesisStatus('名前を入れてください。', { tone: 'error' });
    return;
  }
  if (mode === 'manual' && skeleton === '') {
    setAtelierSynthesisStatus('どんな子かの骨子を入れてください。', { tone: 'error' });
    return;
  }
  const requiredTotal = atelierArrivalView.requiredMaterialTotal;
  if (!isAtelierSelectionComplete({ selection: atelierMaterialSelection, materials: atelierArrivalView.materials, requiredTotal })) {
    setAtelierSynthesisStatus(`素材をちょうど${requiredTotal}個そなえてください（今は${atelierSelectionTotal(atelierMaterialSelection)}個）。`, { tone: 'error' });
    return;
  }
  atelierPendingSynthesis = { mode, name, skeleton: mode === 'manual' ? skeleton : null, materials: atelierSelectionMaterials(atelierMaterialSelection) };
  openAtelierSynthesisConfirm({ mode, name });
}

// The blind-confirm dialog: 人格・顔は誕生まで見えない・一方通行・重コスト — spelled out so the player accepts the
// terms before the irreversible synthesis. Accept → submitAtelierSynthesis with the held params.
function openAtelierSynthesisConfirm({ mode, name }) {
  const body = atelierNode('#academy-atelier-confirm-body');
  body.textContent = `「${name}」を${ATELIER_SYNTHESIS_MODE_LABELS[mode]}で錬成します。どんな人格・どんな顔になるかは、生まれるまで見えません。引き直しはできず、重い対価は錬成が通った時に消費されます。`;
  atelierNode('#academy-atelier-confirm-popup').hidden = false;
}

function closeAtelierSynthesisConfirm() {
  const popup = document.querySelector('#academy-atelier-confirm-popup');
  if (popup) popup.hidden = true;
}

// ── 錬成する時の動き: 錬成室に居たまま、選んだ素材の残光が器へ注がれ、光が満ちて灯り、結果の窓が生まれる ──────────────
// 読み込みの画面へは移らない。六こま（確定 → 注ぐ → 満ちる → 満ち続ける → 灯る → 生まれる）を、部屋の絵と同じ座標（絵の
// 画素）の二枚の svg に requestAnimationFrame で描く: #academy-atelier-forge-dim は器の周りを残して部屋を沈める暗がり、
// #academy-atelier-forge-light は光そのもので screen で重ねる（足すのは明るさだけ — 器の硝子と奥の絵は透けたまま。不透明な
// 塗りは使わない）。満ちる段は応答が届くまで満ちきらずに上がり続け、残光の巡りは途切れない。応答が「注ぐ」より先に届いたら
// 注ぎ終えてから灯る。失敗のときは光が引き、残光が席へ戻って消えてから、部屋の失敗の印を出す。視差を減らす設定では移動と
// 拡大を外し、器の光が出て短く濃くなる → 結果の窓が不透明度で出る、の二段にする。

// 器の座標は錬成室の地の絵（/canonical/atelier/stage.jpg・2000×2000）の画素: 中央奥の大きな丸い硝子の器・その口・部屋の
// 小さな硝子の灯（中心と半径）。地の絵は窓を覆う大きさで真ん中に敷かれる（.table-room の --place-art-size: cover・
// --place-art-position: center・窓に固定）ので、二枚の svg の viewBox を同じ置き方で窓へ写す。
const ATELIER_STAGE_ART_SIZE = 2000;
const ATELIER_VESSEL = Object.freeze({ x: 1206, y: 597, r: 150 });
const ATELIER_VESSEL_MOUTH = Object.freeze({ x: 1206, y: 440 });
const ATELIER_ROOM_LAMPS = Object.freeze([[496, 847, 47], [451, 1330, 56], [1618, 833, 42], [1833, 1472, 83], [1194, 854, 36]]);
// 段の長さ（ms）。確定で表が退き（settle）、残光が一つずつ pourGap おきに pourFlight かけて器の口へ落ちる。灯る（kindle）・
// 生まれる（birth・style.css の atelier-result-rise と同じ長さ）・失敗で光が引く（recede）と残光が席へ戻る（moteReturn ＋
// moteFade）・結果の窓をとじて光が退く（standDown）。reduced は視差を減らす設定の二段の長さ。
const ATELIER_FORGE_MS = Object.freeze({ settle: 300, pourGap: 90, pourFlight: 500, kindle: 1000, birth: 600, recede: 700, moteGap: 20, moteReturn: 500, moteFade: 200, standDown: 300 });
const ATELIER_FORGE_REDUCED_MS = Object.freeze({ appear: 200, kindle: 400, deepen: 150, birth: 300, recede: 250, standDown: 150 });

// The forge standing on the room (the light drawn, the table stepped aside) from 確定 until the result window is closed —
// or, on a failed synthesis, until the light has receded. null otherwise.
let atelierForge = null;

function atelierForgeSvg(parent, name, attributes = {}) {
  const node = document.createElementNS(TABLE_ROOM_SVG_NS, name);
  for (const [key, value] of Object.entries(attributes)) node.setAttribute(key, String(value));
  parent.append(node);
  return node;
}

function atelierForgeGradient(defs, kind, id, stops, attributes = {}) {
  const gradient = atelierForgeSvg(defs, kind, { id, ...attributes });
  for (const [offset, color, opacity] of stops) atelierForgeSvg(gradient, 'stop', { offset, 'stop-color': color, 'stop-opacity': opacity });
  return gradient;
}

const forgeClamp = (value) => Math.min(1, Math.max(0, value));
const forgeEase = (value) => (value < 0.5 ? 4 * value ** 3 : 1 - (-2 * value + 2) ** 3 / 2);
const forgeLerp = (from, to, amount) => from + (to - from) * amount;

// The art placement of the room (window-fixed cover, centred) as a mapping between window points and art pixels. The
// forge layers depend on it, so a room that places its art otherwise is broken wiring.
function atelierArtPlacement(screen) {
  const style = getComputedStyle(screen);
  const size = style.getPropertyValue('--place-art-size').trim();
  const position = style.getPropertyValue('--place-art-position').trim();
  if (size !== 'cover' || position !== 'center') {
    throw new Error(`atelier forge: the room art is placed ${JSON.stringify(size)} / ${JSON.stringify(position)}, not cover / center (the vessel would not sit on the art)`);
  }
  const scale = Math.max(window.innerWidth, window.innerHeight) / ATELIER_STAGE_ART_SIZE;
  const left = (window.innerWidth - ATELIER_STAGE_ART_SIZE * scale) / 2;
  const top = (window.innerHeight - ATELIER_STAGE_ART_SIZE * scale) / 2;
  return { scale, left, top, toArt: (x, y) => ({ x: (x - left) / scale, y: (y - top) / scale }) };
}

// The seats of the chosen materials: each unit's afterglow sits on its material's cell in the (still open) synthesis box,
// the units of one material side by side around the cell's centre. Read before the box steps aside.
function atelierForgeSeats(materials, placement) {
  const grid = atelierNode('#academy-atelier-materials');
  return materials.flatMap(({ item_id: itemId, quantity }) => {
    const cell = grid.querySelector(`.academy-atelier-material[data-item-id="${CSS.escape(itemId)}"]`);
    if (!cell) throw new Error(`atelier forge: no material cell for ${itemId} in the synthesis box (broken picker wiring)`);
    const rect = cell.getBoundingClientRect();
    const centre = placement.toArt(rect.left + rect.width / 2, rect.top + rect.height / 2);
    return Array.from({ length: quantity }, (_, index) => ({ x: centre.x + (index - (quantity - 1) / 2) * 19, y: centre.y + (index % 2) * 14 - 7 }));
  });
}

// A point on the pouring arc from a seat to the vessel mouth (a quadratic curve lifted above both ends), and the part of
// the arc travelled so far (the afterglow's tail).
function atelierPourArc(seat) {
  const control = { x: (seat.x + ATELIER_VESSEL_MOUTH.x) / 2, y: Math.min(seat.y, ATELIER_VESSEL_MOUTH.y) - 153 };
  const at = (p) => ({
    x: (1 - p) ** 2 * seat.x + 2 * (1 - p) * p * control.x + p ** 2 * ATELIER_VESSEL_MOUTH.x,
    y: (1 - p) ** 2 * seat.y + 2 * (1 - p) * p * control.y + p ** 2 * ATELIER_VESSEL_MOUTH.y
  });
  const travelled = (p) => {
    const mid = { x: forgeLerp(seat.x, control.x, p), y: forgeLerp(seat.y, control.y, p) };
    const end = at(p);
    return `M ${seat.x} ${seat.y} Q ${mid.x} ${mid.y} ${end.x} ${end.y}`;
  };
  return { at, travelled };
}

// Start the forge on the room: the table and the exit step aside, the light layers are built and the frame loop runs.
// The returned handle advances the six frames: poured (resolves when every afterglow has fallen into the vessel; until a
// response the vessel keeps filling on its own), kindle() / birth(cardRect) on success, recede() on failure, standDown()
// when the result window is closed, dispose() to clear at once.
function startAtelierForge({ materials }) {
  const screen = atelierNode('#academy-atelier-screen');
  const dimLayer = atelierNode('#academy-atelier-forge-dim');
  const lightLayer = atelierNode('#academy-atelier-forge-light');
  const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const placement = atelierArtPlacement(screen);
  const seats = reduced ? [] : atelierForgeSeats(materials, placement);
  const C = ATELIER_VESSEL;
  const bottom = C.y + C.r;

  const fitLayers = () => {
    const now = atelierArtPlacement(screen);
    const rect = screen.getBoundingClientRect();
    const box = `${(rect.left - now.left) / now.scale} ${(rect.top - now.top) / now.scale} ${rect.width / now.scale} ${rect.height / now.scale}`;
    for (const layer of [dimLayer, lightLayer]) {
      layer.setAttribute('viewBox', box);
      layer.setAttribute('preserveAspectRatio', 'none');
    }
  };
  fitLayers();
  window.addEventListener('resize', fitLayers);

  // The dim: the room sinks around the vessel (clear at the vessel, the full depth beyond it).
  const dimDefs = atelierForgeSvg(dimLayer, 'defs');
  atelierForgeGradient(dimDefs, 'radialGradient', 'atelier-forge-dim', [[0, '#05060f', 0], [0.476, '#05060f', 0.4], [1, '#05060f', 1]],
    { gradientUnits: 'userSpaceOnUse', cx: C.x, cy: C.y + 55, r: 583 });
  const dim = atelierForgeSvg(dimLayer, 'rect', { x: -ATELIER_STAGE_ART_SIZE, y: -ATELIER_STAGE_ART_SIZE, width: ATELIER_STAGE_ART_SIZE * 3, height: ATELIER_STAGE_ART_SIZE * 3, fill: 'url(#atelier-forge-dim)', opacity: 0 });

  // The light: the afterglow motes (amber), the glow filling the vessel (pale glass blue from a bright core), the warmth
  // pooled at its bottom, the glass rim lit from within, the halo round the vessel, the kindled core and its rays.
  const defs = atelierForgeSvg(lightLayer, 'defs');
  atelierForgeGradient(defs, 'radialGradient', 'atelier-forge-mote', [[0, '#fffbe8', 1], [0.35, '#f3d9a6', 0.9], [1, '#e8c877', 0]]);
  atelierForgeGradient(defs, 'radialGradient', 'atelier-forge-glow', [[0, '#e6f6ff', 0.95], [0.45, '#8fd0ff', 0.5], [1, '#4a8fd8', 0]]);
  atelierForgeGradient(defs, 'radialGradient', 'atelier-forge-ember', [[0, '#f6e2b4', 0.8], [1, '#e8c877', 0]]);
  atelierForgeGradient(defs, 'linearGradient', 'atelier-forge-rim', [[0, '#cfeeff', 0.75], [1, '#cfeeff', 0]], { x1: 0, y1: 1, x2: 0, y2: 0 });
  atelierForgeGradient(defs, 'radialGradient', 'atelier-forge-halo', [[0, '#dff2ff', 0.55], [1, '#7fb8ff', 0]]);
  atelierForgeGradient(defs, 'radialGradient', 'atelier-forge-core', [[0, '#ffffff', 1], [0.3, '#fff3c8', 0.95], [1, '#e8c877', 0]]);
  atelierForgeSvg(atelierForgeSvg(defs, 'clipPath', { id: 'atelier-forge-vessel' }), 'circle', { cx: C.x, cy: C.y, r: C.r });
  // The soft edge works in the art's space (a straight ray has no height or no width, so a box-relative region would drop it).
  atelierForgeSvg(atelierForgeSvg(defs, 'filter', { id: 'atelier-forge-soft', filterUnits: 'userSpaceOnUse', x: 0, y: 0, width: ATELIER_STAGE_ART_SIZE, height: ATELIER_STAGE_ART_SIZE }), 'feGaussianBlur', { stdDeviation: 3 });
  const light = atelierForgeSvg(lightLayer, 'g', { opacity: 0 });
  const lamps = ATELIER_ROOM_LAMPS.map(([x, y, r]) => atelierForgeSvg(light, 'circle', { cx: x, cy: y, r: r * 1.8, fill: 'url(#atelier-forge-halo)', opacity: 0 }));
  const halo = atelierForgeSvg(light, 'circle', { cx: C.x, cy: C.y, r: C.r + 97, fill: 'url(#atelier-forge-halo)', opacity: 0 });
  const inside = atelierForgeSvg(light, 'g', { 'clip-path': 'url(#atelier-forge-vessel)' });
  const glow = atelierForgeSvg(inside, 'ellipse', { cx: C.x, fill: 'url(#atelier-forge-glow)', opacity: 0 });
  const ember = atelierForgeSvg(inside, 'ellipse', { cx: C.x, cy: bottom - 14, rx: C.r * 0.62, fill: 'url(#atelier-forge-ember)', opacity: 0 });
  // The motes drifting in the glow: a fixed scatter (the same each synthesis), denser low and sparse towards the top.
  let seed = 7;
  const random = () => {
    seed = (seed * 16807) % 2147483647;
    return seed / 2147483647;
  };
  const drift = Array.from({ length: 26 }, () => ({ u: random(), v: random(), size: 2.2 + random() * 3.3, alpha: 0.45 + random() * 0.5, phase: random() * Math.PI * 2 }))
    .map((mote) => ({ ...mote, node: atelierForgeSvg(inside, 'circle', { r: mote.size, fill: 'url(#atelier-forge-mote)', opacity: 0 }) }));
  const rim = atelierForgeSvg(light, 'circle', { cx: C.x, cy: C.y, r: C.r - 2, fill: 'none', stroke: 'url(#atelier-forge-rim)', 'stroke-width': 3, filter: 'url(#atelier-forge-soft)', opacity: 0 });
  const orbit = Array.from({ length: seats.length }, () => ({
    tail: atelierForgeSvg(light, 'path', { stroke: '#f3d9a6', 'stroke-width': 2.8, fill: 'none', filter: 'url(#atelier-forge-soft)', opacity: 0 }),
    mote: atelierForgeSvg(light, 'circle', { r: 9, fill: 'url(#atelier-forge-mote)', opacity: 0 })
  }));
  const pour = seats.map((seat) => ({
    seat,
    arc: atelierPourArc(seat),
    tail: atelierForgeSvg(light, 'path', { stroke: '#f3d9a6', 'stroke-width': 3.3, fill: 'none', filter: 'url(#atelier-forge-soft)', opacity: 0 }),
    mote: atelierForgeSvg(light, 'circle', { r: 18, fill: 'url(#atelier-forge-mote)', opacity: 0 })
  }));
  const rays = Array.from({ length: 10 }, () => atelierForgeSvg(light, 'line', { x1: C.x, y1: C.y, stroke: '#fff6da', 'stroke-width': 2.2, filter: 'url(#atelier-forge-soft)', opacity: 0 }));
  const core = atelierForgeSvg(light, 'circle', { cx: C.x, cy: C.y, r: 89, fill: 'url(#atelier-forge-core)', opacity: 0 });
  const thread = atelierForgeSvg(light, 'path', { stroke: '#fff6da', 'stroke-width': 4, fill: 'none', filter: 'url(#atelier-forge-soft)', opacity: 0 });

  const timing = reduced ? ATELIER_FORGE_REDUCED_MS : ATELIER_FORGE_MS;
  const pourEnd = reduced ? timing.appear : ATELIER_FORGE_MS.settle + (seats.length - 1) * ATELIER_FORGE_MS.pourGap + ATELIER_FORGE_MS.pourFlight;
  const startedAt = performance.now();
  const marks = { kindle: null, birth: null, recede: null, standDown: null, threadTo: null };

  // The vessel while it fills (a pure function of the time since 確定): reach of the glow (0–1 of the vessel's height) and
  // its brightness. Each fallen afterglow lifts the floor a little; after the pour the glow keeps rising towards — never
  // reaching — the full vessel, so a long wait still shows the light moving.
  const filling = (t) => {
    if (reduced) return { level: 0.66, strength: 0.6 * forgeClamp(t / timing.appear), dim: 0.5 * forgeClamp(t / timing.appear), halo: 0.45 * forgeClamp(t / timing.appear) };
    if (t < pourEnd) {
      const landed = pour.filter((_, index) => t >= ATELIER_FORGE_MS.settle + index * ATELIER_FORGE_MS.pourGap + ATELIER_FORGE_MS.pourFlight).length;
      const dim = t < ATELIER_FORGE_MS.settle ? 0.3 * (t / ATELIER_FORGE_MS.settle) : forgeLerp(0.3, 0.42, (t - ATELIER_FORGE_MS.settle) / (pourEnd - ATELIER_FORGE_MS.settle));
      return { level: 0.08 * (landed / pour.length), strength: 0.5, dim, halo: forgeLerp(0.18, 0.3, t / pourEnd) };
    }
    const since = t - pourEnd;
    const level = 0.08 + 0.82 * (1 - Math.exp(-since / 7000));
    return { level, strength: 0.5 + 0.45 * (1 - Math.exp(-since / 4000)), dim: 0.42 + 0.21 * ((level - 0.08) / 0.82), halo: 0.3 + 0.37 * level };
  };

  const paint = (now) => {
    const t = now - startedAt;
    let { level, strength, dim: dimDepth, halo: haloStrength } = filling(t);
    let lampStrength = reduced ? 0 : forgeClamp((t - pourEnd) / 600) * (0.15 + 0.07 * Math.sin(t / 650));
    let orbitShow = reduced ? 0 : forgeClamp((t - pourEnd) / 400);
    let orbitGather = 0;
    let coreStrength = 0;
    let rayStrength = 0;
    let threadStrength = 0;
    let fade = 1;
    if (marks.kindle !== null) {
      const from = filling(marks.kindle - startedAt);
      const k = reduced ? forgeClamp((now - marks.kindle) / timing.deepen) : forgeEase(forgeClamp((now - marks.kindle) / timing.kindle));
      level = reduced ? from.level : forgeLerp(from.level, 0.9, k);
      strength = forgeLerp(from.strength, 1, k);
      dimDepth = forgeLerp(from.dim, 0.62, k);
      haloStrength = forgeLerp(from.halo, 0.8, k);
      lampStrength = forgeLerp(forgeClamp((marks.kindle - startedAt - pourEnd) / 600) * 0.15, 0.1, k);
      orbitShow = reduced ? 0 : 1;
      orbitGather = k;
      coreStrength = (reduced ? 0.8 : 1) * k;
      rayStrength = reduced ? 0 : 0.55 * k;
    }
    if (marks.birth !== null) {
      const b = forgeEase(forgeClamp((now - marks.birth) / timing.birth));
      if (!reduced) level = forgeLerp(0.9, 0.5, b);
      strength = forgeLerp(1, 0.45, b);
      dimDepth = forgeLerp(0.62, 0.66, b);
      haloStrength = forgeLerp(0.8, 0.4, b);
      lampStrength = 0.1 * (1 - b);
      orbitShow = 0;
      coreStrength *= 1 - b;
      rayStrength *= 1 - b;
      threadStrength = reduced ? 0 : 0.6 * Math.sin(Math.PI * forgeClamp((now - marks.birth) / timing.birth));
    }
    if (marks.recede !== null) {
      const r = forgeEase(forgeClamp((now - marks.recede) / timing.recede));
      strength *= 1 - r;
      dimDepth *= 1 - r;
      haloStrength *= 1 - r;
      lampStrength *= 1 - r;
      orbitShow *= 1 - forgeClamp((now - marks.recede) / 200);
    }
    if (marks.standDown !== null) fade = 1 - forgeEase(forgeClamp((now - marks.standDown) / timing.standDown));

    dim.setAttribute('opacity', String(dimDepth * fade));
    light.setAttribute('opacity', String(fade));
    for (const lamp of lamps) lamp.setAttribute('opacity', String(lampStrength));
    halo.setAttribute('opacity', String(haloStrength));
    const reach = 2 * C.r * level;
    glow.setAttribute('cy', String(bottom - reach * 0.38));
    glow.setAttribute('rx', String(C.r * (0.75 + 0.35 * level)));
    glow.setAttribute('ry', String(reach * 0.78 + 25));
    glow.setAttribute('opacity', String(strength));
    ember.setAttribute('ry', String(36 + reach * 0.16));
    ember.setAttribute('opacity', String(strength));
    rim.setAttribute('opacity', String(strength * Math.min(1, 0.4 + level)));
    for (const mote of drift) {
      const y = bottom - reach * Math.sqrt(mote.v) - 6 + (reduced ? 0 : Math.sin(t * 0.0012 + mote.phase) * 5);
      const half = Math.sqrt(Math.max(0, C.r ** 2 - (y - C.y) ** 2)) - 11;
      mote.node.setAttribute('cx', String(C.x + (mote.u * 2 - 1) * Math.max(0, half)));
      mote.node.setAttribute('cy', String(y));
      mote.node.setAttribute('opacity', String(half > 0 && reach > 0 ? mote.alpha * Math.min(1, strength + 0.2) : 0));
    }

    // The afterglow circling in the light: an ellipse that widens and climbs as the glow rises, gathering into the core
    // when the response kindles it.
    const spread = Math.min(1, Math.max(-0.8, (level - 0.34) / 0.32));
    const rx = (97 + 11 * spread) * (1 - orbitGather);
    const ry = (31 + 11 * spread) * (1 - orbitGather);
    const cy = forgeLerp(C.y + 56 - 42 * spread, C.y, orbitGather);
    orbit.forEach(({ tail, mote }, index) => {
      const angle = (t - pourEnd) * 0.0011 + (index / orbit.length) * Math.PI * 2;
      const x = C.x + Math.cos(angle) * rx;
      const y = cy + Math.sin(angle) * ry;
      mote.setAttribute('cx', String(x));
      mote.setAttribute('cy', String(y));
      mote.setAttribute('opacity', String(0.9 * orbitShow));
      const back = angle - 0.35;
      tail.setAttribute('d', `M ${C.x + Math.cos(back) * rx} ${cy + Math.sin(back) * ry} A ${Math.max(rx, 0.01)} ${Math.max(ry, 0.01)} 0 0 1 ${x} ${y}`);
      tail.setAttribute('opacity', String(0.45 * orbitShow * (1 - orbitGather)));
    });

    // The afterglow pouring from its seat into the vessel mouth one by one — and, on a failure, rising back out of the
    // mouth to its seat and fading there.
    pour.forEach(({ seat, arc, tail, mote }, index) => {
      let position = null;
      let size = 15;
      let opacity = 0;
      let tailPath = null;
      if (marks.recede !== null) {
        const since = now - marks.recede - index * ATELIER_FORGE_MS.moteGap;
        if (since >= 0) {
          const p = forgeEase(forgeClamp(since / ATELIER_FORGE_MS.moteReturn));
          position = arc.at(1 - p);
          opacity = 0.95 * (1 - forgeClamp((since - ATELIER_FORGE_MS.moteReturn) / ATELIER_FORGE_MS.moteFade));
        }
      } else {
        const launch = ATELIER_FORGE_MS.settle + index * ATELIER_FORGE_MS.pourGap;
        if (t < launch) {
          position = seat;
          size = 18;
          opacity = 0.95 * forgeClamp(t / 200);
        } else if (t < launch + ATELIER_FORGE_MS.pourFlight) {
          const p = forgeEase((t - launch) / ATELIER_FORGE_MS.pourFlight);
          position = arc.at(p);
          opacity = 1;
          tailPath = arc.travelled(p);
        }
      }
      mote.setAttribute('opacity', String(opacity));
      if (position) {
        mote.setAttribute('cx', String(position.x));
        mote.setAttribute('cy', String(position.y));
        mote.setAttribute('r', String(size));
      }
      tail.setAttribute('opacity', tailPath ? '0.4' : '0');
      if (tailPath) tail.setAttribute('d', tailPath);
    });

    core.setAttribute('opacity', String(coreStrength));
    rays.forEach((ray, index) => {
      const angle = (index / rays.length) * Math.PI * 2;
      const length = 208 * (0.6 + 0.4 * orbitGather);
      ray.setAttribute('x2', String(C.x + Math.cos(angle) * length));
      ray.setAttribute('y2', String(C.y + Math.sin(angle) * length));
      ray.setAttribute('opacity', String(rayStrength));
    });
    thread.setAttribute('opacity', String(threadStrength));
    if (marks.threadTo) {
      const to = marks.threadTo;
      thread.setAttribute('d', `M ${C.x} ${C.y} C ${C.x} ${C.y + 83}, ${to.x + 28} ${to.y - 28}, ${to.x} ${to.y}`);
    }
  };

  let frame = 0;
  const loop = (now) => {
    paint(now);
    frame = requestAnimationFrame(loop);
  };
  frame = requestAnimationFrame(loop);

  const column = atelierNode('#academy-atelier-column');
  const exit = atelierNode('#academy-atelier-exit');
  const status = atelierNode('#academy-atelier-forge-status');
  // The frame the forge stands in, on the screen (style.css steps the table and the exit aside while it is set):
  // appear (視差を減らす設定) / pour → fill → kindle → birth, or recede on a failure.
  screen.dataset.forge = reduced ? 'appear' : 'pour';
  column.inert = true;
  exit.inert = true;
  status.textContent = '錬成しています';

  const stepAside = () => {
    delete screen.dataset.forge;
    column.inert = false;
    exit.inert = false;
    status.textContent = '';
  };
  const dispose = () => {
    cancelAnimationFrame(frame);
    window.removeEventListener('resize', fitLayers);
    dimLayer.replaceChildren();
    lightLayer.replaceChildren();
    stepAside();
  };

  return {
    poured: sleep(pourEnd).then(() => {
      if (screen.dataset.forge === 'pour' || screen.dataset.forge === 'appear') screen.dataset.forge = 'fill';
    }),
    kindle() {
      marks.kindle = performance.now();
      screen.dataset.forge = 'kindle';
      return sleep(timing.kindle);
    },
    birth(cardRect) {
      marks.birth = performance.now();
      screen.dataset.forge = 'birth';
      const top = placement.toArt(cardRect.left + cardRect.width / 2, cardRect.top);
      marks.threadTo = { x: top.x, y: top.y + 55 };
      return sleep(timing.birth);
    },
    recede() {
      marks.recede = performance.now();
      screen.dataset.forge = 'recede';
      return sleep(reduced ? timing.recede : Math.max(timing.recede, (pour.length - 1) * ATELIER_FORGE_MS.moteGap + ATELIER_FORGE_MS.moteReturn + ATELIER_FORGE_MS.moteFade));
    },
    // The result window is closed: the table returns while the light and the dim fade away.
    async standDown() {
      marks.standDown = performance.now();
      stepAside();
      await sleep(timing.standDown);
      dispose();
    },
    dispose
  };
}

function dismissAtelierForge() {
  if (!atelierForge) return;
  atelierForge.dispose();
  atelierForge = null;
}

// Run the synthesis on the room itself: the forge pours the chosen materials' afterglow into the vessel and keeps it
// filling until the response. On success the room behind is re-read while the light kindles, then the 錬成結果ビュー
// rises from the vessel; the table returns (with the newborn's slot in its birth afterglow) when that window is closed.
// On failure (400 name/mode/所持不足 / 409 満枠/pool / 503 LM / 403 locked — nothing is consumed) the light recedes and the
// afterglow returns to its seats before the room shows its failure glyph.
async function submitAtelierSynthesis() {
  if (atelierActionInFlight) {
    showProcessingToast();
    return;
  }
  const params = atelierPendingSynthesis;
  if (!params) return;
  atelierActionInFlight = true;
  try {
    // A new synthesis starts clean: an earlier failure's glyph beside the place name does not stand over this one.
    setAtelierScreenStatus('');
    const forge = startAtelierForge({ materials: params.materials });
    atelierForge = forge;
    closeAtelierSynthesisConfirm();
    const body = { mode: params.mode, name: params.name, materials: params.materials };
    if (params.mode === 'manual') body.skeleton = params.skeleton;
    let result = null;
    try {
      result = validateAtelierSynthesisResult(await postJson('/api/atelier/synthesize', body));
    } catch (error) {
      await forge.poured;
      await forge.recede();
      dismissAtelierForge();
      if (handleRuntimeApiError(error, { allowSettingsRedirect: true })) return;
      await refreshAtelierScreen();
      showAtelierFailureNotice();
      console.error(error);
      return;
    }
    await forge.poured;
    // The synthesis box stepped aside with the table; the room it stood in is what the table brings back.
    closeAtelierSynthesisForm();
    await Promise.all([forge.kindle(), loadAtelierArrival().catch(reportAtelierScreenError)]);
    forge.birthId = result.homunculus.homunculus_id;
    openAtelierSynthesisResult(result);
    await forge.birth(atelierNode('#academy-atelier-result-popup .academy-atelier-result-frame').getBoundingClientRect());
  } finally {
    atelierActionInFlight = false;
    atelierPendingSynthesis = null;
  }
}

// とじる on the 錬成結果ビュー: the forge stands down and the table returns, the newborn's slot filling with its birth
// afterglow once. The result window only ever stands over a forge, so a missing forge is a broken flow.
async function closeAtelierBirth() {
  const forge = atelierForge;
  if (!forge) throw new Error('atelier result: closed with no forge standing (the 錬成結果ビュー opens only from a synthesis)');
  closeAtelierSynthesisResult();
  const standing = forge.standDown();
  try {
    markAtelierBirth(forge.birthId);
  } finally {
    await standing;
    if (atelierForge === forge) atelierForge = null;
  }
}

function markAtelierBirth(homunculusId) {
  const slot = atelierNode('#academy-atelier-slots').querySelector(`.academy-atelier-slot[data-homunculus-id="${CSS.escape(homunculusId)}"]`);
  if (!slot) throw new Error(`atelier result: the newborn ${homunculusId} has no slot in the room (the arrival was not re-read)`);
  slot.classList.add('academy-atelier-slot--birthing');
}

// The 錬成結果ビュー: the freshly synthesized child's face + name, its 11 generated parameters (label + value from the
// server-normalized shape), and the materials the synthesis consumed (display names + quantities). Closed by とじる,
// leaving the birthed slot (with its birth 演出) behind it; that slot's 会いに行く button enters the first conversation.
// Result shape is validated already.
function openAtelierSynthesisResult(result) {
  if (!result) return;
  atelierNode('#academy-atelier-result-name').textContent = result.homunculus.display_name;
  const face = atelierNode('#academy-atelier-result-face-img');
  hideImageOnError(face);
  face.src = result.homunculus.face_url;
  face.alt = `${result.homunculus.display_name}の顔`;
  atelierNode('#academy-atelier-result-parameter-list').replaceChildren(...atelierParameterListItems(result.homunculus.parameters, parameterTextLabel));
  const consumed = atelierNode('#academy-atelier-result-consumed-list');
  consumed.replaceChildren();
  for (const material of result.consumedMaterials) {
    const item = document.createElement('li');
    item.className = 'academy-atelier-result-consumed-item';
    const name = document.createElement('span');
    name.className = 'academy-atelier-result-consumed-name';
    name.textContent = material.name;
    const qty = document.createElement('span');
    qty.className = 'academy-atelier-result-consumed-qty';
    qty.textContent = `×${material.quantity}`;
    item.append(name, qty);
    consumed.append(item);
  }
  atelierNode('#academy-atelier-result-popup').hidden = false;
}

function closeAtelierSynthesisResult() {
  const popup = document.querySelector('#academy-atelier-result-popup');
  if (popup) popup.hidden = true;
}

// The one-way farewell-confirm dialog: お別れは取り消せず、銘だけが棚に残る — spelled out before the irreversible
// farewell. Accept → submitAtelierFarewell with the held id.
function openAtelierFarewellConfirm(homunculusId, displayName) {
  atelierPendingFarewellId = homunculusId;
  const body = atelierNode('#academy-atelier-farewell-confirm-body');
  body.textContent = `「${displayName}」とお別れします。もう一度会うことはできず、棚には銘だけが残ります。それでも見送りますか。`;
  atelierNode('#academy-atelier-farewell-confirm-popup').hidden = false;
}

function closeAtelierFarewellConfirm() {
  const popup = document.querySelector('#academy-atelier-farewell-confirm-popup');
  if (popup) popup.hidden = true;
}

// Run the farewell behind the loading screen (生成待ちはロード被覆). On success return to the atelier (the re-fetch
// surfaces the new 銘板) and open the farewell-speech 見せ場 over it; on failure return with the structured error
// surfaced (404 not-active / 503 LM). The child stays until the farewell fully succeeds (fail-fast, retriable).
async function submitAtelierFarewell() {
  if (atelierActionInFlight) {
    showProcessingToast();
    return;
  }
  const homunculusId = atelierPendingFarewellId;
  if (typeof homunculusId !== 'string' || homunculusId === '') return;
  atelierActionInFlight = true;
  closeAtelierFarewellConfirm();
  let farewell = null;
  const readiness = (async () => {
    const payload = await postJson('/api/atelier/farewell', { homunculus_id: homunculusId });
    farewell = validateAtelierFarewellResult(payload);
  })();
  try {
    await showAcademyLoadingScreenUntilReady({
      readiness,
      nextScreen: null,
      loadingCopy: { title: 'お別れの支度をしています', status: 'この子の最後の言葉を待っています。' }
    });
  } catch (error) {
    if (settingsRedirectErrorMessage(error) == null) {
      showScreen('academy-atelier');
      showAtelierFailureNotice();
      console.error(error);
    }
    atelierActionInFlight = false;
    atelierPendingFarewellId = null;
    return;
  }
  atelierActionInFlight = false;
  atelierPendingFarewellId = null;
  showScreen('academy-atelier');
  openAtelierFarewellSpeech(farewell);
}

// The farewell-speech 見せ場: the departed child's long-form send-off (hard cap 1000 chars server-side) with its
// name + 銘, read at the player's pace and closed by 送り出す. A missing speech is broken state (validated already).
function openAtelierFarewellSpeech(farewell) {
  atelierNode('#academy-atelier-farewell-speech-name').textContent = farewell.display_name;
  atelierNode('#academy-atelier-farewell-speech-epitaph').textContent = farewell.epitaph;
  atelierNode('#academy-atelier-farewell-speech-text').textContent = farewell.farewell_speech;
  atelierNode('#academy-atelier-farewell-speech-popup').hidden = false;
}

function closeAtelierFarewellSpeech() {
  const popup = document.querySelector('#academy-atelier-farewell-speech-popup');
  if (popup) popup.hidden = true;
}

// Enter the ホムンクルス conversation as a PRE-STARTED atelier conversation (POST /api/atelier/conversation/start, NOT
// /api/interaction/start): adopt the post-start state, bind the daytime actor to the homunculus FROM THE RESPONSE
// (a non-selectable per-slot actor — register its visual so its face / name render), hold the server-authoritative
// injected 錬成室 scene, and reveal the opening on the daytime screen. The daytime turn (routingTurnRequestBody
// carries the atelier id) and the routing drain-on-exit end path (returns to academy-atelier) take it from there.
// The 1 visit = 1 conversation gate (409 spent) and not-active (404) surface on the atelier arrival status line.
async function startAtelierConversation(homunculusId) {
  if (conversationRequestInFlight) {
    showProcessingToast();
    return;
  }
  conversationRequestInFlight = true;
  conversationDayStage.setControlsDisabled(true);
  markConversationDayKind('atelier');
  let payload;
  const readiness = (async () => {
    payload = await postJson('/api/atelier/conversation/start', { homunculus_id: homunculusId });
    const parsed = validateAtelierConversationStart(payload);
    activeCharacterId = parsed.homunculus.homunculus_id;
    currentRuntimeState = payload.state;
    clearVisibleConversation();
    conversationDayStage.surface.setHistory([]);
    // Set AFTER clearVisibleConversation (which drops all content-conversation state) so the daytime turn carries the
    // atelier id, the stage frame / detail popup read the injected 錬成室 scene, and the speaker face / name resolve
    // the homunculus' own visual.
    activeAtelierConversationId = parsed.conversationId;
    activeAtelierScene = { locationName: parsed.locationName, visibleSituation: parsed.visibleSituation };
    registerAtelierActorVisual(parsed.homunculus);
    writeDebugLog({ started_atelier_homunculus: homunculusId, conversation_id: parsed.conversationId, state: payload.state, screen: 'conversation-day' });
  })();
  try {
    try {
      await showAcademyLoadingScreenUntilReady({
        readiness,
        nextScreen: 'conversation-day',
        refreshBeforeNextScreen: false,
        passage: { stage: conversationPassageStage('atelier') }
      });
    } catch (error) {
      if (settingsRedirectErrorMessage(error) == null) {
        showScreen('academy-atelier');
        showAtelierFailureNotice();
      }
      throw error;
    }
    renderConversationDayStage();
    await revealResultSequentially(conversationDayStage.surface, payload);
  } finally {
    conversationRequestInFlight = false;
    conversationDayStage.setControlsDisabled(false);
    focusConversationDayInputIfContinuing();
  }
}

// 錬成室を出る: leave the stay screen through the server-authoritative post_content_screen held from the latest GET
// /api/atelier (routing-only → the routing hub) via the shared return over the place's art, guarded by the shared
// routingContentReturnInFlight flag. A missing held screen is broken state — fail fast (never a fabricated default).
async function exitAtelier() {
  if (routingContentReturnInFlight) {
    showProcessingToast();
    return;
  }
  const nextScreen = atelierExitScreen;
  if (typeof nextScreen !== 'string' || nextScreen === '') {
    throw new Error('atelier exit: no post_content_screen held (錬成室の退出先が未取得 — broken arrival flow)');
  }
  routingContentReturnInFlight = true;
  try {
    await returnToRoutingHubFromContent(nextScreen);
  } finally {
    routingContentReturnInFlight = false;
  }
}

document.querySelector('#academy-atelier-synthesize-open').addEventListener('click', () => openAtelierSynthesisForm());
document.querySelector('#academy-atelier-exit').addEventListener('click', () => exitAtelier().catch(reportAtelierScreenError));
dressSigilButton(document.querySelector('#academy-atelier-synthesis-cancel'), 'back', 'やめる');
document.querySelector('#academy-atelier-synthesis-cancel').addEventListener('click', () => closeAtelierSynthesisForm());
document.querySelector('#academy-atelier-synthesis-form').addEventListener('submit', (event) => {
  event.preventDefault();
  submitAtelierSynthesisForm();
});
for (const radio of document.querySelectorAll('#academy-atelier-synthesis-form input[name="atelier-mode"]')) {
  radio.addEventListener('change', () => updateAtelierSkeletonFieldVisibility());
}
document.querySelector('#academy-atelier-confirm-cancel').addEventListener('click', () => closeAtelierSynthesisConfirm());
document.querySelector('#academy-atelier-confirm-accept').addEventListener('click', () => submitAtelierSynthesis().catch(reportAtelierScreenError));
document.querySelector('#academy-atelier-result-close').addEventListener('click', () => closeAtelierBirth().catch(reportAtelierScreenError));
document.querySelector('#academy-atelier-farewell-confirm-cancel').addEventListener('click', () => closeAtelierFarewellConfirm());
document.querySelector('#academy-atelier-farewell-confirm-accept').addEventListener('click', () => submitAtelierFarewell().catch(reportAtelierScreenError));
document.querySelector('#academy-atelier-farewell-speech-close').addEventListener('click', () => closeAtelierFarewellSpeech());

// ── 札の部屋（依頼の札 academy-errand・研究会の札 academy-study-circle）: 露台の行き先「依頼」「研究会」の着く画面 ─────────
// 二つの画面は一つの作りを分け合い、違うのは地の絵・場所の名・札の値の形の三つだけ（ROOM_CARD_ROOMS の行）。部屋の絵（送り出しの
// 幕と入り道の待ちと同じ一枚・hubTerrace.js の destinationArt）を画面いっぱいに敷き、左上に会話の層と同じ場所・同じ字で週と場所の
// 名を置き、今週の三枚の札を画面の上半分の中ほどに横に並べる。札は部屋の掲示の紙と同じ生成りの紙。
// - 入る: 今週の札の要求（GET）は、送り出しから続く場所の絵の上の待ち（placeVeilForArrival）の下で待ち、札が揃ったところで待ちが
//   薄れて札の部屋が現れる。失敗は待ちが夜へ沈んでから、失敗の報せ（紋と行き先の名）ともう一度の紋の釦を札の場所に出す。
// - 選ぶ: 一枚を押すと、ほかの二枚は退き、押した一枚は舞台の光を帯びて息をしながら、その場で会話の始まり（POST・1回で会話と最初の
//   言葉）を待つ。始まったら同じ部屋の絵の会話の画面へ移り、札の列ごと会話の画面へ持ち込む（札は同じ場所に残る）。会話の層の
//   相手が左下の隅に光の中から現れ、最初の言葉が出揃ったら残った札も退いて、いつもの会話の姿になる。研究会は選んだときに場所の名が
//   札の集まる所へ移る（会話の画面の場所の名と同じ）。始まりに失敗したら、札は三枚に戻り、失敗の報せを出す（設定の画面への誘いは
//   設定の画面へ）。
// 戻る・飛ばす口は無い（行き先へ来た時点で週は使っていて、会話を終えるのがハブへ戻る唯一の道）。
const ROOM_CARDS_OFFER_COUNT = 3;
const ROOM_CARDS_MOON_PHASE_COUNT = 8;
// 依頼の札の値の紋: 会話の画面の左の印の列の「お金」の絵。
const ROOM_CARD_COIN_MARK_URL = '/canonical/conversation_day/icons/money.png';

function assertRoomCardString(room, value, label) {
  if (typeof value !== 'string' || value.trim() === '') {
    throw new Error(`${room.kind} offer: ${label} must be a non-empty string (got ${JSON.stringify(value)})`);
  }
  return value;
}

// 依頼主の顔は選べるロスターの顔の絵（選択の印 → 顔 → 原画の顔）。サーバーは依頼主を選べるロスターから引くので、ロスターに無い id は
// データの食い違い — 顔の URL を作らず、ほかの人の顔も借りずに落ちる。
function errandClientFaceUrl(characterId) {
  const client = selectableCharacters.find((character) => character.character_id === characterId);
  if (!client) {
    throw new Error(`errand client is not in the selectable roster: ${JSON.stringify(characterId)}`);
  }
  return client.selection_icon_url ?? client.face_url ?? sourceSheetImageUrl({ characterId, view: 'face' });
}

// 依頼の札の値: 金の紋と額。
function errandCardWorth(room, offer) {
  const reward = offer.reward_money;
  if (typeof reward !== 'number' || !Number.isFinite(reward) || reward <= 0) {
    throw new Error(`errand offer: reward_money must be a positive number (got ${JSON.stringify(reward)})`);
  }
  const coin = document.createElement('img');
  coin.className = 'room-card-coin';
  coin.src = ROOM_CARD_COIN_MARK_URL;
  coin.alt = '';
  coin.setAttribute('aria-hidden', 'true');
  const money = document.createElement('span');
  money.className = 'room-card-money';
  money.textContent = moneyText(reward);
  return [coin, money];
}

// 研究会の札の値: 伸びる値の名と幅の印（一つの値に一つの印）。
function studyCircleCardWorth(room, offer) {
  const rewardParams = offer.reward_params;
  if (!Array.isArray(rewardParams) || rewardParams.length === 0) {
    throw new Error(`study-circle offer: reward_params must be a non-empty array (got ${JSON.stringify(rewardParams)})`);
  }
  return rewardParams.map((reward) => {
    const label = assertRoomCardString(room, reward?.label, 'reward_params.label');
    const amount = reward?.amount;
    if (typeof amount !== 'number' || !Number.isInteger(amount) || amount <= 0) {
      throw new Error(`study-circle offer: reward amount must be a positive integer (got ${JSON.stringify(amount)})`);
    }
    const gain = document.createElement('span');
    gain.className = 'room-card-gain';
    gain.textContent = `${label} +${amount}`;
    return gain;
  });
}

// 部屋ごとの違い（地の絵・場所の名・札の値の形）と、部屋ごとの要求の口。prefix は画面の要素の id の頭（#<prefix>-screen など）。
// 札の中身の読み方（readOffer）は、札の字（人・題・集まる所・語り）と始まりに渡すものを返す。
const ROOM_CARD_ROOMS = Object.freeze({
  errand: Object.freeze({
    kind: 'errand',
    screen: 'academy-errand',
    prefix: 'academy-errand',
    destinationId: 'errand',
    placeName: ERRAND_SCENE_LOCATION_NAME,
    offersUrl: '/api/errand',
    offersOf: (payload) => payload.errands,
    readOffer: (room, offer) => {
      const clientId = assertRoomCardString(room, offer.client_character_id, 'client_character_id');
      return {
        startId: assertRoomCardString(room, offer.errand_id, 'errand_id'),
        whoName: assertRoomCardString(room, offer.client_display_name, 'client_display_name'),
        whoFaceUrl: errandClientFaceUrl(clientId),
        title: assertRoomCardString(room, offer.title, 'title'),
        venue: null,
        appeal: assertRoomCardString(room, offer.appeal, 'appeal')
      };
    },
    worth: errandCardWorth,
    start: (card) => startErrandConversation(card.startId)
  }),
  'study-circle': Object.freeze({
    kind: 'study-circle',
    screen: 'academy-study-circle',
    prefix: 'academy-study-circle',
    destinationId: 'study_circle',
    placeName: '研究会',
    offersUrl: '/api/study-circle',
    offersOf: (payload) => payload.offers,
    readOffer: (room, offer) => ({
      startId: assertRoomCardString(room, offer.theme_id, 'theme_id'),
      whoName: assertRoomCardString(room, offer.host_display_name, 'host_display_name'),
      // 主催の顔は札の要求が飾った host_face_url（サーバーが引いた顔）。
      whoFaceUrl: assertRoomCardString(room, offer.host_face_url, 'host_face_url'),
      title: assertRoomCardString(room, offer.title, 'title'),
      venue: assertRoomCardString(room, offer.venue, 'venue'),
      appeal: assertRoomCardString(room, offer.appeal, 'appeal')
    }),
    worth: studyCircleCardWorth,
    start: (card) => startStudyCircleConversation(card.startId)
  })
});

function roomCardsRoomOfScreen(name) {
  return Object.values(ROOM_CARD_ROOMS).find((room) => room.screen === name) ?? null;
}

function roomCardsNode(room, part) {
  const node = document.querySelector(`#${room.prefix}-${part}`);
  if (!node) throw new Error(`room cards: #${room.prefix}-${part} is missing`);
  return node;
}

// いま来ている訪問の露台からの到着（{ destinationLabel }・開発用の入口では null。showScreen が置く）。失敗の報せは行き先の名で呼ぶ。
const roomCardsVisitArrivals = new Map();

function roomCardsDestinationLabel(room) {
  return routingArrivalDestinationLabel(roomCardsVisitArrivals.get(room.kind) ?? null);
}

function clearRoomCardsTrouble(room) {
  const status = roomCardsNode(room, 'status');
  status.hidden = true;
  status.replaceChildren();
  delete status.dataset.tone;
  roomCardsNode(room, 'retry').hidden = true;
}

// 失敗の報せ（紋と行き先の名）を札の場所に出す。retry は札の要求の失敗のときだけ（札が無いまま止まらないよう、もう一度の紋の釦）。
function showRoomCardsTrouble(room, { retry }) {
  writeRoutingFailureNotice(roomCardsNode(room, 'status'), { destinationLabel: roomCardsDestinationLabel(room) });
  roomCardsNode(room, 'retry').hidden = !retry;
}

// 週の字と月相の紋: 会話の画面の左上と同じ字（第N週 / 50）と同じ紋。週は会話の画面と同じく、いまの状態の elapsed_weeks から引く
// （札の要求を待つ前に置くので、要求が失敗しても週は見えている）。
function renderRoomCardsWeek(room) {
  const week = conversationStageWeek(currentRuntimeState?.elapsed_weeks);
  roomCardsNode(room, 'week').textContent = `第${week}週 / ${CONVERSATION_DAY_TOTAL_WEEKS}`;
  const phase = conversationStageMoonPhase(week, ROOM_CARDS_MOON_PHASE_COUNT);
  const moon = document.createElement('img');
  moon.className = 'moon-phase-image';
  moon.src = conversationStageMoonImageUrl(phase);
  moon.alt = `月相 ${phase + 1} / ${ROOM_CARDS_MOON_PHASE_COUNT}`;
  roomCardsNode(room, 'moon').replaceChildren(moon);
}

function buildRoomCard(room, offer) {
  if (!offer || typeof offer !== 'object') {
    throw new Error(`${room.kind} offer: malformed entry ${JSON.stringify(offer)}`);
  }
  const card = room.readOffer(room, offer);
  const item = document.createElement('li');
  item.className = `room-card ${room.prefix}-card`;
  const button = document.createElement('button');
  button.type = 'button';
  button.className = `room-card-button ${room.prefix}-card-button`;

  const who = document.createElement('span');
  who.className = 'room-card-who';
  const face = document.createElement('img');
  face.className = 'room-card-face';
  face.alt = '';
  face.setAttribute('aria-hidden', 'true');
  setActorImageSource(face, card.whoFaceUrl);
  const name = document.createElement('span');
  name.className = `room-card-name ${room.prefix}-card-${room.kind === 'errand' ? 'client' : 'host'}-name`;
  name.textContent = card.whoName;
  who.append(face, name);

  const title = document.createElement('span');
  title.className = 'room-card-title';
  title.textContent = card.title;
  button.append(who, title);
  if (card.venue !== null) {
    const venue = document.createElement('span');
    venue.className = 'room-card-venue';
    venue.textContent = card.venue;
    button.append(venue);
  }
  const appeal = document.createElement('span');
  appeal.className = 'room-card-appeal';
  appeal.textContent = card.appeal;
  const worth = document.createElement('span');
  worth.className = 'room-card-worth';
  worth.append(...room.worth(room, offer));
  button.append(appeal, worth);
  button.addEventListener('click', () => chooseRoomCard(room, card, item).catch(reportError));
  item.append(button);
  return item;
}

function renderRoomCards(room, payload) {
  if (!payload || typeof payload !== 'object') {
    throw new Error(`${room.kind} offers: malformed response ${JSON.stringify(payload)}`);
  }
  const offers = room.offersOf(payload);
  if (!Array.isArray(offers) || offers.length !== ROOM_CARDS_OFFER_COUNT) {
    throw new Error(`${room.kind} offers: expected exactly ${ROOM_CARDS_OFFER_COUNT} offers, got ${JSON.stringify(offers)}`);
  }
  roomCardsNode(room, 'offers').replaceChildren(...offers.map((offer) => buildRoomCard(room, offer)));
}

// 札の部屋に着く（showScreen）。地の絵・場所の名・舞台の光を置き、札を空にして、待ちの層の下で今週の札を要求する。札と光が揃ったら
// 待ちが薄れる。失敗は待ちが夜へ沈んでから（awaitUnderPlaceVeil が報せの経路に通す）札の場所に報せともう一度を出す。設定の画面への
// 誘いは待ちごと設定の画面へ去る。
async function enterRoomCards(room) {
  const screen = screens[room.screen];
  const art = destinationArt(room.destinationId);
  screen.style.setProperty('--room-cards-art', `url('${art}')`);
  roomCardsNode(room, 'place').textContent = room.placeName;
  renderRoomCardsWeek(room);
  const offers = roomCardsNode(room, 'offers');
  delete offers.dataset.step;
  offers.replaceChildren();
  clearRoomCardsTrouble(room);
  placeVeilForArrival(room.screen);
  try {
    await awaitUnderPlaceVeil((async () => {
      const [payload, light] = await Promise.all([getJson(room.offersUrl), stageLight(art)]);
      screen.style.setProperty('--cl-light-rgb', light.join(' '));
      renderRoomCards(room, payload);
    })());
  } catch (error) {
    offers.replaceChildren();
    if (settingsRedirectErrorMessage(error) == null) showRoomCardsTrouble(room, { retry: true });
    return;
  }
  placeVeilArrived();
}

// 選んだ札が退く（最初の言葉が出揃い、相手が現れきったところ）。退ききったら札の列を札の部屋へ戻して空にする（動きを減らす設定
// では待たない。画面が閉じて動きが止められたら、待つものは無い）。
async function releaseHeldRoomCard(room) {
  await partnerEmerged();
  const offers = roomCardsNode(room, 'offers');
  offers.dataset.step = 'leaving';
  const chosen = offers.querySelector('.room-card[data-chosen]');
  void getComputedStyle(chosen).opacity;
  for (const animation of chosen.getAnimations()) {
    await animation.finished.catch((error) => {
      if (error.name !== 'AbortError') throw error;
    });
  }
  delete screens['conversation-day'].dataset.roomCardHeld;
  screens[room.screen].append(offers);
  delete offers.dataset.step;
  offers.replaceChildren();
}

// 札を選んだ。ほかの二枚が退き、選んだ札が光を帯びて会話の始まりを待つ。始まったら札の列を会話の画面へ持ち込んで移り、最初の
// 言葉を出し揃え、相手が現れきったら札を退かせる。conversationRequestInFlight は二度押しを止める（二度目は処理中の知らせ・札の釦も押せなくなる）。
async function chooseRoomCard(room, card, item) {
  if (conversationRequestInFlight) {
    showProcessingToast();
    return;
  }
  conversationRequestInFlight = true;
  conversationDayStage.setControlsDisabled(true);
  markConversationDayKind(room.kind);
  const offers = roomCardsNode(room, 'offers');
  const place = roomCardsNode(room, 'place');
  clearRoomCardsTrouble(room);
  item.dataset.chosen = '';
  offers.dataset.step = 'chosen';
  for (const button of offers.querySelectorAll('.room-card-button')) button.disabled = true;
  if (card.venue !== null) place.textContent = card.venue;
  let held = false;
  try {
    let result;
    try {
      result = await room.start(card);
    } catch (error) {
      // 始まりに失敗した: 札を三枚に戻す。設定の画面への誘いはそちらへ、ほかは札の場所に失敗の報せ（会話の画面へは移らない）。
      delete item.dataset.chosen;
      delete offers.dataset.step;
      for (const button of offers.querySelectorAll('.room-card-button')) button.disabled = false;
      place.textContent = room.placeName;
      if (!handleRuntimeApiError(error, { allowSettingsRedirect: true })) showRoomCardsTrouble(room, { retry: false });
      throw error;
    }
    // 札の列を、退いた二枚は消えたまま・選んだ札は光を帯びたまま（動きを掛け直さない段 held）会話の画面の同じ場所へ持ち込む。
    offers.dataset.step = 'held';
    screens['conversation-day'].dataset.roomCardHeld = '';
    screens['conversation-day'].append(offers);
    held = true;
    showScreen('conversation-day');
    renderConversationDayStage();
    await revealResultSequentially(conversationDayStage.surface, result);
  } finally {
    conversationRequestInFlight = false;
    conversationDayStage.setControlsDisabled(false);
    focusConversationDayInputIfContinuing();
    if (held) releaseHeldRoomCard(room).catch(reportError);
  }
}

// 依頼の始まり: POST /api/errand/start は会話と最初の言葉を1回で返す（/api/interaction/start は通らない）。応答の形を確かめてから
// 状態を採る — 相手は応答の依頼主に結ぶ（id を決め打ちしない）・会話を消してから依頼の会話 id と場面を持つ（昼の会話のターンは
// この id を運び、舞台の詳細はこの場面を読む）。形が欠けた応答は状態に触れる前に落ちる。
async function startErrandConversation(errandId) {
  const result = await postJson('/api/errand/start', { errand_id: errandId });
  if (!result.conversation || typeof result.conversation !== 'object') {
    throw new Error(`errand start: response is missing the conversation (got ${JSON.stringify(result.conversation)})`);
  }
  if (!result.state || typeof result.state !== 'object') {
    throw new Error(`errand start: response is missing state (got ${JSON.stringify(result.state)})`);
  }
  const errand = result.errand;
  if (!errand || typeof errand !== 'object') {
    throw new Error(`errand start: response is missing the errand (got ${JSON.stringify(errand)})`);
  }
  const clientCharacterId = errand.client_character_id;
  if (typeof clientCharacterId !== 'string' || clientCharacterId.trim() === '') {
    throw new Error(`errand start: response is missing the client character id (got ${JSON.stringify(clientCharacterId)})`);
  }
  // 依頼の題と様子は舞台の詳細の小窓（依頼の現場）に出る。欠けた題・様子は壊れた状態。
  if (typeof errand.title !== 'string' || errand.title.trim() === '') {
    throw new Error(`errand start: response errand is missing a title (got ${JSON.stringify(errand.title)})`);
  }
  if (typeof errand.situation !== 'string' || errand.situation.trim() === '') {
    throw new Error(`errand start: response errand is missing a situation (got ${JSON.stringify(errand.situation)})`);
  }
  const errandConversationId = result.conversation.id;
  if (typeof errandConversationId !== 'string' || errandConversationId === '') {
    throw new Error(`errand start: conversation is missing a conversation id (got ${JSON.stringify(errandConversationId)})`);
  }
  activeCharacterId = clientCharacterId;
  currentRuntimeState = result.state;
  clearVisibleConversation();
  conversationDayStage.surface.setHistory([]);
  activeErrandConversationId = errandConversationId;
  activeErrandScene = errand;
  writeDebugLog({ started_errand: errandId, character_id: clientCharacterId, conversation_id: errandConversationId, state: result.state, screen: 'conversation-day' });
  return result;
}

// 研究会の始まり（依頼の始まりと同じ形）: POST /api/study-circle/start は会話と最初の言葉を1回で返す。相手は応答の主催に結び、
// 会話を消してから研究会の会話 id と場面（会の種類の名・集まる所・様子）を持つ。
async function startStudyCircleConversation(themeId) {
  const result = await postJson('/api/study-circle/start', { theme_id: themeId });
  if (!result.conversation || typeof result.conversation !== 'object') {
    throw new Error(`study circle start: response is missing the conversation (got ${JSON.stringify(result.conversation)})`);
  }
  if (!result.state || typeof result.state !== 'object') {
    throw new Error(`study circle start: response is missing state (got ${JSON.stringify(result.state)})`);
  }
  const studyCircle = result.study_circle;
  if (!studyCircle || typeof studyCircle !== 'object') {
    throw new Error(`study circle start: response is missing the study_circle (got ${JSON.stringify(studyCircle)})`);
  }
  const hostCharacterId = studyCircle.host_character_id;
  if (typeof hostCharacterId !== 'string' || hostCharacterId.trim() === '') {
    throw new Error(`study circle start: response is missing the host character id (got ${JSON.stringify(hostCharacterId)})`);
  }
  // 会の種類の名・集まる所・様子は舞台の詳細の小窓に出る。欠けたものは壊れた状態。
  if (typeof studyCircle.theme_name !== 'string' || studyCircle.theme_name.trim() === '') {
    throw new Error(`study circle start: response study_circle is missing a theme_name (got ${JSON.stringify(studyCircle.theme_name)})`);
  }
  if (typeof studyCircle.venue !== 'string' || studyCircle.venue.trim() === '') {
    throw new Error(`study circle start: response study_circle is missing a venue (got ${JSON.stringify(studyCircle.venue)})`);
  }
  if (typeof studyCircle.situation !== 'string' || studyCircle.situation.trim() === '') {
    throw new Error(`study circle start: response study_circle is missing a situation (got ${JSON.stringify(studyCircle.situation)})`);
  }
  const studyCircleConversationId = result.conversation.id;
  if (typeof studyCircleConversationId !== 'string' || studyCircleConversationId === '') {
    throw new Error(`study circle start: conversation is missing a conversation id (got ${JSON.stringify(studyCircleConversationId)})`);
  }
  activeCharacterId = hostCharacterId;
  currentRuntimeState = result.state;
  clearVisibleConversation();
  conversationDayStage.surface.setHistory([]);
  activeStudyCircleConversationId = studyCircleConversationId;
  activeStudyCircleScene = studyCircle;
  writeDebugLog({ started_study_circle: themeId, character_id: hostCharacterId, conversation_id: studyCircleConversationId, state: result.state, screen: 'conversation-day' });
  return result;
}

for (const room of Object.values(ROOM_CARD_ROOMS)) {
  roomCardsNode(room, 'retry').addEventListener('click', () => enterRoomCards(room).catch(reportError));
}

async function editUserMessageAtIndex(messageIndex) {
  if (conversationRequestInFlight) {
    showProcessingToast();
    return;
  }
  if (!hasConversationEditItem()) return;
  const original = messageHistory[messageIndex];
  if (!original || original.role !== 'user') return;
  const editedContent = window.prompt('この発言を編集します。編集した発言まで会話を巻き戻し、以降の返答を再生成します。', original.content ?? '');
  if (editedContent === null) return;
  const content = editedContent.trim();
  if (!content || content === (original.content ?? '').trim()) return;
  if (!window.confirm('この発言より後の会話を破棄して、編集後の内容から再開します。よろしいですか？')) return;

  conversationRequestInFlight = true;
  setConversationControlsDisabled(true);
  try {
    renderMessageStream([
      ...messageHistory.slice(0, messageIndex),
      { ...original, content }
    ]);
    // The regenerated reply streams like any turn: each utterance is revealed on its assistant_complete, and the
    // controls stay closed until the result (the end of the turn's post-processing).
    const result = await runAssistantSseStream({
      surface: academyChatSurface,
      endpoint: '/api/conversation/edit-user-message/stream',
      body: {
        character_id: activeCharacterId,
        message_index: messageIndex,
        content,
        provider: conversationProvider()
      },
      statusPrefix: 'edit',
      finalAssistantMode: 'last',
      refreshAfter: false,
      onStageMove: performStageMoveTransition
    });
    await refresh();
    if (result.prompt_prewarm_error) reportConversationError(result.prompt_prewarm_error);
  } finally {
    conversationRequestInFlight = false;
    setConversationControlsDisabled(false);
  }
}

function activeConversationInputElement() {
  return document.querySelector('#academy-conversation-session-player-input');
}

async function runConversation() {
  if (conversationRequestInFlight) {
    showProcessingToast();
    return;
  }
  const playerInputElement = activeConversationInputElement();
  const playerInput = playerInputElement.value.trim();
  if (!playerInput) return;
  conversationRequestInFlight = true;
  setConversationControlsDisabled(true);
  const provider = conversationProvider();
  try {
    if (messageHistory.length === 0) await ensureOpeningUtterance();
    playerInputElement.value = '';
    renderMessageStream([
      ...messageHistory,
      { role: 'user', content: playerInput }
    ]);
    setStreamStatus(provider === 'lmstudio' ? 'stream: starting' : 'non-stream: running');
    if (provider === 'lmstudio') {
      const result = await runConversationStream({ playerInput, provider, refreshAfter: false });
      // A decided routing turn was dispatched in-turn by the SSE seam (it already revealed the
      // send-off and navigated to the destination screen after the queue drained); do not auto-end or
      // refresh the closed hub.
      if (isRoutingTurnDispatch(result)) return;
      if (await autoEndConversationAfterFinalReply(result)) return;
      await refresh();
      if (result.prompt_prewarm_error) reportConversationError(result.prompt_prewarm_error);
      return;
    }
    const result = await postJson('/api/conversation', routingTurnRequestBody({ player_input: playerInput, provider: provider }));
    if (conversationShouldAutoEnd(result) || isRoutingTurnDispatch(result) || isRoutingGraduationHandOff(result)) {
      await renderConversationResultSequentially(result);
    } else {
      renderConversationResult(result, { revealAssistant: true });
    }
    setStreamStatus('non-stream: completed');
    // The non-stream turn never reaches the SSE seam, so consume the same in-turn routing dispatch
    // here: the send-off is already on screen; dispatch to the destination before the loop auto-end.
    if (isRoutingTurnDispatch(result)) {
      await performRoutingTurnDispatch({ result, dispatch: result.routing_dispatch, overSendoff: false });
      return;
    }
    // The non-stream mirror of the graduation guide selection of an academy person (routing phase 2): the 見送り is
    // already on screen (rendered sequentially above), so open the selected character's graduation event before the
    // loop auto-end — the same landing the stream path reaches on graduation_guide_draining.
    if (isRoutingGraduationHandOff(result)) {
      await startRoutingGraduationEndingFromSelection({ result, loadingAlreadyVisible: false });
      return;
    }
    if (await autoEndConversationAfterFinalReply(result)) return;
    await refresh();
  } catch (error) {
    reportConversationError(error);
  } finally {
    conversationRequestInFlight = false;
    setConversationControlsDisabled(false);
  }
}

// Routing conversation end (drain-on-exit): the backend fully drains the pending-finalization queue
// before this request resolves, so we show the loading screen WHILE that drain runs (readiness = the
// end request) and only then navigate to the authoritative transition.next_screen — the hub dispatch
// screen (academy-map/academy-training/academy-dungeon) when routing_dispatch is present, or
// 'interaction' to return to the hub. The load screen and the transition are serialized with the drain
// (no post-processing runs in parallel with the transition, and no stall on a cleared conversation
// screen). We do not hold the loop finalization gate (routing owns its own exit UI).
async function endRoutingConversation() {
  // How the end waits, read before anything is cleared: a content conversation's end returns over the stage the
  // conversation stood on (an academy-map conversation's stage, not the map's overview) — to the terrace, or for a 錬成室
  // conversation back to the 錬成室 — and the graduation guide week's 「今日はここまで」 stays on the terrace, so its wait
  // is the terrace itself. The other hub ends (the wrap-up and the conversationless hub's end, both to the title) keep
  // the loading screen.
  const endWait = isRoutingHubActive()
    ? (isRoutingGraduationGuideActive() ? { art: null, dim: false, until: 'routing-hub', ending: 'cut' } : null)
    : (routingHubStartFailure ? null : { art: academyFieldReading.conversationStage().backgroundUrl, dim: true, until: isActiveAtelierConversation() ? 'academy-atelier' : 'routing-hub', ending: 'fade' });
  hideRoutingFinalizeBlockedNotice();
  const provider = conversationProvider();
  conversationRequestInFlight = true;
  setConversationControlsDisabled(true);
  setStreamStatus('reflection: running');
  // Capture the end-request identity AND the failure-path destination BEFORE clearVisibleConversation()
  // tears down the atelier conversation id / actor. The end request is built from this pre-clear snapshot,
  // never rebuilt from the post-clear mutable globals: a 錬成室 content-return end sends its own homunculus
  // actor id and its captured conversation id explicitly, so it depends on neither a global activeCharacterId
  // that a post-turn refresh may have reset nor the server's last_conversation_id fallback. hubActive is
  // snapshotted here for the same reason (a later clear must not move the hub/content split) and drives the
  // failure-path destination in the catch below.
  const hubActive = isRoutingHubActive();
  // The hub without a conversation (its hub start failed): its 「今日はここまで」 finds no conversation to end
  // server-side and goes on to the title gate (the conversationless branch below). Captured pre-clear like hubActive.
  const hubStartFailure = routingHubStartFailure;
  const endingAtelierConversation = isActiveAtelierConversation();
  const atelierConversationId = endingAtelierConversation ? activeAtelierConversationId : null;
  const endActorId = endingAtelierConversation ? activeAtelierActor.character_id : activeCharacterId;
  clearVisibleConversation();
  // endRoutingConversation is the end path for BOTH routing conversations that reach it: the routing hub
  // "今日はここまで" button AND a routing content-stage conversation (its content-return re-opens the hub). They
  // diverge only in the end-request opt-in. The hub end ("今日はここまで") opts into the explicit backend title
  // wrap-up with wrap_up:'title' — an undecided hub has no decided destination, so a plain end 409s; wrap_up
  // drains the whole pending-finalization queue and returns the decided-title dispatch shape
  // (finalization_status:'drained', routing_dispatch.destination_id:'title', transition.next_screen:'title'),
  // consumed by the title branch below via showRoutingWrapUpTitleTransition. EXCEPT the graduation guide week:
  // while routing_graduation_guide is present, the backend 409s an explicit wrap_up (the guide week has no
  // graduation-avoidance exit), and only a wrap_up-absent hub end reaches the guide continuation contract
  // (finalization_status:'idle' + graduation_guide + transition.next_screen:'interaction', stay on the hub),
  // handled by the graduation_guide branch below — so the wrap_up opt-in is additionally gated on
  // isRoutingGraduationGuideActive() being false. A non-hub routing content conversation must NOT send wrap_up
  // (the backend 400s wrap_up outside a routing hub conversation) and takes the plain content-return end that
  // re-opens the hub. The captured hubActive is the exact hub/non-hub split (the hub sets routingHubConversationId;
  // dispatching to content clears it). The dispatch fail-fast validation (drained / allowed destination /
  // transition agreement) is unchanged for both; on error a hub end returns to the hub while a content end stays
  // on its conversation screen (see the catch below).
  const endBody = { character_id: endActorId, provider };
  if (hubActive && !isRoutingGraduationGuideActive()) endBody.wrap_up = 'title';
  // The 錬成室 content-return end sends its captured conversation id explicitly rather than leaning on the
  // server's last_conversation_id fallback, so the backend's active-atelier actor/id match is checked
  // against the real homunculus conversation even if the global actor had drifted.
  if (endingAtelierConversation) endBody.conversation_id = atelierConversationId;
  // The hub end names the hub conversation for the same reason: a conversation post-processing retry that
  // finalizes an older conversation moves the server's last_conversation_id onto it, so the end that the
  // emergency exit re-runs after 「もう一度」 would otherwise resolve to that older conversation.
  if (hubActive) endBody.conversation_id = routingHubConversationId;
  const endRequest = postJson('/api/conversation/end', endBody);
  try {
    // Hold the wait up until the drain-backed request returns (the target is resolved from the response below): over
    // the place (endWait), or on the loading screen.
    if (endWait) {
      raisePlaceVeil(endWait);
      await awaitUnderPlaceVeil(endRequest);
    } else {
      await showAcademyLoadingScreenUntilReady({
        readiness: endRequest,
        nextScreen: null,
        loadingCopy: ROUTING_EXIT_DRAIN_LOADING_COPY
      });
    }
    const result = await endRequest;
    // The drain request resolved. Release the in-flight flag NOW — before the post-response validation +
    // navigation, whose 'interaction' content-return re-enters enterRoutingHub and needs a settled flag —
    // rather than in a finally that would run only after that navigation. The finally below is the
    // idempotent backstop for the failure path where the request threw before reaching here.
    conversationRequestInFlight = false;
    setConversationControlsDisabled(false);
    writeDebugLog(result);
    if (hubStartFailure) {
      // The conversationless hub's end: the server has no conversation to end and answers exactly with the skip
      // (reason no_active_conversation, no dispatch). Anything else is a contract violation and fails fast. There is
      // nothing to drain, so the exit goes straight on to the title gate like the wrap-up.
      if (result.skipped !== true || result.reason !== 'no_active_conversation' || result.routing_dispatch != null) {
        throw new Error(`routing hub end without a conversation: expected the no_active_conversation skip, got ${JSON.stringify({ skipped: result.skipped, reason: result.reason, routing_dispatch: result.routing_dispatch })}`);
      }
      clearRoutingHubStartFailure();
      await showRoutingWrapUpTitleTransition();
      return;
    }
    const dispatch = result.routing_dispatch ?? null;
    if (result.graduation_guide) {
      // Graduation guide start / continue via the end button ("今日はここまで"): routing week 50 cannot leave
      // graduation, so the backend keeps the hub (guide) conversation ALIVE and returns the graduation_guide
      // contract with no routing_dispatch (guide start = finalization 'drained', a later guide 今日はここまで =
      // 'idle'; neither is a title wrap-up nor a destination dispatch). A dispatch alongside it is a backend
      // contract violation — fail fast rather than mis-routing to a destination screen. Stay on the hub: keep
      // routingHubConversationId, adopt the post-state (so the week counter reads 第50週 / 50), return to the hub
      // screen from the drain loading screen, and reveal ルミ's guide reply through the hub's own reveal so the
      // conversation continues (composer enabled — the in-flight flag was already released above).
      if (dispatch) {
        throw new Error('routing graduation guide end returned both graduation_guide and routing_dispatch (mutually exclusive)');
      }
      // The guide contract guarantees state; a missing/invalid state is a backend contract violation — fail fast
      // rather than silently keeping stale pre-guide state (no ?? default-value fallback, matching the dispatch
      // branch below and the selection path).
      if (!result.state || typeof result.state !== 'object') {
        throw new Error(`routing graduation guide end is missing state (got ${JSON.stringify(result.state)})`);
      }
      currentRuntimeState = result.state;
      showScreen('routing-hub');
      await revealResultSequentially(routingHubStage.surface, result);
      return;
    }
    if (dispatch) {
      // A hub dispatch resolves to a known destination. The backend fully drained the queue before
      // responding (drain-on-exit), so every destination reports 'drained'. Validate the finalization
      // status and the screen against the authoritative transition; an unknown destination_id or a
      // disagreeing transition fail-fasts.
      assertRoutingDispatchFinalization(dispatch, result.finalization_status);
      const dispatchScreen = validateRoutingDispatchScreen(dispatch);
      if (result.transition?.next_screen !== dispatchScreen) {
        throw new Error(`routing dispatch: transition screen ${JSON.stringify(result.transition?.next_screen)} does not match dispatch screen ${dispatchScreen}`);
      }
      // The dispatch's post-dispatch state is authoritative (the queue was drained / week progressed
      // server-side); a missing/invalid state is a contract violation, not a cue to keep stale runtime
      // state (matches performRoutingTurnDispatch).
      if (!result.state || typeof result.state !== 'object') {
        throw new Error(`routing dispatch: conversation end is missing post-dispatch state (got ${JSON.stringify(result.state)})`);
      }
      currentRuntimeState = result.state;
      // The hub conversation is over; drop the routing actor/id so the destination screen and any later
      // normal interaction are not treated as a routing hub.
      clearRoutingHubConversation();
      if (dispatchScreen === 'title') {
        // Wrap up (区切りをつける): the backend already fully drained the pending-finalization queue
        // before responding, so leave play mode and return to the title screen — no post-processing runs
        // in parallel with the transition.
        await showRoutingWrapUpTitleTransition();
        return;
      }
      await navigateToPostContentScreen(result.transition?.next_screen, {
        loadingCopy: routingDispatchLoadingCopy(dispatch),
        copyKey: result.transition?.loading_copy_key ?? null,
        routingArrival: routingArrivalFromDispatch(dispatch)
      });
      return;
    }
    // Content-return (no hub dispatch): the backend fully drained the pending-finalization queue before
    // responding (drain-on-exit), so the queue is empty at this transition. A missing/unexpected
    // finalization_status fail-fasts rather than transitioning on a partial response. Drop the routing
    // actor/id and re-open the hub.
    assertDrainedRoutingFinalization(result.finalization_status);
    currentRuntimeState = result.state ?? currentRuntimeState;
    clearRoutingHubConversation();
    if (endingAtelierConversation) {
      // The 錬成室 conversation returns to the 錬成室 over the wait raised for it (endWait): a disagreeing transition
      // fail-fasts rather than landing elsewhere under a wait raised for the 錬成室.
      if (result.transition?.next_screen !== 'academy-atelier') {
        throw new Error(`atelier conversation end: transition screen ${JSON.stringify(result.transition?.next_screen)} is not academy-atelier`);
      }
      await returnToAtelierUnderPlaceVeil();
      return;
    }
    // A content-return is a routing arrival too (strict field refresh, the academy-map arrival); it carries no
    // dispatch, so it has no destination name.
    await navigateToPostContentScreen(result.transition?.next_screen, {
      loadingCopy: null,
      copyKey: result.transition?.loading_copy_key ?? null,
      routingArrival: { destinationLabel: null }
    });
  } catch (error) {
    // Single defense line over the WHOLE routing end — the drain request AND the post-response validation
    // / navigation: neither may strand the player on the academy-loading screen. A settings-redirect error
    // (invalid LLM output / LM Studio config/connection) was already routed to the settings screen by
    // showAcademyLoadingScreenUntilReady's reportLoadingError or enterRoutingHub; for any other failure — a
    // failed end request OR a post-response contract violation such as a non-'drained' finalization_status
    // on an already-finalized stale end — return to the hub with the cause shown so the loading screen is
    // never terminal. Fail-fast is preserved: the error is surfaced, not swallowed, and no transition is
    // fabricated on a bad response.
    if (settingsRedirectErrorMessage(error) == null) {
      // A wait over the place sinks into the night before the recovery destination comes up.
      if (placeVeilWaiting()) await stopPlaceVeil();
      // Discriminate the recovery destination by conversation kind (captured pre-clear). A hub end failure
      // returns to the routing hub with the cause on the hub status. A content-return end failure (錬成室 /
      // errand / study circle daytime) must NOT eject to the hub — that would surface the pre-content hub
      // history as if it were the live conversation — so it stays on the content conversation screen
      // (conversation-day) with the cause shown on that screen's status line.
      // A hub end refused by a blocked post-processing queue shows the emergency exit instead of the cause.
      if (hubStartFailure) {
        // The conversationless hub's end failed: land on the same hub-start failure landing again (the cause stays on
        // the console).
        console.error(error);
        showRoutingHubStartFailure(hubStartFailure);
      } else if (hubActive && isPendingFinalizationsBlockedError(error)) {
        showScreen('routing-hub');
        routingHubStage.setStatus('');
        showRoutingFinalizeBlockedNotice(endRoutingConversation);
      } else if (hubActive) {
        showScreen('routing-hub');
        routingHubStage.setStatus(errorDisplayMessage(error), { tone: 'error' });
      } else {
        showScreen('conversation-day');
        conversationDayStage.setStatus(errorDisplayMessage(error), { tone: 'error' });
      }
    }
  } finally {
    // Idempotent backstop: if the request phase threw before the mid-try release above, clear in-flight /
    // controls here. A repeat clear after a successful release is a no-op.
    conversationRequestInFlight = false;
    setConversationControlsDisabled(false);
  }
}

// The 錬成室 conversation's return to the 錬成室, under the wait over the 錬成室's stage: the routing arrival's strict field
// refresh runs under the wait, then the 錬成室 shows (its GET /api/atelier re-renders the slots) and the wait fades into
// it. Like navigateToPostContentScreen, a failed refresh never renders the 錬成室 on a stale field: the wait has sunk into
// the night (awaitUnderPlaceVeil) and, short of a settings redirect, the player returns to the hub.
async function returnToAtelierUnderPlaceVeil() {
  const routingArrival = { destinationLabel: null };
  try {
    await awaitUnderPlaceVeil(refresh({ strictField: true }));
    showScreen('academy-atelier', { routingArrival });
  } catch (error) {
    if (settingsRedirectErrorMessage(error) == null) await returnToRoutingHubThroughLoadingScreen({ failedArrival: routingArrival });
  }
}

// A routing turn result carries an in-turn dispatch when the play mode is routing and the decided hub
// turn attached routing_dispatch. The backend only attaches it on a decided routing turn (a loop turn
// never carries it), so this is naturally routing-gated.
function isRoutingTurnDispatch(result) {
  return currentPlayMode === 'routing' && Boolean(result?.routing_dispatch);
}

// In-turn routing dispatch: a decided routing hub turn carries the send-off utterance plus the
// dispatch payload, the same way a field turn carries a stage move. The send-off has already been
// revealed by the caller; consume the dispatch the way the in-turn stage move does — validate the
// dispatch and its destination against the authoritative transition, adopt the post-dispatch state
// (the queue was drained / week progressed server-side, so we never re-apply it), and move to the
// destination screen. overSendoff (the hub terrace's in-turn send-off) waits over the send-off curtain filled with the
// destination's art (raiseSendoffPlaceVeil — already raised when the 見送り読みポーズ outlasted the drain); the other
// dispatches (the send-off resumed after the blocked post-processing, the legacy conversation surfaces) have no curtain
// and wait on the loading interstitial. This is NOT the conversation-end / content-return path
// (navigateToPostContentScreen): a content destination (academy-map/academy-training/academy-dungeon) never re-opens
// the hub, and the wrap-up destination ('title') leaves play mode for the title screen.
async function performRoutingTurnDispatch({ result, dispatch, overSendoff }) {
  if (typeof overSendoff !== 'boolean') throw new Error(`routing dispatch: overSendoff must be a boolean, got ${JSON.stringify(overSendoff)}`);
  const dispatchScreen = validateRoutingDispatchScreen(dispatch);
  // Drain-on-exit: the backend fully drained the pending-finalization queue before responding, so every
  // destination (the wrap-up 'title' and the three content destinations) reports 'drained'. Assert it.
  assertRoutingDispatchFinalization(dispatch, result.finalization_status);
  if (result.transition?.next_screen !== dispatchScreen) {
    throw new Error(`routing dispatch: transition screen ${JSON.stringify(result.transition?.next_screen)} does not match dispatch screen ${dispatchScreen}`);
  }
  // The decided turn's post-dispatch state is authoritative (the queue was drained / week progressed
  // server-side); a missing/invalid state is a contract violation, not a cue to silently keep stale
  // runtime state.
  if (!result.state || typeof result.state !== 'object') {
    throw new Error(`routing dispatch: turn result is missing post-dispatch state (got ${JSON.stringify(result.state)})`);
  }
  currentRuntimeState = result.state;
  // The decided turn ends the hub conversation and dispatches onward; drop the routing actor/id so the
  // destination screen and any later normal interaction are not treated as a hub.
  clearRoutingHubConversation();
  if (dispatchScreen === 'title') {
    // Wrap up (区切りをつける): the backend already fully drained the pending-finalization queue before
    // responding, so leave play mode and return to the title screen — the drain and the title
    // transition are serialized, never running in parallel.
    await showRoutingWrapUpTitleTransition();
    return;
  }
  if (overSendoff && !placeVeilWaiting()) raiseSendoffPlaceVeil(dispatch.destination_id);
  if (dispatchScreen === 'academy-map') {
    // A map dispatch satisfies the routing arrival's strict field refresh + placement reroll contract, then
    // auto-starts a pending event (学院マップを経ずにイベント直行) when one is startable — the same
    // loading-covered event route the loop 鍛錬→学院マップ path uses.
    // The originating hub turn is still in-flight, so the event start opts into allowDuringInFlight (the
    // errand achievement auto-end 流儀).
    await arriveAtRoutingAcademyMap({ loadingCopy: routingDispatchLoadingCopy(dispatch), allowDuringInFlight: true, routingArrival: routingArrivalFromDispatch(dispatch), overSendoff });
    return;
  }
  // The remaining content destinations (鍛錬 / ダンジョン / 依頼 / 調合 / 工房 / 研究会 / 週イベント): the dispatch
  // progressed the week server-side, so refresh the server-evaluated field (/api/field) under the loading screen
  // before the destination renders. A dungeon dispatch lands on the dungeon's prep screen like every other entry
  // to it; the player dives from there. The refresh is strict — a failed /api/field fail-fasts instead of
  // rendering the destination on a stale field. (The academy-map arrival, the only placement-reroll + event-scan
  // destination, is handled above.)
  const routingArrival = routingArrivalFromDispatch(dispatch);
  try {
    if (overSendoff) {
      await awaitUnderPlaceVeil(refresh({ strictField: true }));
      showScreen(dispatchScreen, { routingArrival });
    } else {
      await showAcademyLoadingScreenUntilReady({
        readiness: Promise.resolve(),
        nextScreen: dispatchScreen,
        refreshBeforeNextScreen: true,
        strictFieldRefresh: true,
        routingArrival,
        loadingCopy: routingDispatchLoadingCopy(dispatch)
      });
    }
  } catch (error) {
    // A failed field refresh must not render the destination on a stale field, and must not strand the
    // player on the loading screen or the wait over the curtain. reportLoadingError already surfaced it through the
    // existing discipline (LM config/connection errors redirect to settings) and the wait over the curtain has sunk into
    // the night; for any other failure, return to the hub so the player can choose again, with the failure notice naming
    // the destination. The dispatch already ended the hub conversation, so the hub is opened anew (the originating turn
    // is still in flight).
    if (settingsRedirectErrorMessage(error) == null) await returnToRoutingHubThroughLoadingScreen({ allowDuringInFlight: true, failedArrival: routingArrival });
  }
}

async function endConversation({ allowDuringInFlight = false } = {}) {
  if (conversationRequestInFlight && !allowDuringInFlight) {
    showProcessingToast();
    return;
  }
  // Routing conversations end through the hub drain-on-exit, EXCEPT the graduation conversation (routing phase 2:
  // an academy person's event on the daytime screen, or the 案内人's on the terrace — its end button 今日はここまで and
  // its auto-end both come here): it takes the shared graduation title route below (graduation-ending-complete →
  // title, leaving play mode) rather than the hub drain-on-exit. The rest of routing (hub end, content-return end)
  // still routes to endRoutingConversation.
  if (currentPlayMode === 'routing' && !isRoutingGraduationEndingConversation()) {
    await endRoutingConversation();
    return;
  }
  if (currentPlayMode === 'routing') {
    await walkGraduationRoadToTitle({ allowDuringInFlight });
    return;
  }
  const provider = conversationProvider();
  conversationRequestInFlight = true;
  setConversationControlsDisabled(true);
  conversationFinalizationInFlight = true;
  setAcademyMapNavigationDisabled(true);
  setStreamStatus('reflection: running');
  clearVisibleConversation();
  const runningLog = {
    finalization_status: 'running',
    character_id: activeCharacterId,
    state: { ...(currentRuntimeState ?? {}), current_screen: 'academy-room', current_interaction_character_id: null, pending_interaction_context: null }
  };
  writeDebugLog(runningLog);
  const endingConversation = currentRuntimeState?.pending_interaction_context?.event_flag_id === 'event.graduation_ending.ready';
  let transition = endingConversation
    ? { next_screen: 'title', loading_copy_key: 'graduation-ending-complete' }
    : { next_screen: 'academy-room', loading_copy_key: 'academy-room' };
  const finalization = (async () => {
    try {
      const result = await postJson('/api/conversation/end', { character_id: activeCharacterId, provider });
      // The graduation ending end keeps the loading screen up on this finalization (loadingReadiness = finalization)
      // while it drains + refreshes, so its two await boundaries (the end POST and the refresh) are observable and
      // are advanced here. The non-graduation end runs this drain in the background under a resolved-readiness
      // loader that has already switched away, so it stays deliberately unwired (endingConversation guard) — the
      // single-JSON manual end is not given fabricated progress.
      if (endingConversation) notifyAcademyLoadingProgress();
      writeDebugLog(result);
      transition = result.transition ?? transition;
      currentRuntimeState = result.state ?? currentRuntimeState;
      await refresh();
      if (endingConversation) notifyAcademyLoadingProgress();
      if (transition.next_screen === 'title') {
        document.body.classList.remove('play-mode');
        // The 案内人's graduation ran on the terrace with the hub conversation id held; the title terminal drops it.
        clearRoutingHubConversation();
      } else {
        ensureAcademyMapCharacterAssignments({ force: true });
      }
      setStreamStatus('reflection: completed');
    } catch (error) {
      reportError(error);
    } finally {
      conversationFinalizationInFlight = false;
      if (activeConversationFinalizationPromise === finalization) {
        activeConversationFinalizationPromise = null;
      }
      setAcademyMapNavigationDisabled(false);
    }
  })();
  activeConversationFinalizationPromise = finalization;
  const loadingReadiness = endingConversation ? finalization : Promise.resolve();
  try {
    await showAcademyLoadingScreenUntilReady({
      readiness: loadingReadiness,
      nextScreen: transition.next_screen,
      refreshBeforeNextScreen: false,
      copyKey: transition.loading_copy_key
    });
  } finally {
    conversationRequestInFlight = false;
    setConversationControlsDisabled(false);
  }
}


// 卒業の会話を終える（POST /api/conversation/end）。卒業の会話は締めず（LM を呼ばず記録も作らない）、サーバはこの要求で卒業の印を
// 立てる。卒業の終わりで終える要求を送るのはここ一箇所で、会話が終わった時点（道の材料を読んだ直後）に送る。返す約束は要求が済む
// （失敗は reportError で知らせて済む）と解ける。
function endGraduationConversation() {
  const characterId = activeCharacterId;
  conversationFinalizationInFlight = true;
  setAcademyMapNavigationDisabled(true);
  const finalization = (async () => {
    try {
      const result = await postJson('/api/conversation/end', { character_id: characterId, provider: conversationProvider() });
      writeDebugLog(result);
      if (result.transition?.next_screen !== 'title') {
        throw new Error(`graduation end: expected the title transition, got ${JSON.stringify(result.transition)}`);
      }
      currentRuntimeState = result.state ?? currentRuntimeState;
      await refresh();
    } catch (error) {
      reportError(error);
    } finally {
      conversationFinalizationInFlight = false;
      if (activeConversationFinalizationPromise === finalization) activeConversationFinalizationPromise = null;
      setAcademyMapNavigationDisabled(false);
    }
  })();
  activeConversationFinalizationPromise = finalization;
  return finalization;
}

// routing の卒業の終わり（学院の人の昼の会話・案内人の露台。終えるの釦と相手が切り上げた自動の終わりの両方がここへ来る）:
// 最後の一言が残り、場所が暮れて（露台は沈んで）星の道になり、一年に出会った人が灯って道の終わりで相手が迎え、タイトルへ戻る
// （夜の道行きの層の walkGraduationRoad）。道の人と最後の一言を読んでから会話を終える（終えたあとは道を読めない）。道も終える要求も
// LM を呼ばない。終える要求は道と並んで走り、道の終わりの場面で、それが済むのを待ってからタイトルへ移る。「卒業しました。」の箱は出さない。
async function walkGraduationRoadToTitle({ allowDuringInFlight }) {
  if (conversationRequestInFlight && !allowDuringInFlight) {
    showProcessingToast();
    return;
  }
  const from = screens['routing-hub'].classList.contains('active') ? 'hub' : screens['conversation-day'].classList.contains('active') ? 'day' : null;
  if (from === null) throw new Error(`graduation road: the graduation conversation must be on the daytime screen or the terrace, got ${currentActiveScreenName()}`);
  conversationRequestInFlight = true;
  setConversationControlsDisabled(true);
  try {
    const road = await getJson('/api/graduation/road');
    const ended = endGraduationConversation();
    await metaJourney.walkGraduationRoad({
      road,
      from,
      ending: () => ended,
      onDusk: () => {
        graduationRoadMusic = true;
        syncBgmForUiState();
      },
      onStarLit: playGraduationRoadNote
    });
    document.body.classList.remove('play-mode');
    // 案内人の卒業は露台の会話の id を持ったまま進んだので、タイトルの終わりで外す。
    clearRoutingHubConversation();
    graduationRoadMusic = false;
    showScreen('title');
  } finally {
    graduationRoadMusic = false;
    conversationRequestInFlight = false;
    setConversationControlsDisabled(false);
  }
}

// Read the backend-resolved play mode + entry screen from a new-game / load / slots response.
// The mode wiring is explicit on both sides: an absent field or an unrecognized mode is a
// fail-fast, never a silent fall-through to the loop route (the backend already fail-fasts on a
// corrupt/unknown sidecar, so a successful response is loop or routing).
function resolvePlayModeEntryRoute(result, source) {
  const mode = result?.active_play_mode?.mode;
  if (mode !== 'loop' && mode !== 'routing') {
    throw new Error(`${source}: unexpected active_play_mode.mode ${JSON.stringify(mode)}`);
  }
  const postContentScreen = result?.post_content_screen;
  if (typeof postContentScreen !== 'string' || postContentScreen === '') {
    throw new Error(`${source}: missing post_content_screen`);
  }
  return { mode, postContentScreen };
}

// Routing entry: open the hub conversation (the routing guide on the lina slot) on the conversation
// session screen (academy-conversation-session), which shares its stream/renderer with the interaction
// screen. POST /api/routing/hub/start sets the interaction session and returns the opening (迎え)
// utterance in one call; it is rendered through the existing conversation UI. The hub-return screen is
// the conversation session screen too, so every routing-hub entry (the 3 play entries and content
// return) lands there rather than on the field interaction screen. Routing requires LM Studio, so an
// LM-config error is surfaced to the settings screen rather than silently degrading to loop.
// allowDuringInFlight is the explicit opt-in for the one caller that re-opens the hub from inside a
// still-in-flight originating turn — the errand achievement auto-end (completeErrandFromTurnResult →
// navigateToPostContentScreen('interaction')), which runs before its turn's finally clears the flag. It
// mirrors endConversationDay({ allowDuringInFlight: true }) for the cutoff auto-end: the transition is
// permitted by an explicit flag, never by clearing conversationRequestInFlight early. Every other caller
// (the 3 play entries, training / content return) omits it and keeps the in-flight guard as a re-entry block.
// failedArrivalScreen is the screen of a destination reached without a dispatch whose load failed and sent the player
// back: the hub start names that destination by id, and this resolves to its name in routing_destinations (null otherwise).
async function enterRoutingHub({ allowDuringInFlight = false, failedArrivalScreen = null } = {}) {
  if (conversationRequestInFlight && !allowDuringInFlight) {
    showProcessingToast();
    return null;
  }
  conversationRequestInFlight = true;
  setConversationControlsDisabled(true);
  hideRoutingFinalizeBlockedNotice();
  try {
    // Drain-on-exit owns post-processing: the exit that returned to the hub fully drained the queue
    // before transitioning here, so the hub opening starts immediately with no entry pre-drain wait.
    const result = await postJson('/api/routing/hub/start', failedArrivalScreen === null ? {} : { failed_arrival_screen: failedArrivalScreen });
    // The hub start carries the destination catalog's ids and names: the terrace names the destinations in the guide's
    // words from it, and a failed arrival's name is read from it by id.
    hubTerrace.setDestinations(result.routing_destinations);
    if (failedArrivalScreen !== null && typeof result.failed_arrival?.destination_id !== 'string') {
      throw new Error(`routing hub start: missing failed_arrival.destination_id for ${failedArrivalScreen}`);
    }
    const failedArrivalLabel = failedArrivalScreen === null ? null : hubTerrace.destinationLabel(result.failed_arrival.destination_id);
    // The hub-start POST and the refresh below are the two observed await boundaries every routing hub entry shares
    // (the 3 play entries via enterRoutingHubFromPlayEntry, the returns from a place via returnToRoutingHubFromPlace,
    // the conversation-end and dungeon-exit hub returns, and the failed-arrival returns). Advancing the constellation
    // here — the loader's, or the place veil's — covers all of them at once; a no-op on the direct in-turn re-open
    // where neither is up.
    notifyAcademyLoadingProgress();
    // Pin the routing persona actor and remember the hub conversation id before refresh(): the id keeps
    // refreshCharacters() from resetting the actor to the roster head, and drives the routing display
    // model + deterministic turn continuation. Fail-fast if the response is not a routing hub.
    enterRoutingHubConversation(result.conversation);
    clearRoutingHubStartFailure();
    // Register ルミ's non-selectable visual (the effective routing_lumi_<variant> set) so her face /
    // standee / speaker icon render her own art. Fail-fast if the response omits it — no blank / roster-head fallback.
    registerRoutingPersonaVisual(result.routing_persona_visual);
    clearVisibleConversation();
    routingHubStage.surface.setHistory([]);
    writeDebugLog({ started_routing_hub: true, character_id: activeCharacterId, state: result.state });
    await refresh();
    markTerraceGraduation(isRoutingGraduationGuideActive());
    notifyAcademyLoadingProgress();
    showScreen('routing-hub');
    // The returned week's fade waits for a hub start that answered (its routing_destinations name the place), so the
    // conversationless hub a failed start lands on never paints it.
    hubTerrace.hubStarted(currentRuntimeState);
    await revealResultSequentially(routingHubStage.surface, result);
    await Promise.all([refreshPrompt(), refreshRecordStatus()]);
    return failedArrivalLabel;
  } catch (error) {
    if (handleRuntimeApiError(error, { allowSettingsRedirect: true })) return null;
    throw error;
  } finally {
    conversationRequestInFlight = false;
    setConversationControlsDisabled(false);
  }
}

// Loading copy for the routing play entries (new game / slot load / resume), shown WHILE the
// non-streaming POST /api/routing/hub/start runs, before the hub screen reveals the persona's 迎え
// opening. The persona name is per-variant and not yet resolved at this point, so the copy names the
// guide generically rather than a specific variant.
const ROUTING_HUB_ENTRY_LOADING_COPY = Object.freeze({
  title: 'ハブへ移動しています',
  status: '案内人が出迎えの支度をしています。'
});

// Requested routing entry flow (押下→ロード画面→hub 表示): the three routing play entries (new game /
// slot load / resume) show the academy loading screen while the non-streaming hub start runs, then
// enterRoutingHub switches to the routing hub screen and reveals the 迎え opening the moment the start
// resolves — so the entry never looks unresponsive under the still-visible previous screen. This entry
// wrapper is routing-only; the loop entries keep their direct academy-map/academy-room landing (no
// loading screen) and stay byte-equivalent. The failure contract is unchanged and the loading screen is
// never terminal: a settings-redirect hub-start error (LM unset) already left the loading screen for the
// settings screen inside enterRoutingHub; any other error threw before the hub switch (so the loading
// screen is still active), so un-strand back to the entry's origin screen — the existing error path —
// and rethrow. A post-switch failure (already on the hub) leaves the hub screen up, matching the
// pre-loading-screen behavior.
async function enterRoutingHubFromPlayEntry(originScreen) {
  setAcademyLoadingDestinationCopy(null, { loadingCopy: ROUTING_HUB_ENTRY_LOADING_COPY });
  showScreen('academy-loading');
  try {
    await enterRoutingHub();
  } catch (error) {
    if (document.querySelector('#academy-loading-screen')?.classList.contains('active')) {
      showScreen(originScreen);
    }
    throw error;
  }
}

// Return to the routing hub from the place the player went this week (週を締める・実践から戻る・達成で自動に終わる会話):
// the wait stands on that place's art (raisePlaceVeil — returnedPlaceArt) WHILE the non-streaming hub start runs, and once
// enterRoutingHub shows the hub the place fades into the terrace's moonlit night — so the player is never left on a
// silent content screen during the return request and never sees a copy box. When the wait is already standing on the place (the drain of an exit or an achievement
// auto-end raised it), the hub start continues under it. allowDuringInFlight is the errand / study circle achievement
// auto-return's opt-in: it runs inside the daytime turn's still-in-flight window, so the flag is threaded straight to
// enterRoutingHub's re-entry gate. A failed hub start lands on the hub without a conversation (openRoutingHubUnderCover).
async function returnToRoutingHubFromPlace({ allowDuringInFlight = false } = {}) {
  // 露台の支度が始まった: 場所の絵の上の待ちが既にあればその下で続け、無ければ待ちを上げる。
  if (!placeVeilWaiting()) raisePlaceVeil({ art: returnedPlaceArt(currentRuntimeState), dim: true, until: 'routing-hub', ending: 'fade' });
  await openRoutingHubUnderCover({ allowDuringInFlight, failedArrivalScreen: null, startFailure: { destinationLabel: null } });
}

// Return to the routing hub after a destination's arrival failed, through the loading interstitial with the hub-entry
// copy. failedArrival (routingFailedArrival's { destinationLabel } or { screen }) is the destination whose arrival
// failed and sent the player back: once the hub is open again its status line carries the failure notice naming it —
// by the dispatch's label, or for { screen } by the label the hub start answers for that screen. Resolves true only when
// the hub conversation is open, so the notice never overwrites the hub-start failure landing.
async function returnToRoutingHubThroughLoadingScreen({ allowDuringInFlight = false, failedArrival }) {
  if (failedArrival === null || typeof failedArrival !== 'object') {
    throw new Error(`routing hub return through the loading screen: failedArrival is required, got ${JSON.stringify(failedArrival)}`);
  }
  const failedArrivalScreen = failedArrival.screen ?? null;
  setAcademyLoadingDestinationCopy(null, { loadingCopy: ROUTING_HUB_ENTRY_LOADING_COPY });
  showScreen('academy-loading');
  const { opened, failedArrivalLabel } = await openRoutingHubUnderCover({
    allowDuringInFlight,
    failedArrivalScreen,
    startFailure: { destinationLabel: failedArrivalScreen !== null ? null : failedArrival.destinationLabel }
  });
  if (opened) {
    showRoutingHubFailureNotice({ destinationLabel: failedArrivalScreen === null ? failedArrival.destinationLabel : failedArrivalLabel });
  }
  return opened;
}

// Open the hub under the cover the caller has already raised — the loading screen or the place veil. A settings-redirect
// hub-start error already left the cover for the settings screen inside enterRoutingHub (nothing is shown here); any other
// hub-start failure threw before the hub switch (the cover is still up), so it lands on the hub without a conversation
// (showRoutingHubStartFailure) instead of stranding the player under the cover — a place veil first sinks into the night.
// A post-switch failure (already on the hub) is rethrown to the caller.
async function openRoutingHubUnderCover({ allowDuringInFlight, failedArrivalScreen, startFailure }) {
  let failedArrivalLabel;
  try {
    failedArrivalLabel = await enterRoutingHub({ allowDuringInFlight, failedArrivalScreen });
  } catch (error) {
    if (placeVeilWaiting()) await stopPlaceVeil();
    else if (!isAcademyLoadingScreenActive()) throw error;
    console.error(error);
    showRoutingHubStartFailure(startFailure);
    return { opened: false, failedArrivalLabel: null };
  }
  return { opened: isRoutingHubActive(), failedArrivalLabel };
}

// A routing destination's arrival fetch failed on the screen it landed on: without it the screen has nothing to go on
// with (no board, no held exit), so return to the hub — opened anew, because the dispatch already ended the hub
// conversation — with the failure notice naming the destination (failedArrival: routingFailedArrival's), the same
// exit a failed arrival loading takes. The cause itself stays on the console. An LM config/connection failure goes to
// the settings screen instead.
function returnToRoutingHubAfterArrivalFailure(error, failedArrival) {
  console.error(error);
  if (handleRuntimeApiError(error, { allowSettingsRedirect: true })) return;
  returnToRoutingHubThroughLoadingScreen({ failedArrival }).catch(reportError);
}

// The destination name a routing arrival carries: the dispatch's label, or null for a dev entry that did not come
// through a dispatch.
function routingArrivalDestinationLabel(routingArrival) {
  return routingArrival === null ? null : routingArrival.destinationLabel;
}

// The failed arrival a hub return names: the dispatch's arrival ({ destinationLabel }) when a routing hub dispatch
// landed on the screen, otherwise the screen itself ({ screen }) — an entry that did not come through a dispatch (the
// dev ?initialScreen entry, the reload resume) — whose name the hub start answers from the destination catalog.
function routingFailedArrival(routingArrival, screen) {
  return routingArrival === null ? { screen } : routingArrival;
}

// The routing arrival a dispatch lands with: its destination_label names the destination on a failure notice. The
// label is required (the same contract routingDispatchLoadingCopy holds).
function routingArrivalFromDispatch(dispatch) {
  const label = dispatch?.destination_label;
  if (typeof label !== 'string' || label === '') {
    throw new Error('routing dispatch: missing destination_label');
  }
  return { destinationLabel: label };
}

// 失敗の紋: 途切れた星の道 — two star points joined by a path that breaks off midway. It carries the failure on the
// status lines of the landings a failed destination load leads to, beside the destination's name (the dispatch's
// destination_label); the English cause stays on the console.
const ROUTING_FAILURE_GLYPH_SVG = '<svg class="routing-failure-glyph" viewBox="0 0 40 20" aria-hidden="true" focusable="false">'
  + '<path class="routing-failure-glyph-star" d="M5 4.5 6.1 8.9 10.5 10 6.1 11.1 5 15.5 3.9 11.1-.5 10 3.9 8.9z"/>'
  + '<path class="routing-failure-glyph-star" d="M35 4.5 36.1 8.9 40.5 10 36.1 11.1 35 15.5 33.9 11.1 29.5 10 33.9 8.9z"/>'
  + '<path class="routing-failure-glyph-path" d="M10.8 10H16.6M23.4 10H29.2"/>'
  + '<path class="routing-failure-glyph-break" d="M18.4 7.2 19.4 9M21.6 11 20.6 12.8"/>'
  + '</svg>';

// Write the failure notice onto a status line: the mark — the glyph, then the destination name when the landing
// knows it — and, on a row of its own, the one line the landing adds, so the name never reads as the line's subject.
// A landing without a name or a line shows the glyph alone.
function writeRoutingFailureNotice(status, { destinationLabel = null, line = null }) {
  const mark = document.createElement('span');
  mark.className = 'routing-failure-mark';
  mark.innerHTML = ROUTING_FAILURE_GLYPH_SVG;
  if (destinationLabel) {
    const destination = document.createElement('span');
    destination.className = 'routing-failure-destination';
    destination.textContent = destinationLabel;
    mark.append(destination);
  }
  status.replaceChildren(mark);
  if (line) {
    const lineElement = document.createElement('span');
    lineElement.className = 'routing-failure-line';
    lineElement.textContent = line;
    status.append(lineElement);
  }
  status.hidden = false;
  status.dataset.tone = 'error';
}

// The hub status line keeps the stage's bottom-follow rule: a reader at the bottom of the stream stays there when the
// notice claims its line.
function showRoutingHubFailureNotice(notice) {
  const stream = document.querySelector('#routing-hub-message-stream');
  const stick = routingHubStage.streamIsAtBottom(stream);
  writeRoutingFailureNotice(document.querySelector('#routing-hub-status'), notice);
  if (stick) stream.scrollTop = stream.scrollHeight;
}

// The hub without a conversation: the hub start itself failed (after a failed arrival, or on a plain return such as
// 工房の「出る」). The landing holds the failure notice with its line, the glyph button that asks for the hub
// start again (retryRoutingHubStart), a closed send (there is no conversation to send into), and a
// 「今日はここまで」 that goes on to the title gate (endRoutingConversation's conversationless branch).
// routingHubStartFailure is the landing's { destinationLabel } while it is up, null otherwise.
const ROUTING_HUB_START_FAILED_LINE = '今は、会話を始められませんでした';
let routingHubStartFailure = null;

function showRoutingHubStartFailure(startFailure) {
  routingHubStartFailure = startFailure;
  showScreen('routing-hub');
  showRoutingHubFailureNotice({ destinationLabel: startFailure.destinationLabel, line: ROUTING_HUB_START_FAILED_LINE });
  const retry = document.querySelector('#routing-hub-start-retry');
  retry.hidden = false;
  retry.disabled = false;
  document.querySelector('#routing-hub-send').disabled = true;
}

// The hub conversation is open again (or the conversationless hub is left for the title): drop the landing, its
// notice and its retry button, and reopen the send unless the post-processing notice keeps it stopped.
function clearRoutingHubStartFailure() {
  if (!routingHubStartFailure) return;
  routingHubStartFailure = null;
  document.querySelector('#routing-hub-start-retry').hidden = true;
  routingHubStage.setStatus('');
  if (!routingFinalizeBlockedExit) document.querySelector('#routing-hub-send').disabled = false;
}

async function retryRoutingHubStart() {
  const startFailure = routingHubStartFailure;
  if (!startFailure) throw new Error('routing hub start retry: the hub has a conversation');
  if (conversationRequestInFlight) {
    showProcessingToast();
    return;
  }
  document.querySelector('#routing-hub-start-retry').disabled = true;
  // 露台の上でやり直す: 露台の姿のまま待ち、ハブが出たらそのまま続ける（露台から露台への薄れ替わりは無い）。
  raisePlaceVeil({ art: null, dim: false, until: 'routing-hub', ending: 'cut' });
  await openRoutingHubUnderCover({ allowDuringInFlight: false, failedArrivalScreen: null, startFailure });
}

// Single-flight guard shared by the 調合 受け取る and 工房 出る hub returns so a double press never starts two
// hub-return requests (each would fire a second POST /api/routing/hub/start). Reset in the callers' finally.
let routingContentReturnInFlight = false;

// 調合の受け取り / 工房の退出はどちらも routing content の終了で、両画面とも routing 専用（backend が非 routing を
// 409）なので post_content_screen は常にハブ（'interaction'）。不明値は fail-fast（default 画面へ落とさない）で、
// ハブ復帰は鍛錬終了と同一の共有経路 returnToRoutingHubFromPlace（行ってきた場所の絵の上で待ち、露台の月夜へ薄れ替わる）を
// 流用する。専用の並行遷移機構は新設しない。
async function returnToRoutingHubFromContent(postContentScreen) {
  if (postContentScreen !== 'interaction') {
    throw new Error(`routing content return: unexpected post_content_screen ${JSON.stringify(postContentScreen)}`);
  }
  await returnToRoutingHubFromPlace();
}

// Wrap-up ('区切りをつける') dispatch loading copy: the neutral exit that returns to the title screen
// after the pending-finalization queue is fully drained (the week does not advance).
const ROUTING_WRAP_UP_LOADING_COPY = Object.freeze({
  title: '区切りをつけています',
  status: '今日の後処理を終えて、タイトルへ戻ります。'
});

// Drain-on-exit loading copy shown WHILE the end-conversation request runs the full pending-finalization
// drain server-side (the request resolves only after the drain), so the exit is visible under the
// loading screen instead of a stall on the cleared conversation screen.
const ROUTING_EXIT_DRAIN_LOADING_COPY = Object.freeze({
  title: '会話の後処理をしています',
  status: '今回の会話の後処理を終えてから、次の画面へ移ります。'
});

// The wrap-up dispatch tail, shared by the in-turn (performRoutingTurnDispatch) and end-button
// (endRoutingConversation) paths. The backend has already fully drained the pending-finalization queue
// before responding (a neutral exit that does not progress the week), so the drain and this title
// transition are serialized by construction. Leave play mode and return to the title screen through
// the loading interstitial (equivalent to showScreen('title')).
async function showRoutingWrapUpTitleTransition() {
  document.body.classList.remove('play-mode');
  await showAcademyLoadingScreenUntilReady({
    readiness: Promise.resolve(),
    nextScreen: 'title',
    refreshBeforeNextScreen: false,
    loadingCopy: ROUTING_WRAP_UP_LOADING_COPY
  });
}

// Build the dispatch loading copy from a routing hub dispatch, reflecting the chosen destination
// label in the transition UI. The label is required (no anonymous fallback copy).
function routingDispatchLoadingCopy(dispatch) {
  const label = dispatch?.destination_label;
  if (typeof label !== 'string' || label === '') {
    throw new Error('routing dispatch: missing destination_label');
  }
  return { title: `${label}へ向かいます`, status: `見送りを受けて、${label}へ移動しています。` };
}

// Navigate to a backend-resolved post-content/dispatch screen. The backend's mode-resolved next
// screen is authoritative: 'interaction' re-opens the hub conversation (the hub-and-spoke return),
// any other screen is shown through the loading interstitial. A missing/empty next screen
// fail-fasts rather than falling back to a default screen. allowDuringInFlight is forwarded to the
// 'interaction' hub re-open for the errand achievement auto-end — the one content-return that runs inside
// its still-in-flight originating turn; every other caller leaves it false and keeps the in-flight guard.
// routingArrival ({ destinationLabel } from the dispatch) marks the routing hub dispatch's arrival; null for the
// loop navigation.
async function navigateToPostContentScreen(nextScreen, { loadingCopy = null, copyKey = null, routingArrival = null, allowDuringInFlight = false } = {}) {
  if (typeof nextScreen !== 'string' || nextScreen === '') {
    throw new Error('post-content navigation: missing next screen');
  }
  if (nextScreen === 'interaction') {
    await enterRoutingHub({ allowDuringInFlight });
    return;
  }
  if (routingArrival && nextScreen === 'academy-map') {
    // The routing end-button arrival at the academy map: the sibling of the in-turn map dispatch (both
    // funnel a map arrival into the shared placement-reroll + pending-event-scan helper). The originating
    // turn already released its in-flight flag before navigating (endRoutingConversation), so the event
    // auto-start needs no allowDuringInFlight opt-in here.
    await arriveAtRoutingAcademyMap({ loadingCopy, copyKey, routingArrival });
    return;
  }
  // The routing arrival is the routing content-arrival contract: a routing dispatch progressed the week
  // server-side, so strictly refresh the server-evaluated field (/api/field) under the loading screen
  // before the destination renders (a failed /api/field fail-fasts instead of rendering a stale field). The
  // loop dungeon exit reuses this navigation for academy-room with no routing arrival, so its transition
  // stays byte-equivalent (no added refresh, resilient); the routing return to 'interaction' already
  // refreshes through enterRoutingHub above, and the routing academy-map arrival (placement reroll + pending
  // event scan) is handled above.
  const refreshField = routingArrival !== null;
  try {
    await showAcademyLoadingScreenUntilReady({
      readiness: Promise.resolve(),
      nextScreen,
      refreshBeforeNextScreen: refreshField,
      strictFieldRefresh: refreshField,
      routingArrival,
      loadingCopy,
      copyKey
    });
  } catch (error) {
    // Only the routing arrival fail-fasts here; the loop/non-routing navigation keeps its original propagation (its
    // refresh is resilient and never throws). A failed routing field refresh must not render the destination on a
    // stale field and must not strand the player on the loading screen: reportLoadingError already surfaced it (LM
    // config errors → settings); otherwise return to the hub with the failure notice naming the destination, opened
    // anew because the dispatch already ended the hub conversation.
    if (!refreshField) throw error;
    if (settingsRedirectErrorMessage(error) == null) await returnToRoutingHubThroughLoadingScreen({ allowDuringInFlight, failedArrival: routingArrival });
  }
}

// Routing academy-map arrival with pending-event auto-start. Both routing dispatch paths funnel a map destination
// here: the in-turn performRoutingTurnDispatch and the end-button navigateToPostContentScreen. The dispatch already
// validated the drained finalization and adopted the post-dispatch state upstream; this keeps the loading screen up
// while it (1) holds the minimum display and STRICTLY refreshes the week-progressed server field (the routing
// content-arrival contract — a failed /api/field fail-fasts, returns to the hub, never renders a stale
// field), then (2) fresh-scans pending events over GET /api/event-flags (never from stale client state). A
// startable pending event — an event flag carrying an interaction location + source character, the same
// predicate the loop 鍛錬→学院マップ route uses — keeps the loading screen up and hands off to the loading-aware
// event start (academy-conversation-session); the academy map is never shown, and its end returns to the hub
// through the unchanged routing content-return contract. With no pending event the reroll'd academy map is
// shown, byte-equivalent to the plain routing arrival. The event scan runs AFTER the strict field refresh so
// the routing arrival contract is fully satisfied before any divert. A failed field refresh / event scan /
// event start is never swallowed onto the map: it surfaces through reportLoadingError (or the event start's
// own loading-error handling) and returns to the hub, opened anew because the dispatch already ended the hub
// conversation. The in-turn caller is still in-flight, so it passes allowDuringInFlight through to the event start
// and the hub re-open (the errand achievement auto-end 流儀); the end-button caller already released the flag and
// leaves it false. overSendoff: the in-turn caller's wait already stands over the send-off curtain (raiseSendoffPlaceVeil),
// so no loading screen is raised here; a failure sinks that wait into the night before the hub return, and a pending
// event takes over from it with the conversation passage on its own loading screen.
async function arriveAtRoutingAcademyMap({ loadingCopy = null, copyKey = null, allowDuringInFlight = false, routingArrival, overSendoff = false }) {
  if (!overSendoff) {
    setAcademyLoadingDestinationCopy('academy-map', { copyKey, loadingCopy });
    showScreen('academy-loading');
  }
  const minimumDisplay = new Promise((resolve) => setTimeout(resolve, ACADEMY_LOADING_MINIMUM_MS));
  let autoStartFlag = null;
  try {
    // (1) Hold the loading screen through the minimum display, then the STRICT week-progressed field refresh
    // (a failed /api/field throws — the map is never rendered on a stale field). (2) The dispatch contract is
    // complete (drained + state adopted upstream, field refreshed here); fresh-scan pending events. This scan
    // is INSIDE the try so a failed /api/event-flags returns to the hub instead of silently dropping onto
    // the map.
    await minimumDisplay;
    await refresh({ strictField: true });
    notifyAcademyLoadingProgress();
    const status = await refreshEventFlagStatus();
    notifyAcademyLoadingProgress();
    autoStartFlag = (status.pending_events ?? []).find((flag) => flag.interaction?.location_id && flag.character_id);
  } catch (error) {
    // A failed strict field refresh or pending-event scan must not render the map on a stale field and must
    // not silently drop onto the map: surface it (LM config → settings) and return to the hub, opened anew because
    // the dispatch already ended the hub conversation, so the loading screen is never terminal.
    reportLoadingError(error);
    if (settingsRedirectErrorMessage(error) == null) {
      if (placeVeilWaiting()) await stopPlaceVeil();
      await returnToRoutingHubThroughLoadingScreen({ allowDuringInFlight, failedArrival: routingArrival });
    }
    return;
  }
  if (!autoStartFlag) {
    // No pending event: show the reroll'd academy map (byte-equivalent to the plain routing arrival).
    showScreen('academy-map', { rerollAcademyMap: true });
    return;
  }
  try {
    // A startable pending event: hand off to the loading-aware event start (opening stream 開始まで loading で覆う) — it
    // takes over the loading screen that is up, or raises its own conversation passage over the wait on the send-off
    // curtain; the academy map is never shown.
    await startAcademyConversationSessionFromPendingEvent(autoStartFlag.id, { loadingAlreadyVisible: !overSendoff, allowDuringInFlight });
  } catch (error) {
    // The event start already surfaced the cause through its own reportLoadingError; for a non-settings-redirect
    // failure return to the hub, opened anew like the failures above (never a silent map drop).
    if (settingsRedirectErrorMessage(error) == null) await returnToRoutingHubThroughLoadingScreen({ allowDuringInFlight, failedArrival: routingArrival });
  }
}

// ---- routing-mode finalize queue + persona settings (Stage 9b) ----
// Every function here is routing-only and additive; loop-mode play paths never reach them, so the
// loop frontend is unchanged. Post-processing is drain-on-exit: every routing exit fully drains the
// pending-finalization queue server-side before it transitions, so there is no entry pre-drain wait
// and no background idle drain — only the failed-retry UI (below) touches the queue after an exit.

// The conversation post-processing emergency exit. A hub exit (今日はここまで, a decided send-off turn, a
// graduation-guide partner turn) drains the whole pending-finalization queue server-side; when a failed job
// blocks that drain the server refuses the exit with error_code pending_finalizations_blocked. Only then does
// the hub show one line and 「もう一度」 over itself (the server's English message is never shown). 「もう一度」
// drives the retry route for every failed character; once they all pass the line disappears and the refused
// exit runs again (resumeExit). A retry that fails keeps the line and names the reason beneath it, in the
// model-list transport table's words. The refused turn is already saved server-side and the refused exit has
// closed the hub conversation there, so while the line is up the hub's send stays stopped (the button and
// Enter): a resend could only be refused, and its failure would take the line and 「もう一度」 away.
const PENDING_FINALIZATIONS_BLOCKED_ERROR_CODE = 'pending_finalizations_blocked';
const LM_STUDIO_CONNECTION_UNAVAILABLE_CODE = 'LMSTUDIO_CONNECTION_UNAVAILABLE';
let routingFinalizeBlockedExit = null;
let routingFinalizeRetryInFlight = false;

function isPendingFinalizationsBlockedError(error) {
  return error?.errorCode === PENDING_FINALIZATIONS_BLOCKED_ERROR_CODE;
}

function routingFinalizeNoticeElements() {
  return {
    notice: document.querySelector('#routing-hub-finalize-notice'),
    retry: document.querySelector('#routing-hub-finalize-retry'),
    reason: document.querySelector('#routing-hub-finalize-notice-reason')
  };
}

function setRoutingHubControlsDisabled(disabled) {
  routingHubStage.setControlsDisabled(disabled);
  if (routingFinalizeBlockedExit || routingHubStartFailure) document.querySelector('#routing-hub-send').disabled = true;
}

function setRoutingFinalizeNoticeReason(text) {
  const { reason } = routingFinalizeNoticeElements();
  reason.textContent = text;
  reason.hidden = text === '';
}

function showRoutingFinalizeBlockedNotice(resumeExit) {
  if (typeof resumeExit !== 'function') throw new Error('routing finalize notice requires the refused exit to resume');
  routingFinalizeBlockedExit = resumeExit;
  const { notice, retry } = routingFinalizeNoticeElements();
  setRoutingFinalizeNoticeReason('');
  retry.disabled = false;
  notice.hidden = false;
  document.querySelector('#routing-hub-send').disabled = true;
}

function hideRoutingFinalizeBlockedNotice() {
  const sendWasStopped = routingFinalizeBlockedExit !== null;
  routingFinalizeBlockedExit = null;
  const { notice } = routingFinalizeNoticeElements();
  setRoutingFinalizeNoticeReason('');
  notice.hidden = true;
  if (sendWasStopped && !routingHubStartFailure) document.querySelector('#routing-hub-send').disabled = false;
}

// The reason line for a failed retry: an LM transport failure reads from the model-list table; any other
// failure names its own reason. A failure with no reason at all throws (never an unnamed error).
function routingFinalizeRetryFailureMessage(error) {
  const payload = error?.payload;
  if (payload?.error_code === LM_STUDIO_CONNECTION_UNAVAILABLE_CODE) return lmStudioTransportFailureMessage(payload);
  const reason = String(payload?.error ?? error?.message ?? '').trim();
  if (!reason) throw new Error('conversation post-processing retry failed without a reason');
  return `後片づけに失敗しました: ${reason}`;
}

async function retryBlockedRoutingFinalizations() {
  const resumeExit = routingFinalizeBlockedExit;
  if (!resumeExit) throw new Error('routing finalize retry: no refused hub exit to resume');
  if (routingFinalizeRetryInFlight) return;
  if (conversationRequestInFlight) {
    showProcessingToast();
    return;
  }
  routingFinalizeRetryInFlight = true;
  const { retry } = routingFinalizeNoticeElements();
  retry.disabled = true;
  setRoutingFinalizeNoticeReason('');
  try {
    currentRuntimeState = await getJson('/api/state');
    const characterIds = [...new Set(listFailedFinalizations(currentRuntimeState).map((job) => job.character_id))];
    for (const characterId of characterIds) {
      // The POST + response validation + state persist live in the pure runFailedFinalizationRetry; a re-failed
      // job makes the retry route throw, which lands in the catch below.
      await runFailedFinalizationRetry({
        characterId,
        retry: (id) => postJson('/api/conversation/finalize/retry', { character_id: id }),
        writeState: (state) => { currentRuntimeState = state; }
      });
    }
  } catch (error) {
    setRoutingFinalizeNoticeReason(routingFinalizeRetryFailureMessage(error));
    retry.disabled = false;
    console.error(error);
    return;
  } finally {
    routingFinalizeRetryInFlight = false;
  }
  hideRoutingFinalizeBlockedNotice();
  await resumeExit();
}

// The refused exit of a decided send-off turn, run again after the retry: the send-off turn is already saved,
// so a plain hub end (no wrap_up) makes the server rebuild the same dispatch from the conversation's decided
// destination (the week progression is keyed by the conversation, so it never applies twice), and the
// in-turn dispatch path takes it to the destination.
async function resumeRoutingHubSendoffDispatch() {
  if (conversationRequestInFlight) {
    showProcessingToast();
    return;
  }
  if (!isRoutingHubActive()) throw new Error('routing send-off resume requires the hub conversation');
  const endBody = { character_id: activeCharacterId, conversation_id: routingHubConversationId, provider: conversationProvider() };
  conversationRequestInFlight = true;
  setRoutingHubControlsDisabled(true);
  const endRequest = postJson('/api/conversation/end', endBody);
  try {
    await showAcademyLoadingScreenUntilReady({
      readiness: endRequest,
      nextScreen: null,
      loadingCopy: ROUTING_EXIT_DRAIN_LOADING_COPY
    });
    const result = await endRequest;
    conversationRequestInFlight = false;
    setRoutingHubControlsDisabled(false);
    writeDebugLog(result);
    const dispatch = result.routing_dispatch ?? null;
    if (!dispatch) throw new Error('routing send-off resume: conversation end returned no routing_dispatch');
    await performRoutingTurnDispatch({ result, dispatch, overSendoff: false });
  } catch (error) {
    if (settingsRedirectErrorMessage(error) == null) {
      showScreen('routing-hub');
      if (isPendingFinalizationsBlockedError(error)) {
        routingHubStage.setStatus('');
        showRoutingFinalizeBlockedNotice(resumeRoutingHubSendoffDispatch);
      } else {
        routingHubStage.setStatus(errorDisplayMessage(error), { tone: 'error' });
      }
    }
  } finally {
    conversationRequestInFlight = false;
    setRoutingHubControlsDisabled(false);
  }
}

async function startNewGame() {
  const startButton = document.querySelector('#start-new-game');
  showTitleActionStatusWait();
  if (startButton) startButton.disabled = true;
  try {
    const result = await postJson('/api/new-game', {});
    const route = resolvePlayModeEntryRoute(result, '/api/new-game');
    writeDebugLog(result);
    academyMapSelectedLocationId = null;
    academyCompanionLocationId = null;
    academyMapCharacterAssignments = {};
    academyMapAssignmentSignature = '';
    // Entering play resets the routing hub state before refresh()/mode branch: a routing entry
    // re-adopts it via enterRoutingHub, a loop entry must not inherit a stale hub id (and its actor /
    // stage / turn-id behavior) from a prior in-run routing session.
    clearRoutingHubConversation();
    await refresh();
    await refreshSaveSlots();
    document.body.classList.add('play-mode');
    setTitleActionStatus('');
    if (route.mode === 'routing') {
      await enterRoutingHubFromPlayEntry('title');
      return;
    }
    if (await routeNewGameIntroFromTitle()) return;
    showScreen('academy-map', { rerollAcademyMap: true });
    await routePendingEventFromAcademyMap();
  } finally {
    if (startButton) startButton.disabled = false;
  }
}

async function openLoadScreen({ canResumePlay = false } = {}) {
  if (conversationFinalizationInFlight) {
    showProcessingToast();
    return;
  }
  slotLoadCanResumePlay = canResumePlay;
  await refreshSaveSlots();
  showScreen('slot-load');
}

async function loadSpecificSlot(slotId) {
  if (conversationFinalizationInFlight) {
    showProcessingToast();
    return;
  }
  const result = await postJson('/api/slots/load', { slot_id: slotId });
  const route = resolvePlayModeEntryRoute(result, '/api/slots/load');
  writeDebugLog(result);
  // Loading a slot resets the routing hub state before refresh()/mode branch: a routing slot re-adopts
  // it via enterRoutingHub (which re-opens/resumes the persisted hub), a loop slot must not inherit a
  // stale hub id from a prior in-run routing session.
  clearRoutingHubConversation();
  // A mid-phase-2 graduation slot re-enters the phase-2 conversation in place (the routing 案内人 on the terrace, a
  // routing / loop candidate in the daytime conversation, never the hub start / academy-room). This never calls
  // /api/routing/hub/start (the backend 409s an in-flight phase 2 as a defense — the normal path does not reach it).
  const graduationPhase2Reentry = parseGraduationPhase2Reentry(result, '/api/slots/load');
  if (graduationPhase2Reentry) {
    document.body.classList.add('play-mode');
    await reenterGraduationPhase2(graduationPhase2Reentry, { mode: route.mode });
    return;
  }
  await refresh();
  await refreshSaveSlots();
  document.body.classList.add('play-mode');
  if (route.mode === 'routing') {
    await enterRoutingHubFromPlayEntry('slot-load');
    return;
  }
  showScreen('academy-room');
}

async function resumePlayFromSlotLoad() {
  if (!canResumeFromSlotLoad()) return;
  document.body.classList.add('play-mode');
  // Resume does not re-load a slot, so it uses the route stored by the most recent
  // refreshSaveSlots() (the same call that sets currentActiveSlotId, which canResumeFromSlotLoad
  // already requires). An absent route is an unexpected state, not loop — fail fast rather than
  // silently degrading to the loop landing.
  if (!slotLoadEntryRoute) {
    throw new Error('resume play: no resolved /api/slots route is available');
  }
  // Resuming resets the routing hub state before the mode branch: a routing resume re-adopts it via
  // enterRoutingHub, a loop resume must not inherit a stale hub id from a prior in-run routing session.
  clearRoutingHubConversation();
  // Resume re-enters an in-flight phase-2 graduation slot the same way an explicit load does, reading the
  // re-entry contract stored from the most recent GET /api/slots (resume has no load response of its own). It
  // re-enters the phase-2 conversation in place and never calls /api/routing/hub/start (the backend 409 defense).
  if (slotLoadGraduationPhase2Reentry) {
    await reenterGraduationPhase2(slotLoadGraduationPhase2Reentry, { mode: slotLoadEntryRoute.mode });
    return;
  }
  if (slotLoadEntryRoute.mode === 'routing') {
    await enterRoutingHubFromPlayEntry('slot-load');
    return;
  }
  showScreen('academy-room');
}

async function deleteSpecificSlot(slotId) {
  const response = await fetch(`/api/slots/${encodeURIComponent(slotId)}`, { method: 'DELETE' });
  if (!response.ok) throw new Error(await response.text());
  const result = await response.json();
  writeDebugLog(result);
  // Return to title only when NOTHING is left to act on — no compatible slot AND no degraded card. While a
  // degraded slot remains, stay on the load screen so consecutive incompatible deletions complete in the UI.
  const { slots, incompatibleSlots } = await refreshSaveSlots();
  if (!slots.length && !incompatibleSlots.length) showScreen('title');
}

function isLmStudioRuntimeError(error) {
  return LM_STUDIO_RUNTIME_ERROR_CODES.has(error?.errorCode);
}

function isInvalidLlmOutputError(error) {
  return INVALID_LLM_OUTPUT_ERROR_CODES.has(error?.errorCode);
}

function lmStudioRuntimeErrorMessage(error) {
  return error?.payload?.error ?? error?.message ?? 'LM Studioの接続が確認できません。LM Studioを起動し、設定画面で接続先とモデルを確認してください。';
}

// The cause message an error should show when it is one the player fixes in the LM settings — an LM
// Studio config/connection failure, or invalid LLM output. Returns null for any other error, which is
// how callers tell a settings-redirect error apart from a plain failure.
function settingsRedirectErrorMessage(error) {
  if (isInvalidLlmOutputError(error)) return INVALID_LLM_OUTPUT_MESSAGE;
  if (isLmStudioRuntimeError(error)) return lmStudioRuntimeErrorMessage(error);
  return null;
}

function handleRuntimeApiError(error, { allowSettingsRedirect = false } = {}) {
  const message = settingsRedirectErrorMessage(error);
  if (message == null) return false;
  setStreamStatus(message, { immediate: true, tone: 'error' });
  if (!allowSettingsRedirect) return false;
  showScreen('settings');
  selectSettingsCategory('lmstudio');
  setLmStudioSettingsStatus(message);
  loadLmStudioSettings()
    .then(() => setLmStudioSettingsStatus(message))
    .catch((settingsError) => {
      setLmStudioSettingsStatus(message);
      console.error(settingsError);
    });
  return true;
}

function reportLoadingError(error) {
  if (handleRuntimeApiError(error, { allowSettingsRedirect: true })) return;
  reportError(error);
}

// 最初から始める支度を待つあいだ: 状態の行に字の代わりに画面の中の待ちの印を置く（右下で待ちの紋が回る）。
function showTitleActionStatusWait() {
  const status = document.querySelector('#title-status');
  if (!status) return;
  status.hidden = false;
  status.replaceChildren(screenWaitMark());
  status.dataset.tone = 'info';
}

function setTitleActionStatus(message, options = {}) {
  const status = document.querySelector('#title-status');
  if (!status) return;
  const text = String(message ?? '').trim();
  if (!text) {
    status.hidden = true;
    status.textContent = '';
    delete status.dataset.tone;
    return;
  }
  status.hidden = false;
  status.textContent = text;
  const tone = String(options.tone ?? '').trim();
  if (tone) status.dataset.tone = tone;
  else delete status.dataset.tone;
}

function errorDisplayMessage(error) {
  const message = error?.payload?.error ?? error?.message ?? '';
  return String(message).trim() || '最初から始める処理に失敗しました。ゲームデータ配置と起動ログを確認してください。';
}

function reportConversationError(error) {
  const message = errorDisplayMessage(error);
  setConversationStatus(message, { tone: 'error' });
  setStreamStatus(message, { immediate: true, tone: 'error' });
  console.error(error);
}

function reportError(error) {
  setStreamStatus('error');
  if (handleRuntimeApiError(error)) return;
  if (document.querySelector('#title-screen')?.classList.contains('active')) {
    setTitleActionStatus(errorDisplayMessage(error), { tone: 'error' });
  }
  console.error(error);
}

