  carry: dungeonNode('#dungeon-carry'),
  helpModal: dungeonNode('#dungeon-help-modal'),
  helpBody: dungeonNode('#dungeon-help-body'),
  retreatModal: dungeonNode('#dungeon-retreat-modal'),
