// The dungeon windows that make the board keyboard-inert (help, retreat confirm, actor detail, equipment).
const DUNGEON_MODALS = [dn.helpModal, dn.retreatModal, dn.detailModal, dn.equipModal];

const dungeonReducedMotionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
const dungeonReducedMotion = () => dungeonReducedMotionQuery.matches;
const syncDungeonMotion = () => { dungeonRoot.dataset.motion = dungeonReducedMotion() ? 'reduced' : 'full'; };
syncDungeonMotion();
dungeonReducedMotionQuery.addEventListener('change', syncDungeonMotion);

for (const node of document.querySelectorAll('#academy-dungeon-screen [data-crest]')) node.innerHTML = heroCrestSvg();
// 入る前の画面の地は実践の行き先の絵（送り出しの幕・入るときの待ちと同じ一枚 = destinationArt）。潜るの紋は盤の下り階段と同じ印、
// 同行の印は相棒の札の右下と、同行できないときの印の二か所に置く。
dungeonRoot.style.setProperty('--dungeon-entry-art', `url('${destinationArt('dungeon')}')`);
dn.dive.innerHTML = stairsDownSvg();
dn.entryTether.innerHTML = companyTetherSvg();
dn.entryApartMark.innerHTML = companyTetherSvg();

// server の応答に必ずある field を取る。欠けていれば client と server の食い違いなので止める（空の値で続けない）。
function requiredDungeonField(payload, key, label) {
  if (!payload || payload[key] === undefined || payload[key] === null) throw new Error(`${label} is missing ${key}`);
  return payload[key];
}

// A run view companion is a homunculus when it carries a face_url (the B3 schema marker — a selectable companion
// carries no face_url / parameters). Its face comes from the run view entry snapshot, not the roster.
function dungeonCompanionIsHomunculus(companion) {
  return typeof companion?.face_url === 'string' && companion.face_url !== '';
}

// The face of a dungeon companion — the one resolution the board token, the rail card, the journal line and the voice
// on the board all use. A homunculus companion's face is its entry-snapshot face_url; a selectable companion resolves
// its visual_set face (per expression) from the loaded roster. A roster miss is a real desync and throws.
function dungeonCompanionFaceUrl(companion, expression = 'neutral') {
  if (dungeonCompanionIsHomunculus(companion)) return companion.face_url;
  const character = selectableCharacters.find((entry) => entry.character_id === companion.character_id);
  if (!character?.visual_set_id) throw new Error(`dungeon companion not found in character roster: ${companion.character_id}`);
  return `/canonical/character_visual_sets/${character.visual_set_id}/face_emotions/${expression}.jpg`;
}

// Per-element effect sprite URL. The server serves /canonical/* as .png only (no extension/jpg fallback), and the
// element set is fixed — an unknown element fails fast rather than guessing a sprite.
function dungeonEffectAssetUrl(element, part) {
  if (!DUNGEON_EFFECT_ELEMENTS.includes(element)) throw new Error(`dungeon effect: unknown element ${element}`);
  return `/canonical/dungeon/effects/${element}_${part}.png`;
}

async function refreshDungeonScreen() {
  // The companion faces resolve from the loaded character roster. Boot loads the roster before the dungeon is
  // reachable, so this is a no-op in the normal flow; ensuring it here makes the screen self-sufficient. A fetch
  // failure throws (fail-fast) — an explicit precondition load, not a silent fallback.
  if (!selectableCharacters.length) await refreshCharacters();
  const afterEnterFailure = dungeonEnterFailed;
  dungeonEnterFailed = false;
  const view = await getJson('/api/dungeon/state');
  if (view && view.pending_finalize) {
    // A run is held awaiting its deferred finalize (reloaded mid-exit, or a prior background finalize failed). Resume
    // it the way the run ended: draw its last board, then show the result the run-ending action returned (held_result),
    // run the finalize, and offer the way back.
    renderDungeonPlay(view);
    await showDungeonResult(requiredDungeonField(view, 'held_result', 'dungeon held view'));
    return;
  }
  if (view && view.active) {
    renderDungeonPlay(view);
    return;
  }
  await renderDungeonEntry({ afterEnterFailure });
}

// ── 入る前: 潜る支度。場所の絵（地下へ降りる黒い石のアーチ）を画面いっぱいに敷き、アーチの奥の段の上り口に潜るの紋が灯る。段の
// 手前の床に誰と潜るか（主人公の紋と相棒の札。札を押すと同行とひとりが切り替わる）が立ち、足もとに何を持って潜るか（台の一列）が
// 並ぶ。字は場所の名・人の名・品の名と個数だけで、説明の地の文も字の釦も置かない ─────────────────────────────────────────────
async function renderDungeonEntry({ afterEnterFailure }) {
  currentDungeonView = null;
  dungeonChatMessages = [];
  dungeonBoard.signature = null;
  teardownDungeonConsumableTargeting();
  foldDungeonEffects();
  clearDungeonVoice();
  for (const modal of DUNGEON_MODALS) modal.hidden = true;
  dungeonRoot.dataset.scene = 'entry';
  dungeonRoot.dataset.companion = 'none';
  delete dungeonRoot.dataset.outcome;
  dn.result.hidden = true;
  dn.tiles.replaceChildren();
  dn.entities.replaceChildren();
  dn.board.style.transformOrigin = '';
  dungeonEntityNodes.clear();
  dungeonEntityTiles.clear();
  clearDungeonJournal();
  dungeonPartyCast = null;
  dn.dive.disabled = true;
  const origin = dungeonEntryOrigin();
  dressSigilButton(dn.entryBack, 'back', origin.backLabel);
  dn.entryBack.hidden = origin.backOnlyAfterEnterFailure && !afterEnterFailure;
  dungeonEquipmentTarget = 'player';
  setDungeonEquipmentStatus('');
  clearDungeonEquipment();
  const [availability, snapshot, entry] = await Promise.all([
    getJson('/api/dungeon/availability'),
    getJson('/api/equipment'),
    getJson('/api/dungeon/entry-consumables')
  ]);
  dungeonEntryConsumables = requiredDungeonField(entry, 'consumables', '/api/dungeon/entry-consumables');
  const companion = availability.available ? dungeonEntryCompanion(snapshot) : null;
  dungeonWithCompanion = availability.available;
  // 同行できないとき（LM 未設定・片づけ中）は、相棒の札の代わりに離れた輪の印だけを薄く置く。理由は印の読み上げの名に持つ。
  dn.entryCompanion.hidden = !availability.available;
  dn.entryApart.hidden = availability.available;
  dn.entryApartMark.setAttribute('aria-label', availability.available ? '' : dungeonUnavailableText(availability.reason));
  // 相棒がいなければ、誰が来るかは潜るまで決まらないので、顔も名も無い影の札。
  dn.entryCompanionToggle.classList.toggle('is-unknown', availability.available && !companion);
  dn.entryCompanionToggle.setAttribute('aria-label', companion ? `${companion.name}と潜る` : '同行者と潜る');
  dn.entryFace.hidden = !companion;
  if (companion) dn.entryFace.src = companion.faceUrl;
  else dn.entryFace.removeAttribute('src');
  dn.entryCompanionName.hidden = !companion;
  dn.entryCompanionName.textContent = companion ? companion.name : '';
  syncDungeonCompanyChoice();
  renderDungeonEquipment(snapshot);
  dn.dive.disabled = false;
  dn.dive.focus({ preventScroll: true });
}

// Who comes when the player dives with a companion. The enter request always brings the buddy when one is set
// (a selectable buddy or the active homunculus), so that one is shown by face and name; with no buddy an academy
// character is rolled at enter time, so no one is shown (the shadow token). A homunculus buddy's display_name and
// face_url travel in the /api/equipment buddy sub-view; a selectable buddy resolves from the loaded roster (a miss is
// a real desync and throws).
function dungeonEntryCompanion(snapshot) {
  const buddy = validateDungeonBuddyEquipment(snapshot.buddy);
  if (!buddy) return null;
  if (buddy.displayName !== null) {
    const faceUrl = snapshot.buddy.face_url;
    if (typeof faceUrl !== 'string' || faceUrl === '') throw new Error(`homunculus buddy ${buddy.characterId} is missing face_url`);
    return { name: buddy.displayName, faceUrl };
  }
  const character = selectableCharacters.find((entry) => entry.character_id === buddy.characterId);
  if (!character?.visual_set_id) throw new Error(`dungeon entry: buddy ${buddy.characterId} does not resolve in the selectable roster`);
  return { name: character.display_name, faceUrl: `/canonical/character_visual_sets/${character.visual_set_id}/face_emotions/neutral.jpg` };
}

const DUNGEON_UNAVAILABLE_TEXT = {
  lmstudio_not_configured: 'LM Studio が未設定のため、ひとりで潜ります。',
  llm_busy: '直前の会話の後処理が実行中のため、今はひとりで潜ります。'
};
function dungeonUnavailableText(reason) {
  if (!Object.hasOwn(DUNGEON_UNAVAILABLE_TEXT, reason)) throw new Error(`dungeon availability: unknown reason ${JSON.stringify(reason)}`);
  return DUNGEON_UNAVAILABLE_TEXT[reason];
}

// 同行の選びは相棒の札そのもの（aria-pressed）。押すと札の二つの輪がほどけて顔が灰に沈み、もう一度押すと結ばれ直す。
function syncDungeonCompanyChoice() {
  dn.entryCompanionToggle.setAttribute('aria-pressed', String(dungeonWithCompanion));
  dn.entryParty.classList.toggle('is-solo', !dungeonWithCompanion);
}

dn.entryCompanionToggle.addEventListener('click', () => {
  dungeonWithCompanion = !dungeonWithCompanion;
  syncDungeonCompanyChoice();
});

// 持っていくもの: 足もとの台の一列（左に武器と護符、間を空けて消耗品）。持っている物は琥珀の縁の台に絵が灯って品の名が添い、
// 持っていない台は破線の縁に絵の影だけが残る（字は置かない）。種類は台の絵が示す: 武器の絵は武器の種類から、護符は護符の絵、
// 消耗品は属性の色の小瓶に数を添える。武器と護符の台は押すと付け替えの窓が開く（付け替えの手順と API は装備の区画のまま）。
const DUNGEON_WEAPON_MARKS = { sword: swordSvg, staff: staffSvg, short_rod: wandSvg };
function dungeonKitItem({ kind, svg = null, vial = false, element = null, label, name = null, count = null, onOpen = null }) {
  const item = document.createElement('li');
  item.className = `dn-kit dn-kit--${kind}${name === null ? ' is-empty' : ''}${element ? ` dn-el-${element}` : ''}`;
  const plate = document.createElement(onOpen ? 'button' : 'span');
  plate.className = 'dn-kit-plate';
  if (onOpen) {
    plate.type = 'button';
    plate.setAttribute('aria-haspopup', 'dialog');
    plate.setAttribute('aria-label', `${label}を付け替える`);
    plate.addEventListener('click', () => { plate.blur(); onOpen(); });
  } else {
    plate.setAttribute('role', 'img');
    plate.setAttribute('aria-label', name === null ? `${label}なし` : `${label} ${name}${count === null ? '' : ` ${count}個`}`);
  }
  if (svg) plate.insertAdjacentHTML('beforeend', svg);
  if (vial) {
    const drawn = document.createElement('span');
    drawn.className = 'dn-kit-vial';
    plate.append(drawn);
  }
  if (count !== null) {
    const badge = document.createElement('span');
    badge.className = 'dn-kit-count';
    badge.textContent = `×${count}`;
    plate.append(badge);
  }
  item.append(plate);
  if (name !== null) {
    const body = document.createElement('span');
    body.className = 'dn-kit-name dn-entry-ellipse';
    body.textContent = name;
    item.append(body);
  }
  return item;
}

// The kit reads the hero's slots from the same validated equipment snapshot the equipment window renders, so an equip
// or unequip in the window re-lays the kit from the returned snapshot (the one source of truth).
function renderDungeonEntryKit(view) {
  const weapon = view.slots.weapon?.instance ?? null;
  const amulet = view.slots.amulet?.instance ?? null;
  if (weapon && !(weapon.weapon_type in DUNGEON_WEAPON_MARKS)) throw new Error(`entry kit: unknown weapon_type ${JSON.stringify(weapon.weapon_type)}`);
  const kit = [
    dungeonKitItem({ kind: 'gear', svg: (weapon ? DUNGEON_WEAPON_MARKS[weapon.weapon_type] : wandSvg)(), label: '武器', name: weapon ? weapon.name : null, onOpen: openDungeonEquipment }),
    dungeonKitItem({ kind: 'gear', svg: charmSvg(), label: '護符', name: amulet ? amulet.name : null, onOpen: openDungeonEquipment })
  ];
  if (!dungeonEntryConsumables.length) kit.push(dungeonKitItem({ kind: 'carry', vial: true, label: '消耗品' }));
  for (const row of dungeonEntryConsumables) kit.push(dungeonKitItem({ kind: 'carry', vial: true, element: row.element ?? null, label: '消耗品', name: row.name, count: row.quantity }));
  dn.entryKit.replaceChildren(...kit);
}

function openDungeonEquipment() {
  dn.equipModal.hidden = false;
}

// ── Practical-dungeon entry equipment (the kit window #dungeon-equip-modal → #dungeon-equipment) ─────────────────────────
// The dungeon prep screen carries the hero's two equip slots (weapon / amulet) and the run-correction breakdown.
// GET /api/equipment, POST /api/equipment/equip { slot, instance_id }, and POST /api/equipment/unequip { slot }
// ALL return the SAME authoritative snapshot { slots:{weapon,amulet}, instances:[...], run_equipment }, so the
// response is the single source of truth: the client re-renders from the returned snapshot and never optimistically
// mutates a slot before the server confirms. The equipment vocabulary (kinds / weapon types / qualities / elements
// / effect keys and their closed-set labels) is imported from workshopArrivalClient.js (which mirrors
// app/src/equipment.mjs) — there is NO second label map or private translation here. Equipment changed at entry is
// folded into the run at enter time (C-23 entry snapshot); a change mid-run does not affect the in-progress run, so
// this surface adds no run-time gate — it is simply not shown while a run is active (the entry surface is hidden).
// The snapshot is validated fail-fast (malformed slots / instances / run_equipment throw — no silent skip); an API
// failure (400/409 etc.) surfaces on the equipment status line.

// Single-flight guard so a double click never fires two equip/unequip POSTs (each would rewrite the slot).
let dungeonEquipmentInFlight = false;

// The equip owner the entry surface currently shows/edits: 'player' (hero) or the buddy's character_id. The GET
// /api/equipment snapshot carries BOTH the player fields and the buddy sub-view, so a tab switch re-renders the
// cached snapshot without a refetch; equip/unequip re-render from the POST response and keep the selected owner.
// A fresh entry render resets to 'player'; a snapshot whose buddy is gone/changed falls the selection back to the
// hero (the buddy is a real run companion — a stale target is never silently equipped).
let dungeonEquipmentTarget = 'player';
let dungeonLastEquipmentSnapshot = null;

// The equipment status line is the error surface: a failed snapshot fetch / equip / unequip shows here instead of
// leaving placeholder cards (no silent fallback). The line ships in the entry markup, so a missing node is broken
// wiring — throw rather than silently suppressing the surface equipment failures must appear on.
function setDungeonEquipmentStatus(message, { tone = null } = {}) {
  const status = document.querySelector('#dungeon-equipment-status');
  if (!status) {
    throw new Error('dungeon equipment status line (#dungeon-equipment-status) is missing (broken markup wiring)');
  }
  const text = String(message ?? '').trim();
  if (!text) {
    status.hidden = true;
    status.textContent = '';
    delete status.dataset.tone;
    return;
  }
  status.hidden = false;
  status.textContent = text;
  if (tone) status.dataset.tone = tone;
  else delete status.dataset.tone;
}

function reportDungeonEquipmentError(error) {
  if (handleRuntimeApiError(error, { allowSettingsRedirect: true })) return;
  setDungeonEquipmentStatus(errorDisplayMessage(error), { tone: 'error' });
  console.error(error);
}

function clearDungeonEquipment() {
  document.querySelector('#dungeon-equipment-targets').replaceChildren();
  document.querySelector('#dungeon-equipment-slots').replaceChildren();
  document.querySelector('#dungeon-equipment-run').replaceChildren();
}


// Validate one equipment instance against the shared closed-set vocabulary, returning the instance plus its
// ordered base / bonus effect entries (workshopEffectEntries throws on an unknown effect key or a non-positive
// value — the same headless-tested guard the workshop uses). base / bonus are validated with allowEmpty because the
// equipment instance-shape contract structurally permits an empty effect object (rendered as 「なし」, never a
// silent skip). Every identity field is checked fail-fast against the imported frozen sets — no independent map.
function validateDungeonEquipmentInstance(instance, label) {
  if (!instance || typeof instance !== 'object' || Array.isArray(instance)) {
    throw new Error(`equipment: ${label} must be an object (got ${JSON.stringify(instance)})`);
  }
  if (!WORKSHOP_EQUIPMENT_KINDS.includes(instance.kind)) {
    throw new Error(`equipment: ${label} kind must be one of ${WORKSHOP_EQUIPMENT_KINDS.join('/')} (got ${JSON.stringify(instance.kind)})`);
  }
  assertWorkshopString(instance.instance_id, `${label}.instance_id`);
  if (instance.kind === 'weapon') {
    if (!WORKSHOP_WEAPON_TYPES.includes(instance.weapon_type)) {
      throw new Error(`equipment: ${label} weapon_type must be one of ${WORKSHOP_WEAPON_TYPES.join('/')} (got ${JSON.stringify(instance.weapon_type)})`);
    }
  } else if (Object.prototype.hasOwnProperty.call(instance, 'weapon_type')) {
    throw new Error(`equipment: a ${instance.kind} ${label} must not carry weapon_type (got ${JSON.stringify(instance.weapon_type)})`);
  }
  if (!WORKSHOP_ELEMENTS.includes(instance.element)) {
    throw new Error(`equipment: ${label} element must be one of ${WORKSHOP_ELEMENTS.join('/')} (got ${JSON.stringify(instance.element)})`);
  }
  assertWorkshopInteger(instance.tier, `${label}.tier`, { min: 1, max: 4 });
  if (!WORKSHOP_EQUIPMENT_QUALITIES.includes(instance.quality)) {
    throw new Error(`equipment: ${label} quality must be one of ${WORKSHOP_EQUIPMENT_QUALITIES.join('/')} (got ${JSON.stringify(instance.quality)})`);
  }
  assertWorkshopString(instance.name, `${label}.name`);
  assertWorkshopString(instance.flavor, `${label}.flavor`);
  const baseEffects = workshopEffectEntries(instance.base_effects, `${label}.base_effects`, { allowEmpty: true });
  const bonusEffects = workshopEffectEntries(instance.bonus_effects, `${label}.bonus_effects`, { allowEmpty: true });
  return { instance, baseEffects, bonusEffects };
}

// Validate the run-equipment aggregate. null (nothing equipped) is a valid reading; a present value must carry an
// `effects` object with every scalar effect key a non-negative integer and element_spell_power an object of magic
// element → positive integer (unknown element / bad value throws). Returns the validated effects (or null).
function validateDungeonRunEquipment(runEquipment) {
  if (runEquipment === null || runEquipment === undefined) return null;
  if (typeof runEquipment !== 'object' || Array.isArray(runEquipment)) {
    throw new Error(`equipment: run_equipment must be an object or null (got ${JSON.stringify(runEquipment)})`);
  }
  const effects = runEquipment.effects;
  if (!effects || typeof effects !== 'object' || Array.isArray(effects)) {
    throw new Error(`equipment: run_equipment.effects must be an object (got ${JSON.stringify(effects)})`);
  }
  for (const key of WORKSHOP_EFFECT_KEYS) {
    if (key === 'element_spell_power') {
      const perElement = effects.element_spell_power;
      if (!perElement || typeof perElement !== 'object' || Array.isArray(perElement)) {
        throw new Error(`equipment: run_equipment.effects.element_spell_power must be an object (got ${JSON.stringify(perElement)})`);
      }
      for (const [element, value] of Object.entries(perElement)) {
        if (!WORKSHOP_ELEMENTS.includes(element)) throw new Error(`equipment: run_equipment element_spell_power has an unknown element ${JSON.stringify(element)}`);
        if (!Number.isInteger(value) || value <= 0) throw new Error(`equipment: run_equipment element_spell_power ${element} must be a positive integer (got ${JSON.stringify(value)})`);
      }
      continue;
    }
    const value = effects[key];
    if (!Number.isInteger(value) || value < 0) {
      throw new Error(`equipment: run_equipment.effects.${key} must be a non-negative integer (got ${JSON.stringify(value)})`);
    }
  }
  return effects;
}

// Validate one owner's two equip slots fail-fast: an object carrying BOTH weapon / amulet keys (present, each an
// instance whose kind matches the slot, or null = unequipped — an absent key is malformed, not a silent null).
// Returns the resolved slot map ({ weapon, amulet } of validated instance views or null). Shared by the player
// slots and the buddy sub-view so both owners resolve by the identical rule.
function validateDungeonEquipmentSlots(rawSlots, label) {
  if (!rawSlots || typeof rawSlots !== 'object' || Array.isArray(rawSlots)) {
    throw new Error(`equipment snapshot: ${label} must be an object (got ${JSON.stringify(rawSlots)})`);
  }
  const resolvedSlots = {};
  for (const slot of WORKSHOP_EQUIPMENT_KINDS) {
    if (!Object.prototype.hasOwnProperty.call(rawSlots, slot)) {
      throw new Error(`equipment snapshot: ${label} is missing the ${slot} slot (got ${JSON.stringify(rawSlots)})`);
    }
    const value = rawSlots[slot];
    if (value === null) {
      resolvedSlots[slot] = null;
      continue;
    }
    const view = validateDungeonEquipmentInstance(value, `${label}.${slot}`);
    if (view.instance.kind !== slot) {
      throw new Error(`equipment snapshot: ${label}.${slot} holds a ${view.instance.kind}, not a ${slot}`);
    }
    resolvedSlots[slot] = view;
  }
  return resolvedSlots;
}

// Validate the required `buddy` sub-view: null when no run companion is set, else an object mirroring the player
// fields — a non-empty character_id, the same two-slot shape, and the same run_equipment shape. A missing (undefined)
// buddy key is a broken server contract, not a silent "no buddy". A homunculus buddy additionally carries a
// display_name (the schema marker: field present ⇒ homunculus, absent ⇒ selectable — B1 contract); when present it
// must be a non-empty string. Returns null or { characterId, displayName: string | null, slots, runEffects }.
function validateDungeonBuddyEquipment(buddy) {
  if (buddy === undefined) {
    throw new Error('equipment snapshot: buddy is required (null when unset, an object when set)');
  }
  if (buddy === null) return null;
  if (typeof buddy !== 'object' || Array.isArray(buddy)) {
    throw new Error(`equipment snapshot: buddy must be an object or null (got ${JSON.stringify(buddy)})`);
  }
  assertWorkshopString(buddy.character_id, 'buddy.character_id');
  const hasDisplayName = Object.prototype.hasOwnProperty.call(buddy, 'display_name');
  const displayName = hasDisplayName ? assertWorkshopString(buddy.display_name, 'buddy.display_name') : null;
  const slots = validateDungeonEquipmentSlots(buddy.slots, 'buddy.slots');
  const runEffects = validateDungeonRunEquipment(buddy.run_equipment);
  return { characterId: buddy.character_id, displayName, slots, runEffects };
}

// Validate the whole GET /api/equipment (and equip/unequip) snapshot fail-fast BEFORE any DOM mutation: `slots`
// resolves as above; `instances` is an array of owned instances; run_equipment validates as above; and `buddy` is
// the required run-companion sub-view (null when unset). Returns the normalized snapshot the renderer consumes.
function validateDungeonEquipmentSnapshot(snapshot) {
  if (!snapshot || typeof snapshot !== 'object' || Array.isArray(snapshot)) {
    throw new Error(`equipment snapshot: malformed response ${JSON.stringify(snapshot)}`);
  }
  const slots = validateDungeonEquipmentSlots(snapshot.slots, 'slots');
  if (!Array.isArray(snapshot.instances)) {
    throw new Error(`equipment snapshot: instances must be an array (got ${JSON.stringify(snapshot.instances)})`);
  }
  const instances = snapshot.instances.map((instance, index) => validateDungeonEquipmentInstance(instance, `instances[${index}]`));
  const runEffects = validateDungeonRunEquipment(snapshot.run_equipment);
  const buddy = validateDungeonBuddyEquipment(snapshot.buddy);
  return { slots, instances, runEffects, buddy };
}

function renderDungeonEquipment(snapshot) {
  dungeonLastEquipmentSnapshot = snapshot;
  const view = validateDungeonEquipmentSnapshot(snapshot);
  const owner = activeDungeonEquipmentOwner(view);
  renderDungeonEquipmentTargetTabs(view, owner.target);
  renderDungeonEquipmentSlots(owner.target, owner.slots, view.instances);
  renderDungeonEquipmentRun(owner.runEffects);
  renderDungeonEntryKit(view);
}

// Settle which owner the entry surface renders from the freshly-validated snapshot: the hero by default, or the
// buddy while the snapshot still carries that same buddy. A snapshot whose buddy is gone or changed falls the
// selection back to the hero (a stale companion is never rendered or edited). Returns the equip target id plus that
// owner's resolved slots + run effects.
function activeDungeonEquipmentOwner(view) {
  if (dungeonEquipmentTarget !== 'player') {
    if (view.buddy && view.buddy.characterId === dungeonEquipmentTarget) {
      return { target: view.buddy.characterId, slots: view.buddy.slots, runEffects: view.buddy.runEffects };
    }
    dungeonEquipmentTarget = 'player';
  }
  return { target: 'player', slots: view.slots, runEffects: view.runEffects };
}

// The 主人公 / バディー target tabs. No buddy → the switch UI stays empty (the quiet no-companion state; the hero
// equipment simply shows below). With a buddy, two tabs: the hero and the buddy's roster display name (resolved
// fail-fast — a buddy id absent from the selectable roster throws rather than borrowing another character's name).
function renderDungeonEquipmentTargetTabs(view, activeTarget) {
  const container = document.querySelector('#dungeon-equipment-targets');
  if (!view.buddy) {
    container.replaceChildren();
    return;
  }
  container.replaceChildren(
    buildDungeonEquipmentTargetTab('player', '主人公', activeTarget),
    buildDungeonEquipmentTargetTab(view.buddy.characterId, dungeonEquipmentBuddyName(view.buddy), activeTarget)
  );
}

// The buddy tab's display name. A homunculus buddy carries its display_name in the snapshot sub-view (the schema
// marker); use it directly. A selectable buddy has no display_name field, so it resolves from the already-loaded
// selectable roster (the dungeon flow loads it before the entry render) — an id that does not resolve throws (the
// buddy name is never substituted with another character's, and never falls back to the raw id).
function dungeonEquipmentBuddyName(buddy) {
  if (buddy.displayName !== null) return buddy.displayName;
  const character = selectableCharacters.find((entry) => entry.character_id === buddy.characterId);
  if (!character) {
    throw new Error(`dungeon equipment: buddy ${buddy.characterId} does not resolve in the selectable roster`);
  }
  return character.display_name;
}

function buildDungeonEquipmentTargetTab(target, label, activeTarget) {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'dungeon-equipment-target';
  button.dataset.target = target;
  button.setAttribute('role', 'tab');
  const active = target === activeTarget;
  button.setAttribute('aria-selected', active ? 'true' : 'false');
  if (active) button.dataset.active = 'true';
  button.textContent = label;
  button.addEventListener('click', () => selectDungeonEquipmentTarget(target));
  return button;
}

// Switch the shown/edited owner and re-render from the cached snapshot — both owners already live in it, so a tab
// switch needs no refetch.
function selectDungeonEquipmentTarget(target) {
  if (target === dungeonEquipmentTarget) return;
  dungeonEquipmentTarget = target;
  if (dungeonLastEquipmentSnapshot) renderDungeonEquipment(dungeonLastEquipmentSnapshot);
}

function renderDungeonEquipmentSlots(target, slots, instances) {
  const container = document.querySelector('#dungeon-equipment-slots');
  const cards = WORKSHOP_EQUIPMENT_KINDS.map((slot) => buildDungeonEquipmentSlotCard(target, slot, slots[slot], instances));
  container.replaceChildren(...cards);
}

// One slot card: an occupied slot shows the equipped instance + a 解除 (unequip) button; an empty slot shows a
// quiet 未装備 note and — from the owned instances of this kind — the 装備 candidates (a click equips it). A slot
// with no owned candidate of its kind shows only the quiet empty state (an optional workshop nudge, no new導線).
function buildDungeonEquipmentSlotCard(target, slot, equippedView, instances) {
  const card = document.createElement('div');
  card.className = 'dungeon-equipment-slot';
  card.dataset.slot = slot;
  const head = document.createElement('p');
  head.className = 'dungeon-equipment-slot-head';
  head.textContent = `${workshopKindLabel(slot)}スロット`;
  card.append(head);
  if (equippedView) {
    card.append(buildDungeonEquipmentEquipped(target, slot, equippedView));
  } else {
    card.append(buildDungeonEquipmentEmpty(target, slot, instances.filter((view) => view.instance.kind === slot)));
  }
  return card;
}

function buildDungeonEquipmentEquipped(target, slot, view) {
  const wrap = document.createElement('div');
  wrap.className = 'dungeon-equipment-equipped';
  wrap.append(buildDungeonEquipmentInstanceDetail(view));
  const unequip = document.createElement('button');
  unequip.type = 'button';
  unequip.className = 'dungeon-equipment-action';
  unequip.dataset.action = 'unequip';
  unequip.dataset.slot = slot;
  unequip.textContent = '解除';
  unequip.addEventListener('click', () => dungeonUnequip(target, slot).catch(reportDungeonEquipmentError));
  wrap.append(unequip);
  return wrap;
}

// The full display of an equipped instance: its LLM-authored name, the confirmed identity (種別・属性・階級・出来栄え
// using the shared closed-set labels), and the base + roll-derived bonus effects (both from the shared effect-entry
// helper; an empty set reads an honest 「なし」).
function buildDungeonEquipmentInstanceDetail(view) {
  const { instance, baseEffects, bonusEffects } = view;
  const detail = document.createElement('div');
  detail.className = 'dungeon-equipment-instance';
  detail.dataset.element = instance.element;
  const name = document.createElement('p');
  name.className = 'dungeon-equipment-instance-name';
  name.textContent = instance.name;
  const meta = document.createElement('p');
  meta.className = 'dungeon-equipment-instance-meta';
  meta.textContent = dungeonEquipmentInstanceMetaText(instance);
  const effects = document.createElement('div');
  effects.className = 'dungeon-equipment-instance-effects';
  effects.append(
    buildDungeonEquipmentEffectRow('基礎性能', baseEffects),
    buildDungeonEquipmentEffectRow('付加性能', bonusEffects)
  );
  detail.append(name, meta, effects);
  return detail;
}

// The identity line shared by the equipped detail and the candidate row: 種別（武器は weapon_type 併記）・属性・
// 階級T・出来栄え, every token from the shared closed-set label functions (fail-fast on an out-of-set value).
function dungeonEquipmentInstanceMetaText(instance) {
  return `${workshopKindLabelFull(instance)}・属性${workshopElementLabel(instance.element)}・階級T${instance.tier}・出来栄え${workshopQualityLabel(instance.quality)}`;
}

function buildDungeonEquipmentEffectRow(label, entries) {
  const row = document.createElement('div');
  row.className = 'dungeon-equipment-effect-row';
  const rowLabel = document.createElement('span');
  rowLabel.className = 'dungeon-equipment-effect-label';
  rowLabel.textContent = label;
  const chips = document.createElement('span');
  chips.className = 'dungeon-equipment-effect-chips';
  if (entries.length === 0) {
    const none = document.createElement('span');
    none.className = 'dungeon-equipment-effect-none';
    none.textContent = 'なし';
    chips.append(none);
  } else {
    for (const entry of entries) chips.append(dungeonEquipmentEffectChip(entry));
  }
  row.append(rowLabel, chips);
  return row;
}

function dungeonEquipmentEffectChip(effect) {
  const chip = document.createElement('span');
  chip.className = 'dungeon-equipment-effect';
  chip.textContent = `${effect.label}+${effect.value}`;
  return chip;
}

function buildDungeonEquipmentEmpty(target, slot, candidates) {
  const wrap = document.createElement('div');
  wrap.className = 'dungeon-equipment-empty';
  const note = document.createElement('p');
  note.className = 'dungeon-equipment-empty-note';
  note.textContent = '未装備';
  wrap.append(note);
  if (candidates.length === 0) {
    const hint = document.createElement('p');
    hint.className = 'dungeon-equipment-empty-hint';
    hint.textContent = 'この種別の装備はまだありません。工房で仕立てられます。';
    wrap.append(hint);
    return wrap;
  }
  const list = document.createElement('div');
  list.className = 'dungeon-equipment-candidates';
  for (const candidate of candidates) list.append(buildDungeonEquipmentCandidate(target, slot, candidate));
  wrap.append(list);
  return wrap;
}

function buildDungeonEquipmentCandidate(target, slot, view) {
  const { instance } = view;
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'dungeon-equipment-candidate';
  button.dataset.instanceId = instance.instance_id;
  button.dataset.element = instance.element;
  const name = document.createElement('span');
  name.className = 'dungeon-equipment-candidate-name';
  name.textContent = instance.name;
  const meta = document.createElement('span');
  meta.className = 'dungeon-equipment-candidate-meta';
  meta.textContent = dungeonEquipmentInstanceMetaText(instance);
  button.append(name, meta);
  button.addEventListener('click', () => dungeonEquip(target, slot, instance.instance_id).catch(reportDungeonEquipmentError));
  return button;
}

// The run-correction breakdown: the aggregated effects that WILL fold into the run at enter. Scalar effects are
// listed (in the shared effect-key order) only when non-zero; element_spell_power expands to one row per element
// (属性別). A null run_equipment — nothing equipped — reads 補正なし (not an empty panel).
function renderDungeonEquipmentRun(runEffects) {
  const container = document.querySelector('#dungeon-equipment-run');
  const title = document.createElement('p');
  title.className = 'dungeon-equipment-run-title';
  title.textContent = 'この潜りに効く補正';
  const body = document.createElement('div');
  body.className = 'dungeon-equipment-run-body';
  const rows = runEffects ? dungeonRunEquipmentRows(runEffects) : [];
  if (rows.length === 0) {
    const none = document.createElement('p');
    none.className = 'dungeon-equipment-run-none';
    none.textContent = '補正なし';
    body.append(none);
  } else {
    for (const row of rows) body.append(buildDungeonEquipmentRunRow(row));
  }
  container.replaceChildren(title, body);
}

// Ordered { label, value } rows over the shared effect-key order: each non-zero scalar once, then one row per
// contributing element for element_spell_power (label 同属性スペル威力（<属性>）). Effects are pre-validated.
function dungeonRunEquipmentRows(effects) {
  const rows = [];
  for (const key of WORKSHOP_EFFECT_KEYS) {
    if (key === 'element_spell_power') {
      for (const element of WORKSHOP_ELEMENTS) {
        const value = effects.element_spell_power[element];
        if (value === undefined) continue;
        rows.push({ label: `${WORKSHOP_EFFECT_LABELS[key]}（${workshopElementLabel(element)}）`, value });
      }
      continue;
    }
    const value = effects[key];
    if (value > 0) rows.push({ label: WORKSHOP_EFFECT_LABELS[key], value });
  }
  return rows;
}

function buildDungeonEquipmentRunRow(row) {
  const el = document.createElement('div');
  el.className = 'dungeon-equipment-run-row';
  const label = document.createElement('span');
  label.className = 'dungeon-equipment-run-label';
  label.textContent = row.label;
  const value = document.createElement('span');
  value.className = 'dungeon-equipment-run-value';
  value.textContent = `+${row.value}`;
  el.append(label, value);
  return el;
}

// Equip an owned instance into its slot / clear a slot. Both adopt the returned authoritative snapshot as the sole
// source of truth (no optimistic slot mutation); an in-flight guard blocks a double POST. A failure REJECTS to the
// click handler's reporter (the equip/unequip is fail-fast — nothing is guessed on error). Only the in-flight reset
// runs in finally.
async function dungeonEquip(target, slot, instanceId) {
  if (dungeonEquipmentInFlight) {
    showProcessingToast();
    return;
  }
  dungeonEquipmentInFlight = true;
  try {
    setDungeonEquipmentStatus('');
    const snapshot = await postJson('/api/equipment/equip', { target, slot, instance_id: instanceId });
    renderDungeonEquipment(snapshot);
  } finally {
    dungeonEquipmentInFlight = false;
  }
}

async function dungeonUnequip(target, slot) {
  if (dungeonEquipmentInFlight) {
    showProcessingToast();
    return;
  }
  dungeonEquipmentInFlight = true;
  try {
    setDungeonEquipmentStatus('');
    const snapshot = await postJson('/api/equipment/unequip', { target, slot });
    renderDungeonEquipment(snapshot);
  } finally {
    dungeonEquipmentInFlight = false;
  }
}

// ── 盤: 升目は階ごとに 1 回だけ作り、手番ごとには状態が変わった升目の class だけを書き換える ─────────────────────────
const dungeonBoard = {
  signature: null,
  width: 0,
  height: 0,
  cells: [],
  light: new Uint8Array(0),
  itemNodes: new Map(),
  lastLightAt: 0
};
const DUNGEON_LIGHT_CLASS = ['', 'is-seen', 'is-lit'];
const dungeonLightStep = (distance) => (distance < 1.5 ? 0 : distance < 2.5 ? 1 : distance < 3.5 ? 2 : distance < 4.5 ? 3 : 4);
// Deadzone camera state, in board pixels: the scroll offset whose negation translates the board inside the clipping
// viewport. Persists across renders so the deadzone follow has the previous position to scroll from; a new floor
// centers it and a viewport resize reframes it (see layoutDungeonBoard).
let dungeonCamera = { x: 0, y: 0 };
// The viewport size (px) the camera was last laid out for; a reframe responds only to an actual resize.
let dungeonViewportSize = { w: 0, h: 0 };
// Persistent board tokens (player / companion / enemy:<uid>) kept across renders so a position change slides, and
// each one's current logical tile, so an effect finds the token at an event's tile where it is actually drawn.
const dungeonEntityNodes = new Map();
const dungeonEntityTiles = new Map();

function dungeonFloorBounds(view) {
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (let y = 0; y < view.height; y += 1) {
    for (let x = 0; x < view.width; x += 1) {
      if (view.tiles[y][x] !== 'floor') continue;
      if (x < minX) minX = x;
      if (x > maxX) maxX = x;
      if (y < minY) minY = y;
      if (y > maxY) maxY = y;
    }
  }
  return { minX, minY, maxX, maxY };
}

// 地物は印の SVG（/dungeonMarks.js）か、落ちている物の絵。
function dungeonFeatureNode(className, { svg = null, imageUrl = null, label }) {
  if ((svg === null) === (imageUrl === null)) throw new Error(`dungeon feature ${className} needs exactly one of svg / imageUrl`);
  const node = document.createElement('div');
  node.className = `dn-feature ${className}`;
  node.title = label;
  if (svg) {
    node.innerHTML = svg;
  } else {
    const img = document.createElement('img');
    img.alt = '';
    img.src = imageUrl;
    node.append(img);
  }
  return node;
}

// 宝箱には絵が無いので、印の宝箱（真上から見た蓋）にする。
function dungeonItemFeature(item) {
  if (item.kind === 'treasure_chest') return dungeonFeatureNode('dn-feature--item dn-feature--chest', { svg: chestSvg(), label: item.name });
  return dungeonFeatureNode('dn-feature--item', { imageUrl: `${DUNGEON_ASSET_BASE}/items/${item.kind}.png`, label: item.name });
}

// 升目の形は階ごとに 1 回だけ決める: 床は石の割り方（位置から決まる 4 通り）と、北・西・東の壁が落とす影。壁は床に接する所だけが
// 石組みで、下が床なら手前の面を見せ、床に面した辺に灯りの縁を持つ。床に接しない壁は岩の中（dn-rock）で描かない。
function dungeonCellClass(floorAt, x, y) {
  const variant = ((x * 73856093) ^ (y * 19349663)) >>> 0;
  if (floorAt(x, y)) {
    const shade = [!floorAt(x, y - 1) && 'sh-n', !floorAt(x - 1, y) && 'sh-w', !floorAt(x + 1, y) && 'sh-e'].filter(Boolean);
    return ['dn-cell', 'dn-floor', `dn-v${variant % 4}`, ...shade].join(' ');
  }
  let touchesFloor = false;
  for (let dy = -1; dy <= 1 && !touchesFloor; dy += 1) for (let dx = -1; dx <= 1; dx += 1) if (floorAt(x + dx, y + dy)) { touchesFloor = true; break; }
  if (!touchesFloor) return 'dn-cell dn-wall dn-rock';
  if (floorAt(x, y + 1)) return ['dn-cell', 'dn-wall', 'dn-face', `dn-v${variant % 4}`].join(' ');
  const rim = [floorAt(x, y - 1) && 'rim-n', floorAt(x - 1, y) && 'rim-w', floorAt(x + 1, y) && 'rim-e'].filter(Boolean);
  return ['dn-cell', 'dn-wall', ...rim].join(' ');
}

function buildDungeonFloor(view) {
  dungeonBoard.width = view.width;
  dungeonBoard.height = view.height;
  dungeonBoard.light = new Uint8Array(view.width * view.height);
  dungeonBoard.itemNodes.clear();
  dn.tiles.style.setProperty('--dn-cols', view.width);
  dn.tiles.style.setProperty('--dn-rows', view.height);
  const cells = [];
  const floorAt = (x, y) => view.tiles[y]?.[x] === 'floor';
  for (let y = 0; y < view.height; y += 1) {
    for (let x = 0; x < view.width; x += 1) {
      const cell = document.createElement('div');
      cell.className = dungeonCellClass(floorAt, x, y);
      if (view.stairs.x === x && view.stairs.y === y) {
        cell.append(dungeonFeatureNode('dn-feature--stairs', { svg: stairsDownSvg(), label: '下り階段' }));
      } else if (view.entrance.x === x && view.entrance.y === y) {
        cell.append(dungeonFeatureNode('dn-feature--entrance', { svg: stairsUpSvg(), label: '入場地点（撤退可）' }));
      }
      cells.push(cell);
    }
  }
  dn.tiles.replaceChildren(...cells);
  dungeonBoard.cells = cells;
}

// 灯りの移ろい: 前の移ろいが走っている間に次の手番が来たら、前のものを終わりの姿へ畳んでから次を始める。押し続けで手番が詰まると
// 移ろいの長さも手番の間隔まで縮め、最後の手番の位置に遅れず揃う。
function updateDungeonLight(view) {
  const now = performance.now();
  const since = now - dungeonBoard.lastLightAt;
  if (since < DN_LIGHT_MS) {
    dn.tiles.classList.add('dn-snap');
    void dn.tiles.offsetWidth;
    dn.tiles.classList.remove('dn-snap');
  }
  dn.tiles.style.setProperty('--dn-light-ms', `${Math.round(Math.max(DN_LIGHT_MIN_MS, Math.min(DN_LIGHT_MS, since)))}ms`);
  let changed = 0;
  const { x: px, y: py } = view.player;
  for (let y = 0; y < view.height; y += 1) {
    const exploredRow = view.explored[y];
    const visibleRow = view.visible[y];
    for (let x = 0; x < view.width; x += 1) {
      const index = y * view.width + x;
      // 照らされる升目は、主人公からの距離で灯りの段（0＝足元〜4＝灯りの縁）を持つ。状態＝濃さ×段で比べ、変わった升目だけ書く。
      const next = visibleRow[x] ? 2 + dungeonLightStep(Math.hypot(x - px, y - py)) : (exploredRow[x] ? 1 : 0);
      const prev = dungeonBoard.light[index];
      if (prev === next) continue;
      const cell = dungeonBoard.cells[index];
      const prevClass = DUNGEON_LIGHT_CLASS[Math.min(prev, 2)];
      const nextClass = DUNGEON_LIGHT_CLASS[Math.min(next, 2)];
      if (prevClass !== nextClass) {
        if (prevClass) cell.classList.remove(prevClass);
        if (nextClass) cell.classList.add(nextClass);
      }
      if (next >= 2) cell.dataset.l = String(next - 2);
      else if (prev >= 2) delete cell.dataset.l;
      dungeonBoard.light[index] = next;
      changed += 1;
    }
  }
  dungeonBoard.lastLightAt = now;
  return changed;
}

function updateDungeonItems(view, freshBoard) {
  const live = new Set();
  for (const item of view.items) {
    live.add(item.uid);
    if (dungeonBoard.itemNodes.has(item.uid)) continue;
    const node = dungeonItemFeature(item);
    dungeonBoard.itemNodes.set(item.uid, node);
    dungeonBoard.cells[item.y * view.width + item.x].append(node);
    if (!freshBoard) dungeonFx.animate(node, [{ opacity: 0, transform: 'scale(0.6)' }, { opacity: 1, transform: 'scale(1)' }], { duration: 220, easing: 'ease-out' });
  }
  for (const [uid, node] of dungeonBoard.itemNodes) {
    if (live.has(uid)) continue;
    node.remove();
    dungeonBoard.itemNodes.delete(uid);
  }
}

// 体力と魔力の目盛り: 駒と同じ金の縁と黒い地。減った分は淡い削れとして一拍残ってから落ち、増えた分は満ちていく（減っていく重さが
// 目で読める）。値が変わらない手番では何も書かない。
function dungeonGaugeNode(kind) {
  const gauge = document.createElement('div');
  gauge.className = `dn-gauge dn-gauge--${kind}`;
  const lag = document.createElement('div');
  lag.className = 'dn-gauge-lag';
  const fill = document.createElement('div');
  fill.className = 'dn-gauge-fill';
  gauge.append(lag, fill);
  return gauge;
}

function setCombatGauge(gauge, current, max) {
  if (!Number.isFinite(current) || !Number.isFinite(max) || max <= 0) throw new Error(`combat gauge needs a finite value and a positive max, got ${current} / ${max}`);
  const pct = Math.max(0, Math.min(100, (current / max) * 100));
  const prev = gauge.dataset.pct === undefined ? null : Number(gauge.dataset.pct);
  if (prev === pct) return;
  gauge.dataset.pct = String(pct);
  gauge.title = `${current} / ${max}`;
  const [lag, fill] = gauge.children;
  if (prev === null || dungeonReducedMotion()) {
    lag.style.transition = 'none';
    fill.style.transition = 'none';
  } else if (pct < prev) {
    fill.style.transition = 'none';
    lag.style.transition = '';
  } else {
    lag.style.transition = 'none';
    fill.style.transition = '';
  }
  lag.style.width = `${pct}%`;
  fill.style.width = `${pct}%`;
}

function dungeonTokenNode({ role, element = null, imageUrl = null, glyph = '', crest = false, gauges = [], label = '', elite = false }) {
  const token = document.createElement('div');
  token.className = ['dn-token', `dn-token--${role}`, element ? `dn-el-${element}` : '', elite ? 'dn-token--elite' : ''].filter(Boolean).join(' ');
  if (label) token.title = label;
  const face = document.createElement('div');
  face.className = 'dn-token-face';
  if (crest) {
    face.innerHTML = heroCrestSvg();
  } else if (imageUrl) {
    const img = document.createElement('img');
    img.alt = '';
    img.src = imageUrl;
    face.append(img);
  } else {
    face.textContent = glyph;
  }
  token.append(face);
  if (gauges.length) {
    const frame = document.createElement('div');
    frame.className = 'dn-token-gauges';
    frame.append(...gauges.map((kind) => dungeonGaugeNode(kind)));
    token.append(frame);
  }
  return token;
}

// 駒の下の目盛りを、その駒のいまの値に合わせる（hp と、魔力を持つ駒は mp）。
function updateDungeonTokenGauges(token, actor) {
  const hp = token.querySelector('.dn-gauge--hp');
  if (hp) setCombatGauge(hp, actor.hp, actor.max_hp);
  const mp = token.querySelector('.dn-gauge--mp');
  if (mp) setCombatGauge(mp, actor.mp, actor.max_mp);
}

// 駒は id（player／companion／enemy:<uid>）で使い回す。駒は一度だけ作り、目盛りは値だけを動かし、位置は transform の滑りで動かす。
function upsertDungeonEntity(key, live, x, y, actor, build, { appear }) {
  live.add(key);
  dungeonEntityTiles.set(key, { x, y });
  const transform = `translate(calc((var(--dn-cell) + var(--dn-gap)) * ${x}), calc((var(--dn-cell) + var(--dn-gap)) * ${y}))`;
  let node = dungeonEntityNodes.get(key);
  if (!node) {
    node = document.createElement('div');
    node.className = `dn-entity dn-entity--${key.split(':')[0]}`;
    node.style.transform = transform;
    node.append(build());
    dungeonEntityNodes.set(key, node);
    dn.entities.append(node);
    updateDungeonTokenGauges(node.firstChild, actor);
    if (appear) dungeonFx.animate(node.firstChild, [{ opacity: 0, filter: 'brightness(0.3)' }, { opacity: 1, filter: 'brightness(1)' }], { duration: 260, easing: 'ease-out' });
    return;
  }
  node.style.transform = transform;
  updateDungeonTokenGauges(node.firstChild, actor);
}

function renderDungeonEntities(view, freshBoard) {
  if (freshBoard) {
    dungeonEntityNodes.clear();
    dungeonEntityTiles.clear();
    dn.entities.replaceChildren();
  }
  const live = new Set();
  if (view.companion && !view.companion.down) {
    const companion = view.companion;
    upsertDungeonEntity('companion', live, companion.x, companion.y, companion,
      () => dungeonTokenNode({ role: 'ally', imageUrl: dungeonCompanionFaceUrl(companion), gauges: ['hp', 'mp'], label: companion.name }), { appear: false });
  }
  for (const enemy of view.enemies) {
    upsertDungeonEntity(`enemy:${enemy.uid}`, live, enemy.x, enemy.y, enemy,
      () => dungeonTokenNode({ role: 'enemy', element: enemy.element, elite: enemy.elite || enemy.boss, imageUrl: `${DUNGEON_ASSET_BASE}/enemies/${enemy.archetype_id}.png`, glyph: enemy.glyph, gauges: ['hp'], label: `${enemy.name}（${DUNGEON_MAGIC_LABELS[enemy.element] ?? enemy.element}）` }),
      { appear: !freshBoard });
  }
  upsertDungeonEntity('player', live, view.player.x, view.player.y, view.player,
    () => dungeonTokenNode({ role: 'self', crest: true, gauges: ['hp', 'mp'], label: DUNGEON_PLAYER_NAME }), { appear: false });
  for (const [key, node] of dungeonEntityNodes) {
    if (live.has(key)) continue;
    node.remove();
    dungeonEntityNodes.delete(key);
    dungeonEntityTiles.delete(key);
  }
}

function renderDungeonBoard(view) {
  const previousPlayerTile = dungeonEntityTiles.get('player') ?? null;
  const signature = `${view.run_id}:${view.floor}`;
  const freshBoard = signature !== dungeonBoard.signature;
  if (freshBoard) {
    dungeonBoard.signature = signature;
    buildDungeonFloor(view);
  }
  const changed = updateDungeonLight(view);
  updateDungeonItems(view, freshBoard);
  renderDungeonEntities(view, freshBoard);
  const playerMoved = !previousPlayerTile || previousPlayerTile.x !== view.player.x || previousPlayerTile.y !== view.player.y;
  layoutDungeonBoard(view, { mode: freshBoard ? 'center' : (playerMoved ? 'follow' : 'preserve') });
  return { freshBoard, changed };
}

// One rule for the camera: a new floor centers on the hero, walking follows with a deadzone, and a window resize keeps
// the hero at the same place in the window.
function measureDungeonReframeAnchor() {
  const node = dungeonEntityNodes.get('player');
  if (!node) throw new Error('dungeon: reframe needs the rendered player node');
  const playerRect = dungeonLocalRect(node);
  const boardRect = dungeonLocalRect(dn.board);
  const frac = playerViewportFraction({ playerRect, viewportRect: dungeonLocalRect(dn.viewport) });
  return {
    fracX: frac.x,
    fracY: frac.y,
    boardCenterX: (playerRect.left + playerRect.width / 2) - boardRect.left,
    boardCenterY: (playerRect.top + playerRect.height / 2) - boardRect.top
  };
}

function snapDungeonEntitiesToCell() {
  if (!dungeonEntityNodes.size) return;
  for (const node of dungeonEntityNodes.values()) node.style.transition = 'none';
  void dn.viewport.offsetWidth;
  for (const node of dungeonEntityNodes.values()) node.style.transition = '';
}

function layoutDungeonBoard(view, { mode }) {
  if (mode === 'preserve') return;
  const viewW = dn.viewport.clientWidth;
  const viewH = dn.viewport.clientHeight;
  if (viewW === 0 || viewH === 0) return;
  if (mode === 'reframe' && viewW === dungeonViewportSize.w && viewH === dungeonViewportSize.h) return;
  const anchor = mode === 'reframe' ? measureDungeonReframeAnchor() : null;
  const style = getComputedStyle(dn.viewport);
  const fromCell = mode === 'reframe' ? parseFloat(style.getPropertyValue('--dn-cell')) : null;
  const gap = parseFloat(style.getPropertyValue('--dn-gap'));
  if (!Number.isFinite(gap)) throw new Error('dungeon: --dn-gap must resolve to a length');
  const cell = computeDungeonCellSize({ viewW, viewH, gap, targetCells: DN_TARGET_CELLS, cellMin: DN_CELL_MIN, cellMax: DN_CELL_MAX });
  dn.viewport.style.setProperty('--dn-cell', `${cell}px`);
  const step = cell + gap;
  const playerX = view.player.x * step + cell / 2;
  const playerY = view.player.y * step + cell / 2;
  const r = view.player_stats.vision_radius;
  const marginX = computeFollowMargin({ visionRadius: r, step, cell, viewSize: viewW });
  const marginY = computeFollowMargin({ visionRadius: r, step, cell, viewSize: viewH });
  // 端止めは「どの床の升目に立っても主人公を窓の中央に置ける広さ」で取り、灯りをいつも窓の中ほどに置く（床の外接矩形で止めると、
  // 床の端にいると灯りが窓の隅へ寄る）。
  const bounds = dungeonFloorBounds(view);
  const contentMinX = bounds.minX * step + cell / 2 - viewW / 2;
  const contentMinY = bounds.minY * step + cell / 2 - viewH / 2;
  const contentMaxX = bounds.maxX * step + cell / 2 + viewW / 2;
  const contentMaxY = bounds.maxY * step + cell / 2 + viewH / 2;
  let next;
  if (mode === 'reframe' && cell !== fromCell) {
    snapDungeonEntitiesToCell();
    next = reframeDungeonCamera({ playerX, playerY, fracX: anchor.fracX, fracY: anchor.fracY, contentMinX, contentMaxX, contentMinY, contentMaxY, viewW, viewH });
  } else if (mode === 'reframe') {
    const anchorX = rescaleBoardPx({ px: anchor.boardCenterX, fromCell, toCell: cell, gap });
    const anchorY = rescaleBoardPx({ px: anchor.boardCenterY, fromCell, toCell: cell, gap });
    next = reframeDungeonCamera({ playerX: anchorX, playerY: anchorY, fracX: anchor.fracX, fracY: anchor.fracY, contentMinX, contentMaxX, contentMinY, contentMaxY, viewW, viewH });
  } else {
    const seedX = mode === 'center' ? playerX - viewW / 2 : dungeonCamera.x;
    const seedY = mode === 'center' ? playerY - viewH / 2 : dungeonCamera.y;
    next = computeDungeonCamera({ playerX, playerY, contentMinX, contentMaxX, contentMinY, contentMaxY, viewW, viewH, marginX, marginY, prevX: seedX, prevY: seedY });
    if (dungeonCompanionSpeaking()) next = holdDungeonSpeaker(next, { cell, step, viewW, viewH });
  }
  dungeonCamera = next;
  dungeonViewportSize = { w: viewW, h: viewH };
  const transform = `translate(${-next.x}px, ${-next.y}px)`;
  if (mode === 'follow') {
    dn.board.style.transition = '';
    dn.board.style.transform = transform;
  } else {
    dn.board.style.transition = 'none';
    dn.board.style.transform = transform;
    void dn.board.offsetWidth;
    dn.board.style.transition = '';
  }
  placeDungeonVoice();
}

new ResizeObserver(() => {
  if (!currentDungeonView || dungeonRoot.dataset.scene !== 'play') return;
  layoutDungeonBoard(currentDungeonView, { mode: 'reframe' });
}).observe(dn.viewport);

// ── 演出: どれも次の手番を待たせない。新しい手番が来たら、遅れて出る予定のものまで含めて前の演出をすべて畳む ─────────
// 打ち合いの演出の値の一つの定義。ダンジョンと闘技会は同じキャラクターが同じ魔法を使うので、弾・着弾・身を引く動き・浮く数・縁の赤・
// 外れ（弾が抜けて駒が身をかわす）・空振り・回復・蘇生・回避の魔法をこの値と下の描き手（stage を受ける playCombatEvents ほか）で描く。
// 大きさの値（*Cells）は升の数。fadeMs は動きを減らす設定で、移動と拡大縮小の代わりに使う不透明度だけの変化の長さ。
const COMBAT_FX = Object.freeze({
  strikeStaggerMs: 70,
  strikeStaggerCapMs: 280,
  boltMs: 180,
  impactMs: 240,
  recoilMs: 160,
  recoilPx: 5,
  floatMs: 1100,
  floatRisePx: 26,
  floatLiftCells: 0.32,
  hurtMs: 260,
  boltCells: 0.9,
  impactCells: 1.05,
  missPassCells: 0.9,
  missPassMs: 200,
  dodgeCells: 0.3,
  dodgeMs: 300,
  missHoldMs: 150,
  whiffCells: 1.3,
  whiffMs: 420,
  mendCells: 1.15,
  mendMs: 680,
  mendMotes: 6,
  mendOrbCells: 0.32,
  reviveCells: 0.72,
  reviveMs: 760,
  wardCells: 1.6,
  wardMs: 560,
  fadeMs: 280
});
// 打ち合いの kind（弾が飛ぶ出来事）。
const COMBAT_STRIKE_KINDS = new Set(['melee', 'cast', 'enemy_attack']);

// 遅れて出る予定（later）と走っている動き（animate）を持ち、fold で全部を畳む。畳んだ数を返す。
function createCombatFx() {
  const timers = new Set();
  const animations = new Set();
  return {
    later(ms, run) {
      const id = setTimeout(() => {
        timers.delete(id);
        run();
      }, ms);
      timers.add(id);
    },
    animate(el, keyframes, options, onDone = null) {
      const animation = el.animate(keyframes, options);
      animations.add(animation);
      animation.onfinish = () => {
        animations.delete(animation);
        onDone?.();
      };
      return animation;
    },
    fold() {
      const folded = timers.size + animations.size;
      for (const id of timers) clearTimeout(id);
      timers.clear();
      for (const animation of animations) animation.cancel();
      animations.clear();
      return folded;
    }
  };
}

const dungeonFx = createCombatFx();

// 降りた手番（keepVeil）では、押した瞬間から掛かっている暗がりを残し、その下で下の階を描く。
function foldDungeonEffects({ keepVeil = false } = {}) {
  const folded = dungeonFx.fold();
  dn.effects.replaceChildren();
  if (!keepVeil) dn.veil.classList.remove('is-dark');
  dn.floorMark.classList.remove('is-shown');
  dn.hurt.classList.remove('is-hurt');
  dungeonRoot.dataset.fxFolded = String(folded);
  return folded;
}

function dungeonCellMetrics() {
  const style = getComputedStyle(dn.viewport);
  const cell = parseFloat(style.getPropertyValue('--dn-cell'));
  const gap = parseFloat(style.getPropertyValue('--dn-gap'));
  return { cell, step: cell + gap };
}

// 盤の上の位置: その升目にいまいる駒が実際に描かれている中心（滑りの途中ならその途中）か、升目の中心。
function dungeonTileCenter(x, y) {
  const { cell, step } = dungeonCellMetrics();
  for (const [key, tile] of dungeonEntityTiles) {
    if (tile.x !== x || tile.y !== y) continue;
    const node = dungeonEntityNodes.get(key);
    if (!node) continue;
    const r = dungeonLocalRect(node);
    const b = dungeonLocalRect(dn.board);
    return { x: (r.left + r.width / 2) - b.left, y: (r.top + r.height / 2) - b.top };
  }
  return { x: x * step + cell / 2, y: y * step + cell / 2 };
}

// 数字は駒の上端から浮いて薄れる（駒の絵と、吸われていく物の絵に重ならない高さ）。会心は数を少し大きくして「会心」と添える
// （ダンジョンに会心は出ない）。動きを減らす設定では浮かず、その高さで現れて薄れる。
// stage は描く盤: { prefix（'dn'／'an'・class の頭）, fx（createCombatFx）, layer（演出の層）, hurt（縁の赤）, cell（升目の px）,
// flightMs（弾が飛ぶ時間）, reduced(), tileCenter(x, y)（層の中の位置）, tokenAt(x, y)（その升目の駒の node か null） }。
function combatFloatWord(stage, at, text, kind, { crit = false } = {}) {
  const p = stage.prefix;
  const node = document.createElement('div');
  node.className = crit ? `${p}-float ${p}-float--${kind} ${p}-float--crit` : `${p}-float ${p}-float--${kind}`;
  if (crit) {
    const mark = document.createElement('span');
    mark.className = `${p}-float-crit`;
    mark.textContent = '会心';
    node.append(mark, document.createTextNode(text));
  } else {
    node.textContent = text;
  }
  node.style.left = `${at.x}px`;
  node.style.top = `${at.y - stage.cell * COMBAT_FX.floatLiftCells}px`;
  stage.layer.append(node);
  const rise = -COMBAT_FX.floatRisePx;
  const keyframes = stage.reduced()
    ? [{ opacity: 0 }, { opacity: 1, offset: 0.18 }, { opacity: 1, offset: 0.7 }, { opacity: 0 }].map((frame) => ({ ...frame, transform: 'translate(-50%, -80%)' }))
    : [
      { opacity: 0, transform: 'translate(-50%, -30%)' },
      { opacity: 1, transform: 'translate(-50%, -80%)', offset: 0.18 },
      { opacity: 1, transform: `translate(-50%, calc(-80% + ${rise * 0.6}px))`, offset: 0.7 },
      { opacity: 0, transform: `translate(-50%, calc(-80% + ${rise}px))` }
    ];
  stage.fx.animate(node, keyframes, { duration: COMBAT_FX.floatMs, easing: 'ease-out' }, () => node.remove());
}

// 演出の層に、at を中心にした sizeCells 升の大きさの要素を置く。
function combatFxNode(stage, className, at, sizeCells, tag = 'div') {
  const node = document.createElement(tag);
  node.className = className;
  if (tag === 'img') node.alt = '';
  node.style.left = `${at.x}px`;
  node.style.top = `${at.y}px`;
  node.style.setProperty('--combat-fx-size', `${Math.round(stage.cell * sizeCells)}px`);
  stage.layer.append(node);
  return node;
}

// 動きを減らす設定の形: その場で peak の濃さまで現れて薄れるだけ（移動も拡大縮小も無い）。
function fadeCombatFx(stage, node, peak) {
  stage.fx.animate(node, [{ opacity: 0 }, { opacity: peak, offset: 0.3 }, { opacity: 0 }], { duration: COMBAT_FX.fadeMs, easing: 'ease-out' }, () => node.remove());
}

// 弾が from から to へ飛び、着いた時に onLand。beyond があれば（外れ）弾は消えずに同じ向きの beyond まで抜けながら薄れる。
function spawnCombatBolt(stage, event, from, to, onLand, beyond = null) {
  if (stage.reduced()) { onLand(); return; }
  const p = stage.prefix;
  const bolt = document.createElement(event.element ? 'img' : 'div');
  bolt.className = event.element ? `${p}-bolt` : `${p}-bolt ${p}-bolt--melee`;
  if (event.element) {
    bolt.alt = '';
    bolt.src = dungeonEffectAssetUrl(event.element, 'bolt');
    bolt.style.setProperty('--combat-fx-size', `${Math.round(stage.cell * COMBAT_FX.boltCells)}px`);
  }
  bolt.style.left = `${from.x}px`;
  bolt.style.top = `${from.y}px`;
  stage.layer.append(bolt);
  stage.fx.animate(bolt, [{ left: `${from.x}px`, top: `${from.y}px` }, { left: `${to.x}px`, top: `${to.y}px` }], { duration: stage.flightMs, easing: 'ease-in' }, () => {
    onLand();
    if (!beyond) { bolt.remove(); return; }
    stage.fx.animate(bolt, [
      { left: `${to.x}px`, top: `${to.y}px`, opacity: 1 },
      { left: `${beyond.x}px`, top: `${beyond.y}px`, opacity: 0 }
    ], { duration: COMBAT_FX.missPassMs, easing: 'linear' }, () => bolt.remove());
  });
}

function spawnCombatImpact(stage, event, to) {
  if (stage.reduced()) return;
  const p = stage.prefix;
  const impact = document.createElement(event.element ? 'img' : 'div');
  impact.className = event.element ? `${p}-impact` : `${p}-impact ${p}-impact--melee`;
  if (event.element) {
    impact.alt = '';
    impact.src = dungeonEffectAssetUrl(event.element, 'impact');
  }
  impact.style.left = `${to.x}px`;
  impact.style.top = `${to.y}px`;
  impact.style.setProperty('--combat-fx-size', `${Math.round(stage.cell * COMBAT_FX.impactCells)}px`);
  stage.layer.append(impact);
  stage.fx.animate(impact, [{ transform: 'translate(-50%, -50%) scale(0.3)', opacity: 0.95 }, { transform: 'translate(-50%, -50%) scale(1)', opacity: 0 }], { duration: COMBAT_FX.impactMs, easing: 'ease-out' }, () => impact.remove());
}

// 当たった駒がごく短く身を引く（攻めた側から離れる向きに数 px）。
function recoilCombatToken(stage, node, from, to) {
  if (stage.reduced()) return;
  const dx = Math.sign(to.x - from.x) * COMBAT_FX.recoilPx;
  const dy = Math.sign(to.y - from.y) * COMBAT_FX.recoilPx;
  stage.fx.animate(node.firstChild, [{ transform: 'translate(0, 0)' }, { transform: `translate(${dx}px, ${dy}px)`, offset: 0.35 }, { transform: 'translate(0, 0)' }], { duration: COMBAT_FX.recoilMs, easing: 'ease-out' });
}

function flashCombatHurt(stage) {
  stage.hurt.classList.add('is-hurt');
  stage.fx.later(COMBAT_FX.hurtMs, () => stage.hurt.classList.remove('is-hurt'));
}

// 外れた駒が、弾の向きに直角（上寄りの側）へ身をかわして戻る。動きを減らす設定では、その場で一度薄れて戻るだけ。
function dodgeCombatToken(stage, node, from, to) {
  const token = node.firstChild;
  if (stage.reduced()) {
    stage.fx.animate(token, [{ opacity: 1 }, { opacity: 0.35, offset: 0.4 }, { opacity: 1 }], { duration: COMBAT_FX.fadeMs, easing: 'ease-out' });
    return;
  }
  const length = Math.hypot(to.x - from.x, to.y - from.y);
  let side = length ? { x: -(to.y - from.y) / length, y: (to.x - from.x) / length } : { x: 0, y: -1 };
  if (side.y > 0 || (side.y === 0 && side.x < 0)) side = { x: -side.x, y: -side.y };
  const reach = stage.cell * COMBAT_FX.dodgeCells;
  stage.fx.animate(token, [
    { transform: 'translate(0, 0)' },
    { transform: `translate(${side.x * reach}px, ${side.y * reach}px)`, offset: 0.3 },
    { transform: 'translate(0, 0)' }
  ], { duration: COMBAT_FX.dodgeMs, easing: 'ease-out' });
}

// 範囲の空振り: 弾は狙った空きの升に着き、色の抜けた着弾が広く薄く散る（誰も身をかわさず、弾も抜けない）。
function spawnCombatWhiff(stage, event, at) {
  const p = stage.prefix;
  const node = combatFxNode(stage, event.element ? `${p}-impact ${p}-impact--whiff` : `${p}-impact ${p}-impact--melee ${p}-impact--whiff`, at, COMBAT_FX.whiffCells, event.element ? 'img' : 'div');
  if (event.element) node.src = dungeonEffectAssetUrl(event.element, 'impact');
  if (stage.reduced()) { fadeCombatFx(stage, node, 0.5); return; }
  stage.fx.animate(node, [
    { transform: 'translate(-50%, -50%) scale(0.5)', opacity: 0.7 },
    { transform: 'translate(-50%, -50%) scale(1)', opacity: 0 }
  ], { duration: COMBAT_FX.whiffMs, easing: 'ease-out' }, () => node.remove());
}

// 打ち合いの一つ: 当たりは着弾・身を引く動き・浮く数・縁の赤、外れは弾が駒をかすめて抜け駒が身をかわす、空振りは空きの升で散る。
function playCombatStrike(stage, strike) {
  const { event } = strike;
  const from = stage.tileCenter(event.from.x, event.from.y);
  const to = stage.tileCenter(event.to.x, event.to.y);
  if (event.whiff) {
    spawnCombatBolt(stage, event, from, to, () => spawnCombatWhiff(stage, event, to));
    return;
  }
  if (!event.hit) {
    const length = Math.hypot(to.x - from.x, to.y - from.y);
    const pass = stage.cell * COMBAT_FX.missPassCells;
    const beyond = length ? { x: to.x + ((to.x - from.x) / length) * pass, y: to.y + ((to.y - from.y) / length) * pass } : null;
    spawnCombatBolt(stage, event, from, to, () => {
      const node = stage.tokenAt(event.to.x, event.to.y);
      if (node) dodgeCombatToken(stage, node, from, to);
    }, beyond);
    return;
  }
  spawnCombatBolt(stage, event, from, to, () => {
    spawnCombatImpact(stage, event, to);
    const node = stage.tokenAt(event.to.x, event.to.y);
    if (node) recoilCombatToken(stage, node, from, to);
    if (strike.damage !== null) combatFloatWord(stage, to, String(strike.damage), strike.onPlayer ? 'hurt' : 'hit', { crit: strike.crit });
    if (strike.onPlayer) flashCombatHurt(stage);
  });
}

// 回復: 受けた駒に、戻したものの色（HP は緑・MP は青）の光が満ちて引き、駒が一度明るむ。魔法は光の粒が立ちのぼり、品は輪が一つ
// 広がる。使った者と受けた者が別なら、先に同じ色の玉が使った者から受けた者へ渡る。動きを減らす設定では、受けた升の光が薄れるだけ。
function spawnCombatMend(stage, event) {
  const p = stage.prefix;
  const tone = `${p}-mend--${event.resource}`;
  const to = stage.tileCenter(event.to.x, event.to.y);
  const bloom = () => {
    const glow = combatFxNode(stage, `${p}-mend ${tone}`, to, COMBAT_FX.mendCells);
    if (stage.reduced()) { fadeCombatFx(stage, glow, 0.9); return; }
    const duration = COMBAT_FX.mendMs;
    stage.fx.animate(glow, [
      { transform: 'translate(-50%, -50%) scale(0.6)', opacity: 0 },
      { transform: 'translate(-50%, -50%) scale(1)', opacity: 0.9, offset: 0.3 },
      { transform: 'translate(-50%, -50%) scale(1.12)', opacity: 0 }
    ], { duration, easing: 'ease-out' }, () => glow.remove());
    const node = stage.tokenAt(event.to.x, event.to.y);
    if (node) stage.fx.animate(node.firstChild, [{ filter: 'brightness(1)' }, { filter: 'brightness(1.45)', offset: 0.3 }, { filter: 'brightness(1)' }], { duration, easing: 'ease-out' });
    if (event.source === 'item') {
      const ring = combatFxNode(stage, `${p}-mend-ring ${tone}`, to, COMBAT_FX.mendCells);
      stage.fx.animate(ring, [
        { transform: 'translate(-50%, -50%) scale(0.45)', opacity: 0.95 },
        { transform: 'translate(-50%, -50%) scale(1.3)', opacity: 0 }
      ], { duration: duration * 0.7, easing: 'ease-out' }, () => ring.remove());
      return;
    }
    const rise = stage.cell * 0.62;
    for (let index = 0; index < COMBAT_FX.mendMotes; index += 1) {
      const spread = (index / (COMBAT_FX.mendMotes - 1) - 0.5) * stage.cell * 0.62;
      const mote = combatFxNode(stage, `${p}-mend-mote ${tone}`, { x: to.x + spread, y: to.y + stage.cell * (index % 2 ? 0.22 : 0.3) }, 0.09);
      stage.fx.animate(mote, [
        { transform: 'translate(-50%, -50%)', opacity: 0 },
        { transform: `translate(-50%, calc(-50% - ${rise * 0.35}px))`, opacity: 1, offset: 0.3 },
        { transform: `translate(-50%, calc(-50% - ${rise}px))`, opacity: 0 }
      ], { duration: duration * 0.8, delay: index * 40, fill: 'backwards', easing: 'ease-out' }, () => mote.remove());
    }
  };
  if (stage.reduced() || (event.from.x === event.to.x && event.from.y === event.to.y)) { bloom(); return; }
  const from = stage.tileCenter(event.from.x, event.from.y);
  const orb = combatFxNode(stage, `${p}-mend-orb ${tone}`, from, COMBAT_FX.mendOrbCells);
  stage.fx.animate(orb, [{ left: `${from.x}px`, top: `${from.y}px` }, { left: `${to.x}px`, top: `${to.y}px` }], { duration: stage.flightMs, easing: 'ease-in-out' }, () => {
    orb.remove();
    bloom();
  });
}

// 蘇生: 立った升に下から光の柱が伸びて引き、駒が暗がりから明るんで立つ。動きを減らす設定では、柱と駒が薄れて／現れるだけ。
function spawnCombatRevive(stage, event) {
  const at = stage.tileCenter(event.to.x, event.to.y);
  const pillar = combatFxNode(stage, `${stage.prefix}-revive`, { x: at.x, y: at.y + stage.cell * 0.45 }, COMBAT_FX.reviveCells);
  const node = stage.tokenAt(event.to.x, event.to.y);
  if (stage.reduced()) {
    fadeCombatFx(stage, pillar, 0.85);
    if (node) stage.fx.animate(node.firstChild, [{ opacity: 0.2 }, { opacity: 1 }], { duration: COMBAT_FX.fadeMs, easing: 'ease-out' });
    return;
  }
  stage.fx.animate(pillar, [
    { transform: 'translate(-50%, -100%) scaleY(0)', opacity: 0 },
    { transform: 'translate(-50%, -100%) scaleY(1)', opacity: 0.95, offset: 0.35 },
    { transform: 'translate(-50%, -100%) scaleY(1)', opacity: 0 }
  ], { duration: COMBAT_FX.reviveMs, easing: 'ease-out' }, () => pillar.remove());
  if (node) {
    stage.fx.animate(node.firstChild, [
      { opacity: 0.2, filter: 'brightness(0.4)', transform: 'translateY(12%)' },
      { opacity: 1, filter: 'brightness(1.35)', transform: 'translateY(0)', offset: 0.55 },
      { opacity: 1, filter: 'brightness(1)', transform: 'translateY(0)' }
    ], { duration: COMBAT_FX.reviveMs, easing: 'ease-out' });
  }
}

// 回避の魔法をかけた瞬間: 主の駒のまわりに淡い輪が外から絞られて消える。かかっている間の印は、view から描く駒の状態（CSS）が持つ。
function spawnCombatWard(stage, event) {
  const ring = combatFxNode(stage, `${stage.prefix}-ward`, stage.tileCenter(event.to.x, event.to.y), COMBAT_FX.wardCells);
  if (stage.reduced()) { fadeCombatFx(stage, ring, 0.9); return; }
  stage.fx.animate(ring, [
    { transform: 'translate(-50%, -50%) scale(1.5) rotate(0deg)', opacity: 0 },
    { transform: 'translate(-50%, -50%) scale(1) rotate(60deg)', opacity: 0.95, offset: 0.45 },
    { transform: 'translate(-50%, -50%) scale(0.82) rotate(90deg)', opacity: 0 }
  ], { duration: COMBAT_FX.wardMs, easing: 'ease-out' }, () => ring.remove());
}

// event の kind ごとの描き手。知らない kind は描く前に止める。
const COMBAT_BEAT_PAINTERS = Object.freeze({
  melee: playCombatStrike,
  cast: playCombatStrike,
  enemy_attack: playCombatStrike,
  heal: (stage, beat) => spawnCombatMend(stage, beat.event),
  revive: (stage, beat) => spawnCombatRevive(stage, beat.event),
  evasion: (stage, beat) => spawnCombatWard(stage, beat.event)
});

function combatStrikeDelayMs(index) {
  return Math.min(index * COMBAT_FX.strikeStaggerMs, COMBAT_FX.strikeStaggerCapMs);
}

// index 番目の出来事の弾が着く時刻（応答の打ち合いのあとに続く演出の起点）。
function combatBeatLandMs(stage, index) {
  return combatStrikeDelayMs(index) + stage.flightMs;
}

// 一つの応答の出来事を、解いた順に strikeStaggerMs ずつ（上限 strikeStaggerCapMs）ずらして流す。beats は
// [{ event, damage（null なら数を出さない）, onPlayer, crit }]（damage・onPlayer・crit は打ち合いの kind だけが持つ）。
function playCombatEvents(stage, beats) {
  const painters = beats.map((beat) => {
    if (!Object.hasOwn(COMBAT_BEAT_PAINTERS, beat.event.kind)) throw new Error(`combat fx: no painter for event kind ${JSON.stringify(beat.event.kind)}`);
    return COMBAT_BEAT_PAINTERS[beat.event.kind];
  });
  const reduce = stage.reduced();
  beats.forEach((beat, index) => {
    stage.fx.later(reduce ? 0 : combatStrikeDelayMs(index), () => painters[index](stage, beat));
  });
}

function dungeonEntityAt(x, y) {
  for (const [key, tile] of dungeonEntityTiles) if (tile.x === x && tile.y === y) return dungeonEntityNodes.get(key) ?? null;
  return null;
}

// 倒した敵の絵が属性の色の塵にほどける（描き方の粒）。
function dissolveDungeonEnemy(enemy, at, cell) {
  const ghost = document.createElement('img');
  ghost.className = 'dn-ghost';
  ghost.alt = '';
  ghost.src = `${DUNGEON_ASSET_BASE}/enemies/${enemy.archetype_id}.png`;
  ghost.style.left = `${at.x}px`;
  ghost.style.top = `${at.y}px`;
  ghost.style.setProperty('--combat-fx-size', `${Math.round(cell * 0.78)}px`);
  dn.effects.append(ghost);
  if (dungeonReducedMotion()) {
    dungeonFx.animate(ghost, [{ opacity: 0.8 }, { opacity: 0 }], { duration: 260 }, () => ghost.remove());
    return;
  }
  dungeonFx.animate(ghost, [{ opacity: 1, filter: 'blur(0)' }, { opacity: 0, filter: 'blur(3px)' }], { duration: 420, easing: 'ease-in' }, () => ghost.remove());
  for (let index = 0; index < 14; index += 1) {
    const mote = document.createElement('span');
    mote.className = `dn-mote dn-el-${enemy.element}`;
    mote.style.left = `${at.x + (Math.random() - 0.5) * cell * 0.5}px`;
    mote.style.top = `${at.y + (Math.random() - 0.5) * cell * 0.5}px`;
    dn.effects.append(mote);
    const angle = (index / 14) * Math.PI * 2 + Math.random() * 0.4;
    const reach = cell * (0.35 + Math.random() * 0.35);
    dungeonFx.animate(mote, [
      { opacity: 1, transform: 'translate(-50%, -50%) scale(1)' },
      { opacity: 0, transform: `translate(calc(-50% + ${Math.cos(angle) * reach}px), calc(-50% + ${Math.sin(angle) * reach - cell * 0.2}px)) scale(0.4)` }
    ], { duration: 520 + Math.random() * 160, easing: 'ease-out' }, () => mote.remove());
  }
}

// 手に入ったものの絵が、出た升目から主人公の駒へ吸われ、柱の持ち物に並ぶ。
function drawDungeonItemIn(imageUrl, from, to, cell, onArrive) {
  const icon = document.createElement('img');
  icon.className = 'dn-draw-in';
  icon.alt = '';
  icon.src = imageUrl;
  icon.style.setProperty('--combat-fx-size', `${Math.round(cell * 0.5)}px`);
  icon.style.left = `${from.x}px`;
  icon.style.top = `${from.y}px`;
  dn.effects.append(icon);
  if (dungeonReducedMotion()) {
    dungeonFx.animate(icon, [{ opacity: 1 }, { opacity: 0 }], { duration: 400 }, () => { icon.remove(); onArrive(); });
    return;
  }
  dungeonFx.animate(icon, [
    { left: `${from.x}px`, top: `${from.y}px`, opacity: 0, transform: 'translate(-50%, -50%) scale(0.6)' },
    { left: `${from.x}px`, top: `${from.y + cell * 0.12}px`, opacity: 1, transform: 'translate(-50%, -50%) scale(1)', offset: 0.35 },
    { left: `${to.x}px`, top: `${to.y}px`, opacity: 0.2, transform: 'translate(-50%, -50%) scale(0.4)' }
  ], { duration: 560, easing: 'ease-in' }, () => { icon.remove(); onArrive(); });
}

function pulseDungeonCarry(key) {
  const row = dn.carry.querySelector(`[data-key="${CSS.escape(key)}"]`);
  if (!row || dungeonReducedMotion()) return;
  const style = getComputedStyle(dungeonRoot);
  dungeonFx.animate(row, [
    { backgroundColor: style.getPropertyValue('--dungeon-carry-pulse') },
    { backgroundColor: style.getPropertyValue('--dungeon-carry-pulse-end') }
  ], { duration: 700, easing: 'ease-out' });
}

// 下の階は、降りる手を押した瞬間から掛かった暗がりの下で描かれている。暗いまま一拍置いて明け、「N 階」を出す。
function markDungeonDescent(floor) {
  dn.veil.classList.add('is-dark');
  dn.floorMark.textContent = `${floor} 階`;
  dungeonFx.later(dungeonReducedMotion() ? 0 : DUNGEON_DESCENT_DARK_HOLD_MS, () => {
    dn.veil.classList.remove('is-dark');
    dn.floorMark.classList.add('is-shown');
    dungeonFx.later(1100, () => dn.floorMark.classList.remove('is-shown'));
  });
}

// ── 手番の読み解き: 数字は server の応答の log（新しく足された行の「<名>に N ダメージ。」）から取り、events の to の升目の相手と
// 名前で結ぶ。log の行に数字が無い出来事（範囲の投げ物の巻き込み・同行者が倒れた）は数字を出さない。 ─────────────────────
function newDungeonLogLines(prevLog, nextLog) {
  if (!prevLog) return [...nextLog];
  for (let shift = 0; shift <= prevLog.length; shift += 1) {
    const overlap = prevLog.length - shift;
    let same = true;
    for (let i = 0; i < overlap; i += 1) {
      if (prevLog[shift + i] !== nextLog[i]) { same = false; break; }
    }
    if (same) return nextLog.slice(overlap);
  }
  return [...nextLog];
}

function dungeonNamesAt(prev, next, x, y) {
  const names = [];
  if (next.player.x === x && next.player.y === y) names.push(DUNGEON_PLAYER_NAME);
  if (next.companion && next.companion.x === x && next.companion.y === y) names.push(next.companion.name);
  for (const enemy of [...prev.enemies, ...next.enemies]) if (enemy.x === x && enemy.y === y && !names.includes(enemy.name)) names.push(enemy.name);
  return names;
}

function takeDungeonDamage(lines, used, names) {
  for (let index = 0; index < lines.length; index += 1) {
    if (used.has(index)) continue;
    for (const name of names) {
      const match = lines[index].match(new RegExp(`${name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}(?:に|の防御を貫き)(\\d+)ダメージ。`));
      if (match) {
        used.add(index);
        return Number(match[1]);
      }
    }
  }
  return null;
}

// 応答の出来事を解いた順の beats に読む。打ち合いには数（log から）と、主人公の升へ着くかを添える。
function readDungeonBeats(prev, next, events, lines) {
  const used = new Set();
  return events.map((event) => {
    if (!COMBAT_STRIKE_KINDS.has(event.kind)) return { event };
    const damage = event.hit ? takeDungeonDamage(lines, used, dungeonNamesAt(prev, next, event.to.x, event.to.y)) : null;
    const onPlayer = event.to.x === next.player.x && event.to.y === next.player.y;
    return { event, damage, onPlayer, crit: false };
  });
}

function readDungeonTurn(prev, next, lines) {
  const beats = readDungeonBeats(prev, next, next.events, lines);
  const kills = [];
  for (const line of lines) {
    const match = line.match(/^(.+)を倒した。$/);
    if (!match) continue;
    const enemy = prev.enemies.find((candidate) => candidate.name === match[1] && !next.enemies.some((alive) => alive.uid === candidate.uid) && !kills.includes(candidate));
    if (enemy) kills.push(enemy);
  }
  const prevMaterials = new Map(prev.material_buffer.map((item) => [item.item_id, item.quantity]));
  const materials = next.material_buffer.filter((item) => item.quantity > (prevMaterials.get(item.item_id) ?? 0));
  const pickedItems = prev.floor === next.floor
    ? prev.items.filter((item) => !next.items.some((left) => left.uid === item.uid) && item.x === next.player.x && item.y === next.player.y)
    : [];
  return { beats, kills, materials, pickedItems, descended: prev.run_id === next.run_id && next.floor !== prev.floor };
}

// 潜りが終わる手番の応答は盤を持たないので、直前の盤の上で出来事だけを読む。
function readDungeonEndedTurn(last, events, lines) {
  return { beats: readDungeonBeats(last, last, events, lines), kills: [], materials: [], pickedItems: [], descended: false };
}

function playDungeonTurn(reading, next) {
  const { cell } = dungeonCellMetrics();
  if (!Number.isFinite(cell)) return;
  const reduce = dungeonReducedMotion();
  const stage = {
    prefix: 'dn',
    fx: dungeonFx,
    layer: dn.effects,
    hurt: dn.hurt,
    cell,
    flightMs: COMBAT_FX.boltMs,
    reduced: dungeonReducedMotion,
    tileCenter: dungeonTileCenter,
    tokenAt: dungeonEntityAt
  };
  const lastLand = combatBeatLandMs(stage, Math.max(0, reading.beats.findLastIndex((beat) => COMBAT_STRIKE_KINDS.has(beat.event.kind))));
  playCombatEvents(stage, reading.beats);
  const killAt = new Map();
  reading.kills.forEach((enemy) => {
    killAt.set(enemy.uid, dungeonTileCenter(enemy.x, enemy.y));
    dungeonFx.later(reduce ? 0 : lastLand, () => dissolveDungeonEnemy(enemy, killAt.get(enemy.uid), cell));
  });
  const playerAt = () => dungeonTileCenter(next.player.x, next.player.y);
  reading.materials.forEach((item, index) => {
    const origin = reading.kills.length ? killAt.get(reading.kills[Math.min(index, reading.kills.length - 1)].uid) : playerAt();
    dungeonFx.later(reduce ? 0 : lastLand + 520 + index * 90, () => drawDungeonItemIn(`${DUNGEON_ASSET_BASE}/material-icons/${item.item_id}.png`, origin, playerAt(), cell, () => pulseDungeonCarry(`material:${item.item_id}`)));
  });
  reading.pickedItems.forEach((item) => {
    if (item.kind === 'treasure_chest') pulseDungeonCarry(`item:${item.kind}`);
    else drawDungeonItemIn(`${DUNGEON_ASSET_BASE}/items/${item.kind}.png`, playerAt(), playerAt(), cell, () => pulseDungeonCarry(`item:${item.kind}`));
  });
  if (reading.descended) markDungeonDescent(next.floor);
}

// ── 柱: 上（階と手番・主人公と同行者の札）・中（会話とこれまでの出来事）・下（魔法の札・持ち物） ──────────────────────
// 札は駒と同じ顔（主人公は紋章）に、駒と同じ金の縁と黒い地の目盛りを添える。札は潜りの顔ぶれが変わったときだけ作り、手番ごとには
// 目盛りと数だけを動かす。
function dungeonPartyCard(key, name, { crest = false, imageUrl = null, onOpen }) {
  const card = document.createElement('div');
  card.className = `dn-member dn-member--${key}`;
  const token = dungeonTokenNode({ role: crest ? 'self' : 'ally', crest, imageUrl });
  token.classList.add('dn-member-token');
  const head = document.createElement('button');
  head.type = 'button';
  head.className = 'dn-member-name';
  head.textContent = name;
  head.addEventListener('click', () => { head.blur(); try { onOpen(); } catch (error) { reportError(error); } });
  const row = (kind, label) => {
    const wrap = document.createElement('div');
    wrap.className = `dn-member-gauge dn-member-gauge--${kind}`;
    const tag = document.createElement('span');
    tag.className = 'dn-member-tag';
    tag.textContent = label;
    const value = document.createElement('span');
    value.className = 'dn-member-value';
    wrap.append(tag, dungeonGaugeNode(kind), value);
    return wrap;
  };
  card.append(token, head, row('hp', '体'), row('mp', '魔'));
  return card;
}

function updateDungeonPartyCard(card, name, actor, down) {
  card.classList.toggle('is-down', down);
  const head = card.querySelector('.dn-member-name');
  const label = down ? `${name}（戦闘不能）` : name;
  if (head.textContent !== label) head.textContent = label;
  for (const kind of ['hp', 'mp']) {
    const wrap = card.querySelector(`.dn-member-gauge--${kind}`);
    setCombatGauge(wrap.querySelector('.dn-gauge'), actor[kind], actor[`max_${kind}`]);
    const text = String(actor[kind]);
    const value = wrap.querySelector('.dn-member-value');
    if (value.textContent !== text) value.textContent = text;
  }
}

let dungeonPartyCast = null;
function renderDungeonPartyAndDepth(view) {
  dn.depthFloor.textContent = `${view.floor} / ${view.max_floors} 階`;
  dn.depthTurn.textContent = `${view.turn} 手目`;
  const cast = JSON.stringify([view.run_id, view.companion?.character_id ?? null]);
  if (cast !== dungeonPartyCast) {
    dungeonPartyCast = cast;
    const cards = [dungeonPartyCard('player', DUNGEON_PLAYER_NAME, { crest: true, onOpen: () => openDungeonHeroDetail() })];
    if (view.companion) {
      const companion = view.companion;
      cards.push(dungeonPartyCard('companion', companion.name, { imageUrl: dungeonCompanionFaceUrl(companion), onOpen: () => openDungeonCompanionDetail(currentDungeonView.companion) }));
    }
    dn.party.replaceChildren(...cards);
  }
  updateDungeonPartyCard(dn.party.querySelector('.dn-member--player'), DUNGEON_PLAYER_NAME, view.player, false);
  if (view.companion) updateDungeonPartyCard(dn.party.querySelector('.dn-member--companion'), view.companion.name, view.companion, view.companion.down);
}

// 札を押したあとは focus を body へ返す（押した直後の方向キーがそのまま歩きになる）。
function dungeonActButton({ className, label, cost, title, disabled, onPress }) {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = className;
  button.title = title;
  button.disabled = disabled;
  const name = document.createElement('span');
  name.className = 'dn-card-name';
  name.textContent = label;
  button.append(name);
  if (cost !== null) {
    const mp = document.createElement('span');
    mp.className = 'dn-card-cost';
    mp.textContent = cost;
    button.append(mp);
  }
  button.addEventListener('click', () => {
    button.blur();
    onPress();
  });
  return button;
}

let dungeonSpellSignature = null;
function renderDungeonSpells(view) {
  const healing = view.healing_spell;
  const pierce = view.pierce_spell;
  const evasion = view.evasion_spell;
  if (!healing || healing.action_type !== 'heal_spell' || typeof healing.can_use !== 'boolean') throw new Error('dungeon view is missing healing_spell');
  if (!pierce || pierce.action_type !== 'pierce_spell' || typeof pierce.can_use !== 'boolean') throw new Error('dungeon view is missing pierce_spell');
  if (!evasion || evasion.action_type !== 'evasion_spell' || typeof evasion.can_use !== 'boolean' || typeof evasion.active !== 'boolean') throw new Error('dungeon view is missing evasion_spell');
  const signature = JSON.stringify([view.player.mp, view.castable_elements, healing, pierce, evasion]);
  if (signature === dungeonSpellSignature) return;
  dungeonSpellSignature = signature;
  const buttons = view.castable_elements.map((spell) => {
    const button = dungeonActButton({
      className: `dn-card dn-el-${spell.element}`,
      label: DUNGEON_MAGIC_LABELS[spell.element] ?? spell.element,
      cost: `${spell.mp_cost}`,
      title: `${spell.label} 威力${spell.power} / MP${spell.mp_cost}`,
      disabled: view.player.mp < spell.mp_cost,
      onPress: () => dungeonDo({ type: 'cast', element: spell.element }).catch(reportError)
    });
    button.dataset.element = spell.element;
    return button;
  });
  buttons.push(dungeonActButton({ className: 'dn-card dn-card--craft', label: '回復', cost: `${healing.mp_cost}`, title: `自己回復 +${healing.heal_amount} / MP${healing.mp_cost}`, disabled: !healing.can_use, onPress: () => dungeonDo({ type: 'heal_spell' }).catch(reportError) }));
  buttons.push(dungeonActButton({ className: 'dn-card dn-card--craft', label: '貫通', cost: `${pierce.mp_cost}`, title: `貫通魔法（防御無視）威力${pierce.power} / MP${pierce.mp_cost}`, disabled: !pierce.can_use, onPress: () => dungeonDo({ type: 'pierce_spell' }).catch(reportError) }));
  buttons.push(dungeonActButton({
    className: `dn-card dn-card--craft${evasion.active ? ' is-active' : ''}`,
    label: evasion.active ? `回避 残${evasion.turns_remaining}` : '回避',
    cost: `${evasion.mp_cost}`,
    title: evasion.active
      ? `回避魔法（発動中・残り${evasion.turns_remaining}ターン）回避+${evasion.evasion_bonus} / MP${evasion.mp_cost}`
      : `回避魔法（${evasion.duration}ターン）回避+${evasion.evasion_bonus} / MP${evasion.mp_cost}`,
    disabled: !evasion.can_use,
    onPress: () => dungeonDo({ type: 'evasion_spell' }).catch(reportError)
  }));
  dn.spells.replaceChildren(...buttons);
}

// The compact effect summary shown on a consumable chip. effect_kind is a closed engine set — an unknown
// kind is a desync and throws (no silent generic label).
function dungeonConsumableSummaryText(row) {
  const element = DUNGEON_MAGIC_LABELS[row.element] ?? row.element;
  switch (row.effect_kind) {
    case 'attack_single': return `${element}・単体 威力${row.power}`;
    case 'attack_area': return `${element}・範囲${row.radius} 威力${row.power}`;
    case 'heal': return `HP+${row.heal_amount}`;
    case 'heal_full': return 'HP全回復';
    case 'mp_restore': return `MP+${row.mp_amount}`;
    case 'mp_restore_full': return 'MP全回復';
    case 'revive': return '同行者を蘇生';
    default: throw new Error(`unknown consumable effect_kind: ${JSON.stringify(row.effect_kind)}`);
  }
}

function dungeonConsumableDisabledReason(view, row) {
  if (row.target_mode === 'revive') {
    if (view.revive_used) return 'この探索では蘇生を使い切りました。';
    if (!view.companion || !view.companion.down) return 'ダウン中の同行者がいません。';
  }
  return null;
}

// 持ち物は中身があるときだけ並ぶ（持ち込んだ消耗品・拾ったアイテム・拾った素材）。
let dungeonCarrySignature = null;
// The row contracts of the carry and the result lists: a non-empty name, a finite count. A malformed row throws.
function requiredDungeonItemName(item, label, field = 'name') {
  if (typeof item[field] !== 'string' || item[field] === '') throw new Error(`${label} requires a non-empty ${field}, got ${JSON.stringify(item)}`);
  return item[field];
}

function requiredDungeonItemCount(item, label, field) {
  if (typeof item[field] !== 'number' || !Number.isFinite(item[field])) throw new Error(`${label} requires a numeric ${field}, got ${JSON.stringify(item)}`);
  return item[field];
}

function renderDungeonCarry(view) {
  if (!Array.isArray(view.consumables) || !Array.isArray(view.inventory) || !Array.isArray(view.material_buffer)) throw new Error('dungeon view is missing an item list');
  const signature = JSON.stringify([view.consumables, view.inventory, view.material_buffer, view.revive_used, view.companion?.down ?? null, dungeonConsumableTargeting?.item_id ?? null]);
  if (signature === dungeonCarrySignature) return;
  dungeonCarrySignature = signature;
  const rows = [];
  for (const row of view.consumables) {
    const reason = dungeonConsumableDisabledReason(view, row);
    const button = document.createElement('button');
    button.type = 'button';
    button.className = `dn-carry-row dn-carry-row--use${row.element ? ` dn-el-${row.element}` : ''}`;
    button.dataset.key = `consumable:${row.item_id}`;
    button.dataset.targetMode = row.target_mode;
    if (dungeonConsumableTargeting?.item_id === row.item_id) button.dataset.armed = 'true';
    button.disabled = reason !== null;
    button.title = reason ?? row.description ?? '';
    button.innerHTML = '<span class="dn-carry-name"></span><span class="dn-carry-note"></span><span class="dn-carry-count"></span>';
    button.querySelector('.dn-carry-name').textContent = row.name;
    button.querySelector('.dn-carry-note').textContent = dungeonConsumableSummaryText(row);
    button.querySelector('.dn-carry-count').textContent = `×${row.quantity}`;
    button.addEventListener('click', () => { button.blur(); try { onDungeonConsumableClick(row); } catch (error) { reportError(error); } });
    rows.push(button);
  }
  for (const item of view.inventory) {
    requiredDungeonItemName(item, 'dungeon inventory item', 'kind');
    requiredDungeonItemName(item, 'dungeon inventory item');
    requiredDungeonItemCount(item, 'dungeon inventory item', 'count');
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'dn-carry-row dn-carry-row--use';
    button.dataset.key = `item:${item.kind}`;
    button.innerHTML = item.kind === 'treasure_chest'
      ? `<span class="dn-carry-icon">${chestSvg()}</span><span class="dn-carry-name"></span><span class="dn-carry-count"></span>`
      : '<img class="dn-carry-icon" alt=""><span class="dn-carry-name"></span><span class="dn-carry-count"></span>';
    if (item.kind !== 'treasure_chest') button.querySelector('.dn-carry-icon').src = `${DUNGEON_ASSET_BASE}/items/${item.kind}.png`;
    button.querySelector('.dn-carry-name').textContent = item.name;
    button.querySelector('.dn-carry-count').textContent = `×${item.count}`;
    button.addEventListener('click', () => { button.blur(); dungeonDo({ type: 'use_item', item_kind: item.kind }).catch(reportError); });
    rows.push(button);
  }
  for (const item of view.material_buffer) {
    requiredDungeonItemName(item, 'dungeon material', 'display_name');
    requiredDungeonItemCount(item, 'dungeon material', 'quantity');
    const row = document.createElement('div');
    row.className = 'dn-carry-row';
    row.dataset.key = `material:${item.item_id}`;
    row.innerHTML = '<img class="dn-carry-icon" alt=""><span class="dn-carry-name"></span><span class="dn-carry-count"></span>';
    row.querySelector('.dn-carry-icon').src = `${DUNGEON_ASSET_BASE}/material-icons/${item.item_id}.png`;
    row.querySelector('.dn-carry-name').textContent = item.display_name;
    row.querySelector('.dn-carry-count').textContent = `×${item.quantity}`;
    rows.push(row);
  }
  dn.carry.replaceChildren(...rows);
  dn.carry.hidden = rows.length === 0;
}

// 記録: 柱の中ほどは、この潜りの会話と出来事が起きた順に並ぶ 1 本の記録で、札のすぐ下から書き始め、溢れたら上へ遡れる。出来事の
// 行は手番ごとに末尾へ足すだけで、読み返している間（末尾から離れている間）は位置を奪わない。
const dungeonJournal = { talkCommitted: 0, live: null };

function dungeonJournalAtEnd() {
  return dn.journal.scrollHeight - dn.journal.scrollTop - dn.journal.clientHeight < 8;
}

function appendDungeonRecord(lines, errorText) {
  if (!lines.length && !errorText) return;
  const stick = dungeonJournalAtEnd();
  const rows = lines.map((line) => {
    const p = document.createElement('p');
    p.className = 'dn-event';
    p.textContent = line;
    return p;
  });
  if (errorText) {
    const p = document.createElement('p');
    p.className = 'dn-event is-note';
    p.textContent = errorText;
    rows.push(p);
  }
  dn.journal.append(...rows);
  if (stick) dn.journal.scrollTop = dn.journal.scrollHeight;
}

dn.journal.addEventListener('keydown', (event) => { if (event.key === 'Escape') { event.preventDefault(); dn.journal.blur(); } });
dn.journal.addEventListener('scroll', () => { dn.journal.classList.toggle('is-scrolled', dn.journal.scrollTop > 0); }, { passive: true });

// 階が変わるたびに、記録に階の区切りを置く（遡るときの目印）。
function appendDungeonFloorMark(floor) {
  const stick = dungeonJournalAtEnd();
  const mark = document.createElement('p');
  mark.className = 'dn-event dn-event--floor';
  mark.textContent = `${floor} 階`;
  dn.journal.append(mark);
  if (stick) dn.journal.scrollTop = dn.journal.scrollHeight;
}

function clearDungeonJournal() {
  dungeonJournal.talkCommitted = 0;
  dungeonJournal.live = null;
  dn.journal.replaceChildren();
}

// ── 同行者との会話: 共有の runAssistantSseStream が返事を吹き出しごとに cooldown を挟んで揃え、共有の createMessageRows が行を
// 作る。この区画が持つのは置き場だけ — 会話は記録の末尾に一続きとして書き、書き直すのはまだ確定していない一続き（送った行・流れて
// いる返事・待ちの点）だけで、commitState で確定する（確定した行は以後の手番の出来事の行より前に残る）。会話の間は手番が進まない
// ので、一続きはいつも記録の末尾にある。
let dungeonVoiceSpoken = false;

function dungeonCompanionIdentity() {
  const companion = currentDungeonView?.companion;
  return { character_id: companion?.character_id ?? null, character_name: companion?.name ?? '' };
}

// Maps the run-scoped companion conversation into display messages, carrying each assistant turn's expression so the
// journal shows per-message faces (the conversation pipeline is the source of truth for the full message list).
function dungeonMessagesFromConversation(conversation) {
  const identity = dungeonCompanionIdentity();
  return (conversation?.messages ?? [])
    .filter((message) => message.role === 'user' || message.role === 'assistant')
    .map((message) => {
      if (message.role === 'assistant') {
        return {
          role: 'assistant',
          character_id: identity.character_id,
          character_name: identity.character_name,
          content: message.content ?? '',
          face_emotion_variant_id: message.face_emotion_variant_id ?? 'face_neutral',
          expression: message.expression ?? 'neutral'
        };
      }
      return { role: 'user', content: message.content ?? '' };
    });
}

function renderDungeonTalkLog(messages, { popFromDisplayIndex = -1, settle = false } = {}) {
  dungeonChatMessages = messages;
  const displayList = displayMessages(messages);
  const rows = createMessageRows(displayList, popFromDisplayIndex, false).slice(dungeonJournal.talkCommitted);
  // A homunculus companion is absent from the selectable roster, so the shared rows cannot resolve its face; the run
  // view companion's face_url overrides each of its rows here (the shared createMessageRows stays untouched).
  const companion = currentDungeonView?.companion;
  if (companion && dungeonCompanionIsHomunculus(companion)) {
    for (const row of rows) for (const image of row.querySelectorAll('.message-face img')) setActorImageSource(image, companion.face_url);
  }
  if (dungeonTalkPending && !settle) {
    const waiting = document.createElement('div');
    waiting.className = 'dn-line dn-line--waiting';
    waiting.innerHTML = '<span class="dn-wait-dot"></span><span class="dn-wait-dot"></span><span class="dn-wait-dot"></span>';
    rows.push(waiting);
  }
  if (!dungeonJournal.live) {
    dungeonJournal.live = document.createElement('div');
    dungeonJournal.live.className = 'dn-talk-block';
    dn.journal.append(dungeonJournal.live);
  }
  dungeonJournal.live.replaceChildren(...rows);
  if (settle) {
    if (!rows.length) dungeonJournal.live.remove();
    dungeonJournal.live = null;
    dungeonJournal.talkCommitted = displayList.length;
  }
  dn.journal.scrollTop = dn.journal.scrollHeight;
  // The companion's first reply line of this exchange also rises from its token on the board.
  const revealed = popFromDisplayIndex >= 0 ? displayList[popFromDisplayIndex] : null;
  if (revealed?.role === 'assistant' && !dungeonVoiceSpoken) {
    dungeonVoiceSpoken = true;
    speakDungeonVoice(revealed.content);
  }
}

// The dungeon companion mounts the shared streaming chat controller with its own history store, render target,
// identity, and conversation mapping.
const dungeonChatSurface = {
  getHistory: () => dungeonChatMessages,
  setHistory: (messages) => { dungeonChatMessages = messages; },
  render: (messages, options) => renderDungeonTalkLog(messages, options),
  mapMessages: (conversation) => dungeonMessagesFromConversation(conversation),
  assistantIdentity: () => dungeonCompanionIdentity(),
  commitState: (result) => {
    dungeonTalkPending = false;
    syncDungeonSpeaking();
    renderDungeonTalkLog(dungeonMessagesFromConversation(result.conversation), { settle: true });
  },
  refresh: async () => {}
};

// A companion exchange starts: the journal shows the waiting dots and the board keeps the speaker in the window.
function beginDungeonTalk() {
  dungeonTalkPending = true;
  dungeonVoiceSpoken = false;
  frameDungeonSpeaker();
}

function renderDungeonTalkAvailability(view) {
  const disabled = !view.companion || view.companion.down;
  dn.talkInput.disabled = disabled;
  dn.talkSend.disabled = disabled;
}

function isDungeonModalOpen() {
  return DUNGEON_MODALS.some((modal) => !modal.hidden);
}

// Restore keyboard focus to the talk input once the companion's reply has revealed to its last 吹き出し, so the next
// utterance is typed and sent without a mouse — unless the screen left, the run has no companion, a window is open, the
// input is disabled (a downed companion), or a board key was pressed during the reply (the player already chose to
// walk). preventScroll keeps a scrolled-up read position in place.
function focusDungeonTalkInputIfContinuing() {
  if (!screens['academy-dungeon'].classList.contains('active')) return;
  if (dungeonRoot.dataset.scene !== 'play' || !currentDungeonView?.companion) return;
  if (isDungeonModalOpen() || dungeonBoardKeyPressedSinceTalk || dn.talkInput.disabled) return;
  dn.talkInput.focus({ preventScroll: true });
}

// The talk's error line: a failure the turn survived (its utterances stay shown) is reported here; the next send
// clears it.
function setDungeonTalkStatus(message, { tone = null } = {}) {
  const status = document.querySelector('#dungeon-talk-status');
  if (!status) throw new Error('dungeon talk status line (#dungeon-talk-status) is missing (broken markup wiring)');
  const text = String(message ?? '').trim();
  status.hidden = !text;
  status.textContent = text;
  if (text && tone) status.dataset.tone = tone;
  else delete status.dataset.tone;
}

async function dungeonTalk() {
  const text = dn.talkInput.value.trim();
  if (!text || dungeonActionInFlight || !currentDungeonView?.companion || currentDungeonView.companion.down) return;
  setDungeonTalkStatus('');
  dungeonActionInFlight = true;
  dungeonBoardKeyPressedSinceTalk = false;
  dn.talkInput.disabled = true;
  dn.talkSend.disabled = true;
  // Snapshot the committed history so a failed send can roll the optimistic line back out.
  const previousMessages = dungeonChatMessages;
  try {
    dn.talkInput.value = '';
    beginDungeonTalk();
    // Show the player's line immediately, then stream the companion reply through the shared controller (tokens,
    // per-message expression, cooldown-paced reveal).
    dungeonChatSurface.render([...previousMessages, { role: 'user', content: text }]);
    const result = await runAssistantSseStream({
      surface: dungeonChatSurface,
      endpoint: '/api/dungeon/companion/talk/stream',
      body: { player_input: text },
      statusPrefix: 'companion',
      finalAssistantMode: 'last',
      refreshAfter: false
    });
    if (result.prompt_prewarm_error) setDungeonTalkStatus(errorDisplayMessage(result.prompt_prewarm_error), { tone: 'error' });
  } catch (error) {
    // Roll the optimistic (and any partially revealed) line out by restoring the pre-send history, and put the text
    // back in the input so the player can retry.
    dungeonTalkPending = false;
    syncDungeonSpeaking();
    dn.talkInput.value = text;
    renderDungeonTalkLog(previousMessages, { settle: true });
    reportError(error);
  } finally {
    dungeonActionInFlight = false;
    if (currentDungeonView) renderDungeonTalkAvailability(currentDungeonView);
    focusDungeonTalkInputIfContinuing();
  }
}

let dungeonTalkIsComposing = false;
dn.talkInput.addEventListener('compositionstart', () => { dungeonTalkIsComposing = true; });
dn.talkInput.addEventListener('compositionend', () => { dungeonTalkIsComposing = false; });
dn.talkInput.addEventListener('keydown', (event) => {
  if (enterShouldSubmit(event, dungeonTalkIsComposing)) {
    event.preventDefault();
    dungeonTalk().catch(reportError);
    return;
  }
  // Escape leaves the input so the arrow keys walk again (an IME composition keeps its own Escape).
  if (event.key === 'Escape' && !event.isComposing && !dungeonTalkIsComposing) {
    event.preventDefault();
    dn.talkInput.blur();
  }
});
dn.talkSend.addEventListener('click', () => dungeonTalk().catch(reportError));

// ── 照準と対象選び: auto/revive はすぐ撃ち、aim は盤の升目、ally は主人公か同行者を選ぶ。Esc・同じ札・中止でやめる ───
function onDungeonConsumableClick(row) {
  if (dungeonActionInFlight) return;
  if (dungeonConsumableTargeting?.item_id === row.item_id) { cancelDungeonConsumableTargeting(); return; }
  cancelDungeonConsumableTargeting();
  if (row.target_mode === 'auto' || row.target_mode === 'revive') { useDungeonConsumable(row.item_id); return; }
  if (row.target_mode === 'aim') { enterDungeonAimMode(row); return; }
  if (row.target_mode === 'ally') { openDungeonAllyTargetPrompt(row); return; }
  throw new Error(`unknown consumable target_mode: ${JSON.stringify(row.target_mode)}`);
}

function useDungeonConsumable(itemId, extra = {}) {
  teardownDungeonConsumableTargeting();
  dungeonDo({ type: 'use_consumable', item_id: itemId, ...extra }).catch(reportError);
}

function dungeonHasLineOfSight(view, from, to) {
  const dx = to.x - from.x;
  const dy = to.y - from.y;
  const steps = Math.max(Math.abs(dx), Math.abs(dy));
  for (let step = 1; step < steps; step += 1) {
    const x = Math.round(from.x + (dx * step) / steps);
    const y = Math.round(from.y + (dy * step) / steps);
    if (x < 0 || y < 0 || x >= view.width || y >= view.height || view.tiles[y][x] !== 'floor') return false;
  }
  return true;
}

function dungeonAimTileValid(view, x, y) {
  if (x < 0 || y < 0 || x >= view.width || y >= view.height) return false;
  if (!view.explored[y][x] || view.tiles[y][x] !== 'floor') return false;
  return dungeonHasLineOfSight(view, view.player, { x, y });
}

function showDungeonTargeting(text, actions) {
  const message = document.createElement('span');
  message.textContent = text;
  const row = document.createElement('span');
  row.className = 'dn-targeting-actions';
  for (const action of actions) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'dn-quiet';
    button.textContent = action.label;
    if (action.disabled) button.disabled = true;
    if (action.title) button.title = action.title;
    button.addEventListener('click', () => { button.blur(); try { action.onClick(); } catch (error) { reportError(error); } });
    row.append(button);
  }
  dn.targeting.replaceChildren(message, row);
  dn.targeting.hidden = false;
}

function enterDungeonAimMode(row) {
  const view = currentDungeonView;
  dungeonConsumableTargeting = { item_id: row.item_id, mode: 'aim' };
  const layer = document.createElement('div');
  layer.className = 'dn-aim';
  layer.style.setProperty('--dn-cols', view.width);
  layer.style.setProperty('--dn-rows', view.height);
  const cells = [];
  for (let y = 0; y < view.height; y += 1) {
    for (let x = 0; x < view.width; x += 1) {
      const cell = document.createElement('div');
      cell.className = 'dn-aim-cell';
      cell.dataset.x = x;
      cell.dataset.y = y;
      if (view.explored[y][x] && view.tiles[y][x] === 'floor') cell.classList.add('is-known');
      if (dungeonAimTileValid(view, x, y)) cell.classList.add('is-valid');
      cells.push(cell);
    }
  }
  layer.replaceChildren(...cells);
  // 巻き込む範囲は一度でも見た床だけに取り、その外周の辺を data-edge（t・r・b・l）で持たせる。CSS は升目を塗らずに外周の線と
  // 着弾の点の印だけを描くので、照準の間も灯りと闇の濃さは盤のまま見える。
  const clearBlast = () => {
    for (const cell of layer.querySelectorAll('.is-blast, .is-point')) {
      cell.classList.remove('is-blast', 'is-point');
      delete cell.dataset.edge;
    }
  };
  layer.addEventListener('pointermove', (event) => {
    const cell = event.target.closest('.dn-aim-cell');
    clearBlast();
    if (!cell || !cell.classList.contains('is-valid')) return;
    const cx = Number(cell.dataset.x);
    const cy = Number(cell.dataset.y);
    const inBlast = (x, y) => x >= 0 && y >= 0 && x < view.width && y < view.height
      && Math.abs(x - cx) + Math.abs(y - cy) <= row.radius && cells[y * view.width + x].classList.contains('is-known');
    for (const other of cells) {
      const x = Number(other.dataset.x);
      const y = Number(other.dataset.y);
      if (!inBlast(x, y)) continue;
      other.classList.add('is-blast');
      other.dataset.edge = [[0, -1, 't'], [1, 0, 'r'], [0, 1, 'b'], [-1, 0, 'l']].filter(([dx, dy]) => !inBlast(x + dx, y + dy)).map(([, , side]) => side).join('');
    }
    cell.classList.add('is-point');
  });
  layer.addEventListener('pointerleave', clearBlast);
  layer.addEventListener('click', (event) => {
    if (dungeonActionInFlight) return;
    const cell = event.target.closest('.dn-aim-cell');
    if (!cell || !cell.classList.contains('is-valid')) return;
    useDungeonConsumable(row.item_id, { aim: { x: Number(cell.dataset.x), y: Number(cell.dataset.y) } });
  });
  dn.board.append(layer);
  dungeonRoot.dataset.aiming = 'true';
  showDungeonTargeting(`「${row.name}」の着弾点を選んでください（Escで中止）。`, [{ label: '中止', onClick: () => cancelDungeonConsumableTargeting() }]);
  dungeonCarrySignature = null;
  renderDungeonCarry(view);
}

function openDungeonAllyTargetPrompt(row) {
  const view = currentDungeonView;
  dungeonConsumableTargeting = { item_id: row.item_id, mode: 'ally' };
  const usable = !!view.companion && !view.companion.down;
  showDungeonTargeting(`「${row.name}」を誰に使いますか？`, [
    { label: DUNGEON_PLAYER_NAME, onClick: () => useDungeonConsumable(row.item_id, { target: 'player' }) },
    {
      label: view.companion ? view.companion.name : '同行者',
      onClick: () => useDungeonConsumable(row.item_id, { target: 'companion' }),
      disabled: !usable,
      title: !view.companion ? '同行者がいません。' : (view.companion.down ? '同行者はダウン中です（蘇生が必要）。' : '')
    },
    { label: '中止', onClick: () => cancelDungeonConsumableTargeting() }
  ]);
  dungeonCarrySignature = null;
  renderDungeonCarry(view);
}

function teardownDungeonConsumableTargeting() {
  dungeonConsumableTargeting = null;
  dn.board.querySelector('.dn-aim')?.remove();
  delete dungeonRoot.dataset.aiming;
  dn.targeting.hidden = true;
  dn.targeting.replaceChildren();
}

function cancelDungeonConsumableTargeting() {
  const was = dungeonConsumableTargeting !== null;
  teardownDungeonConsumableTargeting();
  if (was && currentDungeonView) {
    dungeonCarrySignature = null;
    renderDungeonCarry(currentDungeonView);
  }
}

// ── unified actor-detail shell ───────────────────────────────────────────────────────────────────────────
// The section grammar for a run-time actor detail (the arena's actor detail): an optional image slot (companion
// only — selectable standee / homunculus face; the hero has none), the 11-value parameters, the read-only equipment,
// and an optional 獲得予定 section. The structural class names (actor-detail-*) are scoped by the host container's
// token layer. The caller builds each section's inner nodes with its own builders; this shell only lays out the
// section grammar. A null image / acquisition node omits that section.
function buildActorDetailBody({ imageNode = null, parameterNodes, equipmentNode, acquisitionNode = null }) {
  const sections = document.createElement('div');
  sections.className = 'actor-detail-sections';
  if (imageNode) sections.append(buildActorDetailSection(null, [imageNode], 'actor-detail-image-section'));
  sections.append(buildActorDetailSection('能力値', parameterNodes, 'actor-detail-parameters-section'));
  sections.append(buildActorDetailSection('装備', [equipmentNode], 'actor-detail-equipment-section'));
  if (acquisitionNode) sections.append(buildActorDetailSection('獲得予定', [acquisitionNode], 'actor-detail-acquisition-section'));
  return sections;
}

function buildActorDetailSection(heading, nodes, modifierClass) {
  const section = document.createElement('section');
  section.className = `actor-detail-section${modifierClass ? ` ${modifierClass}` : ''}`;
  if (heading) {
    const head = document.createElement('h4');
    head.className = 'actor-detail-section-head';
    head.textContent = heading;
    section.append(head);
  }
  section.append(...nodes);
  return section;
}

// The companion image slot: a selectable companion's scene standee (portrait aspect) or a homunculus's face
// (1:1), shaped by the modifier. A missing/broken source hides the image (the shared error handler) rather than
// showing a broken-image icon.
function buildActorDetailImage({ src, alt, shape }) {
  const figure = document.createElement('figure');
  figure.className = `actor-detail-image-frame actor-detail-image-frame--${shape}`;
  const img = document.createElement('img');
  img.className = 'actor-detail-image';
  img.alt = alt;
  hideImageOnError(img);
  img.style.visibility = '';
  setActorImageSource(img, src);
  figure.append(img);
  return figure;
}

// ── 手番 ─────────────────────────────────────────────────────────────────────────────────────────────────
function renderDungeonPlay(next) {
  const prev = currentDungeonView;
  currentDungeonView = next;
  // A fresh view invalidates any in-progress consumable targeting (its tile coords / armed item may no longer hold).
  teardownDungeonConsumableTargeting();
  foldDungeonEffects({ keepVeil: Boolean(prev) && prev.run_id === next.run_id && prev.floor !== next.floor });
  dn.result.hidden = true;
  dn.equipModal.hidden = true;
  dungeonRoot.dataset.scene = 'play';
  dungeonRoot.dataset.companion = next.companion ? 'present' : 'none';
  renderDungeonPartyAndDepth(next);
  renderDungeonSpells(next);
  renderDungeonCarry(next);
  renderDungeonTalkAvailability(next);
  if (!dungeonCompanionSpeaking()) clearDungeonVoice();
  const lines = newDungeonLogLines(prev?.run_id === next.run_id ? prev.log : null, next.log);
  if (!prev || prev.run_id !== next.run_id || prev.floor !== next.floor) appendDungeonFloorMark(next.floor);
  appendDungeonRecord(lines, next.action_error ? dungeonActionErrorText(next.action_error) : null);
  renderDungeonBoard(next);
  // 回避の魔法がかかっている間は、主人公の駒に静かな印が残る（view から描く状態で、演出の畳みでは消えない）。
  dungeonEntityNodes.get('player').classList.toggle('dn-entity--warded', next.evasion_spell.active);
  if (prev && prev.run_id === next.run_id) playDungeonTurn(readDungeonTurn(prev, next, lines), next);
  placeDungeonVoice();
  dungeonRoot.dataset.turn = String(next.turn);
  dungeonRoot.dataset.render = String(Number(dungeonRoot.dataset.render ?? 0) + 1);
}

function dungeonActionErrorText(code) {
  if (!Object.prototype.hasOwnProperty.call(DUNGEON_ACTION_ERROR_MESSAGES, code)) throw new Error(`unknown dungeon action_error code: ${JSON.stringify(code)}`);
  return DUNGEON_ACTION_ERROR_MESSAGES[code];
}

// 階段の上に立ち、下にまだ階があるとき（最下層の階段を降りると踏破で潜りが終わる）。
function dungeonDescentLeadsDown(view) {
  return view.player.x === view.stairs.x && view.player.y === view.stairs.y && view.floor < view.max_floors;
}

// 盤を暗くし、暗くなりきる移ろいの終わりで解ける Promise を返す（動きを減らす設定では移ろいが無く、すぐ解ける）。
function darkenDungeonForDescent() {
  dn.veil.classList.add('is-dark');
  return Promise.all(dn.veil.getAnimations().map((animation) => animation.finished));
}

// 要求が飛んでいる間に来た入力は捨てる。下の階へ降りる手は押した瞬間に盤を暗くし、応答と暗くなりきるのを両方待ってから
// 下の階を描く。要求が失敗したら、暗いまま止めずにいまの階へ明ける。
async function dungeonDo(action) {
  if (dungeonActionInFlight || !currentDungeonView) return;
  dungeonActionInFlight = true;
  const veiled = action.type === 'descend' && dungeonDescentLeadsDown(currentDungeonView) ? darkenDungeonForDescent() : null;
  try {
    const request = postJson('/api/dungeon/action', { action });
    const result = veiled ? (await Promise.all([request, veiled]))[0] : await request;
    if (result.ended) {
      // A run-ending turn (e.g. the fatal blow) still plays its strikes on the still-visible board, then the result.
      const lines = newDungeonLogLines(currentDungeonView.log, requiredDungeonField(result, 'log', 'dungeon result'));
      appendDungeonRecord(lines, null);
      foldDungeonEffects();
      if (requiredDungeonField(result, 'events', 'dungeon result').length) {
        playDungeonTurn(readDungeonEndedTurn(currentDungeonView, result.events, lines), currentDungeonView);
        await sleep(DUNGEON_ENDED_ANIM_MS);
      }
      await showDungeonResult(result);
    } else {
      renderDungeonPlay(result);
    }
  } catch (error) {
    if (veiled) dn.veil.classList.remove('is-dark');
    throw error;
  } finally {
    dungeonActionInFlight = false;
  }
}

// ── 盤の上の声: 同行者が話している間（返事が流れている間と、最初の一言が出ている間）は、盤の追従がその人を窓の内側に保ち、
// 最初の一言がその人の駒のそばから立ちのぼって消える。一言は敵・階段・主人公の升目を隠さない側に置く。 ─────────────────────
let dungeonVoice = null;
const DUNGEON_VOICE_LIFE_MS = 3200;

function dungeonFirstPhrase(content) {
  const match = content.match(/^[^。！？!?…]*[。！？!?…]*/);
  const phrase = (match?.[0] ?? content).trim() || content.trim();
  return [...phrase].length > 28 ? `${[...phrase].slice(0, 27).join('')}…` : phrase;
}

function clearDungeonVoice() {
  dungeonVoice?.node.remove();
  dungeonVoice = null;
  dungeonSpeakerFrame = { afar: null };
  syncDungeonSpeaking();
}

function dungeonCompanionSpeaking() {
  return Boolean(currentDungeonView?.companion && !currentDungeonView.companion.down && (dungeonVoice || dungeonTalkPending));
}

function syncDungeonSpeaking() {
  const speaking = dungeonCompanionSpeaking();
  if (speaking) dungeonRoot.dataset.speaking = 'companion';
  else delete dungeonRoot.dataset.speaking;
  return speaking;
}

function speakDungeonVoice(content) {
  clearDungeonVoice();
  if (!currentDungeonView?.companion || currentDungeonView.companion.down) return;
  const node = document.createElement('p');
  node.className = 'dn-voice';
  const face = document.createElement('img');
  face.className = 'dn-voice-face';
  face.alt = '';
  face.src = dungeonCompanionFaceUrl(currentDungeonView.companion);
  const text = document.createElement('span');
  text.className = 'dn-voice-text';
  text.textContent = dungeonFirstPhrase(content);
  node.append(face, text);
  dn.voices.append(node);
  dungeonVoice = { node };
  frameDungeonSpeaker();
  node.animate(dungeonReducedMotion()
    ? [{ opacity: 1 }, { opacity: 1, offset: 0.85 }, { opacity: 0 }]
    : [{ opacity: 0, translate: '0 6px' }, { opacity: 1, translate: '0 0', offset: 0.1 }, { opacity: 1, translate: '0 -4px', offset: 0.8 }, { opacity: 0, translate: '0 -12px' }],
  { duration: DUNGEON_VOICE_LIFE_MS, easing: 'ease-out' }).onfinish = () => {
    if (dungeonVoice?.node === node) clearDungeonVoice();
    else node.remove();
  };
}

// 話している間の盤の置き方。駒の箱（目盛りを含む）と一言の箱を盤の px で取り、窓の縁から余白を空けて収める。盤はいまの位置から
// 収まる範囲までのいちばん小さな動きで置く（収まっていれば動かさない）:
// 1. 同行者と一言・主人公・見えている敵（主人公の先の危険）がそろって収まるなら、その組を収める。一言の分だけ収まらないなら、
//    駒の組を収め、一言は駒の横か下の空いた側に出す。
// 2. 同行者の駒も収まらない向きでは、主人公と先の危険を先に取って窓に収め、同行者はその向きで窓の外へ出す（縁で切れない所まで押し出す）。
//    そのとき一言は、同行者のいる向きの窓の縁から余白を空けた内側に、同行者の小さな顔を添えて出し、尾は同行者のいる向きを指す。
// 向き（横・縦）ごとに独立に決める。返す afar は、同行者が窓の外に出た向き（null なら窓の中）。
const DUNGEON_VOICE_EST = { w: 230, h: 34 };
const DUNGEON_VOICE_TAIL = 12;
let dungeonSpeakerFrame = { afar: null };

// 駒の箱は升目そのもの（顔と下の目盛りは升目の中に収まる）。
function dungeonTokenBox(at, { cell, step }) {
  return { left: at.x * step, right: at.x * step + cell, top: at.y * step, bottom: at.y * step + cell };
}

function holdDungeonSpeaker(next, { cell, step, viewW, viewH }) {
  const view = currentDungeonView;
  const margin = Math.max(24, cell * 0.5);
  const voiceH = dungeonVoice ? dungeonVoice.node.offsetHeight : DUNGEON_VOICE_EST.h;
  const voiceW = dungeonVoice ? dungeonVoice.node.offsetWidth : DUNGEON_VOICE_EST.w;
  const danger = [dungeonTokenBox(view.player, { cell, step }), ...view.enemies.map((enemy) => dungeonTokenBox(enemy, { cell, step }))];
  const token = dungeonTokenBox(view.companion, { cell, step });
  const centre = (token.left + token.right) / 2;
  const speaker = { left: Math.min(token.left, centre - voiceW / 2), right: Math.max(token.right, centre + voiceW / 2), top: token.top - voiceH - DUNGEON_VOICE_TAIL, bottom: token.bottom };
  const range = (boxes, lowKey, highKey, size) => {
    const lo = Math.max(...boxes.map((box) => box[highKey])) + margin - size;
    const hi = Math.min(...boxes.map((box) => box[lowKey])) - margin;
    return lo <= hi ? { lo, hi } : null;
  };
  const within = ({ lo, hi }, from) => Math.max(lo, Math.min(hi, from));
  const axis = (lowKey, highKey, size, from) => {
    const all = range([...danger, speaker], lowKey, highKey, size);
    if (all) return { at: within(all, from), afar: null };
    const withToken = range([...danger, token], lowKey, highKey, size);
    if (withToken) return { at: within(withToken, from), afar: null };
    const kept = range(danger, lowKey, highKey, size) ?? range(danger.slice(0, 1), lowKey, highKey, size);
    if (!kept) return { at: from, afar: null };
    // 危険の組を収め、同行者の駒が縁にかかるなら窓の外へ出し切る位置まで押す（危険の組は窓に残る範囲で）。
    const beyondHigh = token[lowKey] > (danger[0][lowKey] + danger[0][highKey]) / 2;
    const outAt = beyondHigh ? token[lowKey] - size - 1 : token[highKey] + 1;
    let at = within(kept, from);
    const touches = beyondHigh ? at + size > token[lowKey] : at < token[highKey];
    if (touches) at = Math.max(kept.lo, Math.min(kept.hi, outAt));
    return { at, afar: beyondHigh ? 'high' : 'low' };
  };
  const x = axis('left', 'right', viewW, next.x);
  const y = axis('top', 'bottom', viewH, next.y);
  dungeonSpeakerFrame = { afar: y.afar === 'high' ? 'down' : y.afar === 'low' ? 'up' : x.afar === 'high' ? 'right' : x.afar === 'low' ? 'left' : null };
  return { x: x.at, y: y.at };
}

// 話し始めた（返事を待つ間を含む）ときに盤を動かす。動きは歩く追従より少しゆっくり。
function frameDungeonSpeaker() {
  if (!syncDungeonSpeaking() || dungeonRoot.dataset.scene !== 'play') return;
  const { cell, step } = dungeonCellMetrics();
  const viewW = dn.viewport.clientWidth;
  const viewH = dn.viewport.clientHeight;
  if (!Number.isFinite(cell) || viewW === 0) return;
  const next = holdDungeonSpeaker(dungeonCamera, { cell, step, viewW, viewH });
  if (next.x !== dungeonCamera.x || next.y !== dungeonCamera.y) {
    dungeonCamera = next;
    dn.board.style.transition = dungeonReducedMotion() ? 'none' : 'transform 0.42s ease-in-out';
    dn.board.style.transform = `translate(${-next.x}px, ${-next.y}px)`;
  }
  placeDungeonVoice();
}

function dungeonVoiceBlockedCells(view) {
  const cells = new Set(view.enemies.map((enemy) => `${enemy.x},${enemy.y}`));
  cells.add(`${view.stairs.x},${view.stairs.y}`);
  cells.add(`${view.player.x},${view.player.y}`);
  return cells;
}

function placeDungeonVoice() {
  const view = currentDungeonView;
  if (!dungeonVoice || !view?.companion) return;
  const { node } = dungeonVoice;
  const { cell, step } = dungeonCellMetrics();
  if (!Number.isFinite(cell)) return;
  const token = dungeonEntityNodes.get('companion')?.firstChild;
  if (!token) return;
  const viewW = dn.viewport.clientWidth;
  const viewH = dn.viewport.clientHeight;
  node.classList.toggle('is-afar', dungeonSpeakerFrame.afar !== null);
  const w = node.offsetWidth;
  const h = node.offsetHeight;
  const edge = Math.max(24, cell * 0.5);
  if (dungeonSpeakerFrame.afar !== null) {
    // 同行者が窓の外: 一言はその向きの縁から余白を空けた内側に、同行者の駒の位置へ寄せて置く（尾が同行者の向きを指す）。
    const at = dungeonTokenBox(view.companion, { cell, step });
    const cx = (at.left + at.right) / 2 - dungeonCamera.x;
    const cy = (at.top + at.bottom) / 2 - dungeonCamera.y;
    const clampX = (value) => Math.max(edge, Math.min(viewW - edge - w, value));
    const clampY = (value) => Math.max(edge, Math.min(viewH - edge - h, value));
    const box = dungeonSpeakerFrame.afar === 'down' ? { left: clampX(cx - w / 2), top: viewH - edge - h }
      : dungeonSpeakerFrame.afar === 'up' ? { left: clampX(cx - w / 2), top: edge }
        : dungeonSpeakerFrame.afar === 'right' ? { left: viewW - edge - w, top: clampY(cy - h / 2) }
          : { left: edge, top: clampY(cy - h / 2) };
    node.style.left = `${box.left + dungeonCamera.x}px`;
    node.style.top = `${box.top + dungeonCamera.y}px`;
    node.dataset.side = `toward-${dungeonSpeakerFrame.afar}`;
    return;
  }
  const tokenRect = dungeonLocalRect(token);
  const boardRect = dungeonLocalRect(dn.board);
  const at = { x: tokenRect.left + tokenRect.width / 2 - boardRect.left, y: tokenRect.top + tokenRect.height / 2 - boardRect.top };
  const blocked = dungeonVoiceBlockedCells(view);
  // 候補: 上・右・左・下。一言が覆う升目に敵・階段・主人公がいない最初の向きを選び、どれも塞がるなら上に置く。
  // 一言の尾が駒の縁に届くよう、升目ではなく駒そのものの縁から 8px 離して置く。下に置くときは目盛りの下から離す。
  const half = tokenRect.width / 2;
  const candidates = [
    { side: 'above', left: at.x - w / 2, top: at.y - half - h - 8 },
    { side: 'right', left: at.x + half + 8, top: at.y - h / 2 },
    { side: 'left', left: at.x - half - w - 8, top: at.y - h / 2 },
    { side: 'below', left: at.x - w / 2, top: at.y + half + 24 }
  ];
  const covers = (box) => {
    const x0 = Math.floor(box.left / step);
    const x1 = Math.floor((box.left + w) / step);
    const y0 = Math.floor(box.top / step);
    const y1 = Math.floor((box.top + h) / step);
    for (let y = y0; y <= y1; y += 1) for (let x = x0; x <= x1; x += 1) if (blocked.has(`${x},${y}`)) return true;
    return false;
  };
  const inside = (box) => box.left - dungeonCamera.x >= edge && box.left + w - dungeonCamera.x <= viewW - edge && box.top - dungeonCamera.y >= edge && box.top + h - dungeonCamera.y <= viewH - edge;
  const chosen = candidates.find((box) => !covers(box) && inside(box)) ?? candidates.find((box) => inside(box)) ?? candidates[0];
  node.style.left = `${chosen.left}px`;
  node.style.top = `${chosen.top}px`;
  node.dataset.side = chosen.side;
}

// ── ヘルプ・撤退・詳細・装備の窓 ─────────────────────────────────────────────────────────────────────────
for (const modal of DUNGEON_MODALS) {
  modal.addEventListener('click', (event) => { if (event.target === modal || event.target.closest('[data-close]')) modal.hidden = true; });
}

function openDungeonHelp() {
  const keys = document.createElement('dl');
  keys.className = 'dn-help-keys';
  for (const [key, meaning] of DUNGEON_HELP_KEYS) {
    const dt = document.createElement('dt');
    dt.textContent = key;
    const dd = document.createElement('dd');
    dd.textContent = meaning;
    keys.append(dt, dd);
  }
  dn.helpBody.replaceChildren(keys);
  dn.helpModal.hidden = false;
}

// The retreat confirm: the confirm is disabled off the entrance/stairs (can_retreat 契約 unchanged), and the one line
// said there is what the player is told on the spot.
function openDungeonRetreatConfirm() {
  dn.retreatMessage.textContent = currentDungeonView?.can_retreat
    ? '撤退して、道中で得た経験を能力として持ち帰りますか？'
    : 'ここでは撤退できません。各階の入口か階段の上まで戻ってください。';
  dn.retreatYes.disabled = !currentDungeonView?.can_retreat;
  dn.retreatModal.hidden = false;
}

dn.help.addEventListener('click', () => { dn.help.blur(); openDungeonHelp(); });
dn.retreat.addEventListener('click', () => { dn.retreat.blur(); openDungeonRetreatConfirm(); });
dn.retreatYes.addEventListener('click', () => {
  if (!currentDungeonView?.can_retreat) return;
  dn.retreatModal.hidden = true;
  dungeonDo({ type: 'retreat' }).catch(reportError);
});

// The run equipment of the hero or the companion: null is nothing equipped (both slots empty); anything else is the
// validated two-slot shape (a malformed slot throws).
function dungeonEquipmentList(runEquipment) {
  if (runEquipment === undefined) throw new Error('dungeon detail equipment is required (null when nothing is equipped)');
  const slots = runEquipment === null ? { weapon: null, amulet: null } : validateDungeonEquipmentSlots(runEquipment.slots, 'dungeon detail equipment');
  const list = document.createElement('dl');
  list.className = 'dn-detail-list';
  for (const slot of WORKSHOP_EQUIPMENT_KINDS) {
    const dt = document.createElement('dt');
    dt.textContent = workshopKindLabel(slot);
    const dd = document.createElement('dd');
    dd.textContent = slots[slot] ? slots[slot].instance.name : '未装備';
    list.append(dt, dd);
  }
  return list;
}

function dungeonDetailSection(title, ...nodes) {
  const wrap = document.createElement('section');
  wrap.className = 'dn-detail-section';
  const h = document.createElement('h3');
  h.textContent = title;
  wrap.append(h, ...nodes);
  return wrap;
}

function openDungeonHeroDetail() {
  const view = currentDungeonView;
  if (!view) return;
  const preview = requiredDungeonField(view, 'pending_gains_preview', 'dungeon view');
  const gains = [
    ...Object.entries(preview.magic).map(([key, value]) => `${DUNGEON_MAGIC_LABELS[key] ?? key}+${value}`),
    ...Object.entries(preview.abilities).map(([key, value]) => `${DUNGEON_ABILITY_LABELS[key] ?? key}+${value}`)
  ];
  if (!Array.isArray(view.equipment_buffer)) throw new Error('dungeon view is missing equipment_buffer');
  const gainText = document.createElement('p');
  gainText.textContent = gains.length ? gains.join('、') : 'まだ持ち帰る能力上昇はありません。';
  const gearText = document.createElement('p');
  gearText.textContent = view.equipment_buffer.length ? view.equipment_buffer.map((item) => requiredDungeonItemName(item, 'dungeon equipment_buffer item')).join('、') : 'まだ手に入れた装備はありません。';
  dn.detailTitle.textContent = DUNGEON_PLAYER_NAME;
  dn.detailBody.replaceChildren(dungeonDetailSection('装備', dungeonEquipmentList(view.equipment)), dungeonDetailSection('上昇能力', gainText), dungeonDetailSection('獲得予定装備', gearText));
  dn.detailModal.hidden = false;
}

function openDungeonCompanionDetail(companion) {
  const face = document.createElement('img');
  face.className = 'dn-detail-face';
  face.alt = `${companion.name}の顔`;
  face.src = dungeonCompanionFaceUrl(companion);
  dn.detailTitle.textContent = companion.name;
  dn.detailBody.replaceChildren(face, dungeonDetailSection('装備', dungeonEquipmentList(companion.equipment)));
  dn.detailModal.hidden = false;
}

// ── 盤のキー: 方向キーで移動・スペースで待機・エンターで降りる。開いた窓・照準中・入力欄や札や記録に focus があるときは盤に渡さない ──
const DUNGEON_ARROW_DIRS = { ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right' };
window.addEventListener('keydown', (event) => {
  if (!screens['academy-dungeon'].classList.contains('active')) return;
  if (dungeonRoot.dataset.scene !== 'play' || !currentDungeonView) return;
  if (isDungeonModalOpen()) return;
  // While a consumable is being targeted (an aim tile or an ally pick), the board is a target picker, not a movement
  // surface: Escape cancels, and no key drives a move / 待機 / 階段.
  if (dungeonConsumableTargeting) {
    if (event.key === 'Escape') { event.preventDefault(); cancelDungeonConsumableTargeting(); }
    return;
  }
  // Never steal keys from a focused control (the talk input, a card, a button) or from the focused journal.
  const active = document.activeElement;
  if (active && (active === dn.journal || ['INPUT', 'TEXTAREA', 'SELECT', 'BUTTON'].includes(active.tagName))) return;
  // The Enter that sends a talk line disables the input mid-dispatch, so focus may already be on the body here; it is
  // still the input's key, not a board key.
  if (event.target === dn.talkInput) return;
  const direction = DUNGEON_ARROW_DIRS[event.key];
  if (direction) {
    event.preventDefault();
    dungeonBoardKeyPressedSinceTalk = true;
    dungeonDo({ type: 'move', direction }).catch(reportError);
    return;
  }
  if (event.key === ' ' || event.code === 'Space') {
    event.preventDefault();
    dungeonBoardKeyPressedSinceTalk = true;
    dungeonDo({ type: 'wait' }).catch(reportError);
    return;
  }
  if (event.key === 'Enter') {
    // Descend; off the stairs the engine returns a clear "stairs only" message in the journal.
    event.preventDefault();
    dungeonBoardKeyPressedSinceTalk = true;
    dungeonDo({ type: 'descend' }).catch(reportError);
  }
});

// ── 潜る: 入場は入る前の画面と同じ場所の絵（destinationArt・置き方は画面の宣言）を地にした待ち（raisePlaceVeil）の下で流れ、
// 盤は入場の盤が届いて同行者の第一声が流れ始めた瞬間（ひとりなら待ちの最短のあと）に出て、待ちは薄れて終わる ─────────────────
async function enterDungeon() {
  if (dungeonActionInFlight) return;
  if (dungeonFinalizationInFlight) {
    // A prior run's finalize is still landing; the run is held server-side, so block re-entry.
    showProcessingToast();
    return;
  }
  dungeonActionInFlight = true;
  dungeonChatMessages = [];
  let bufferedView = null;
  let boardShown = false;
  const showPlay = () => {
    if (boardShown || !bufferedView) return;
    boardShown = true;
    // End the wait: show the dungeon screen again (without its auto state-refetch, since the board is already held) and
    // reveal the buffered board as the wait fades.
    showScreen('academy-dungeon', { skipDungeonRefresh: true });
    renderDungeonPlay(bufferedView);
    frameDungeonSpeaker();
  };
  try {
    raisePlaceVeil({ art: destinationArt('dungeon'), dim: true, until: 'academy-dungeon', ending: 'fade' });
    const minimumDisplay = sleep(ACADEMY_LOADING_MINIMUM_MS);
    beginDungeonTalk();
    // Enter streams: the board arrives on a dungeon_enter event, then the companion opening streams token by token
    // into the journal. The first token ends the wait and reveals the board.
    await runAssistantSseStream({
      surface: dungeonChatSurface,
      endpoint: '/api/dungeon/enter',
      body: { with_companion: dungeonWithCompanion },
      statusPrefix: 'dungeon-enter',
      finalAssistantMode: 'first',
      refreshAfter: false,
      onEvent: (event, data) => { if (event === 'dungeon_enter') bufferedView = data.view; },
      onAssistantStreamStart: () => showPlay()
    });
    // Solo / no-companion enter has no opening token: hold the wait its usual minimum, then reveal the board.
    await minimumDisplay;
    showPlay();
  } catch (error) {
    // Enter / opening failure sinks the wait into the night, then goes to the mode's landing (routing: the prep screen,
    // whose refresh resumes a held run or renders the entry to retry or go back; loop: the room) and surfaces the
    // error — never a silent drop into a solo run under the wait.
    if (placeVeilWaiting()) await stopPlaceVeil();
    dungeonTalkPending = false;
    dungeonEnterFailed = true;
    showScreen(dungeonEntryOrigin().enterFailedScreen);
    reportError(error);
  } finally {
    dungeonActionInFlight = false;
  }
}

dn.dive.addEventListener('click', () => enterDungeon().catch(reportError));
document.querySelector('#academy-training-open-dungeon').addEventListener('click', () => showScreen('academy-dungeon'));
dn.entryBack.addEventListener('click', () => dungeonEntryOrigin().back().catch(reportError));

// ── 終わり: 持ち帰って終わる潜り（踏破・撤退）は灯りが戻る中に持ち帰るものが並び、力尽きた潜りは灯りが落ちた中に失ったものが薄く
// 並ぶ。並びが出揃ってから「戻る」が出て、押すとこの画面の戻り先（loop は自室・routing は案内人）へ進む ────────────────────
function dungeonResultLine(text, className = '') {
  const p = document.createElement('p');
  p.className = `dn-result-line ${className}`.trim();
  p.textContent = text;
  return p;
}

function dungeonResultLines(result) {
  const lines = [];
  const kept = result.status !== 'dead';
  const applied = requiredDungeonField(result, 'applied_gains', 'dungeon result');
  const parts = [
    ...Object.entries(applied.magic).map(([key, value]) => `${DUNGEON_MAGIC_LABELS[key] ?? key}+${value}`),
    ...Object.entries(applied.abilities).map(([key, value]) => `${DUNGEON_ABILITY_LABELS[key] ?? key}+${value}`)
  ];
  lines.push(dungeonResultLine(kept ? (parts.length ? `能力上昇: ${parts.join('、')}` : '今回は能力上昇はありませんでした。') : '道中の経験は失われました。', 'is-gain'));
  const materials = result.materials;
  if (!materials || typeof materials.retained !== 'boolean' || !Array.isArray(materials.items)) throw new Error('dungeon result requires a materials manifest');
  if (materials.items.length) {
    lines.push(dungeonResultLine(materials.retained ? '持ち帰った素材' : '失った素材', 'is-head'));
    for (const item of materials.items) {
      requiredDungeonItemName(item, 'dungeon result material', 'display_name');
      requiredDungeonItemCount(item, 'dungeon result material', 'quantity');
      const row = dungeonResultLine(`${item.display_name} ×${item.quantity}`, 'is-item');
      const icon = document.createElement('img');
      icon.alt = '';
      icon.src = `${DUNGEON_ASSET_BASE}/material-icons/${item.item_id}.png`;
      row.prepend(icon);
      lines.push(row);
    }
  }
  const equipment = result.equipment;
  if (!equipment || typeof equipment.retained !== 'boolean' || !Array.isArray(equipment.items)) throw new Error('dungeon result requires an equipment manifest');
  if (equipment.items.length) {
    lines.push(dungeonResultLine(equipment.retained ? '手に入れた装備' : '失った装備', 'is-head'));
    for (const item of equipment.items) lines.push(dungeonResultLine(requiredDungeonItemName(item, 'dungeon result equipment'), 'is-item'));
  }
  return lines;
}

// 持ち帰って終わる潜りの盤: 一度見た所の全体が窓に収まるまで引き、歩いた所の地図として見せる（盤の追従は終わっている）。
function fitDungeonExploredBoard(view) {
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (let y = 0; y < view.height; y += 1) {
    for (let x = 0; x < view.width; x += 1) {
      if (!view.explored[y][x]) continue;
      minX = Math.min(minX, x);
      maxX = Math.max(maxX, x);
      minY = Math.min(minY, y);
      maxY = Math.max(maxY, y);
    }
  }
  if (minX === Infinity) throw new Error('dungeon result: the last board has no explored cell');
  const { cell, step } = dungeonCellMetrics();
  const viewW = dn.viewport.clientWidth;
  const viewH = dn.viewport.clientHeight;
  const boxW = (maxX - minX) * step + cell;
  const boxH = (maxY - minY) * step + cell;
  const scale = Math.min(1, (viewW - step) / boxW, (viewH - step) / boxH);
  const tx = viewW / 2 - scale * (minX * step + boxW / 2);
  const ty = viewH / 2 - scale * (minY * step + boxH / 2);
  dn.board.style.transition = '';
  dn.board.style.transformOrigin = '0 0';
  dn.board.style.transform = `translate(${tx}px, ${ty}px) scale(${scale})`;
}

// The result the way back reads (its transition carries the mode-resolved next screen).
let dungeonEndedResult = null;

async function showDungeonResult(result) {
  if (!(result.status in DUNGEON_RESULT_HEADINGS)) throw new Error(`unknown dungeon result status: ${result.status}`);
  const kept = result.status !== 'dead';
  teardownDungeonConsumableTargeting();
  for (const modal of DUNGEON_MODALS) modal.hidden = true;
  clearDungeonVoice();
  if (kept && currentDungeonView) fitDungeonExploredBoard(currentDungeonView);
  currentDungeonView = null;
  dungeonChatMessages = [];
  dungeonEndedResult = result;
  dungeonRoot.dataset.scene = 'result';
  dungeonRoot.dataset.outcome = kept ? 'kept' : 'lost';
  dn.resultTitle.textContent = DUNGEON_RESULT_HEADINGS[result.status];
  dn.resultTitle.dataset.status = result.status;
  dn.resultReach.textContent = `到達 ${result.floor_reached} / ${result.max_floors} 階`;
  const lines = dungeonResultLines(result);
  dn.resultLines.replaceChildren(...lines);
  dn.resultBack.hidden = true;
  dn.result.hidden = false;
  // For a synchronous (solo) end the banked parameters arrive here; a deferred companion end banks in the background
  // (started now, the same moment the result shows), so it carries no world yet.
  if (result.world?.player_parameters) {
    currentWorld = { ...(currentWorld ?? {}), player_parameters: result.world.player_parameters };
    renderTrainingPlayerParameters(result.world.player_parameters);
    renderPlayerParametersEditor(result.world.player_parameters);
  }
  if (currentRuntimeState) currentRuntimeState = result.state ?? currentRuntimeState;
  if (result.pending_finalize) startDungeonBackgroundFinalize();
  const reduce = dungeonReducedMotion();
  const entrances = lines.map((line, index) => line.animate([{ opacity: 0, translate: '0 6px' }, { opacity: kept ? 1 : 0.5, translate: '0 0' }], { duration: reduce ? 1 : 420, delay: reduce ? 0 : 1000 + index * 140, easing: 'ease-out', fill: 'both' }).finished);
  // 「戻る」は並びが出揃ってから、並びの最後に出す。
  await Promise.all(entrances);
  dn.resultBack.hidden = false;
}

// The way back: the action-ended result carries the mode-resolved next screen (loop -> academy-room, routing ->
// interaction). A run resumed from a held-finalize state (the held view's held_result) has no transition — the dungeon
// state view does not expose it — so the global play mode resolves the return screen for that recovery case, mirroring
// the backend's post-dungeon screen.
async function dungeonExitToRoom(result) {
  let nextScreen = result.transition?.next_screen ?? null;
  if (nextScreen == null) {
    if (currentPlayMode !== 'loop' && currentPlayMode !== 'routing') {
      throw new Error(`dungeon resume: unknown play mode ${JSON.stringify(currentPlayMode)}`);
    }
    nextScreen = currentPlayMode === 'routing' ? 'interaction' : 'academy-room';
  }
  // Loop returns to academy-room and never enters the hub, so it keeps the un-awaited background finalize (its room is
  // reached without waiting on the LLM).
  if (nextScreen !== 'interaction') {
    await navigateToPostContentScreen(nextScreen, { loadingCopy: DUNGEON_EXIT_LOADING_COPY });
    return;
  }
  // The routing dungeon return waits over the result screen itself: the ground stays the board the run ended on, and
  // the hub fades in over it. Drain-on-exit: the companion dungeon finalize (POST /api/dungeon/finalize) is the
  // dungeon's post-processing; drain it to completion under the wait BEFORE opening the hub, so the companion finalize
  // and the hub opening never race on the LM pipeline.
  raisePlaceVeil({ art: null, dim: true, until: 'routing-hub', ending: 'fade' });
  try {
    if (activeDungeonFinalizationPromise) {
      await awaitUnderPlaceVeil(activeDungeonFinalizationPromise);
    }
    await navigateToPostContentScreen(nextScreen);
  } catch (error) {
    // A failed hub start has no landing of its own here: the wait sinks into the night and leaves the result screen.
    if (placeVeilWaiting()) await stopPlaceVeil();
    throw error;
  }
}

dn.resultBack.addEventListener('click', () => {
  dn.resultBack.blur();
  if (!dungeonEndedResult) throw new Error('dungeon: the way back needs the ended result');
  dn.resultBack.hidden = true;
  dungeonExitToRoom(dungeonEndedResult).catch(reportError);
});

// Runs the deferred companion finalize -> bank -> clear in the background. The server holds the
// LLM busy gate for the request's duration, so re-entering the dungeon meanwhile sees llm_busy.
// A failure surfaces (reportError) and leaves the run held server-side for a later retry.
function startDungeonBackgroundFinalize() {
  if (dungeonFinalizationInFlight) return;
  dungeonFinalizationInFlight = true;
  const finalization = (async () => {
    try {
      const result = await postJson('/api/dungeon/finalize', {});
      if (result.world?.player_parameters) {
        currentWorld = { ...(currentWorld ?? {}), player_parameters: result.world.player_parameters };
      }
      currentRuntimeState = result.state ?? currentRuntimeState;
      await refresh();
      if (screens['academy-room']?.classList.contains('active')) renderAcademyRoomScreen();
    } catch (error) {
      reportError(error);
    } finally {
      dungeonFinalizationInFlight = false;
      if (activeDungeonFinalizationPromise === finalization) activeDungeonFinalizationPromise = null;
    }
  })();
  activeDungeonFinalizationPromise = finalization;
}

renderMessageStream();
updateViewportMetrics();
window.addEventListener('resize', updateViewportMetrics);
if ('ResizeObserver' in window) {
  new ResizeObserver(updateViewportMetrics).observe(document.querySelector('.topbar'));
}
// ===== 闘技会 (arena) screen =====
// A routing destination screen: the participate-form selection, the weekly 16-slot single-elimination bracket,
// the player's interactive matches (the dungeon combat grammar over a fixed all-visible board), and spectator
// replays. It stands on the venue (会場で分け合う作り): the arena's art fills the screen, the way of its stages
// (選ぶ・勝ち上がりの表・試合・結果) runs across the top, and each stage's face changes over it; the match board keeps the
// dungeon's play grammar under the screen-scoped --arena-* token layer. The board renderer and combat animation are
// arena-scoped (the dungeon's board code is not shared); the combat effects (弾・着弾・身を引く動き・浮く数・縁の赤・外れ・空振り・
// 回復・蘇生) and the gauge motion are the dungeon's own painters and values (COMBAT_FX / playCombatEvents / setCombatGauge) over an arena
// stage, and the consumable effect summary (dungeonConsumableSummaryText) is a shared pure helper reused directly.

let currentArenaState = null;       // last validated GET /api/arena/state (selection or tournament view)
let currentArenaMatchView = null;   // the match engine view currently rendered (interactive or a replay frame)
let arenaActionInFlight = false;    // single-flight guard for enter / start / action / replay fetches
let arenaConsumableTargeting = null;
const arenaEntityNodes = new Map();
const arenaEntityTiles = new Map();
let arenaBoardSignature = null;
let arenaSunk = new Set();          // actor ids whose token is drawn fallen (grey and sunk) on the board
let arenaTurnActorId = null;        // the fighter under the turn ring (and the lit HUD name), or null
let arenaFlow = null;               // { settle } — the board flow in progress (入り・一手の流れ・決着); folding settles it to its end
let arenaHud = null;                // { signature, round, cards } — the HUD built once per match line-up
let arenaDockMatchId = null;        // the match whose spells / items the dock last drew (a read-only frame keeps them)
const arenaFx = createCombatFx();
// The board scale is FROZEN per window size: --an-cell is computed once (from the match surface's fullest,
// dock+items-present layout) and reused until the window itself resizes. The match surface hides the item /
// dock / prompt / replay regions as the state changes (e.g. a replay shows no dock+items), which
// resizes the inner stage; without this lock the ResizeObserver would rezoom the board on that content toggle
// and warp an in-flight combat trajectory (the player-reported symptom). Keyed on window size so only a real
// window resize (mirrors the dungeon's window-only recompute) re-fits the board.
let arenaCellLock = null;           // frozen --an-cell (px) for the current window size, or null before first fit
let arenaCellLockWindow = null;     // { w, h } window inner size the frozen cell was computed for
let arenaReplay = null;             // { matchId, winnerUnitId, turns, index, timer, seenEnd, heroActorIds, mirrored } while a spectator replay is playing
let arenaReplaySpeed = 'low';       // session-held replay pacing (low = default interval, mid = 1/2, high = 1/4).
                                    // NOT persisted / never reset — it carries across replays for the whole page session.
// LLM flavor (試合前口上 / 優勝・敗退実況一文) UI state. Both surfaces are independent of the combat / reward flow:
// they fetch on their own (never touching arenaActionInFlight, so combat input is never blocked) and a generation
// failure shows an explicit error in its own slot while every non-flavor arena flow keeps working.
let arenaIntroMatchId = null;       // the match the intro banner currently reflects (single-flight token)
let arenaResultFlavorState = { text: null, pending: false, failed: false }; // the concluded tournament's 実況一文
const ARENA_REPLAY_STEP_MS = 1100;  // auto-advance interval between replay turns (低速 = the unmodified baseline)
// 3-step spectator speed: 低速 = the baseline interval, 中速 = half it, 高速 = a quarter of it (client pacing only).
const ARENA_REPLAY_SPEED_DIVISORS = { low: 1, mid: 2, high: 4 };
const ARENA_REPLAY_SPEED_LABELS = { low: '低速', mid: '中速', high: '高速' };
// 入り（ms）: 相手の側→自陣の側の順に、足もとの輪が開き（ring）、その輪から駒が立つ（rise）。settle で輪がほどけ、会場が試合の濃さへ
// 明け、口上と呪文の欄が出る。
const ARENA_ENTRANCE_MS = Object.freeze({ firstRing: 120, ring: 260, rise: 260, settle: 1000 });
// 番の受け渡し（ms）: 一つの応答の出来事（打ち合い・回復・蘇生）を手の主ごとの区切りで流す。輪は縮んで消えてから次の手の主の足もとに
// 開き（各 handoff）、その手の出来事は区切りの始まりから strike（輪が移らない区切りは firstStrike）で流れ出す。区切りの長さは、輪が
// 移らない区切り first・輪が移る区切り slot・出来事の無い区切り（動いただけ）quiet。番が主人公へ戻ると呪文の欄の光の筋が一度走る（streak）。
const ARENA_TURN_MS = Object.freeze({ handoff: 160, firstStrike: 100, strike: 220, first: 600, slot: 400, quiet: 400, streak: 520 });
// 決着（ms・決める一撃が着いた時から）: 倒れた学院生が沈み（sinkAfter）、会場の灯と勝った側の足もとの輪（light）、印（mark）。
// 主人公の試合は hold で盤が薄れ（fade）、表へ移る。決める一撃の着弾は ARENA_DECISIVE_IMPACT_SCALE 倍に大きく、盤は flash の間白む。
const ARENA_DECISIVE_MS = Object.freeze({ sinkAfter: 200, light: 600, mark: 900, hold: 2300, fade: 300, flash: 260 });
const ARENA_DECISIVE_IMPACT_SCALE = 1.5;
const ARENA_MARK_LABELS = Object.freeze({ advance: '勝ち上がり', champion: '優勝', eliminated: '敗退' });
// 表の明かし（勝って戻った回戦）と見届け（敗退の後の残りの回戦）の時割り（ms）。一組の明かしは step の長さで、節が灯り、勝者の
// 線が節から次の節へ伸びる。主人公の組（と決勝）は lead の長さで先に明かし、残りは stagger ずつずらす。
const ARENA_REVEAL_PACES = {
  advance: { step: 400, stagger: 200, roundGap: 0 },
  watch: { step: 300, stagger: 120, roundGap: 180 }
};
const ARENA_REVEAL_LEAD_MS = 400;
let arenaReveal = null;             // { timers, foldOnClick } while the bracket is revealing a round (a click folds it)
// 観戦の明かし: 入場した観戦の大会で、バディーの試合を見返し終えた（見ずに先へで進めた）回戦の数。画面だけが持ち、読み直すと
// null に戻って結果の段で出る（サーバは入場で大会を全部解いている）。
let arenaSpectate = null;           // { revealed } while a freshly entered 観戦 is being walked through
// 観戦の入り（バディーの名が灯り、バディーの組の目が金の輪で開く）の時割り（ms）。押せば落ち着いた姿まで畳む。
const ARENA_SPECTATE_ENTRANCE_MS = { heroName: 300, eye: 700, settle: 1000 };

// 段の道（選ぶ・勝ち上がりの表・試合・結果）。いまの段は見えている面とトーナメントの終わりで決まる（arenaWayStage）。
const ARENA_WAY = ['選ぶ', '勝ち上がりの表', '試合', '結果'];
const arenaScreen = document.querySelector('#academy-arena-screen');
dressVenueGround(arenaScreen, 'arena');
dressVenueSigilButton(document.querySelector('#arena-retry'), 'retry', VENUE_RETRY_LABEL);
let arenaWayFailed = false;

function arenaWayStage() {
  if (!document.querySelector('#arena-match').hidden) return 2;
  if (!document.querySelector('#arena-bracket').hidden) return arenaShowsResult(currentArenaState) && !arenaReveal ? 3 : 1;
  return 0;
}

// 段の道と出る紋を、いまの面に合わせる。出る紋は結果の段（トーナメントの終わり）だけ。
function renderArenaWay() {
  const stage = arenaWayStage();
  arenaScreen.dataset.stage = ['selection', 'bracket', 'match', 'result'][stage];
  renderVenuePath(document.querySelector('#arena-path'), { names: ARENA_WAY, current: stage, failed: arenaWayFailed });
  document.querySelector('#arena-exit').hidden = stage !== 3;
}

// 闘技会の失敗（400/404/409 の already_entered・no_buddy・concluded など）: いまの段の星の先で道が途切れ、言い直しの紋が立つ。
// 言い直しは闘技会を読み直す（GET /api/arena/state）。原因は console にだけ残す。闘技会は LM を使わないので設定の画面への誘いは無い。
function reportArenaScreenError(error) {
  console.error(error);
  arenaWayFailed = true;
  renderArenaWay();
  setVenueRetry(document.querySelector('#arena-retry'), () => {
    arenaWayFailed = false;
    renderArenaWay();
    refreshArenaScreen().catch(reportArenaScreenError);
  });
}

function clearArenaWayFailure() {
  arenaWayFailed = false;
  setVenueRetry(document.querySelector('#arena-retry'), null);
}

// Drop the frozen board scale so the next match re-fits under its own first (interactive) layout. Called when
// leaving the match surface and on screen (re)open, never on a per-action re-render — so a match keeps its scale
// from start through 決着, but a later match (or a resume after a spectate that froze a larger cell) starts clean.
function resetArenaBoardScale() {
  arenaCellLock = null;
  arenaCellLockWindow = null;
}

function showArenaSurface(name) {
  stopArenaReveal();
  // Leaving the match surface forgets the drawn board, so the next match drawn there — even the same replay watched again —
  // starts as a fresh board (no mark, venue light or fallen tokens carried over).
  if (name !== 'match') { resetArenaBoardScale(); clearArenaMatchIntro(); arenaBoardSignature = null; }
  document.querySelector('#arena-selection').hidden = name !== 'selection';
  document.querySelector('#arena-bracket').hidden = name !== 'bracket';
  document.querySelector('#arena-match').hidden = name !== 'match';
  clearArenaWayFailure();
  renderArenaWay();
}

// ----- LLM flavor: 試合前口上 (match intro banner) -----

// 口上の欄: 待つあいだは画面の中の待ちの印（右下で待ちの紋が回る）、届いたら本文、届かなければ失敗の紋（字は持たない・原因は console）。
function setArenaMatchIntroBanner({ state, text = '' }) {
  const node = document.querySelector('#arena-match-intro');
  if (state === 'hidden') { node.hidden = true; node.replaceChildren(); node.removeAttribute('data-state'); return; }
  node.hidden = false;
  node.dataset.state = state; // 'pending' | 'ready' | 'error'
  if (state === 'pending') node.replaceChildren(screenWaitMark('口上を生成中'));
  else if (state === 'error') node.replaceChildren(venueFailureMark('口上の生成に失敗しました'));
  else node.textContent = text;
}

function clearArenaMatchIntro() {
  arenaIntroMatchId = null;
  setArenaMatchIntroBanner({ state: 'hidden' });
}

// Fetch (or restore the persisted) 口上 for a viewable match and show it in the match banner. Runs on its own —
// NOT gated by arenaActionInFlight — so board input keeps working while the 口上 streams; a 503 shows an explicit
// error in the banner without interrupting the match / replay. A newer match's intro supersedes a stale in-flight
// one via the arenaIntroMatchId token.
async function arenaShowMatchIntro(matchId) {
  arenaIntroMatchId = matchId;
  setArenaMatchIntroBanner({ state: 'pending' });
  try {
    const payload = await postJson('/api/arena/match/intro', { match_id: matchId });
    const { intro } = validateArenaIntroResponse(payload);
    if (arenaIntroMatchId !== matchId) return; // a newer match took over — drop the stale result
    setArenaMatchIntroBanner({ state: 'ready', text: intro });
  } catch (error) {
    if (arenaIntroMatchId !== matchId) return;
    setArenaMatchIntroBanner({ state: 'error' });
    console.error(error);
  }
}

// ----- LLM flavor: 優勝・敗退実況一文 (terminal result) -----

function resetArenaResultFlavor() {
  arenaResultFlavorState = { text: null, pending: false, failed: false };
}

// The flavor line node for the terminal result panel, reflecting the current fetch state (pending / ready /
// error). Rebuilt whenever the result panel re-renders, and swapped in place when a fetch completes.
function arenaResultFlavorNode() {
  const p = document.createElement('p');
  p.className = 'arena-result-flavor';
  p.id = 'arena-result-flavor';
  if (arenaResultFlavorState.text) { p.dataset.state = 'ready'; p.textContent = arenaResultFlavorState.text; }
  else if (arenaResultFlavorState.failed) { p.dataset.state = 'error'; p.append(venueFailureMark('実況の生成に失敗しました')); }
  else { p.dataset.state = 'pending'; p.append(screenWaitMark('実況を生成中')); }
  return p;
}

function refreshArenaResultFlavorDom() {
  const existing = document.querySelector('#arena-result-flavor');
  if (existing) existing.replaceWith(arenaResultFlavorNode());
}

// Fetch (or restore the persisted) 実況一文 once per concluded tournament. Idempotent + single-flight: a second
// call while a fetch is in flight, or after it succeeded, is a no-op. A 503 leaves an explicit error in the slot
// while the reward panel and 闘技会を出る stay operable.
async function arenaEnsureResultFlavor() {
  if (arenaResultFlavorState.text || arenaResultFlavorState.pending) return;
  arenaResultFlavorState.pending = true;
  arenaResultFlavorState.failed = false;
  try {
    const payload = await postJson('/api/arena/result-flavor', {});
    const { flavor } = validateArenaResultFlavorResponse(payload);
    arenaResultFlavorState.text = flavor;
  } catch (error) {
    arenaResultFlavorState.failed = true;
    console.error(error);
  } finally {
    arenaResultFlavorState.pending = false;
    refreshArenaResultFlavorDom();
  }
}

// Open the arena: the participate-form selection when no tournament is built this week, else the bracket (with
// the player's live match restored when one is in progress — reload resume). A malformed payload fails fast
// (validateArenaState) before any surface renders.
async function refreshArenaScreen() {
  stopArenaReplay();
  resetArenaBoardScale();
  resetArenaResultFlavor();
  arenaSpectate = null;
  const payload = await getJson('/api/arena/state');
  renderArenaState(validateArenaState(payload));
}

function renderArenaState(view) {
  currentArenaState = view;
  if (view.phase === 'selection') { renderArenaSelection(view); return; }
  // A tournament with a live match (start / resume) drops straight into the match surface; otherwise the bracket.
  if (view.current_match) {
    renderArenaMatch(view.current_match, view, { replay: false });
    setArenaTurn(view.current_match.player_actor_id ?? null);
    if (view.current_match_id) arenaShowMatchIntro(view.current_match_id); // resume restores the persisted 口上
    return;
  }
  renderArenaBracket(view);
}

// ----- phase 1: participate-form selection -----

// 選ぶ段: 床の魔法陣に三つの立ち位置（一人・二人・バディーの観戦）。形の紋が床に灯る輪の上に立ち、名は読み上げの名だけ。
// 選べない立ち位置は沈んで押せず（隠さない）、二人と観戦の後ろの姿（バディー）は、バディーがいなければ破線の空いた輪郭になる。
function renderArenaSelection(view) {
  teardownArenaConsumableTargeting();
  currentArenaMatchView = null;
  currentArenaState = view;
  showArenaSurface('selection');
  const container = document.querySelector('#arena-selection-modes');
  container.replaceChildren();
  const buddyName = view.buddy ? view.buddy.display_name : null;
  for (const mode of view.modes) {
    const spot = document.createElement('button');
    spot.type = 'button';
    spot.className = 'arena-floor-spot';
    spot.dataset.mode = mode.mode;
    spot.disabled = !mode.available;
    const withBuddy = mode.mode === 'pair' || mode.mode === 'spectate';
    const reason = !mode.available && mode.reason ? arenaModeUnavailableReasonText(mode.reason) : null;
    const buddy = withBuddy && buddyName ? `バディー：${buddyName}` : null;
    const detail = [buddy, reason].filter(Boolean).join('・');
    spot.setAttribute('aria-label', detail ? `${ARENA_MODE_LABELS[mode.mode]}（${detail}）` : ARENA_MODE_LABELS[mode.mode]);
    const ring = document.createElement('span');
    ring.className = 'arena-floor-ring';
    ring.setAttribute('aria-hidden', 'true');
    const holder = document.createElement('span');
    holder.innerHTML = ARENA_MODE_SIGILS[mode.mode];
    const sigil = holder.firstElementChild;
    sigil.setAttribute('class', 'arena-floor-sigil');
    // 二人・観戦の紋の後ろの姿（頭の円と胴の二つ）がバディー。いないときは破線の空いた輪郭。
    if (withBuddy && !view.buddy) for (const part of [...sigil.children].slice(-2)) part.dataset.buddy = 'absent';
    spot.append(ring, sigil);
    spot.addEventListener('click', () => arenaEnter(mode.mode).catch(reportArenaScreenError));
    container.append(spot);
  }
}

async function arenaEnter(mode) {
  if (arenaActionInFlight) { showProcessingToast(); return; }
  arenaActionInFlight = true;
  try {
    resetArenaResultFlavor(); // a fresh tournament — the prior week's 実況一文 must not linger
    const payload = await postJson('/api/arena/enter', { mode });
    const view = validateArenaState(payload);
    // 観戦は入場で大会が解けているが、表は一回戦の組み合わせから始め、バディーの試合を見ていくごとに明かす。
    if (view.mode === 'spectate') { arenaSpectate = { revealed: 0 }; startArenaSpectateEntrance(view); return; }
    renderArenaState(view);
  } finally {
    arenaActionInFlight = false;
  }
}

// ----- phase 2: bracket -----

// 勝ち上がりの表の段（トーナメントが終わっていれば結果の段: 表の上に結果が乗り、右上に出る紋が立つ）。
// revealFrom（試合から戻ったときだけ）: 戻る前の表が結果を見せていた回戦の数。そこから今の表までの差を順に明かし、明かし終わって
// から試合を始める紋（大会が終わっていれば、表を沈めて結果の段）を立てる。無ければ明かし終わりの姿で描く（読み直し・見返しから戻る）。
function renderArenaBracket(view, { revealFrom = null } = {}) {
  teardownArenaConsumableTargeting();
  currentArenaMatchView = null;
  currentArenaState = view;
  showArenaSurface('bracket');
  const revealed = arenaRevealedRounds(view);
  if (revealFrom === null || revealFrom === revealed) {
    renderArenaRing(view, arenaShownResults(view, revealed), arenaSpectateEntryMatch(view, revealed));
    renderArenaBracketActions(view);
    renderArenaResult(view);
    return;
  }
  if (revealFrom > revealed) throw new Error(`arena: bracket reveal cannot go back from ${revealFrom} to ${revealed} rounds`);
  startArenaReveal(view, revealFrom, revealed);
}

// 表が結果を見せてよい回戦の数: 主人公の試合が解けた回戦まで（その回戦のほかの組も、そこで明かす）。大会が終われば全部（敗退の後は
// 見届けで決勝まで明かす。観戦は入場で終わった大会）。主人公の解けた試合は一回戦から続く回戦にしか無い — 飛びがあれば表の食い違い。
// 観戦の明かしの間は、バディーの試合を見終えた（見ずに先へで進めた）回戦まで。
function arenaRevealedRounds(view) {
  const rounds = view.bracket.rounds;
  if (view.mode === 'spectate' && arenaSpectate) return arenaSpectate.revealed;
  if (view.terminal) return rounds.length;
  const resolved = rounds.map((round) => round.some((match) => match.is_player_match && match.resolved));
  const count = resolved.includes(false) ? resolved.indexOf(false) : resolved.length;
  if (resolved.slice(count).some(Boolean)) throw new Error('arena: the player has a resolved match after an unresolved round');
  return count;
}

// 結果を見せる試合（match_id の集合）: 明かした回戦の解けた試合。
function arenaShownResults(view, revealedRounds) {
  const shown = new Set();
  view.bracket.rounds.slice(0, revealedRounds).forEach((round) => {
    for (const match of round) {
      if (!match.resolved) throw new Error(`arena: revealed round match ${match.match_id} is unresolved`);
      shown.add(match.match_id);
    }
  });
  return shown;
}

// 表が結果の段まで明かし終えているか（大会が終わり、全部の回戦を明かした）。観戦の明かしの途中は終わった大会でも表の段。
function arenaShowsResult(view) {
  return Boolean(view?.terminal) && arenaRevealedRounds(view) === view.bracket.rounds.length;
}

// 表が主人公に見立てる組の試合か: 主人公の組（一人・二人）、観戦ではバディーの組（player_unit_id）が出る試合。
function arenaHeroMatch(view, match) {
  return match.team_a_unit_id === view.player_unit_id || match.team_b_unit_id === view.player_unit_id;
}

// 観戦で、まだ結果を見せずに見返しの目を金の輪で灯すバディーの次の組（明かし終えていれば無い）。revealed は表が結果を見せている
// 回戦の数（既定は明かし終わりの数。明かしの初めの表は、明かす前の数で描く）。
function arenaSpectateEntryMatch(view, revealed = arenaSpectate?.revealed) {
  if (view.mode !== 'spectate' || !arenaSpectate || revealed >= view.bracket.rounds.length) return null;
  const match = view.bracket.rounds[revealed].find((candidate) => arenaHeroMatch(view, candidate));
  if (!match) throw new Error(`arena: spectate round ${revealed} has no buddy match`);
  return match;
}

// 観戦で一つの回戦を明かす（バディーの試合を見終えた・見ずに先へを押した）。バディーが負けた回戦か決勝なら、決勝まで見届ける。
function arenaSpectateAdvance(view) {
  const entry = arenaSpectateEntryMatch(view);
  if (!entry) throw new Error('arena: spectate has nothing left to reveal');
  const from = arenaSpectate.revealed;
  const lost = entry.winner_unit_id !== view.player_unit_id;
  arenaSpectate.revealed = lost ? view.bracket.rounds.length : from + 1;
  renderArenaBracket(view, { revealFrom: from });
}

// 明かしの順: 回戦ごとに、主人公の組 → （勝って戻ったときは）次の相手を決める隣の組 → 残りを上から。
function arenaRevealOrder(view, round) {
  const player = round.find((match) => arenaHeroMatch(view, match));
  const first = player ? [player] : [];
  const advanced = player && player.winner_unit_id === view.player_unit_id && player.round < view.bracket.rounds.length - 1;
  const neighbor = advanced ? round.find((match) => match.index === (player.index ^ 1)) : null;
  if (neighbor) first.push(neighbor);
  return [...first, ...round.filter((match) => !first.includes(match))];
}

// 明かしの流れ: 戻る前の姿を描き、明かす試合ごとに 節が灯る→勝者の線が次の節へ伸びる を時割りどおりに流す。勝って戻ったときは
// advance の速さ、敗退の後の見届けは watch の速さで回戦の間に短い間を置く。表のどこを押しても、明かし終わりの姿まで畳む。
function startArenaReveal(view, fromRounds, toRounds) {
  const shown = arenaShownResults(view, fromRounds);
  const ring = renderArenaRing(view, shown, arenaSpectateEntryMatch(view, fromRounds));
  document.querySelector('#arena-bracket-actions').replaceChildren();
  hideArenaResult();
  const lastRound = view.bracket.rounds.length - 1;
  // 見立てた組（主人公・観戦ではバディー）が明かす回戦で負けていれば、敗退の後の見届けの速さ。
  const heroLost = view.bracket.rounds.slice(fromRounds, toRounds)
    .some((round) => round.some((match) => arenaHeroMatch(view, match) && match.winner_unit_id !== view.player_unit_id));
  const pace = ARENA_REVEAL_PACES[heroLost ? 'watch' : 'advance'];
  const timers = [];
  const at = (ms, fn) => timers.push(window.setTimeout(fn, ms));
  let t = 0;
  for (let r = fromRounds; r < toRounds; r += 1) {
    if (r > fromRounds) t += pace.roundGap;
    let end = t;
    arenaRevealOrder(view, view.bracket.rounds[r]).forEach((match, order) => {
      const lead = arenaHeroMatch(view, match) || r === lastRound;
      const step = lead ? ARENA_REVEAL_LEAD_MS : pace.step;
      at(t, () => arenaRingRevealMatch(ring, match, shown, step));
      end = Math.max(end, t + step);
      t += lead && order === 0 ? step : pace.stagger;
    });
    t = end;
  }
  const finish = ({ folded }) => {
    stopArenaReveal();
    if (folded) renderArenaRing(view, arenaShownResults(view, toRounds), arenaSpectateEntryMatch(view));
    else applyArenaRingState(ring, shown, arenaSpectateEntryMatch(view));
    renderArenaWay();
    renderArenaBracketActions(view);
    if (arenaShowsResult(view) && !folded) document.querySelector('#arena-bracket').classList.add('arena-bracket--sinking');
    renderArenaResult(view);
  };
  const foldOnClick = (event) => {
    event.preventDefault();
    event.stopPropagation();
    finish({ folded: true });
  };
  arenaScreen.addEventListener('click', foldOnClick, true);
  arenaReveal = { timers, foldOnClick };
  renderArenaWay(); // the way stays on 勝ち上がりの表 (and 出る stays hidden) until the result stands
  at(t, () => finish({ folded: false }));
}

// 明かしを止める（面を移る・読み直す）。止めた後の姿は、呼んだ側が描き直す。
function stopArenaReveal() {
  document.querySelector('#arena-bracket').classList.remove('arena-bracket--sinking', 'arena-bracket--entering', 'arena-bracket--hero-lit');
  if (!arenaReveal) return;
  for (const timer of arenaReveal.timers) window.clearTimeout(timer);
  arenaScreen.removeEventListener('click', arenaReveal.foldOnClick, true);
  arenaReveal = null;
}

// 一組の明かし（step の長さ）: 節が灯り（解けた自動の組は見返しの目が開く）、負けた名が半分の濃さへ沈み、勝者の線が節から次の節へ
// 伸びて、伸びる先に光の頭が付く。主人公が進むときは主人公の名の後ろに金の楕円の板が灯って消える。決勝は頂に星が灯り、優勝者の道が
// 金で中心まで通り、優勝者の名の後ろに板が灯る。
function arenaRingRevealMatch(ring, match, shown, step) {
  const last = ring.view.bracket.rounds.length - 1;
  const ms = `${step}ms`;
  const loser = match.winner_unit_id === match.team_a_unit_id ? match.team_b_unit_id : match.team_a_unit_id;
  ring.labels.get(loser).style.setProperty('--arena-reveal-ms', ms);
  shown.add(match.match_id);
  applyArenaRingState(ring, shown, ring.entry);
  const eye = ring.eyes.get(match.match_id);
  if (eye) {
    eye.style.setProperty('--arena-reveal-ms', ms);
    eye.classList.add('arena-ring-eye--lit');
  }
  if (match.round === last) {
    ring.crownStar.style.setProperty('--arena-reveal-ms', ms);
    ring.crownStar.classList.add('arena-ring-crown-star--lighting');
    glowArenaRingPlate(ring, match.winner_unit_id, step);
    return;
  }
  const lit = ring.nodeEdges.get(match.match_id).lit;
  lit.style.setProperty('--arena-reveal-ms', ms);
  lit.classList.add('arena-ring-lit--growing');
  startArenaRingHead(ring, match.match_id, step);
  if (match.winner_unit_id === ring.view.player_unit_id) glowArenaRingPlate(ring, match.winner_unit_id, step);
}

function glowArenaRingPlate(ring, unitId, step) {
  const plate = ring.labels.get(unitId).querySelector('.arena-ring-plate');
  plate.style.setProperty('--arena-reveal-ms', `${step}ms`);
  plate.classList.add('arena-ring-plate--glowing');
}

// 光の頭: 伸びる線の先を、線の点列に沿って step の長さで節から次の節へ運ぶ（伸びきったら消える）。
function startArenaRingHead(ring, matchId, step) {
  const head = document.createElementNS(VENUE_SVG_NS, 'circle');
  head.setAttribute('class', 'arena-ring-head');
  head.setAttribute('r', '2.6');
  ring.layers.nodes.append(head);
  const entry = { matchId, head };
  entry.animation = head.animate(arenaRingHeadFrames(ring, matchId), { duration: step, easing: 'linear', fill: 'both', id: 'arena-ring-head' });
  entry.animation.onfinish = () => {
    head.remove();
    ring.heads.delete(entry);
  };
  ring.heads.add(entry);
}

// 光の頭の keyframes: 節から次の節への線の点列を、線に沿う長さの割合で並べる。
function arenaRingHeadFrames(ring, matchId) {
  const points = ring.layout.edgePoints.get(matchId);
  const steps = points.slice(1).map((p, i) => Math.hypot(p[0] - points[i][0], p[1] - points[i][1]));
  const total = steps.reduce((sum, d) => sum + d, 0);
  let along = 0;
  return points.map((p, i) => {
    if (i > 0) along += steps[i - 1];
    return { transform: `translate(${p[0]}px, ${p[1]}px)`, offset: total > 0 ? along / total : i / (points.length - 1) };
  });
}

// unit_id -> the unit (identity + actors), for the bracket name labels (the bracket is server-authoritative — the
// client never re-pairs units, it only draws the rounds the view hands it).
function arenaUnitMap(view) {
  const map = new Map();
  for (const unit of view.units) map.set(unit.unit_id, unit);
  return map;
}

// 円の表の寸法（px・どの窓でも同じ）。名は円の左右に段で一度だけ置く: 段の高さ rowH、一回戦の組の間は段の matchGapRatio ぶん空け、
// 段は画面の上 top から下 bottomReserve の手前まで。円の半径は、横の余地（窓の端から marginX・名の札から円まで labelGap・いちばん
// 広い名の札）と、段の半分の高さ ÷ rowSpan の小さい方。回戦ごとの輪は半径の rings 倍（一回戦・準々決勝・準決勝・決勝 = 中心の輪）。
// 道が輪へ乗る・輪から節へ降りる四分円の半径は bendMax まで、かつその輪でいちばん短い回りの bendShare 倍まで。eye は見返しの目の
// 釦の一辺、finalEyeDrop は決勝の目を頂から下へずらす長さ。
const ARENA_RING = Object.freeze({
  top: 92, bottomReserve: 98, marginX: 28, labelGap: 12, rowH: 40, matchGapRatio: 0.45, rowSpan: 0.80,
  rings: Object.freeze([0.86, 0.70, 0.54, 0.38]), bendMax: 14, bendShare: 0.35, bendSteps: 12, eye: 30, finalEyeDrop: 34
});
let arenaRing = null;               // the drawn ring bracket: { view, host, svg, layers, labels, firstEdges, nodeEdges, dots, eyes, crown, crownStar, heads, entry, layout }

// 表の上の組 m が勝者を送る次の回戦の組（決勝は無い）。round r+1 の組 i は、round r の組 2i・2i+1 の勝者が出会う。
function arenaParentMatch(view, match) {
  const rounds = view.bracket.rounds;
  return match.round === rounds.length - 1 ? null : rounds[match.round + 1][Math.floor(match.index / 2)];
}

// 円の表を描く: 一回戦の 16 の名を円の左右に 8 段ずつ一度だけ置き（左は一回戦の組 0..3、右は 4..7 を上から）、名の端から線が内へ
// 入って回戦ごとの同心の輪を一つずつ渡り、中心の輪の真上（頂）で決勝になる。名は押せないただの字（名の窓は HUD の名からだけ開く）。
// 部品を作り（renderArenaRing）、窓の寸法から置き（layoutArenaRing）、見せている結果で灯す（applyArenaRingState）。
// shown は結果を見せる試合（match_id の集合）、entry は観戦でバディーの次の組（見返しの目を金の輪で灯す・無ければ null）。
function renderArenaRing(view, shown, entry) {
  const host = document.querySelector('#arena-bracket-ring');
  host.replaceChildren();
  const rounds = view.bracket.rounds;
  const last = rounds.length - 1;
  const units = arenaUnitMap(view);
  const svg = document.createElementNS(VENUE_SVG_NS, 'svg');
  svg.setAttribute('class', 'arena-ring');
  svg.setAttribute('aria-hidden', 'true');
  const defs = document.createElementNS(VENUE_SVG_NS, 'defs');
  // 結果の段の板の下は、円を溶かして消す（線が結果の字に重ならない）。板の箱は fitArenaRingResultMask が合わせる。
  defs.innerHTML = '<filter id="arena-ring-feather" x="-20%" y="-20%" width="140%" height="140%"><feGaussianBlur stdDeviation="22"/></filter>'
    + '<mask id="arena-ring-under-result" maskUnits="userSpaceOnUse"><rect class="arena-ring-mask-field" fill="white"/>'
    + '<rect class="arena-ring-mask-hole" rx="60" fill="black" filter="url(#arena-ring-feather)"/></mask>';
  svg.append(defs);
  const layer = (name) => {
    const g = document.createElementNS(VENUE_SVG_NS, 'g');
    g.setAttribute('class', `arena-ring-layer arena-ring-layer--${name}`);
    svg.append(g);
    return g;
  };
  const layers = { skeleton: layer('skeleton'), route: layer('route'), lit: layer('lit'), nodes: layer('nodes') };
  const path = (parent, className) => {
    const p = document.createElementNS(VENUE_SVG_NS, 'path');
    p.setAttribute('class', className);
    p.setAttribute('fill', 'none');
    parent.append(p);
    return p;
  };
  // 四つの輪（一回戦・準々決勝・準決勝・決勝 = 中心の輪）を全周まで引く（まだの線より淡い）。道はこの輪の上を回る。
  const guides = ARENA_RING.rings.map(() => {
    const c = document.createElementNS(VENUE_SVG_NS, 'circle');
    c.setAttribute('class', 'arena-ring-guide');
    c.setAttribute('fill', 'none');
    layers.skeleton.append(c);
    return c;
  });
  // 線: まだの線（skeleton）の上に、灯った線（lit・pathLength 1 で伸びる長さを割合で持つ）を重ねる。自分のこの先の道は route。
  const litPath = () => {
    const p = path(layers.lit, 'arena-ring-lit');
    p.setAttribute('pathLength', '1');
    return p;
  };
  const firstEdges = new Map();
  const labels = new Map();
  for (const match of rounds[0]) {
    for (const unitId of [match.team_a_unit_id, match.team_b_unit_id]) {
      const unit = units.get(unitId);
      if (!unit) throw new Error(`arena: bracket unit ${unitId} is missing from the view`);
      const first = { skeleton: path(layers.skeleton, 'arena-ring-line'), lit: litPath() };
      first.lit.dataset.unitId = unitId;
      firstEdges.set(unitId, first);
      const label = document.createElement('div');
      label.className = 'arena-ring-name';
      label.dataset.unitId = unitId;
      const plate = document.createElement('div');
      plate.className = 'arena-ring-plate';
      label.append(plate);
      for (const actor of unit.actors) {
        const line = document.createElement('div');
        line.className = 'arena-ring-name-line';
        line.dataset.actorId = actor.actor_id;
        line.textContent = actor.name;
        label.append(line);
      }
      host.append(label);
      labels.set(unitId, label);
    }
  }
  const nodeEdges = new Map();
  const dots = new Map();
  for (const round of rounds.slice(0, last)) {
    for (const match of round) {
      const edge = { skeleton: path(layers.skeleton, 'arena-ring-line'), lit: litPath(), route: path(layers.route, 'arena-ring-route') };
      for (const p of [edge.lit, edge.route]) {
        p.dataset.matchId = match.match_id;
        p.dataset.round = String(match.round);
      }
      nodeEdges.set(match.match_id, edge);
      const dot = document.createElementNS(VENUE_SVG_NS, 'circle');
      dot.setAttribute('class', 'arena-ring-node');
      dot.dataset.matchId = match.match_id;
      dot.dataset.round = String(match.round);
      layers.nodes.append(dot);
      dots.set(match.match_id, dot);
    }
  }
  // 頂（決勝の節・中心の輪の真上）: 細い輪、決勝が自分の次の組なら深紅、明かしたら金で灯り、星が付く。
  const crown = document.createElementNS(VENUE_SVG_NS, 'circle');
  crown.setAttribute('class', 'arena-ring-crown');
  crown.setAttribute('r', '16');
  crown.dataset.matchId = rounds[last][0].match_id;
  crown.dataset.round = String(last);
  layers.nodes.append(crown);
  const crownStar = venueSigil('star', 'arena-ring-crown-star');
  host.prepend(svg);
  host.append(crownStar);
  const ring = { view, host, svg, layers, guides, labels, firstEdges, nodeEdges, dots, eyes: new Map(), crown, crownStar, heads: new Set(), entry, layout: null };
  arenaRing = ring;
  layoutArenaRing(ring);
  applyArenaRingState(ring, shown, entry);
  return ring;
}

// 円の表を窓の寸法から置く（描いたときと、窓の寸法が変わるたび）。表が隠れている間は測れないので置かず、出たときに置き直す
// （#arena-bracket-ring の ResizeObserver）。
function layoutArenaRing(ring) {
  const { width: W, height: H } = ring.host.getBoundingClientRect();
  if (W === 0 || H === 0) return;
  const A = ARENA_RING;
  const rounds = ring.view.bracket.rounds;
  const last = rounds.length - 1;
  const order = rounds[0].flatMap((match) => [match.team_a_unit_id, match.team_b_unit_id]);
  const rows = order.length / 2; // 片側の段の数
  const top = A.top + A.rowH / 2;
  const bottom = H - A.bottomReserve - A.rowH / 2;
  const unit = (bottom - top) / ((rows - 1) + (rows / 2 - 1) * A.matchGapRatio);
  const ys = Array.from({ length: rows }, (_, k) => top + k * unit + Math.floor(k / 2) * unit * A.matchGapRatio);
  const cx = W / 2;
  const cy = (top + bottom) / 2;
  const labelWidth = Math.max(...[...ring.labels.values()].map((label) => label.getBoundingClientRect().width));
  const r = Math.min(cx - A.marginX - A.labelGap - labelWidth, (bottom - top) / 2 / A.rowSpan);
  const pt = (radius, angle) => [cx + radius * Math.cos(angle), cy + radius * Math.sin(angle)];
  // 名の端（円の上）と角度。左は 90°〜270° の続いた角度で持つ。
  const anchors = new Map();
  order.forEach((unitId, p) => {
    const left = p < rows;
    const y = ys[left ? p : p - rows];
    const dx = Math.sqrt(Math.max(0, r * r - (y - cy) ** 2));
    let a = Math.atan2(y - cy, left ? -dx : dx);
    if (left && a < 0) a += 2 * Math.PI;
    anchors.set(unitId, { R: r, a, left, x: cx + (left ? -dx : dx), y });
  });
  // 節: k 回戦の線は輪 k に乗って回り、節は輪の少し内（輪 − 曲がりの半径）。一回戦の節は組の二つの名のうち横の軸に近い名の角度
  // （近い名は真っ直ぐ内へ入り、遠い名は輪を回って寄る — どちらの道も上下の向きが反転しない）、以後は前の二つの節の中ほど。決勝の
  // 節は中心の輪の頂（真上）。
  const nodes = new Map();
  rounds.forEach((round, ri) => {
    const radius = r * A.rings[ri];
    if (ri === last) {
      const [x, y] = pt(radius, -Math.PI / 2);
      nodes.set(round[0].match_id, { R: radius, ring: radius, bend: A.bendMax, final: true, x, y });
      return;
    }
    const feeds = round.map((match) => (ri === 0
      ? [anchors.get(match.team_a_unit_id), anchors.get(match.team_b_unit_id)]
      : [nodes.get(rounds[ri - 1][match.index * 2].match_id), nodes.get(rounds[ri - 1][match.index * 2 + 1].match_id)]));
    const offAxis = (feed) => Math.abs(feed.left ? feed.a - Math.PI : feed.a);
    const angles = feeds.map(([f0, f1]) => (ri === 0 ? (offAxis(f0) < offAxis(f1) ? f0.a : f1.a) : (f0.a + f1.a) / 2));
    const shortest = Math.min(...feeds.flatMap((feed, i) => feed.map((f) => Math.abs(angles[i] - f.a) * radius)).filter((s) => s > 1e-6));
    const bend = Math.min(A.bendMax, A.bendShare * shortest);
    round.forEach((match, i) => {
      const [x, y] = pt(radius - bend, angles[i]);
      nodes.set(match.match_id, { R: radius - bend, a: angles[i], ring: radius, bend, left: feeds[i][0].left, x, y });
    });
  });
  // 線の点列: from から内へ降り、四分円で輪に乗り、輪に沿って節の角度まで回り、四分円で節へ降りる。輪に沿う長さ s（角度 × 輪の
  // 半径）と半径の平面で描いて円へ写すので、半径は一度も増えず、どこでも向きが続く。決勝の線は中心の輪に乗った後、頂まで回って終わる。
  const edgePoints = (from, to) => {
    const an = to.final ? (from.left ? 1.5 * Math.PI : -0.5 * Math.PI) : to.a;
    const { ring: radius, bend: f } = to;
    const dir = Math.sign(an - from.a) || 1;
    const s0 = from.a * radius;
    const s1 = an * radius;
    const sp = [[s0, from.R]];
    if (!to.final && Math.abs(s1 - s0) < 1e-6) sp.push([s0, radius - f]); // 節と同じ角度から: 真っ直ぐ内へ
    else {
      for (let i = 0; i <= A.bendSteps; i += 1) {
        const q = (i / A.bendSteps) * Math.PI / 2;
        sp.push([s0 + dir * f * (1 - Math.cos(q)), radius + f * (1 - Math.sin(q))]);
      }
      const arcFrom = s0 + dir * f;
      const arcTo = to.final ? s1 : s1 - dir * f;
      const arcSteps = Math.max(2, Math.ceil(Math.abs(arcTo - arcFrom) / 3));
      for (let i = 1; i <= arcSteps; i += 1) sp.push([arcFrom + (arcTo - arcFrom) * (i / arcSteps), radius]);
      if (!to.final) {
        for (let i = 1; i <= A.bendSteps; i += 1) {
          const q = (i / A.bendSteps) * Math.PI / 2;
          sp.push([arcTo + dir * f * Math.sin(q), radius - f * (1 - Math.cos(q))]);
        }
      }
    }
    return sp.map(([s, radius2]) => pt(radius2, s / radius));
  };
  const pathData = (points) => `M${points.map(([x, y]) => `${x.toFixed(2)} ${y.toFixed(2)}`).join(' L')}`;
  ring.svg.setAttribute('width', String(W));
  ring.svg.setAttribute('height', String(H));
  for (const field of ring.svg.querySelectorAll('#arena-ring-under-result, .arena-ring-mask-field')) {
    field.setAttribute('x', '0');
    field.setAttribute('y', '0');
    field.setAttribute('width', String(W));
    field.setAttribute('height', String(H));
  }
  ring.guides.forEach((guide, i) => {
    guide.setAttribute('cx', String(cx));
    guide.setAttribute('cy', String(cy));
    guide.setAttribute('r', String(r * A.rings[i]));
  });
  for (const match of rounds[0]) {
    for (const unitId of [match.team_a_unit_id, match.team_b_unit_id]) {
      const d = pathData(edgePoints(anchors.get(unitId), nodes.get(match.match_id)));
      const edge = ring.firstEdges.get(unitId);
      edge.skeleton.setAttribute('d', d);
      edge.lit.setAttribute('d', d);
    }
  }
  const nodeEdgePoints = new Map();
  for (const round of rounds.slice(0, last)) {
    for (const match of round) {
      const points = edgePoints(nodes.get(match.match_id), nodes.get(arenaParentMatch(ring.view, match).match_id));
      nodeEdgePoints.set(match.match_id, points);
      const d = pathData(points);
      const edge = ring.nodeEdges.get(match.match_id);
      for (const p of [edge.skeleton, edge.lit, edge.route]) p.setAttribute('d', d);
      const { x, y } = nodes.get(match.match_id);
      ring.dots.get(match.match_id).setAttribute('cx', String(x));
      ring.dots.get(match.match_id).setAttribute('cy', String(y));
    }
  }
  const crown = nodes.get(rounds[last][0].match_id);
  ring.crown.setAttribute('cx', String(crown.x));
  ring.crown.setAttribute('cy', String(crown.y));
  ring.crownStar.style.left = `${crown.x - 11}px`;
  ring.crownStar.style.top = `${crown.y - 11}px`;
  // 名の札: 名の端から labelGap 外、円の外側へ揃える（左の名は右揃え・右の名は左揃え）。
  for (const [unitId, label] of ring.labels) {
    const an = anchors.get(unitId);
    const box = label.getBoundingClientRect();
    label.classList.toggle('arena-ring-name--left', an.left);
    label.style.top = `${an.y - box.height / 2}px`;
    label.style.left = `${an.left ? an.x - A.labelGap - box.width : an.x + A.labelGap}px`;
  }
  ring.layout = { W, H, cx, cy, r, nodes, edgePoints: nodeEdgePoints, crown };
  for (const [matchId, eye] of ring.eyes) placeArenaRingEye(ring, matchId, eye);
  for (const entry of ring.heads) entry.animation.effect.setKeyframes(arenaRingHeadFrames(ring, entry.matchId));
  ring.host.dataset.layout = `${W}x${H}`;
}

// 見返しの目の釦を節の上へ置く。決勝の目は頂の星の下（中心の輪の内）。
function placeArenaRingEye(ring, matchId, eye) {
  if (!ring.layout) return;
  const node = ring.layout.nodes.get(matchId);
  const y = node.final ? node.y + ARENA_RING.finalEyeDrop : node.y;
  eye.style.left = `${node.x - ARENA_RING.eye / 2}px`;
  eye.style.top = `${y - ARENA_RING.eye / 2}px`;
}

// 見せている結果で円の表を灯す（何度呼んでも同じ姿になる）。
// - 線: 自分（観戦はバディー）の名から一回戦の節までは常に金。勝った組の線は白く灯り、自分の道は金、自分が負けた後の自分の道は半分の
//   濃さの金、優勝が明かされたら優勝者の道は名から頂まで強い金。自分のまだ明かしていない組から先の道は金の点線で頂まで。
// - 節: 明かした自動の組は見返しの目、観戦のバディーの次の組は金の輪の目、自分の次の組は深紅の輪、明かした組は灯（自分が勝った組は
//   金）、まだの組は小さな点。決勝は頂が担う。
// - 名: 自分は強い字、負けが明かされた名は半分の濃さ、勝ち上がった名は少し強い字、優勝者は強い字と星一つ。
function applyArenaRingState(ring, shown, entry) {
  const { view } = ring;
  ring.entry = entry;
  const rounds = view.bracket.rounds;
  const last = rounds.length - 1;
  const hero = view.player_unit_id;
  const isShown = (match) => shown.has(match.match_id);
  const champion = rounds[last][0];
  const crowned = isShown(champion) ? champion.winner_unit_id : null;
  const heroOut = rounds.some((round) => round.some((match) => isShown(match) && arenaHeroMatch(view, match) && match.winner_unit_id !== hero));
  const variant = (unitId) => (unitId === crowned ? 'champion' : unitId === hero ? 'hero' : 'won');
  const light = (litPath, unitId) => {
    litPath.classList.toggle('arena-ring-lit--on', unitId !== null);
    for (const kind of ['champion', 'hero', 'won']) litPath.classList.toggle(`arena-ring-lit--${kind}`, unitId !== null && variant(unitId) === kind);
  };
  ring.svg.classList.toggle('arena-ring--hero-out', heroOut);
  for (const match of rounds[0]) {
    for (const unitId of [match.team_a_unit_id, match.team_b_unit_id]) {
      const lit = unitId === hero || unitId === crowned || (isShown(match) && match.winner_unit_id === unitId);
      light(ring.firstEdges.get(unitId).lit, lit ? unitId : null);
    }
  }
  const route = new Set();
  for (let match = rounds[0].find((m) => arenaHeroMatch(view, m)); match && match.round < last; match = arenaParentMatch(view, match)) {
    if (isShown(match) && match.winner_unit_id !== hero) break;
    if (!isShown(match)) route.add(match.match_id);
  }
  for (const round of rounds.slice(0, last)) {
    for (const match of round) {
      const edge = ring.nodeEdges.get(match.match_id);
      light(edge.lit, isShown(match) ? match.winner_unit_id : null);
      edge.route.classList.toggle('arena-ring-route--on', route.has(match.match_id));
    }
  }
  const nextHero = heroOut ? null : rounds.map((round) => round.find((match) => arenaHeroMatch(view, match) && !isShown(match))).find(Boolean) ?? null;
  for (const round of rounds) {
    for (const match of round) {
      const state = isShown(match) && match.is_auto ? 'eye'
        : match === entry ? 'entry'
          : match === nextHero ? 'next'
            : isShown(match) ? (match.winner_unit_id === hero ? 'hero' : 'won') : 'open';
      (match.round === last ? ring.crown : ring.dots.get(match.match_id)).dataset.state = state;
      let eye = ring.eyes.get(match.match_id);
      if (state === 'eye' || state === 'entry') {
        if (!eye) {
          eye = venueSigilButton('watch', '観戦', () => startArenaReplay(match.match_id).catch(reportArenaScreenError), 'arena-ring-eye');
          eye.dataset.matchId = match.match_id;
          eye.dataset.round = String(match.round);
          ring.host.append(eye);
          ring.eyes.set(match.match_id, eye);
          placeArenaRingEye(ring, match.match_id, eye);
        }
        eye.classList.toggle('arena-ring-eye--entry', state === 'entry');
      } else if (eye) {
        eye.remove();
        ring.eyes.delete(match.match_id);
      }
    }
  }
  ring.crown.classList.toggle('arena-ring-crown--lit', crowned !== null);
  ring.crownStar.classList.toggle('arena-ring-crown-star--lit', crowned !== null);
  const lost = new Set();
  const advanced = new Set();
  for (const round of rounds) {
    for (const match of round) {
      if (!isShown(match)) continue;
      advanced.add(match.winner_unit_id);
      lost.add(match.winner_unit_id === match.team_a_unit_id ? match.team_b_unit_id : match.team_a_unit_id);
    }
  }
  for (const [unitId, label] of ring.labels) {
    label.classList.toggle('arena-ring-name--hero', unitId === hero);
    label.classList.toggle('arena-ring-name--lost', lost.has(unitId));
    label.classList.toggle('arena-ring-name--advanced', unitId !== hero && !lost.has(unitId) && advanced.has(unitId));
    label.classList.toggle('arena-ring-name--champion', unitId === crowned);
    const star = label.querySelector('.arena-ring-name-star');
    if (unitId === crowned && !star) label.append(venueSigil('star', 'arena-ring-name-star'));
    else if (unitId !== crowned && star) star.remove();
  }
}

// 結果の段: 板の下の円を溶かして消し（線が結果の字に重ならない）、板に重なる見返しの目を隠す。板の箱は transform の前の置き場から取る
// （立ち上がりの動きでずれない）。板が出ていなければ溶かさない。
function fitArenaRingResultMask() {
  if (!arenaRing?.layout) return;
  const panel = document.querySelector('#arena-result');
  const layers = Object.values(arenaRing.layers);
  if (panel.hidden) {
    for (const g of layers) g.removeAttribute('mask');
    for (const eye of arenaRing.eyes.values()) eye.classList.remove('arena-ring-eye--under-result');
    return;
  }
  const bracket = document.querySelector('#arena-bracket').getBoundingClientRect();
  const box = {
    left: bracket.left + panel.offsetLeft - panel.offsetWidth / 2,
    top: bracket.top + panel.offsetTop - panel.offsetHeight / 2,
    width: panel.offsetWidth,
    height: panel.offsetHeight
  };
  const hole = arenaRing.svg.querySelector('.arena-ring-mask-hole');
  hole.setAttribute('x', String(box.left - 18));
  hole.setAttribute('y', String(box.top - 18));
  hole.setAttribute('width', String(box.width + 36));
  hole.setAttribute('height', String(box.height + 36));
  for (const g of layers) g.setAttribute('mask', 'url(#arena-ring-under-result)');
  for (const eye of arenaRing.eyes.values()) {
    const left = parseFloat(eye.style.left);
    const top = parseFloat(eye.style.top);
    const under = left + ARENA_RING.eye > box.left - 10 && left < box.left + box.width + 10 && top + ARENA_RING.eye > box.top - 10 && top < box.top + box.height + 10;
    eye.classList.toggle('arena-ring-eye--under-result', under);
  }
}

new ResizeObserver(() => {
  if (!arenaRing) return;
  layoutArenaRing(arenaRing);
  fitArenaRingResultMask();
}).observe(document.querySelector('#arena-bracket-ring'));
new ResizeObserver(fitArenaRingResultMask).observe(document.querySelector('#arena-result'));

// 観戦の入り: 一回戦の名だけの表で、バディーの名が灯り（0.3 秒）、バディーの組の目が金の輪で開き（0.7 秒）、落ち着いた所で
// 見ずに先へ進む紋が出る（1 秒）。表のどこを押しても落ち着いた姿まで畳む。
function startArenaSpectateEntrance(view) {
  renderArenaBracket(view);
  const bracket = document.querySelector('#arena-bracket');
  bracket.classList.add('arena-bracket--entering');
  const timers = [];
  const at = (ms, fn) => timers.push(window.setTimeout(fn, ms));
  const finish = () => {
    stopArenaReveal();
    renderArenaWay();
  };
  const foldOnClick = (event) => {
    event.preventDefault();
    event.stopPropagation();
    finish();
  };
  arenaScreen.addEventListener('click', foldOnClick, true);
  arenaReveal = { timers, foldOnClick };
  at(ARENA_SPECTATE_ENTRANCE_MS.heroName, () => bracket.classList.add('arena-bracket--hero-lit'));
  at(ARENA_SPECTATE_ENTRANCE_MS.settle, finish);
}

// The earliest unresolved player match whose opponent is already resolved (both unit ids filled) — the one the
// player can start now. spectate has no player match.
function arenaFindStartablePlayerMatch(view) {
  if (view.mode === 'spectate') return null;
  for (const round of view.bracket.rounds) {
    for (const match of round) {
      if (match.is_player_match && !match.resolved && match.team_a_unit_id && match.team_b_unit_id) return match;
    }
  }
  return null;
}

// 表の下の中ほど（手元）: 始められる自分の試合があれば、試合を始める紋。終わったトーナメントは右上の出る紋で出る（週は送り出しで
// 消費済み）。
function renderArenaBracketActions(view) {
  const actions = document.querySelector('#arena-bracket-actions');
  actions.replaceChildren();
  if (arenaSpectateEntryMatch(view)) {
    actions.append(venueSigilButton('skip', '見ずに先へ', () => { try { arenaSpectateAdvance(view); } catch (error) { reportArenaScreenError(error); } }, 'arena-spectate-skip'));
    return;
  }
  if (view.terminal) return;
  if (arenaFindStartablePlayerMatch(view)) {
    actions.append(venueSigilButton('fight', '試合開始', () => arenaStartMatch().catch(reportArenaScreenError), 'arena-fight'));
  }
}

function hideArenaResult() {
  const panel = document.querySelector('#arena-result');
  panel.hidden = true;
  panel.replaceChildren();
  fitArenaRingResultMask();
}

function renderArenaResult(view) {
  const panel = document.querySelector('#arena-result');
  if (!arenaShowsResult(view) || !view.content_result) { hideArenaResult(); return; }
  const detail = validateArenaContentResult(view.content_result);
  panel.replaceChildren(...buildArenaResultNodes(detail), arenaResultFlavorNode());
  panel.hidden = false;
  fitArenaRingResultMask();
  // The 実況一文 is generated independently of the reward panel — a failure never blocks 闘技会を出る.
  arenaEnsureResultFlavor();
}

// 結果: 優勝・敗退の名と勝ち抜いた数、賞金（賞金の印と額）と素材（素材の結晶の印と名・数）。見出しの字は置かない。
function buildArenaResultNodes(detail) {
  const title = document.createElement('h3');
  title.className = 'arena-result-title';
  title.dataset.outcome = detail.outcome;
  title.textContent = arenaOutcomeLabel(detail.outcome);
  const summary = document.createElement('p');
  summary.className = 'arena-result-summary';
  summary.textContent = `${detail.wins} 勝`;
  const prize = document.createElement('p');
  prize.className = 'arena-result-prize';
  prize.setAttribute('aria-label', '賞金');
  const coins = document.querySelector('#arena-selection .arena-stake-prize .arena-stake-coins').closest('svg').cloneNode(true);
  coins.setAttribute('class', 'arena-stake-art arena-result-prize-mark');
  coins.querySelector('.arena-stake-crystals').remove();
  coins.setAttribute('viewBox', '0 0 72 40');
  const amount = document.createElement('span');
  amount.textContent = `${detail.prize_money.toLocaleString('ja-JP')} G`;
  prize.append(coins, amount);
  const nodes = [title, summary, prize];
  if (detail.materials.length) {
    const list = document.createElement('ul');
    list.className = 'arena-result-materials';
    list.setAttribute('aria-label', '獲得素材');
    for (const item of detail.materials) {
      const row = document.createElement('li');
      row.className = 'arena-result-materials-row';
      const crystal = document.querySelector('#arena-selection .arena-stake-prize .arena-stake-crystals').closest('svg').cloneNode(true);
      crystal.setAttribute('class', 'arena-stake-art arena-result-material-mark');
      crystal.setAttribute('viewBox', '78 6 34 34');
      for (const part of crystal.querySelectorAll('.arena-stake-coins, .arena-stake-rise')) part.remove();
      const name = document.createElement('span');
      name.className = 'arena-result-materials-name';
      name.textContent = item.display_name;
      const qty = document.createElement('span');
      qty.className = 'arena-result-materials-quantity';
      qty.textContent = `×${item.quantity.toLocaleString('ja-JP')}`;
      row.append(crystal, name, qty);
      list.append(row);
    }
    nodes.push(list);
  }
  return nodes;
}

async function arenaStartMatch() {
  if (arenaActionInFlight) { showProcessingToast(); return; }
  arenaActionInFlight = true;
  try {
    const payload = await postJson('/api/arena/match/start', {});
    const view = validateArenaMatchView(payload.view);
    const tournament = validateArenaState(payload.tournament);
    foldArenaEffects();
    renderArenaMatch(view, tournament, { replay: false });
    playArenaEntrance(view);
    if (tournament.current_match_id) arenaShowMatchIntro(tournament.current_match_id);
  } finally {
    arenaActionInFlight = false;
  }
}

// 闘技会を出る is a routing content completion whose return is always the hub (the arena is a routing-only
// destination, so the post-content screen is invariably 'interaction'): return through the shared hub return over the
// arena's art (returnToRoutingHubFromPlace), the same primitive 鍛錬 / 調合 / 工房 use, so the hub-start wait is never a
// bare enterRoutingHub under the still-visible arena screen (a freeze). The wait is never terminal (a failed hub start
// lands on the hub without a conversation).
async function arenaExit() {
  stopArenaReplay();
  await returnToRoutingHubFromPlace();
}

// ----- phase 3/4: match surface (interactive play + spectator replay share one board renderer) -----

function renderArenaMatch(view, tournamentView, { replay = false } = {}) {
  currentArenaMatchView = view;
  if (tournamentView) currentArenaState = tournamentView;
  teardownArenaConsumableTargeting();
  showArenaSurface('match');
  // Interactive controls are live only when a living player controller is up (the view carries the player block)
  // and it is not a replay. In the player's match a resolved / player-down frame keeps the spell dock and the item
  // column as last drawn, every button disabled (the 決着 holds them in place); a replay shows neither.
  const interactive = !replay && view.active && Object.prototype.hasOwnProperty.call(view, 'player_actor_id');
  document.querySelector('#arena-replay-controls').hidden = !replay;
  document.querySelector('#arena-dock-main').hidden = replay;
  document.querySelector('#arena-items').hidden = replay;
  renderArenaHud(view);
  renderArenaLog(view);
  if (replay) renderArenaReplayControls();
  if (interactive) {
    renderArenaDock(view);
    renderArenaConsumables(view);
    arenaDockMatchId = view.match_id;
  } else {
    // A read-only frame of a match the dock never drew (resumed after the player fell) shows it empty, not another match's.
    if (arenaDockMatchId !== view.match_id) {
      for (const slot of ['#arena-spells', '#arena-heal', '#arena-consumables-list']) document.querySelector(slot).replaceChildren();
      arenaDockMatchId = view.match_id;
    }
    for (const button of document.querySelectorAll('#arena-dock-main button, #arena-items button')) button.disabled = true;
  }
  renderArenaBoard(view);
}

async function arenaDo(action) {
  if (arenaActionInFlight || !currentArenaMatchView) return;
  arenaActionInFlight = true;
  const before = currentArenaState; // the bracket as it stood before this exchange (what the table had revealed)
  try {
    const payload = await postJson('/api/arena/action', { action });
    const view = validateArenaMatchView(payload.view);
    const tournament = validateArenaState(payload.tournament);
    const events = validateArenaEvents(payload.events, 'arena action events');
    // A new response folds whatever the previous flow still had in flight (the dungeon's 次の手で畳む), then the whole
    // exchange (every turn the call resolved) plays over the fresh board, turn by turn under the turn ring. A refused action
    // (action_error) passed no turn and plays nothing.
    const previous = currentArenaMatchView;
    foldArenaEffects();
    renderArenaMatch(view, tournament, { replay: false });
    if (view.action_error) return;
    const ending = view.active ? null : arenaPlayerEnding(view, tournament);
    const decided = playArenaFlow(previous, view, events, { slotted: true, ending });
    if (view.active) return;
    // The player's match resolved: the 決着 plays on the still-visible board, the board fades, then the (advanced) bracket
    // takes over — terminal reflects the result + 闘技会を出る there.
    await decided;
    await fadeArenaMatch();
    renderArenaBracket(tournament, { revealFrom: arenaRevealedRounds(before) });
  } finally {
    arenaActionInFlight = false;
  }
}

// The side the protagonist fights on — whether or not the protagonist is still standing — so the HUD's 自陣 and the
// board's ally / enemy rings stay put through the exchange that downs the protagonist. null when no player controller
// fights in the match (a spectator replay: the board then colors team a as the near side).
function arenaFriendlyTeam(view) {
  const player = view.actors.find((actor) => actor.controller === 'player');
  return player ? player.team : null;
}

function arenaPlayerTeamActors(view) {
  const player = view.actors.find((actor) => actor.actor_id === view.player_actor_id);
  if (!player) return [];
  return view.actors.filter((actor) => actor.team === player.team);
}
function arenaDownedTeammates(view) { return arenaPlayerTeamActors(view).filter((actor) => actor.down); }
function arenaLivingTeammates(view) { return arenaPlayerTeamActors(view).filter((actor) => !actor.down); }

// ----- HUD -----

// A HUD bar: the label, the shared lag/fill gauge (the dungeon's 一拍遅れて削れる目盛り) and the number.
function arenaBarEl(label, modifier) {
  const wrap = document.createElement('div');
  wrap.className = `an-hud-bar ${modifier}`;
  const name = document.createElement('span');
  name.className = 'an-hud-bar-label';
  name.textContent = label;
  const track = arenaGaugeEl('an-hud-bar-track');
  const value = document.createElement('span');
  value.className = 'an-hud-bar-value';
  wrap.append(name, track, value);
  return { wrap, track, value };
}

function setArenaBar(bar, current, max) {
  setCombatGauge(bar.track, current, max);
  const text = `${current}/${max}`;
  if (bar.value.textContent !== text) bar.value.textContent = text;
}

function arenaGaugeEl(className) {
  const gauge = document.createElement('div');
  gauge.className = className;
  const lag = document.createElement('div');
  lag.className = 'an-gauge-lag';
  const fill = document.createElement('div');
  fill.className = 'an-gauge-fill';
  gauge.append(lag, fill);
  return gauge;
}

function arenaChipEl(label, value) {
  const chip = document.createElement('div');
  chip.className = 'an-hud-chip';
  const l = document.createElement('span');
  l.className = 'an-hud-chip-label';
  l.textContent = label;
  const v = document.createElement('strong');
  v.textContent = value;
  chip.append(l, v);
  return chip;
}

function arenaActorCard(actor) {
  const card = document.createElement('div');
  card.className = 'an-hud-actor';
  const head = document.createElement('div');
  head.className = 'an-hud-actor-head';
  // Every actor name (protagonist included) is a clickable button that opens its detail.
  const name = arenaNameButton(actor);
  name.classList.add('an-hud-actor-name');
  const state = document.createElement('span');
  state.className = 'an-hud-actor-state';
  state.textContent = '戦闘不能';
  head.append(name, state);
  const hp = arenaBarEl('HP', 'an-hud-bar--hp');
  const mp = arenaBarEl('MP', 'an-hud-bar--mp');
  card.append(head, hp.wrap, mp.wrap);
  return { card, state, hp, mp };
}

function updateArenaActorCard(entry, actor) {
  entry.card.classList.toggle('an-hud-actor--down', actor.down);
  entry.state.hidden = !actor.down;
  setArenaBar(entry.hp, actor.hp, actor.max_hp);
  setArenaBar(entry.mp, actor.mp, actor.max_mp);
}

function arenaHudTeamColumn(label, cards, friendly) {
  const col = document.createElement('div');
  col.className = `an-hud-team${friendly ? ' an-hud-team--friendly' : ''}`;
  const head = document.createElement('p');
  head.className = 'an-hud-team-label';
  head.textContent = label;
  col.append(head, ...cards);
  return col;
}

// The HUD is built once per match line-up (match, actors, 自陣) and then only its round, gauges, numbers and 戦闘不能
// marks move, so the gauges carry the dungeon's lag across the exchange instead of being redrawn at the new value.
function renderArenaHud(view) {
  const node = document.querySelector('#arena-hud-status');
  const friendly = arenaFriendlyTeam(view);
  const signature = JSON.stringify([view.match_id, friendly, view.actors.map((actor) => actor.actor_id)]);
  if (arenaHud?.signature !== signature) {
    // The round number reserves a fixed 4-digit tabular width (arena-round-chip) so 1→2→3→4 digit counts never shift
    // the chip or the party columns beside it.
    const roundChip = arenaChipEl('ラウンド', '');
    roundChip.classList.add('arena-round-chip');
    const cards = new Map(view.actors.map((actor) => [actor.actor_id, arenaActorCard(actor)]));
    // 自陣は主人公の側（盤が近い側に塗る側と同じ読み — 主人公のいない観戦の再生では team a）、もう一方が相手。列の並びは a・b。
    const near = friendly ?? 'a';
    const party = document.createElement('div');
    party.className = 'an-hud-party';
    party.append(...['a', 'b'].map((team) => arenaHudTeamColumn(team === near ? '自陣' : '相手',
      view.actors.filter((actor) => actor.team === team).map((actor) => cards.get(actor.actor_id).card), friendly === team)));
    node.replaceChildren(roundChip, party);
    arenaHud = { signature, round: roundChip.querySelector('strong'), cards };
  }
  arenaHud.round.textContent = String(view.round + 1);
  for (const actor of view.actors) updateArenaActorCard(arenaHud.cards.get(actor.actor_id), actor);
}

// ----- dock (spells + heal) + log -----

function renderArenaDock(view) {
  const spells = document.querySelector('#arena-spells');
  spells.replaceChildren();
  const player = view.actors.find((actor) => actor.actor_id === view.player_actor_id);
  for (const spell of view.castable_elements ?? []) {
    // 属性の紋（露台の能力の紋の属性）と消費 MP の数。名は読み上げの名。
    if (!Object.hasOwn(DUNGEON_MAGIC_LABELS, spell.element)) throw new Error(`arena castable element ${JSON.stringify(spell.element)} is not one of the six attributes`);
    const button = document.createElement('button');
    button.type = 'button';
    button.className = `arena-spell an-el-${spell.element}`;
    button.setAttribute('aria-label', `${spell.label ?? DUNGEON_MAGIC_LABELS[spell.element]}（威力${spell.power ?? ''}・MP${spell.mp_cost}）`);
    const sigil = abilitySigilLabel(spell.element, DUNGEON_MAGIC_LABELS[spell.element]);
    sigil.removeAttribute('role');
    sigil.removeAttribute('aria-label');
    sigil.className = 'arena-spell-sigil';
    const cost = document.createElement('span');
    cost.className = 'arena-spell-mp';
    cost.textContent = String(spell.mp_cost);
    button.append(sigil, cost);
    button.disabled = !player || player.mp < spell.mp_cost;
    button.addEventListener('click', () => arenaDo({ type: 'cast', element: spell.element }).catch(reportError));
    spells.append(button);
  }
  // Self-heal on its own row below the attack spells — label + enabled state come straight from the engine
  // view.healing_spell (the front end never recomputes the heal amount / MP cost). A missing contract fails fast.
  const healSlot = document.querySelector('#arena-heal');
  healSlot.replaceChildren();
  const healing = view.healing_spell;
  if (!healing) throw new Error('arena view is missing healing_spell');
  const { action_type, mp_cost, heal_amount, can_use } = healing;
  if (action_type !== 'heal_spell' || typeof mp_cost !== 'number' || typeof heal_amount !== 'number' || typeof can_use !== 'boolean') {
    throw new Error('arena healing_spell is missing required fields');
  }
  const healButton = document.createElement('button');
  healButton.type = 'button';
  healButton.className = 'arena-spell arena-spell-heal';
  healButton.setAttribute('aria-label', `自己回復 +${heal_amount}（MP${mp_cost}）`);
  const healCost = document.createElement('span');
  healCost.className = 'arena-spell-mp';
  healCost.textContent = String(mp_cost);
  healButton.append(venueSigil('heal'), healCost);
  healButton.disabled = !can_use;
  healButton.addEventListener('click', () => arenaDo({ type: action_type }).catch(reportError));
  healSlot.append(healButton);
}

function renderArenaLog(view) {
  const log = document.querySelector('#arena-log');
  const atBottom = log.scrollHeight - log.scrollTop - log.clientHeight < 4;
  log.replaceChildren();
  for (const entry of view.log ?? []) {
    const p = document.createElement('p');
    p.textContent = entry;
    log.append(p);
  }
  if (view.action_error) {
    const note = document.createElement('p');
    note.className = 'arena-log-note';
    note.textContent = arenaActionErrorText(view.action_error);
    log.append(note);
  }
  if (atBottom) log.scrollTop = log.scrollHeight;
}

// ----- brought-item column (持ち込みアイテム only — no pickups) -----

function renderArenaConsumables(view) {
  const list = document.querySelector('#arena-consumables-list');
  if (!list) return;
  if (!Array.isArray(view.consumables)) throw new Error('arena view is missing consumables');
  // 持ち込んだ品が無ければ、空を知らせる袋の点線の絵（露台の空の絵）を置く。
  if (view.consumables.length === 0) {
    list.replaceChildren(fillWithEmptyArt(document.createElement('span'), 'pouch', '持ち込んだ消耗品はない'));
    return;
  }
  list.replaceChildren(...view.consumables.map((row) => buildArenaConsumableChip(view, row)));
}

// Only revive is render-gated (needs a downed teammate + an unspent per-match revive); every other kind stays
// enabled and lets the server resolve its own guard into a turn-non-consuming action_error.
function arenaConsumableDisabledState(view, row) {
  if (row.target_mode === 'revive') {
    if (view.revive_used) return { disabled: true, reason: 'この試合では蘇生を使い切りました。', note: '使い切り' };
    if (!arenaDownedTeammates(view).length) return { disabled: true, reason: 'ダウン中の味方がいません。', note: '対象なし' };
  }
  return { disabled: false, reason: '', note: '' };
}

function buildArenaConsumableChip(view, row) {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'arena-consumable';
  button.dataset.itemId = row.item_id;
  button.dataset.targetMode = row.target_mode;
  if (row.element) button.classList.add(`an-el-${row.element}`);
  const state = arenaConsumableDisabledState(view, row);
  button.disabled = state.disabled;
  if (state.reason) button.title = state.reason;
  if (arenaConsumableTargeting?.item_id === row.item_id) button.dataset.armed = 'true';
  const name = document.createElement('span');
  name.className = 'arena-consumable-name';
  name.textContent = row.name;
  const summary = document.createElement('span');
  summary.className = 'arena-consumable-summary';
  summary.textContent = dungeonConsumableSummaryText(row);
  const qty = document.createElement('span');
  qty.className = 'arena-consumable-qty';
  qty.textContent = `×${row.quantity}`;
  button.append(name, summary, qty);
  if (state.disabled && state.note) {
    const note = document.createElement('span');
    note.className = 'arena-consumable-note';
    note.textContent = state.note;
    button.append(note);
  }
  button.addEventListener('click', () => { try { onArenaConsumableClick(view, row); } catch (error) { reportError(error); } });
  return button;
}

// A chip click resolves the row's target_mode. auto fires at once; aim arms board targeting; ally / revive open
// an actor_id pick over the player's team (living for heal/MP, downed for revive) — the arena generalization of
// the dungeon's player/companion vocabulary to the all-visible board.
function onArenaConsumableClick(view, row) {
  if (arenaActionInFlight) { showProcessingToast(); return; }
  if (arenaConsumableTargeting?.item_id === row.item_id) { cancelArenaConsumableTargeting(); return; }
  cancelArenaConsumableTargeting();
  if (row.target_mode === 'auto') { useArenaConsumable(row.item_id); return; }
  if (row.target_mode === 'aim') { enterArenaAimMode(view, row); return; }
  if (row.target_mode === 'ally') { openArenaAllyTargetPrompt(view, row, { downed: false }); return; }
  if (row.target_mode === 'revive') { openArenaAllyTargetPrompt(view, row, { downed: true }); return; }
  throw new Error(`unknown consumable target_mode: ${JSON.stringify(row.target_mode)}`);
}

function useArenaConsumable(itemId, extra = {}) {
  teardownArenaConsumableTargeting();
  arenaDo({ type: 'use_consumable', item_id: itemId, ...extra }).catch(reportError);
}

// heal / MP / revive pick: the target is an actor_id from the player's team (living for heal/MP, downed for
// revive). The pick sends target:<actor_id>.
function openArenaAllyTargetPrompt(view, row, { downed }) {
  arenaConsumableTargeting = { item_id: row.item_id, mode: downed ? 'revive' : 'ally', name: row.name };
  const targets = downed ? arenaDownedTeammates(view) : arenaLivingTeammates(view);
  const actions = targets.map((actor) => ({
    label: actor.name,
    onClick: () => useArenaConsumable(row.item_id, { target: actor.actor_id })
  }));
  showArenaConsumablePrompt(row.name, actions);
  renderArenaConsumables(view);
}

// ----- attack_area aim mode (all-visible board: in-bounds + floor + line of sight, no fog gate) -----

function enterArenaAimMode(view, row) {
  arenaConsumableTargeting = { item_id: row.item_id, mode: 'aim', radius: row.radius, element: row.element, name: row.name };
  buildArenaAimOverlay(view, row);
  document.querySelector('#arena-grid')?.classList.add('an-aiming');
  showArenaConsumablePrompt(row.name, []);
  renderArenaConsumables(view);
}

// Mirrors the engine's line-of-sight walk (arenaEngine.hasLineOfSight): the rounded cells strictly between the
// player and the target must all be floor. Kept identical so the client pre-filter matches the server's aim gate.
function arenaHasLineOfSight(view, from, to) {
  const dx = to.x - from.x;
  const dy = to.y - from.y;
  const steps = Math.max(Math.abs(dx), Math.abs(dy));
  for (let step = 1; step < steps; step += 1) {
    const x = Math.round(from.x + (dx * step) / steps);
    const y = Math.round(from.y + (dy * step) / steps);
    if (x < 0 || y < 0 || x >= view.width || y >= view.height || view.tiles[y][x] !== 'floor') return false;
  }
  return true;
}

function arenaAimTileValid(view, x, y) {
  if (x < 0 || y < 0 || x >= view.width || y >= view.height) return false;
  if (view.tiles[y][x] !== 'floor') return false;
  const player = view.actors.find((actor) => actor.actor_id === view.player_actor_id);
  if (!player) return false;
  return arenaHasLineOfSight(view, player, { x, y });
}

function buildArenaAimOverlay(view, row) {
  const board = document.querySelector('#arena-grid .an-board');
  if (!board) return;
  document.querySelector('#arena-grid .an-aim')?.remove();
  const layer = document.createElement('div');
  layer.className = 'an-aim';
  layer.style.setProperty('--an-cols', view.width);
  layer.style.setProperty('--an-rows', view.height);
  const cells = [];
  for (let y = 0; y < view.height; y += 1) {
    for (let x = 0; x < view.width; x += 1) {
      const cell = document.createElement('div');
      cell.className = 'an-aim-cell';
      cell.dataset.x = x;
      cell.dataset.y = y;
      if (arenaAimTileValid(view, x, y)) cell.classList.add('an-aim-valid');
      cells.push(cell);
    }
  }
  layer.replaceChildren(...cells);
  layer.addEventListener('pointermove', (event) => onArenaAimHover(event, row));
  layer.addEventListener('pointerleave', () => clearArenaAimBlast());
  layer.addEventListener('click', (event) => { try { onArenaAimClick(event, row); } catch (error) { reportError(error); } });
  board.append(layer);
}

function onArenaAimHover(event, row) {
  const cell = event.target.closest('.an-aim-cell');
  if (!cell || !cell.classList.contains('an-aim-valid')) { clearArenaAimBlast(); return; }
  paintArenaAimBlast(row, Number(cell.dataset.x), Number(cell.dataset.y));
}

function paintArenaAimBlast(row, cx, cy) {
  clearArenaAimBlast();
  const layer = document.querySelector('#arena-grid .an-aim');
  if (!layer) return;
  for (const cell of layer.querySelectorAll('.an-aim-cell')) {
    const distance = Math.abs(Number(cell.dataset.x) - cx) + Math.abs(Number(cell.dataset.y) - cy);
    if (distance <= row.radius) cell.classList.add('an-aim-blast');
  }
}

function clearArenaAimBlast() {
  const layer = document.querySelector('#arena-grid .an-aim');
  if (!layer) return;
  for (const cell of layer.querySelectorAll('.an-aim-blast')) cell.classList.remove('an-aim-blast');
}

function onArenaAimClick(event, row) {
  if (arenaActionInFlight) return;
  const cell = event.target.closest('.an-aim-cell');
  if (!cell || !cell.classList.contains('an-aim-valid')) return;
  useArenaConsumable(row.item_id, { aim: { x: Number(cell.dataset.x), y: Number(cell.dataset.y) } });
}

// 狙い・相手選びの間、盤の上に浮かぶ口: 使う品の名・相手の名の釦（相手選びのとき）・やめる紋。問いかけの字は置かない。
function showArenaConsumablePrompt(itemName, actions) {
  const prompt = document.querySelector('#arena-consumable-prompt');
  if (!prompt) return;
  const message = document.createElement('span');
  message.className = 'arena-consumable-prompt-text';
  message.textContent = itemName;
  const actionRow = document.createElement('span');
  actionRow.className = 'arena-consumable-prompt-actions';
  for (const action of actions) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'arena-consumable-prompt-action';
    button.textContent = action.label;
    if (action.disabled) button.disabled = true;
    if (action.title) button.title = action.title;
    button.addEventListener('click', () => { try { action.onClick(); } catch (error) { reportError(error); } });
    actionRow.append(button);
  }
  actionRow.append(venueSigilButton('cancel', '中止', () => cancelArenaConsumableTargeting(), 'arena-consumable-prompt-cancel'));
  prompt.replaceChildren(message, actionRow);
  prompt.hidden = false;
}

function teardownArenaConsumableTargeting() {
  arenaConsumableTargeting = null;
  document.querySelector('#arena-grid .an-aim')?.remove();
  document.querySelector('#arena-grid')?.classList.remove('an-aiming');
  const prompt = document.querySelector('#arena-consumable-prompt');
  if (prompt) { prompt.hidden = true; prompt.replaceChildren(); }
}

function cancelArenaConsumableTargeting() {
  const wasTargeting = arenaConsumableTargeting !== null;
  teardownArenaConsumableTargeting();
  if (wasTargeting && currentArenaMatchView) renderArenaConsumables(currentArenaMatchView);
}

// ----- student-face resolution + character-detail (name click) -----

// The face image for a student unit's board token. A homunculus is not in the selectable roster, so it uses the
// enriched actor.face_url (the arena view carries it — see arenaSession); a character resolves its visual set from
// the selectable roster by actor_id (= character_id), exactly like the dungeon ally token. Unresolvable identity
// throws (roster desync / missing face_url) — no silent default-icon fallback. The protagonist never reaches here.
function arenaActorFaceUrl(actor) {
  if (actor.kind === 'homunculus') {
    if (typeof actor.face_url !== 'string' || !actor.face_url) {
      throw new Error(`arena homunculus actor is missing face_url: ${actor.actor_id}`);
    }
    return actor.face_url;
  }
  const character = (selectableCharacters ?? []).find((entry) => entry.character_id === actor.actor_id);
  if (!character) throw new Error(`arena actor not found in character roster: ${actor.actor_id}`);
  const visualSetId = character.visual_set_id;
  if (!visualSetId) throw new Error(`arena actor is missing visual_set_id: ${actor.actor_id}`);
  return `/canonical/character_visual_sets/${visualSetId}/face_emotions/neutral.jpg`;
}

// A clickable actor name (the match HUD) — every actor (protagonist included) opens its detail via
// openArenaActorDetail, surfaced through reportArenaScreenError.
function arenaNameButton(actor) {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'arena-name-button interaction-name-button';
  button.textContent = actor.name;
  button.addEventListener('click', () => { try { openArenaActorDetail(actor); } catch (error) { reportArenaScreenError(error); } });
  return button;
}

// Opens an actor's detail in the unified actor-detail shell (arena token scope): the same section grammar as the
// dungeon (image / 能力値 / 装備 — no 獲得予定 in the arena). The protagonist has no image; a roster character shows
// its scene standee; a homunculus shows its enriched face. The 能力値 + 装備 read the projection's entry-snapshot
// values (actor.parameters / actor.equipment — snapshot strict, no roster / current-world re-resolve). A roster
// miss (image resolution) is a real desync → throw; the equipment contract is validated before the DOM is touched.
function openArenaActorDetail(actor) {
  const body = buildActorDetailBody({
    imageNode: arenaActorDetailImage(actor),
    parameterNodes: buildParameterGroups(actor.parameters, parameterTextLabel),
    equipmentNode: buildArenaDetailEquipment(actor.equipment ?? null),
    acquisitionNode: null
  });
  openArenaActorDetailShell(actor.name, body);
}

// The detail image slot: none for the protagonist, the scene standee (portrait) for a roster character (resolved
// from the roster by actor_id — a miss is a desync → throw), the enriched face (1:1) for a homunculus.
function arenaActorDetailImage(actor) {
  if (actor.kind === 'protagonist') return null;
  if (actor.kind === 'homunculus') {
    return buildActorDetailImage({ src: actor.face_url, alt: `${actor.name}の顔`, shape: 'face' });
  }
  const character = (selectableCharacters ?? []).find((item) => item.character_id === actor.actor_id);
  if (!character) throw new Error(`arena actor not found in character roster: ${actor.actor_id}`);
  return buildActorDetailImage({
    src: characterSceneStandeeUrl(character),
    alt: `${character.display_name ?? character.character_id}の一枚絵`,
    shape: 'standee'
  });
}

// The arena read-only equipment section: weapon + amulet slots (shared .actor-detail-equipment* grammar), each an
// equipped-instance detail (arena-scoped card — NO 解除 button) or a quiet 未装備 note. runEquipment is the
// entry-snapshot run-equipment (null when nothing is equipped, else {slots:{weapon,amulet}, effects}); its slots
// are validated fail-fast (a malformed slot throws before the DOM is touched).
function buildArenaDetailEquipment(runEquipment) {
  const slots = runEquipment === null
    ? { weapon: null, amulet: null }
    : validateDungeonEquipmentSlots(runEquipment.slots, 'arena detail equipment');
  const wrap = document.createElement('div');
  wrap.className = 'actor-detail-equipment';
  for (const slot of WORKSHOP_EQUIPMENT_KINDS) {
    const card = document.createElement('div');
    card.className = 'actor-detail-equipment-slot';
    card.dataset.slot = slot;
    const head = document.createElement('p');
    head.className = 'actor-detail-equipment-slot-head';
    head.textContent = `${workshopKindLabel(slot)}スロット`;
    card.append(head);
    const view = slots[slot];
    if (view) {
      card.append(buildArenaEquipmentInstanceDetail(view));
    } else {
      const empty = document.createElement('p');
      empty.className = 'actor-detail-equipment-empty';
      empty.textContent = '未装備';
      card.append(empty);
    }
    wrap.append(card);
  }
  return wrap;
}

// One equipped-instance card (arena-scoped): name + identity meta (shared vocab via dungeonEquipmentInstanceMetaText)
// + the base / bonus effect rows. The arena classes carry the crimson token layer; the shape mirrors the dungeon
// instance card so both detail shells read the same.
function buildArenaEquipmentInstanceDetail(view) {
  const { instance, baseEffects, bonusEffects } = view;
  const detail = document.createElement('div');
  detail.className = 'arena-equipment-instance';
  detail.dataset.element = instance.element;
  const name = document.createElement('p');
  name.className = 'arena-equipment-instance-name';
  name.textContent = instance.name;
  const meta = document.createElement('p');
  meta.className = 'arena-equipment-instance-meta';
  meta.textContent = dungeonEquipmentInstanceMetaText(instance);
  const effects = document.createElement('div');
  effects.className = 'arena-equipment-instance-effects';
  effects.append(
    buildArenaEquipmentEffectRow('基礎性能', baseEffects),
    buildArenaEquipmentEffectRow('付加性能', bonusEffects)
  );
  detail.append(name, meta, effects);
  return detail;
}

function buildArenaEquipmentEffectRow(label, entries) {
  const row = document.createElement('div');
  row.className = 'arena-equipment-effect-row';
  const rowLabel = document.createElement('span');
  rowLabel.className = 'arena-equipment-effect-label';
  rowLabel.textContent = label;
  const chips = document.createElement('span');
  chips.className = 'arena-equipment-effect-chips';
  if (entries.length === 0) {
    const none = document.createElement('span');
    none.className = 'arena-equipment-effect-none';
    none.textContent = 'なし';
    chips.append(none);
  } else {
    for (const entry of entries) {
      const chip = document.createElement('span');
      chip.className = 'arena-equipment-effect';
      chip.textContent = `${entry.label}+${entry.value}`;
      chips.append(chip);
    }
  }
  row.append(rowLabel, chips);
  return row;
}

// Opens the unified actor-detail shell for the arena. The body is built (validating the equipment contract) BEFORE
// the shell is shown, so a broken contract throws without leaving a half-open dialog. Missing markup is broken
// wiring — fail fast.
function openArenaActorDetailShell(title, bodyNode) {
  const popup = document.querySelector('#arena-actor-detail');
  const titleEl = document.querySelector('#arena-actor-detail-title');
  const body = document.querySelector('#arena-actor-detail-body');
  if (!popup || !titleEl || !body) {
    throw new Error('arena actor detail shell nodes are missing (broken markup wiring)');
  }
  titleEl.textContent = title;
  body.replaceChildren(bodyNode);
  popup.hidden = false;
}

function closeArenaActorDetail() {
  const popup = document.querySelector('#arena-actor-detail');
  if (!popup) throw new Error('arena actor detail shell node #arena-actor-detail is missing (broken markup wiring)');
  popup.hidden = true;
}

// ----- board renderer (arena-scoped; fixed all-visible board, no camera) -----

function arenaTokenEl({ roleClass, elementClass = '', imageUrl = null, glyph = '', label = '' }) {
  const token = document.createElement('div');
  token.className = ['an-token', roleClass, elementClass].filter(Boolean).join(' ');
  if (label) token.title = label;
  const inner = document.createElement('div');
  inner.className = 'an-token-inner';
  // A student unit (roster character / homunculus) wears its face image like the dungeon ally token; the
  // protagonist has no imageUrl and keeps the faceless emblem glyph. A broken image URL surfaces the glyph.
  if (imageUrl) {
    const img = document.createElement('img');
    img.className = 'an-token-img';
    img.alt = '';
    img.src = imageUrl;
    img.addEventListener('error', () => {
      img.remove();
      const fallback = document.createElement('span');
      fallback.className = 'an-token-glyph';
      fallback.textContent = glyph;
      inner.append(fallback);
    });
    inner.append(img);
  } else {
    const glyphEl = document.createElement('span');
    glyphEl.className = 'an-token-glyph';
    glyphEl.textContent = glyph;
    inner.append(glyphEl);
  }
  token.append(inner, arenaGaugeEl('an-token-hp'));
  return token;
}

// Tokens are reused by actor id like the dungeon's: built once (the token over its foot ring), then only the slide (transform),
// the HP gauge, the ring and the fallen state move.
function upsertArenaEntity(overlay, key, actor, side, build) {
  arenaEntityTiles.set(key, { x: actor.x, y: actor.y });
  const transform = `translate(calc((var(--an-cell) + var(--an-gap)) * ${actor.x}), calc((var(--an-cell) + var(--an-gap)) * ${actor.y}))`;
  let node = arenaEntityNodes.get(key);
  if (!node) {
    node = document.createElement('div');
    node.className = `an-entity an-entity--${side}`;
    node.style.transform = transform;
    const ring = document.createElement('span');
    ring.className = 'an-foot';
    ring.dataset.ring = 'off';
    ring.setAttribute('aria-hidden', 'true');
    node.append(build(), ring);
    arenaEntityNodes.set(key, node);
    overlay.append(node);
  }
  node.style.transform = transform;
  setCombatGauge(node.querySelector('.an-token-hp'), actor.hp, actor.max_hp);
}

function renderArenaBoard(view) {
  const grid = document.querySelector('#arena-grid');
  let board = grid.querySelector('.an-board');
  if (!board) {
    const viewport = document.createElement('div');
    viewport.className = 'an-viewport';
    board = document.createElement('div');
    board.className = 'an-board';
    const tilesLayer = document.createElement('div');
    tilesLayer.className = 'an-tiles';
    const entitiesLayer = document.createElement('div');
    entitiesLayer.className = 'an-entities';
    const effectsLayer = document.createElement('div');
    effectsLayer.className = 'an-effects';
    board.append(tilesLayer, entitiesLayer, effectsLayer);
    viewport.append(board);
    grid.replaceChildren(viewport);
  }
  const tiles = board.querySelector('.an-tiles');
  const overlay = board.querySelector('.an-entities');

  const friendly = arenaFriendlyTeam(view);
  // A new match is a fresh board: drop the persistent entity nodes so each re-mounts at its position instead of
  // sliding in from a prior match's layout.
  const freshBoard = view.match_id !== arenaBoardSignature;
  // Every actor stays on the board. One that goes down is drawn fallen (grey and sunk) — at its fall in the board flow
  // (sinkArenaActor), or at once when the board is fresh — and stays there as the revive target.
  // Resolve every on-board token (side + face image / emblem glyph) BEFORE mutating any board DOM, so an
  // unresolvable student face (roster desync / missing homunculus face_url) throws without leaving a
  // half-painted board. The protagonist stays a faceless emblem; students wear their face like the dungeon ally.
  const tokenSpecs = view.actors.map((actor) => {
    let side;
    let glyph;
    let imageUrl = null;
    if (actor.kind === 'protagonist') { side = 'self'; glyph = '★'; }
    else {
      if (arenaReplay?.heroActorIds?.has(actor.actor_id)) side = 'self'; // 観戦のバディー: 主人公の金の輪
      else side = (friendly !== null ? actor.team === friendly : actor.team === 'a') ? 'ally' : 'enemy';
      glyph = '◆';
      imageUrl = arenaActorFaceUrl(actor);
    }
    return { actor, side, glyph, imageUrl };
  });

  tiles.style.setProperty('--an-cols', view.width);
  tiles.style.setProperty('--an-rows', view.height);

  if (freshBoard) {
    arenaBoardSignature = view.match_id;
    arenaEntityNodes.clear();
    arenaEntityTiles.clear();
    overlay.replaceChildren();
    arenaSunk = new Set(view.actors.filter((actor) => actor.down).map((actor) => actor.actor_id));
    resetArenaBoardFlow();
  }

  // A wall on the board's edge is the enclosing ring (an-rim): it keeps its grid place but is not drawn, so only the
  // floor and the pillars inside it show over the venue art.
  const cells = [];
  for (let y = 0; y < view.height; y += 1) {
    for (let x = 0; x < view.width; x += 1) {
      const edge = x === 0 || y === 0 || x === view.width - 1 || y === view.height - 1;
      const cell = document.createElement('div');
      cell.className = `an-cell ${view.tiles[y][x] === 'floor' ? 'an-floor' : edge ? 'an-rim' : 'an-wall'}`;
      cells.push(cell);
    }
  }
  tiles.replaceChildren(...cells);

  for (const { actor, side, glyph, imageUrl } of tokenSpecs) {
    upsertArenaEntity(overlay, `actor:${actor.actor_id}`, actor, side,
      () => arenaTokenEl({ roleClass: `an-token--${side}`, elementClass: `an-token--el-${actor.element}`, imageUrl, glyph,
        label: `${actor.name}（${DUNGEON_MAGIC_LABELS[actor.element] ?? actor.element}）` }));
    // A revived actor stands again; one already sunk stays sunk (a fresh fall waits for its moment in the flow).
    if (!actor.down) { arenaSunk.delete(actor.actor_id); arenaEntityNode(actor.actor_id).classList.remove('an-entity--down'); }
    else if (arenaSunk.has(actor.actor_id)) arenaEntityNode(actor.actor_id).classList.add('an-entity--down');
  }
  layoutArenaBoard(view);
}

// The arena board shows every tile at once (no fog / no camera), so layout is a single fit: the largest cell
// that fits the whole 11×9 board in the stage on both axes. The result is FROZEN per window size (arenaCellLock)
// so a content-driven stage resize — the dock / item / prompt / replay regions coming and going as the match
// state changes, most sharply at 決着 — reuses the frozen scale instead of rezooming the board (which would warp
// an in-flight combat trajectory). Only a real window resize recomputes. Because the first fit runs under the
// interactive (dock+items present) layout, the frozen cell already fits when those regions are shown, so hiding
// them later never overflows. A viewport not yet sized bails (the ResizeObserver re-runs after layout).
function layoutArenaBoard(view) {
  const grid = document.querySelector('#arena-grid');
  if (!grid) return;
  const win = { w: window.innerWidth, h: window.innerHeight };
  if (arenaCellLock !== null && arenaCellLockWindow && arenaCellLockWindow.w === win.w && arenaCellLockWindow.h === win.h) {
    grid.style.setProperty('--an-cell', `${arenaCellLock}px`);
    return;
  }
  const viewport = grid.querySelector('.an-viewport');
  if (!viewport) return;
  const availW = viewport.clientWidth;
  const availH = viewport.clientHeight;
  if (availW === 0 || availH === 0) return;
  const gap = parseFloat(getComputedStyle(grid).getPropertyValue('--an-gap'));
  if (!Number.isFinite(gap)) throw new Error('arena: --an-gap must resolve to a length');
  const cellW = (availW - gap * (view.width - 1)) / view.width;
  const cellH = (availH - gap * (view.height - 1)) / view.height;
  const cell = Math.max(1, Math.floor(Math.min(cellW, cellH)));
  arenaCellLock = cell;
  arenaCellLockWindow = win;
  grid.style.setProperty('--an-cell', `${cell}px`);
}

// ----- combat effects (the dungeon's painters and values over the arena board) -----

// The arena stage for playCombatEvents: the board's effect layer, the stage's red edge, and positions read from where a
// token is drawn right now (mid-slide included) like the dungeon's, else the tile's centre. flightMs is how long a bolt flies.
function arenaCombatStage(flightMs) {
  const grid = document.querySelector('#arena-grid');
  const board = grid.querySelector('.an-board');
  const style = getComputedStyle(grid);
  const cell = parseFloat(style.getPropertyValue('--an-cell'));
  const gap = parseFloat(style.getPropertyValue('--an-gap'));
  if (!Number.isFinite(cell) || !Number.isFinite(gap)) throw new Error('arena: --an-cell and --an-gap must resolve to lengths');
  const step = cell + gap;
  // A standing token wins its tile over a fallen one left on the same tile.
  const tokenAt = (x, y) => {
    let fallen = null;
    for (const [key, tile] of arenaEntityTiles) {
      if (tile.x !== x || tile.y !== y) continue;
      const node = arenaEntityNodes.get(key);
      if (!node.classList.contains('an-entity--down')) return node;
      fallen = node;
    }
    return fallen;
  };
  return {
    prefix: 'an',
    fx: arenaFx,
    layer: board.querySelector('.an-effects'),
    hurt: document.querySelector('#arena-hurt'),
    cell,
    flightMs,
    reduced: dungeonReducedMotion,
    tileCenter: (x, y) => {
      const node = tokenAt(x, y);
      if (!node) return { x: x * step + cell / 2, y: y * step + cell / 2 };
      const r = node.getBoundingClientRect();
      const b = board.getBoundingClientRect();
      return { x: (r.left + r.width / 2) - b.left, y: (r.top + r.height / 2) - b.top };
    },
    tokenAt
  };
}

// One turn's events as beats: a strike carries its own damage and crit, and lands on the player when it lands on the tile of the
// protagonist under the player's control (never in a replay: no player there).
function playArenaEvents(view, events, flightMs) {
  if (!events.length) return;
  const player = view.actors.find((actor) => actor.controller === 'player');
  playCombatEvents(arenaCombatStage(flightMs), events.map((event) => {
    if (!COMBAT_STRIKE_KINDS.has(event.kind)) return { event };
    return {
      event,
      damage: event.hit ? event.damage : null,
      onPlayer: Boolean(player) && event.to.x === player.x && event.to.y === player.y,
      crit: event.crit
    };
  }));
}

// A replay step's bolt flight: a fast step flies its bolts sooner so a miss stays in view at least missHoldMs before the next
// step folds it.
function arenaReplayFlightMs() {
  return Math.min(COMBAT_FX.boltMs, arenaReplayStepMs() - COMBAT_FX.missHoldMs);
}

// Folds every effect in flight and settles the board flow in progress to its end state.
function foldArenaEffects() {
  arenaFx.fold();
  document.querySelector('#arena-grid .an-effects')?.replaceChildren();
  document.querySelector('#arena-hurt').classList.remove('is-hurt');
  const flow = arenaFlow;
  arenaFlow = null;
  flow?.settle();
}

// ----- the board flow: 入り・番の受け渡し・決着 -----

function arenaEntityNode(actorId) {
  return arenaEntityNodes.get(`actor:${actorId}`) ?? null;
}

function setArenaRing(actorId, state) {
  const ring = arenaEntityNode(actorId)?.querySelector('.an-foot');
  if (ring) ring.dataset.ring = state;
}

// The turn ring and the lit HUD name move to actorId (null = nobody holds the turn).
function setArenaTurn(actorId) {
  if (arenaTurnActorId !== null && arenaTurnActorId !== actorId) {
    setArenaRing(arenaTurnActorId, 'off');
    arenaHud?.cards.get(arenaTurnActorId)?.card.classList.remove('an-hud-actor--turn');
  }
  arenaTurnActorId = actorId;
  if (actorId === null) return;
  setArenaRing(actorId, 'turn');
  arenaHud?.cards.get(actorId)?.card.classList.add('an-hud-actor--turn');
}

function sinkArenaActor(actorId) {
  arenaSunk.add(actorId);
  arenaEntityNode(actorId)?.classList.add('an-entity--down');
}

// A fresh board starts with no turn ring, no venue light, no mark and the spell dock up.
function resetArenaBoardFlow() {
  arenaTurnActorId = null;
  const mark = document.querySelector('#arena-mark');
  mark.classList.remove('is-shown');
  mark.removeAttribute('data-outcome');
  mark.textContent = '';
  document.querySelector('#arena-venue').removeAttribute('data-venue');
  document.querySelector('#arena-match').removeAttribute('data-flow');
  document.querySelector('#arena-dock-main').classList.remove('is-flowing');
}

// An actor waiting to enter: its token is not shown and its gauges (token and HUD) are empty at once — dropping the gauge's
// last value makes the empty a first paint, so the lag does not trail down from full.
function emptyArenaActor(actor) {
  const node = arenaEntityNode(actor.actor_id);
  node.classList.add('an-entity--waiting');
  const empty = (gauge, max) => { delete gauge.dataset.pct; setCombatGauge(gauge, 0, max); };
  empty(node.querySelector('.an-token-hp'), actor.max_hp);
  const entry = arenaHud.cards.get(actor.actor_id);
  for (const [bar, max] of [[entry.hp, actor.max_hp], [entry.mp, actor.max_mp]]) {
    empty(bar.track, max);
    bar.value.textContent = '';
  }
}

// The actor rises from its ring (from the dark and from a little below, like a dungeon token appearing) and its gauges fill.
function riseArenaActor(actor, { animate }) {
  const node = arenaEntityNode(actor.actor_id);
  if (!node) return;
  node.classList.remove('an-entity--waiting');
  if (animate) {
    arenaFx.animate(node.firstChild, [
      { opacity: 0, filter: 'brightness(0.3)', transform: 'translateY(14%)' },
      { opacity: 1, filter: 'brightness(1)', transform: 'translateY(0)' }
    ], { duration: ARENA_ENTRANCE_MS.rise, easing: 'ease-out' });
  }
  setCombatGauge(node.querySelector('.an-token-hp'), actor.hp, actor.max_hp);
  const entry = arenaHud?.cards.get(actor.actor_id);
  if (entry) updateArenaActorCard(entry, actor);
}

// 入り: 盤だけが開き（会場の沈みが一段深く・目盛りは空）、相手の側→自陣の側の順に足もとの輪が開いて、その輪から駒が立ち目盛りが
// 満ちる。終わりに輪がほどけ、会場が試合の濃さへ明け、口上と（主人公の試合なら）呪文の欄が出て、主人公の足もとに番の輪が残る。
function playArenaEntrance(view) {
  const match = document.querySelector('#arena-match');
  const venue = document.querySelector('#arena-venue');
  const dock = document.querySelector('#arena-dock-main');
  // 主人公のいない試合（見返し）は team a が近い側。主人公の試合で主人公の組が解けないのは壊れた view なので止める。
  const near = Object.hasOwn(view, 'player_actor_id') ? arenaFriendlyTeam(view) : 'a';
  if (near === null) throw new Error(`arena entrance: no player-controlled actor in match ${view.match_id}`);
  const sides = [view.actors.filter((actor) => actor.team !== near), view.actors.filter((actor) => actor.team === near)];
  const settle = () => {
    match.removeAttribute('data-flow');
    venue.removeAttribute('data-venue');
    dock.classList.remove('is-flowing');
    for (const actor of view.actors) {
      riseArenaActor(actor, { animate: false });
      setArenaRing(actor.actor_id, 'off');
    }
    setArenaTurn(view.player_actor_id ?? null);
  };
  if (dungeonReducedMotion()) { settle(); return; }
  match.dataset.flow = 'entering';
  venue.dataset.venue = 'entering';
  dock.classList.add('is-flowing');
  for (const actor of view.actors) emptyArenaActor(actor);
  sides.forEach((side, index) => {
    const ringAt = ARENA_ENTRANCE_MS.firstRing + index * ARENA_ENTRANCE_MS.ring;
    arenaFx.later(ringAt, () => { for (const actor of side) setArenaRing(actor.actor_id, 'open'); });
    arenaFx.later(ringAt + ARENA_ENTRANCE_MS.ring, () => { for (const actor of side) riseArenaActor(actor, { animate: true }); });
  });
  const flow = { settle };
  arenaFlow = flow;
  arenaFx.later(ARENA_ENTRANCE_MS.settle, () => {
    if (arenaFlow === flow) arenaFlow = null;
    settle();
  });
}

// One response's turns, in order: the events (strikes, heals, revives) split by the fighter whose turn made them (an event's `from`
// is its maker's tile — where it stands after the response, or where it stood before it when it moved on a later turn of the same
// response), then the fighters that only moved. The player's turn leads when it made no event.
function arenaExchangeTurns(previous, view, events) {
  const before = new Map(previous.actors.map((actor) => [actor.actor_id, actor]));
  const standing = view.actors.filter((actor) => !before.get(actor.actor_id).down);
  const on = (tile, actor) => actor.x === tile.x && actor.y === tile.y;
  const turns = [];
  for (const event of events) {
    const owner = standing.find((actor) => on(event.from, actor)) ?? standing.find((actor) => on(event.from, before.get(actor.actor_id)));
    if (!owner) throw new Error(`arena event from ${event.from.x},${event.from.y} matches no standing fighter`);
    if (turns.at(-1)?.actorId === owner.actor_id) turns.at(-1).events.push(event);
    else turns.push({ actorId: owner.actor_id, events: [event] });
  }
  const player = view.actors.find((actor) => actor.controller === 'player') ?? null;
  if (player && !turns.some((turn) => turn.actorId === player.actor_id)) turns.unshift({ actorId: player.actor_id, events: [] });
  for (const actor of standing) {
    if (turns.some((turn) => turn.actorId === actor.actor_id)) continue;
    const was = before.get(actor.actor_id);
    if (actor.x !== was.x || actor.y !== was.y) turns.push({ actorId: actor.actor_id, events: [] });
  }
  return turns;
}

// How the player's match ended, seen from the player's side: the venue light swells on a win and sinks on a loss, and the mark is
// 勝ち上がり / 優勝 (the win that concludes the tournament) / 敗退.
function arenaPlayerEnding(view, tournament) {
  const friendly = arenaFriendlyTeam(view);
  if (friendly === null) throw new Error(`arena ending: no player-controlled actor in match ${view.match_id}`);
  const won = view.winner === friendly;
  return { winner: view.winner, light: won ? 'swell' : 'sink', outcome: won ? (tournament.terminal ? 'champion' : 'advance') : 'eliminated' };
}

// A replayed match (no protagonist in it) ends from the winner's side: the light swells and the mark is 勝ち上がり, 優勝 in the final.
// 観戦のバディーの試合は、バディーの側から読む（勝てば灯がふくらみ 勝ち上がり／優勝、負ければ灯が沈み 敗退）。勝ち負けはどの試合も
// 表と同じ見返しの winner_unit_id で読む（三百の回りで打ち切られた試合は、最後の手の view に勝者が載らない）。
function arenaReplayEnding(matchId) {
  const match = currentArenaState.bracket.rounds.flat().find((candidate) => candidate.match_id === matchId);
  if (!match) throw new Error(`arena ending: replay match ${matchId} is not in the bracket`);
  const { winnerUnitId } = arenaReplay;
  if (winnerUnitId !== match.team_a_unit_id && winnerUnitId !== match.team_b_unit_id) {
    throw new Error(`arena ending: replay winner ${winnerUnitId} is not a side of match ${matchId}`);
  }
  const side = winnerUnitId === match.team_a_unit_id ? 'a' : 'b';
  const winner = arenaReplay.mirrored ? (side === 'a' ? 'b' : 'a') : side;
  const final = currentArenaState.bracket.rounds.at(-1).includes(match);
  const won = !arenaReplay.heroActorIds || winnerUnitId === currentArenaState.player_unit_id;
  return { winner, light: won ? 'swell' : 'sink', outcome: won ? (final ? 'champion' : 'advance') : 'eliminated' };
}

// 決める一撃: 着弾がひとまわり大きく、盤が一瞬白む。
function strikeArenaDecisive(event) {
  if (dungeonReducedMotion()) return;
  const stage = arenaCombatStage(COMBAT_FX.boltMs);
  spawnCombatImpact({ ...stage, cell: stage.cell * ARENA_DECISIVE_IMPACT_SCALE }, event, stage.tileCenter(event.to.x, event.to.y));
  const flash = document.createElement('div');
  flash.className = 'an-flash';
  stage.layer.append(flash);
  arenaFx.animate(flash, [{ opacity: 0 }, { opacity: 0.5, offset: 0.25 }, { opacity: 0 }], { duration: ARENA_DECISIVE_MS.flash, easing: 'ease-out' }, () => flash.remove());
}

// 会場の灯と、勝った側の立っている者の足もとに大きく開く輪。
function lightArenaEnding(view, ending) {
  setArenaTurn(null);
  for (const actor of view.actors) if (actor.team === ending.winner && !actor.down) setArenaRing(actor.actor_id, 'wide');
  document.querySelector('#arena-venue').dataset.venue = ending.light;
}

function markArenaEnding(ending) {
  const mark = document.querySelector('#arena-mark');
  mark.dataset.outcome = ending.outcome;
  mark.textContent = ARENA_MARK_LABELS[ending.outcome];
  mark.classList.add('is-shown');
}

// One response (slotted: the player's exchange) or one replay turn (not slotted: the ring jumps to the turn's fighter and the
// events play at once, with the bolts flying fast enough that a fast replay step never outruns a miss). A fighter downed in it sinks
// just after the strike that downs it lands; a fighter revived in it stays fallen until its revive plays. With an ending, the 決着
// follows the decisive strike (the last strike landing on a fighter downed in it); for the player's match the returned promise
// resolves when the 決着 has been held (or is folded), else null.
function playArenaFlow(previous, view, events, { slotted, ending }) {
  const reduced = dungeonReducedMotion();
  const dock = document.querySelector('#arena-dock-main');
  const player = view.actors.find((actor) => actor.actor_id === view.player_actor_id) ?? null;
  const falling = view.actors.filter((actor) => actor.down && !arenaSunk.has(actor.actor_id));
  const rising = [];
  const flightMs = slotted ? COMBAT_FX.boltMs : arenaReplayFlightMs();
  const fallAt = new Map();
  let decisive = null;
  let holder = arenaTurnActorId;
  let t = 0;
  for (const turn of arenaExchangeTurns(previous, view, events)) {
    let strikeAt = 0;
    if (slotted && !reduced) {
      const handoff = turn.actorId !== holder;
      if (handoff) {
        const at = t;
        arenaFx.later(at, () => setArenaTurn(null));
        arenaFx.later(at + ARENA_TURN_MS.handoff, () => setArenaTurn(turn.actorId));
      }
      strikeAt = t + (handoff ? ARENA_TURN_MS.strike : ARENA_TURN_MS.firstStrike);
      t += !turn.events.length ? ARENA_TURN_MS.quiet : handoff ? ARENA_TURN_MS.slot : ARENA_TURN_MS.first;
    } else {
      setArenaTurn(turn.actorId);
    }
    holder = turn.actorId;
    if (!turn.events.length) continue;
    turn.events.forEach((event, index) => {
      if (event.kind !== 'revive' || strikeAt === 0) return;
      const revived = view.actors.find((actor) => !actor.down && actor.x === event.to.x && actor.y === event.to.y);
      if (!revived) return;
      const node = arenaEntityNode(revived.actor_id);
      node.classList.add('an-entity--down');
      rising.push(node);
      arenaFx.later(strikeAt + combatStrikeDelayMs(index), () => node.classList.remove('an-entity--down'));
    });
    if (strikeAt === 0) playArenaEvents(view, turn.events, flightMs);
    else arenaFx.later(strikeAt, () => playArenaEvents(view, turn.events, flightMs));
    turn.events.forEach((event, index) => {
      if (!COMBAT_STRIKE_KINDS.has(event.kind) || !event.hit) return;
      const target = falling.find((actor) => actor.x === event.to.x && actor.y === event.to.y);
      if (!target) return;
      const land = strikeAt + (reduced ? 0 : combatStrikeDelayMs(index) + flightMs);
      fallAt.set(target.actor_id, land);
      if (!decisive || land >= decisive.at) decisive = { at: land, event };
    });
  }
  for (const actor of falling) {
    const at = (fallAt.get(actor.actor_id) ?? t) + ARENA_DECISIVE_MS.sinkAfter;
    arenaFx.later(at, () => sinkArenaActor(actor.actor_id));
  }
  const flow = { settle: null };
  const release = () => { if (arenaFlow === flow) arenaFlow = null; };
  arenaFlow = flow;

  if (!ending) {
    // The turn returns to the player: the ring hands back and the spell dock rises with its streak.
    const back = slotted && player && holder !== player.actor_id && !reduced;
    if (back) {
      arenaFx.later(t, () => setArenaTurn(null));
      arenaFx.later(t + ARENA_TURN_MS.handoff, () => setArenaTurn(player.actor_id));
    }
    const settleTurn = () => {
      for (const node of rising) node.classList.remove('an-entity--down');
      for (const actor of falling) sinkArenaActor(actor.actor_id);
      dock.classList.remove('is-flowing');
      setArenaTurn(slotted ? (player?.actor_id ?? null) : holder);
    };
    flow.settle = settleTurn;
    if (slotted && !reduced) {
      dock.classList.add('is-flowing');
      arenaFx.later(back ? t + 2 * ARENA_TURN_MS.handoff : t, () => {
        release();
        settleTurn();
        arenaFx.animate(document.querySelector('#arena-dock-streak'), [
          { opacity: 0, backgroundPosition: '-70% 0' },
          { opacity: 1, offset: 0.2 },
          { opacity: 0, backgroundPosition: '170% 0' }
        ], { duration: ARENA_TURN_MS.streak, easing: 'ease-out' });
      });
    } else if (reduced) {
      release();
      settleTurn();
    }
    // A replay turn keeps its flow until the next step folds it, so its falls still sink on their strikes.
    return null;
  }

  const t0 = decisive ? decisive.at : t;
  let finish = () => {};
  const decided = slotted ? new Promise((resolve) => { finish = resolve; }) : null;
  flow.settle = () => {
    for (const node of rising) node.classList.remove('an-entity--down');
    for (const actor of falling) sinkArenaActor(actor.actor_id);
    lightArenaEnding(view, ending);
    markArenaEnding(ending);
    finish();
  };
  if (decisive) arenaFx.later(t0, () => strikeArenaDecisive(decisive.event));
  arenaFx.later(t0 + ARENA_DECISIVE_MS.light, () => lightArenaEnding(view, ending));
  arenaFx.later(t0 + ARENA_DECISIVE_MS.mark, () => {
    markArenaEnding(ending);
    if (!slotted) release();
  });
  if (slotted) arenaFx.later(t0 + ARENA_DECISIVE_MS.hold, () => { release(); finish(); });
  return decided;
}

// 決着の後、盤が薄れる。畳まれたら（戻る紋・読み直し）その場で終わる。
function fadeArenaMatch() {
  if (dungeonReducedMotion()) return Promise.resolve();
  return new Promise((resolve) => {
    const flow = { settle: resolve };
    arenaFlow = flow;
    arenaFx.animate(document.querySelector('#arena-match'), [{ opacity: 1 }, { opacity: 0 }], { duration: ARENA_DECISIVE_MS.fade, easing: 'ease-in' }, () => {
      if (arenaFlow === flow) arenaFlow = null;
      resolve();
    });
  });
}

// ----- spectator replay -----

async function startArenaReplay(matchId) {
  if (arenaActionInFlight) { showProcessingToast(); return; }
  arenaActionInFlight = true;
  try {
    const payload = await getJson(`/api/arena/match/${encodeURIComponent(matchId)}/replay`);
    const replay = validateArenaReplay(payload);
    stopArenaReplay();
    // 観戦のバディーの試合は、バディーを主人公に見立てて自陣の側（左・team a の読み）に置き、足もとの輪を主人公の金にする。
    // 盤は左右対称なので、バディーが右（team b）の試合は画面の側で左右に映す。
    const hero = arenaReplayHero(currentArenaState, replay.match_id);
    const turns = hero?.side === 'b' ? replay.turns.map(arenaMirrorReplayTurn) : replay.turns;
    arenaReplay = { matchId: replay.match_id, winnerUnitId: replay.winner_unit_id, turns, index: 0, timer: null, seenEnd: turns.length === 1, heroActorIds: hero?.actorIds ?? null, mirrored: hero?.side === 'b' };
    renderArenaMatch(turns[0].view, currentArenaState, { replay: true });
    playArenaEntrance(turns[0].view);
    arenaShowMatchIntro(matchId); // the intro for the auto match being watched
    arenaScheduleReplayStep(dungeonReducedMotion() ? 0 : ARENA_ENTRANCE_MS.settle);
  } finally {
    arenaActionInFlight = false;
  }
}

// 観戦のバディーの試合の見返しで、主人公に見立てるバディーの側と actor id（観戦の大会でなければ・バディーの出ない試合なら null）。
function arenaReplayHero(view, matchId) {
  if (view?.mode !== 'spectate') return null;
  const match = view.bracket.rounds.flat().find((candidate) => candidate.match_id === matchId);
  if (!match) throw new Error(`arena: replay match ${matchId} is not in the bracket`);
  if (!arenaHeroMatch(view, match)) return null;
  const unit = view.units.find((candidate) => candidate.unit_id === view.player_unit_id);
  if (!unit) throw new Error(`arena: the buddy unit ${view.player_unit_id} is not in the tournament`);
  return { side: match.team_a_unit_id === view.player_unit_id ? 'a' : 'b', actorIds: new Set(unit.actors.map((actor) => actor.actor_id)) };
}

// 見返しの一手を左右に映す: 組（a ⇔ b）・勝ち負け・列（x → 幅 - 1 - x）・床・打ち合いの両端を入れ替える。
function arenaMirrorReplayTurn(turn) {
  const { view } = turn;
  const flip = (team) => (team === 'a' ? 'b' : 'a');
  const mx = (x) => view.width - 1 - x;
  const status = { active: 'active', a_won: 'b_won', b_won: 'a_won' }[view.status];
  if (!status) throw new Error(`arena: cannot mirror a replay turn with status ${JSON.stringify(view.status)}`);
  return {
    ...turn,
    view: {
      ...view,
      status,
      winner: view.winner === null ? null : flip(view.winner),
      tiles: view.tiles.map((row) => [...row].reverse()),
      actors: view.actors.map((actor) => ({ ...actor, team: flip(actor.team), x: mx(actor.x) }))
    },
    events: turn.events.map((event) => ({ ...event, from: { ...event.from, x: mx(event.from.x) }, to: { ...event.to, x: mx(event.to.x) } }))
  };
}

// The current auto-advance interval: the baseline divided by the selected speed. A speed change takes effect on the
// NEXT scheduled step (the in-flight timeout keeps its interval), matching 「次のターン送りから反映」.
function arenaReplayStepMs() {
  return ARENA_REPLAY_STEP_MS / ARENA_REPLAY_SPEED_DIVISORS[arenaReplaySpeed];
}

// The next step comes one interval after `afterMs` (the first step waits out the 入り).
function arenaScheduleReplayStep(afterMs = 0) {
  if (!arenaReplay || arenaReplay.index >= arenaReplay.turns.length - 1) return;
  arenaReplay.timer = window.setTimeout(() => arenaReplayAdvance(), afterMs + arenaReplayStepMs());
}

// One replay turn: the ring passes to the fighter whose turn it is and its strikes play; the last turn plays the 決着 from the
// winner's side and the replay stops on it.
function arenaReplayAdvance() {
  if (!arenaReplay || arenaReplay.index >= arenaReplay.turns.length - 1) return;
  const previous = arenaReplay.turns[arenaReplay.index].view;
  arenaReplay.index += 1;
  if (arenaReplay.index === arenaReplay.turns.length - 1) arenaReplay.seenEnd = true;
  const turn = arenaReplay.turns[arenaReplay.index];
  foldArenaEffects();
  renderArenaMatch(turn.view, currentArenaState, { replay: true });
  // 三百の回りで打ち切られて最後の手がまだ active でも、最後の手で決着を出す。
  const last = arenaReplay.index === arenaReplay.turns.length - 1;
  playArenaFlow(previous, turn.view, turn.events, { slotted: false, ending: last ? arenaReplayEnding(arenaReplay.matchId) : null });
  arenaScheduleReplayStep();
}

// Skip to the final frame, stopping the auto-advance: the replay rests on its end — the fallen sunk, the winner's light, rings and mark.
function arenaReplaySkip() {
  if (!arenaReplay) return;
  if (arenaReplay.timer) { window.clearTimeout(arenaReplay.timer); arenaReplay.timer = null; }
  arenaReplay.index = arenaReplay.turns.length - 1;
  arenaReplay.seenEnd = true; // 観戦: 終わりまで送っても見終えたことにする
  foldArenaEffects();
  const view = arenaReplay.turns[arenaReplay.index].view;
  renderArenaMatch(view, currentArenaState, { replay: true });
  const ending = arenaReplayEnding(arenaReplay.matchId);
  for (const actor of view.actors) if (actor.down) sinkArenaActor(actor.actor_id);
  lightArenaEnding(view, ending);
  markArenaEnding(ending);
}

function stopArenaReplay() {
  if (arenaReplay?.timer) window.clearTimeout(arenaReplay.timer);
  arenaReplay = null;
  foldArenaEffects();
}

// 観戦の操作: いまのターンの数・速さの三つの紋・終わりまで送る紋（終わりに着くまで）・表へ戻る紋。
function renderArenaReplayControls() {
  const node = document.querySelector('#arena-replay-controls');
  node.replaceChildren();
  const atEnd = !arenaReplay || arenaReplay.index >= arenaReplay.turns.length - 1;
  const info = document.createElement('span');
  info.className = 'arena-replay-info';
  info.textContent = arenaReplay ? `${arenaReplay.index + 1} / ${arenaReplay.turns.length}` : '';
  node.append(info, arenaReplaySpeedControl());
  if (!atEnd) node.append(venueSigilButton('skip', 'スキップ', () => { try { arenaReplaySkip(); } catch (error) { reportError(error); } }, 'arena-replay-skip'));
}

// The 低速/中速/高速 speed toggle. The selection lives in arenaReplaySpeed (session-held, never reset), so it carries
// across replays; picking a speed re-renders the controls (to move the selected mark) and the next scheduled step
// picks up the new interval.
function arenaReplaySpeedControl() {
  const group = document.createElement('div');
  group.className = 'arena-replay-speed';
  group.setAttribute('role', 'group');
  group.setAttribute('aria-label', '再生速度');
  for (const key of ['low', 'mid', 'high']) {
    const button = venueSigilButton(`speed-${key}`, ARENA_REPLAY_SPEED_LABELS[key], () => { arenaReplaySpeed = key; renderArenaReplayControls(); }, 'arena-replay-speed-button');
    const selected = arenaReplaySpeed === key;
    button.classList.toggle('is-selected', selected);
    button.setAttribute('aria-pressed', selected ? 'true' : 'false');
    group.append(button);
  }
  return group;
}

// ----- match-surface wiring (static nodes) -----

dressSigilButton(document.querySelector('#arena-exit'), 'back', '闘技会を出る').addEventListener('click', () => arenaExit().catch(reportError));
// Pressing anywhere on the match surface while a board flow plays folds the rest of it (入り・一手の流れ・決着).
document.querySelector('#arena-match').addEventListener('pointerdown', () => { if (arenaFlow) foldArenaEffects(); });
dressSigilButton(document.querySelector('#arena-match-back'), 'back', 'ブラケットへ戻る').addEventListener('click', () => {
  if (arenaActionInFlight) return;
  const watched = arenaReplay;
  stopArenaReplay();
  if (currentArenaState?.phase === 'tournament') {
    // 観戦: バディーの次の組を見終えて戻ったら、盤が薄れてから（主人公の試合の決着の後と同じ）その回戦を明かす。
    if (watched?.seenEnd && watched.matchId === arenaSpectateEntryMatch(currentArenaState)?.match_id) {
      arenaActionInFlight = true;
      fadeArenaMatch()
        .then(() => arenaSpectateAdvance(currentArenaState))
        .catch(reportArenaScreenError)
        .finally(() => { arenaActionInFlight = false; });
      return;
    }
    renderArenaBracket(currentArenaState);
    return;
  }
  refreshArenaScreen().catch(reportArenaScreenError);
});

// The arena match is driven from the keyboard like the dungeon (the dock has no movement buttons): arrow keys
// move, Space waits. There is no descend/retreat. Replay frames and consumable targeting are non-move surfaces.
const ARENA_ARROW_DIRS = { ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right' };
window.addEventListener('keydown', (event) => {
  if (!screens['academy-arena'].classList.contains('active')) return;
  if (document.querySelector('#arena-match').hidden) return;
  if (arenaReplay) return; // a replay is a non-interactive surface
  if (!currentArenaMatchView || !currentArenaMatchView.active) return;
  if (!Object.prototype.hasOwnProperty.call(currentArenaMatchView, 'player_actor_id')) return;
  if (arenaConsumableTargeting) {
    if (event.key === 'Escape') { event.preventDefault(); cancelArenaConsumableTargeting(); }
    return;
  }
  const active = document.activeElement;
  if (active && (active.id === 'arena-log' || ['INPUT', 'TEXTAREA', 'SELECT', 'BUTTON'].includes(active.tagName))) return;
  const direction = ARENA_ARROW_DIRS[event.key];
  if (direction) { event.preventDefault(); arenaDo({ type: 'move', direction }).catch(reportError); return; }
  if (event.key === ' ' || event.code === 'Space') { event.preventDefault(); arenaDo({ type: 'wait' }).catch(reportError); }
});

if ('ResizeObserver' in window) {
  const arenaGridEl = document.querySelector('#arena-grid');
  if (arenaGridEl) {
    // Refit the all-visible board whenever the arena stage resizes (window resize / narrow-screen reflow).
    new ResizeObserver(() => {
      if (!currentArenaMatchView || document.querySelector('#arena-match').hidden) return;
      layoutArenaBoard(currentArenaMatchView);
    }).observe(arenaGridEl);
  }
}

// ── Dev-only drag calibration (frame-decoration corners + map pins) ────────────────────────────────────
// Opened with ?calibrate=<screen> (e.g. ?calibrate=conversation-day / ?calibrate=academy-map). It shows the target
// screen and lays a draggable handle over each registered target, of which there are two kinds read from the
// declarative registries (frameDecorationCalibration.js):
//   • corner ornament — dragging updates a pair of translate-offset CSS custom properties in px (set on the
//     registered style host, inherited by its ::before/::after or real-element consumer); export is a CSS
//     declaration block to bake back into the defaults.
//   • map pin — dragging moves the stage marker by a percentage of the map image; export is a JS object
//     literal to paste back over the truth-source constant (academyMapStagePinCoordinates).
// The tool body dispatches on the target kind but is otherwise generic — a new corner or a new pin group is a
// registry entry, no code here changes. Without the query, none of this runs and normal play is byte-equivalent.
const CALIBRATION_CORNER_POINT = {
  'top-left': (rect) => ({ x: rect.left, y: rect.top }),
  'top-right': (rect) => ({ x: rect.right, y: rect.top }),
  'bottom-left': (rect) => ({ x: rect.left, y: rect.bottom }),
  'bottom-right': (rect) => ({ x: rect.right, y: rect.bottom })
};

let frameDecorationCalibrationState = null;

function requireCalibrationElement(selector, role, targetId) {
  const element = document.querySelector(selector);
  if (!element) {
    throw new Error(`calibration target ${targetId}: ${role} selector ${JSON.stringify(selector)} matched no element`);
  }
  return element;
}

function readCalibrationOffsetPx(computed, varName, targetId) {
  // Delegate the accept/reject boundary to the pure parser (strict px format, fail-fast on empty / non-px).
  return parseCalibrationOffsetPx(computed.getPropertyValue(varName), { varName, targetId });
}

// Resolve a registry entry against the live DOM: the anchor and style-host elements must exist and the
// offset custom properties must be defined (their CSS defaults). A missing selector or undefined property
// fail-fasts — a broken registration is surfaced, never silently skipped. The initial offset is read from
// the current property values so calibration continues from any already-baked offset.
function resolveCalibrationTarget(target) {
  const anchor = requireCalibrationElement(target.anchorSelector, 'anchor', target.id);
  const styleHost = requireCalibrationElement(target.styleHostSelector, 'style host', target.id);
  const computed = getComputedStyle(styleHost);
  const offset = {
    x: readCalibrationOffsetPx(computed, target.varX, target.id),
    y: readCalibrationOffsetPx(computed, target.varY, target.id)
  };
  // Capture the starting state so リセット returns to the screen's declared baseline (which may be a non-zero
  // baked offset), not to a hardcoded origin.
  return { target, anchor, styleHost, offset, baseline: { x: offset.x, y: offset.y } };
}

function applyCalibrationOffset(entry) {
  entry.styleHost.style.setProperty(entry.target.varX, `${Math.round(entry.offset.x)}px`);
  entry.styleHost.style.setProperty(entry.target.varY, `${Math.round(entry.offset.y)}px`);
}

function positionCalibrationHandle(entry) {
  const rect = entry.anchor.getBoundingClientRect();
  const point = CALIBRATION_CORNER_POINT[entry.target.corner](rect);
  entry.handle.style.left = `${point.x + entry.offset.x}px`;
  entry.handle.style.top = `${point.y + entry.offset.y}px`;
}

function repositionCalibrationHandles() {
  const state = frameDecorationCalibrationState;
  if (!state) return;
  for (const entry of state.corners) positionCalibrationHandle(entry);
  for (const group of state.pinGroups) for (const pin of group.pins) positionMapPinHandle(pin);
}

function calibrationReadoutRow(name, valueText) {
  const li = document.createElement('li');
  const nameEl = document.createElement('span');
  nameEl.textContent = name;
  const valueEl = document.createElement('span');
  valueEl.textContent = valueText;
  li.append(nameEl, valueEl);
  return li;
}

function updateCalibrationReadout() {
  const state = frameDecorationCalibrationState;
  if (!state) return;
  if (state.cornerReadout) {
    state.cornerReadout.replaceChildren(...state.corners.map((entry) =>
      calibrationReadoutRow(entry.target.label, `${Math.round(entry.offset.x)}, ${Math.round(entry.offset.y)}`)));
    state.cornerExport.value = formatCalibrationOffsetsCss(state.corners.map((entry) => ({
      target: entry.target,
      x: entry.offset.x,
      y: entry.offset.y
    })));
  }
  for (const group of state.pinGroups) {
    group.readout.replaceChildren(...group.pins.map((pin) =>
      calibrationReadoutRow(pin.pinId, `${roundMapPinCoordinate(pin.offset.x)}, ${roundMapPinCoordinate(pin.offset.y)}`)));
    const overrides = {};
    for (const pin of group.pins) overrides[pin.pinId] = { x: pin.offset.x, y: pin.offset.y };
    group.exportBox.value = formatMapPinCoordinatesJs({
      coordinatesName: group.coordinatesName,
      baseCoordinates: group.baseCoordinates,
      overrides
    });
  }
}

function beginCalibrationDrag(event, entry) {
  event.preventDefault();
  const handle = entry.handle;
  handle.setPointerCapture(event.pointerId);
  handle.dataset.dragging = 'true';
  const startX = event.clientX;
  const startY = event.clientY;
  const startOffset = { ...entry.offset };
  const move = (moveEvent) => {
    entry.offset = {
      x: startOffset.x + (moveEvent.clientX - startX),
      y: startOffset.y + (moveEvent.clientY - startY)
    };
    applyCalibrationOffset(entry);
    positionCalibrationHandle(entry);
    updateCalibrationReadout();
  };
  const end = () => {
    handle.removeEventListener('pointermove', move);
    handle.removeEventListener('pointerup', end);
    handle.removeEventListener('pointercancel', end);
    delete handle.dataset.dragging;
  };
  handle.addEventListener('pointermove', move);
  handle.addEventListener('pointerup', end);
  handle.addEventListener('pointercancel', end);
}

function createCalibrationHandle(entry) {
  const handle = document.createElement('button');
  handle.type = 'button';
  handle.className = 'frame-decoration-calibration-handle';
  handle.dataset.calibrationId = entry.target.id;
  handle.setAttribute('aria-label', `${entry.target.label} を移動`);
  const label = document.createElement('span');
  label.className = 'frame-decoration-calibration-handle-label';
  label.textContent = entry.target.label;
  handle.append(label);
  handle.addEventListener('pointerdown', (event) => beginCalibrationDrag(event, entry));
  entry.handle = handle;
  return handle;
}

// ── Map-pin calibration kind ───────────────────────────────────────────────────────────────────────────
// A pin group is resolved so that EVERY pin in the truth source gets a draggable handle — not just the pins the
// active field happens to render. The rendered pin nodes are zipped with the same renderable-location list
// renderAcademyMap produced (identical function + order) to recover each rendered node's locationId WITHOUT
// stamping anything onto the shipped pin markup (normal play stays byte-equivalent; no data attribute is added).
// Every truth-source id then binds to a live rendered node when one exists, or to a calibration-only marker
// synthesized at its % when it does not (event stages, or stages absent from the current field) — so all stages
// are positionable. An unknown coordinates source, a rendered node/location count desync, or a non-finite
// coordinate fail-fasts.
function resolveMapPinCalibrationPins(entry) {
  const container = requireCalibrationElement(entry.containerSelector, 'container', entry.id);
  const coordinates = MAP_PIN_CALIBRATION_COORDINATE_SOURCES[entry.coordinatesName];
  if (!coordinates) {
    throw new Error(`map-pins ${entry.id}: unknown coordinates source ${JSON.stringify(entry.coordinatesName)}`);
  }
  const ids = Object.keys(coordinates);
  if (ids.length === 0) {
    throw new Error(`map-pins ${entry.id}: coordinates source ${JSON.stringify(entry.coordinatesName)} has no pins`);
  }
  const renderedNodes = [...container.querySelectorAll(entry.nodeSelector)];
  const renderedLocations = academyMapRegionRenderableNodes(activeMapRegion, currentField?.locations ?? []);
  if (renderedNodes.length !== renderedLocations.length) {
    throw new Error(`map-pins ${entry.id}: ${renderedNodes.length} rendered pin nodes but ${renderedLocations.length} renderable locations (desync)`);
  }
  const nodeByLocationId = new Map(renderedLocations.map((location, index) => [location.id, renderedNodes[index]]));
  return ids.map((pinId) => {
    const base = coordinates[pinId];
    if (!base || !Number.isFinite(base.x) || !Number.isFinite(base.y)) {
      throw new Error(`map-pins ${entry.id}: pin ${JSON.stringify(pinId)} has no finite ${entry.coordinatesName} coordinate`);
    }
    let node = nodeByLocationId.get(pinId);
    const synthetic = node === undefined;
    if (synthetic) node = createCalibrationPinMarker(container, base);
    node.classList.add('is-drag-editable');
    return {
      entry,
      container,
      node,
      pinId,
      synthetic,
      offset: { x: base.x, y: base.y },
      baseline: { x: base.x, y: base.y }
    };
  });
}

// A calibration-only pin marker for a stage the normal render does not draw (an event stage, or one absent from
// the current field). It is a real .academy-map-node visual so it drags identically to a live pin, plus a
// modifier so the calibrator can tell it apart. It exists ONLY under ?calibrate=academy-map — normal play never
// creates one (renderAcademyMap is untouched).
function createCalibrationPinMarker(container, base) {
  const marker = document.createElement('div');
  marker.className = 'academy-map-node academy-map-node--calibration-synthetic';
  marker.style.backgroundImage = `url('${academyMapPinImageUrl(activeMapRegion, false, false)}')`;
  marker.style.left = `${base.x}%`;
  marker.style.top = `${base.y}%`;
  container.append(marker);
  return marker;
}

// Write the pin's current % back onto the live map node (renderAcademyMap consumes button.style.left/top = %).
function applyMapPinOffset(pin) {
  pin.node.style.left = `${pin.offset.x}%`;
  pin.node.style.top = `${pin.offset.y}%`;
}

// The pin marker's anchor is bottom-center (translate(-50%,-100%)), so the pin tip sits at the rect's
// bottom-center — that is the point the % coordinate names, and where the handle rides.
function positionMapPinHandle(pin) {
  const rect = pin.node.getBoundingClientRect();
  pin.handle.style.left = `${rect.left + rect.width / 2}px`;
  pin.handle.style.top = `${rect.bottom}px`;
}

function beginMapPinDrag(event, pin) {
  event.preventDefault();
  const handle = pin.handle;
  handle.setPointerCapture(event.pointerId);
  handle.dataset.dragging = 'true';
  pin.node.classList.add('is-dragging');
  // The pointer delta is in screen px; convert to a % of the map image (the stage layer = the container) so
  // the exported value is in the same left-origin percentage renderAcademyMap writes.
  const containerRect = pin.container.getBoundingClientRect();
  const startX = event.clientX;
  const startY = event.clientY;
  const startOffset = { ...pin.offset };
  const move = (moveEvent) => {
    pin.offset = {
      x: startOffset.x + ((moveEvent.clientX - startX) / containerRect.width) * 100,
      y: startOffset.y + ((moveEvent.clientY - startY) / containerRect.height) * 100
    };
    applyMapPinOffset(pin);
    positionMapPinHandle(pin);
    updateCalibrationReadout();
  };
  const end = () => {
    handle.removeEventListener('pointermove', move);
    handle.removeEventListener('pointerup', end);
    handle.removeEventListener('pointercancel', end);
    delete handle.dataset.dragging;
    pin.node.classList.remove('is-dragging');
  };
  handle.addEventListener('pointermove', move);
  handle.addEventListener('pointerup', end);
  handle.addEventListener('pointercancel', end);
}

function createMapPinHandle(pin) {
  const handle = document.createElement('button');
  handle.type = 'button';
  handle.className = 'frame-decoration-calibration-handle frame-decoration-calibration-handle--pin';
  handle.dataset.calibrationId = `${pin.entry.id}:${pin.pinId}`;
  handle.dataset.calibrationPinId = pin.pinId;
  handle.setAttribute('aria-label', `${pin.pinId} を移動`);
  const label = document.createElement('span');
  label.className = 'frame-decoration-calibration-handle-label';
  label.textContent = pin.pinId;
  handle.append(label);
  handle.addEventListener('pointerdown', (event) => beginMapPinDrag(event, pin));
  pin.handle = handle;
  return handle;
}

function buildCalibrationPanel(corners, pinGroups) {
  const panel = document.createElement('div');
  panel.className = 'frame-decoration-calibration-panel';
  const heading = document.createElement('h2');
  heading.textContent = 'フレーム装飾 校正モード';
  const help = document.createElement('p');
  help.textContent = 'ハンドルをドラッグして位置を合わせ、下のテキストをコピーして Lead に渡してください。';
  panel.append(heading, help);
  const actions = document.createElement('div');
  actions.className = 'frame-decoration-calibration-actions';

  let cornerReadout = null;
  let cornerExport = null;
  if (corners.length) {
    cornerReadout = document.createElement('ul');
    cornerReadout.className = 'frame-decoration-calibration-readout';
    cornerExport = document.createElement('textarea');
    cornerExport.className = 'frame-decoration-calibration-export';
    cornerExport.readOnly = true;
    panel.append(cornerReadout, cornerExport);
    actions.append(buildCalibrationCopyButton('CSSをコピー', 'copy-corners', () => cornerExport.value));
  }

  for (const group of pinGroups) {
    const sectionLabel = document.createElement('p');
    sectionLabel.className = 'frame-decoration-calibration-section-label';
    sectionLabel.textContent = `${group.entry.label}（表示 ${group.pins.length} 件 / 出力 ${Object.keys(group.baseCoordinates).length} 件）`;
    const readout = document.createElement('ul');
    readout.className = 'frame-decoration-calibration-readout frame-decoration-calibration-pin-readout';
    const exportBox = document.createElement('textarea');
    exportBox.className = 'frame-decoration-calibration-export frame-decoration-calibration-pin-export';
    exportBox.readOnly = true;
    group.readout = readout;
    group.exportBox = exportBox;
    panel.append(sectionLabel, readout, exportBox);
    actions.append(buildCalibrationCopyButton('ピン座標JSをコピー', 'copy-pins', () => exportBox.value));
  }

  const resetButton = document.createElement('button');
  resetButton.type = 'button';
  resetButton.textContent = '既定に戻す';
  resetButton.dataset.calibrationAction = 'reset';
  resetButton.addEventListener('click', () => {
    const state = frameDecorationCalibrationState;
    // Restore every target to its captured baseline (the declared/baked start), not a hardcoded 0 / seed value.
    restoreCalibrationBaselines(state.corners);
    for (const entry of state.corners) {
      applyCalibrationOffset(entry);
      positionCalibrationHandle(entry);
    }
    for (const group of state.pinGroups) {
      restoreCalibrationBaselines(group.pins);
      for (const pin of group.pins) {
        applyMapPinOffset(pin);
        positionMapPinHandle(pin);
      }
    }
    updateCalibrationReadout();
  });
  actions.append(resetButton);
  panel.append(actions);
  return { panel, cornerReadout, cornerExport };
}

// No ad-hoc alternate path / silent fallback: copy requires the async clipboard API. When it is genuinely
// unavailable it surfaces an explicit error rather than quietly doing something else — the always-visible
// read-only export box is the manual copy affordance, and the button stays truthful.
function buildCalibrationCopyButton(labelText, action, getExportText) {
  const button = document.createElement('button');
  button.type = 'button';
  button.textContent = labelText;
  button.dataset.calibrationAction = action;
  button.addEventListener('click', () => {
    if (typeof navigator.clipboard?.writeText !== 'function') {
      reportError(new Error('クリップボード API (navigator.clipboard.writeText) が使えません。下のテキストボックスから手動でコピーしてください。'));
      return;
    }
    navigator.clipboard.writeText(getExportText()).catch(reportError);
  });
  return button;
}

function buildFrameDecorationCalibrationOverlay(cornerTargets, pinGroupTargets) {
  const corners = cornerTargets.map(resolveCalibrationTarget);
  const pinGroups = pinGroupTargets.map((entry) => ({
    entry,
    pins: resolveMapPinCalibrationPins(entry),
    coordinatesName: entry.coordinatesName,
    baseCoordinates: MAP_PIN_CALIBRATION_COORDINATE_SOURCES[entry.coordinatesName],
    readout: null,
    exportBox: null
  }));
  const layer = document.createElement('div');
  layer.className = 'frame-decoration-calibration-layer';
  const { panel, cornerReadout, cornerExport } = buildCalibrationPanel(corners, pinGroups);
  layer.append(panel);
  for (const entry of corners) layer.append(createCalibrationHandle(entry));
  for (const group of pinGroups) for (const pin of group.pins) layer.append(createMapPinHandle(pin));
  document.body.append(layer);
  frameDecorationCalibrationState = { corners, pinGroups, layer, cornerReadout, cornerExport };
  repositionCalibrationHandles();
  updateCalibrationReadout();
  window.addEventListener('resize', repositionCalibrationHandles);
  window.addEventListener('scroll', repositionCalibrationHandles, true);
}

// Switch the multi-region map screen to the ?region= selector before the map-pin overlay is built. A region id
// that is not a known map region fail-fasts (mirrors the unknown-screen fail-fast) instead of silently routing
// through the default-region behavior of mapRegionDefinition — a wrong ?region= is a broken invocation, not a
// state to degrade past.
function applyCalibrationMapRegion(region) {
  const known = ACADEMY_MAP_REGIONS.some((definition) => definition.id === region);
  if (!known) {
    throw new Error(`?calibrate region ${JSON.stringify(region)} is not a known map region (known: ${ACADEMY_MAP_REGIONS.map((definition) => definition.id).join(', ')})`);
  }
  setActiveMapRegion(region);
}

function activateFrameDecorationCalibration(screen) {
  validateCalibrationRegistry(FRAME_DECORATION_CALIBRATION_TARGETS);
  validateMapPinCalibrationRegistry(MAP_PIN_CALIBRATION_TARGETS);
  const region = readCalibrationRegion(window.location.search);
  const { corners, pins } = calibrationTargetsForScreen(screen);
  showScreen(screen);
  // Build the overlay after the screen has laid out so the anchor / pin rects (and thus handle positions) are real.
  requestAnimationFrame(() => {
    // The map screen hosts several regions on one DOM; ?region= switches to the one being calibrated so its
    // background + live pins render. Absent, the screen keeps its default region. Only the pin groups whose
    // region is active are built, so exactly one region's pins are calibrated at a time.
    if (region !== null) applyCalibrationMapRegion(region);
    const activePins = pins.filter((entry) => entry.region === activeMapRegion);
    if (pins.length > 0 && activePins.length === 0) {
      throw new Error(`no map-pin calibration group for screen ${JSON.stringify(screen)} region ${JSON.stringify(activeMapRegion)} (registered regions: ${[...new Set(pins.map((entry) => entry.region))].join(', ')})`);
    }
    buildFrameDecorationCalibrationOverlay(corners, activePins);
  });
}

function applyFrameDecorationCalibrationOverride() {
  const screen = readCalibrationScreen(window.location.search);
  if (screen === null) return;
  activateFrameDecorationCalibration(screen);
}

// ===== 競売場 (auction) screen =====
// A routing destination driven entirely from the frontend across the auction's per-utterance HTTP surface. The
// persisted granularity is the LOT: the slot advances only at resolve. A lot's in-progress bidding (current price /
// standing highest bidder / who has dropped / turn cursor) is held HERE and re-validated server-side against the
// authoritative slot each request; a reload restarts the current lot's bidding from the top. The SSE reader is
// consumer-owned (the auction's result shape { lot_index, utterance, ... } is not conversation-shaped, so the shared
// runAssistantSseStream is not reused).
//
// It stands on the venue (会場で分け合う作り): the auction house's art fills the screen and the way of its stages
// (出品・一品目・二品目・三品目) runs across the top. 競売人ガロウ stands at the back of the stage, the lot and its price
// sit in front of the rostrum, and the week's seated bidders (3〜5) sit in the front rows to the left and right as
// faces matted onto the stage light (conversationLayer.js litFace). Who holds the highest bid is told by the light on
// that person and the raised paddle; a dropped bidder sinks with the paddle lowered. A bidder's words land over the
// speaker's head and the master's long 口上 beside his face (older ones fade); the authored 地の文 (流札・ざわめき・
// 籠入りの落札) sits under the price, and the player's own bid / pass line sits over the hand at the bottom, where the
// purse, the raise (the minimum increment already in it) and the bid / drop sigils are.

const AUCTION_MASTER_ACTOR = Object.freeze({
  character_id: 'auction_garou',
  display_name: '競売人ガロウ',
  face_url: '/canonical/character_visual_sets/auction_garou/face_emotions/neutral.jpg'
});
const AUCTION_PLAYER_WINNER_ID = 'player';
const AUCTION_PLAYER_LABEL = 'あなた';
// 競売場 is a routing-only destination (the auction API rejects non-routing with 409 ROUTING_MODE_REQUIRED), so its
// post-content return is always the routing hub — the exact value resolvePostContentScreen({ mode: 'routing' })
// yields server-side and the value returnToRoutingHubFromContent requires. Held as this invariant rather than a
// silently-defaulted screen id.
const AUCTION_POST_CONTENT_SCREEN = 'interaction';
// Authored 地の演出 (LLM 非関与): the 流札 line and the between-lot murmurs that fill the serial-LM gaps.
const AUCTION_PASSED_IN_NARRATION = 'どこからも声は上がらず、槌は静かに置かれた。この品は流れ、また別の宵を待つ。';
// A player-won 籠入りの生き物 (house lot) is not an inventory item — it goes onto the 星の揺り籠 caged surface
// (backend writer). This screen otherwise has no way to show that destination, so an authored 地の文 names it; the
// identifying part (the lot name) comes straight from the view — the frontend never re-derives 品種/band.
function auctionCagedCreatureAwardNarration(lot) {
  return `落札した「${lot.name}」は、星の揺り籠の籠入りに迎え入れられた。`;
}
const AUCTION_MURMUR_POOL = Object.freeze([
  '会場のあちこちで、値踏みするようなざわめきが起こる。',
  'ランタンの灯が揺れ、天鵞絨の緞帳がかすかに波打つ。',
  '扇を鳴らす音、囁き交わす声——宵の会場が次の品を待って熱を帯びていく。',
  '槌の余韻が消え、燭台の炎だけが小さく爆ぜた。'
]);
let auctionMurmurCursor = 0;
// The way of the stages: 出品 (the player's consignment window / lot), then the three house lots.
const AUCTION_WAY = ['出品', '一品目', '二品目', '三品目'];
// The seat the master's words land on (the bidders' seats are their character ids).
const AUCTION_MASTER_SEAT = 'master';
// How a seat's line gives way: the previous line thins out while drawing back upward, and only once it is gone does
// the new one come in over the same spot — the two lines never show at once.
const AUCTION_WORD_LEAVE_MS = 340;
const AUCTION_WORD_ENTER_MS = 280;

// Auction session state (frontend-carried; not persisted — see the module header).
let auctionSlotView = null;        // last GET/enter/resolve state view (bidders / lots / awards / current_lot_index / status)
let auctionBidState = null;        // { current, highestBidder, highestBidderName, history[], activeNpcIds:Set, playerActive }
let auctionFlowInFlight = false;   // guards the re-entrant showScreen during a loading transition and double-drive
let auctionActionInFlight = false; // single-flight guard for a player bid / pass submission
let auctionPlayerResolve = null;   // resolves the pending player-turn promise when the bid / drop sigil is pressed
let auctionMoney = null;           // last known player money, for the bid validation + the purse
let auctionLotGoaded = false;      // one master goad per lot before the player's standing-bid decision
let auctionMasterUtterances = [];  // this visit's already-spoken master 口上 (opening/goad/hammer), carried to each
                                   // master request so the model varies each 口上 (反復回避ハンドオフ). Not persisted;
                                   // a reload restarts the visit and this accumulator (per-utterance design).
// 出品側 (player-consignment) session state (frontend-carried; not persisted — same lot-granular design as the house
// lots). The consignment lot runs before the house lots when the player lists an asset this visit.
let auctionConsignmentView = null;        // the current visit's consignment view (state.consignment / submit response): { status, presentation, band, initial_price, min_increment, ... }
let auctionConsignmentChoiceResolve = null; // resolves the 出品/skip picker choice ({ kind:'submit', source } | { kind:'skip' })
let auctionPhase = null;                   // 'picker' | 'consignment' | 'house' | 'closed' — the entry phase, read post-cover to choose what to render
// The words spoken this visit, oldest first: { seat, role: 'speech' | 'narration', text }. seat is 'master', a seated
// bidder's character_id, 'ground' (the authored 地の文) or 'player' (the player's own bid / pass line).
let auctionWords = [];
// The seats of this visit's bidders (character_id → the seat's figure), built once the slot's bidders are known.
let auctionSeats = new Map();
let auctionSeatsBidders = null;
// 段の道が途切れているか（失敗の紋と言い直しの紋が立っている間）。
let auctionWayFailed = false;
// The 流札 line for a consignment lot: unlike a house-lot 流札 (the品 flows away), the player's own unsold asset
// stays with them — the authored 地の文 says so (authored, LLM 非関与).
const AUCTION_CONSIGNMENT_PASSED_IN_NARRATION = 'どこからも声は上がらず、槌は静かに置かれた。この品は落札されず、あなたの手元に残った。';

const auctionScreen = document.querySelector('#academy-auction-screen');
dressVenueGround(auctionScreen, 'auction');
dressVenueSigilButton(document.querySelector('#academy-auction-retry'), 'retry', VENUE_RETRY_LABEL);
const AUCTION_STAGE_ART = destinationArt('auction');

// ----- the way of the stages and its failure -----

// The stage the way is on: the 出品 window / lot, a house lot (its index + 1), or past the last lot when closed. A
// failure after the close (leaving by the exit sigil) breaks the way past the last lot (三品目), since a finished way
// has no stage left to break at.
function auctionWayStage() {
  if (auctionPhase === 'closed') return auctionWayFailed ? AUCTION_WAY.length - 1 : AUCTION_WAY.length;
  if (auctionPhase === 'house' && auctionSlotView) return Math.min(auctionSlotView.current_lot_index, auctionSlotView.lots.length - 1) + 1;
  return 0;
}

function renderAuctionWay() {
  renderVenuePath(document.querySelector('#academy-auction-path'), { names: AUCTION_WAY, current: auctionWayStage(), failed: auctionWayFailed });
  auctionScreen.dataset.stage = auctionPhase ?? 'entering';
  document.querySelector('#academy-auction-exit').hidden = auctionPhase !== 'closed';
}

// 競売場の失敗: いまの段の星の先で道が途切れ、言い直しの紋が立つ。LM の設定・接続の失敗は設定の画面へ誘う（handleRuntimeApiError）。
// 生成の関所が言葉を通さなかった失敗（AUCTION_GENERATION_FAILED）もほかの失敗も、原因は console にだけ残す。retry は失敗した手を
// もう一度行う（既定は競売場へ入り直す = いまのロットを頭からやり直す。ロット単位の永続と同じ）。
function reportAuctionScreenError(error, retry = retryAuctionEntry) {
  if (handleRuntimeApiError(error, { allowSettingsRedirect: true })) return;
  console.error(error);
  auctionWayFailed = true;
  renderAuctionWay();
  setVenueRetry(document.querySelector('#academy-auction-retry'), () => {
    clearAuctionWayFailure();
    retry();
  });
}

function retryAuctionEntry() {
  enterOrResumeAuctionScreen({ routingArrival: null }).catch((error) => reportAuctionScreenError(error));
}

function clearAuctionWayFailure() {
  auctionWayFailed = false;
  setVenueRetry(document.querySelector('#academy-auction-retry'), null);
  renderAuctionWay();
}

function auctionLotView(lotIndex) {
  const lot = auctionSlotView?.lots?.find((entry) => entry.lot_index === lotIndex);
  if (!lot) throw new Error(`auction lot view not found for index ${lotIndex}`);
  return lot;
}

function auctionCurrentLotView() {
  if (!auctionSlotView || auctionSlotView.current_lot_index >= auctionSlotView.lots.length) return null;
  return auctionLotView(auctionSlotView.current_lot_index);
}

function showAuctionLive() {
  document.querySelector('#academy-auction-live').hidden = false;
  document.querySelector('#academy-auction-closed').hidden = true;
  document.querySelector('#academy-auction-consignment').hidden = true;
  renderAuctionWay();
}

// Shows the 出品 picker (before the house lots), hiding the live stage and the closed view.
function showAuctionConsignmentPicker() {
  document.querySelector('#academy-auction-live').hidden = true;
  document.querySelector('#academy-auction-closed').hidden = true;
  document.querySelector('#academy-auction-consignment').hidden = false;
  renderAuctionWay();
}

function hideAuctionConsignmentPicker() {
  const picker = document.querySelector('#academy-auction-consignment');
  picker.hidden = true;
  delete picker.dataset.reveal;
}

// The rows come in one after another once the screen has arrived (the window already stands at its final size, so
// nothing around the rows moves while they come in). With reduced motion the app turns every CSS animation off (it
// only switches); inside that rule this one list still comes in by opacity alone, as its ordered motion asks, through
// script animations the CSS rule does not reach.
const AUCTION_ROW_FADE_MS = 200;
const AUCTION_ROW_STAGGER_MS = 45;
function revealAuctionConsignmentRows() {
  const picker = document.querySelector('#academy-auction-consignment');
  picker.dataset.reveal = 'true';
  if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  picker.querySelectorAll('.academy-auction-consignment-row').forEach((row, order) => {
    row.animate([{ opacity: 0 }, { opacity: 1 }], { duration: AUCTION_ROW_FADE_MS, delay: Math.min(order, 8) * AUCTION_ROW_STAGGER_MS, easing: 'ease-out', fill: 'backwards' });
  });
}

// The no-bid mark before the lot name is shown only while the player's own consignment lot is on the stage.
function setAuctionConsignorBadge(visible) {
  document.querySelector('#academy-auction-consignor-badge').hidden = !visible;
}

// ----- the seats: the master at the back of the stage, the bidders in the front rows -----

// A seated bidder's face: the selectable roster's visual set (neutral — the auction SSE carries no emotion). An id
// missing from the roster is a desync, not a cue for a default face.
function auctionBidderFaceUrl(characterId) {
  const character = selectableCharacters.find((entry) => entry.character_id === characterId);
  if (!character) throw new Error(`auction bidder not found in the character roster: ${characterId}`);
  if (!character.visual_set_id) throw new Error(`auction bidder is missing visual_set_id: ${characterId}`);
  return `/canonical/character_visual_sets/${character.visual_set_id}/face_emotions/neutral.jpg`;
}

// The seat of the i-th seated bidder: the front rows split left (ceil(n/2)) and right (floor(n/2)), filled from the
// corners inward in seated order (left corner, right corner, the next on the left, ...).
function auctionSeatPlace(index) {
  return { side: index % 2 === 0 ? 'left' : 'right', rank: Math.floor(index / 2) };
}

async function auctionSeatFigure({ seat, name, faceUrl, light, side = null, rank = null }) {
  const figure = document.createElement('figure');
  figure.className = 'academy-auction-seat';
  figure.dataset.seat = seat;
  if (side !== null) { figure.dataset.side = side; figure.dataset.rank = String(rank); }
  const voice = document.createElement('div');
  voice.className = 'academy-auction-voice';
  const well = document.createElement('div');
  well.className = 'academy-auction-seat-face';
  const image = document.createElement('img');
  image.alt = '';
  image.src = await litFace(faceUrl, light);
  await image.decode();
  well.append(image);
  const caption = document.createElement('figcaption');
  caption.className = 'academy-auction-seat-name';
  caption.textContent = name;
  figure.append(voice, well, caption);
  if (side !== null) {
    const paddle = document.createElement('span');
    paddle.className = 'academy-auction-seat-paddle';
    paddle.setAttribute('role', 'img');
    const mark = document.createElementNS(VENUE_SVG_NS, 'svg');
    mark.setAttribute('class', 'academy-auction-paddle');
    mark.setAttribute('aria-hidden', 'true');
    mark.setAttribute('focusable', 'false');
    const use = document.createElementNS(VENUE_SVG_NS, 'use');
    use.setAttribute('href', '#venue-paddle');
    mark.append(use);
    paddle.append(mark);
    figure.append(paddle);
  }
  return figure;
}

// Builds the master's and this visit's bidders' seats once the slot is known (the same bidders all week).
async function renderAuctionSeats() {
  const bidders = auctionSlotView.bidders;
  const key = bidders.map((bidder) => bidder.character_id).join(' ');
  if (auctionSeatsBidders === key) return;
  const light = await stageLight(AUCTION_STAGE_ART);
  auctionScreen.style.setProperty('--auction-light-rgb', light.join(' '));
  const figures = [await auctionSeatFigure({ seat: AUCTION_MASTER_SEAT, name: AUCTION_MASTER_ACTOR.display_name, faceUrl: AUCTION_MASTER_ACTOR.face_url, light })];
  const seats = new Map([[AUCTION_MASTER_SEAT, figures[0]]]);
  for (const [index, bidder] of bidders.entries()) {
    const { side, rank } = auctionSeatPlace(index);
    const figure = await auctionSeatFigure({ seat: bidder.character_id, name: bidder.display_name, faceUrl: auctionBidderFaceUrl(bidder.character_id), light, side, rank });
    figure.dataset.count = String(bidders.length);
    seats.set(bidder.character_id, figure);
    figures.push(figure);
  }
  document.querySelector('#academy-auction-seats').replaceChildren(...figures);
  auctionSeats = seats;
  auctionSeatsBidders = key;
  renderAuctionWords();
  renderAuctionSeatStates();
}

// The seats' bid states: the standing highest bidder is lit with the paddle raised; a bidder who has bid and is still
// in shows the raised paddle; a dropped bidder sinks with the paddle lowered; the master is lit while speaking.
function renderAuctionSeatStates() {
  const bidded = new Set((auctionBidState?.history ?? []).filter((entry) => entry.action === 'bid').map((entry) => entry.character_id));
  for (const [seat, figure] of auctionSeats) {
    if (seat === AUCTION_MASTER_SEAT) continue;
    const paddle = figure.querySelector('.academy-auction-seat-paddle');
    let state = 'waiting';
    if (auctionBidState) {
      if (auctionBidState.highestBidder === seat) state = 'highest';
      else if (!auctionBidState.activeNpcIds.has(seat)) state = 'down';
      else if (bidded.has(seat)) state = 'raised';
    }
    figure.dataset.state = state;
    paddle.hidden = state === 'waiting';
    paddle.setAttribute('aria-label', { highest: '最高入札者', down: '降りた', raised: '入札中', waiting: '入札中' }[state]);
  }
  document.querySelector('#academy-auction-desk-highest').hidden = auctionBidState?.highestBidder !== AUCTION_PLAYER_WINNER_ID;
}

// ----- words: each seat's latest line over the speaker's head, the 地の文 under the price, the player's line over the hand -----

// cut: swap the seats' lines without movement (a fresh visit clears the last visit's words at once).
function renderAuctionWords({ cut = false } = {}) {
  const speaking = auctionWords.length ? auctionWords[auctionWords.length - 1].seat : null;
  for (const [seat, figure] of auctionSeats) {
    placeAuctionSeatWord(figure.querySelector('.academy-auction-voice'), auctionWords.findLast((word) => word.seat === seat), cut);
    if (seat === AUCTION_MASTER_SEAT) figure.dataset.state = speaking === AUCTION_MASTER_SEAT ? 'speaking' : 'quiet';
  }
  for (const [seat, selector] of [['ground', '#academy-auction-ground-words'], ['player', '#academy-auction-player-words']]) {
    const latest = auctionWords.filter((word) => word.seat === seat).slice(-1);
    document.querySelector(selector).replaceChildren(...latest.map(auctionWordNode));
  }
}

// Puts a seat's latest line over the speaker's head. A changed line does not vanish at once: the previous one thins
// out and draws back upward over the same spot and leaves the DOM, and the new one waits unseen until then before
// coming in — at rest each seat holds one line. Reduced motion swaps without movement.
function placeAuctionSeatWord(place, word, cut) {
  const current = place.querySelector(':scope > .academy-auction-word:not([data-leaving])');
  if (current && word && current.dataset.role === word.role && current.textContent === word.text) return;
  const still = cut || window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  for (const leaving of place.querySelectorAll(':scope > .academy-auction-word[data-leaving]')) leaving.remove();
  if (current) {
    if (still) current.remove();
    else {
      current.dataset.leaving = '';
      current.setAttribute('aria-hidden', 'true');
      current.animate([{ opacity: 1, translate: '0 0' }, { opacity: 0, translate: '0 -0.9em' }], { duration: AUCTION_WORD_LEAVE_MS, easing: 'ease-in', fill: 'forwards' })
        .finished.then(() => current.remove());
    }
  }
  if (!word) return;
  const node = auctionWordNode(word);
  place.append(node);
  if (!still) node.animate([{ opacity: 0 }, { opacity: 1 }], { duration: AUCTION_WORD_ENTER_MS, delay: current ? AUCTION_WORD_LEAVE_MS : 0, easing: 'ease-out', fill: 'backwards' });
}

function auctionWordNode(word) {
  const node = document.createElement('p');
  node.className = 'academy-auction-word';
  node.dataset.role = word.role;
  node.textContent = word.text;
  return node;
}

// The display pieces of one utterance: the speech split at its （所作） parentheses (the shared split), each piece
// keeping its speaker's seat. A bidder's seat carries the spoken words only, so its （所作） pieces are dropped.
function auctionWordPieces(seat, text) {
  return displayMessages([{ role: 'assistant', content: text }])
    .filter((piece) => (piece.content ?? '').trim())
    .filter((piece) => seat === AUCTION_MASTER_SEAT || piece.role !== 'narration')
    .map((piece) => ({ seat, role: piece.role === 'narration' ? 'narration' : 'speech', text: piece.content }));
}

// A cooldown-paced reveal of one utterance's pieces over the speaker's head (the shared turn-reveal queue).
function createAuctionWordsReveal(base) {
  return createConversationStageTurnReveal({
    cooldownMs: conversationPopupCooldownMs,
    sleep,
    render: (revealed) => {
      auctionWords = [...base, ...revealed];
      renderAuctionWords();
    }
  });
}

// Consumer-owned SSE reader for one auction speech (master 口上 / goad / hammer, character reaction). Frames events
// exactly like the shared stream helper (event:/data: over \n\n blocks) but returns the auction result payload
// ({ lot_index, utterance, ... }). onStreamStart fires once on the first token so the entry wait can end on the
// opening's first stream.
async function readAuctionSpeechSse(endpoint, body, { onDelta, onComplete, onStreamStart = null }) {
  const response = await fetch(endpoint, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(body)
  });
  if (!response.ok) {
    const text = await response.text();
    throw createApiError({ url: endpoint, status: response.status, payload: parseJsonText(text), fallbackText: text });
  }
  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = '';
  let finalResult = null;
  let streamStarted = false;
  const notifyStreamStarted = () => {
    if (streamStarted) return;
    streamStarted = true;
    onStreamStart?.();
  };
  const handleBlock = (block) => {
    const event = block.split('\n').find((line) => line.startsWith('event: '))?.slice(7);
    const dataText = block.split('\n').find((line) => line.startsWith('data: '))?.slice(6);
    const data = dataText ? JSON.parse(dataText) : null;
    if (event === 'assistant_delta') { notifyStreamStarted(); onDelta(data.delta ?? ''); }
    if (event === 'assistant_complete') { notifyStreamStarted(); onComplete(data.content ?? ''); }
    if (event === 'result') finalResult = data;
    if (event === 'error') throw createApiError({ url: endpoint, status: 503, payload: data, fallbackText: data?.error ?? '' });
  };
  while (true) {
    const { value, done } = await reader.read();
    buffer += decoder.decode(value ?? new Uint8Array(), { stream: !done });
    const blocks = buffer.split('\n\n');
    buffer = blocks.pop() ?? '';
    for (const block of blocks) if (block.trim()) handleBlock(block);
    if (done) break;
  }
  if (buffer.trim()) handleBlock(buffer);
  if (!finalResult) throw new Error('auction speech stream ended without a final result');
  return finalResult;
}

// Streams one speech, revealing completed pieces over the speaker's head as they arrive. On failure the reveal is
// cancelled and the words go back to what they were before the speech (no half-revealed line left behind).
async function revealAuctionSpeech({ seat, endpoint, body, onStreamStart = null }) {
  const base = [...auctionWords];
  const reveal = createAuctionWordsReveal(base);
  let fullText = '';
  let pieceCount = 0;
  const enqueueFrom = (text) => {
    if (!text.trim()) return;
    const pieces = auctionWordPieces(seat, text);
    const fresh = pieces.slice(pieceCount);
    pieceCount += fresh.length;
    reveal.enqueue(fresh.map((piece) => ({ ...piece, content: piece.text })));
  };
  let result = null;
  try {
    result = await readAuctionSpeechSse(endpoint, body, {
      onStreamStart,
      onDelta: (delta) => { fullText += delta; enqueueFrom(completedAssistantPrefix(fullText)); },
      onComplete: (content) => { fullText = content || fullText; enqueueFrom(fullText); }
    });
    await reveal.drain();
  } catch (error) {
    reveal.cancel();
    auctionWords = base;
    renderAuctionWords();
    throw error;
  }
  auctionWords = [...base, ...auctionWordPieces(seat, fullText)];
  renderAuctionWords();
  return result;
}

// Records a just-spoken master 口上 into this visit's accumulator, which is sent to every subsequent master request
// as the 反復回避ハンドオフ (so the model does not open every lot with the same 賛辞). Returns the result unchanged.
function recordAuctionMasterUtterance(result) {
  const text = String(result?.utterance ?? '').trim();
  if (text) auctionMasterUtterances.push(text);
  return result;
}

// Reveals one already-generated utterance (an NPC bid decision is a JSON turn, not SSE) through the same paced reveal.
async function revealAuctionUtterance(seat, text) {
  if (!String(text ?? '').trim()) return;
  const base = [...auctionWords];
  const reveal = createAuctionWordsReveal(base);
  reveal.enqueue(auctionWordPieces(seat, text).map((piece) => ({ ...piece, content: piece.text })));
  await reveal.drain();
  auctionWords = [...base, ...auctionWordPieces(seat, text)];
  renderAuctionWords();
}

// Appends an authored 地の文 (流札 / murmur / 籠入りの落札) under the price, with the same cooldown-paced pop-in.
async function appendAuctionNarration(text) {
  auctionWords = [...auctionWords, { seat: 'ground', role: 'narration', text }];
  renderAuctionWords();
  await sleep(conversationPopupCooldownMs());
}

// Appends the player's own ground-text (bid / pass) over the hand.
async function appendAuctionPlayerNarration(text) {
  auctionWords = [...auctionWords, { seat: 'player', role: 'narration', text }];
  renderAuctionWords();
  await sleep(conversationPopupCooldownMs());
}

function nextAuctionMurmur() {
  const line = AUCTION_MURMUR_POOL[auctionMurmurCursor % AUCTION_MURMUR_POOL.length];
  auctionMurmurCursor += 1;
  return line;
}

// ----- lot / hand rendering -----

function pulseAuctionPrice() {
  const price = document.querySelector('.academy-auction-price');
  price.classList.remove('is-updated');
  void price.offsetWidth;
  price.classList.add('is-updated');
}

function renderAuctionPurse() {
  document.querySelector('#academy-auction-money').textContent = auctionMoney !== null ? `${auctionMoney}G` : '—';
}

function renderAuctionBoardFromState({ pulse = false } = {}) {
  const lot = auctionCurrentLotView();
  if (!lot) return;
  document.querySelector('#academy-auction-board-category').textContent = lot.category_label;
  document.querySelector('#academy-auction-board-name').textContent = lot.name;
  document.querySelector('#academy-auction-board-blurb').textContent = lot.blurb;
  document.querySelector('#academy-auction-current').textContent = String(auctionBidState ? auctionBidState.current : lot.initial_price);
  renderAuctionPurse();
  setAuctionConsignorBadge(false); // a house lot is never the player's own listing
  setAuctionDeskConsignment(false);
  renderAuctionSeatStates();
  renderAuctionWay();
  renderAuctionBidAffordance();
  if (pulse) pulseAuctionPrice();
}

// Renders the stage for the player's own consignment lot: the listing presentation (not a house lot view), the
// no-bid mark before its name, and the NPC-only bid states. The hand holds the purse and the no-bid line only.
function renderAuctionConsignmentBoardFromState({ pulse = false } = {}) {
  if (!auctionConsignmentView) return;
  const presentation = auctionConsignmentView.presentation;
  document.querySelector('#academy-auction-board-category').textContent = presentation.category_label;
  document.querySelector('#academy-auction-board-name').textContent = presentation.name;
  document.querySelector('#academy-auction-board-blurb').textContent = presentation.blurb;
  document.querySelector('#academy-auction-current').textContent = String(auctionBidState ? auctionBidState.current : auctionConsignmentView.initial_price);
  renderAuctionPurse();
  setAuctionConsignorBadge(true);
  setAuctionDeskConsignment(true);
  renderAuctionSeatStates();
  renderAuctionWay();
  if (pulse) pulseAuctionPrice();
}

// The hand on the player's own lot: the raise and the bid / drop buttons give way to the no-bid line.
function setAuctionDeskConsignment(consignment) {
  const desk = document.querySelector('#academy-auction-bid-bar');
  desk.toggleAttribute('data-consignment', consignment);
  document.querySelector('#academy-auction-desk-no-bid').hidden = !consignment;
}

// reason names the note that the hand itself raised ('short': the raise is over the purse) so the hand can take it
// down again when the raise comes back within the purse, without clearing a note from elsewhere.
function setAuctionBidNote(text, reason = null) {
  const note = document.querySelector('#academy-auction-bid-note');
  const message = String(text ?? '').trim();
  note.hidden = !message;
  note.textContent = message;
  if (message && reason) note.dataset.reason = reason;
  else delete note.dataset.reason;
}

function disableAuctionBidControls(disabled) {
  for (const selector of ['#academy-auction-bid-input', '#academy-auction-bid', '#academy-auction-drop']) {
    document.querySelector(selector).disabled = disabled;
  }
  if (!disabled) renderAuctionBidAffordance();
}

// A lot's raise starts at its minimum increment, written under the raise, before anyone bids — so the bid button
// carries an amount from the first look at the hand.
function primeAuctionRaise(lot) {
  const input = document.querySelector('#academy-auction-bid-input');
  input.min = String(lot.min_increment);
  input.value = String(lot.min_increment);
  document.querySelector('#academy-auction-raise-floor').textContent = `最低増分 ${lot.min_increment}G`;
  auctionBidAmountShown = null; // a new lot's amount is set, not counted from the last lot's
}

// The player's turn opens the hand: the raise starts at the lot's minimum increment.
function setAuctionBidBarActive(active, lot = null) {
  document.querySelector('#academy-auction-bid-bar').dataset.active = active ? 'true' : 'false';
  if (active && lot) primeAuctionRaise(lot);
  if (!active) setAuctionBidNote('');
  disableAuctionBidControls(!active);
}

// The raise the player has typed, or null while it is not a whole positive number (the bid button then reads 入札
// without an amount; pressing it says what is wrong).
function auctionRaiseAmount() {
  const add = Number(document.querySelector('#academy-auction-bid-input').value.trim());
  return Number.isInteger(add) && add > 0 ? add : null;
}

// The bid button carries the amount it would bid (the current price + the raise). On the player's turn a bid over
// the purse is told before any press: the note stands over the hand and the bid button is shut, the drop stays open.
function renderAuctionBidAffordance() {
  if (!auctionBidState) return;
  const add = auctionRaiseAmount();
  const next = add === null ? null : auctionBidState.current + add;
  renderAuctionBidAmount(next);
  const desk = document.querySelector('#academy-auction-bid-bar');
  if (desk.dataset.active !== 'true' || auctionActionInFlight) return;
  const short = next !== null && auctionMoney !== null && next > auctionMoney;
  document.querySelector('#academy-auction-bid').disabled = short;
  const note = document.querySelector('#academy-auction-bid-note');
  if (short) setAuctionBidNote(`入札額${next}Gが所持金${auctionMoney}Gを超えています。`, 'short');
  else if (note.dataset.reason === 'short') setAuctionBidNote('');
}

// The amount moves to its new value rather than jumping: it counts from the shown amount to the new one. With
// reduced motion it changes at once.
let auctionBidAmountShown = null;
let auctionBidAmountFrame = 0;
const AUCTION_BID_AMOUNT_MOVE_MS = 220;
function renderAuctionBidAmount(next) {
  const amount = document.querySelector('#academy-auction-bid-amount');
  cancelAnimationFrame(auctionBidAmountFrame);
  if (next === null) {
    auctionBidAmountShown = null;
    amount.textContent = '';
    return;
  }
  const from = auctionBidAmountShown;
  auctionBidAmountShown = next;
  if (from === null || from === next || window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    amount.textContent = `${next}G`;
    return;
  }
  const start = performance.now();
  const step = (now) => {
    const t = Math.min(1, (now - start) / AUCTION_BID_AMOUNT_MOVE_MS);
    const eased = 1 - (1 - t) ** 3;
    amount.textContent = `${Math.round(from + (next - from) * eased)}G`;
    if (t < 1) auctionBidAmountFrame = requestAnimationFrame(step);
  };
  auctionBidAmountFrame = requestAnimationFrame(step);
}

// ----- bid state machine -----

function initAuctionBidState(lot) {
  auctionBidState = {
    current: lot.initial_price,
    highestBidder: null,
    highestBidderName: null,
    history: [],
    activeNpcIds: new Set(auctionSlotView.bidders.map((bidder) => bidder.character_id)),
    playerActive: true
  };
}

function auctionActiveParticipantCount() {
  return auctionBidState.activeNpcIds.size + (auctionBidState.playerActive ? 1 : 0);
}

// The lot is ready to resolve when no one is left to raise: with a standing highest bid, when the only remaining
// active participant is that highest bidder (everyone else dropped); with no bid at all, only once everyone has
// dropped (a 流札). The current highest bidder never drops (they are skipped on their own turn), so an
// active-count of 1 with a standing bid is always the highest bidder alone.
function auctionLotResolutionReady() {
  const active = auctionActiveParticipantCount();
  if (auctionBidState.highestBidder === null) return active === 0;
  return active <= 1;
}

function requestAuctionNpcBid(lotIndex, bidder) {
  return postJson('/api/auction/npc-bid', {
    lot_index: lotIndex,
    character_id: bidder.character_id,
    current: auctionBidState.current,
    highest_bidder: auctionBidState.highestBidder,
    highest_bidder_name: auctionBidState.highestBidderName,
    history: auctionHistoryForRequest()
  });
}

// The bid history as the server takes it ({ display_name, action, amount? }); the seat id each entry also carries is
// this screen's own (it lights the seats).
function auctionHistoryForRequest() {
  return auctionBidState.history.map(({ display_name, action, amount }) => (action === 'bid' ? { display_name, action, amount } : { display_name, action }));
}

function applyAuctionNpcDecision(bidder, decision) {
  if (decision.action === 'bid') {
    auctionBidState.current = decision.current;            // server-revalidated standing amount
    auctionBidState.highestBidder = decision.highest_bidder; // = bidder.character_id
    auctionBidState.highestBidderName = bidder.display_name;
    auctionBidState.history.push({ character_id: bidder.character_id, display_name: bidder.display_name, action: 'bid', amount: decision.current });
  } else {
    auctionBidState.activeNpcIds.delete(bidder.character_id);
    auctionBidState.history.push({ character_id: bidder.character_id, display_name: bidder.display_name, action: 'pass' });
  }
}

// One sub-round of NPC bids over `askList` (this round's active, non-highest seated bidders, in seated order).
// 数珠つなぎ (1本先行・並列発射なし): the next bidder's request is fired as soon as the current bidder's decision
// returns (so the serial LM generates it while the current utterance reveals) — never two requests in flight.
async function runAuctionNpcSubRound(lotIndex, askList) {
  let pending = askList.length ? requestAuctionNpcBid(lotIndex, askList[0]) : null;
  for (let i = 0; i < askList.length; i += 1) {
    const bidder = askList[i];
    const decision = await pending;
    applyAuctionNpcDecision(bidder, decision);
    pending = (i + 1 < askList.length) ? requestAuctionNpcBid(lotIndex, askList[i + 1]) : null;
    await revealAuctionUtterance(bidder.character_id, decision.utterance);
    renderAuctionBoardFromState({ pulse: decision.action === 'bid' });
    if (auctionLotResolutionReady()) break;
  }
}

// Suspends the flow for the player's turn; resolved by the bid / drop sigil handlers (submitAuctionPlayerBid /
// submitAuctionPlayerPass), which continue the loop.
function runAuctionPlayerTurn(lot) {
  return new Promise((resolve) => {
    auctionPlayerResolve = resolve;
    setAuctionBidBarActive(true, lot);
  });
}

async function runAuctionBidLoop(lotIndex) {
  const lot = auctionLotView(lotIndex);
  initAuctionBidState(lot);
  primeAuctionRaise(lot);
  auctionLotGoaded = false;
  // A being lot with no free 錬成室 slot cannot be adopted: disable the player's bidding and say why (never a
  // silent hide). The player watches the seated bidders contest it.
  const playerCanBid = !(lot.category === 'being' && lot.adoptable === false);
  if (!playerCanBid) {
    auctionBidState.playerActive = false;
    setAuctionBidBarActive(false);
    setAuctionBidNote('錬成室の枠が空いていないため、この品には入札できません。');
  }
  renderAuctionBoardFromState();
  while (!auctionLotResolutionReady()) {
    const askList = auctionSlotView.bidders.filter((bidder) =>
      auctionBidState.activeNpcIds.has(bidder.character_id) && auctionBidState.highestBidder !== bidder.character_id);
    if (askList.length) await runAuctionNpcSubRound(lotIndex, askList);
    if (auctionLotResolutionReady()) break;
    if (auctionBidState.playerActive && auctionBidState.highestBidder !== AUCTION_PLAYER_WINNER_ID) {
      if (!auctionLotGoaded && auctionBidState.highestBidder !== null) {
        auctionLotGoaded = true;
        recordAuctionMasterUtterance(await revealAuctionSpeech({
          seat: AUCTION_MASTER_SEAT,
          endpoint: '/api/auction/lot/goad/stream',
          body: { lot_index: lotIndex, current: auctionBidState.current, bidder_name: auctionBidState.highestBidderName, prior_utterances: auctionMasterUtterances.slice() }
        }));
      }
      await runAuctionPlayerTurn(lot);
    }
    if (auctionLotResolutionReady()) break;
    // No NPC could be asked this round and the player is highest or has dropped: no further raise is possible.
    if (!askList.length && (auctionBidState.highestBidder === AUCTION_PLAYER_WINNER_ID || !auctionBidState.playerActive)) break;
  }
  await resolveAuctionCurrentLot(lotIndex);
}

async function submitAuctionPlayerBid() {
  if (!auctionPlayerResolve) return;
  if (auctionActionInFlight) { showProcessingToast(); return; }
  const lot = auctionCurrentLotView();
  if (!lot) return;
  const input = document.querySelector('#academy-auction-bid-input');
  const add = Number(input.value.trim());
  if (!Number.isInteger(add) || add <= 0) { setAuctionBidNote('上乗せ額は正の整数で入力してください。'); return; }
  if (add < lot.min_increment) { setAuctionBidNote(`最低増分は${lot.min_increment}Gです。それ以上を上乗せしてください。`); return; }
  const nextPrice = auctionBidState.current + add;
  if (auctionMoney !== null && nextPrice > auctionMoney) { setAuctionBidNote(`入札額${nextPrice}Gが所持金${auctionMoney}Gを超えています。`); return; }
  auctionActionInFlight = true;
  disableAuctionBidControls(true);
  try {
    const result = await postJson('/api/auction/bid', { lot_index: lot.lot_index, current: auctionBidState.current, add_amount: add });
    auctionBidState.current = result.current;
    auctionBidState.highestBidder = AUCTION_PLAYER_WINNER_ID;
    auctionBidState.highestBidderName = AUCTION_PLAYER_LABEL;
    auctionBidState.history.push({ character_id: AUCTION_PLAYER_WINNER_ID, display_name: AUCTION_PLAYER_LABEL, action: 'bid', amount: result.current });
    auctionMoney = result.money;
    setAuctionBidNote('');
    setAuctionBidBarActive(false);
    await appendAuctionPlayerNarration(`${result.current}Gで競り上げた。`);
    renderAuctionBoardFromState({ pulse: true });
    const resolve = auctionPlayerResolve;
    auctionPlayerResolve = null;
    resolve();
  } catch (error) {
    const reason = auctionBidErrorReason(error);
    if (reason) {
      setAuctionBidNote(reason);
    } else {
      reportAuctionScreenError(error, clearAuctionWayFailure);
    }
    disableAuctionBidControls(false); // let the player revise the amount and try again
  } finally {
    auctionActionInFlight = false;
  }
}

async function submitAuctionPlayerPass() {
  if (!auctionPlayerResolve) return;
  if (auctionActionInFlight) { showProcessingToast(); return; }
  const lot = auctionCurrentLotView();
  if (!lot) return;
  auctionActionInFlight = true;
  disableAuctionBidControls(true);
  try {
    await postJson('/api/auction/bid', { lot_index: lot.lot_index, pass: true });
    auctionBidState.playerActive = false;
    auctionBidState.history.push({ character_id: AUCTION_PLAYER_WINNER_ID, display_name: AUCTION_PLAYER_LABEL, action: 'pass' });
    setAuctionBidBarActive(false);
    await appendAuctionPlayerNarration('ここは見送ることにした。');
    renderAuctionBoardFromState();
    const resolve = auctionPlayerResolve;
    auctionPlayerResolve = null;
    resolve();
  } catch (error) {
    reportAuctionScreenError(error, clearAuctionWayFailure);
    disableAuctionBidControls(false);
  } finally {
    auctionActionInFlight = false;
  }
}

function auctionBidErrorReason(error) {
  if (error?.errorCode === 'AUCTION_BELOW_MIN_INCREMENT' || error?.errorCode === 'AUCTION_INSUFFICIENT_MONEY') {
    return error.message;
  }
  return null;
}

// Resolves the current lot: winner is the standing highest bidder ('player' | a seated character_id) or null
// (流札). An awarded lot gets the master's hammer 落札宣言 (streamed); a player win refreshes the authoritative
// money / equipment / inventory. A 流札 gets the authored 地の演出. On the third lot's resolution the auction
// closes and returns the closed view; otherwise the flow advances to the next lot.
async function resolveAuctionCurrentLot(lotIndex) {
  const lot = auctionLotView(lotIndex); // captured before the resolve reassigns auctionSlotView to the advanced slot
  const winner = auctionBidState.highestBidder;
  const amount = winner === null ? null : auctionBidState.current;
  setAuctionBidBarActive(false);
  const result = await postJson('/api/auction/lot/resolve', { lot_index: lotIndex, winner, amount });
  auctionSlotView = result.state;
  if (result.resolution.outcome === 'awarded') {
    recordAuctionMasterUtterance(await revealAuctionSpeech({ seat: AUCTION_MASTER_SEAT, endpoint: '/api/auction/lot/hammer/stream', body: { lot_index: lotIndex, prior_utterances: auctionMasterUtterances.slice() } }));
    if (winner === AUCTION_PLAYER_WINNER_ID) {
      await refresh();
      if (Number.isInteger(currentInventory?.money)) auctionMoney = currentInventory.money;
      renderAuctionPurse();
      // A 籠入りの生き物 win lands on the 星の揺り籠 caged surface, not in the inventory refresh above — name the
      // destination so the player sees where it went (the caged list itself picks it up on the next overlay open).
      if (lot.category === 'caged_creature') await appendAuctionNarration(auctionCagedCreatureAwardNarration(lot));
    }
  } else {
    await appendAuctionNarration(AUCTION_PASSED_IN_NARRATION);
  }
  if (result.resolution.closed) {
    // The third lot's 決着 speech (awarded: the hammer 口上 reveal / 流札: the authored 演出) is the last thing said
    // this visit. Hold it on screen for the shared reading pause (DRAIN_READING_PAUSE_MS — hub 見送り / 昼会話 達成
    // 自動終了 と単一ソース共有) before swapping to the closed view, so the closing words are legible instead of the
    // screen snapping away the moment they render.
    await sleep(DRAIN_READING_PAUSE_MS);
    renderAuctionClosed(auctionSlotView);
    return;
  }
  await appendAuctionNarration(nextAuctionMurmur());
  await runAuctionLot(auctionSlotView.current_lot_index);
}

// Runs one lot start-to-finish: master opening 口上 → seated-bidder reactions (prior_reactions chain) → bid loop.
async function runAuctionLot(lotIndex, { onOpeningStreamStart = null } = {}) {
  // The stage follows the lot whose 口上 is being heard. Drop the prior lot's bid states (initAuctionBidState only
  // runs once the bid loop starts, after the reactions) and paint this lot — fresh 初期額, no one lit — the instant
  // its opening 口上 stream begins (onStreamStart = first token), not after the reactions play out. The switch
  // composes with any caller onStreamStart (e.g. the entry wait ending on the first lot).
  auctionBidState = null;
  recordAuctionMasterUtterance(await revealAuctionSpeech({
    seat: AUCTION_MASTER_SEAT,
    endpoint: '/api/auction/lot/opening/stream',
    body: { lot_index: lotIndex, prior_utterances: auctionMasterUtterances.slice() },
    onStreamStart: () => { renderAuctionBoardFromState(); onOpeningStreamStart?.(); }
  }));
  const priorReactions = [];
  for (const bidder of auctionSlotView.bidders) {
    const result = await revealAuctionSpeech({
      seat: bidder.character_id,
      endpoint: '/api/auction/lot/reaction/stream',
      body: { lot_index: lotIndex, character_id: bidder.character_id, prior_reactions: priorReactions.slice() }
    });
    priorReactions.push({ display_name: result.display_name, utterance: result.utterance });
  }
  await runAuctionBidLoop(lotIndex);
}

// ----- 出品側 (player-consignment) lot -----

// True when this entry should open the 出品 picker: no consignment decided yet (未決) and the house lots have not
// begun (current_lot_index 0 — the consignment window). A resolved / skipped consignment, or house bidding already
// underway, skips the picker.
function auctionConsignmentNeedsPicker(view) {
  return view.consignment === null && view.current_lot_index === 0;
}

// The consignment bid state is the house bid-state shape with the player permanently inactive: the player never
// bids on their own lot, so only seated NPCs contest it. auctionLotResolutionReady / auctionActiveParticipantCount
// then resolve NPC-only (highest alone → awarded, everyone passed → 流札) with no player branch.
function initAuctionConsignmentBidState() {
  auctionBidState = {
    current: auctionConsignmentView.initial_price,
    highestBidder: null,
    highestBidderName: null,
    history: [],
    activeNpcIds: new Set(auctionSlotView.bidders.map((bidder) => bidder.character_id)),
    playerActive: false
  };
}

function requestAuctionConsignmentNpcBid(bidder) {
  return postJson('/api/auction/consignment/npc-bid', {
    character_id: bidder.character_id,
    current: auctionBidState.current,
    highest_bidder: auctionBidState.highestBidder,
    highest_bidder_name: auctionBidState.highestBidderName,
    history: auctionHistoryForRequest()
  });
}

// One NPC sub-round over the consignment lot, mirroring the house sub-round's 数珠つなぎ (1本先行・並列発射なし):
// the next bidder's request is fired as the current decision returns, never two in flight.
async function runAuctionConsignmentNpcSubRound(askList) {
  let pending = askList.length ? requestAuctionConsignmentNpcBid(askList[0]) : null;
  for (let i = 0; i < askList.length; i += 1) {
    const bidder = askList[i];
    const decision = await pending;
    applyAuctionNpcDecision(bidder, decision);
    pending = (i + 1 < askList.length) ? requestAuctionConsignmentNpcBid(askList[i + 1]) : null;
    await revealAuctionUtterance(bidder.character_id, decision.utterance);
    renderAuctionConsignmentBoardFromState({ pulse: decision.action === 'bid' });
    if (auctionLotResolutionReady()) break;
  }
}

// NPC-only round-robin over the consignment lot: seated order, pass = drop, the highest bidder skips its own turn,
// and it ends when only the highest remains (awarded) or everyone passed (流札). No player turn, no goad.
async function runAuctionConsignmentBidLoop() {
  initAuctionConsignmentBidState();
  renderAuctionConsignmentBoardFromState();
  while (!auctionLotResolutionReady()) {
    const askList = auctionSlotView.bidders.filter((bidder) =>
      auctionBidState.activeNpcIds.has(bidder.character_id) && auctionBidState.highestBidder !== bidder.character_id);
    if (!askList.length) break; // only the highest bidder (or no one) remains — already resolution-ready
    await runAuctionConsignmentNpcSubRound(askList);
  }
}

// Resolves the consignment lot: the winner is the standing highest NPC bidder (a seated character_id) or null (流札
// — the asset stays with the player). An awarded lot gets the master's hammer 落札宣言 (streamed) and credits the
// payout (payout.money is the authoritative post-credit money); a 流札 gets the authored 品が残る 地の演出. Either
// way the flow then advances to the house lots (the consignment does not advance the house slot).
async function resolveAuctionConsignmentLot() {
  const winner = auctionBidState.highestBidder; // a seated character_id or null — never 'player'
  const amount = winner === null ? null : auctionBidState.current;
  const result = await postJson('/api/auction/consignment/resolve', { winner, amount });
  auctionConsignmentView = result.consignment;
  if (result.resolution.outcome === 'awarded') {
    recordAuctionMasterUtterance(await revealAuctionSpeech({
      seat: AUCTION_MASTER_SEAT,
      endpoint: '/api/auction/consignment/hammer/stream',
      body: { prior_utterances: auctionMasterUtterances.slice() }
    }));
    // An awarded consignment always credits the player: payout.money is the contract-guaranteed authoritative
    // post-credit balance. A missing / non-integer payout.money is a broken upstream
    // contract, not a display default — fail fast rather than silently leaving stale money on screen.
    if (!result.payout || !Number.isInteger(result.payout.money)) {
      throw new Error('auction consignment awarded resolve is missing an authoritative payout.money');
    }
    auctionMoney = result.payout.money; // the removed asset itself shows on the next refresh
    renderAuctionConsignmentBoardFromState();
  } else {
    await appendAuctionNarration(AUCTION_CONSIGNMENT_PASSED_IN_NARRATION);
  }
  setAuctionConsignorBadge(false);
  auctionPhase = 'house';
  await appendAuctionNarration(nextAuctionMurmur());
  await runAuctionLot(auctionSlotView.current_lot_index);
}

// Runs the consignment lot start-to-finish: master 出品披露口上 (its prior_utterances is empty — the first speech of
// the visit) → seated-bidder reactions (prior_reactions chain) → NPC-only bid loop → resolve → on to the house lots.
async function runAuctionConsignmentLot({ onOpeningStreamStart = null } = {}) {
  showAuctionLive();
  renderAuctionConsignmentBoardFromState();
  recordAuctionMasterUtterance(await revealAuctionSpeech({
    seat: AUCTION_MASTER_SEAT,
    endpoint: '/api/auction/consignment/opening/stream',
    body: { prior_utterances: auctionMasterUtterances.slice() },
    onStreamStart: onOpeningStreamStart
  }));
  const priorReactions = [];
  for (const bidder of auctionSlotView.bidders) {
    const result = await revealAuctionSpeech({
      seat: bidder.character_id,
      endpoint: '/api/auction/consignment/reaction/stream',
      body: { character_id: bidder.character_id, prior_reactions: priorReactions.slice() }
    });
    priorReactions.push({ display_name: result.display_name, utterance: result.utterance });
  }
  await runAuctionConsignmentBidLoop();
  await resolveAuctionConsignmentLot();
}

// ----- 出品 picker (asset selection before the house lots) -----

// Renders the 出品 window: one row per consignable asset (unequipped equipment + sell_price>0 持ち物 + 籠入りの生き物)
// — its picture, its name (with the held count for a 持ち物), what it is (kind・属性・T・売値, each where the asset has
// it) and the lot it would open as (開始値・最低増分) — and the 出品する button that lists it at once. Every value
// comes straight from the options view (the frontend never re-derives a band, a price or a label). An empty list
// says so in words, says what can be consigned, and the one button goes on to the first lot.
function renderAuctionConsignmentOptions(options) {
  const list = document.querySelector('#academy-auction-consignment-options');
  const empty = document.querySelector('#academy-auction-consignment-empty');
  // The options contract always carries all three arrays. A missing array is a broken
  // upstream shape, not an empty-list default — fail fast rather than silently rendering nothing.
  if (!Array.isArray(options.equipment) || !Array.isArray(options.items) || !Array.isArray(options.caged)) {
    throw new Error('auction consignment options must carry equipment, items, and caged arrays');
  }
  const entries = [...options.equipment, ...options.items, ...options.caged];
  const rows = entries.map((entry, order) => auctionConsignmentRow(entry, order));
  const isEmpty = entries.length === 0;
  list.hidden = isEmpty;
  empty.hidden = !isEmpty;
  document.querySelector('#academy-auction-consignment-outcomes').hidden = isEmpty;
  document.querySelector('#academy-auction-consignment-skip').textContent = isEmpty ? '一品目へ' : '出品しない';
  if (isEmpty) renderAuctionConsignmentEmpty(empty);
  else empty.replaceChildren();
  list.replaceChildren(...rows);
}

function renderAuctionConsignmentEmpty(empty) {
  const art = fillWithEmptyArt(document.createElement('span'), 'pouch', '出品できる品がありません');
  art.className = 'academy-auction-consignment-empty-art';
  art.setAttribute('aria-hidden', 'true');
  const title = document.createElement('p');
  title.className = 'academy-auction-consignment-empty-title';
  title.textContent = '出品できる品がありません';
  const scope = document.createElement('p');
  scope.className = 'academy-auction-consignment-empty-scope';
  // ui-prose-exception: msg_20261007T034129+0900_85835_YB57GQ
  scope.textContent = '出品できるもの：外している装備・売値のある持ち物・籠入りの生き物';
  empty.replaceChildren(art, title, scope);
}

// One consignable asset as a row. element / tier / sell_price / art are null where the asset has none (a 持ち物 that
// is not a dungeon material, a 籠入りの生き物's tier and sell price, an equipment's picture); any other value missing
// is a broken options view and fails fast.
function auctionConsignmentRow(entry, order) {
  for (const key of ['name', 'category_label']) {
    if (typeof entry[key] !== 'string' || entry[key] === '') throw new Error(`auction consignment option has no ${key}: ${JSON.stringify(entry)}`);
  }
  for (const key of ['initial_price', 'min_increment']) {
    if (!Number.isInteger(entry[key])) throw new Error(`auction consignment option has no ${key}: ${JSON.stringify(entry)}`);
  }
  for (const key of ['element', 'tier', 'sell_price', 'art']) {
    if (!Object.hasOwn(entry, key)) throw new Error(`auction consignment option has no ${key}: ${JSON.stringify(entry)}`);
  }
  // Source shape by kind (出品側): a 持ち物 is keyed by item_id, an equipment instance and a caged creature both by
  // instance_id. An unknown kind is caught by the backend's closed-vocab submit gate, not silently mis-shaped here.
  const source = entry.kind === 'item'
    ? { kind: 'item', item_id: entry.item_id }
    : { kind: entry.kind, instance_id: entry.instance_id };
  const li = document.createElement('li');
  li.className = 'academy-auction-consignment-row';
  li.style.setProperty('--row-order', String(order));
  const art = document.createElement('span');
  art.className = 'academy-auction-consignment-art';
  if (entry.art !== null) {
    const image = document.createElement('img');
    image.src = entry.art;
    image.alt = '';
    art.append(image);
  }
  const text = document.createElement('div');
  text.className = 'academy-auction-consignment-text';
  const head = document.createElement('p');
  head.className = 'academy-auction-consignment-name-line';
  const name = document.createElement('span');
  name.className = 'academy-auction-consignment-name';
  name.id = `academy-auction-consignment-name-${order}`;
  name.textContent = entry.name;
  head.append(name);
  if (entry.kind === 'item') {
    if (!Number.isInteger(entry.quantity)) throw new Error(`auction consignment item has no quantity: ${JSON.stringify(entry)}`);
    const held = document.createElement('span');
    held.className = 'academy-auction-consignment-held';
    held.textContent = `所持 ×${entry.quantity}`;
    head.append(held);
  }
  const what = document.createElement('p');
  what.className = 'academy-auction-consignment-what';
  what.textContent = [
    entry.category_label,
    entry.element === null ? null : `属性${auctionElementLabel(entry.element)}`,
    entry.tier === null ? null : `T${entry.tier}`,
    entry.sell_price === null ? null : `売値 ${entry.sell_price}G`
  ].filter((part) => part !== null).join('・');
  const lot = document.createElement('p');
  lot.className = 'academy-auction-consignment-lot';
  lot.textContent = `開始値 ${entry.initial_price}G・最低増分 ${entry.min_increment}G`;
  text.append(head, what, lot);
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'academy-auction-word-button academy-auction-consignment-option';
  button.dataset.kind = entry.kind;
  button.textContent = '出品する';
  button.setAttribute('aria-describedby', name.id);
  button.addEventListener('click', () => submitAuctionConsignmentChoice(source));
  li.append(art, text, button);
  return li;
}

function auctionElementLabel(element) {
  const label = DUNGEON_MAGIC_LABELS[element];
  if (!label) throw new Error(`auction consignment option has an unknown element: ${JSON.stringify(element)}`);
  return label;
}

function awaitAuctionConsignmentChoice() {
  return new Promise((resolve) => { auctionConsignmentChoiceResolve = resolve; });
}

function setAuctionConsignmentPickerBusy(busy) {
  document.querySelector('#academy-auction-consignment-skip').disabled = busy;
  for (const button of document.querySelectorAll('.academy-auction-consignment-option')) button.disabled = busy;
}

function submitAuctionConsignmentChoice(source) {
  if (!auctionConsignmentChoiceResolve) return;
  setAuctionConsignmentPickerBusy(true);
  const resolve = auctionConsignmentChoiceResolve;
  auctionConsignmentChoiceResolve = null;
  resolve({ kind: 'submit', source });
}

function skipAuctionConsignmentChoice() {
  if (!auctionConsignmentChoiceResolve) return;
  setAuctionConsignmentPickerBusy(true);
  const resolve = auctionConsignmentChoiceResolve;
  auctionConsignmentChoiceResolve = null;
  resolve({ kind: 'skip' });
}

// After the picker choice: submit lists the asset (POST submit) and runs the consignment lot; skip records the
// terminal skip (POST skip) and goes straight to the house lots. Runs as the session promise (kept in flight so
// the entry re-entrant guard holds through the whole visit).
async function runAuctionConsignmentPhaseAfterPicker() {
  const choice = await awaitAuctionConsignmentChoice();
  if (choice.kind === 'submit') {
    const view = await postJson('/api/auction/consignment/submit', { source: choice.source });
    auctionConsignmentView = view;
    auctionPhase = 'consignment';
    await runAuctionConsignmentLot();
  } else {
    await postJson('/api/auction/consignment/skip', {});
    auctionPhase = 'house';
    showAuctionLive();
    renderAuctionBoardFromState();
    await runAuctionLot(auctionSlotView.current_lot_index);
  }
}

// ----- entry / resume / closed view -----

// Clears every prior-visit view residue before an auction entry decides closed vs live. The auction is
// lot-granular and never persists in-lot progress, so a reload / re-entry restarts the current lot's bidding from
// the top — no prior-visit words, seat states, or hand state is ever valid on screen.
function resetAuctionScreenView() {
  auctionSlotView = null;
  auctionBidState = null;
  auctionLotGoaded = false;
  auctionMasterUtterances = []; // fresh visit: the 反復回避ハンドオフ accumulates only this visit's 口上
  auctionConsignmentView = null;       // fresh visit: no listed asset carried over
  auctionConsignmentChoiceResolve = null; // drop any dangling picker promise from a prior visit
  auctionPhase = null;
  auctionWords = [];
  renderAuctionWords({ cut: true });
  renderAuctionSeatStates();
  document.querySelector('#academy-auction-consignment-options').replaceChildren(); // clear any prior visit's 出品 options
  setAuctionConsignmentPickerBusy(false); // clear the picker busy residue: the static skip sigil stays disabled across visits otherwise (option buttons are rebuilt, but #academy-auction-consignment-skip is the same node)
  setAuctionConsignorBadge(false);
  setAuctionDeskConsignment(false);
  hideAuctionConsignmentPicker();
  setAuctionBidBarActive(false);
  setAuctionBidNote('');
  clearAuctionWayFailure();
}

// Called by showScreen('academy-auction'). Resets the view (no prior-visit residue), then GETs the weekly slot
// state: a closed week renders the closed view; a selection (未開催) / in-progress week enters-or-resumes and runs
// the session under the wait over the auction (placeVeilForArrival) that ends on the first opening 口上 stream
// (M-2026-07-06-001). A hub dispatch's arrival carries the send-off's wait onto the auction screen, so the state GET
// already runs under it; the auctionFlowInFlight guard makes a showScreen('academy-auction') during the visit a no-op
// re-entry (so the reset runs once per genuine entry, never mid-session). A failed state GET leaves the screen with
// nothing to go on with, so it returns to the hub whatever the entrance (the hub dispatch's arrival, the dev
// ?initialScreen entry, the reload resume of an auction in progress), sinking a carried wait into the night first.
async function enterOrResumeAuctionScreen({ routingArrival }) {
  if (auctionFlowInFlight) return;
  resetAuctionScreenView();
  let state;
  try {
    state = await getJson('/api/auction/state');
  } catch (error) {
    if (placeVeilWaiting() && settingsRedirectErrorMessage(error) == null) await stopPlaceVeil();
    returnToRoutingHubAfterArrivalFailure(error, routingFailedArrival(routingArrival, 'academy-auction'));
    return;
  }
  if (state.phase === 'closed') {
    if (placeVeilWaiting()) placeVeilArrived();
    renderAuctionClosed(state);
    return;
  }
  await runAuctionSession({ routingArrival });
}

async function runAuctionSession({ routingArrival }) {
  auctionFlowInFlight = true;
  auctionMoney = Number.isInteger(currentInventory?.money) ? currentInventory.money : null;
  let arrived = false;
  try {
    let openingStartedResolve = null;
    let openingStartedResolved = false;
    const openingStarted = new Promise((resolve) => { openingStartedResolve = resolve; });
    const markOpeningStarted = () => {
      if (openingStartedResolved) return;
      openingStartedResolved = true;
      openingStartedResolve?.();
    };
    let sessionPromise = Promise.resolve();
    placeVeilForArrival('academy-auction');
    const readiness = (async () => {
      const view = await postJson('/api/auction/enter', {}); // build the week slot (selection) or resume it (in-progress)
      auctionSlotView = view;
      if (view.status === 'closed') { auctionPhase = 'closed'; markOpeningStarted(); renderAuctionClosed(view); return; }
      // The week's seats (the master and the seated bidders' matted faces) are set before anyone speaks.
      await renderAuctionSeats();
      if (auctionConsignmentNeedsPicker(view)) {
        // 出品 window: fetch the consignable assets and reveal the picker. There is no opening stream to wait on
        // here, so the wait ends as soon as the picker is on screen (the visit continues on the player's submit / skip
        // choice as the session promise).
        auctionPhase = 'picker';
        const options = await getJson('/api/auction/consignment/options');
        renderAuctionConsignmentOptions(options); // the window takes its final size before it is shown
        showAuctionConsignmentPicker();
        markOpeningStarted();
        sessionPromise = runAuctionConsignmentPhaseAfterPicker();
      } else if (view.consignment && view.consignment.status === 'listed') {
        // Resume onto a still-listed consignment lot: re-run it from the top (per-lot restart), then the house lots.
        auctionPhase = 'consignment';
        auctionConsignmentView = view.consignment;
        sessionPromise = runAuctionConsignmentLot({ onOpeningStreamStart: markOpeningStarted });
      } else {
        // Consignment resolved / skipped (or house bidding already underway): go straight to the house lots.
        auctionPhase = 'house';
        showAuctionLive();
        sessionPromise = runAuctionLot(view.current_lot_index, { onOpeningStreamStart: markOpeningStarted });
      }
      await Promise.race([openingStarted, sessionPromise]);
    })();
    await awaitUnderPlaceVeil(readiness);
    arrived = true;
    placeVeilArrived();
    if (auctionPhase === 'picker') revealAuctionConsignmentRows();
    if (auctionSlotView?.status !== 'closed') {
      if (auctionPhase === 'consignment') renderAuctionConsignmentBoardFromState();
      else if (auctionPhase === 'house') renderAuctionBoardFromState();
      // 'picker': the 出品 picker is shown; no lot render until submit / skip picks the lot.
    }
    await sessionPromise;
  } catch (error) {
    // Wait-residual defense: a failed auction entry / resume must not strand the player under the wait (it has sunk
    // into the night in awaitUnderPlaceVeil). Auction is routing-only content, so un-strand to the routing hub opened
    // anew whatever the entrance — the same landing a failed routing arrival takes, with the failure notice naming the
    // destination — then re-raise so the caller's reportAuctionScreenError logs it once. A settings-redirect error
    // already left for the settings screen (reportLoadingError), so the guard skips.
    if (!arrived && settingsRedirectErrorMessage(error) == null) {
      await returnToRoutingHubThroughLoadingScreen({ failedArrival: routingFailedArrival(routingArrival, 'academy-auction') });
    }
    throw error;
  } finally {
    auctionFlowInFlight = false;
    setAuctionBidBarActive(false);
  }
}

// 閉場: the way is all done, the night's results stand on the stage, and the exit sigil (only now) goes back to the hub.
function renderAuctionClosed(state) {
  auctionSlotView = state;
  auctionPhase = 'closed';
  document.querySelector('#academy-auction-live').hidden = true;
  document.querySelector('#academy-auction-closed').hidden = false;
  document.querySelector('#academy-auction-consignment').hidden = true;
  const list = document.querySelector('#academy-auction-closed-results');
  const bidderName = (id) => state.bidders.find((bidder) => bidder.character_id === id)?.display_name ?? id;
  list.replaceChildren(...state.lots.map((lot, index) => {
    const award = state.awards[index] ?? null;
    const li = document.createElement('li');
    const result = !award
      ? 'pending'
      : award.outcome === 'passed_in'
        ? 'passed_in'
        : award.winner_character_id === AUCTION_PLAYER_WINNER_ID ? 'won_by_player' : 'won_by_other';
    li.dataset.result = result;
    const head = `「${lot.name}」`;
    li.textContent = result === 'won_by_player'
      ? `${head} … ${award.amount}Gで落札`
      : result === 'won_by_other'
        ? `${head} … ${bidderName(award.winner_character_id)}が${award.amount}Gで落札`
        : result === 'passed_in'
          ? `${head} … 流札`
          : `${head} … 未確定`;
    return li;
  }));
  renderAuctionWay();
}

// 競売場を出る: routing-only content, so the return is always the routing hub (AUCTION_POST_CONTENT_SCREEN), taken
// through the shared content return over the place's art and guarded by routingContentReturnInFlight.
async function exitAuction() {
  if (routingContentReturnInFlight) { showProcessingToast(); return; }
  routingContentReturnInFlight = true;
  try {
    await returnToRoutingHubFromContent(AUCTION_POST_CONTENT_SCREEN);
  } finally {
    routingContentReturnInFlight = false;
  }
}

document.querySelector('#academy-auction-bid').addEventListener('click', () => submitAuctionPlayerBid().catch((error) => reportAuctionScreenError(error, clearAuctionWayFailure)));
document.querySelector('#academy-auction-drop').addEventListener('click', () => submitAuctionPlayerPass().catch((error) => reportAuctionScreenError(error, clearAuctionWayFailure)));
const exitAuctionFromSigil = () => exitAuction().catch((error) => reportAuctionScreenError(error, exitAuctionFromSigil));
dressSigilButton(document.querySelector('#academy-auction-exit'), 'back', 'ハブへ戻る').addEventListener('click', exitAuctionFromSigil);
document.querySelector('#academy-auction-consignment-skip').addEventListener('click', () => skipAuctionConsignmentChoice());
document.querySelector('#academy-auction-bid-input').addEventListener('input', () => renderAuctionBidAffordance());
document.querySelector('#academy-auction-bid-input').addEventListener('keydown', (event) => {
  if (event.key === 'Enter') {
    event.preventDefault();
    submitAuctionPlayerBid().catch((error) => reportAuctionScreenError(error, clearAuctionWayFailure));
  }
});

// ===== 談話室 (lounge) screen =====
// The lounge's own art is the whole screen (unblurred); the three participants sit in the three seats of a ring — the
// near left, the far side of the table, the near right — and the player is the missing seat on this side of the
// screen. Each word rides above the head of whoever said it (older words fade); only the one speaking now carries the
// room's light. The faces are matted and lit by the conversation layer's parts (stageLight / litFace / faceFade), the
// same look the five conversations give a person. It drives itself from the frontend across the lounge per-utterance
// HTTP surface (spec loungeApi): each assistant message carries its OWN speaker identity (character_id /
// character_name / emotion), preserved end-to-end so every word lands over the right seat. The group path NEVER
// re-labels every message to one active character (the 1:1 messagesFromConversation trap) —
// loungeMessagesFromConversation keeps per-message identity and a clicked word's or seat's data-character-id
// resolves WHICH participant it belongs to. A round is NPC1→NPC2→NPC3 (server-shuffled
// order) then the player; the server group record is the authoritative cursor and every request re-validates the
// client-carried cursor. Reaching it is the routing hub dispatch (lounge → academy-lounge); ending it is the
// player's explicit 退出 → aggregate finalization + content-return to the hub.

// Dedicated 「寮の談話室」 stage art for the screen's ground + the stage-detail popup. The authored scene TEXT
// (location_name 「寮の談話室」+ the week-seeded visible_situation) is server-authoritative: the name is the stage-name
// button at the top left, and the popup it opens shows the name + the situation.
const LOUNGE_STAGE_IMAGE_URL = '/canonical/lounge/stage.jpg';

// The ring's seats, in the participants' order (the week-seeded draw): the near left, the far side of the table, the
// near right. The player's words take the fourth place (the missing seat, the lower middle).
const LOUNGE_SEATS = Object.freeze(['left', 'far', 'right']);
// character_id → { seat, node, image, src, request } for the visit in progress (rebuilt on each entry).
const loungeSeats = new Map();
// Participants who left mid-talk this visit. Their seat stays empty (nobody moves into it). A departure turn is the
// one utterance that carries two assistant messages (the normal line, then the leaving line — spec C-29 v2).
const loungeDeparted = new Set();

// Lounge session state (frontend-carried; not persisted — the server group record is the truth source).
let loungeConversation = null;     // last authoritative conversation view (enter / utterance result / player-turn)
let loungeFlowInFlight = false;    // guards the re-entrant showScreen during the entry loading transition
let loungeActionInFlight = false;  // single-flight guard for a player round-closing turn submission
let loungePlayerResolve = null;    // resolves the pending player-turn promise when 送信 / 退出 is pressed

// Group-aware conversation → chat-message mapper: keeps each assistant message's OWN speaker identity + emotion
// (the fix for the 1:1 messagesFromConversation re-label). User messages are the player's words. The server group
// record validates that every assistant message carries both emotion fields, so a missing one is a malformed
// authoritative payload — reject it rather than mask it with a neutral face.
function loungeMessagesFromConversation(conversation) {
  return (conversation?.messages ?? []).filter((message) => message.role === 'user' || message.role === 'assistant').map((message) => {
    if (message.role === 'assistant') {
      if (typeof message.expression !== 'string' || typeof message.face_emotion_variant_id !== 'string') {
        throw new Error(`lounge assistant message is missing emotion fields: ${message.character_id ?? '(no character_id)'}`);
      }
      return {
        role: 'assistant',
        character_id: message.character_id,
        character_name: message.character_name,
        content: message.content ?? '',
        expression: message.expression,
        face_emotion_variant_id: message.face_emotion_variant_id
      };
    }
    return { role: 'user', content: message.content ?? '' };
  });
}

// One assistant message carrying its OWN speaker identity + the turn's confirmed emotion (the seat resolves
// the face via sourceSheetImageUrl per message from these fields). Used for the streamed reveal segments; the final
// committed history comes from the server-authoritative conversation view. The emotion is REQUIRED — a reveal
// segment must never be built before the turn's emotion is confirmed, so there is no neutral fallback: a missing
// emotion is a protocol violation (assistant content arrived before assistant_emotion) and fails fast.
function loungeMessage(speaker, content, emotion) {
  if (!emotion || typeof emotion.expression !== 'string' || typeof emotion.face_emotion_variant_id !== 'string') {
    throw new Error('lounge reveal segment requires a confirmed emotion (assistant content before assistant_emotion)');
  }
  return {
    role: 'assistant',
    character_id: speaker.character_id,
    character_name: speaker.character_name,
    content,
    expression: emotion.expression,
    face_emotion_variant_id: emotion.face_emotion_variant_id
  };
}

// The lounge's display segments: displayMessages, with each assistant 仕草 (the 括弧 part the split turns into a
// narration segment) keeping the speaker it belongs to, so it rides over the same seat. Feeding the result back in is
// idempotent (a narration segment passes through displayMessages unchanged, its speaker kept).
function loungeDisplayMessages(messages) {
  return messages.flatMap((message) => displayMessages([message]).map((segment) => (segment.role === 'narration' && message.role !== 'narration'
    ? { ...segment, character_id: message.character_id, character_name: message.character_name }
    : segment)));
}

function loungeSeat(characterId) {
  const seat = loungeSeats.get(characterId);
  if (!seat) throw new Error(`lounge: ${characterId} has no seat (not a participant of this visit)`);
  return seat;
}

// The room's light (read from the lounge art once by the conversation layer), carried on the screen for the speaking
// glow; every face is lit with it.
async function loungeStageLight() {
  const light = await stageLight(LOUNGE_STAGE_IMAGE_URL);
  screens['academy-lounge'].style.setProperty('--lounge-light-rgb', light.join(' '));
  return light;
}

// Put the face for `expression` in a seat: the face art matted and lit by the room's light, with the dissolve the
// conversation layer picks for it (head / window). A newer request for the same seat wins; the same face is not
// redrawn.
async function showLoungeSeatFace(characterId, expression) {
  const seat = loungeSeat(characterId);
  const src = sourceSheetImageUrl({ expression, view: 'face', characterId });
  if (seat.src === src) return;
  seat.src = src;
  const request = ++seat.request;
  const light = await loungeStageLight();
  const [lit, fade] = await Promise.all([litFace(src, light), faceFade(src)]);
  if (request !== seat.request) return;
  const image = new Image();
  image.src = lit;
  await image.decode();
  if (request !== seat.request) return;
  seat.image.src = lit;
  seat.node.dataset.faceFade = fade;
  seat.node.dataset.expression = expression;
}

// Seat the three participants of the visit (participants[0..2] → the near left, the far side, the near right) with
// their neutral faces. Resolves when the three faces are drawn.
function seatLoungeParticipants(participants) {
  if (!Array.isArray(participants) || participants.length !== LOUNGE_SEATS.length) {
    throw new Error(`lounge: expected ${LOUNGE_SEATS.length} participants, got ${JSON.stringify(participants)}`);
  }
  const seats = document.querySelector('#academy-lounge-seats');
  if (!seats) throw new Error('lounge seats node #academy-lounge-seats is missing (broken markup wiring)');
  loungeSeats.clear();
  const nodes = participants.map((participant, index) => {
    if (typeof participant?.character_id !== 'string' || typeof participant.character_name !== 'string' || !participant.character_name) {
      throw new Error(`lounge participant ${index} has no character_id / character_name: ${JSON.stringify(participant)}`);
    }
    const node = document.createElement('button');
    node.type = 'button';
    node.className = 'lounge-seat';
    node.dataset.seat = LOUNGE_SEATS[index];
    node.dataset.characterId = participant.character_id;
    const well = document.createElement('span');
    well.className = 'lounge-seat-well';
    const image = document.createElement('img');
    image.alt = '';
    well.append(image);
    const name = document.createElement('span');
    name.className = 'lounge-seat-name';
    name.textContent = participant.character_name;
    node.append(well, name);
    loungeSeats.set(participant.character_id, { seat: LOUNGE_SEATS[index], node, image, src: null, request: 0 });
    return node;
  });
  seats.replaceChildren(...nodes);
  return Promise.all(participants.map((participant) => showLoungeSeatFace(participant.character_id, 'neutral')));
}

// Bring the seats up to the words on screen: each face takes the expression of its person's newest line, the room's
// light rests on whoever spoke the newest word (no one when the player did), and a seat whose person left is empty.
function followLoungeSeats(displayList) {
  const expressions = new Map();
  let speaking = null;
  for (const segment of displayList) {
    if (segment.role === 'assistant') expressions.set(segment.character_id, segment.expression);
    speaking = segment.role === 'assistant' || segment.role === 'narration' ? segment.character_id : null;
  }
  for (const [characterId, seat] of loungeSeats) {
    seat.node.toggleAttribute('data-speaking', characterId === speaking);
    seat.node.toggleAttribute('data-departed', loungeDeparted.has(characterId));
    if (expressions.has(characterId)) showLoungeSeatFace(characterId, expressions.get(characterId)).catch(reportLoungeScreenError);
  }
}

// The stage's row renderer for the lounge: the words as four voices — one over each seat and the player's at the lower
// middle — stacked from the bottom, each word carrying its age (0 = the newest) for the fade. The 仕草 lines are the
// quiet words. Returns the four voice nodes the stage puts in the stream.
function loungeVoices(displayList, popFromDisplayIndex) {
  const voices = new Map(['left', 'far', 'right', 'player'].map((seat) => {
    const voice = document.createElement('div');
    voice.className = 'lounge-voice';
    voice.dataset.seat = seat;
    return [seat, voice];
  }));
  displayList.forEach((segment, index) => {
    const player = segment.role === 'user' || segment.role === 'player-narration';
    const word = document.createElement('p');
    word.className = 'lounge-word';
    if (segment.role === 'narration' || segment.role === 'player-narration') word.classList.add('is-gesture');
    if (!player) word.dataset.characterId = segment.character_id;
    if (!player && popFromDisplayIndex >= 0 && index >= popFromDisplayIndex) word.classList.add('is-new');
    word.style.setProperty('--lounge-age', String(displayList.length - 1 - index));
    word.textContent = segment.content ?? '';
    voices.get(player ? 'player' : loungeSeat(segment.character_id).seat).append(word);
  });
  followLoungeSeats(displayList);
  return [...voices.values()];
}

const loungeStage = createConversationStage({
  screenSelector: '#academy-lounge-screen',
  streamSelector: '#academy-lounge-message-stream',
  statusSelector: '#academy-lounge-status',
  controlSelectors: ['#academy-lounge-input', '#academy-lounge-send', '#academy-lounge-end'],
  respondingClass: 'is-day-responding',
  playerSpokeClass: 'is-day-player-spoke',
  dispatchClimaxClass: 'is-day-dispatch-climax',
  playerSpokeMs: 600,
  dispatchClimaxMs: 900,
  // No week / moon (the lounge shows neither) and no persona standee: the three participants sit in their seats, so
  // renderScreen's standee/speaker blocks are guarded no-ops (the daytime stage 流儀).
  personaVisual: () => null,
  // Multiple speakers, so there is no single assistant identity; the group mapper keeps each message's identity.
  // This inert value only feeds the shared surface's assistantIdentity seam (unused by the consumer-owned
  // per-utterance reader below).
  assistantIdentity: () => ({ character_id: null, character_name: '' }),
  refresh: () => refresh(),
  // No info drawer / category rail: these selectors resolve to no nodes, so openInfo/closeInfo are guarded no-ops
  // (the auction 流儀).
  infoPopupSelector: '#academy-lounge-info-popup',
  infoTitleSelector: '#academy-lounge-info-popup-title',
  infoBodySelector: '#academy-lounge-info-popup-body',
  infoIconSelector: '#academy-lounge-info-popup-icon',
  categoryButtonSelector: '.academy-lounge-category-button',
  categoryDataKey: 'loungeCategory',
  categoryTitles: {},
  categoryIconUrl: () => '',
  categoryRenderers: {}
}, {
  // The stream is the voices (words over the seats), not chat rows.
  displayMessages: loungeDisplayMessages,
  createMessageRows: (displayList, popFromDisplayIndex) => loungeVoices(displayList, popFromDisplayIndex),
  messagesFromConversation: loungeMessagesFromConversation,
  conversationPopupCooldownMs,
  sleep,
  setActorImageSource
});

function reportLoungeScreenError(error) {
  if (handleRuntimeApiError(error, { allowSettingsRedirect: true })) return;
  loungeStage.setStatus(errorDisplayMessage(error), { tone: 'error' });
  console.error(error);
}

// Consumer-owned SSE reader for one NPC utterance. Frames events exactly like the shared / auction stream helper
// (event:/data: over \n\n blocks) but understands the lounge event列: status → assistant_emotion →
// assistant_delta* → assistant_complete (one for a continue turn, two for a depart turn — Stage 2 契約) →
// [lounge_draining → lounge_finalization_progress* on all-exited] → result. The emotion always arrives before the
// first delta so the turn's face is fixed before any bubble reveals. onStreamStart fires once on the first token so
// the entry loading cover can release on the first utterance's first stream. The lounge_draining /
// lounge_finalization_progress events are progress signals the reader does not act on — the terminal `result` carries
// the completion payload the auto path validates and hands off to the hub return (runLoungeAutoCompletion).
async function readLoungeUtteranceSse(body, { onDelta, onComplete, onEmotion, onStreamStart = null }) {
  const endpoint = '/api/lounge/utterance/stream';
  const response = await fetch(endpoint, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(body)
  });
  if (!response.ok) {
    const text = await response.text();
    throw createApiError({ url: endpoint, status: response.status, payload: parseJsonText(text), fallbackText: text });
  }
  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = '';
  let finalResult = null;
  let streamStarted = false;
  const notifyStreamStarted = () => {
    if (streamStarted) return;
    streamStarted = true;
    onStreamStart?.();
  };
  const handleBlock = (block) => {
    const event = block.split('\n').find((line) => line.startsWith('event: '))?.slice(7);
    const dataText = block.split('\n').find((line) => line.startsWith('data: '))?.slice(6);
    const data = dataText ? JSON.parse(dataText) : null;
    if (event === 'assistant_delta') { notifyStreamStarted(); onDelta(data.delta ?? ''); }
    if (event === 'assistant_emotion') { onEmotion?.({ expression: data.expression, face_emotion_variant_id: data.face_emotion_variant_id }); }
    if (event === 'assistant_complete') { notifyStreamStarted(); onComplete(data.content ?? ''); }
    if (event === 'result') finalResult = data;
    if (event === 'error') throw createApiError({ url: endpoint, status: 503, payload: data, fallbackText: data?.error ?? '' });
  };
  while (true) {
    const { value, done } = await reader.read();
    buffer += decoder.decode(value ?? new Uint8Array(), { stream: !done });
    const blocks = buffer.split('\n\n');
    buffer = blocks.pop() ?? '';
    for (const block of blocks) if (block.trim()) handleBlock(block);
    if (done) break;
  }
  if (buffer.trim()) handleBlock(buffer);
  if (!finalResult) throw new Error('lounge utterance stream ended without a final result');
  return finalResult;
}

// Streams one NPC utterance, revealing completed 吹き出し単位 through the shared reveal queue as they arrive, then
// adopts the server-authoritative conversation view (each message keeps its own speaker identity + final emotion).
// On failure the reveal is cancelled and the pre-utterance history is restored (no half-revealed bubble left).
//
// v2 契約 (Stage 3): 1 utterance が複数 assistant_message を carry する（continue turn = 1・depart turn = 2）。
// 各 assistant_complete が 1 メッセージの終端を表す — SSE order 契約により delta stream は complete より前に流れ切っ
// ているので、complete 到達時点で該当メッセージ本文は確定している。complete ごとに (a) 現在の in-progress メッセー
// ジを reveal に flush し (b) committed 配列に確定 message として積み (c) fullText/segCount を次のメッセージ用に
// reset する。turn 終端は SSE `result` の到達で判定する（complete 数の推測に依存しない）。immutable turnEmotion は 1
// utterance に 1 回・最初の delta より前に確定し、その 1 emotion を継続 message にも退出 message にも spread する。
async function revealLoungeUtterance({ speaker, id, cursor, onStreamStart = null }) {
  const base = [...loungeStage.surface.getHistory()];
  const reveal = loungeStage.createTurnReveal(base);
  // Committed assistant messages accumulated within this ONE utterance. Each assistant_complete pushes a message
  // here; the next message's reveal segments are built from base + committed + the in-progress buffer so newly
  // enqueued rows only include the tail belonging to the new message (segCount counts fresh segments within the
  // current in-progress message alone — it is reset on each complete).
  const committed = [];
  let fullText = '';
  let segCount = 0;
  // The turn's emotion is confirmed once, by the first assistant_emotion event (which the server sends BEFORE any
  // assistant_delta and BEFORE any assistant_complete), and stays immutable for the whole utterance. Every assistant
  // segment — including a 括弧分割 that yields two face rows — is built from this single emotion, so both faces
  // match; the depart turn's two assistant messages also share this one emotion. Assistant content that arrives
  // before the emotion is confirmed is a protocol violation: fail fast, never revealing a stand-in face.
  let turnEmotion = null;
  const enqueueFrom = (text) => {
    if (!text.trim()) return;
    if (!turnEmotion) throw new Error('lounge utterance stream sent assistant content before assistant_emotion (protocol violation)');
    // Segments for the CURRENT in-progress message. Prior committed messages already have their segments in the
    // reveal queue, so slice them off before slicing off segments already revealed in this in-progress message.
    // The prefix length is measured in SEGMENTS (not messages): displayMessages performs 括弧分割 that can split
    // one message into multiple face rows, so `committed.length` (a message count) would leave stale trailing
    // committed segments on the head of the in-progress list and re-enqueue the previous message's tail face
    // when the next complete arrives. The correct prefix is the segment count committed messages produce on
    // their own — computed here by running displayMessages over `committed` alone and filtering the same way.
    const committedSegments = loungeDisplayMessages(committed).filter((segment) => (segment.content ?? '').trim());
    const segments = loungeDisplayMessages([...committed, loungeMessage(speaker, text, turnEmotion)])
      .filter((segment) => (segment.content ?? '').trim())
      .slice(committedSegments.length);
    const fresh = segments.slice(segCount);
    segCount += fresh.length;
    reveal.enqueue(fresh);
  };
  let result = null;
  try {
    result = await readLoungeUtteranceSse(
      { id, round_number: cursor.round_number, next_speaker_index: cursor.next_speaker_index },
      {
        onStreamStart,
        onEmotion: (chosen) => {
          if (turnEmotion) throw new Error('lounge utterance stream sent assistant_emotion more than once (protocol violation)');
          turnEmotion = chosen;
        },
        onDelta: (delta) => { fullText += delta; enqueueFrom(completedAssistantPrefix(fullText)); },
        onComplete: (content) => {
          // A complete finalizes the CURRENT assistant message. Flush its final text (backend guarantees the delta
          // stream for this message has ended by now — SSE order 契約 pinned in Stage 2), then commit the message and
          // reset the in-progress buffer so the NEXT complete starts a fresh segment. The turn's emotion is reused —
          // the depart turn's two messages carry the same face by construction.
          fullText = content || fullText;
          enqueueFrom(fullText);
          committed.push(loungeMessage(speaker, fullText, turnEmotion));
          fullText = '';
          segCount = 0;
        }
      }
    );
    await reveal.drain();
  } catch (error) {
    reveal.cancel();
    loungeStage.surface.setHistory(base);
    loungeStage.renderStream(base);
    throw error;
  }
  // Two assistant messages in one utterance is the departure turn (the normal line, then the leaving line): the
  // speaker has left, and the render below empties their seat. Any other count is outside the v2 contract.
  if (committed.length === 2) loungeDeparted.add(speaker.character_id);
  else if (committed.length !== 1) throw new Error(`lounge utterance carried ${committed.length} assistant messages (expected 1, or 2 for a departure)`);
  // Completion reconcile: adopt the server-authoritative history into BOTH the surface state AND the DOM. setHistory
  // alone leaves the just-revealed rows in the DOM (the same reason resetLoungeScreenView pairs setHistory with
  // renderStream), which would let a stale face linger until the next render. emotion-before-delta is the primary
  // contract; this re-render is the completion backstop against any deferred face变化.
  const authoritative = loungeMessagesFromConversation(result.conversation);
  loungeStage.surface.setHistory(authoritative);
  loungeStage.renderStream(authoritative);
  return result;
}

// The lounge's modal popups: the stage-detail popup and the clicked speaker's detail popup. While either is open the
// player is reading it, so the player-turn focus must not pull focus behind it.
const LOUNGE_OVERLAY_SELECTORS = Object.freeze([
  '#academy-lounge-stage-popup',
  '#academy-lounge-character-popup'
]);

function isLoungeOverlayOpen() {
  return LOUNGE_OVERLAY_SELECTORS.some((selector) => {
    const overlay = document.querySelector(selector);
    if (!overlay) throw new Error(`lounge overlay ${selector} is missing (broken markup wiring)`);
    return !overlay.hidden;
  });
}

// True while a lounge group talk is the active conversation. Requires a concrete conversation id string (the same
// discipline as isRoutingHubActive).
function isLoungeConversationActive() {
  return typeof loungeConversation?.id === 'string' && loungeConversation.id !== '';
}

// Put keyboard focus into `#academy-lounge-input` when the player's turn opens, so the next utterance is typed and
// sent without a mouse. The same gate as the routing hub's focusRoutingHubInputIfContinuing, all required, no silent
// fallback: the lounge screen is active and no wait is up over it, the lounge conversation is live, no lounge popup is
// open, the input is present and not disabled. A player turn that opens while the entry wait is still up (a fast LM)
// is a no-op here; the entry puts the focus in once the wait ends (runLoungeSession). preventScroll keeps a scrolled-up
// read position in place.
function focusLoungeInputIfContinuing() {
  if (!screens['academy-lounge'].classList.contains('active')) return;
  if (placeVeilWaiting()) return;
  if (!isLoungeConversationActive()) return;
  if (isLoungeOverlayOpen()) return;
  const input = document.querySelector('#academy-lounge-input');
  if (!input || input.disabled) return;
  input.focus({ preventScroll: true });
}

// The suspended player round-closing turn: opens the input at the round boundary and resolves when 送信
// (submitLoungePlayerTurn → { ended:false, conversation }) or 退出 (exitLounge → { ended:true }) is pressed.
function runLoungePlayerTurn() {
  return new Promise((resolve) => {
    loungePlayerResolve = resolve;
    loungeStage.setControlsDisabled(false);
    focusLoungeInputIfContinuing();
  });
}

// The round drive: stream each scheduled NPC (server cursor → next_speaker), then open the player's turn. The
// server advances the cursor per request (next_speaker becomes null once all of the round's NPCs have spoken →
// the player's turn; a player turn advances to the next round's first NPC). NPC responses keep the input closed
// (shared setControlsDisabled); the loop returns when the player ends the talk.
//
// v2 契約 (Stage 3): terminal utterance が「全員退出 auto completion」を carry している場合、backend は SSE の
// terminal `result` に `finalization_status:'completed'` と手動 `/end` と等価な `state` / `transition.next_screen`
// / `post_content_screen` / `lounge_result` を merge する（Stage 2 で pin）。この場合は player input を開かず、
// `runLoungeAutoCompletion(result)` に handoff して routing hub へ帰す（明示退出ボタン導線は並存）。terminal
// result の `finalization_status` フィールドが未定義なら通常の round loop（次 NPC or player turn）を続ける — strict
// check（フィールドの存在を明示的に見る）で決め、silent fallback にしない。
async function runLoungeConversation({ onFirstStreamStart = null } = {}) {
  let firstStreamPending = Boolean(onFirstStreamStart);
  while (true) {
    while (loungeConversation.next_speaker) {
      loungeStage.setControlsDisabled(true);
      loungeStage.setResponding(true);
      const onStreamStart = firstStreamPending ? () => { firstStreamPending = false; onFirstStreamStart(); } : null;
      const result = await revealLoungeUtterance({
        speaker: loungeConversation.next_speaker,
        id: loungeConversation.id,
        cursor: loungeConversation.cursor,
        onStreamStart
      });
      // Auto completion detection: the terminal `result` event carries `finalization_status` ONLY when the backend
      // ran the shared completion helper (Stage 2). Strict presence check — silent fallback (推測) にしない: the
      // field's absence means "continue the round"; its presence means "hand off to the hub return".
      if ('finalization_status' in result) {
        await runLoungeAutoCompletion(result);
        return;
      }
      // No auto completion this turn — the reveal committed, the round advances.
      loungeConversation = result.conversation;
    }
    loungeStage.setResponding(false);
    const outcome = await runLoungePlayerTurn();
    if (outcome.ended) return;
    loungeConversation = outcome.conversation;
  }
}

// Strict-validate the completed-finalization payload (no default-value fallback for state / next_screen /
// post_content_screen). Split out from promoteLoungeCompletion so callers can validate BEFORE raising any loading
// cover (a malformed payload throws straight into the caller's un-strand branch instead of wasting a full drain
// cover cycle on state that is about to be rejected).
function assertLoungeCompletion(completion) {
  if (completion.finalization_status !== 'completed') {
    throw new Error(`lounge completion: unexpected finalization_status ${JSON.stringify(completion.finalization_status)}`);
  }
  if (completion.transition?.next_screen !== 'interaction') {
    throw new Error(`lounge completion: unexpected transition.next_screen ${JSON.stringify(completion.transition?.next_screen)}`);
  }
  if (completion.post_content_screen !== 'interaction') {
    throw new Error(`lounge completion: unexpected post_content_screen ${JSON.stringify(completion.post_content_screen)}`);
  }
  if (!completion.state || typeof completion.state !== 'object') {
    throw new Error(`lounge completion is missing post-finalize state (got ${JSON.stringify(completion.state)})`);
  }
}

// Shared post-promote hub-return helper: assumes the payload has already passed assertLoungeCompletion (both
// callers validate FIRST so a malformed payload rejects without wasting a loading-cover cycle), then adopts the
// post-finalize state, and hands off through the shared content return. Callers: exitLounge
// (after endRequest resolves), runLoungeAutoCompletion (after the terminal utterance result arrives). Keeping the
// adopt + handoff in ONE place is how the frontend has a SINGLE hub-return path for lounge completion, per Stage
// 3 acceptance (auto and manual paths share the same helper — no duplicated completion path).
async function promoteLoungeCompletion(completion) {
  assertLoungeCompletion(completion);
  currentRuntimeState = completion.state;
  await returnToRoutingHubFromContent(completion.post_content_screen);
}

// Auto completion handoff: reached when a terminal utterance SSE `result` carries the same completion fields the
// explicit `/api/lounge/end` returns (Stage 2 backend merge). Raises the wait over the lounge's art (the backend
// has already promoted by the time this terminal result arrives — the completion payload IS the proof of promote,
// so readiness is pre-resolved), then delegates to promoteLoungeCompletion for the strict-validate + adopt + hub
// return. returnToRoutingHubFromContent continues the same wait through the hub start (M-2026-07-06-001).
//
// Failure branches: this path is entered ONLY after the backend has already promoted the atomic finalization, so a
// validation throw here is post-promote — the wait sinks into the night and the shared failed-arrival hub return
// takes the player to the routing hub with the failure notice (same discipline as exitLounge's post-promote branch). A pre-promote failure
// surfaces as an SSE `error` event inside readLoungeUtteranceSse, which throws up through revealLoungeUtterance /
// runLoungeConversation / runLoungeSession and is un-stranded to the lounge chrome for retry (matches Stage 2 SSE
// error contract: pre-promote = retry-able, the record was not promoted).
//
// Race guard with the explicit exit button: sets routingContentReturnInFlight (the same single-flight guard
// exitLounge uses) so a concurrent 退出 press does not double-start the hub return. The auto path never opens the
// player turn (the round loop returns immediately after this handoff), so loungePlayerResolve is null throughout —
// asserted so a future refactor that opens the player turn first fails loud instead of stranding a resolver.
async function runLoungeAutoCompletion(result) {
  if (routingContentReturnInFlight) {
    // An explicit 退出 press already grabbed the hub-return slot in the same round boundary. Fail loud rather than
    // silently dropping the auto completion — this should not happen: the auto path is entered while the input is
    // still closed (NPCs are still speaking / streaming), so 退出 cannot be pressed at that moment.
    throw new Error('lounge auto completion: routing content return is already in flight (race with explicit exit)');
  }
  if (loungePlayerResolve) {
    throw new Error('lounge auto completion: player turn resolver is unexpectedly held (should never be opened on the auto path)');
  }
  routingContentReturnInFlight = true;
  try {
    // Validate BEFORE raising the wait: a malformed payload throws straight into the post-promote un-strand branch
    // below without wasting a full wait cycle on state that is about to be rejected (review Finding 3 / Minor). The
    // auto path is entered ONLY after the backend has already promoted (the completion payload IS the proof of
    // promote), so a validation throw here is still post-promote un-strand semantics.
    assertLoungeCompletion(result);
    // Raise the wait over the lounge's art (the backend already promoted, so readiness is pre-resolved — the wait holds
    // only for its minimum-display window before handing off to the hub return, matching exitLounge's shape: the
    // shared content return continues the same wait through the hub start).
    raisePlaceVeil({ art: returnedPlaceArt(currentRuntimeState), dim: true, until: 'routing-hub', ending: 'fade' });
    await awaitUnderPlaceVeil(Promise.resolve());
    await promoteLoungeCompletion(result);
  } catch (error) {
    if (settingsRedirectErrorMessage(error) != null) {
      // enterRoutingHub already redirected to the settings screen for an LM-config error — do not overwrite that
      // screen.
      reportLoungeScreenError(error);
    } else {
      // Post-promote failure: the backend already promoted the record before sending the terminal result, so we
      // cannot go back to the lounge (the finalizer would reject a re-finalization). The wait (when it is up) sinks
      // into the night, then the shared failed-arrival hub return takes the player to the routing hub with the
      // failure notice naming the lounge (matches exitLounge's post-promote un-strand); the cause stays on the console.
      console.error(error);
      if (placeVeilWaiting()) await stopPlaceVeil();
      await returnToRoutingHubThroughLoadingScreen({ failedArrival: routingFailedArrival(loungeVisitRoutingArrival, 'academy-lounge') });
    }
  } finally {
    routingContentReturnInFlight = false;
  }
}

// Clears every prior-visit residue before an entry. The lounge never persists in-flight progress (reload/re-entry
// restarts the same week's talk fresh), so no prior chat, cursor, or open popup is ever valid on screen.
function resetLoungeScreenView() {
  loungeConversation = null;
  loungePlayerResolve = null;
  loungeActionInFlight = false;
  loungeSeats.clear();
  loungeDeparted.clear();
  document.querySelector('#academy-lounge-seats').replaceChildren();
  document.querySelector('#academy-lounge-stage-name').textContent = '';
  loungeStage.surface.setHistory([]);
  loungeStage.renderStream([]); // repaint empty (setHistory alone leaves the prior rows in the DOM)
  loungeStage.setStatus('');
  loungeStage.setControlsDisabled(true); // input stays closed until the first round ends
  closeLoungeStagePopup();
  closeLoungeCharacterPopup();
}

// Called by showScreen('academy-lounge'). Resets the view, then enters + drives the weekly group talk under the wait over
// the lounge (placeVeilForArrival — the send-off's wait carried onto the lounge screen) that ends on the first NPC
// utterance stream (M-2026-07-06-001). The loungeFlowInFlight guard makes a showScreen('academy-lounge') during the visit
// a no-op re-entry.
// The routing arrival of the lounge visit in progress ({ destinationLabel } when a routing hub dispatch landed on it,
// null on the dev entry; set once per genuine entry): a failure after the promote names the destination by it.
let loungeVisitRoutingArrival = null;

async function enterLoungeScreen({ routingArrival }) {
  if (loungeFlowInFlight) return;
  loungeVisitRoutingArrival = routingArrival;
  resetLoungeScreenView();
  await runLoungeSession({ routingArrival });
}

async function runLoungeSession({ routingArrival }) {
  loungeFlowInFlight = true;
  let arrived = false;
  try {
    let openingStartedResolve = null;
    let openingStartedResolved = false;
    const openingStarted = new Promise((resolve) => { openingStartedResolve = resolve; });
    const markOpeningStarted = () => {
      if (openingStartedResolved) return;
      openingStartedResolved = true;
      openingStartedResolve?.();
    };
    let sessionPromise = Promise.resolve();
    placeVeilForArrival('academy-lounge');
    const readiness = (async () => {
      const enter = await postJson('/api/lounge/enter', {}); // fresh week slot (same-week re-entry restarts fresh)
      currentRuntimeState = enter.state ?? currentRuntimeState;
      loungeConversation = enter.conversation;
      // The three take their seats (their faces matted and lit while the first words are generated) and the room's
      // name goes up at the top left.
      if (typeof loungeConversation.location_name !== 'string' || !loungeConversation.location_name) {
        throw new Error(`lounge enter answered no location_name: ${JSON.stringify(loungeConversation.location_name)}`);
      }
      document.querySelector('#academy-lounge-stage-name').textContent = loungeConversation.location_name;
      const seated = seatLoungeParticipants(loungeConversation.participants);
      // Drive the rounds; the first NPC utterance's first stream token ends the wait (once the three are seated).
      sessionPromise = runLoungeConversation({ onFirstStreamStart: markOpeningStarted });
      await Promise.all([Promise.race([openingStarted, sessionPromise]), seated]);
    })();
    await awaitUnderPlaceVeil(readiness);
    arrived = true;
    placeVeilArrived();
    // The player's turn may already have opened under the wait (a fast LM); its focus comes now that the lounge shows.
    focusLoungeInputIfContinuing();
    await sessionPromise;
  } catch (error) {
    // Wait-residual defense: a failed lounge entry must not strand the player under the wait (it has sunk into the
    // night in awaitUnderPlaceVeil). The lounge is routing-only content, so un-strand to the routing hub opened anew
    // whatever the entrance, with the failure notice naming the destination, then re-raise so the caller's
    // reportLoungeScreenError logs it once. A settings-redirect error already left for the settings screen
    // (reportLoadingError), so the guard skips.
    if (!arrived && settingsRedirectErrorMessage(error) == null) {
      await returnToRoutingHubThroughLoadingScreen({ failedArrival: routingFailedArrival(routingArrival, 'academy-lounge') });
    }
    throw error;
  } finally {
    loungeFlowInFlight = false;
  }
}

// 送信: the player's round-closing turn. Appends the utterance server-side (cursor re-validated) and adopts the
// authoritative view (the player bubble + the next round's cursor), then resolves the suspended player turn so the
// round loop continues into the next round.
async function submitLoungePlayerTurn() {
  if (!loungePlayerResolve) return; // not the player's turn (NPCs are still speaking)
  if (loungeActionInFlight) { showProcessingToast(); return; }
  const input = document.querySelector('#academy-lounge-input');
  const content = (input?.value ?? '').trim();
  if (!content) return;
  loungeActionInFlight = true;
  loungeStage.setControlsDisabled(true);
  const historySnapshot = [...loungeStage.surface.getHistory()];
  const inputSnapshot = input ? input.value : '';
  try {
    if (input) input.value = '';
    loungeStage.flashPlayerSpoke();
    const result = await postJson('/api/lounge/player-turn', {
      id: loungeConversation.id,
      round_number: loungeConversation.cursor.round_number,
      next_speaker_index: loungeConversation.cursor.next_speaker_index,
      content
    });
    loungeStage.surface.setHistory(loungeMessagesFromConversation(result.conversation));
    loungeStage.renderStream(loungeStage.surface.getHistory());
    const resolve = loungePlayerResolve;
    loungePlayerResolve = null;
    resolve({ ended: false, conversation: result.conversation });
  } catch (error) {
    // The player turn is still pending (loungePlayerResolve stays set): restore the display + input and re-open
    // the controls so the round can be retried.
    loungeStage.surface.setHistory(historySnapshot);
    loungeStage.renderStream(historySnapshot);
    if (input) input.value = inputSnapshot;
    loungeStage.setControlsDisabled(false);
    reportLoungeScreenError(error);
  } finally {
    loungeActionInFlight = false;
  }
}

// 退出: the player's explicit end (offered only at a round boundary, when the input is open). Mirrors the 1:1
// routing end (endRoutingConversation): the /api/lounge/end request — which drains the 3-participant aggregate
// finalization server-side — runs under the wait over the lounge's art (raisePlaceVeil, M-2026-07-06-001) instead of
// stranding the player on a live lounge screen while the longest post-processing block runs. Once the wait is up we
// await the end result, strict-validate the completed-finalization contract (no default-value fallback for state /
// next_screen / post_content_screen), release the suspended round loop, and hand off to the shared content-return,
// which continues the same wait through the hub start. Error un-strand splits on where the failure landed:
//   pre-atomic-promote (endRequest reject: HTTP 4xx/5xx, LM config, participant failure): the group finalizer
//   discarded staging; the wait sinks into the night over the lounge screen, which never left, and the player-turn
//   resolver + controls are restored for retry;
//   post-atomic-promote (validation throw after endRequest resolves): the marker is written and the finalizer would
//   reject a re-finalization, so un-strand to the routing hub with the failure notice instead of re-showing the
//   lounge. A failed hub start lands on the hub without a conversation inside the shared return. A settings-redirect
//   error (LM unset) is owned by the shared wait helper / enterRoutingHub and is skipped here.
async function exitLounge() {
  if (!loungePlayerResolve) { showProcessingToast(); return; } // only endable at a round boundary (player turn)
  if (loungeActionInFlight) { showProcessingToast(); return; }
  if (routingContentReturnInFlight) { showProcessingToast(); return; }
  const loungeArt = returnedPlaceArt(currentRuntimeState);
  routingContentReturnInFlight = true;
  loungeStage.setControlsDisabled(true);
  const endRequest = postJson('/api/lounge/end', { id: loungeConversation.id });
  let endResolved = false;
  try {
    // The wait stands on the lounge's art from the moment the player pressed 退出.
    raisePlaceVeil({ art: loungeArt, dim: true, until: 'routing-hub', ending: 'fade' });
    await awaitUnderPlaceVeil(endRequest);
    const result = await endRequest;
    endResolved = true;
    // Release the suspended round loop cleanly; the shared completion helper below owns the navigation. Doing this
    // BEFORE the strict validation matches the pre-refactor sequence (the round loop is released as soon as the
    // response is captured), and the auto path never reaches here — it enters runLoungeAutoCompletion instead.
    const resolve = loungePlayerResolve;
    loungePlayerResolve = null;
    if (resolve) resolve({ ended: true });
    // Strict validation + adopt + hub return: delegated to the shared completion helper so the frontend has a
    // SINGLE hub-return path for lounge completion (both explicit 退出 and auto-exit go through
    // promoteLoungeCompletion — no duplicated completion path per Stage 3 acceptance).
    await promoteLoungeCompletion(result);
  } catch (error) {
    if (settingsRedirectErrorMessage(error) != null) {
      // The shared wait helper (reportLoadingError) already redirected to the settings screen for an LM-config
      // error — do not overwrite that screen.
      reportLoungeScreenError(error);
    } else if (!endResolved) {
      // Pre-atomic-promote failure: the group finalizer discarded its staging workspace, so nothing has been
      // written. The wait has sunk and gone; the lounge screen stayed under it, and the suspended
      // player-turn resolver is still held, so re-enabling the controls re-opens the round.
      if (loungePlayerResolve) loungeStage.setControlsDisabled(false);
      reportLoungeScreenError(error);
    } else {
      // Post-atomic-promote failure: the marker was written and the finalizer would reject a re-finalization, so
      // we cannot go back to the lounge. The wait sinks into the night, then the shared failed-arrival return takes
      // the player to the routing hub with the failure notice naming the lounge (a hub start failure lands on the hub
      // without a conversation); the cause stays on the console.
      console.error(error);
      if (placeVeilWaiting()) await stopPlaceVeil();
      await returnToRoutingHubThroughLoadingScreen({ failedArrival: routingFailedArrival(loungeVisitRoutingArrival, 'academy-lounge') });
    }
  } finally {
    routingContentReturnInFlight = false;
  }
}

// The clicked speaker's detail popup: the group path keeps each word's and seat's own data-character-id, so the clicked
// participant (not one active character) resolves to a roster character → standee + parameters. Fail-fast on an
// unresolvable id / missing display_name / missing popup nodes (broken data / wiring — no id fallback).
function openLoungeCharacterPopup(characterId) {
  const character = selectableCharacters.find((item) => item.character_id === characterId);
  if (!character) {
    throw new Error(`lounge participant not found in character roster: ${characterId}`);
  }
  if (typeof character.display_name !== 'string' || character.display_name.trim() === '') {
    throw new Error(`lounge participant ${character.character_id} has no display_name (broken roster data — no id fallback)`);
  }
  const popup = document.querySelector('#academy-lounge-character-popup');
  const title = document.querySelector('#academy-lounge-character-popup-title');
  const standee = document.querySelector('#academy-lounge-character-popup-standee');
  if (!popup || !title || !standee) {
    throw new Error('lounge character popup nodes are missing (broken markup wiring)');
  }
  title.textContent = character.display_name;
  standee.alt = `${character.display_name}の一枚絵`;
  setActorImageSource(standee, characterSceneStandeeUrl(character));
  renderCharacterParametersInto(character, '#academy-lounge-character-popup-parameters');
  popup.hidden = false;
}

function closeLoungeCharacterPopup() {
  const popup = document.querySelector('#academy-lounge-character-popup');
  if (popup) popup.hidden = true;
}

// The 舞台 detail popup: the authored scene (location_name「寮の談話室」 + the week-seeded visible_situation) carried
// on the active conversation view, plus the 暫定 舞台画像. Fail-fast on missing nodes / no active conversation.
function openLoungeStagePopup() {
  if (!loungeConversation) {
    throw new Error('lounge stage popup requires an active conversation (none held)');
  }
  const popup = document.querySelector('#academy-lounge-stage-popup');
  const title = document.querySelector('#academy-lounge-stage-popup-title');
  const text = document.querySelector('#academy-lounge-stage-popup-text');
  const image = document.querySelector('#academy-lounge-stage-popup-image');
  if (!popup || !title || !text || !image) {
    throw new Error('lounge stage popup nodes are missing (broken markup wiring)');
  }
  title.textContent = loungeConversation.location_name;
  text.textContent = loungeConversation.visible_situation;
  image.style.backgroundImage = `url('${LOUNGE_STAGE_IMAGE_URL}')`;
  popup.hidden = false;
}

function closeLoungeStagePopup() {
  const popup = document.querySelector('#academy-lounge-stage-popup');
  if (popup) popup.hidden = true;
}

document.querySelector('#academy-lounge-send').addEventListener('click', () => submitLoungePlayerTurn().catch(reportLoungeScreenError));
document.querySelector('#academy-lounge-end').addEventListener('click', () => exitLounge().catch(reportLoungeScreenError));
const loungeInputElement = document.querySelector('#academy-lounge-input');
loungeInputElement.addEventListener('compositionstart', () => { playerInputIsComposing = true; });
loungeInputElement.addEventListener('compositionend', () => { playerInputIsComposing = false; });
loungeInputElement.addEventListener('keydown', (event) => {
  if (shouldSubmitPlayerInput(event)) {
    event.preventDefault();
    if (loungeActionInFlight) {
      showProcessingToast();
      return;
    }
    submitLoungePlayerTurn().catch(reportLoungeScreenError);
  }
});
// Speaker click → the CLICKED participant's popup, resolved off the clicked seat's or word's data-character-id
// (delegated so it survives re-render). The player's words carry no data-character-id, so they are never clickable.
for (const selector of ['#academy-lounge-seats', '#academy-lounge-message-stream']) {
  document.querySelector(selector).addEventListener('click', (event) => {
    const speaker = event.target.closest('[data-character-id]');
    if (!speaker) return;
    try { openLoungeCharacterPopup(speaker.dataset.characterId); } catch (error) { reportError(error); }
  });
}
document.querySelector('#academy-lounge-stage-name').addEventListener('click', () => {
  try { openLoungeStagePopup(); } catch (error) { reportError(error); }
});
// The ground is the lounge art, and the send / leave buttons and the writing place wear the terrace's marks (their
// names are the aria-labels).
document.querySelector('#academy-lounge-art').style.backgroundImage = `url('${LOUNGE_STAGE_IMAGE_URL}')`;
for (const [target, source, className] of [
  ['#academy-lounge-screen .lounge-writing', '#routing-hub-screen .routing-hub-composer .terrace-write-mark', 'lounge-write-mark'],
  ['#academy-lounge-send', '#routing-hub-send svg', 'lounge-way-mark'],
  ['#academy-lounge-end', '#routing-hub-end svg', 'lounge-way-mark']
]) {
  const mark = document.querySelector(source);
  if (!mark) throw new Error(`lounge: the terrace mark ${source} is missing`);
  const copy = mark.cloneNode(true);
  copy.setAttribute('class', className);
  document.querySelector(target).prepend(copy);
}
for (const closer of document.querySelectorAll('#academy-lounge-stage-popup [data-lounge-popup-close]')) {
  closer.addEventListener('click', () => closeLoungeStagePopup());
}
for (const closer of document.querySelectorAll('#academy-lounge-character-popup [data-lounge-popup-close]')) {
  closer.addEventListener('click', () => closeLoungeCharacterPopup());
}

// ===== 星見の窓 (overlook) screen =====
// A routing-only content destination (hub dispatch overlook → academy-overlook). Two faces share the section:
//   - the field (構成表 状態 3〜6・10〜14・17〜19): the whole map at scale 1.0 under a top shade, the week/moon/
//     academy-time bar, the 「顔ぶれ」 and exit buttons; the twelve children drawn as DOM face comas where the server
//     walks them (polled field, one GET at a time, played back between samples along each child's route — the
//     children sent off and their newcomers too, on the road outside the gate), the hover say label / relation lines
//     (lines in the module worker), the pair ring, the traces / writing marks, the writing frame, the roster list
//     (a frame over the field, open only on the field / hover / pair states);
//   - the talk (状態 7〜9): the lounge's conversation-day screen with the four changes of 構成表 0.7 (the window
//     stage art, the encounter's seed line first, no input, one 「次へ」 that becomes 「フィールドへ戻る」).
// The server owns the field, the focus choice and the talk; the screen draws and forwards the viewer's acts
// (pick, write, next, return, exit). Every payload goes through overlookClient.js validators, every state change
// through its closed machine (mirrored on #academy-overlook-screen[data-state]).

const overlookStageDeps = {
  displayMessages,
  createMessageRows,
  messagesFromConversation: (conversation) => overlookTalkMessages(conversation),
  conversationPopupCooldownMs,
  sleep,
  setActorImageSource
};

const overlookWeekConfig = {
  weekTotal: CONVERSATION_DAY_TOTAL_WEEKS,
  moonPhaseCount: 8,
  weekLabel: (week, total) => `第${week}週 / ${total}`,
  moonAriaLabel: (phase, count) => `月相 ${phase + 1} / ${count}`,
  currentWeek: () => conversationStageWeek(currentRuntimeState?.elapsed_weeks)
};

// The talk face: the lounge's stage config with the overlook's own nodes (no input, one control: 次へ).
const overlookTalkStage = createConversationStage({
  ...overlookWeekConfig,
  screenSelector: '#academy-overlook-screen',
  streamSelector: '#academy-overlook-message-stream',
  statusSelector: '#academy-overlook-status',
  controlSelectors: ['#academy-overlook-next'],
  weekSelector: '#academy-overlook-talk-week',
  moonSelector: '#academy-overlook-talk-moon-phase',
  respondingClass: 'is-day-responding',
  playerSpokeClass: 'is-day-player-spoke',
  dispatchClimaxClass: 'is-day-dispatch-climax',
  playerSpokeMs: 600,
  dispatchClimaxMs: 900,
  personaVisual: () => null,
  assistantIdentity: () => ({ character_id: null, character_name: '' }),
  refresh: () => refresh(),
  ambient: createConversationDayAmbient({ canvasSelector: '#academy-overlook-motes', moteColorRgb: '255, 236, 179', moteCount: 70 }),
  infoPopupSelector: '#academy-overlook-info-popup',
  infoTitleSelector: '#academy-overlook-info-popup-title',
  infoBodySelector: '#academy-overlook-info-popup-body',
  infoIconSelector: '#academy-overlook-info-popup-icon',
  categoryButtonSelector: '.academy-overlook-category-button',
  categoryDataKey: 'overlookCategory',
  categoryTitles: {},
  categoryIconUrl: () => '',
  categoryRenderers: {}
}, overlookStageDeps);

// The field bar's moon + week are the same stage part (renderWeekAndMoon only); the field face has no chat.
const overlookFieldBar = createConversationStage({
  ...overlookWeekConfig,
  weekSelector: '#academy-overlook-week',
  moonSelector: '#academy-overlook-moon-phase'
}, overlookStageDeps);

let overlookSession = null;       // the live entry (null when none)
let overlookFlowInFlight = false; // guards the re-entrant showScreen during the entry loading cover
let overlookLayoutWorker = null;  // the module worker for the relation lines (created on first use)

function overlookNode(selector) {
  const node = document.querySelector(selector);
  if (!node) throw new Error(`overlook markup node is missing: ${selector}`);
  return node;
}

function overlookSeedMessage(seedLine) {
  return { role: 'narration', content: seedLine, face_emotion_variant_id: 'narration_face', expression: 'narration' };
}

function overlookTalkMessages(conversation) {
  return conversation.messages.map((message) => ({
    role: 'assistant',
    character_id: message.character_id,
    character_name: message.character_name,
    content: message.content,
    expression: message.expression,
    face_emotion_variant_id: message.face_emotion_variant_id
  }));
}

function overlookTalkHistory(conversation) {
  return [overlookSeedMessage(conversation.seed_line), ...overlookTalkMessages(conversation)];
}

// The face coma's image: the child's neutral face from the selectable roster (the arena / dungeon form).
function overlookFaceUrl(characterId) {
  const character = selectableCharacters.find((entry) => entry.character_id === characterId);
  if (!character) throw new Error(`overlook child is not in the selectable roster: ${characterId}`);
  if (!character.visual_set_id) throw new Error(`overlook child has no visual_set_id: ${characterId}`);
  return `/canonical/character_visual_sets/${character.visual_set_id}/face_emotions/neutral.jpg`;
}

function overlookViewport() {
  const rect = overlookNode('#academy-overlook-screen').getBoundingClientRect();
  return { width: rect.width, height: rect.height };
}

// The screen parts (上部バー・「顔ぶれ」・出るボタン、開いていれば顔ぶれの一覧の枠) as screen rects — the layout
// module's `parts`. A coma under a part belongs to the part (no hover).
function overlookParts(session) {
  const origin = overlookNode('#academy-overlook-screen').getBoundingClientRect();
  const selectors = ['#academy-overlook-topbar', '#academy-overlook-roster-button', '#academy-overlook-exit'];
  if (session.roster.open) selectors.push('#academy-overlook-roster');
  return selectors.map((selector) => {
    const rect = overlookNode(selector).getBoundingClientRect();
    return { left: rect.left - origin.left, top: rect.top - origin.top, right: rect.right - origin.left, bottom: rect.bottom - origin.top };
  });
}

function overlookTransition(session, to) {
  session.machine.transition(to);
  overlookNode('#academy-overlook-screen').dataset.state = session.machine.state;
  // The roster list is a frame over the field: any state it cannot stay open on closes it (寄る・書き込み・ハブへ・止まる).
  if (session.roster.open && !overlookRosterMayOpen(session.machine.state)) closeOverlookRoster(session);
}

function overlookPollWanted(session) {
  const { state } = session.machine;
  return isOverlookFieldState(state) || state === 'focusing' || state === 'awaiting-first-line';
}

function overlookFieldVisible(session) {
  const { state } = session.machine;
  return isOverlookFieldState(state) || state === 'focusing' || state === 'returning';
}

// ---------- entry / resume / leave ----------

function createOverlookSessionView(entered) {
  const { field, places } = entered;
  const session = {
    machine: createOverlookStateMachine(),
    places,
    map: field.map,
    postContentScreen: entered.post_content_screen,
    samples: [],
    latest: null,
    receivedAt: 0,
    // Placed on the fountain once the screen is shown and has its size (resumeOverlookScreen).
    camera: null,
    fountain: places.find((place) => place.place_id === OVERLOOK_FOUNTAIN_PLACE_ID),
    cameraAnim: null,
    comas: new Map(),
    positions: new Map(),
    marksKey: '',
    markRects: new Map(),
    marksDirty: true,
    pointer: null,
    drag: null,
    hover: null,
    pair: null,
    writing: null,
    // 顔ぶれの一覧: open or not, the rendered rows' key, and the rows whose 「送り出す」 request is in flight.
    roster: { open: false, key: '', sending: new Set() },
    focus: null,
    talk: null,
    lines: { requestId: 0, pending: false, result: null, key: null },
    polling: false,
    raf: 0
  };
  const world = overlookNode('#academy-overlook-world');
  world.style.width = `${field.map.width}px`;
  world.style.height = `${field.map.height}px`;
  overlookNode('#academy-overlook-comas').replaceChildren();
  overlookNode('#academy-overlook-marks').replaceChildren();
  overlookNode('#academy-overlook-mark-labels').replaceChildren();
  overlookNode('#academy-overlook-hover').replaceChildren();
  overlookNode('#academy-overlook-writing').hidden = true;
  overlookNode('#academy-overlook-roster').replaceChildren();
  overlookNode('#academy-overlook-roster').hidden = true;
  overlookNode('#academy-overlook-roster-button').setAttribute('aria-expanded', 'false');
  overlookNode('#academy-overlook-talk').hidden = true;
  overlookNode('#academy-overlook-field').hidden = false;
  overlookNode('.academy-overlook-vignette').style.opacity = '0';
  overlookTalkStage.surface.setHistory([]);
  overlookTalkStage.renderStream([]);
  overlookTalkStage.setStatus('');
  applyOverlookField(session, field);
  return session;
}

async function enterOrResumeOverlookScreen() {
  if (overlookFlowInFlight) return;
  const session = overlookSession;
  if (session && session.machine.state !== 'failed' && session.machine.state !== 'exiting') {
    resumeOverlookScreen(session);
    return;
  }
  await runOverlookEntry();
}

// Enter under the shared loading cover (状態 2): the cover holds until the entry's first field arrives.
async function runOverlookEntry() {
  overlookFlowInFlight = true;
  try {
    let entered = null;
    const readiness = postJson('/api/overlook/enter', {}).then((payload) => { entered = validateOverlookEnterResponse(payload); });
    await showAcademyLoadingScreenUntilReady({ readiness, nextScreen: null, refreshBeforeNextScreen: false, loadingCopy: OVERLOOK_ENTRY_LOADING_COPY });
    overlookSession = createOverlookSessionView(entered);
    overlookTransition(overlookSession, 'field');
    showScreen('academy-overlook');
    resumeOverlookScreen(overlookSession);
  } finally {
    overlookFlowInFlight = false;
  }
}

function resumeOverlookScreen(session) {
  if (!session.camera) session.camera = overlookCameraCentredOn(session.fountain, overlookViewport(), session.map);
  overlookFieldBar.renderWeekAndMoon();
  if (overlookFieldVisible(session)) {
    startOverlookFrameLoop(session);
    ensureOverlookPoll(session);
  }
  if (['talk', 'talk-generating', 'talk-closed'].includes(session.machine.state)) overlookTalkStage.startAmbient();
}

function suspendOverlookScreen() {
  overlookTalkStage.stopAmbient();
  if (!overlookSession) return;
  cancelAnimationFrame(overlookSession.raf);
  overlookSession.raf = 0;
}

// Any failure ends this entry: an LM failure (503 or a strict-gate violation) goes to the settings screen by the
// shared path (状態 15); anything else returns to the hub with the failure notice naming 星見の窓 (the hub never
// dispatches to it, so the hub start names it from the catalog). The cause stays on the console.
function reportOverlookScreenError(error) {
  const session = overlookSession;
  overlookSession = null;
  if (session) {
    if (session.machine.state !== 'failed') overlookTransition(session, 'failed');
    cancelAnimationFrame(session.raf);
  }
  overlookTalkStage.stopAmbient();
  console.error(error);
  if (settingsRedirectErrorMessage(error) != null) {
    if (!screens.settings.classList.contains('active')) handleRuntimeApiError(error, { allowSettingsRedirect: true });
    return;
  }
  returnToRoutingHubThroughLoadingScreen({ failedArrival: { screen: 'academy-overlook' } }).catch(reportError);
}

// ---------- the field poll ----------

function ensureOverlookPoll(session) {
  if (session.polling || !overlookPollWanted(session)) return;
  session.polling = true;
  runOverlookPoll(session).catch((error) => {
    session.polling = false;
    if (overlookSession === session) reportOverlookScreenError(error);
  });
}

// One field GET at a time: the next is sent OVERLOOK_FIELD_POLL_MS after the previous answer arrived.
async function runOverlookPoll(session) {
  while (overlookSession === session && overlookPollWanted(session)) {
    const payload = await getJson('/api/overlook/field');
    if (overlookSession !== session) return;
    applyOverlookField(session, validateOverlookFieldResponse(payload, { places: session.places }).field);
    await sleep(OVERLOOK_FIELD_POLL_MS);
  }
  session.polling = false;
}

function overlookMarksOf(field) {
  const traces = [...field.traces]
    .sort((a, b) => overlookAcademyMinute(a.academy_time) - overlookAcademyMinute(b.academy_time))
    .map((trace) => ({ id: `trace:${trace.place_id}:${trace.academy_time}:${trace.text}`, kind: 'trace', ...trace }));
  const marks = field.writing_marks.map((mark) => ({ id: `writing:${mark.writing_id}`, kind: 'writing', ...mark }));
  return [...traces, ...marks];
}

// Every field the server sends (poll, enter, focus, return, writings) lands here.
function applyOverlookField(session, field) {
  if (session.latest && field.clock.tick < session.latest.clock.tick) return;
  // A field at the same tick replaces the newest sample but keeps its arrival time: the playback clock is anchored
  // to when that tick first arrived, so a clock that stands still (15:00) never pulls the drawing back.
  const sameTick = session.latest && field.clock.tick === session.latest.clock.tick;
  if (sameTick) session.samples.pop();
  session.samples.push(field);
  session.latest = field;
  if (!sameTick) session.receivedAt = performance.now();
  overlookNode('#academy-overlook-time').textContent = field.clock.academy_time;
  syncOverlookComas(session, field);
  renderOverlookRoster(session);
  const marks = overlookMarksOf(field);
  const marksKey = marks.map((mark) => mark.id).join('|');
  if (marksKey !== session.marksKey) {
    session.marksKey = marksKey;
    renderOverlookMarks(session, marks);
  }
  const { state } = session.machine;
  if (state === 'writing-limited' && field.writing.available) {
    overlookTransition(session, 'writing');
    renderOverlookWritingFrame(session);
  }
  if ((state === 'focusing' || state === 'awaiting-first-line') && session.focus && !session.focus.conversationId && field.focus?.encounter_id === session.focus.encounterId && field.focus.conversation_id) {
    session.focus.conversationId = field.focus.conversation_id;
    startOverlookFirstLine(session, session.focus);
  }
  if (!isOverlookFieldState(session.machine.state)) return;
  if (field.clock.ended) {
    exitOverlookToHub(session).catch(reportOverlookScreenError);
    return;
  }
  if (field.focus) beginOverlookFocus(session, field.focus);
}

function syncOverlookComas(session, field) {
  const layer = overlookNode('#academy-overlook-comas');
  const ids = new Set(field.children.map((child) => child.character_id));
  for (const [id, node] of session.comas) {
    if (!ids.has(id)) {
      node.remove();
      session.comas.delete(id);
    }
  }
  for (const child of field.children) {
    if (session.comas.has(child.character_id)) continue;
    const node = document.createElement('div');
    node.className = 'academy-overlook-coma';
    node.dataset.characterId = child.character_id;
    const image = document.createElement('img');
    image.alt = child.character_name;
    image.draggable = false;
    setActorImageSource(image, overlookFaceUrl(child.character_id));
    node.append(image);
    layer.append(node);
    session.comas.set(child.character_id, node);
  }
}

function overlookChild(session, characterId) {
  const child = session.latest.children.find((entry) => entry.character_id === characterId);
  if (!child) throw new Error(`overlook child is not on the field: ${characterId}`);
  return child;
}

// ---------- the frame loop ----------

function startOverlookFrameLoop(session) {
  if (session.raf) return;
  const frame = () => {
    session.raf = 0;
    if (overlookSession !== session || !overlookFieldVisible(session)) return;
    try {
      renderOverlookFrame(session);
    } catch (error) {
      reportOverlookScreenError(error);
      return;
    }
    session.raf = requestAnimationFrame(frame);
  };
  session.raf = requestAnimationFrame(frame);
}

function overlookCameraFrame(session, viewport) {
  const anim = session.cameraAnim;
  if (!anim) return overlookFrameOfCamera(session.camera, viewport);
  return overlookFocusCameraFrame({
    from: anim.from,
    target: anim.target,
    viewport,
    map: session.map,
    elapsedMs: performance.now() - anim.startedAt,
    reverse: anim.reverse
  });
}

function renderOverlookFrame(session) {
  const viewport = overlookViewport();
  const now = performance.now();
  const latestMs = overlookSampleMs(session.latest);
  const moment = Math.min(latestMs + (now - session.receivedAt) - OVERLOOK_PLAYBACK_DELAY_MS, latestMs);
  session.samples = overlookTrimSamples(session.samples, moment);
  session.positions = overlookPlaybackPositions(session.samples, moment);
  const frame = overlookCameraFrame(session, viewport);
  overlookNode('#academy-overlook-world').style.transform = `translate(${viewport.width / 2 - frame.centre.x * frame.scale}px, ${viewport.height / 2 - frame.centre.y * frame.scale}px) scale(${frame.scale})`;
  overlookNode('.academy-overlook-vignette').style.opacity = String(frame.dim ?? 0);
  for (const [id, node] of session.comas) {
    const point = session.positions.get(id);
    // A newcomer's coma exists from the newest sample on but is drawn only once the playback reaches it.
    node.style.visibility = point ? '' : 'hidden';
    if (point) node.style.transform = `translate(${point.x}px, ${point.y}px)`;
  }
  const anim = session.cameraAnim;
  if (anim && frame.done) {
    session.cameraAnim = null;
    session.camera = clampOverlookCamera({ x: frame.centre.x - viewport.width / 2, y: frame.centre.y - viewport.height / 2 }, viewport, session.map);
    session.marksDirty = true;
    anim.onDone();
    return;
  }
  if (anim) return;
  const comas = [...session.positions].map(([id, point]) => ({ id, ...overlookScreenPoint(point, frame, viewport) }));
  const parts = overlookParts(session);
  if (isOverlookFieldState(session.machine.state)) updateOverlookHover(session, { viewport, frame, comas, parts, now });
  renderOverlookWritingFrame(session, { frame, viewport });
  if (session.marksDirty) {
    session.marksDirty = false;
    layoutOverlookMarkLabels(session, { frame, viewport, comas, parts });
  }
  drawOverlookLines(session, viewport);
}

// ---------- traces and writing marks (状態 10・12) ----------

function renderOverlookMarks(session, marks) {
  const dots = overlookNode('#academy-overlook-marks');
  const labels = overlookNode('#academy-overlook-mark-labels');
  dots.replaceChildren();
  labels.replaceChildren();
  const liveIds = new Set(marks.map((mark) => mark.id));
  for (const id of [...session.markRects.keys()]) if (!liveIds.has(id)) session.markRects.delete(id);
  for (const mark of marks) {
    const dot = document.createElement('span');
    dot.className = 'academy-overlook-dot';
    dot.dataset.kind = mark.kind;
    dot.style.left = `${mark.x}px`;
    dot.style.top = `${mark.y}px`;
    dots.append(dot);
    const label = document.createElement('p');
    label.className = 'academy-overlook-label academy-overlook-mark-label';
    label.dataset.kind = mark.kind;
    label.dataset.markId = mark.id;
    const time = document.createElement('span');
    time.className = 'academy-overlook-mark-time';
    time.textContent = mark.academy_time;
    label.append(time, `　${mark.text}`);
    labels.append(label);
  }
  session.marks = marks;
  session.marksDirty = true;
}

// 跡の札の置き場 (状態 10): placed in screen px at scale 1 and kept on the map; a label is re-placed only when a
// later label / the writing frame / the say label comes within 4 px of it.
function layoutOverlookMarkLabels(session, { frame, viewport, comas, parts }) {
  const marks = session.marks ?? [];
  if (marks.length === 0) return;
  const toScreen = (rect) => ({ left: rect.left - session.camera.x, top: rect.top - session.camera.y, right: rect.right - session.camera.x, bottom: rect.bottom - session.camera.y });
  const rects = [];
  if (session.writing?.rect) rects.push(session.writing.rect);
  if (session.hover?.say) rects.push(session.hover.say.rect);
  const nodes = new Map([...document.querySelectorAll('#academy-overlook-mark-labels [data-mark-id]')].map((node) => [node.dataset.markId, node]));
  const placed = placeTraceLabels({
    parts,
    comaRadius: OVERLOOK_COMA_RADIUS,
    comas: comas.map(({ x, y }) => ({ x, y })),
    rects,
    labels: marks.map((mark) => {
      const node = nodes.get(mark.id);
      const point = overlookScreenPoint(mark, frame, viewport);
      const previous = session.markRects.get(mark.id);
      return { id: mark.id, x: point.x, y: point.y, width: node.offsetWidth, height: node.offsetHeight, ...(previous ? { rect: toScreen(previous) } : {}) };
    })
  });
  for (const entry of placed) {
    const mapRect = { left: entry.rect.left + session.camera.x, top: entry.rect.top + session.camera.y, right: entry.rect.right + session.camera.x, bottom: entry.rect.bottom + session.camera.y };
    session.markRects.set(entry.id, mapRect);
    const node = nodes.get(entry.id);
    node.style.left = `${mapRect.left}px`;
    node.style.top = `${mapRect.top}px`;
  }
}

function overlookMarkDotsOnScreen(session, frame, viewport) {
  return (session.marks ?? []).map((mark) => ({ ...overlookScreenPoint(mark, frame, viewport), radius: 4 }));
}

function overlookMarkLabelRectsOnScreen(session) {
  return [...session.markRects.values()].map((rect) => ({ left: rect.left - session.camera.x, top: rect.top - session.camera.y, right: rect.right - session.camera.x, bottom: rect.bottom - session.camera.y }));
}

// ---------- hover: say label, relation lines, the pair ring (状態 4・5・14) ----------

function overlookHoverTarget(session, { comas, parts, viewport }) {
  if (!session.pointer || session.drag) return null;
  const id = overlookComaAt(session.pointer, comas);
  if (!id) return null;
  const coma = comas.find((entry) => entry.id === id);
  if (!isOverlookComaHoverable(coma, { screen: viewport, parts })) return null;
  // The playback runs behind the newest field, so a child sent off may still be drawn after it left the field.
  const child = session.latest.children.find((entry) => entry.character_id === id);
  if (!child || !isOverlookChildPointable(child)) return null;
  const encounter = session.latest.encounters.find((entry) => entry.pickable && entry.participants.some((participant) => participant.character_id === id));
  if (encounter) return { kind: 'pair', id, encounter };
  if (child.wish_line === null) return null;
  return { kind: 'say', id };
}

function clearOverlookHover(session) {
  session.hover = null;
  session.pair = null;
  session.lines = { requestId: session.lines.requestId, pending: false, result: null, key: null };
  overlookNode('#academy-overlook-hover').replaceChildren();
  session.marksDirty = true;
}

function overlookLabelNode(text, kind) {
  const node = document.createElement('p');
  node.className = 'academy-overlook-label';
  node.dataset.kind = kind;
  node.textContent = text;
  overlookNode('#academy-overlook-hover').append(node);
  return node;
}

function placeOverlookNode(node, rect) {
  node.style.left = `${rect.left}px`;
  node.style.top = `${rect.top}px`;
}

function updateOverlookHover(session, { viewport, frame, comas, parts, now }) {
  const { state } = session.machine;
  if (state === 'writing' || state === 'writing-limited') return;
  const target = overlookHoverTarget(session, { comas, parts, viewport });
  const current = session.hover?.id ?? session.pair?.id ?? null;
  const currentKind = session.hover ? 'say' : session.pair ? 'pair' : null;
  if (!target || target.id !== current || target.kind !== currentKind) {
    if (current !== null) {
      clearOverlookHover(session);
      if (session.machine.state !== 'field') overlookTransition(session, 'field');
    }
    if (target?.kind === 'say') session.hover = { id: target.id, since: now, say: null, sayNode: null, feelingNodes: new Map() };
    if (target?.kind === 'pair') {
      session.pair = { id: target.id, encounter: target.encounter, ring: null, ringNode: null, labelNode: null };
      overlookTransition(session, 'pair');
    }
  }
  if (session.hover) updateOverlookSay(session, { viewport, comas, parts, now });
  if (session.pair) updateOverlookPair(session, { viewport, frame, comas, parts });
}

function updateOverlookSay(session, { viewport, comas, parts, now }) {
  const hover = session.hover;
  const child = overlookChild(session, hover.id);
  const coma = comas.find((entry) => entry.id === hover.id);
  const since = now - hover.since;
  if (since < OVERLOOK_SAY_DELAY_MS) return;
  if (!hover.say) {
    hover.sayNode = overlookLabelNode(child.wish_line, 'say');
    const targetIds = child.feelings.map((feeling) => feeling.character_id);
    hover.say = placeSayLabel({
      screen: viewport,
      parts,
      comaRadius: OVERLOOK_COMA_RADIUS,
      comas,
      hoverId: hover.id,
      targetIds,
      width: hover.sayNode.offsetWidth,
      height: hover.sayNode.offsetHeight
    });
    // Measured before they show (the worker needs their size), so they wait invisible rather than hidden.
    for (const feeling of child.feelings) {
      const node = overlookLabelNode(feeling.label, 'feeling');
      node.style.visibility = 'hidden';
      hover.feelingNodes.set(feeling.character_id, node);
    }
    overlookTransition(session, 'say');
    session.marksDirty = true;
  } else {
    hover.say = { side: hover.say.side, rect: overlookSayLabelRectAt(coma, hover.say.side, { width: hover.sayNode.offsetWidth, height: hover.sayNode.offsetHeight }) };
  }
  placeOverlookNode(hover.sayNode, hover.say.rect);
  requestOverlookLines(session, { viewport, comas, parts, child });
  if (since >= OVERLOOK_LINES_DELAY_MS && session.lines.result && session.machine.state === 'say') overlookTransition(session, 'lines');
  if (session.machine.state === 'lines' && session.lines.result) {
    for (const [id, node] of hover.feelingNodes) {
      const label = session.lines.result.feelingLabels.find((entry) => entry.targetId === id);
      node.style.visibility = label ? 'visible' : 'hidden';
      if (label) placeOverlookNode(node, label.rect);
    }
  }
}

// The relation lines run in the module worker from the say label onward (0.3 秒), one request at a time; while
// the hover lasts each answer is followed by a request for the comas where they are now.
function requestOverlookLines(session, { viewport, comas, parts, child }) {
  if (session.lines.pending) return;
  if (!overlookLayoutWorker) {
    overlookLayoutWorker = new Worker(new URL('./overlookLayoutWorker.js', import.meta.url), { type: 'module' });
    overlookLayoutWorker.addEventListener('message', (event) => {
      const live = overlookSession;
      if (!live) return;
      try {
        const reply = validateOverlookLayoutReply(event.data);
        if (reply.id !== live.lines.requestId || !live.hover) return;
        if (!reply.ok) throw new Error(`overlook relation lines failed in the worker: ${reply.error}`);
        live.lines.pending = false;
        live.lines.result = reply.result;
      } catch (error) {
        reportOverlookScreenError(error);
      }
    });
    overlookLayoutWorker.addEventListener('error', (event) => reportOverlookScreenError(new Error(`overlook layout worker error: ${event.message}`)));
  }
  const hover = session.hover;
  session.lines.requestId += 1;
  session.lines.pending = true;
  overlookLayoutWorker.postMessage({
    id: session.lines.requestId,
    input: {
      screen: viewport,
      parts,
      comaRadius: OVERLOOK_COMA_RADIUS,
      comas,
      hoverId: hover.id,
      targets: child.feelings.map((feeling) => {
        const node = hover.feelingNodes.get(feeling.character_id);
        return { id: feeling.character_id, width: node.offsetWidth, height: node.offsetHeight };
      }),
      sayLabel: hover.say
    }
  });
}

function overlookCssColor(token) {
  const value = getComputedStyle(overlookNode('#academy-overlook-screen')).getPropertyValue(token).trim();
  if (!value) throw new Error(`overlook color token is not declared: ${token}`);
  return value;
}

// 線: 芯は琥珀 3 px、その下に黒曜の縁取り 7 px（構成表 状態 5）。
function drawOverlookLines(session, viewport) {
  const canvas = overlookNode('#academy-overlook-lines');
  const ratio = window.devicePixelRatio || 1;
  const width = Math.round(viewport.width * ratio);
  const height = Math.round(viewport.height * ratio);
  if (canvas.width !== width || canvas.height !== height) {
    canvas.width = width;
    canvas.height = height;
  }
  const ctx = canvas.getContext('2d');
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.clearRect(0, 0, width, height);
  if (session.machine.state !== 'lines' || !session.lines.result) return;
  ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  const trace = (line) => {
    ctx.beginPath();
    ctx.moveTo(line.path[0].from.x, line.path[0].from.y);
    for (const piece of line.path) {
      if (piece.type === 'line') ctx.lineTo(piece.to.x, piece.to.y);
      else ctx.arc(piece.center.x, piece.center.y, piece.radius, piece.startAngle, piece.endAngle, piece.anticlockwise);
    }
  };
  const layers = [
    { width: OVERLOOK_LINE_WIDTH.casing, color: overlookCssColor('--cd-night-bg-0') },
    { width: OVERLOOK_LINE_WIDTH.core, color: overlookCssColor('--cd-night-amber') }
  ];
  for (const layer of layers) {
    ctx.lineWidth = layer.width;
    ctx.strokeStyle = layer.color;
    for (const line of session.lines.result.lines) {
      trace(line);
      ctx.stroke();
    }
  }
}

function updateOverlookPair(session, { viewport, frame, comas, parts }) {
  const pair = session.pair;
  const [initiator, partner] = pair.encounter.participants.map((participant) => comas.find((coma) => coma.id === participant.character_id));
  const ring = overlookPairRing(initiator, partner);
  if (!pair.ringNode) {
    pair.ringNode = document.createElement('div');
    pair.ringNode.className = 'academy-overlook-pair-ring';
    overlookNode('#academy-overlook-hover').append(pair.ringNode);
    pair.labelNode = overlookLabelNode(overlookChild(session, initiator.id).wish_line, 'say');
  }
  pair.ringNode.style.width = `${ring.width}px`;
  pair.ringNode.style.height = `${ring.height}px`;
  pair.ringNode.style.borderRadius = `${ring.cornerRadius}px`;
  pair.ringNode.style.transform = `translate(${ring.x - ring.width / 2}px, ${ring.y - ring.height / 2}px) rotate(${ring.angleDeg}deg)`;
  const placed = placePairSayLabel({
    screen: viewport,
    parts,
    comaRadius: OVERLOOK_COMA_RADIUS,
    comas,
    pairIds: [initiator.id, partner.id],
    ring,
    width: pair.labelNode.offsetWidth,
    height: pair.labelNode.offsetHeight,
    dots: overlookMarkDotsOnScreen(session, frame, viewport),
    rects: overlookMarkLabelRectsOnScreen(session)
  });
  placeOverlookNode(pair.labelNode, placed.rect);
}

// ---------- pointer: drag the camera, hover, click ----------

function overlookPointerPoint(event) {
  const origin = overlookNode('#academy-overlook-screen').getBoundingClientRect();
  return { x: event.clientX - origin.left, y: event.clientY - origin.top };
}

function onOverlookPointerDown(event) {
  const session = overlookSession;
  if (!session || !isOverlookFieldState(session.machine.state) && session.machine.state !== 'focusing') return;
  // A click outside the open roster list only closes it (no place, no pair, no drag).
  if (session.roster.open) {
    closeOverlookRoster(session);
    return;
  }
  const point = overlookPointerPoint(event);
  session.drag = { start: point, camera: { ...session.camera }, moved: false, pointerId: event.pointerId };
  overlookNode('#academy-overlook-viewport').setPointerCapture(event.pointerId);
}

function onOverlookPointerMove(event) {
  const session = overlookSession;
  if (!session) return;
  const point = overlookPointerPoint(event);
  session.pointer = point;
  const drag = session.drag;
  if (!drag || session.machine.state === 'focusing') return;
  const dx = point.x - drag.start.x;
  const dy = point.y - drag.start.y;
  if (!drag.moved && Math.hypot(dx, dy) < 4) return;
  if (!drag.moved) {
    drag.moved = true;
    clearOverlookHover(session);
    if (session.machine.state === 'say' || session.machine.state === 'lines' || session.machine.state === 'pair') overlookTransition(session, 'field');
    overlookNode('#academy-overlook-viewport').classList.add('is-dragging');
  }
  session.camera = clampOverlookCamera({ x: drag.camera.x - dx, y: drag.camera.y - dy }, overlookViewport(), session.map);
  session.marksDirty = true;
}

function onOverlookPointerUp(event) {
  const session = overlookSession;
  if (!session || !session.drag) return;
  const drag = session.drag;
  session.drag = null;
  overlookNode('#academy-overlook-viewport').classList.remove('is-dragging');
  if (drag.moved) return;
  onOverlookClick(session, overlookPointerPoint(event)).catch(reportOverlookScreenError);
}

function onOverlookPointerLeave() {
  if (overlookSession) overlookSession.pointer = null;
}

// A click on the map: a meeting pair → pick that focus (状態 14 → 6); a coma → nothing; a place's radius →
// the writing frame (状態 11, or 13 while the limit holds); an open writing frame closes on an outside click.
async function onOverlookClick(session, point) {
  const { state } = session.machine;
  if (state === 'writing' || state === 'writing-limited') {
    closeOverlookWritingFrame(session);
    return;
  }
  const viewport = overlookViewport();
  const frame = overlookCameraFrame(session, viewport);
  const comas = [...session.positions].map(([id, position]) => ({ id, ...overlookScreenPoint(position, frame, viewport) }));
  const comaId = overlookComaAt(point, comas);
  if (comaId) {
    const encounter = session.latest.encounters.find((entry) => entry.pickable && entry.participants.some((participant) => participant.character_id === comaId));
    if (encounter && (isOverlookFieldState(state) || state === 'focusing')) await pickOverlookEncounter(session, encounter);
    return;
  }
  if (!isOverlookFieldState(state)) return;
  const mapPoint = { x: (point.x - viewport.width / 2) / frame.scale + frame.centre.x, y: (point.y - viewport.height / 2) / frame.scale + frame.centre.y };
  const place = overlookPlaceAt(session.places, session.map, mapPoint);
  if (place) openOverlookWritingFrame(session, place);
}

async function pickOverlookEncounter(session, encounter) {
  try {
    const payload = await postJson('/api/overlook/focus', { encounter_id: encounter.encounter_id });
    if (overlookSession !== session) return;
    const answer = validateOverlookFocusResponse(payload, { places: session.places });
    const redirect = session.machine.state === 'focusing';
    applyOverlookField(session, answer.field);
    if (redirect) beginOverlookFocus(session, answer.field.focus);
  } catch (error) {
    // The server's 409 is the screen's truth (the encounter is gone, or a talk is already on screen): read the
    // field again and let it drive the state.
    if (error.statusCode !== 409) throw error;
    const payload = await getJson('/api/overlook/field');
    if (overlookSession !== session) return;
    applyOverlookField(session, validateOverlookFieldResponse(payload, { places: session.places }).field);
  }
}

// ---------- writing (状態 11〜13) ----------

function openOverlookWritingFrame(session, place) {
  clearOverlookHover(session);
  overlookTransition(session, session.latest.writing.available ? 'writing' : 'writing-limited');
  session.writing = { place, rect: null, ringNode: null, limitedUntil: session.latest.writing.next_available_at };
  const input = overlookNode('#academy-overlook-writing-input');
  input.value = '';
  overlookNode('#academy-overlook-writing-place').textContent = place.name;
  overlookNode('#academy-overlook-writing').hidden = false;
  renderOverlookWritingFrame(session);
  if (session.machine.state === 'writing') input.focus();
}

function closeOverlookWritingFrame(session) {
  session.writing = null;
  overlookNode('#academy-overlook-writing').hidden = true;
  overlookNode('#academy-overlook-hover').replaceChildren();
  session.marksDirty = true;
  overlookTransition(session, 'field');
}

function renderOverlookWritingFrame(session, placement = null) {
  const writing = session.writing;
  if (!writing) return;
  const limited = session.machine.state === 'writing-limited';
  const input = overlookNode('#academy-overlook-writing-input');
  const submit = overlookNode('#academy-overlook-writing-submit');
  const status = overlookNode('#academy-overlook-writing-status');
  input.disabled = limited;
  submit.disabled = limited || !isValidOverlookWritingText(input.value);
  status.hidden = !limited;
  status.textContent = limited ? `次の書き込みは ${writing.limitedUntil ?? session.latest.writing.next_available_at} から` : '';
  if (!placement) return;
  const point = overlookScreenPoint(writing.place, placement.frame, placement.viewport);
  if (!writing.ringNode) {
    writing.ringNode = document.createElement('div');
    writing.ringNode.className = 'academy-overlook-place-ring';
    overlookNode('#academy-overlook-hover').append(writing.ringNode);
  }
  writing.ringNode.style.transform = `translate(${point.x}px, ${point.y}px)`;
  const frameNode = overlookNode('#academy-overlook-writing');
  const ringRadius = writing.ringNode.offsetWidth / 2;
  const rect = overlookWritingFrameRect(point, { height: frameNode.offsetHeight, ringRadius });
  if (!writing.rect || writing.rect.left !== rect.left || writing.rect.top !== rect.top) session.marksDirty = true;
  writing.rect = rect;
  placeOverlookNode(frameNode, rect);
}

async function submitOverlookWriting(session) {
  if (session.machine.state !== 'writing' || !session.writing) return;
  const input = overlookNode('#academy-overlook-writing-input');
  const text = input.value.trim();
  if (!isValidOverlookWritingText(text)) return;
  overlookNode('#academy-overlook-writing-submit').disabled = true;
  try {
    const payload = await postJson('/api/overlook/writings', { place_id: session.writing.place.place_id, text });
    if (overlookSession !== session) return;
    const answer = validateOverlookWritingResponse(payload, { places: session.places });
    closeOverlookWritingFrame(session);
    applyOverlookField(session, answer.field);
  } catch (error) {
    if (error.statusCode !== 409 || error.errorCode !== 'OVERLOOK_WRITING_LIMITED') throw error;
    session.writing.limitedUntil = validateOverlookWritingLimited(error.payload);
    overlookTransition(session, 'writing-limited');
    renderOverlookWritingFrame(session);
  }
}

// ---------- the roster: the 「顔ぶれ」 button, the list, sending a child off (状態 17〜19) ----------

// The list's 12 rows follow field.roster (the order the children joined; a newcomer takes its leaver's row). A row's
// 「送り出す」 is dead while the child is a newcomer before the gate, and while its own request is in flight.
function renderOverlookRoster(session) {
  const { roster } = session.latest;
  const key = roster.map((row) => `${row.character_id}:${row.swappable}:${session.roster.sending.has(row.character_id)}`).join('|');
  if (key === session.roster.key) return;
  session.roster.key = key;
  const list = overlookNode('#academy-overlook-roster');
  if (list.children.length === 0) {
    for (let index = 0; index < roster.length; index += 1) {
      const item = document.createElement('li');
      item.className = 'academy-overlook-roster-row';
      const face = document.createElement('img');
      face.className = 'academy-overlook-roster-face';
      face.alt = '';
      face.draggable = false;
      const name = document.createElement('span');
      name.className = 'academy-overlook-roster-name';
      const send = document.createElement('button');
      send.type = 'button';
      send.className = 'conversation-day-action-button conversation-day-action-secondary academy-overlook-roster-send';
      send.textContent = '送り出す';
      item.append(face, name, send);
      list.append(item);
    }
  }
  if (list.children.length !== roster.length) throw new Error(`overlook roster list holds ${list.children.length} rows for ${roster.length}`);
  roster.forEach((row, index) => {
    const item = list.children[index];
    if (item.dataset.characterId !== row.character_id) {
      item.dataset.characterId = row.character_id;
      setActorImageSource(item.querySelector('.academy-overlook-roster-face'), overlookFaceUrl(row.character_id));
      item.querySelector('.academy-overlook-roster-name').textContent = row.character_name;
    }
    item.querySelector('.academy-overlook-roster-send').disabled = !row.swappable || session.roster.sending.has(row.character_id);
  });
}

function openOverlookRoster(session) {
  if (session.writing) closeOverlookWritingFrame(session);
  if (!overlookRosterMayOpen(session.machine.state)) return;
  const list = overlookNode('#academy-overlook-roster');
  session.roster.open = true;
  list.hidden = false;
  // Every opening starts from the first row.
  list.scrollTop = 0;
  overlookNode('#academy-overlook-roster-button').setAttribute('aria-expanded', 'true');
  session.marksDirty = true;
}

function closeOverlookRoster(session) {
  session.roster.open = false;
  overlookNode('#academy-overlook-roster').hidden = true;
  overlookNode('#academy-overlook-roster-button').setAttribute('aria-expanded', 'false');
  session.marksDirty = true;
}

// 「送り出す」: the server swaps the row at once and walks the two through the gate; the field it answers carries
// the newcomer's row and both walkers. No confirmation, no undo, no count (the board's three disclosed points).
async function sendOffOverlookChild(session, characterId) {
  const row = session.latest.roster.find((entry) => entry.character_id === characterId);
  if (!session.roster.open || !row?.swappable || session.roster.sending.has(characterId)) return;
  session.roster.sending.add(characterId);
  renderOverlookRoster(session);
  try {
    const payload = await postJson('/api/overlook/roster/swap', { character_id: characterId });
    if (overlookSession !== session) return;
    applyOverlookField(session, validateOverlookSwapResponse(payload, { places: session.places }).field);
  } catch (error) {
    // The server's 409 is the screen's truth (the day ended, a talk took the screen, the child cannot go now):
    // read the field again and let it drive the list and the state.
    if (error.statusCode !== 409) throw error;
    const payload = await getJson('/api/overlook/field');
    if (overlookSession !== session) return;
    applyOverlookField(session, validateOverlookFieldResponse(payload, { places: session.places }).field);
  } finally {
    session.roster.sending.delete(characterId);
    if (overlookSession === session) renderOverlookRoster(session);
  }
}

// ---------- focus: the camera move, the first line, the talk (状態 6〜9) ----------

function beginOverlookFocus(session, focus) {
  if (session.writing) {
    session.writing = null;
    overlookNode('#academy-overlook-writing').hidden = true;
  }
  clearOverlookHover(session);
  // A redirect during the move starts from where the camera is looking now.
  const viewport = overlookViewport();
  const from = overlookCameraFrame(session, viewport).centre;
  const [a, b] = focus.participants.map((participant) => session.positions.get(participant.character_id) ?? overlookChild(session, participant.character_id));
  const target = { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 };
  let startedResolve;
  const token = {
    encounterId: focus.encounter_id,
    participants: focus.participants,
    conversationId: null,
    target,
    started: false,
    startedPromise: new Promise((resolve) => { startedResolve = resolve; }),
    markStarted: () => {
      if (token.started) return;
      token.started = true;
      startedResolve();
    }
  };
  session.focus = token;
  overlookTransition(session, 'focusing');
  session.cameraAnim = { from, target, startedAt: performance.now(), reverse: false, onDone: () => finishOverlookFocusMove(session, token) };
  startOverlookFrameLoop(session);
  ensureOverlookPoll(session);
  if (focus.conversation_id) {
    token.conversationId = focus.conversation_id;
    startOverlookFirstLine(session, token);
  }
}

// The first line: read the talk (seed line, the two), then open the next stream. The first delta (or the line
// arriving whole) is "the stream has started" for the 1.1 s check.
function startOverlookFirstLine(session, token) {
  (async () => {
    const payload = await getJson(`/api/overlook/conversation?conversation_id=${encodeURIComponent(token.conversationId)}`);
    if (session.focus !== token) return;
    const { conversation } = validateOverlookConversationResponse(payload);
    session.talk = { conversationId: conversation.conversation_id, conversation, line: null, token };
    await streamOverlookLine(session, session.talk, { onStarted: token.markStarted });
  })().catch((error) => {
    // A focus the viewer redirected elsewhere drops its talk (the server answers its stream with an error).
    if (session.focus !== token || overlookSession !== session) return;
    reportOverlookScreenError(error);
  });
}

function finishOverlookFocusMove(session, token) {
  if (session.focus !== token) return;
  if (token.started) {
    openOverlookTalk(session, { crossfade: true });
    return;
  }
  overlookTransition(session, 'awaiting-first-line');
  (async () => {
    await showAcademyLoadingScreenUntilReady({
      readiness: token.startedPromise,
      nextScreen: null,
      refreshBeforeNextScreen: false,
      loadingCopy: overlookFocusLoadingCopy(token.participants)
    });
    if (overlookSession !== session || session.focus !== token) return;
    showScreen('academy-overlook');
    openOverlookTalk(session, { crossfade: false });
  })().catch(reportOverlookScreenError);
}

function openOverlookTalk(session, { crossfade }) {
  const talk = session.talk;
  if (!talk) throw new Error('overlook talk opened before the conversation was read');
  const talkNode = overlookNode('#academy-overlook-talk');
  overlookNode('#academy-overlook-stage-image').style.backgroundImage = `url('${OVERLOOK_STAGE_IMAGE_URL}')`;
  overlookTalkStage.renderWeekAndMoon();
  overlookTalkStage.setStatus('');
  const history = overlookTalkHistory(talk.conversation);
  overlookTalkStage.surface.setHistory(history);
  overlookTalkStage.renderStream(history);
  talkNode.hidden = false;
  talkNode.classList.toggle('is-crossfading', crossfade);
  overlookTalkStage.startAmbient();
  if (talk.line) {
    overlookTransition(session, 'talk-generating');
    attachOverlookLineReveal(talk);
  } else {
    overlookTransition(session, talk.conversation.closed ? 'talk-closed' : 'talk');
  }
  syncOverlookTalkControls(session);
  setTimeout(() => {
    if (overlookSession !== session || overlookNode('#academy-overlook-talk').hidden) return;
    talkNode.classList.remove('is-crossfading');
    overlookNode('#academy-overlook-field').hidden = true;
  }, crossfade ? OVERLOOK_TALK_CROSSFADE_MS : 0);
}

function syncOverlookTalkControls(session) {
  const { state } = session.machine;
  const next = overlookNode('#academy-overlook-next');
  next.textContent = state === 'talk-closed' ? 'フィールドへ戻る' : '次へ';
  overlookTalkStage.setControlsDisabled(state === 'talk-generating');
  overlookTalkStage.setResponding(state === 'talk-generating');
}

// The line being generated is shown as the next speaker's rows as their text arrives. The stream carries no
// expression before the line is complete, so these rows use the speaker's neutral face; the completed line is
// redrawn from the server's conversation with its own expression.
function overlookLineSegments(line, text) {
  return displayMessages([{
    role: 'assistant',
    character_id: line.speaker.character_id,
    character_name: line.speaker.character_name,
    content: text,
    expression: 'neutral',
    face_emotion_variant_id: 'neutral'
  }]).filter((segment) => (segment.content ?? '').trim());
}

function enqueueOverlookLine(line, text) {
  if (!line.reveal || !text.trim()) return;
  const fresh = overlookLineSegments(line, text).slice(line.segCount);
  line.segCount += fresh.length;
  line.reveal.enqueue(fresh);
}

function attachOverlookLineReveal(talk) {
  const line = talk.line;
  if (!line || line.reveal) return;
  line.reveal = overlookTalkStage.createTurnReveal(overlookTalkHistory(talk.conversation));
  enqueueOverlookLine(line, completedAssistantPrefix(line.text));
}

async function readOverlookNextSse(conversationId, { onDelta }) {
  const endpoint = '/api/overlook/conversation/next';
  const response = await fetch(endpoint, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ conversation_id: conversationId })
  });
  if (!response.ok) {
    const text = await response.text();
    throw createApiError({ url: endpoint, status: response.status, payload: parseJsonText(text), fallbackText: text });
  }
  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = '';
  let conversation = null;
  const handleBlock = (block) => {
    if (conversation) throw new Error('overlook next stream sent an event after its message');
    const { event, data } = parseOverlookSseBlock(block);
    if (event === 'assistant_delta') { notifyAcademyLoadingProgress(); onDelta(data.delta); }
    if (event === 'message') { notifyAcademyLoadingProgress(); conversation = data.conversation; }
    if (event === 'error') throw createApiError({ url: endpoint, status: 503, payload: data, fallbackText: data.error });
  };
  while (true) {
    const { value, done } = await reader.read();
    buffer += decoder.decode(value ?? new Uint8Array(), { stream: !done });
    const blocks = buffer.split('\n\n');
    buffer = blocks.pop() ?? '';
    for (const block of blocks) if (block.trim()) handleBlock(block);
    if (done) break;
  }
  if (buffer.trim()) handleBlock(buffer);
  if (!conversation) throw new Error('overlook next stream ended without its message');
  return conversation;
}

// Shows the next line (状態 7 → 7 when it was generated ahead, 7 → 8 → 7/9 when it streams).
async function streamOverlookLine(session, talk, { onStarted = null } = {}) {
  const shown = talk.conversation.messages.length;
  const line = { speaker: talk.conversation.participants[shown % 2], text: '', segCount: 0, reveal: null };
  talk.line = line;
  const conversation = await readOverlookNextSse(talk.conversationId, {
    onDelta: (delta) => {
      onStarted?.();
      line.text += delta;
      if (session.machine.state === 'talk') {
        overlookTransition(session, 'talk-generating');
        attachOverlookLineReveal(talk);
        syncOverlookTalkControls(session);
      }
      enqueueOverlookLine(line, completedAssistantPrefix(line.text));
    }
  });
  onStarted?.();
  if (overlookSession !== session || session.talk !== talk) return;
  if (conversation.conversation_id !== talk.conversationId || conversation.messages.length !== shown + 1) {
    throw new Error(`overlook next stream answered ${conversation.messages.length} lines for ${shown} shown`);
  }
  const fresh = conversation.messages[shown];
  if (fresh.character_id !== line.speaker.character_id) throw new Error('overlook next line came from the other speaker');
  if (line.reveal) {
    enqueueOverlookLine(line, fresh.content);
    await line.reveal.drain();
  }
  talk.conversation = conversation;
  const onTalkFace = ['talk', 'talk-generating'].includes(session.machine.state);
  if (!onTalkFace) {
    talk.line = null;
    return;
  }
  const history = overlookTalkHistory(conversation);
  if (line.reveal) {
    overlookTalkStage.surface.setHistory(history);
    overlookTalkStage.renderStream(history);
  } else {
    const reveal = overlookTalkStage.createTurnReveal(overlookTalkHistory({ ...conversation, messages: conversation.messages.slice(0, shown) }));
    reveal.enqueue(displayMessages(overlookTalkMessages({ messages: [fresh] })).filter((segment) => (segment.content ?? '').trim()));
    await reveal.drain();
    overlookTalkStage.surface.setHistory(history);
    overlookTalkStage.renderStream(history);
  }
  talk.line = null;
  overlookTransition(session, conversation.closed ? 'talk-closed' : 'talk');
  syncOverlookTalkControls(session);
}

function advanceOverlookTalk() {
  const session = overlookSession;
  if (!session) return;
  const { state } = session.machine;
  if (state === 'talk' && !session.talk.line) {
    streamOverlookLine(session, session.talk).catch(reportOverlookScreenError);
    return;
  }
  if (state === 'talk-closed') returnOverlookToField(session).catch(reportOverlookScreenError);
}

// 「フィールドへ戻る」: the server records the return (and may choose the next focus), then the camera runs the
// focus move backwards to the talk's place at scale 1.0 (状態 9 → 10).
async function returnOverlookToField(session) {
  const talk = session.talk;
  overlookTransition(session, 'returning');
  overlookTalkStage.setControlsDisabled(true);
  const payload = await postJson('/api/overlook/conversation/return', { conversation_id: talk.conversationId });
  if (overlookSession !== session) return;
  const { field } = validateOverlookReturnResponse(payload, { places: session.places });
  session.samples = [];
  session.latest = null;
  applyOverlookField(session, field);
  const target = talk.token.target;
  session.focus = null;
  session.talk = null;
  overlookTalkStage.stopAmbient();
  overlookNode('#academy-overlook-talk').hidden = true;
  overlookNode('#academy-overlook-field').hidden = false;
  session.cameraAnim = {
    from: target,
    target,
    startedAt: performance.now(),
    reverse: true,
    onDone: () => {
      overlookTransition(session, 'field');
      ensureOverlookPoll(session);
      if (session.latest.clock.ended) exitOverlookToHub(session).catch(reportOverlookScreenError);
      else if (session.latest.focus) beginOverlookFocus(session, session.latest.focus);
    }
  };
  startOverlookFrameLoop(session);
}

// ---------- leaving: the exit button or 15:00 (状態 16) ----------

// 星見の窓の地の絵（地図）は、カメラが動かす世界の中の一枚。露台へ戻る層が読む置き方（窓の座標）を、いまのカメラの枠
// （renderOverlookFrame と同じ移しと縮尺）から画面に書く。
function declareOverlookArtPlacement(session) {
  const viewport = overlookViewport();
  const frame = overlookCameraFrame(session, viewport);
  const origin = overlookNode('#academy-overlook-viewport').getBoundingClientRect();
  const screen = overlookNode('#academy-overlook-screen');
  screen.style.setProperty('--place-art-size', `${session.map.width * frame.scale}px ${session.map.height * frame.scale}px`);
  screen.style.setProperty('--place-art-position', `${origin.left + viewport.width / 2 - frame.centre.x * frame.scale}px ${origin.top + viewport.height / 2 - frame.centre.y * frame.scale}px`);
}

async function exitOverlookToHub(session) {
  if (routingContentReturnInFlight) {
    showProcessingToast();
    return;
  }
  const overlookArt = returnedPlaceArt(currentRuntimeState);
  overlookTransition(session, 'exiting');
  clearOverlookHover(session);
  routingContentReturnInFlight = true;
  try {
    let result = null;
    const exitRequest = postJson('/api/overlook/exit', {}).then((payload) => { result = validateOverlookExitResponse(payload); });
    // The exit and the hub start that follows it wait over the overlook's art.
    declareOverlookArtPlacement(session);
    raisePlaceVeil({ art: overlookArt, dim: true, until: 'routing-hub', ending: 'fade' });
    await awaitUnderPlaceVeil(exitRequest);
    if (overlookSession === session) overlookSession = null;
    await returnToRoutingHubFromContent(result.post_content_screen);
  } finally {
    routingContentReturnInFlight = false;
  }
}

const overlookViewportElement = document.querySelector('#academy-overlook-viewport');
overlookViewportElement.addEventListener('pointerdown', onOverlookPointerDown);
overlookViewportElement.addEventListener('pointermove', onOverlookPointerMove);
overlookViewportElement.addEventListener('pointerup', onOverlookPointerUp);
overlookViewportElement.addEventListener('pointerleave', onOverlookPointerLeave);
document.querySelector('#academy-overlook-exit').addEventListener('click', () => {
  const session = overlookSession;
  if (!session || !isOverlookFieldState(session.machine.state)) return;
  exitOverlookToHub(session).catch(reportOverlookScreenError);
});
document.querySelector('#academy-overlook-roster-button').addEventListener('click', () => {
  const session = overlookSession;
  if (!session || !isOverlookFieldState(session.machine.state)) return;
  if (session.roster.open) closeOverlookRoster(session);
  else openOverlookRoster(session);
});
document.querySelector('#academy-overlook-roster').addEventListener('click', (event) => {
  const send = event.target.closest('.academy-overlook-roster-send');
  const session = overlookSession;
  if (!send || send.disabled || !session) return;
  sendOffOverlookChild(session, send.closest('.academy-overlook-roster-row').dataset.characterId).catch(reportOverlookScreenError);
});
document.querySelector('#academy-overlook-writing').addEventListener('submit', (event) => {
  event.preventDefault();
  if (overlookSession) submitOverlookWriting(overlookSession).catch(reportOverlookScreenError);
});
const overlookWritingInput = document.querySelector('#academy-overlook-writing-input');
overlookWritingInput.addEventListener('input', () => {
  if (overlookSession?.writing) renderOverlookWritingFrame(overlookSession);
});
overlookWritingInput.addEventListener('compositionstart', () => { playerInputIsComposing = true; });
overlookWritingInput.addEventListener('compositionend', () => { playerInputIsComposing = false; });
overlookWritingInput.addEventListener('keydown', (event) => {
  if (event.key === 'Enter' && playerInputIsComposing) event.preventDefault();
});
document.querySelector('#academy-overlook-next').addEventListener('click', advanceOverlookTalk);
document.querySelector('#academy-overlook-message-stream').addEventListener('click', () => {
  if (overlookSession?.machine.state === 'talk') advanceOverlookTalk();
});
document.addEventListener('keydown', (event) => {
  const session = overlookSession;
  if (!session || !screens['academy-overlook'].classList.contains('active')) return;
  const { state } = session.machine;
  if (event.key === 'Escape' && session.roster.open) {
    event.preventDefault();
    closeOverlookRoster(session);
    return;
  }
  if (event.key === 'Escape' && (state === 'writing' || state === 'writing-limited')) {
    event.preventDefault();
    closeOverlookWritingFrame(session);
    return;
  }
  if (event.key === 'Enter' && !event.isComposing && (state === 'talk' || state === 'talk-closed')) {
    event.preventDefault();
    advanceOverlookTalk();
  }
});

// Boot loads persisted state and the hub's ability sigils (hubTerrace.js) then applies the initial-screen
// override. The state is read after the sigils are in: the shop, gathering and training screens draw them while rendering it. Dev calibration (?calibrate=<screen>) chains AFTER (so the target screen has its runtime state), and
// runs whether or not the refresh above succeeded because the reportError catch resolves the chain. Its
// fail-fasts (invalid registry / unknown screen / missing target selector / undefined offset custom property)
// are intentionally NOT caught: a broken calibration registration must propagate and abort calibration setup,
// never be swallowed into a degraded dev mode that keeps running.
// Apply the persisted audio settings to the BGM controller once at boot (its own chain so it never gates the
// initial-screen override, and its failure is handled inside initAudioSettings by dropping to silence).
initAudioSettings();

// The night journey layer over the title / slot-load / settings / loading screens and the arrival at the hub. It
// takes the gate choices only once the boot below has run applyInitialScreenOverride.
const metaJourney = startMetaJourney({ refreshSettings: refreshSettingsScreen });

// 学院マップと昼の会話の見せ方の層（academyMapLayer.js・conversationLayer.js）の読み口。舞台の並びは renderAcademyMap がピンを
// 置くのと同じ academyMapRegionRenderableNodes の順で、ピンの釦の並びと1対1に対応する。そこにいる人はマップの hover と会話相手
// 選びが使う stageOccupantsFor そのもの。名・顔・絵は欠けたら名指しで throw する（別の値で埋めない）。顔は学院の人が
// selection_icon_url、クリーチャーが face_url（creatureCandidateFromSummary が必須にしている欄）。
const academyFieldReadingRequired = (value, label) => {
  if (typeof value !== 'string' || value === '') throw new Error('academy field reading: missing ' + label);
  return value;
};
const academyFieldReading = Object.freeze({
  region() {
    return activeMapRegion;
  },
  currentLocationId() {
    return currentField?.current_location?.id ?? null;
  },
  // 舞台そのもの（地図のピンに限らない）。会話の途中の移動の行先は山林・雪の中庭にもなり得る。
  location(id) {
    const location = fieldStageLocation(id);
    return {
      id: location.id,
      displayName: academyFieldReadingRequired(location.display_name, 'display_name of stage ' + id),
      backgroundUrl: academyFieldReadingRequired(location.background_url, 'background_url of stage ' + id)
    };
  },
  // いまの会話の地にする舞台（会話の種類の印ごと）。依頼・研究会・ホムンクルスは種類ごとに決まった場所の絵（正方形の stage.jpg）と、
  // 舞台の詳細の小窓と同じ場所の名。学院の会話と出来事はいま居る舞台そのもの（出来事はイベントの場所）。
  // いまの会話が卒業の会話か（会話を終えても相手は消えず、星の道へ続く）。
  isGraduationConversation() {
    return isRoutingGraduationEndingConversation();
  },
  conversationStage() {
    const kind = screens['conversation-day'].dataset.conversationKind;
    if (kind === 'errand') {
      return { id: 'errand', displayName: ERRAND_SCENE_LOCATION_NAME, backgroundUrl: ERRAND_SCENE_STAGE_IMAGE_URL };
    }
    if (kind === 'study-circle') {
      return { id: 'study-circle', displayName: conversationDayStudyCircleResolvedScene().venue, backgroundUrl: STUDY_CIRCLE_SCENE_STAGE_IMAGE_URL };
    }
    if (kind === 'atelier') {
      return { id: 'atelier', displayName: conversationDayAtelierResolvedScene().locationName, backgroundUrl: ATELIER_SCENE_STAGE_IMAGE_URL };
    }
    if (kind === 'field' || kind === 'event') {
      return this.location(academyFieldReadingRequired(this.currentLocationId(), 'current stage of the ' + kind + ' conversation'));
    }
    throw new Error('academy field reading: no conversation stage for conversation kind ' + JSON.stringify(kind ?? null));
  },
  nodes() {
    const nodes = academyMapRegionRenderableNodes(activeMapRegion, currentField?.locations ?? []);
    return nodes.map((node, index) => {
      const kind = isAcademyMapShopNode(node) ? 'shop' : isSanrinMapGatheringNode(node) ? 'gathering' : 'stage';
      return {
        id: node.id,
        kind,
        displayName: academyFieldReadingRequired(node.display_name, 'display_name of map node ' + node.id),
        point: academyMapPointFor(node.id, index, nodes.length),
        situation: academyMapNodeDescription(node),
        backgroundUrl: academyFieldReadingRequired(node.background_url, 'background_url of map node ' + node.id),
        occupants: kind === 'stage'
          ? stageOccupantsFor(node).map((character) => ({
              characterId: character.character_id,
              displayName: academyFieldReadingRequired(character.display_name, 'display_name of ' + character.character_id),
              faceUrl: character.is_creature === true
                ? academyFieldReadingRequired(character.face_url, 'face_url of creature ' + character.character_id)
                : academyFieldReadingRequired(character.selection_icon_url, 'selection_icon_url of ' + character.character_id),
              isCreature: character.is_creature === true,
              isBuddy: character.is_buddy === true,
              isEnemy: character.is_enemy === true
            }))
          : []
      };
    });
  }
});
startAcademyMapLayer(academyFieldReading);
startConversationLayer(academyFieldReading);

Promise.all([
  refreshSaveSlots(),
  loadAbilitySigils().then(() => refresh({ noSaveYet: true })),
  loadConversationPopupSettings(),
  loadTableRoomSigils(),
  loadVenueSigils()
]).then(() => applyInitialScreenOverride()).catch(reportError).then(() => metaJourney.bootFinished()).then(() => applyFrameDecorationCalibrationOverride());
